export default [{"id":177,"question":"هل مَن مات في حوادث السيارات يدخل في حكم صاحب الهدم أو المطعون في ثبوت حكم الشَّهادة لهم التي وردت في الحديث؟","title":"هل يُعدّ شهيدًا من يموت بحادث سير؟","answer":"الجواب: نعم، مَن مات بسبب السيارات -انقلاب أو مُصادمة- فكله إن شاء الله في حكم الشُّهداء، في حكم صاحب الهدم.","link":"https://binbaz.org.sa/fatwas/3726/هل-يعد-شهيدا-من-يموت-بحادث-سير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0178.mp3","categories":["شروح الحديث","مسائل متفرقة في الجنائز"]},{"id":219,"question":"ما درجة هذا الحديث: إذا قامت الساعةُ وفي يد أحدكم فسيلة فليغرسها؟","title":"معنى \"إذا قامت الساعة وفي يد أحدكم فسيلة\"","answer":"الجواب: هذا صحيحٌ؛ رواه أحمد وغيره بإسنادٍ صحيحٍ. والمعنى: التَّشجيع على العمل، وإلا فمعلومٌ عند قيام الساعة ما يتمكَّن أن يُسوي شيئًا، لكن المقصود التشجيع على العمل، وأن الإنسان ينبغي أن يعمل، وفيه حثٌّ على الزراعة والغراس، وأنه ينبغي للمؤمن أن يكون ذا عملٍ، ليس ذا بطالةٍ وكسلٍ كما يفعل بعضُ الناس، لا، ينبغي للمؤمن أن يكون ذا عملٍ، ذا نشاطٍ، ذا همَّةٍ في الزراعة، في غرس الأشجار، في أنواع المكاسب: من نجارة، من حدادة، من غراسة، من كتابة، من غير ذلك، لا يبقى مُعطلًا، بل يعمل.\nوفي \"الصحيح\" عن النبي ﷺ أنه قال: على كل سُلامى منكم صدقة، قالوا: يا رسول الله، فإن لم يجد؟ ما عنده مال، قال: يعمل بيديه فينفع نفسه ويتصدَّق. وقال عليه الصلاة والسلام: احرص على ما ينفعك، واستعن بالله ولا تعجزنَّ الحديث رواه مسلم. وقال ﷺ في أول هذا الحديث: المؤمن القوي خيرٌ وأحبُّ إلى الله من المؤمن الضَّعيف، وفي كلٍّ خيرٌ، ومن قوة المؤمن وكمال دينه: العمل والجد والنَّشاط في طلب الرزق.\nومن ذلك يقول ﷺ لما سُئل: أي الكسب أطيب؟ قال: عمل الرجل بيده، وكل بيع مبرور.\nومن هذا ما رواه البخاري في \"الصحيح\" أنَّ النبي ﷺ قال: ما أكل أحد طعامًا أفضل من أن يأكل من عمل يده، وإنَّ داود عليه الصلاة والسلام كان يأكل من عمل يده.","link":"https://binbaz.org.sa/fatwas/4057/معنى-اذا-قامت-الساعة-وفي-يد-احدكم-فسيلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0226.mp3","categories":["شروح الحديث","الحكم على الأحاديث"]},{"id":228,"question":"كيف نجمع بين حديث الرسول ﷺ: لا تُطروني كما أطرت النَّصارى ابن مريم .. الحديث، وبين قوله ﷺ: لا يُؤمن أحدُكم حتى أكون أحبَّ إليه من نفسه وولده ووالديه والناس أجمعين؟","title":"كيف يُجمع بين محبتهﷺوعدم الغلو فيه؟","answer":"الجواب: لا منافاة ولا مخالفة بين الحديثين، فقد سمعتُم الكلام في هذا.\nحديث لا تُطروني يمنعنا من الغلو والزيادة، كأن نقول: إنه يعلم الغيب، هذا الإطراء: أنه يعلم الغيب، وأنه يُدعى من دون الله، ويُستغاث به بعد موته ﷺ، أو يقال: إنه يتصرف في الكون، أو يُدخل الجنة مَن يشاء، أو أنَّ الله خلق الخلق من أجله، كما يقول بعضُ الجهَّال وبعض الغالطين، فهذا من الغلو.\nأما في حياته ﷺ فلا بأس أن يُستعان به فيما يقدر عليه، مثل غيره من المخلوقين، فالحي الحاضر القادر يُستعان به فيما يقدر عليه، تقول له: أعني على كذا، على نفقة العيال، أقرضني كذا، أعني من بيت المال على كذا، يا أخي، ساعدني على إصلاح سيارتي، على عمارة بيتي، على مزرعتي، لا بأس، مثلما قال الله  في قصة موسى: فَاسْتَغَاثَهُ الَّذِي مِنْ شِيعَتِهِ عَلَى الَّذِي مِنْ عَدُوِّهِ [القصص:15].\nأما بعد الوفاة: فلا النبي، ولا غيره، لا يُطلب منه شيءٌ، ولا يُطلب منه مددٌ، ولا الغوث، ولا يُطلب من البدوي، ولا من الشيخ عبدالقادر الجيلاني، ولا من الحسين، ومن فلان، كما يفعل عبادُ القبور، وكما تفعل الرافضة مع أهل البيت، هذا منكرٌ عظيمٌ، وشركٌ وخيمٌ، وعبادةٌ لغير الله، وغلوٌّ زائدٌ، ولكن في حياته يطلب منه الشفاعة يوم القيامة عند البعث والنشور، يطلب منه المؤمنون الشفاعة في أهل الموقف، هذا حقٌّ، أما في البرزخ في حال الموت فلا يُدعى، لا هو ولا غيره عليه الصلاة والسلام، ولا يُستغاث به، ولا يُنذر له كما تفعله الجُهَّال والغُلاة، لا، هذه مصيبةٌ عظيمةٌ وقع فيها كثيرٌ من الناس، حتى وقع فيها مَن يُنسب إلى العلم، ويُدعى بالعالم في كثيرٍ من الأمصار، ولا حول ولا قوة إلا بالله -نسأل الله السَّلامة.\nوأما لا يؤمن أحدُكم حتى أكون أحبَّ إليه من ولده ووالده.. الحديث، فهذا معناه: أنه يُحبه محبةً صادقةً، أهم من أنفسنا، ومن أولادنا، ما معنى هذا؟ يعني: نُقدم طاعته على طاعة أهوائنا، نُقدم طاعته ونُصلي في الجماعة وإن خالف هوانا، وإن كنا نُحبّ أن نستريح مع الأهل، أو في الأكل، أو في كذا وكذا، لا، نُقدم طاعة الرسول ﷺ؛ لأنَّ الواجب أن نُحبَّه فوق محبَّة أنفسنا، فنُطيعه فيما أمرنا به، وننتهي عمَّا نهى عنه وإن خالف أهواءنا وشهواتنا، وننفذ ما أوجب علينا، وما أمرنا به عليه الصلاة والسلام، سواء كان ذلك عن نشاطٍ منا، أو عن مشقَّةٍ، نصبر ونقوم بالواجب عن محبَّةٍ، وعن رغبةٍ، وعن امتثال.\nالإنسان في بعض المرات يضعف: عند البرد، عند النوم، عند وجود بعض الناس عنده، لكن محبَّة الرسول ﷺ، بل ومحبَّة الله فوق ذلك؛ تُوجب عليه أن يُؤثر حقَّ الله على حقِّ الناس وعلى حقِّ النفس، وأن يُبادر بما أوجب الله، وإن أحبَّ الجلوس أو النوم أو شبه ذلك، يُقدّم طاعة الرب الواجبة على هوى نفسه: في النوم، أو في الأكل، أو في الجلوس مع فلان أو فلان، أو مع الزوجة، أو مع غيرها.","link":"https://binbaz.org.sa/fatwas/4079/كيف-يجمع-بين-محبتهﷺوعدم-الغلو-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0235.mp3","categories":["شروح الحديث"]},{"id":231,"question":"فضيلة الشيخ، هنا سائلٌ يقول: إنَّ الرسول ﷺ يقول: إنَّ الله لا ينظر إلى صوركم، ولا إلى أموالكم، ولكن ينظر إلى قلوبكم وأعمالكم، فيقول أنه يدَّعي بعضُ الناس استنادًا لهذا الحديث أنَّ المهم فقط هو القلب، فتراه يقول أنَّ قلبه عامرٌ بالإيمان، ولكنه لا يُؤدي الشَّعائر المطلوبة منه وخلاف ذلك، فما تعليقكم على ذلك؟","title":"معنى حديث \"إن الله لا ينظر إلى صوركم..\"","answer":"الجواب: هذا يسأل عمَّا جاء في الحديث الصحيح: أنَّ النبي ﷺ قال: إنَّ الله لا ينظر إلى صوركم، ولا إلى أموالكم، ولكن ينظر إلى قلوبكم وأعمالكم، يقول أنَّ بعض الناس قد يتعلق بهذا ويقول: إن المُعول على القلب، وأن العمل لا معولَ عليه، ولهذا إذا نُصح وقيل له: اتَّقِ الله، قال: \"الإيمان في القلب\"، هكذا يقول بعضُ الناس، فإذا نصحته عمَّا يحصل منه من المعاصي، من التَّساهل بالصلاة، أو البخل بالزكاة، أو غير هذا، أو حلق لحيته، أو إسبال ملابسه، أو تعاطيه المُسكر، أو ما أشبه ذلك؛ قال: \"الإيمان في القلب\".\nوهذا الاحتجاج بهذا الكلام حُجَّة شيطانية باطلة، فإنَّ القلب هو الأساس، فمتى صلح القلبُ صلحت الأعمالُ، كما سمعت في الحديث الآخر، فلو كان الإيمانُ في القلب صحيحًا موجودًا لمنعك من هذه المعاصي، ولكنه ضعيفٌ أو معدومٌ.\nثم في الحديث نفسه قال: ولكن ينظر إلى قلوبكم وأعمالكم، فجعل العملَ مع القلب، هكذا رواه مسلم في \"الصحيح\"، فلم يقل العمل قال: ينظر إلى قلوبكم وأعمالكم.\nوفي حديث النعمان المتقدم قال: في القلب مُضْغَةٌ، إذا صلحت صلح الجسدُ كلُّه بالعمل الصالح، فإذا صلح القلبُ صلح البدن، فانقادت الجوارح لطاعة الله، وانكفَّت عن محارم الله، هذا هو الصلاح، فإذا كان الجسدُ لم يصلح فهذه علامة أنَّ القلب لم يصلح، وأنَّ الإيمان فيه معدومٌ أو مريضٌ مدخولٌ ضعيفٌ.\nوالإيمان يزيد وينقص، وهو قولٌ وعملٌ عند أهل السنة والجماعة، والله يقول: وَقُلِ اعْمَلُوا [التوبة:105]، ويقول: ادْخُلُوا الْجَنَّةَ بِمَا كُنْتُمْ تَعْمَلُونَ [النحل:32]، ما قال بإيمانكم فقط، قال: بِمَا كُنْتُمْ تَعْمَلُونَ، فالإيمان قولٌ وعملٌ، والصلاة عملٌ، والزكاة عملٌ وهكذا، فالواجبات التي فرضها الله من الإيمان، وترك المحارم من الإيمان.\nفالواجب على العبد أن يتَّقي الله، وأن يحذر التَّعلقات التي تضرُّه وتُغضب الله عليه، فإيمانك إذا صحَّ في قلبك حملك على أداء الفرائض، وعلى ترك المحارم، ومتى وُجد منك الخللُ في بعض الواجبات، أو ركوب بعض المحارم، فذلك دليلٌ على ضعف إيمانك، وكلما زاد الضَّعفُ صار الخطرُ أكبر، وربما توالى حتى يزول الإيمانُ بالكلية.\nوهكذا المعاصي: كلما زادت ضعف القلبُ، وضعف الإيمان، وربما جرَّه ذلك إلى الانسلاخ من الإيمان بناقضٍ من نواقض الإسلام، فإنَّ المعاصي بريد الكفر، كالمرض بريد الموت.\nفالواجب على المسلم أن يتَّقي الله، وأن يحذر الشيطان والهوى، ويتباعد عن محارم الله ويحذرها، وأن يجتهد في أداء ما أوجب الله، فهذا هو الدليل على صلاح القلب.","link":"https://binbaz.org.sa/fatwas/4089/معنى-حديث-ان-الله-لا-ينظر-الى-صوركم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0241.mp3","categories":["شروح الحديث"]},{"id":257,"question":"ما حكم مَن أوتر بعد صلاة العشاء بركعةٍ واحدةٍ؟ ففي الحديث الذي ورد في البخاري: أنَّ معاوية  أوتر بعد العشاء بركعةٍ واحدةٍ، فقيل لابن عباس ذلك، فقال: \"دعوه فإنه فقيه\"؟","title":"حكم الوتر بعد صلاة العشاء بركعة واحدة","answer":"الجواب: صحيح، نعم، الوتر بواحدةٍ كافٍ، ومن هذا حديث أبي أيوب الأنصاري، وهو ثابتٌ عن النبي ﷺ قال: مَن أحبَّ أن يُوتر بخمسٍ فليفعل، ومَن أحبَّ أن يُوتر بثلاثٍ فليفعل، ومَن أحبَّ أن يُوتر بواحدةٍ فليفعل، فالوتر أقلّه ركعة واحدة من آخر الليل، أو من وسط الليل، أو من أول الليل، كافٍ، بعد العشاء، وكلما زاد فهو أفضل، إن أوتر بثلاثٍ فهو أفضل، بخمسٍ فهو أفضل، بسبعٍ فهو أفضل، بتسعٍ فهو أفضل، بإحدى عشرة، بثلاث عشرة، إلى هنا انتهى وتره ﷺ: ثلاث عشرة، ومَن زاد فلا بأس؛ لأنَّ هذا ليس بحدٍّ محدود، فلو أوتر بمئة ركعة وواحدة فلا بأس، يقول النبيُّ لما سُئل عن صلاة الليل: مثنى، مثنى، فإذا خشي أحدُكم الصبحَ صلَّى ركعةً واحدةً تُوتر له ما قد صلَّى خرجه البخاري ومسلم في \"الصحيحين\".\nفدلَّ ذلك على أنَّ صلاة الليل غير محدودةٍ، لا في رمضان، ولا في غيره، فمَن صلَّى إحدى عشرة كما صلَّى النبيُّ ﷺ أو ثلاث عشرة فهو أفضل، ومَن زاد لأنه أحبَّ أن يستفيد من الصلاة؛ لأنَّ عنده نشاطًا، استمر، صلَّى عشرين في رمضان، أو في غيره، أو صلَّى أكثر؛ فلا بأس بذلك.\nوقد جاء عن الصحابة أنهم صلوا عشرين، وصلوا إحدى عشرة بعده ﷺ، وصلَّى بعضُهم أكثر من ذلك، والأمر في هذا واسعٌ، وليس فيه حدٌّ محدود، إلا أن الأفضل أن تكون صلاته مثل صلاة النبي ﷺ إحدى عشرة أو ثلاث عشرة، مع العناية والركود والقراءة والتَّدبر والتَّعقل والركعات، حتى يُصلي صلاة كاملة، فيها من الخشوع والطّمأنينة ما ينفعه الله بها.","link":"https://binbaz.org.sa/fatwas/4249/حكم-الوتر-بعد-صلاة-العشاء-بركعة-واحدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0300.mp3","categories":["الوتر وقيام الليل","شروح الحديث"]},{"id":259,"question":"ما معنى حديث: مَن ستر مسلمًا ستره الله في الدنيا والآخرة؟","title":"معنى حديث \"من ستر مسلماً ستره الله..\"","answer":"الجواب: هذا عامٌّ، \"يستر\" عامٌّ، يعمّ الستر الحسي والستر المعنوي، والستر المعنوي أهم وأكبر، فالستر الحسي أن تجده عاريًا فتكسوه -تجد أخاك عاريًا فتكسوه- كسوةً من عندك، أو نقودًا يشتري بها كسوةً، فهذا يدخل في الحديث، لكن أعظم من ذلك ستر عورته الدينية التي هي معصية، فتستره ولا تفضحه، ولا تخزه، هذا أعظم من ذلك.\nفإذا سترت أخاك، وجدتَه على معصيةٍ فسترت عليه، ونصحته، وحذَّرته من مغبَّتها، ولكن لم تُحدّث بها الناس، فأنت بهذا فزتَ بهذا الجزاء العظيم، والله يقول سبحانه: إِنَّ الَّذِينَ يُحِبُّونَ أَنْ تَشِيعَ الْفَاحِشَةُ فِي الَّذِينَ آمَنُوا لَهُمْ عَذَابٌ أَلِيمٌ فِي الدُّنْيَا وَالْآخِرَةِ [النور:19].\nفالستر على أخيك إن وجدتَه في بيت تهمةٍ، وجدته يستتر بالدخان، يستتر بشرب المسكر، وجدتَه على معصيةٍ أخرى مُستترًا بها، فسترتها عليه، ولم تذعه عند الناس تقول: وجدتُ فلانًا كذا..... هذا لك فيه أجرٌ عظيمٌ: ستره الله في الدنيا والآخرة، لكن لا يمنع هذا من النَّصيحة، فتستره وتنصحه وتُوجهه إلى الخير، وتحذّره من مغبَّة هذا الشيء.","link":"https://binbaz.org.sa/fatwas/4253/معنى-حديث-من-ستر-مسلما-ستره-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0304.mp3","categories":["شروح الحديث"]},{"id":323,"question":"ما المقصود بقول الرسول ﷺ في الحديث: مائلات مُميلات؟","title":"معنى \"مائلات مميلات\" في الحديث","answer":"الجواب: الشيخ: يقول النبيُّ ﷺ: صنفان من أهل النار لم أرهما: رجال بأيديهم سياطٌ كأذناب البقر يضربون بها الناس، ونساء كاسيات عاريات، مائلات مُميلات، رؤوسهن كأسنمة البُخت المائلة، لا يدخلن الجنةَ، ولا يجدن ريحها الحديث، رواه مسلم في \"الصحيح\".\nمعنى كاسيات عاريات عند أهل العلم يعني: كاسية كسوة ما تستر، رقيقة، أو قصيرة، فهن كاسيات في الاسم، عاريات في الحقيقة.\nوقال بعضُ أهل العلم: معنى كاسيات يعني: من نِعَم الله، عاريات من شكرها.\nولا شكَّ أنَّ لبس القصير والرقيق من المعصية، فالواجب على المرأة التستر والحجاب عن الرجال، وعدم إظهار شيء من زينتها؛ لقوله سبحانه: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53]، وقوله سبحانه: يَا أَيُّهَا النَّبِيُّ قُلْ لِأَزْوَاجِكَ وَبَنَاتِكَ وَنِسَاءِ الْمُؤْمِنِينَ يُدْنِينَ عَلَيْهِنَّ مِنْ جَلَابِيبِهِنَّ الآية [الأحزاب:59]. والجلباب: هو الثواب الواسع الذي تُلقيه المرأةُ عليها فوق ملابسها، يُسمّيه بعضُهم الآن: الشّرشف، الثوب الواسع تلحفه فوق ملابسها، وتُغطي به رأسَها ووجهها ويديها عند الحاجة إلى ذلك.\nويقول جلَّ وعلا: وَقُلْ لِلْمُؤْمِنَاتِ يَغْضُضْنَ مِنْ أَبْصَارِهِنَّ وَيَحْفَظْنَ فُرُوجَهُنَّ إلى أن قال: وَلَا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ الآية [النور:31]، فلا تُبدي زينتها -كوجهها ونحوه- إلا لأبيها، أو أخيها، أو بعلها ونحو ذلك، والله المستعان.\nومعنى مائلات مميلات يعني: مائلات عن العفَّة وعن الطاعة إلى المعصية والزنا والفواحش، مُميلات لغيرهن يعني: يُملن غيرهن إلى الفساد والمعصية.\nأما قول بعضهم: مائلات في المشية، فهذا ليس بشيءٍ، الصواب: معناه مائلات عن العفَّة وعن الاستقامة إلى الفساد والمعصية، مُميلات لغيرهن من النساء، يتأسّين بهن حتى يُملنهن عن الرشاد والعفَّة إلى المعاصي والفسوق والفجور -نسأل الله السَّلامة.","link":"https://binbaz.org.sa/fatwas/4410/معنى-ماىلات-مميلات-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0376.mp3","categories":["شروح الحديث"]},{"id":443,"question":"حديث الرسول ﷺ: أيما إيهاب دبغ فقد طهر وحديث جابر في تحريم الميتة، كيف نجمع بينهما؟","title":"معنى حديث: \"أيما إيهاب دبغ فقد طهر\"","answer":"الجواب: هذا في تحريم الميتة، وهذا في تطهير الجلد بالدباغ، ما في تناقض.\n(دروس شرح بلوغ المرام، كتاب البيوع)","link":"https://binbaz.org.sa/fatwas/5930/معنى-حديث-ايما-ايهاب-دبغ-فقد-طهر","audio":"https://files.zadapps.info/binbaz.org.sa/dabj.mp3","categories":["شروح الحديث"]},{"id":451,"question":"هناك من استدل على جواز بيع العِينَة بحديث أبي سعيد وأبي هريرة قال ﷺ: \"بع الجمع بالدراهم ثم اشتر بالدراهم جنيبًا\"؟","title":"معنى حديث \"بع الجمع بالدراهم ثم اشتر..\"","answer":"الجواب: لا، ما هو بعِينة، هذا يبيعها ويأخذ الفلوس ثم يشتري. تبيع التمر الرديء بالدراهم ثم تأخذ الدراهم وتشتري التمر الطيب.\n(دروس شرح بلوغ المرام، كتاب البيوع)","link":"https://binbaz.org.sa/fatwas/6174/معنى-حديث-بع-الجمع-بالدراهم-ثم-اشتر","audio":"https://files.zadapps.info/binbaz.org.sa/3eana009.mp3","categories":["شروح الحديث","البيوع"]},{"id":534,"question":"سواء مات عنها أو طلقت تُسمّى \"أيم\"؟","title":"هل وصف \"الأيم\" للمطلقة ومن مات زوجها؟","answer":"الجواب: نعم تُسمّى \"أيم\".\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6365/هل-وصف-الايم-للمطلقة-ومن-مات-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/maram100 - 02 - .mp3","categories":["شروح الحديث"]},{"id":560,"question":"حديث: من أتى امرأة في دبرها فقد كفر، الكفر دون الكفر؟","title":"معنى \"من أتى امرأة في دبرها فقد كفر\"","answer":"الجواب: إذا صح فإنه كُفْر دون كُفْر.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6391/معنى-من-اتى-امراة-في-دبرها-فقد-كفر","audio":"https://files.zadapps.info/binbaz.org.sa/maram126 - 02 - .mp3","categories":["شروح الحديث"]},{"id":607,"question":"ما المقصود بـ\"الفُسْحة في الدين\"؟","title":"ما معنى \"الفُسْحة في الدين\"؟","answer":"الجواب: يعني رجاء التوبة، وقد يعفو الله عليه إذا مات عليها ولم يتب، لكن الشرك ما فيه توبة ولا عفو، والقتل خطره عظيم قد يعذب في النار ولا يتوب الله عليه ولا يعفو عنه، كما توعّده الله بالنار إذا قتل بغير حق توعّده الله بالنار والخلود فيه، قد لا يُعفى عنه، قد يُعذب ولا يخرج من النار إلا بعد مدة، وإنْ كان لا يُخَلَّد فيها الموحد، لكن القتل شأنه خطير قد لا يُعفى عنه، نسأل الله العافية.\n(دروس شرح بلوغ المرام، كتاب الجنايات)","link":"https://binbaz.org.sa/fatwas/6446/ما-معنى-الفسحة-في-الدين","audio":"https://files.zadapps.info/binbaz.org.sa/maram174 - 03 - .mp3","categories":["شروح الحديث"]},{"id":659,"question":"س: قيام الليل هل هو واجب على الرسول ﷺ؟","title":"هل كان قيام الليل واجبًا على النبي ﷺ؟","answer":"الجواب: به قال بعض أهل العلم، وفيه خلاف بين أهل العلم؛ لأن الله قال: فَتَهَجَّدۡ أمْر، قالوا: فهذا يدل على الوجوب، وبعضهم قال: لا على السنية؛ لأن الرسول ﷺ لما سئل قال له رجل: يا رسول الله، هل عليّ غير الصلوات الخمس؟ قال: لا، إلا أن تطوع، والرسول ﷺ داخل في الأوامر.\n(دروس شرح بلوغ المرام، كتاب الحج والعمرة)","link":"https://binbaz.org.sa/fatwas/6690/هل-كان-قيام-الليل-واجبا-على-النبي-ﷺ","audio":"https://files.zadapps.info/binbaz.org.sa/maram228 - 01 -  Start.mp3","categories":["الوتر وقيام الليل","شروح الحديث"]},{"id":679,"question":"كيف الجمع بين قوله ﷺ: إن لو تفتح عمل الشيطان، وبين قوله ﷺ: لو استقبلت من أمري ما استدبرت ما سقت الهدي؟","title":"معنى \"لو\" بحديث: \"لو استقبلت من أمري..\"","answer":"الجواب: هذا في تَمَنِّي الخير، يقول: لو صليت مع فلان، لو استقبلت من أمري ما استدبرت كان ساعدت فلانًا في كذا؛ فما يخالف، فهذا يتمنى الخير: لو علم كذا لفعل كذا؛ فما في بأس.\nأما المنكر: لو أني رُحت للطبيب سَلِمْت. لو أني سافرت سَلِمْت. لو أني ما سافرت سَلِمْت. أو ما أشبه ذلك.\n(دروس شرح بلوغ المرام، كتاب الجامع)","link":"https://binbaz.org.sa/fatwas/6719/معنى-لو-بحديث-لو-استقبلت-من-امري","audio":"https://files.zadapps.info/binbaz.org.sa/maram259 - 01 -  Start.mp3","categories":["شروح الحديث","مسائل متفرقة في العقيدة"]},{"id":688,"question":"من فسّر صلاة الليل بصلاة العشاء في قوله: وصلوا بالليل؟","title":"ما معنى :\" وصلوا بالليل\" في الحديث؟","answer":"الجواب: لا، التهجد في الليل؛ لأنه قال: والناس نيام.\n(دروس شرح بلوغ المرام، كتاب الجامع)","link":"https://binbaz.org.sa/fatwas/6835/ما-معنى-وصلوا-بالليل-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/maram256 - 03 - .mp3","categories":["شروح الحديث","الوتر وقيام الليل"]},{"id":702,"question":"يقول السلام عليكم ورحمة الله وبركاته، يا شيخ حياك الله بيننا، وإنا والله نحبك في الله، ونسأل الله لنا ولك التوفيق وحسن الخاتمة، وذكر أسئلة، منها يقول: كيف نجمع بين حديث: إنَّ في القلب مضغةً إذا صلحت صلح الجسد كله، وبين ظهور القلب الصّناعي في هذه الأيام؟","title":"هل القلب الصّناعي يتأثر بحال من نُقِل إليه؟","answer":"الجواب: أحبَّك الله الذي أحببتنا له، وأسأل الله أن يجعلنا جميعًا من المتحابين في جلاله، وأن يتوفَّنا مسلمين.\nأما ظهور القلب الصناعي: فالمواد التي تمد هذا القلب، والعروق التي تمد هذا القلب، هو آلة، وإنما إمداده من العروق التي تمده حتى يعمر بالإيمان أو بالكفر، فإذا ثبت القلب الصناعي أنه قلب كافرٍ أو عاصٍ إلى رجلٍ طيبٍ، فإنَّ من باب هذا القلب بما يلين الله عليه من الاستقامة والطاعة، وذكر الله، والمحبة لله، والخوف من الله، يجعل هذا القلب يستقيم ويعمر بطاعة الله، بسبب ما يمدّه من العروق التي يجري فيها هذا الدَّم، ويجري فيها ما يفتح الله على العبد، فيتكلم بلسانه، ويعمل بجوارحه بطاعة الله، فيكون إمداد هذا القلب من طريق هذه العروق التي تمدّه بالدم الذي يصل إليه، ويكون ذلك من أسباب عمارته في تقوى الله ؛ لأنَّ الله سبحانه هو الذي خلق الأول وخلق الثاني -خلق القلب الأول، وخلق القلب الثاني- فإذا نصب في هذا البدن واستقرَّ في هذا البدن وصلح؛ أُمِد بالمواد التي أمِد بها القلب الأول، وصار في حاله قلبًا سليمًا طيبًا، كما لو هدى الله صاحبه الذي نُزع منه، الكافر يكون كافرًا خبيثًا، فإذا هداه الله صلح قلبه، والعاصي إذا هداه الله صلح قلبه، فهكذا إن نُقل قلبه وهو خبيثٌ أو فاسقٌ؛ يصلح قلبه إذا استقرَّ وثبت في المحل الطيب، جاءته من باب هداية الله للتوفيق والهداية، من طريق الوسائط التي جعلها الله مُرسلةً إلى هذه المواد الصَّالحة، وما يجعل الله فيه من المحبَّة لله، والخوف من الله، والرغبة فيما عنده، كما جعل في الأول، هو على كل شيءٍ قدير .","link":"https://binbaz.org.sa/fatwas/20536/هل-القلب-الصناعي-يتاثر-بحال-من-نقل-اليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0503فتاوى المحاضرات للشيخ عبدالعزيز بن باز رحمه الله.mp3","categories":["شروح الحديث"]},{"id":714,"question":"جاء في حديثٍ: أن الله  ليُدخل بالسهم ثلاثةً، مَن هم هؤلاء الثلاثة؟ وهل يُثاب الإنسانُ وهو يأخذ أجرًا على ذلك؟","title":"معنى حديث: أن الله يُدخل بالسهم ثلاثةًً الجنة","answer":"الجواب: الثلاثة: صانعه يحتسبه، والرامي به، والمناول، الذي صنع السهم: صنع مثلًا الرمح أو السيف أو البندق أو المدفع أو نحو ذلك، صنعه ليحتسب، يعني: يريد بذلك وجهَ الله، حتى يُساعد المجاهدين، والذي يرمي به، والذي يُناوله أخاه، يُعطيه السيف، أو يُناوله إيَّاه، أو يُعطيه الرمح.\nهؤلاء هم الثلاثة، كلهم إذا احتسبوا هذا لله؛ فهذا من أسباب دخول الجنَّة.","link":"https://binbaz.org.sa/fatwas/20570/معنى-حديث-ان-الله-يدخل-بالسهم-ثلاثة-الجنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0525فتاوى المحاضرات للشيخ عبدالعزيز بن باز رحمه الله.mp3","categories":["شروح الحديث"]},{"id":719,"question":"جاء عن رسول الله ﷺ: أنَّ أعرابيًّا جاء إليه فقال: يا رسول الله، دُلَّني على عملٍ إذا عملتُه دخلتُ الجنة، قال: تعبد الله ولا تُشرك به شيئًا، وتُقيم الصلاة، وتُؤتي الزكاة المفروضة، وتصوم رمضان، قال: والذي نفسي بيده، لا أزيد على هذا، فلما ولَّى قال النبيُّ ﷺ: مَن سرَّه أن ينظر إلى رجلٍ من أهل الجنة فلينظر إلى هذا متفق عليه.و كيف نُوفِّق بين معنى هذا الحديث لمَن أتى بهذه الأركان وارتكب بعض المعاصي في الدنيا؟","title":"معنى ما جاء بالحديث من أعمال توجب الجنة","answer":"الجواب: هذا شيءٌ، وهذا شيءٌ، هذا أخبره النبيُّ ﷺ بالفرائض، فقال: لا أزيد على ما فُرض عليَّ، وفي اللفظ الآخر: وعلَّمه بشرائع الإسلام، فقال: لا أزيد ولا أنقص، ولم يذكر له المحارم، وإنما ذكر له الفرائض، وقال: لا يزيد عليها، لا يبتدع، لا يزيد شيئًا، معناه: أنه لو لم يتنفَّل فهو على خيرٍ، حتى ولو ما تنفَّل، لو ما صلَّى مع الصَّلوات نافلةً، ولا صلَّى في  الليل، ولا صلَّى الضُّحى، أجزأه ذلك، وهو من أهل الجنة إذا مات على الإسلام.\nلكن مَن تنفَّل وصلَّى في الليل وتهجَّد في الليل وصلَّى الرواتب وصلَّى الضُّحى زاد أجره، وصار من السَّابقين المقرَّبين، فوق الأبرار المقتصدين، ولا بدّ أيضًا من ترك المحارم؛ لأنه ما ذكر له المحارم هنا، إنما ذكر الفرائض، فترك المحارم لا بدّ منه.\nثم النصوص من الكتاب والسنة يُضمّ بعضُها إلى بعضٍ؛ لأن الرسول يذكر المقالة في موضعٍ للترغيب في شيءٍ والتَّحريم في شيءٍ، ثم يذكر مقالًا آخر في شيءٍ آخر، فالنصوص يُضمّ بعضُها إلى بعضٍ؛ لأنها كلها من عند الله، كما قال هنا ما قال، قال الله جلَّ وعلا في الآية الأخرى: وَلِلَّهِ عَلَى النَّاسِ حِجُّ الْبَيْتِ [آل عمران:97]، فلعله حين قال له ما ذكر من الزكاة والصلاة والصيام لم يُفرض الحجّ، فجاء الحجُّ بعد ذلك، فلا بدّ من الحجِّ، ولعله حين قال ذلك لم يكن الجهاد مفروضًا، فجاء فرضُ الجهاد بعد ذلك، وهكذا الأمر بالمعروف والنَّهي عن المنكر جاءت فيه نصوصٌ أخرى، فالنصوص التي جاءت بعد ذلك تُضمّ إلى هذه النصوص، ولا يرد بعضها ببعضٍ، ولا يُكَذّب بعضها ببعضٍ.\nفعلينا أن نتتبّع ما قال في جميع الأحاديث، كما نصَّ القرآن في جميع الآيات، والله يقول سبحانه: وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانْتَهُوا [الحشر:7]، وهكذا المحارم: فكما أنه ذكر الفرائض هنا ذكر في القرآن المحارم فقال: وَلَا تَقْرَبُوا الزِّنَا إِنَّهُ كَانَ فَاحِشَةً وَسَاءَ سَبِيلًا ۝ وَلَا تَقْتُلُوا النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ [الإسراء:32- 33]، وقال: وَأَوْفُوا الْكَيْلَ وَالْمِيزَانَ بِالْقِسْطِ [الأنعام:152]، لَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا [البقرة:286] إلى غير هذا من النصوص.\nفكما أنه يجب علينا أن نأخذ بما أوجب في هذا الحديث وأحاديث أخرى، كذلك نأخذ بما أوجب في آيات وأحاديث أخرى، ونأخذ بما حرَّم علينا في آيات....؛ لأننا مأمورون بهذا كله، مأمورون أن نقبل ما جاء به كتابُ ربنا وسنةُ نبينا، وألا نُكذب بعضه، ولا نرد بعضه، بل نقبله كله: وَاعْتَصِمُوا بِحَبْلِ اللَّهِ جَمِيعًا وَلَا تَفَرَّقُوا [آل عمران:103]، ويقول ﷺ: ما نهيتُكم عنه فاجتنبوه، وما أمرتكم به فأتوا منه ما استطعتم متفق عليه.\nفالقاعدة بإجماع أهل العلم: أن على المسلمين أن يتقبَّلوا ما جاء في الكتاب والسنة، وأن يأخذوا به جميعه، ويُضمّ بعضه إلى بعضٍ، وأن يُصدِّقوا بعضه ببعضٍ، وألا يكذبوا بعضه ببعض.","link":"https://binbaz.org.sa/fatwas/20563/معنى-ما-جاء-بالحديث-من-اعمال-توجب-الجنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0520فتاوى المحاضرات للشيخ عبدالعزيز بن باز رحمه الله.mp3","categories":["شروح الحديث"]},{"id":799,"question":"ما المقصود بجماعة المسلمين التي جاءت في الأحاديث، وأنَّ مَن تركها شذَّ في النار، وأنه يلزم بيعتها؟ ثم ما أنواع البيعة الصَّحيحة من الكتاب والسُّنة؟","title":"ما معنى \"جماعة المسلمين\" في الحديث؟","answer":"الجواب: جماعة المسلمين هم الملتزمون بأمر الله، العاملون بكتاب الله وسنة رسوله عليه الصلاة والسلام، هؤلاء هم جماعة المسلمين في أي مكانٍ، كما في حديث حذيفة قال: يا رسول الله، كنا في جاهليةٍ وشرٍّ، فجاءنا الله بهذا الخير، فهل بعد هذا الخير من شرٍّ؟ قال: نعم، قلتُ: يا رسول الله، وهل بعد ذلك الشر من خيرٍ؟ قال: نعم، وفيه دَخَنٌ، قلت: وما دخنه؟ قال: قومٌ يهدون بغير هدي، ويستنون بغير سنتي، تعرف منهم وتُنْكِر، قلت: وهل بعد ذلك الخير من شرٍّ؟ قال: نعم، دُعاة على أبواب جهنم، مَن أجابهم إليها قذفوه فيها، قلت: يا رسول الله، صفهم لنا، قال: هم من جلدتنا، ويتكلَّمون بألسنتنا، قلت: يا رسول الله، فما تأمرني إن أدركني ذلك؟ قال: تلزم جماعة المسلمين وإمامهم، قلت: فإن لم يكن لهم جماعة ولا إمام؟ قال: فاعتزل تلك الفرق كلها، ولو أن تعضَّ على أصل شجرةٍ حتى يُدركك الموتُ وأنت على ذلك.\nفجماعة المسلمين هم الملتزمون بالإسلام، السَّائرون على نهج النبي عليه الصلاة والسلام، ولو كانوا قليلين، في أي طرفٍ من الأرض، في أي بقعةٍ، فالجماعة الملتزمة في أمريكا هم جماعة المسلمين، والملتزمة في لندن هم جماعة المسلمين، والملتزمة في فرنسا مثلًا أو هولندا أو كذا هم الجماعة، وهكذا الجماعة الملتزمة في أي مكانٍ: في الجزيرة العربية، في مصر، في الشام، في إندونيسيا.\nالمقصود مَن التزم بأمر الله، واستقام عليه، ودعا إليه؛ هؤلاء هم الجماعة الملتزمة، تلزمهم وتُكثِّر سوادهم أينما كنتَ، في الجهة التي أنت فيها.","link":"https://binbaz.org.sa/fatwas/20797/ما-معنى-جماعة-المسلمين-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0626ما المقصود بجماعة المسلمين التي جاءت في الأحاديث؟ ابن باز فتاوى المحاضرات.mp3","categories":["شروح الحديث","مسائل متفرقة في العقيدة"]},{"id":817,"question":"السلام عليكم ورحمة الله وبركاته، ما معنى الحديث في البخاري: يقول الله لملائكته: كيف وجدتُم عبادي؟ فيقولون: وجدناهم يعبدونك ويُسبِّحونك ويدعونك، فهل هذا يدل على جواز التَّسبيح الجماعي؟ أفيدونا جزاكم الله خيرًا.","title":"معنى حديث \"وجدناهم يعبدونك ويُسبِّحونك..\"","answer":"الجواب: هذا ثابتٌ في الحديث الصحيح: أن الملائكة يتَّبعون مجالسَ الذكر، فإذا وجدوا مجلسًا فيه طلب العلم، فيه التَّسبيح، فيه الذكر؛ جلسوا وحضروا، كما في الحديث الصحيح: إنَّ لله ملائكةً فَضْلًا يلتمسون مجالس الذكر، وفي اللفظ الآخر: إنَّ لله ملائكةً سيَّاحين، يبلغوني أمتي السلام عليه الصلاة والسلام، فهؤلاء الملائكة يصعدون إلى الله فيسألهم وهو أعلم بهم، يعلم أحوال عباده، لا تخفى عليه خافيةٌ جلَّ وعلا، ولكن يسألهم لإظهار فضل أهل الإيمان وأهل الخير: كيف وجدتُم عبادي؟ فيقولون: وجدناهم يُسبِّحونك، ويستغفرونك، ويذكرونك... إلى آخره، قال: ماذا يسألون؟ قالوا: يسألونك الجنةَ... إلى آخر الحديث.\nفالمقصود أن هذا السؤال من الله لإظهار فضلهم، وإظهار شأنهم، وليس فيه دلالة على التَّكبير الجماعي، أو الذكر الجماعي، كلٌّ يُسبح لنفسه، وكلٌّ يدعو لنفسه، وهذا يسأل عن علمٍ، وهذا يسأل عن آيةٍ، وهذا يسأل عن حديثٍ، هذا يقول: سبحان الله، وهذا يقول: الحمد لله، وهذا يقول: لا إله إلا الله، ما كان الصحابةُ يذكرونه جماعيًّا، وهم القدوة، لكن هذا يدل على أنَّ الملائكة تحفظ عليهم أعمالهم.","link":"https://binbaz.org.sa/fatwas/20853/معنى-حديث-وجدناهم-يعبدونك-ويسبحونك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0649 الحديث الذي في البخاري  وجدناهم يعبدونك ويسبحونك فهل في الحديث جواز التسبيح الجماعي؟ ابن باز.mp3","categories":["شروح الحديث"]},{"id":855,"question":"إنَّ رسول الله ﷺ يقول: إذا رأيتُم الرجل يعتاد المساجدَ فاشهدوا له بالإيمان، ونُلاحظ أنَّ من بين روَّاد المساجد مَن لا يتَّقي الله، ولا يُراقبه في أعماله، كيف تُفسرون هذا الأمر؟","title":"معنى حديث \"إذا رأيتُم الرجل يعتاد المساجدَ\"","answer":"الجواب: هذا وصفٌ أغلبي، الغالب على أهل المساجد الخير، مَن حافظ على الصلاة واستقام على أدائها في الجماعة فالغالب عليه أنه من أهل الخير. فهو -لو صحَّ الحديثُ- فهو وصفٌ أغلبي، ولكن الحديث ضعيفٌ عند أهل العلم؛ لأنه من رواية شخصٍ يُقال له: دراج أبو السمح، عن أبي الهيثم، وروايته ضعيفةٌ، فالحديث عند أهل العلم ليس بثابتٍ. ولكنه لو صحَّ فالمراد بذلك أنه وصفٌ أغلبي، يعني: الغالب على مَن يعتاد المساجد ويستقيم على الصلاة الغالب عليه الخير.","link":"https://binbaz.org.sa/fatwas/20889/معنى-حديث-اذا-رايتم-الرجل-يعتاد-المساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0684ما معنى حديث إذا رأيتم الرجل يعتاد المساجد فاشهدوا له بالإيمان؟ ابن باز فتاوى المحاضرات.mp3","categories":["شروح الحديث"]},{"id":865,"question":"من القضايا التي تُثير المُناقشات في بعض الأحيان: التوسل، خاصَّةً بجاه وقدر رسول الله ﷺ وبعض الأولياء والصَّالحين الأموات، فهل يجوز ذلك أم يحظر؟ أفيدونا وفَّقكم الله.","title":"حكم التوسل بجاه النبي وقبور الصالحين","answer":"الجواب: التوسل بالجاه محظورٌ عند جمهور أهل العلم؛ لأنه ليس من المشروعات، ولم يأتِ عن النبي ﷺ ولا عن أصحابه ما يدل على جوازه، فهو من البدع، والدعاء والوسائل من العبادات، فلا يجوز أن يتّخذ من الوسائل إلا ما شرعه الله، فالتوسل بجاه النبي، أو بجاه فلانٍ، أو بحقِّ الأنبياء، أو بحقِّ المؤمنين؛ لا أصلَ له، بل هو من البدعة في الدعاء، وإنما التوسل يكون بأسماء الله وصفاته، كما قال : وَلِلَّهِ الْأَسْمَاءُ الْحُسْنَى فَادْعُوهُ بِهَا [الأعراف:180].\nوفي الحديث: اللهم إني أسألك بأني أشهد أنَّك أنت الله لا إله إلا أنت، وحديث أصحاب الغار، التوسل بأعمالهم الطيبة: واحد توسَّل ببرِّ والديه، والثاني توسَّل بعفَّته عن الزنا، والثالث توسَّل بأداء الأمانة؛ لا بأس، أما التوسل بجاه فلانٍ وحقِّ فلانٍ؛ هذا بدعة، هذا هو الذي عليه جمهورُ أهل العلم، وليس بشركٍ، لكنه بدعة من وسائل الشرك.","link":"https://binbaz.org.sa/fatwas/20906/حكم-التوسل-بجاه-النبي-وقبور-الصالحين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0701ما حكم التوسل بجاه وقبر الرسول صلى الله عليه وسلم وبعض الأولياء والصالحين والأموات؟ ابن باز.mp3","categories":["شروح الحديث","التوسل والشفاعة"]},{"id":913,"question":"هناك حديثٌ عن النبي عليه الصلاة والسلام: الأذنان من الرأس، فما صحَّة هذا الحديث؟ وهل يلزم منه أن يحلق الشعر الذي ينبت على الأذنين في العمرة أو الحج؟","title":"ما حكم وكيفية مسح الأذنين في الوضوء؟","answer":"الجواب: نعم، الأذنان من الرأس، وقد دلَّت على ذلك أحاديث صحيحة، كان يمسح ﷺ على رأسه وأذنيه جميعًا، ولا يغسلهما مع الوجه، فدلَّ على أنهما من الرأس، والواجب مسحهما في الوضوء مع الرأس، وحلق ما فوقهما في الحجِّ والعمرة.","link":"https://binbaz.org.sa/fatwas/20946/ما-حكم-وكيفية-مسح-الاذنين-في-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0742في الحديث الأذنان من الرأس فهل يلزم منه أن يحلق الشعر الذي ينبت على الأذنين؟ ابن باز.mp3","categories":["شروح الحديث"]},{"id":954,"question":"هل هداية الإنسان من الضَّلال إلى الصلاح مع كونه مسلمًا يدخل في حديث: «لأن يهدي الله بك رجلًا واحدًا خيرٌ لك من حُمْر النَّعم»؟","title":"هل فضل \"حُمْر النَّعم\" يعمُّ هداية مسلم عاصٍ؟","answer":"الجواب: الذي يظهر العموم، وإن كان في اليهود ودخولهم في الإسلام، لكن العبرة بعموم الألفاظ، لا بخصوص الأسباب، وفضل الله واسعٌ ، فإذا هدى الله على يد الإنسان إنسانًا من الكفر حتى دخل في الإسلام فهذا داخلٌ في الحديث بلا شك، وإذا هداه الله على يديه من الخمر ومن الزنا، أو من العقوق؛ فهو خيرٌ له من حمر النعم، كذلك نعمة عظيمة، هدى الله على يديه أخًا له كان يعق والديه، فهداه الله بأسبابه، كان زنَّاءً فهداه الله بأسبابه، كان سِكّيرًا فهداه الله بأسبابه، كان مُرابيًا فهداه الله بأسبابه، وهو مسلمٌ؛ نرجو لك هذا الفضل، وأنَّ لك هذا الفضل الذي قاله النبيُّ ﷺ: خيرٌ لك من حمر النعم، بل خيرٌ من الدنيا وما عليها؛ لأنَّ الرسول أراد به التَّمثيل، ليس المراد الحصر، لكن لما كانت حُمْرُ النَّعم معروفة عند العرب ويُفضلونها كثيرًا مثَّل بها عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/21003/هل-فضل-حمر-النعم-يعم-هداية-مسلم-عاص","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0800هل هداية الإنسان من الضلال إلى الصلاح مع كونه مسلما يدخل في حديث لأن يهدي الله بك رجلا واحدا؟.mp3","categories":["شروح الحديث"]},{"id":960,"question":"سماحة الشيخ، ورد عنه ﷺ أنه قال: شيَّبتني هودٌ وأخواتها، فما أخوات هود؟","title":"ما أخوات هود بحديث \"شيَّبتني هودٌ...\"؟","answer":"الجواب: جاء في بعض الروايات بيان أخواتها: الواقعة، والمرسلات، وعم يتساءلون، وجاء في بعضها زيادة ونقص، ومَن أراد ذلك فليُراجع تفسير ابن كثير في تفسير سورة هود، وهكذا غيره: كابن جرير، والبغوي، وغيرهم، هذا الحمد لله موجود.","link":"https://binbaz.org.sa/fatwas/20996/ما-اخوات-هود-بحديث-شيبتني-هود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0793ورد عنه صلى الله عليه وسلم شيبتني هود وأخواتها فما أخوات هود؟ ابن باز فتاوى المحاضرات.mp3","categories":["شروح الحديث"]},{"id":982,"question":"جاء في \"صحيح البخاري\" أنَّ مَن قتل نفسه خالد مُخلَّد في النار، وعقيدة أهل السنة والجماعة أنَّ صاحب الكبيرة لا يُخلَّد في النار. نرجو التوضيح أفادكم الله.","title":"معنى ما جاء في خلود بعض العصاة بالنار","answer":"الجواب: الخلود خلودان: خلود الكفرة، وهو الذي ليس له نهاية، فهذا يختص بالكفرة. وأما الخلود الذي هو طول الإقامة؛ فهذا قد يقع لبعض العصاة: كقاتل نفسه، فإن الرسول ﷺ قال: إنه في النار خالدًا مُخَلَّدًا فيها يعني: مُقيمًا طويلًا -نسأل الله العافية- والعرب تقول فيمَن أطال الإقامة: أقاموا فأخلدوا، أي: طوَّلوا، وقال تعالى: وَالَّذِينَ لَا يَدْعُونَ مَعَ اللَّهِ إِلَهًا آخَرَ وَلَا يَقْتُلُونَ النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ وَلَا يَزْنُونَ وَمَنْ يَفْعَلْ ذَلِكَ يَلْقَ أَثَامًا  ۝  يُضَاعَفْ لَهُ الْعَذَابُ يَوْمَ الْقِيَامَةِ وَيَخْلُدْ فِيهِ مُهَانًا [الفرقان:68- 69]، فجعل المشرك والزاني والقاتل في عذابٍ وخلودٍ، وقال جلَّ وعلا في القاتل: وَمَنْ يَقْتُلْ مُؤْمِنًا مُتَعَمِّدًا فَجَزَاؤُهُ جَهَنَّمُ خَالِدًا فِيهَا وَغَضِبَ اللَّهُ عَلَيْهِ وَلَعَنَهُ وَأَعَدَّ لَهُ عَذَابًا عَظِيمًا [النساء:93]، هذا الخلود عند أهل السنة خلودٌ له نهاية، إذا كان لم يستحلّ ذلك، أما إذا استحلَّ القتلَ والزنا صار كافرًا مُخَلَّدًا خلود الكفار، لكن إذا قتل وهو يعلم أنه عاصٍ، أو زنا وهو يعلم أنه عاصٍ، فهذا لا يُخلَّد خلود الكفار، ولكنه خلود له نهاية.\nفالعُصاة على حسب مراتبهم في المعاصي، مَن دخل النارَ منهم فهم متفاوتون في ذلك: منهم مَن تطول إقامته، ومنهم مَن لا تطول، على حسب حاله في المعاصي، وقد يعفو الله عن بعضهم فلا يدخل النار، كما قال تعالى: وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ [النساء:48]، وقد يعفو عن بعضهم لأعمالٍ صالحةٍ، وكثرة خيرٍ. ولكن مَن دخلها منهم فهم على أقسامٍ وعلى درجات، لكنَّهم لا يُخلَّدون خلود الكفار، بل مَن كثرت معاصيه وعظمت -كالقاتل والزاني- فهذا يُخلَّد خلودًا له نهاية، وهكذا قاتل نفسه، يعني: خلودًا طويلًا، إقامة طويلة، لكن لها نهاية، ما يُخلَّد خلود الكفار أبدًا عند أهل السنة والجماعة، ولكنه خلود له أمد، وله نهاية، نسأل الله السلامة والعافية.","link":"https://binbaz.org.sa/fatwas/21026/معنى-ما-جاء-في-خلود-بعض-العصاة-بالنار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0823في البخاري أن من قتل نفسه خالداً مخلداً في الناروعقيدة أهل السنة أن صاحب الكبيرةلا يخلد في النار.mp3","categories":["شروح الحديث","مسائل متفرقة في العقيدة"]},{"id":1053,"question":"كيف نُوفق بين الحديثين الشريفين: لا عدوى، ولا طيرة و فِرّ من المجذوم فرارك من الأسد؟","title":"معنى حديثَي: \"لا عدوى\" و\"فر من المجذوم\"؟","answer":"الجواب:\nلا مُنافاة عند أهل العلم بين هذا وهذا، كلاهما قاله النبيُّ ﷺ، قال: لا عدوى، ولا طيرة، ولا هامَةَ، ولا صفر، ولا نوء، ولا غول نفيًا لما يعتقده العربُ من أن العدوى تُعدي بطبعها، الأمراض تُعدي بطبعها، وأنَّ مَن خالط المريضَ أصابه ما أصاب المريض، هذا غلطٌ، قد يُخالطه ولا يحصل به شيء، هذا واقع ومعروف.\nولا طيرة يعني: كانوا يتشاءمون يتطيرون، إذا سمعوا صوتًا لا يُعجبهم تشاءموا ورجعوا عن حاجتهم، أو رأوا شيئًا لا يُعجبهم تراجعوا عن حاجاتهم، فالنبي نهى عن الطيرة: لا طيرة، وسمَّاها: شركًا، فإذا خرج لحاجةٍ ورأى مثلًا شيئًا لا يُعجبه -إنسانًا لا يُعجبه، أو دابَّةً لا تُعجبه- يمشي في حاجته ويقول: اللهم لا خيرَ إلا خيرك، ولا طير إلا طيرك، ولا إله غيرك، ويقول أيضًا: اللهم لا يأتِي بالحسنات إلا أنت، ولا يدفع السيئات إلا أنت، ولا حول ولا قوة إلا بك، هكذا قال النبيُّ ﷺ: إذا رأى الإنسانُ ما يكره يقول: اللهم لا يأتي بالحسنات إلا أنت، ولا يدفع السيئات إلا أنت، ولا حول ولا قوة إلا بك، واللفظ الآخر قال: اللهم لا خيرَ إلا خيرك، ولا طير إلا طيرك، ولا إله غيرك، أو سمع صوتًا من غرابٍ أو غيره لا يلتفت لها، يمشي في حاله. لا هامة الهامة كانوا يتشاءمون بها في الجاهلية يقولون يسمعون روح الميت، يقولون: هذه روح الميت تتكلم، عندما يسمعون صوت البومة -طائر معروف- يُسمّونها: الهامة، ويقولون: هذه تنعى الميت، وأن صاحب البيت يموت، كل هذه خُرافات لا أصلَ لها، ويقولون: إنها تأتي إلى الأموات، تطير عند القبور، كل هذا لا أصلَ له.\nولا صفر الشهر المعروف صفر، يتشاءم منه أهلُ الجاهلية، فأبطل النبيُّ ﷺ ذلك، وقال بعضُهم: إنَّ صفر داءٌ في البطن يتشاءم به أهلُ الجاهلية، فأبطله النبيُّ عليه الصلاة والسلام.\nولا نَوء كانوا يتشاءمون ببعض الأنواء -بعض النجوم- فأبطلها النبيُّ ﷺ.\nولا غُول الغُول: مُخبّلات الجن، ويُقال لها: الثعالب، كانوا يتشاءمون بها ويقولون: إنها تفعل بنفسها، وأنها تضلّهم عن الطريق، وأنها تَصَرَّف بنفسها، فأبطل النبيُّ ﷺ ذلك، وأنها لا تصرف لها بنفسها، بل هي من مخلوقات الله، إذا رآها الإنسانُ يتعوَّذ بكلمات الله التامَّات من شرِّ ما خلق، ويكفي، ويُشرع له الأذان عند رؤية الشياطين، كما في الحديث: إذا تغوَّلت الغيلانُ فعليكم بالأذان، وفي الحديث: إن الشيطان إذا سمع النِّداء فرَّ، إذا سمع الأذان، فالسنة إذا رأى الإنسانُ ما يُخيفه من أزوال يظنّها جنًّا أن يرفع صوته بالأذان، فهي تطرد ذلك.\nوالجواب عن: فرّ من المجذوم، وعن الحديث الآخر: لا يُورِد مُمرضٌ على مُصحٍّ، الجواب عنه: معناه: أنه لا يجوز أن يعتقد بالعدوى، ولكن لا بأس أن يتعاطى الأسباب مع كونه لا يعتقد العدوى، وأن الأمراض تُعدي بطبعها، لا، ما تُعدي بطبعها إلا بإذن الله جلَّ وعلا، إذا أراد ذلك وقعت العدوى، لكن أن يجتنب الأسبابَ ويبتعد عن أسباب الأمراض التي تُعدي، التي من عادتها ومن طبعها أنها تنتقل في الغالب، لا يُخالط أهلها: كالجذام، في الغالب أنه ينتقل، فلا يُخالط، وجاء في بعض الأحاديث عنه ﷺ أنه جاءه وفدٌ يُبايعونه وفيهم مجذوم، فقال: ارجع، فقد بايعتُك، بايعه من دون مماسَّةٍ، وجاء عنه أنه أكل مع المجذوم وقال: كُلْ بسم الله، ثقةً بالله، فإذا وثق الإنسانُ وتساهل ولم يُبال؛ فلا بأس، وإن اتَّقى الأمراض التي يخشى منها؛ فلا بأس.\nوهكذا: لا يُورِد مُمرضٌ على مُصحٍّ يعني: لا يجوز لصاحب الإبل المراض، أو البقر المراض، أو الغنم المراض، لا يُوردها مع صاحب الإبل الصَّحيحة، والبقر الصحيحة، والغنم الصحيحة، يكون لهذا وقت، ولهذا وقت؛ لأنه يخشى أن يكون مع الخلطة أن تنتقل هذه الأمراض إلى الصَّحيحة، من باب اتِّقاء الأسباب، من باب البُعد عن الأسباب التي يخشى منها، وليس من باب العدوى، من باب البُعد عن الأسباب التي يخشى منها الشرّ. هذا هو معنى الحديث عند أهل العلم، فيتَّقي الأسباب مع اعتقاده أنه لا عدوى إلا بإذن الله، وأنَّ المراد: لا تُعدي بطبعها، فكم من مريضٍ خالط أصحاء فلم يُصبهم إلا خير، وكم من جرباء وقعت في ..... ولم تُجرب، وكم من شخصٍ خالط جذماء فلم يُصب بجذامهم؛ لأنَّ الله لم يُرد ذلك. لكن المؤمن مأمورٌ بالبعد عن الأسباب الضَّارة، كما يبتعد عمَّا يضرُّه من حيات، وعقارب، وذئاب، يحذر الأسبابَ التي تضرُّه، ويأخذ السلاح عند الحاجة؛ من باب الأخذ بالأسباب.","link":"https://binbaz.org.sa/fatwas/21102/معنى-حديثي-لا-عدوى-وفر-من-المجذوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0898كيف نوفق بين حديث لاعدوى ولاطيره وحديث فرَّ من المجذوم فرارك من الأسد؟ ابن باز.mp3","categories":["شروح الحديث"]},{"id":1072,"question":"هذا يقول: إني أجد في نفسي حرجًا في كل عملٍ أو قولٍ أقوم به، نتيجة التفكير المُستمر في الرياء، والذي حرمني من أعمال وأقوال ربما أن المصلحة تقتضيها، فما السبيل للخلاص، مع العلم أنني ذُقْتُ من ذلك الكثير من الآلام؟","title":"حكم من يجد في نفسه خوفًا مستمرًّا من الرياء","answer":"الجواب:\nهذه من مكائد أعداء الله، الشيطان يأتي إلى الرجل الصالح ويقول: أنت فعلتَ هذا رياءً، تفعل هذا رياءً، حتى يُثبطه. فاتَّقِ الله واحذر هذا الشيء، ولا تلتفت إلى عدو الله، افعل الخير، وهذه الهواجس التي تقول لك: الرياء، الرياء، هذا من الشيطان، احذر وافعل ما استطعت من الخير، ولا تتوهم هذه الأشياء، واعلم أنها من مكائد أعداء الله، من مكائد الشياطين، بعدما تعلم من نفسك أنك فعلتَها لله، فاحذر هذه الوساوس ولا تلتفت إليها بالكلية.","link":"https://binbaz.org.sa/fatwas/21110/حكم-من-يجد-في-نفسه-خوفا-مستمرا-من-الرياء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0906يقول السائل أني أجد في نفسي حرجاً في كل عمل أقوم به نتيجة التفكير المستمر في الرياء فما الخلاص؟.mp3","categories":["شروح الحديث","الرياء والسمعة"]},{"id":1098,"question":"ورد في الحديث: وكلتا يدي الرحمن يمين، وفي الحديث الآخر: وبيده الأخرى الميزان، وفي مسلمٍ: إنَّ الأخرى تُسمَّى بالشمال وطعن فيها البيهقي، وبعده ابن حجر، في تفرُّد عمر بن حمزة بن عبدالله بن عمر بها، ورواه نافع وابن مقسم بدونها، فما معنى الحديث؟ وهل إذا قيل أنَّها يمين في الفضل؛ لئلا يتوهم فيها نقصٌ لتسميتها الشمال، فيكون ذلك تأويلًا؟ أفيدونا جزاكم الله خيرًا.","title":"ما معنى حديث \"وكلتا يدي الرحمن يمين\"؟","answer":"الجواب:\nالحديث ثابتٌ، ورواه مسلم، ومسلم رحمه الله توخَّى الأحاديث الصَّحيحة، وإذا كان جرح عمر بن حمزة بعض الناس فمُسلم لم يجرحه، وروى عنه، ووثَّقه ابنُ حبان، وصحح له الحاكم.\nفالمقصود أن الحديث لا بأس به، وهي شمال في الاسم، وأما في الفضل فهي يمين، ولهذا في الحديث الصحيح: كلتا يدي ربي يمين مباركة، فكلاهما يمين مباركة في الشرف والفضل، وتُسمَّى إحداهما: يمينًا، كما قال تعالى: وَالسَّمَاوَاتُ مَطْوِيَّاتٌ بِيَمِينِهِ [الزمر:67]، وتُسمَّى الأخرى: شمالًا، وهي يمينٌ في الفضل والبركة والشرف، وإن سُمِّيَتْ شمالًا، لكنها في الفضل والشرف لها ما لليمين باليُمن والخير والبركة والشرف، ولا منافاة، فالحديث كلتا يدي ربي يمين مباركة، يُبين فضلها وشرفها، وأنه لا نقصَ فيها، والتَّسمية بتسميتها شمالًا لا يدل على النقص، بل إنما هي مجرد أسماء فقط، كما أن تسمية يده: يد، وتسميته قدمه: قدم، وعين، وسمع، وبصر، كل هذا لا يتضمن المشابهة والتَّمثيل، فكلها صفات تليق بالله، وكلها كاملة، ليس فيها نقصٌ، تليق بالله جلَّ وعلا، لا يُماثل فيها خلقه .","link":"https://binbaz.org.sa/fatwas/21153/ما-معنى-حديث-وكلتا-يدي-الرحمن-يمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0949ما معنى حديث وكلتا يدي الرحمن يمين؟ ابن باز فتاوى المحاضرات.mp3","categories":["شروح الحديث"]},{"id":1099,"question":"ورد في \"صحيح البخاري\" وغيره في حديثٍ ما معناه: وإذا أتاني مشيًا أتيتُه هرولةً، فما معنى الحديث، علمًا بأنَّ اللازم منه واضح، وهو سرعة رحمة الله للعبد؛ لأنَّ بعض أهل العلم المُعاصرين يُثبت ذلك صفةً لله، رغم أنه لا يعلم أنَّ أحدًا من السلف أثبته؟ فأفتونا بذلك مأجورين جزاكم الله خيرًا.","title":"معنى حديث \"وإذا أتاني مشيًا أتيته هرولة\"","answer":"الجواب:\nبسم الله، والصلاة والسلام على رسول الله، الحديث معروفٌ، وفي أوله يقول النبيُّ ﷺ: يقول الله جلَّ وعلا: مَن ذكرني في نفسه ذكرتُه في نفسي، ومَن ذكرني في ملإٍ ذكرتُه في ملإٍ خيرٍ منه، ومَن تقرَّب إليَّ شبرًا تقرَّبتُ إليه ذراعًا، ومَن تقرَّب إليَّ ذراعًا تقرَّبتُ منه باعًا، ومَن أتاني يمشي  أتيتُه هرولةً.\nطريقة أهل السنة والجماعة في هذه الأحاديث وأشباهها إمرارها كما جاءت، وعدم تأويلها، وعدم تكييفها، معناها واضح وظاهر، وأنه جلَّ وعلا بفضله وإحسانه أسرع بالخير والإحسان إلى عباده منهم، وهذا مضمون الحديث. أما معناه: فلا يعلم كيفيته إلا هو ، فهو جلَّ وعلا تقرُّبه إلى عباده ومشيه إليهم هرولةً هذه أمور هو أخبر بها عن نفسه، فلا تُفسَّر بما يُخالف ما جاء في كتابه وسنة نبيه، بل يُقال فيها كما يُقال في غيرها: لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ الْبَصِيرُ [الشورى:11]، وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ [الإخلاص:4]، فتقربه ذراعًا وباعًا ومجيئه هرولةً، كل هذا شيءٌ نسبه لنفسه، فننسبه إليه ونقول: لا يعلم كيفيته إلا هو، كما لا يعلم كيف استواؤه، ولا كيف نزوله في آخر الليل، ولا كيف مجيئه يوم القيامة إلا هو ، ولا كيف غضبه، ولا كيف رضاه، ولا كيف يضحك ويتقرب ذراعًا وباعًا، وكيف يأتي هرولةً، كل هذا إليه ، لا يعلم كيفيته إلا هو.\nلكن المعنى من مُقتضى هذا الحديث: أنه أسرع بالخير لنا، وأنه أسرع بالإحسان لنا من فضله وجوده، أما كيفية هذا المعنى، وما صفة هذا المعنى؟ فهذا إليه ، لا يعلم كيف صفاته إلا هو جلَّ وعلا، كسائر الصِّفات.","link":"https://binbaz.org.sa/fatwas/21152/معنى-حديث-واذا-اتاني-مشيا-اتيته-هرولة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0948ما معنى حديث وأذا أتاني مشياً أتيته هرولة؟ ابن باز فتاوى المحاضرات.mp3","categories":["شروح الحديث"]},{"id":1119,"question":"ورد عن النبي ﷺ أنه قال في ذات ليلةٍ: أرأيتُم ليلتكم هذه؟ فإنه بعد مئة سنةٍ لا يبقى ممن على وجه الأرض أحد، أو كما قال ﷺ، وفي قصة الجسَّاسة عند مسلمٍ: أن تميم الداري رأى الدجالَ وهو ينتظر أن يُؤْذَن له بالخروج. كيف نُوفِّق بين قول النبي ﷺ: لا يبقينَّ بعد مئة سنةٍ أحدٌ وكون الدجال عائشًا منذ ذلك الوقت إلى يومنا هذا؟","title":"معنى حديث \"لا يبقينَّ بعد مئة سنةٍ أحدٌ\"","answer":"الجواب:\nالحديث صحيحٌ، ومراد النبي ﷺ أنَّ القرن يخترم -كما قاله الصحابة- وأنه لا يبقى على وجه الأرض ممن هو على ظهرها ذاك الوقت أحدٌ بعد مئة عام، أي: يموتون.\nأما حديث الدجال: فهو من باب الخاصّ، من باب الخصوصية، فلا يرد على هذا؛ لأنَّ النصوص فيها خاصٌّ وعامٌّ، هذا يعمُّ، ما عدا خبر الدجال.","link":"https://binbaz.org.sa/fatwas/21160/معنى-حديث-لا-يبقين-بعد-مىة-سنة-احد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0956كيف نوفق بين قوله عليه الصلاة لا يبقينَّ بعد مائة سنة أحد وكون الدجال عائش إلى يومنا هذا؟ابن باز.mp3","categories":["شروح الحديث"]},{"id":1140,"question":"ما حكم قراءة القرآن للحائض والنُّفساء، وأحيانًا يُصادف الامتحان مثل هذه الحالات؟","title":"ما حكم قراءة القرآن للحائض والنُّفساء؟","answer":"فيه خلافٌ بين أهل العلم، والصواب أنه يجوز للحائض أن تقرأ القرآنَ عن ظهر قلبٍ، والنفساء كذلك، ولا يجوز أن تُقاس عليها الجُنُب، والجُنُب يتيسر له الاغتسال بسرعةٍ ويقرأ، لكن الحائض والنفساء ليستا كذلك، ليستا مثله، لهن مدَّة، ليس الأمر بأيديهن.\nفالصواب أنه يجوز لهنَّ قراءة القرآن عن ظهر قلبٍ، وهكذا قراءة القرآن من المصحف من وراء حائلٍ أو قفَّازين عند الحاجة إلى ذلك: كمُراجعة مَن تغلط فيه عند الامتحان ونحو ذلك.\nأما حديث لا يقرأ القرآنَ الحائضُ والجنبُ فهو حديثٌ ضعيفٌ عند أهل العلم، والصواب أنَّ هذا خاصٌّ بالجُنب، كان النبي ﷺ لا يحجزه شيءٌ عن القرآن إلا الجنابة، فلا يُقاس على الجنبِ الحائضُ والنفساء؛ لأنهما ليستا مثله، وهما في حاجةٍ إلى قراءة القرآن عن ظهر قلبٍ، وإلى مُراجعته عند الامتحان والاختبار، ولئلا تنساه الحائض والنفساء، ولكن يجوز بواسطة حائلٍ: قفَّازين ونحوهما.","link":"https://binbaz.org.sa/fatwas/21192/ما-حكم-قراءة-القران-للحاىض-والنفساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0988ما حكم قراءة القرآن للحائض والنفساء وأحياناً يصادف اختبار؟.mp3","categories":["شروح الحديث","القرآن وعلومه","الحيض والنفاس"]},{"id":1142,"question":"هل يجوز لي أن أتزوج من شقيق أبي رضاعةً؟","title":"حكم الزواج من شقيق الأب بالرضاعةً","answer":"الجواب:\nهذا عمُّك، تتزوجين عمك؟! شقيق أبيك رضاعةً مثل شقيقه نسبًا، والعم مُحرَّمٌ، لا يجوز التزوج عليه، أما ابن العم فلا بأس، عمّك وعمّ جدك، حتى عمّ الجد وعمّ الأب عمٌّ لك، عمُّكِ وعمُّ أبيك وعمُّ جدك من النَّسب والرضاع كلهم محارم، أما ابن العم فلا بأس.","link":"https://binbaz.org.sa/fatwas/21190/حكم-الزواج-من-شقيق-الاب-بالرضاعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجوز الزواج من شقيق الأب رضاعة.mp3","categories":["شروح الحديث","الرضاع"]},{"id":1173,"question":"الحديث القدسي الذي يقول فيه النبيُّ ﷺ: لا تسبُّوا الدهر، فإنَّ الله هو الدهر، أو كما ورد، ما المقصود بالدهر؟ هل هو مرور الزمن؟ وإذا كان كذلك فهل يجوز أن نقول: إنَّ صلاتي ونُسكي لدهري، باعتبار أنَّ الدهر هو الله؛ استنادًا إلى هذا الحديث؟","title":"ما معنى الدهر في حديث \"لا تسبوا الدهر\"؟","answer":"الجواب:\nالدهر هو الزمان، ومعنى لا تسبُّوا الدهر؛ لأنَّ الدهر ليس عنده تصرُّفٌ، المتصرف في الدهر هو الله وحده، ولهذا قال ﷺ: لا تسبُّوا الدهر، فإنَّ الله هو الدهر، يُقلِّب ليلَه ونهارَه يعني: هو المتصرف فيه سبحانه وتعالى.  والدهر هو الزمان، كانوا في الجاهلية يقولون: ما يُهلكنا إلا الدهر، فأنكر الله عليهم ذلك، فالدهر هو الزمان، لا يُسبُّ؛ لأن سبَّه سبٌّ لما لا يستحق السبَّ، ليس في يده تصرُّفٌ، المتصرف هو الله وحده، هو الذي يُقلِّب الليلَ والنَّهار، وينزل ما ينزل، ويقدر ما يقدر .\nولهذا في الحديث الصحيح يقول الله جلَّ وعلا: يُؤذيني ابن آدم؛ يسبُّ الدهر، وأنا الدهر، أُقلِّب الليل والنَّهار، فمعنى أنه الدهر: يُقلِّب ليله ونهاره، ويُصرِّف شؤون هذا الدهر بين العباد، فلا يُسبُّ الدهر؛ لأنَّ سبَّ الدهر معناه سبّ للذي يُصرِّف شؤونه .\nفلا يجوز للمسلم أن يسبَّ الدهر، ولكن يُجاهد نفسه في طاعة الله ورسوله، وترك ما نهى الله عنه ورسوله، فما أصابه من الأذى هو بأسباب أعماله السيئة، لا بأسباب الدهر، الدهر ما له تصرُّفٌ، لكن وصفه بالشدة لا يضرُّ، يقول: هذا زمان شديد، أو هذا زمان حارٌّ أو بارد، ما يضرُّ هذا، لكن السبَّ: كونه يلعنه، أو يقول: لعن الله هذه الساعة، أو هذا اليوم، أو هذا الزمان، أو لا بارك الله في هذه الساعة، أو قاتل الله هذه الساعة، أو ما أشبه من السبِّ؛ هذا هو المنهي عنه، أما كونه يقول: هذا الزمان شديد، أو حارٌّ، أو باردٌ، أو وصفه بالشدة؛ فلا يضرُّ ذلك.","link":"https://binbaz.org.sa/fatwas/21229/ما-معنى-الدهر-في-حديث-لا-تسبوا-الدهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1164ورد في الحديث لا تسبوا الدهر فإن الله هو الدهر أو كما ورد ما المقصود بالدهر؟ ابن باز.mp3","categories":["شروح الحديث","مسائل متفرقة في العقيدة"]},{"id":1186,"question":"كيف نربط بين أنَّ الرسول ﷺ يقوم الليل ويأمر بذلك، وبين ما ورد عنه ﷺ: مَن صلَّى العشاء والفجر في جماعةٍ فكأنما قام الليل؟","title":"معنى الفضل في صلاة العشاء والفجر جماعة","answer":"الجواب:\nلا منافاة، هذا يُبين فضل صلاة العشاء والفجر في الجماعة، ولكن مَن قام الليل يكون أكمل وأعظم، وجمع بينهما، مَن صلَّى العشاء في جماعةٍ فكأنما قام نصف الليل، ومَن صلَّى الفجر في جماعةٍ فكأنما قام الليل كله، يعني: العشاء والفجر جميعًا، هذا تحريضٌ على المسارعة إلى الجماعة، والحرص على أداء هاتين الصلاتين في الجماعة، ولكن إذا جمع بين هذا وبين قيام الليل جمع خيرًا كثيرًا.\nويدل هذا على أن التَّهجد بالليل ليس بواجبٍ، بل هو سنة وقُربة، وليس بواجبٍ، مثلما قال ﷺ في قُلْ هُوَ اللَّهُ أَحَدٌ أنها تعدل ثلث القرآن، يعني: في الفضل، لكن إذا قرأ الثلثَ صار أكمل؛ لما يحصل من الخير في قراءة القرآن، وتدبُّر القرآن، وإذا ختمه كله صار أفضل وأفضل، وإن كانت تعدل في الأجر، لكن تحصل له أجور أخرى فيما يحصل له من التَّدبر والتَّعقل وكثرة الآيات التي يقرؤها، إلى غير ذلك، هذا يُبين فضلها وفضل صلاة الفجر والعشاء في جماعةٍ، لكن مَن جمع بينهما كان أفضل وأكمل.","link":"https://binbaz.org.sa/fatwas/21246/معنى-الفضل-في-صلاة-العشاء-والفجر-جماعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1148كيف نجمع بين قيام الليل وحديث من صلى العشاء والفجر في جماعة فكأنما قام الليل كله.mp3","categories":["شروح الحديث"]},{"id":1205,"question":"ما العوامل التي تُساعد على تجنب الرياء؟","title":"ما العوامل التي تعين على تجنب الرياء؟","answer":"الجواب:\nالعوامل على ذلك: استحضار عظمة الله، وأنك عبدٌ من عباده، مطلوب طاعته، والرغبة فيما عنده، والجزاء من عنده، وأن الناس لا ينفعون ولا يضرُّون، كل شيءٍ عنده . فاستحضر أنَّ الخير بيده كله، وأنه النافع والضَّار، لا مانع لما أعطى، ولا مُعطي لما منع، فليس حاجة إلى الرياء، ما في حاجة إلى رياء الناس، لا ينفعونك ولا يضرُّونك إلا بإذن الله.  فأخلص لله، واستحضر أنَّ كل خيرٍ بيده، وأنه النافع والضَّار، المعطي والمانع، فليس ينفعك رياؤهم، بل يضرّك رياؤهم، فاحذر رياءَهم، وأخلص لله العمل؛ لأنه الضَّار النافع .","link":"https://binbaz.org.sa/fatwas/21264/ما-العوامل-التي-تعين-على-تجنب-الرياء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1130ما هي الأسباب التي تجعلني أتجنب الرياء؟ ابن باز فتاوى.mp3","categories":["شروح الحديث","الرياء والسمعة"]},{"id":1216,"question":"قال ﷺ: مَن صام ثلاثة أيام من كل شهرٍ فقد صام الدهرَ كله،  هل يقصد بالثلاثة أيام الأيام البيض أو أي ثلاثة أيام؟","title":"هل صوم ثلاثة أيام كل شهر يُقصد به البِيض؟","answer":"الجواب:\nالشيخ: عامٌّ، يعمّ الأيام كلها، ثلاثة أيام من كل شهر، سواء من أوله، أو من آخره، أو من وسطه؛ لأنَّ الأحاديث الصَّحيحة كلها ليس فيها البيض، فيها صوم ثلاثة أيام، والنبي ﷺ أوصى أبا هريرة وأوصى أبا الدَّرداء بصيام ثلاثة أيام من كل شهرٍ، ولم يقل لهما: البيض، وهكذا قال لعبدالله بن عمرو: صم من الشهر ثلاثة أيام.\nلكن إذا صام البيض فهو أفضل، كما جاء في حديث أبي ذرٍّ: يصوم الثالث عشر والرابع عشر والخامس عشر، إذا صام البيض فذلك أفضل، وإلا فيكفي أن يصوم من الشهر، سواء كان من أوله، أو من وسطه، أو من آخره، والحمد لله، سواء متفرقة أو مجتمعة أيضًا، سواء جمعها وتابعها أو فرَّقها.","link":"https://binbaz.org.sa/fatwas/21272/هل-صوم-ثلاثة-ايام-كل-شهر-يقصد-به-البيض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1122قال عليه الصلاة والسلام من صام ثلاثة أيام من كل شهر فقد صام الشهر كله هل هي البيض.mp3","categories":["شروح الحديث","صيام التطوع"]},{"id":1245,"question":"كيف نُفسر هذا الحديث: قول النبي ﷺ: لا يدخل الجنةَ قتَّاتٌ، لا يدخل الجنةَ نمَّامٌ؟ وكيف لا يدخل الجنةَ مع أنه قد يكون مات على التوحيد؟","title":"معنى الوعيد في \"لا يدخل الجنة نمام\" ونحوه","answer":"الجواب:\nهذه يُقال لها: أحاديث الوعيد، يُسميها العلماء: أحاديث الوعيد على المعاصي، يتوعدهم النبيُّ ﷺ بما أوحى الله إليه، فقوله: لا يدخل الجنةَ قتَّاتٌ يعني: نمَّامٌ، وما أشبهه، مثل: لا يزني الزاني حين يزني وهو مؤمن، ولا يسرق السارقُ حين يسرق وهو مؤمن، ولا يشرب الخمر حين يشربها وهو مؤمن، وما أشبه ذلك من الوعيد، كله للتَّحذير من هذه المعاصي.\nوقد تأوَّلها العلماء، معناها: لا يدخل الجنةَ، يعني: مع أول الدَّاخلين، أو: حتى يتوب، فليس معناها أنه لن يدخلها بالكلية؛ لأنَّ الرسول أخبرنا أنَّ الموحد يدخل الجنةَ، وأن أهل السيئات قد يُعذَّبون ثم بعد التَّطهير يُخرجهم الله من النار إلى الجنة، وقد يُعفى عنهم كما قال جلَّ وعلا: إِنَّ اللَّهَ لَا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ [النساء:48]، فالمعاصي تحت الشرك، تحت المشيئة، قد يدخلون النار ويُعذَّبون ثم يغفر الله لهم، فيُخرجهم من النار، وقد يغفر لهم قبل ذلك.\nفالنَّمام من ذلك، وهكذا جميع ما جاء من الوعيد في حرمان دخول الجنة بسبب المعاصي، مثلما ذكر الله في الزاني والقاتل، قال: وَالَّذِينَ لَا يَدْعُونَ مَعَ اللَّهِ إِلَهًا آخَرَ وَلَا يَقْتُلُونَ النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ وَلَا يَزْنُونَ وَمَنْ يَفْعَلْ ذَلِكَ يَلْقَ أَثَامًا  ۝  يُضَاعَفْ لَهُ الْعَذَابُ يَوْمَ الْقِيَامَةِ وَيَخْلُدْ فِيهِ مُهَانًا * إِلَّا مَنْ تَابَ [الفرقان:68- 70]، وقوله : وَمَنْ يَقْتُلْ مُؤْمِنًا مُتَعَمِّدًا فَجَزَاؤُهُ جَهَنَّمُ خَالِدًا فِيهَا وَغَضِبَ اللَّهُ عَلَيْهِ وَلَعَنَهُ وَأَعَدَّ لَهُ عَذَابًا عَظِيمًا [النساء:93]، وما أشبه ذلك كله من باب الوعيد، فإن تاب تاب الله عليه ودخل الجنة، وإن مات على معصيته من الخمر أو النَّمامة أو القتل أو ما أشبه ذلك فهو تحت مشيئة الله: إن شاء الله غفر له لأعماله الصَّالحة وتوحيده ودخل الجنة، كما يفعل في بعضهم، وإن شاء أدخله النار وعذَّبه فيها على قدر المعاصي التي مات عليها ولم يتب، ثم يُخرجه الله من النار بإجماع أهل السنة: أنهم يخرجون من النار، أهل التوحيد إذا عُذِّبوا بمعاصيهم لا يُخلَّدون، لكن قد تطول مدّتهم ويُسمَّى: خلودًا، طول المدة يُسمَّى: خلودًا، كما قال: وَيَخْلُدْ فِيهِ مُهَانًا [الفرقان:69]، طول المدة يُسمَّى: خلودًا، لكن ليس مثل خلود الكفَّار، العاصي قد يخلد، لكن خلود ليس مثل خلود الكفار، خلود الكفَّار لا نهايةَ له، أبد الآباد، أما خلود العاصي فقد يطول ثم يُخرجه الله من النار، كما أخبر عن القاتل أنه يخلد، والزاني، لكن لا يدوم، بل له نهاية، ثم يُخرجه الله من النار.\nهذا قول أهل السنة والجماعة، خلافًا للخوارج والمعتزلة ومَن سار في ركابهم، فإنهم يقولون: إنه إذا دخل النارَ لا يخرج منها، وتقول الخوارج: إنه كافر، الزاني كافر عندهم، والسارق كافر، والنمام كافر. هذا قولٌ باطلٌ عند أهل السنة والجماعة، ليس بكافرٍ إذا لم يستحلَّها، العاصي ما استحلَّها؛ ليس بكافرٍ، ولكنه تحت مشيئة الله إذا لم يتب عند أهل السنة والجماعة قاطبةً، ولا يخلد في النار إذا دخلها وهو مُوحِّد لم يُشرك، لا يخلد في النار، بل له نهاية، يُخرجه الله من النار إلى الجنة بفضله ورحمته  بإجماع أهل السنة والجماعة، خلافًا للخوارج والمعتزلة ومَن سلك مسلكهم من الإباضية وغيرهم ممن سلك مسلك المعتزلة.\n س: يذكر يا شيخ عن ابن القيم: أن نار العُصاة من المُوحِّدين تفنى؟\nالشيخ: هذا صرَّح به في \"الوابل\"، والله أعلم، لكن على حال الموحد، لا يخلد، له نهاية، سواء فنيت ناره أو ما فنيت ناره، إن فنيت فربُّك على كل شيءٍ قدير، وإن لم تفنَ زِيدت في عذاب الكفار، وأضيفت إلى عذاب الكفار، إن جاء نصٌّ بأنها تفنى، وإلا فالأصل عدم الفناء، لكن إن جاء نصٌّ يدل على أنها تفنى فنعم، وإلا فقول العالم قد يُخطئ ويُصيب، فإن جاء نصٌّ أنها تفنى قلنا به، وإلا فهي تبقى، يخرج منها وتُضاف إلى بقية النار، إلى عذاب الكفَّار -نسأل الله السلامة.","link":"https://binbaz.org.sa/fatwas/21309/معنى-الوعيد-في-لا-يدخل-الجنة-نمام-ونحوه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1052ماهو تفسير حديث لا يدخل الجنة نمام وقد يكون مات على التوحيد؟ ابن باز.mp3","categories":["شروح الحديث"]},{"id":1246,"question":"ما حكم التَّوسل بجاه النبي ﷺ، علمًا بأن أخي يقول: إن شيخ الإسلام ابن تيمية وشيخ الإسلام محمد بن عبدالوهاب وسماحة الشيخ عبدالعزيز بن باز يقولون بأنها مسألةٌ خلافيةٌ بين أهل العلم، والراجح أنه مكروه كراهة تنزيهٍ؟ فما قول فضيلتكم في هذا الأمر وجزاكم الله خيرًا؟","title":"ما حكم التوسل بجاه الأنبياء؟","answer":"الجواب:\nالتَّوسل بجاه النبي ﷺ، وبجاه الأنبياء، أو بحقِّ النبي، أو بحقِّ الأنبياء؛ بدعة في الدعاء، ومنكر لا يجوز، وهذا الذي قاله جمهورُ أهل العلم، وهو قول شيخ الإسلام ابن تيمية وابن القيم وأئمَّة الدعوة، كالشيخ محمد بن عبدالوهاب وغيرهم؛ لأنَّ الرسول ما كان يُعلِّم الناسَ هذا، يقول الله: وَلِلَّهِ الْأَسْمَاءُ الْحُسْنَى فَادْعُوهُ بِهَا [الأعراف:180]، ما قال: فادعوه بجاه فلان، أو بحقِّ فلان، قال: فَادْعُوهُ بِهَا.\nوالرسول كان يدعو الله بأسمائه، يقول للصديق لما قال: يا رسول الله، علمني دعاء أدعو به في صلاتي، قال: قل: اللهم إني ظلمتُ نفسي ظلمًا كثيرًا، ولا يغفر الذنوبَ إلا أنت، فاغفر لي مغفرةً من عندك وارحمني، إنَّك أنت الغفور الرحيم، ما قال: ادعُ الله بجاهي.\nوالحديث الذي يقول: توسَّلوا بجاهي، فإنَّ جاهي عند الله عظيم هذا موضوعٌ، أجمع العلماء على أنه موضوعٌ مكذوبٌ عن النبي ﷺ.\nوقال لمعاذٍ: يا معاذ، والله إني لأحبُّك، لا تدعنَّ أن تقول دبر كل صلاةٍ: اللهم أعني على ذكرك وشُكرك وحُسن عبادتك، ما قال: بجاه نبيك، أو بحقِّ نبيك، فالدعاء عبادة، والوسائل عبادة، لا بد فيها من دليلٍ: قال الله، وقال رسوله.\nيُروى عن بعض العلماء أنَّهم أجازوا ذلك، واحتجُّوا بحديث الأعمى، قالوا: إنَّ الأعمى علَّمه النبيُّ لما شكى، علَّمه النبيُّ ﷺ قال: توضأ وصلِّ ركعتين، ثم قل: اللهم إني أسألك وأتوجه إليك بنبيك محمدٍ نبي الرحمة، اللهم إني أتوجه إليك بنبيك في حاجتي هذه أن تُقضى، اللهم شفِّعه فيَّ، وشفعني فيه، قال بعضُهم: وذكره بعضُهم عن العز ابن عبدالسلام، أنَّ هذا يدل على التوسل بالنبي خاصَّةً.\nقال العلماء: الجواب عن هذا أن هذا توسّل بدعائه؛ لأنه حيٌّ، أمره أن يدعوه، هذا توسّل بدعاء النبي، ولهذا قال: اللهم شفّعه فيَّ، فقوله: اللهم إني أتوجه إليك وأتوسّل بنبيك محمدٍ يعني: بدعائه لي وشفاعته لي، ثم قال: اللهم شفّعه فيَّ، وشفعني فيه يعني: اللهم اقبل دعاءه فيَّ، ودعائي فيه، ولم يقل للناس: ادعوا الله بشفاعتي، بجاهي، أو بحقِّي، لا، بل يُدعى الربُّ بأسمائه وصفاته وبالأعمال الصَّالحة، كأن تقول: \"اللهم إني أسألك بمحبتي لك، أو بمحبتي لنبيك ﷺ، أو باتباعي لنبيك محمد ﷺ\"، هذا طيبٌ، توسل بالأعمال أو بالصفات: \"اللهم إني أسألك بعلمك الغيب، بمحبتك، بكرمك، بجودك\"، توسل بصفات الله، أو بأسمائه، كله حقٌّ.\nفالتوسل بأسماء الله وصفاته وتوحيده وبالأعمال الصَّالحة كله حقٌّ، كما قال تعالى: وَلِلَّهِ الْأَسْمَاءُ الْحُسْنَى فَادْعُوهُ بِهَا [الأعراف:180]، وعلم الصديق يقول: اللهم إني ظلمتُ نفسي ظلمًا كثيرًا، ولا يغفر الذنوبَ إلا أنت، فاغفر لي مغفرةً من عندك، وارحمني، إنك أنت الغفور الرحيم، هذا توسّل بأسماء الله وصفاته، وهكذا في الحديث: اللهم إني أسألك بأني أشهد أنَّك أنت الله لا إله إلا أنت، الأحد الصمد، الذي لم يلد ولم يولد، ولم يكن له كفوًا أحد، هذا توسل بصفات الله وتوحيده، كله حقٌّ.\nوهكذا أصحاب الغار الثلاثة الذين أخبر عنهم النبيُّ ﷺ في \"الصحيحين\" أنهم آواهم المبيت، وفي لفظٍ: المطر إلى غارٍ، جاؤوا إلى غارٍ في الليل بسبب المبيت والمطر، فدخلوا فيه، فانحدرت عليهم صخرةٌ عظيمةٌ سُدَّت الغارَ، فما استطاعوا أن يخرجوا ولا أن يدفعوها، فقالوا فيما بينهم: لن يُنجيكم من هذه المصيبة إلا أن تدعوا الله بصالح أعمالكم، فقال أحدُهم: اللهم إنه كان لي أبوان شيخان كبيران، وكنتُ لا أغبق قبلهما أهلًا ولا مالًا، يعني: اللبن الحليب، الغبوق: لبن يشربونه بعد العشاء، فنأى بي طلبُ الشجر ذات ليلةٍ، فلم أرح عليهما إلا وقد ناما -صيف عليهم- فوقفتُ بالقدح على يدي أنتظر استيقاظهما، وكرهتُ أن أُوقظهما، والصِّبية يتضاغون تحت قدمي –يعني: يُريدون الشراب- فلم أزل أنتظرهما حتى برق الصبحُ، اللهم إن كنت تعلم أني فعلتُ ذلك ابتغاء وجهك فافرج عنا ما نحن فيه، فانفرجت الصَّخرةُ بعض الشيء، لكن لا يستطيعون الخروج.\nثم قال الثاني: اللهم إنه كانت لي ابنةُ عمٍّ كنتُ أحبها كأشدّ ما يُحب الرجال النساء، فطلبتُها لنفسي، فاعتذرت عليَّ، طلبها للزنا فأبت، فألمت بها حاجةٌ –يعني: فقرًا- فجاءت إليه تقول: يا عبدالله، أعطني كذا وكذا، أنا محتاجة، فقال: لا، حتى تُمكنيني من نفسك، فعند الضَّرورة وافقت على أن يُعطيها مئةً وعشرين دينارًا، مئة جنيه وعشرين جنيهًا ذهبًا حتى تُمكّنه من نفسها، ففعل، فلما جلس بين رجليها قالت: يا عبدالله، اتَّق الله ولا تفضّ الخاتم إلا بحقِّه، فخاف الرجلُ وقام وتركها وذهبها، ولم يُجامعها، ثم قال: اللهم إن كنتَ تعلم أني فعلتُ هذا ابتغاء وجهك فافرج عنا ما نحن فيه، فانفرجت الصخرةُ بعض الشيء، لكن لا يستطيعون الخروج.\nفقال الثالث: اللهم إنه كان لي أُجراء، فأعطيتُ كلَّ أجيرٍ حقَّه، إلا أجيرًا واحدًا ترك عندي حقَّه، فثمرته له، واشتريتُ منه إبلًا وبقرًا وغنمًا ورقيقًا، ثم جاء يطلب حقَّه فقلتُ: كل هذا من حقِّك، هذه الإبل، وهذا البقر، وهذه الغنم، وهذا الرقيق؛ كله من حقِّك، وحقّه كان أرزًا أو ذرةً، شيء من طعامٍ، فباعه وثَمَّره هذا حقّك، فساقه كلَّه ولم يدع منه شيئًا، اللهم إن كنتَ تعلم أني فعلتُ هذا ابتغاء وجهك فافرج عنا ما نحن فيه، فانفرجت الصخرةُ وخرجوا.\nهذه من آيات الله، أراهم الله العبرة، ودعوا ربَّهم بهذه الأعمال الصَّالحة، فهذا لا بأس به، التوسل إلى الله بأعمالك الصَّالحة: بتوحيد الله، بأسمائه وصفاته، بمحبَّتك له؛ لأنَّ هذا عملٌ صالحٌ، المحبَّة لنبيه والمؤمنين عملٌ صالحٌ، هذا لا بأس، أما بالجاه والحقّ: بجاه فلان، أو بحق فلان، فهذا ليس وسيلةً، بل هذا بدعة، لا يجوز التَّوسل بها على الصحيح الذي عليه جمهورُ أهل العلم.\nوالله ولي التوفيق.","link":"https://binbaz.org.sa/fatwas/21308/ما-حكم-التوسل-بجاه-الانبياء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1051ما حكم التوسل بجاه النبي صلى الله عليه وسلم؟ ابن باز فتاوى.mp3","categories":["شروح الحديث","التوسل والشفاعة"]},{"id":1260,"question":"كيف نُوفِّق بين قول الله تعالى: إِنَّ اللَّهَ لَا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ [النساء:48]، وبين قول النبي ﷺ: أبى الله أن يجعل لقاتل المؤمن توبةً؟","title":"هل صح حديثٌ في نفي توبة قاتل المؤمن؟","answer":"الجواب:\nالحمد لله، وصلَّى الله وسلَّم على رسول الله، وعلى آله وأصحابه.\nأما بعد: فقد أجمع العلماء رحمهم الله على أنَّ جميع الذنوب تصحّ التوبة منها، حتى الشرك الذي هو أعظم الذنوب قَبِلَ اللهُ توبةَ أهله، لما أسلموا وتابوا تاب اللهُ عليهم، قال تعالى في سورة الزمر: قُلْ يَا عِبَادِيَ الَّذِينَ أَسْرَفُوا عَلَى أَنْفُسِهِمْ لَا تَقْنَطُوا مِنْ رَحْمَةِ اللَّهِ إِنَّ اللَّهَ يَغْفِرُ الذُّنُوبَ جَمِيعًا إِنَّهُ هُوَ الْغَفُورُ الرَّحِيمُ [الزمر:53]، أخبر سبحانه أنه يغفر الذنوب جميعًا –يعني: للتَّائبين- أجمع أهلُ العلم على أنَّ هذه الآية في التَّائبين، وأن الذنوب كلها تُغفر: الشرك وما دونه، حتى سبّ الأنبياء، وحتى سبّ الله، مَن تاب؛ تاب الله عليه.\nفالقتل دون ذلك، القتل دون الشرك، وقد نصَّ القرآنُ على توبة القاتل، قال تعالى: وَالَّذِينَ لَا يَدْعُونَ مَعَ اللَّهِ إِلَهًا آخَرَ وَلَا يَقْتُلُونَ النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ وَلَا يَزْنُونَ وَمَنْ يَفْعَلْ ذَلِكَ يَلْقَ أَثَامًا  ۝  يُضَاعَفْ لَهُ الْعَذَابُ يَوْمَ الْقِيَامَةِ وَيَخْلُدْ فِيهِ مُهَانًا  ۝  إِلَّا مَنْ تَابَ [الفرقان:68-70]، هذا نصُّ القرآن: إِلَّا مَنْ تَابَ وَآمَنَ وَعَمِلَ عَمَلًا صَالِحًا، هذا يدخل فيه المشرك والقاتل والزاني بنصّ القرآن.\nأما الحديث: فهذا غير صحيحٍ: أبى الله أن يقبل التوبةَ من القاتل هذا ليس بصحيحٍ، إنما يُروى عن ابن عباس، وابن عباس في هذا غلَّطه العلماء، والصواب أنَّ القاتل مثل غيره تُقبل توبته، والقول بأنه لا تُقبل توبة القاتل قولٌ غلطٌ مرجوحٌ مخالفٌ للأدلة الصَّحيحة، وإن كان ابنُ عباسٍ  معروفَ المنزلة في العلم، وترجمان القرآن، وحبر الأمة، لكن ليس معصومًا، له أقوال خالف فيها غيرَه، والدليل مع غيره، منها هذه المسألة، وإنما قال ذلك للتَّغليظ على القاتل، ولكن التَّغليظ على القاتل ما يكون إلا بالشرع، لا بغير الشرع، فالقاتل إذا تاب؛ تاب الله عليه، كالكافر من باب أوْلى.\nلكن هنا نقطة في القاتل ينبغي التَّنبه لها، وهي: أنَّ حقَّ القتيل لا يضيع، حق الورثة يحصل لهم بالقصاص، أو بالدية إذا سمحوا بالدية، وحقّ الله سقط بالتوبة، وحقّ القتيل لا يضيع، يُرضيه الله عنه يوم القيامة، إذا تاب القاتلُ أرضَى اللهُ القتيلَ من فضله ، لا يضيع حقّه.","link":"https://binbaz.org.sa/fatwas/21314/هل-صح-حديث-في-نفي-توبة-قاتل-المومن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1057كيف نوفق بين قوله أن الله لايغفر أن يشرك به وبين قول النبي أبى الله آن يجعل لقاتل المؤمن توبة.mp3","categories":["التفسير","شروح الحديث"]},{"id":1261,"question":"كيف نُفسر قول النبي ﷺ «صلة الرحم تُطيل العمر»؟","title":"ما معنى أن صلة الرحم تُطيل العمر؟","answer":"الجواب:\nيعني: لأسباب؛ برّ الوالدين، وصلة الرحم، كل ذلك من أسباب البسط في الأجل، كما في الحديث: لا يزيدُ في العمرِ إلا البرُّ، مَن أحبَّ أن يُبسط له في رزقه، وأن يُنسأ له في أجله؛ فليصل رحمه؛ فصلة الرحم وبرّ الوالدين من أسباب طول العمر. الله قدَّر أشياء بأسبابها، فجعل سبحانه البرَّ والصلةَ من أسباب طول العمر، وجعل القطيعة والعقوق من أسباب قِصَر العمر، وله الحكمة البالغة سبحانه وتعالى، وقد يقع لبعض الناس قِصَر العمر لأسبابٍ أخرى.","link":"https://binbaz.org.sa/fatwas/21313/ما-معنى-ان-صلة-الرحم-تطيل-العمر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1056كيف نفسر قول النبي صلى الله عليه وسلم صلة الرحم تطيل العمر؟ ابن باز.mp3","categories":["شروح الحديث"]},{"id":1262,"question":"كيف نُوفق بين قول الله تعالى: وَاللَّهُ يَعْصِمُكَ مِنَ النَّاسِ [المائدة:67]، وما ورد أنَّ النبي ﷺ مات من أثر السّم الذي وضعته له امرأةٌ يهوديةٌ؟ وما المقصود بعصمة الله تعالى له عليه الصلاة والسلام من الناس؟","title":"معنى قوله تعالى: {وَاللَّهُ يَعْصِمُكَ مِنَ النَّاسِ}","answer":"الجواب:\nكلمة مجملة: وَاللَّهُ يَعْصِمُكَ مِنَ النَّاسِ مجملة، قد عصمه سبحانه حتى بلَّغ الرسالة؛ لأن قبلها: يَا أَيُّهَا الرَّسُولُ بَلِّغْ مَا أُنْزِلَ إِلَيْكَ مِنْ رَبِّكَ وَإِنْ لَمْ تَفْعَلْ فَمَا بَلَّغْتَ رِسَالَتَهُ وَاللَّهُ يَعْصِمُكَ مِنَ النَّاسِ، فالمعنى: بلِّغ، والله يعصمك؛ حتى لا تضل في بلاغك.  وهو ﷺ معصومٌ فيما بلَّغه عن الله بإجماع المسلمين، وليس معصومًا أنه لا يُصيبه مرضٌ، كل الأنبياء يمرضون، وليس معصومًا ما يتعدَّى عليه أحدٌ، قد أُوذي في أحدٍ، وجُرح في أحدٍ عليه الصلاة والسلام، وكُسرت البيضة على رأسه، وآذاه المشركون في مكة، لكن يعصمه حتى يُبلِّغ رسالة ربِّه، حتى لا يكتم منها شيئًا، حتى لا يُمنع من ذلك، وقد بلَّغ الرسالة، وأدَّى الأمانة، وعصمه الله حتى بلَّغ الرسالة.  وليس معنى يَعْصِمُكَ: لا يُؤذيك أحدٌ، ولا يتعدَّى عليك أحدٌ، ولا تمرض، لا، العصمة معناها ما بيَّنتها الآيةُ الكريمة؛ لأنها بعد قوله: يَا أَيُّهَا الرَّسُولُ بَلِّغْ مَا أُنْزِلَ إِلَيْكَ مِنْ رَبِّكَ، فقد بلَّغ الرسالة، وعصمه من الناس، فلم يُقتل ولم يمت حتى بلَّغ الرسالة عليه الصلاة والسلام، وإن تعدَّى عليه الناسُ في مكة، وإن تعدّوا عليه في أُحدٍ، وإن تعدّوا عليه في غير ذلك، لكن الله عصمه حتى بلَّغ، وقد مرض ومات مريضًا عليه الصلاة والسلام، وقد آذاه المشركون، لم يُعصم منهم، وقد آذوه يوم أحد، وآذوه في مواضع كثيرة عليه الصلاة والسلام، وآذوا الرسل.","link":"https://binbaz.org.sa/fatwas/21312/معنى-قوله-تعالى-والله-يعصمك-من-الناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1055كيف التوفيق بين قوله والله يعصمك من الناس وما ورد أن النبي مات من أثر سم.mp3","categories":["التفسير","شروح الحديث"]},{"id":1293,"question":"ورد في \"صحيح مسلم\" في الفتن: عن جابرٍ  قال: يوشِك ألا يُجبى إلى العراق قفيزٌ ولا درهمٌ، قلنا: مما ذاك؟ قال: من العجم، يمنعون ذاك، فهل في هذا إشارة إلى هذا الحصار الاقتصادي المضروب على العراق اليوم؟ أفيدونا جزاكم الله خيرًا.","title":"معنى حديث \"يوشِك ألا يُجبى إلى العراق..\"","answer":"الجواب:\nالشيخ: هذا مضى له أشياء كثيرة، هذا له دهرٌ طويلٌ، ومنعت العراقُ قفيزها، ومنعت الشام درهمها ودينارها، مضى، قد منعوه عن المدينة وعن مكة وعن الجزيرة، وقد يمنعون منه أيضًا هم عن غيرهم من قواتٍ أخرى من أهل الكفر، ولا يمنع أن يكون هذا داخلًا في ذلك، لا مانع أن يكون داخلًا في ذلك، والله أعلم، لكن الحصار هذا شديد، يمنع العراق من درهمها وقفيزها وسائر ما عندها، ويمنع غيرهم من إيصال الخير إليهم أيضًا، هو نوعٌ مما يدخل في الحديث.","link":"https://binbaz.org.sa/fatwas/21352/معنى-حديث-يوشك-الا-يجبى-الى-العراق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1095ورد في صحيح مسلم يوشك الاَّ يجبى إلى العراق قطيف ولا درهم فهل هذا أشارة إلى الحصار.mp3","categories":["شروح الحديث"]},{"id":1303,"question":"يقول السائلُ: قول النبي ﷺ: أربع يُسأل عنها ابن آدم يوم القيامة: عن علمه ماذا عمل فيه؟ هل المقصود أي علمٍ تلقَّاه يجب عليه أن يذكره، أم أنه لا يُطالب إلا بما يُسأل عنه؟","title":"ما معنى \"عن علمه ماذا عمل به\" في الحديث","answer":"الجواب:\nعن علمه الذي علمه فيما يتعلَّق بما أوجب الله عليه، وما حرَّم الله عليه، هل نفذ أو ما نفذ؟ أما العلوم الأخرى التي ما تتعلق بالتَّكليف ما يضرُّه إذا كانت مباحةً: علم النِّجارة، وعلم الخرازة، ما يُسأل عنها، إلا إذا كان قصَّر فيه، إذا كان خان في خرازته، خان في نجارته، يُسأل عن ذلك، هذه معصية، أما كونه ما خان في ذلك -يكتسب بالنِّجارة والحدادة ونحو ذلك- فهذا لا له ولا عليه، مباح.  لكن إذا قصد بها خيرًا وأدَّى الأمانة كان له أجرٌ، وإذا خان صار عليه وزرٌ، لكن علمه الشرعي هل عمل به؟ هل أدَّى ما أوجب الله؟ هل ترك ما حرَّم الله أو قصَّر في ذلك؟","link":"https://binbaz.org.sa/fatwas/21366/ما-معنى-عن-علمه-ماذا-عمل-به-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1109ما هو مقصود قول النبي صلى الله عليه وسلم عن علم ماذا عمل به؟.mp3","categories":["شروح الحديث"]},{"id":1304,"question":"ورد في الحديث في أوصاف الذين يدخلون الجنةَ بغير حسابٍ، قال: هم الذين لا يرقون –أو: لا يسترقون- ولا يتطيَّرون، وعلى ربهم يتوكَّلون، فهل من الممكن أن تشرح لنا هذه الأوصاف؟","title":"معنى \"لا يَسْتَرْقُون ولا يَكْتَوُون\" في الحديث","answer":"الجواب:\nنعم، نعم، لا يَسْتَرْقُون، ولا يَكْتَوُون يعني: أنهم يتركون الحاجة إلى الناس في طلب الاسترقاء، إذا استغنوا عن ذلك، إذا لم يكن لهم حاجة، وهكذا الكي.  أما إذا احتاجوا فلا بأس، النبي ﷺ كوى بعضَ أصحابه وقال: الشِّفاء في ثلاثة: كَيَّة نار، وشَرْطَة مِحْجَم، وشربة عسل، وما أحب أن أكتوي، وفي لفظٍ: وأنا أنهى أمتي عن الكيّ، فالمعنى: أنَّ هذا أفضل، ترك الكي والاسترقاء أفضل، إلا عند الحاجة.\nوأمر عائشة وأسماء بنت عميس أن تسترقي للأولاد الذين أصابتهم العين، فالاسترقاء عند الحاجة لا بأس به، لكن إذا استُغني عن هذا بدواءٍ آخر وعلاجٍ آخر فهو أوْلى من سؤال الناس الاسترقاء -سؤال الناس أن يرقوه-. والكي معروفٌ، الكي بالنار معروفٌ.\nأما رواية: لا يَرْقُون ذكر المحققون أنَّها وهمٌ وغلطٌ، وإنما المحفوظ: لا يسترقون، وورد في رواية مسلم: لا يرقون، ولكنَّها رواية غلط من بعض الرواة، كما قال شيخُ الإسلام ابن تيمية رحمه الله وجماعة: أنها غلط؛ لأنَّ الرسول رقى ورُقِيَ عليه الصلاة والسلام، وحثَّ على الرقية قال: مَنِ اسْتَطَاعَ مِنكُم أَنْ يَنْفَعَ أَخَاهُ فَلْيَنْفَعْهُ، فالرُّقية مطلوبةٌ ومشروعةٌ ومأمورٌ بها.","link":"https://binbaz.org.sa/fatwas/21365/معنى-لا-يسترقون-ولا-يكتوون-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1108ما معنى قول النبي صلى الله عليه وسلم لايسترقون ولايكتوون؟ابن باز فتاوى.mp3","categories":["شروح الحديث","الرقى والتمائم"]},{"id":1314,"question":"ورد في حديثٍ أن لله ملائكةً سيَّارةً تسير في الأرض، تحفّ الجماعة الذين يذكرون الله، يقول بأنَّ بعض الصوفية يستدلون بهذا الحديث على بعض أعمالهم، فكيف نردّ عليهم؟","title":"معنى \"إن لله ملائكة سيَّاحين..\" في الحديث","answer":"الجواب:\nهذا الحديث صحيحٌ: إنَّ لله ملائكةً سيَّاحين، يلتمسون مجالسَ الذكر، فإذا وجدوها تنادوا: هلموا إلى حاجاتكم، فيحفّونهم إلى عنان السماء، ويسمعون منهم أذكارهم وأعمالهم الطيبة، ثم إذا عرجوا سألهم الله عمَّا وجدوا -وهو أعلم - فيُخبرونه بما شاهدوا.\nولا حجَّة في هذا للصوفية، الصوفية مُبتدعة، عليهم أن يلزموا الشريعة، ويستقيموا عليها، وإذا ذَكَروا الله كما يذكر الله المسلمون فطيبٌ، أما وجود الملائكة عند الذاكرين الله فما هو بحجَّة للصوفية في اختراعهم بدعًا ما أنزل الله بها من سلطانٍ، عبادات ما شرعها الله، أو عبادات لأهل القبور وأصحاب القبور، أو ما أشبه ذلك مما اخترعوه من الطرق الباطلة، فالملائكة يحضرون مجالسَ الذكر، ومجالس العلم، ويستفيدون.\nوهناك ملائكة آخرون يُبلِّغون النبيَّ ﷺ الصلاةَ والسلامَ عليه، عليه الصلاة والسلام، وفي الحديث الآخر: إنَّ لله ملائكةً سيَّاحين يُبلغوني عن أمتي الصلاة والسلام عليه الصلاة والسلام، ولله ملائكة يتّبعون مجالسَ الذكر، ويسمعون مجالسَ الذكر، ويحفّونها.","link":"https://binbaz.org.sa/fatwas/21355/معنى-ان-لله-ملاىكة-سياحين-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1098جاء في الحديث أن لله ملائكة سيارة الصوفية يستدلون بهذا الحديث على بعض أعمالهم.mp3","categories":["شروح الحديث"]},{"id":1325,"question":"الحديث الآخر: فَهُمَا في الوِزْر سواء؟","title":"معنى \"فَهُمَا في الوِزْر سواء\" في الحديث","answer":"الجواب:\nهذا شيء آخر أراد به: الرجل الذي كان له مال يعمل فيه بمعاصي الله، وقال الآخر: لو كان لي مِثل فلان لعملت مِثل عمله فهما في الوزر سواء. نسأل الله العافية. والثاني: اللي هو يعمل، أعطاه القرآن وأعطاه الحكمة، فقال الآخر: لو أن لي مِثله لعملت مِثل عمله، فهما في الأجر سواء.","link":"https://binbaz.org.sa/fatwas/21416/معنى-فهما-في-الوزر-سواء-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى فهما في الوزر سواء في الحديث.mp3","categories":["شروح الحديث"]},{"id":1327,"question":"معنى: لو أقْسَم على الله لأبَرَّه؟","title":"معنى حديث \"لو أقْسَم على الله لأبَرَّه\"","answer":"الجواب:\nفي من عباد الله يقول: والله أن هذا سيكون، ويُبِرُّ قَسَمَه، ويقع ما يقال.  لكن ما ينبغي للإنسان أن يقسم على الله؛ لأن هذا فيه شيء من الجُرأة.  ولكن بعض الناس لإيمانه وتقواه لو أقْسَم على الله لأبَرَّه، لكنْ تَرْك الإقسام على الله أوْلى، أحوْط.","link":"https://binbaz.org.sa/fatwas/21418/معنى-حديث-لو-اقسم-على-الله-لابره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى لو أقسم على الله لأبره.mp3","categories":["شروح الحديث"]},{"id":1341,"question":"قول الرسول ﷺ: ما يصيب المسلم من نَصَب.. يدخل فيها أهل الكبائر؟","title":"هل التكفير بما يصيب المسلم يَعُمُّ أهل الكبائر؟","answer":"الجواب:\nيدخلون، كل مسلم داخل؛ النَّصَب: التعب، والوَصب: المرض.\nس: الذين يستمعون للأغاني ويعق والديه ويأكل ربا ويجد في صدره همًّا وغمًّا هل يدخل في هذا؟\nج: نعم، هم وغم من جهة المصائب هذه يُرَجَى له خير، لعل الله يَمُنّ عليه بالتوبة.....","link":"https://binbaz.org.sa/fatwas/21432/هل-التكفير-بما-يصيب-المسلم-يعم-اهل-الكباىر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما يصيب المسلم من نصب.. هل يدخل فيه أهل الكبائر.mp3","categories":["شروح الحديث"]},{"id":1343,"question":"قوله: فمن رضي المراد به الصبر أو الرضا ؟","title":"معنى حديث \"فمن رَضِي فله الرِّضا\"","answer":"الجواب:\nالمراتب أربع: صبر. ورضا. وشكر. فالصبر واجب، والرضا مستحب أن يرضى ولا يكره المصيبة؛ لما يترتب عليها من الخير.  والمرتبة الرابعة: يَعُدُّها نعمة يشكر الله عليها أن أصيب بكذا وكذا؛ حتى تُخفف عنه الخطايا وتُمحى عنه السيئات. وهذه درجات مختلفة للمؤمنين، لكن أهمها الصبر.","link":"https://binbaz.org.sa/fatwas/21434/معنى-حديث-فمن-رضي-فله-الرضا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المراد بقوله في الحديث فمن رضي الرضا أم الصبر.mp3","categories":["شروح الحديث"]},{"id":1344,"question":"لا يخاف إلا الله والذئب على غنمه؟","title":"معنى \"لا يخاف إلا الله والذئب على غنمه\"","answer":"الجواب:\n... أخبر أنه يحصل الأمن حتى يسير الراكب المسافة الطويلة لا يخاف إلا الله من صنعاء إلى حضرموت، ومن المدينة إلى العراق، ومن العراق إلى مكة، لا يخاف إلا الله والذئب... هذا ما هو التعلق بمسألة الحلف بالله وفلان، يخاف هذا ويخاف هذا، مثلما في قوله ﷺ: ثلاث من كن فيه وجد بهن حلاوة الإيمان أن يكون الله ورسوله أحب إليه مما سواهما، وكذلك حتى يُحِبَّكم للهِ ولِقَرابَتي يعني: حتى يجمع بين الأمرين.","link":"https://binbaz.org.sa/fatwas/21435/معنى-لا-يخاف-الا-الله-والذىب-على-غنمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/لا يخاف إلا الله والذئب على غنمه.mp3","categories":["شروح الحديث"]},{"id":1348,"question":"حديث أبي هريرة : ما يزال البلاء بالمؤمن..  يدل أنه ما يقع بلاءٌ إلا بذنب؟","title":"هل صح أنه ما يقع بلاءٌ إلا بذنب؟","answer":"الجواب:\nالأبلغ وَمَا أَصَابَكُمْ مِنْ مُصِيبَةٍ فَبِمَا كَسَبَتْ أَيْدِيكُمْ وَيَعْفُوا عَنْ كَثِيرٍ [الشورى:30]، مَا أَصَابَكَ مِنْ حَسَنَةٍ فَمِنَ اللَّهِ وَمَا أَصَابَكَ مِنْ سَيِّئَةٍ فَمِنْ نَفْسِكَ [النساء:79]، أسبابها نفسه.","link":"https://binbaz.org.sa/fatwas/21440/هل-صح-انه-ما-يقع-بلاء-الا-بذنب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما يزال البلاء بالمؤمن هل يدل أنه ما يقع بلاء إلا بذنب.mp3","categories":["شروح الحديث"]},{"id":1364,"question":"الحديث الأخير ما شرحته وهو قوله: واعلموا أنه لن يَنْجُوَ أحد منكم بعمله؟","title":"معنى حديث \"لن يَنْجُوَ أحدٌ منكم بعمله\"","answer":"الجواب:\nتقدم، هذا هو، يعني أن العمل سبب، والله جل وعلا هو المُوَفِّق، والإنسان لا يَمُنُّ بعمله ولا يُعْجَب بعمله، بل يعمل ويكدح ويسأل ربه التوفيق والمغفرة، ولا يظن أن عمله المُنجي، قالوا: ولا أنت يا رسول الله، قال: ولا أنا إلا أن يتغمدني الله برحمة منه وفضل فالمُعَوَّل على رحمة الله وعفوه، الأعمال أسباب، والطاعات أسباب، وترك المعاصي أسباب، والتوفيق بيد الله؛ هو الذي يوفق ويُنْجِي ويرحم .","link":"https://binbaz.org.sa/fatwas/21457/معنى-حديث-لن-ينجو-احد-منكم-بعمله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/شرح حديث واعلموا أنه لن ينجو أحد منكم بعمله.mp3","categories":["شروح الحديث"]},{"id":1366,"question":"حديث أبي هريرة يقول: يُصْبِح الرجل مؤمنًا ويُمْسِي كافرًا يبيع دينه بعَرَضٍ مِن الدنيا ما معنى هذا الحديث؟","title":"معنى \"يُصْبِح الرجلُ مؤمنًا ويُمْسِي كافرًا\"","answer":"الجواب:\nيقول ﷺ: بادروا بالأعمال فتنًا كقطع الليل المظلم يقول: سارعوا بالأعمال الصالحة بادروا بها فتنًا كقطع الليل المظلم، فتن في الدين، وفتن في الأبدان، وفتن في الأموال، وفتن في المجتمع، الإنسان يحذر، يبادر بالأعمال قبل أن يُفتن، قبل أن تقع فتنة تحول بينه وبين العمل بادروا بالأعمال فتنًا كقطع الليل المظلم من اشتباهها وكثرتها وحيرة الفكر فيها، يصبح الرجل فيها مؤمنًا ويمسي كافرًا، ويمسي مؤمنًا ويصبح كافرًا يبيع دينه بعرض من الدنيا؛ لأجل اشتباهها وعدم وضوحها؛ قد يصبح مسلمًا ويمسي كافرًا مفتونًا بها، ويمسي مسلمًا ويصبح كافرًا؛ بسبب اشتباهها وكثرة ما فيها من الشرور.  وفي اللفظ الآخر: بادروا بالأعمال سبعًا هل تنتظرون إلا فقرًا مُنْسِيًا أو غِنًى مُطْغِيًا أو مرضًا مُفْسِدًا، أو هَرَمًا مُفَنِّدًا، أو موتًا مُجْهِزًا، أو الدجال، فالدجال شَرُّ غائب ينتظر، أو الساعة فالساعة أدْهى وأمَرّ فالإنسان يبادر بالأعمال ويحرص على أعمال الخير ؛ لأنه قد يبتلى بشيء يمنعه قد يموت، قد يمرض، قد يشغل، فإذا هم بالعمل الصالح فليبادر. وفق الله الجميع.\nس: فتن كقطع الليل المظلم في زماننا هذا؟\nج: لاشتباهها في زماننا وقبله وبعده.\nس: ويصبح الرجل مؤمنًا ويمسي كافرًا في زماننا؟\nج: يرتد، نعم بسبب اشتباهها، يجي واحد يقول له كذا وكذا ويوافقه على الباطل، على الردة ويرتد، يجيه واحد من أهل السنة والدعوة والخير فيسلم؛ لاشتباه الأمور.","link":"https://binbaz.org.sa/fatwas/21459/معنى-يصبح-الرجل-مومنا-ويمسي-كافرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى حديث يصبح الرجل مؤمنًا ويمسي كافرًا يبيع دينه بعرض من الدنيا.mp3","categories":["شروح الحديث"]},{"id":1368,"question":"الحديث (ولئِن سألَني لأعطينَّهُ) الصوفية يستدلون به أن الله  يَحِلُّ فيهم بسبب أنه يكون سمعهم وبصرهم؟","title":"معنى حديث \"ولئِن سألَني لأعطينَّهُ..\"","answer":"الجواب:\nهذا من جهلهم؛ تسديده قال: ولئِن سألَني لأعطينَّهُ ولئنِ استعاذني لأعيذنَّهُ معناه أنه يُوَفَّق، ولهذا في اللفظ الآخر: فبي يسمَعُ وبي يُبصِرُ وبي يبطِشُ وبي يمشي يعني: بتوفيقي وهدايتي، هذه تفسرها.  ومعلوم: سمعه قائم به وبصره قائم به ويده قائمة به، ولكن المقصود التسديد والتوفيق، هذا أمر معروف عند العرب وتوسع العرب، ولهذا جاء في الرواية الأخرى: فبي يسمع تفسير لها، ولكن الصوفية جَهَلَة وضُلَّال ما يفهمون، نسأل الله العافية.\nس:  هل الصوفيون على الكفر؟\nج: يختلفون على حسب عقائدهم، فمن اعتقد أن الشيخ يُعبد من دون الله؛ كَفَر.","link":"https://binbaz.org.sa/fatwas/21461/معنى-حديث-ولىن-سالني-لاعطينه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/استدلال الصوفية بحديث لئن سألني لأعطينه على حلول الله فيهم، والحكم على الصوفية.mp3","categories":["شروح الحديث"]},{"id":1375,"question":"كيف نجمع بين قوله جل وعلا في الحديث: كلكم ضال إلا من هديته وبين قوله في الحديث الآخر: إني خلقت عبادي حنفاء فاجتالتهم الشيطان؟","title":"معنى حديث \"كلكم ضال إلا من هديته..\"","answer":"الجواب:\nهذا على بابه، وهذا على بابه، أصلهم حنفاء، لكن بعد البلوغ الكِبَر كلهم ضال إلا من هداه الله. الأصل على الفطرة فإذا بَلَغُوا فهم على الضلال إلا من هداه، إلا من لزم الحق ووفقه الله لقبول الحق.","link":"https://binbaz.org.sa/fatwas/21468/معنى-حديث-كلكم-ضال-الا-من-هديته","audio":"undefined","categories":["شروح الحديث"]},{"id":1379,"question":"معنى حديث أنس: إن الله تابع الوحي على رسول الله ﷺ وقبل وفاته حتى تُوُفِّي أكثر ما كان الوحي؟","title":"معنى أن النبيﷺتُوُفِّي أكثر ما كان الوحي","answer":"الجواب:\nلإنهاء ما أراد الله من أمر ونهي،  تابع الوحي في آخر حياته حتى تُستكمل الشريعة وتَكْمُل الأمور المطلوبة، حتى يُتَوفَّى وقد بَلَّغ كل الرسالة ﷺ.","link":"https://binbaz.org.sa/fatwas/21472/معنى-ان-النبيﷺتوفي-اكثر-ما-كان-الوحي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى حديث إن الله تابع الوحي على رسول الله صلى الله عليه وسلم وقبل وفاته حتى توفي أكثر ما كان الوحي.mp3","categories":["شروح الحديث"]},{"id":1382,"question":"بعض الناس يقول إنه من الجمعة إلى الجمعة مكفِّرة وما بينهما ورمضان إلى رمضان؛ فتجده ما يصلي إلا الجمعة وفي رمضان بس؟","title":"معنى \"مُكَفِّراتٌ لما بينهُنَّ إذا اجْتُنِبتِ الكبائِرُ\"","answer":"الجواب:\nهذا من الجهل؛ لأن الرسول ﷺ قال: \"إذا اجتنب الكبائر\"، شرط، \"الصلوات الخمس والجمعة إلى الجمعة ورمضان إلى رمضان كفارات لما بينهما\"، والصلوات الخمس بين الجمعة يعني داخلة فيها..... هذا من الجهل العظيم، يجب أن يُنصح، التخلف عن الصلاة من أسباب الرِّدَّة، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/21475/معنى-مكفرات-لما-بينهن-اذا-اجتنبت-الكباىر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بحديث الصلوات الخمس والجمعة إلى الجمعة.mp3","categories":["شروح الحديث"]},{"id":1386,"question":"وفي بُضْع أحدكم صَدَقَة هل يُشترط لهذا النية؟","title":"هل تُشترط النية في أجر جِمَاع الرجل أهْلَه؟","answer":"الجواب:\nلا، ما هو بظاهر، ولو ما له نية، مأجور على جماع لأهله؛ لأنه من أسباب غض البصر وإحصان الفرج له ولها، قالوا: يا رسول الله أيأتي أحدنا شهوته ويكون له فيها أجر؟ قال: أرأيتم لو وضعها في حرام أكان عليه وزر؟ فهكذا إذا وضعها في الحلال كان له أجر.","link":"https://binbaz.org.sa/fatwas/21479/هل-تشترط-النية-في-اجر-جماع-الرجل-اهله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/في بضع أحدكم صدقة هل يشترط لهذا النية.mp3","categories":["شروح الحديث"]},{"id":1394,"question":"كيف نجمع بين حديث اغتنم خمسًا قبل خمس وبين أحب الأعمال إلى الله أدومها وإن قل؟","title":"ما ضابط الاجتهاد والاقتصاد في الطاعة؟","answer":"الجواب:\nما في منافاة؛ الإنسان يعمل بطاعة الله ويجتهد في العمل وإن كان قليلاً، هذا خير له من كونه تارة يعمل وتارة ما يعمل، تارة يصلي الضحى وتارة ما يصلي، تارة يوتر وتارة ما يوتر، لا، يوتر ولو بواحدة أفضل ولو كل ليلة أفضل من كونه ليلة يوتر بخمس وليلة ما يوتر، أو ليلة يوتر بسبع وليلة ما يوتر،  لا، كونه يوتر بواحدة أو ثلاث دائمًا دائمًا أفضل من كونه بعض الليالي يوتر وبعض الليالي ما يوتر.\nس: أحيانًا الإنسان يكون عنده إجازات في الخميس والجمعة فيكون عنده مجال فيزيد في صلاته؟\nج: يتزوّد في الخير طيب، بس التكلف لا يتكلف، لا يكلِّف نفسه ويتَنَطَّع.","link":"https://binbaz.org.sa/fatwas/21487/ما-ضابط-الاجتهاد-والاقتصاد-في-الطاعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الجمع بين حديث استغل خمسًا قبل خمس وبين أحب الأعمال إلى الله أدومها وإن قل.mp3","categories":["شروح الحديث"]},{"id":1397,"question":"معنى قول النبي ﷺ: يعجب الله لشاب ليس له صَبْوَةٌ؟","title":"معنى حديث \"يعجب الله لشاب ليس له صَبْوَةٌ\"","answer":"الجواب:\nيعني ما له زلات، يعني استقام على العبادة من أول شبابه، مثل حديث السبعة: سبعة يظلهم الله في ظله، ذكر منهم شاب نشأ في عبادة الله، ما له صَبْوَةٌ، ما له معاصٍ في أول شبابه، ما له جهالات.","link":"https://binbaz.org.sa/fatwas/21490/معنى-حديث-يعجب-الله-لشاب-ليس-له-صبوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى حديث يعجب الله لشاب ليس له صبوة.mp3","categories":["شروح الحديث"]},{"id":1398,"question":"السفر بالليل: تُطْوَى لمن سافر بالليل الأرض؟","title":"معنى أن \"الأرض تُطْوَى بالليل\" في الحديث","answer":"الجواب:\nيعني: يسهل الله له السير؛ لأنه في نشاط ورغبة، وينتهي من أرض كثيرة وهو لا يشعر، والأرض هي الأرض، لكن تُطوى من جهة نشاطه في السير ورغبته في السير وعدم تَمَلْمُلِه من الحر ولا الشمس.\nس: هذا اللفظ أنها تُطوى في الحديث؟\nج: إشارة إلى سرعة السير.\nس: السفر في أول الليل والنهار سُنة؟\nج: هذا أنسب للمسافر وأعون على السفر، كما قال ﷺ: اغدوا وروحوا.","link":"https://binbaz.org.sa/fatwas/21491/معنى-ان-الارض-تطوى-بالليل-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في السفر في الليل.mp3","categories":["شروح الحديث"]},{"id":1405,"question":"النفاق الذي كان يخشاه السلف هو النفاق الأكبر؟","title":"ما النفاق الذي كان يخشاه السلف؟","answer":"الجواب:\nلا، مرادهم -والله أعلم- النفاق الأصغر، الرياء، يعني هذا هو الأغلب، مثل ما قال ﷺ: أخوف ما أخاف عليكم الشرك الأصغر فسئل عنه فقال: الرياء؛ لأن الله جل وعلا يحميهم من النفاق الأكبر وقد علموا وتيقنوا والحمد لله، ولكن كون الإنسان يتظاهر بأشياء ولا يكون عليها خشوا أن يكون هذا من النفاق؛ كونه يتظاهر بأشياء ثم يخل بها هذا ما يضر، كونه يتعبد تارة ويترك تارة، يصوم تارة ويفطر تارة، يقرأ تارة ويسكت تارة، كل هذا، الحمد لله، الأمر واسع.","link":"https://binbaz.org.sa/fatwas/21498/ما-النفاق-الذي-كان-يخشاه-السلف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/النفاق الذي كان يخشاه السلف.mp3","categories":["شروح الحديث","الرياء والسمعة"]},{"id":1406,"question":"صيام الأبد نهي تحريم أم كراهة؟","title":"ما حكم صيام الدهر؟","answer":"الجواب:\nالصواب تحريمه لا صَامَ مَن صَامَ الأبَدَ الرسول ﷺ نهى عنه.","link":"https://binbaz.org.sa/fatwas/21499/ما-حكم-صيام-الدهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل النهي عن صيام الدهر للتحريم أم للكراهة.mp3","categories":["شروح الحديث","صيام التطوع"]},{"id":1411,"question":"قوله ﷺ: إنما أهلك من كان قبلكم كثرة سؤالهم يعني؟","title":"معنى \"إنما أهلك من كان قبلكم كثرة سؤالهم\"","answer":"الجواب:\nيتعنتون، يسألون أنبيائهم تعنتًا ويختلفون عليهم، الإنسان لا يسأل إلا عند حاجته، حاجته للعلم أما التعنت والتكلف لا، ولهذا قال جل وعلا: لَا تَسْأَلُوا عَنْ أَشْيَاءَ إِنْ تُبْدَ لَكُمْ تَسُؤْكُمْ.. [المائدة:101].","link":"https://binbaz.org.sa/fatwas/21506/معنى-انما-اهلك-من-كان-قبلكم-كثرة-سوالهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/شرح حديث إنما أهلك من كان قبلكم كثرة سؤالهم.mp3","categories":["شروح الحديث"]},{"id":1414,"question":"معنى قوله ﷺ في الحديث: واختلافهم على أنبيائهم؟","title":"معنى \"واختلافهم على أنبيائهم\" في الحديث","answer":"الجواب:\nيعني: مخالفتهم، الأنبياء يقولون شيئًا، وهم يقولون شيئًا آخر؛ يخالفونهم، هذا الذي أهلكهم؛ مخالفة الأنبياء.","link":"https://binbaz.org.sa/fatwas/21509/معنى-واختلافهم-على-انبياىهم-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى قوله في الحديث واختلافهم على أنبيائهم.mp3","categories":["شروح الحديث"]},{"id":1416,"question":"كل محدثة بدعة، صحيح؟","title":"معنى \"كل محدثة بدعة\" في الحديث","answer":"الجواب:\nالحديث في صحيح مسلم أيضاً فإن كل محدثة بدعة، وكل بدعة ضلالة يعني في الدين، هذا هو المراد. ما هو بأمور الأكل والشرب والعادات، لا، البدعة في الدين، الحَدَث في الدين.\nس: وهذا ثابت عن النبي ﷺ؟\nج: نعم في صحيح مسلم كان يخطبهم ويقول عليه الصلاة والسلام في خطبته: خيرُ الكلامِ كلامُ اللهِ، وخيرُ الهدي هديُ محمدٍﷺ، وشرُ الأمورِ محدثاتُها ، وكلُّ بدعةٍ ضلالةٌ.","link":"https://binbaz.org.sa/fatwas/21511/معنى-كل-محدثة-بدعة-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى كل محدثة بدعة.mp3","categories":["شروح الحديث"]},{"id":1422,"question":"(حديث إذا أكل أحدكم فلْيَلْعَق أصابعه) هل يفهم منه عدم كراهية الشبع؟ لأنه أتى على الطعام الذي في القصعة كله؟","title":"معنى ودلالة \"إذا أكل أحدكم فلْيَلْعَق أصابعه\"","answer":"الجواب:\nيجوز الشبع، لكن يخلي بقية أحسن، وإلا يجوز الشبع، في الصحيح أن الرسول ﷺ دعا أهل الصفة يومًا فاجتمعوا عنده وكانوا نحو السبعين وكان قد أهدي له لبن؛ فأمر أبا هريرة أن يمشي باللبن على الناس القدح، وكان يمر عليهم ويشربون نحو سبعين كل واحد يشرب حاجته، ثم بقي في القدح كأنه ما شرب منه أحد فقدمه أبو هريرة للنبي ﷺ، فقال له النبي ﷺ: اشرب يا أبا هريرة فشرب، ثم قال له: اشرب فشرب، ثم قال له: اشرب فشرب، ثم قال له: اشرب، فقال: والذي بعثك بالحق لا أجد له مسلكًا، ثم أخذ النبي ﷺ الفضلة وشربها عليه الصلاة والسلام. هذا يدل على علم من أعلام النبوة؛ سبعين في قدح واحد يشربون ويَرْوُون من هذا القدح، ثم يبقى بقية يَرْوَى منها أبو هريرة ويقول: لا أجد مسلكًا، ثم يبقى بقية ويشربها النبي ﷺ، من قدح واحد، هذه من آيات الله العظيمة الذي يقول للشيء كن فيكون .","link":"https://binbaz.org.sa/fatwas/21517/معنى-ودلالة-اذا-اكل-احدكم-فليلعق-اصابعه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث إذا أكل أحدكم فليلعق أصابعه، وليعلق القصعة هل يفيد بكراهية الشبع.mp3","categories":["شروح الحديث"]},{"id":1425,"question":"هل الأوْلى أنه يُبْقي في القصعة حتى ما يتم شبعه، وإلا...؟","title":"حكم لَعْق القصعة وهل يستحب عدم الشبع؟","answer":"الجواب:\nعلى حسب، يأكل من الجوانب حتى تنتهي.\nس: كثير من الناس يُبْقي نصف القصعة لا يأكلها؟\nج: يأكل منها حتى يشبع، وإذا بقي يخلي شوية ما يشبع شوي أحسن، حديث: بحسب ابن آدم لقيمات يقمن صلبه ينبغي أن يخلّي شيئًا للنَّفَس وللشراب، طيِّب.\nس: ولو فسد الطعام.....؟\nج: البقية يتصدق على الفقراء وإلا يعطيه الدواب.\nس: العلماء في الحديث اكتشفوا أن  آخر الأكل اللي يمسح بيده يساعد على هضم الطعام..... إذا لحس يده تساعد الدهون اللي تطلع من اليد على الهضم؟\nج: الله أعلم، سُنة وبس، السُّنة يلعق يده سواء هضمت وإلا ما هضمت، السُّنة يلعق يده، ما عليك من أنها تهضم وإلا ما تهضم.","link":"https://binbaz.org.sa/fatwas/21520/حكم-لعق-القصعة-وهل-يستحب-عدم-الشبع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث وليعلق القصعة، هل يجب ألا يبقي شيء في القصعة.mp3","categories":["شروح الحديث"]},{"id":1442,"question":"الحديث الذي قبله الذي يتحدث عمَّن وجدوه في النار (يُؤتى بالرجل يوم القيامة فيُلْقَى في النار..)؟","title":"جزاء من يأمر بالمعروف ولا يأتيه","answer":"الجواب:\nذاك حديث أسامة: أنه يُؤتى بالرجل يوم القيامة فيُلْقَى في النار، فتندلق أَقْتَابُ بطنه -أمعاؤه تخرج- فيدور في النار كما يدور الحمار بالرَّحَى، فيجتمع عليه أهلُ النار ويقولون: ألم تكن تأمرنا بالمعروف وتنهانا عن المنكر؟! فيقول: بلى، ولكن كنتُ آمركم بالمعروف ولا آتيه، وأنهاكم عن المنكر وآتيه! يقول: صلُّوا، وهو لا يُصلِّي، يقول: إياكم والزِّنا، وهو يزني، يقول: إياكم الخمر، وهو يشرب الخمر -نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/21538/جزاء-من-يامر-بالمعروف-ولا-ياتيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/جزاء من يأمر بالمعروف ولا يأتيه وينهى عن المنكر ويأتيه.mp3","categories":["شروح الحديث"]},{"id":1443,"question":"الشفاعة خاصَّة بأمة المسلمين، وبالنسبة لموسى وعيسى هل ما يشفعون لأُمَمِهم؟","title":"أنواع الشفاعة يوم القيامة ولمن تكون؟","answer":"الجواب:\nبلى، ولكن هذا الموقف للجميع، هذه شفاعة الموقف ودخول الجنة للجميع. وأما الشفاعة الخاصة فكل نبيٍّ له شفاعة، لكن يوم القيامة الناس يشتد بهم الأمر: ماذا يفعلون من الكرب حتى يُقْضَى بينهم؟ أول شيءٍ يذهبون إلى آدم -أبي البشر- ويُحيلهم آدمُ إلى نوحٍ، ونوحٌ يُحيلهم إلى إبراهيم، وإبراهيمُ يُحيلهم إلى موسى، وموسى يُحيلهم إلى عيسى، وعيسى يُحيلهم إلى النبي ﷺ، فيتقدَّم ويشفع في أهل الموقف حتى يُقْضَى بينهم.\nالشفاعة الثانية العظيمة تكون في الجنة، فإذا انتهى الحسابُ وبقي دخول أهل الجنة الجنة؛ فإنهم كذلك يطلبون الشفاعة –أهل الجنة- في أن يُوَجَّهوا إلى الجنة، وأن تُفْتَح أبوابها لإظهار شأنهم ووضعهم، فيأتون آدم، ثم نوحًا، ثم إبراهيم .. إلى آخره، فتنتهي إلى النبي ﷺ، ويشفع لهم في دخولهم الجنة.\nس: النبي الذي يأتي وحده يوم القيامة هل له شفاعة؟\nج: ما تبعه أحدٌ -نسأل الله السلامة- الذي مات أو قتلوه ما في شفاعة، كفَّارٌ كلهم.\nس: بالنسبة لشفاعة النبي ﷺ لأهل النار: هل يدخل فيها الأممُ الباقية؟\nج: عُصاة أمته فقط.\nس: أمته فقط؟\nج: نعم أمته.\nس: وبقية الأنبياء يشفعون أيضًا؟\nج: نعم يشفعون لأممهم، والأخيار، والمؤمنون، والملائكة.\nس: بالنسبة للشفاعة الأولى أوَّلًا يبدأ بها النبيُّ ﷺ؟\nج: نعم في أهل الموقف حتى يُقْضَى بينهم، ثم في أهل الجنة حتى يدخلوها، ثم بعد ذلك فيمَن دخل النار أن  يُخرج منها –العُصاة- فيشفع شفاعات عديدة. س: الحوض قبل الصراط؟\nج: الحوض قبل الصراط وقبل الحساب والجزاء، يرده الناسُ يوم القيامة وهم ظِمَاء.\nس: بالنسبة للشفاعة الأولى هل يشترك بقيةُ الأنبياء مع نبينا محمدٍ؟\nج: لا، وحده، هو الذي يسجد تحت العرش، ثم يحمد الله بمحامد، ثم يُقال له: ارفع رأسك.","link":"https://binbaz.org.sa/fatwas/21539/انواع-الشفاعة-يوم-القيامة-ولمن-تكون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في الشفاعة.mp3","categories":["شروح الحديث","التوسل والشفاعة"]},{"id":1446,"question":"ما معنى التطويق (في حديث مَنْ ظَلَمَ قِيدَ شِبْرٍ مِنَ الأرْضِ طُوِّقَهُ مِن سَبْعِ أرَضِينَ)؟","title":"معنى حديث \"مَن ظَلَمَ قِيدَ شِبْرٍ مِنَ الأرض..\"","answer":"الجواب:\nيجعل طوقًا في عنقه –نسأل الله العافية-.\nس: ومَن قال أنه الخسف؟\nج: يُروى في اللفظ الآخر: خُسِفَ به، وجاء أنه الطوق، ولا مانع أن يُخسف به ويجعل طوقًا جميعًا –نسأل الله العافية-.","link":"https://binbaz.org.sa/fatwas/21542/معنى-حديث-من-ظلم-قيد-شبر-من-الارض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى التطويق في حديث من ظلم قيد شبرٍ من الأرض طوَّقه الله إياه.mp3","categories":["شروح الحديث"]},{"id":1448,"question":"هذا أحد الطلاب يسأل ويقول: ما رأيكم في حديث: \"مَن قال: أستغفر الله العظيم الذي لا إله إلا هو الحي القيوم وأتوب إليه؛ غُفِرَ له ذنوبه، ولو كان فارًّا من الزحف\"؟","title":"معنى حديث \"من قال أستغفر الله العظيم..\"","answer":"الجواب:\nهذا جاء عن النبي ﷺ، والمعنى -لو صحَّ- أنه إذا كان تاب توبةً صحيحةً، فالإنسان إذا استغفر باللسان ما يصير توبةً، التوبة تكون مع إقلاع القلب وندمه وعدم إصراره، فإذا تاب توبةً صادقةً محا الله ذنوبه كلها سبحانه، فالتوبة يمحو الله بها الذنوبَ كلها.","link":"https://binbaz.org.sa/fatwas/21544/معنى-حديث-من-قال-استغفر-الله-العظيم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى حديث َن قال أستغفر الله العظيم الذي لا إله إلا هو الحي القيوم وأتوب إليه؛ غُفِرَ له ذنوبه ولو كان فارًّا من الزحف.mp3","categories":["شروح الحديث"]},{"id":1456,"question":"ورد حديث: \"لا تَبِعْ ما ليس عندك\"، كيف نجمع بينه وبين جواز السَّلَم؟","title":"ما الفرق بين السَّلَم و\"بيع ما ليس عندك\"؟","answer":"الجواب:\nالسَّلَمُ: شيءٌ في الذمة إلى أجلٍ معلومٍ، ما هو شيء معين، هذا بإجماع المسلمين. أما الكيلُ المعلومُ وما يكون في العين فلا يُسَمَّى سَلَمًا، إذا قال: بعتُك الناقة الفلانية، أو الشاة الفلانية، وهي موجودة؛ فهذا ليس سَلَمًا، هذا بيع معين.","link":"https://binbaz.org.sa/fatwas/21553/ما-الفرق-بين-السلم-وبيع-ما-ليس-عندك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الجمع بين حديث لا تَبِعْ ما ليس عندك وجواز السلم.mp3","categories":["شروح الحديث"]},{"id":1459,"question":"بعض الشُّرَّاح يقول في معنى قوله: استدار، أي: عاد ورجع إلى انقسام السنين إلى سنين، والسنة إلى أشهر؟","title":"معنى حديث \"إن الزمان قد استدار..\"","answer":"الجواب:\nلا، السنة والشهر من قديم الزمان. لكن المعنى: إلغاء ما أحدثته الجاهلية في تغيير الشهور.\nس: يكون حجّه ﷺ في تلك السنة وافق ذي الحجة قدرًا؟\nج: نعم.","link":"https://binbaz.org.sa/fatwas/21556/معنى-حديث-ان-الزمان-قد-استدار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى استدار في قوله إن الزمان قد استدار.mp3","categories":["شروح الحديث"]},{"id":1489,"question":"معنى قوله \"حق\" (في حديث حقُّ المسلم على المسلم ستُّ..) يعني: واجب أو متأكد؟","title":"هل الحقوق في حديث \"حقُّ المسلم\" واجبة؟","answer":"الجواب:\nمتأكد، المعروف عند أهل العلم أنه متأكِّد.\nس: قد يكون بعضها واجبًا وقد يكون بعضها مستحبًّا؟\nج: المعروف عند أهل العلم أنها سنة، أنَّ هذه الحقوق متأكِّدة، كلها متأكدة، أمَّا رد السلام فهو واجب.\nس: وتشميت العاطس إذا حمد الله؟\nج: القول بوجوبه قوي؛ لأن فيه أمرًا، وكلها أوامر، فينبغي للمؤمن ألا يتخلَّف عنها.\nس: إجابة الدعوة؟\nج: واجب، مَن لم يُجِبِ الدَّعوةَ فقد عصى الله ورسوله، ينبغي للإنسان أن يحتاط لنفسه، ويحذر فلا يتساهل فيها ويقول: بعض العلماء يقول أنها مستحبة، لا، يأخذ بالحيطة؛ لأن الرسول ﷺ أمر، والأمر يقتضي الوجوب، قال: فقد عصى الله ورسوله، هذا صريحٌ في الوجوب.\nس: ماذا تُرجِّحون في البداءة بالسلام: الوجوب أم الاستحباب؟\nج: المعروف عند أهل العلم السنية، أولى الناس بالله الذي يبدؤهم بالسلام.\nس: إذا تعددت الدعوات، فدعاه مثلًا ثلاثةُ أشخاصٍ أو شخصان؟\nج: يبدأ بالأول، فإن كانت الدعوات جميعًا جاءت مرةً واحدةً فيُجيب أقربهم بابًا، إذا تعددت الدعوة يجاب الأول، فإن جاءت جميعًا يُجاب أقربهم بابًا، كما جاء في الحديث.\nس: لو ما حمد الله، هل يأمره أحدٌ بأن يحمد الله ؟\nج: إذا ذكَّره كان طيبًا، إذا ذكَّره فهذا من النُّصْح له.\nس: في بعض الروايات بالنسبة للعاطس يقول: الحمد لله على كلِّ حالٍ، وفي الرد: يغفر الله لنا ولكم؟\nج: لا، الثابت عن النبي ﷺ في الحديث الصحيح يقول: يهديكم الله ويُصلح بالكم.\nس: وسائر الروايات غير هذا؟\nج: محل نظر.","link":"https://binbaz.org.sa/fatwas/21587/هل-الحقوق-في-حديث-حق-المسلم-واجبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحقوق في حديث حقُّ المسلم على المسلم ستُّ.mp3","categories":["شروح الحديث"]},{"id":1496,"question":"لو كان الاجتماع في بيتٍ من البيوت العادية هل يحصل لهم نفس الفضل؟","title":"هل يشمل البيوت فضلُ مجالس الذكر؟","answer":"الجواب:\nيُرْجَى لهم إن شاء الله، لكن في المساجد أفضل وأنفع للناس، وإذا صارت في البيوت يُرجى لهم هذا الخير.","link":"https://binbaz.org.sa/fatwas/21595/هل-يشمل-البيوت-فضل-مجالس-الذكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في حديث ما اجتمع قومٌ في بيتٍ من بيوت الله.mp3","categories":["شروح الحديث"]},{"id":1500,"question":"الحديث: مَنْ سَتَر مسلما.. ما المقصود هنا؟","title":"معنى حديث \"مَنْ سَتَرَ مسلما\" وضوابط الستر","answer":"الجواب:\nسَتَرَه الله في الدنيا والآخرة.. ويشمل المعنى والعورة: مَن ستر عورته بالكسوة. ومن ستر عورته إذا زلَّ زلَّةً ولم يفضحه.\nس: أليس المقصود إذا فعل معصيةً وتاب؟\nج: يشمل الأمرين.\nس: الستر عام أم له ضوابط؟\nج: إذا كان ما أعلنها ولم يفضح نفسه، لكن إذا كنتَ تعلم أنت منه شيئًا فلا تفضحه، استر عليه، وادعُ له بالهداية، أما إذا فضح نفسه فما فيه حيلة.","link":"https://binbaz.org.sa/fatwas/21599/معنى-حديث-من-ستر-مسلما-وضوابط-الستر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بحديث من ستر مسلما.mp3","categories":["شروح الحديث"]},{"id":1506,"question":"يقول النبي ﷺ: ليسَ الكَذّابُ (الذي يُصْلِحُ بيْنَ النَّاسِ).. ما معناه؟","title":"معنى \"ليس الكذَّابُ الذي يُصلح بين الناس\"","answer":"الجواب:\nالذي يصلح بين الناس ليس بكذَّابٍ، هذا معناه، الذي يصلح بين الناس ليس بكذَّابٍ، فيقول خيرًا، أو يَنْمي خيرًا. إنما الكذَّاب الذي يكذب بدون إصلاح بين الناس، هذا الكذَّاب الذي يضرّ الناس، والذي ينفعهم ما هو كذَّاب.","link":"https://binbaz.org.sa/fatwas/21605/معنى-ليس-الكذاب-الذي-يصلح-بين-الناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى حديث النبي عليه الصلاة والسلام ليس الكذَّابُ الذي يُصلح بين الناس.mp3","categories":["شروح الحديث"]},{"id":1514,"question":"الأحاديث التي فيها تخمير الأواني: هل يشمل هذا الأواني الفارغة أم المراد الملآنة؟","title":"هل تغطية الأوانييشمل الفارغة والملآنة؟","answer":"الجواب:\nظاهر الحديث العموم، فإما أن يضع عليها عودًا أو يكفأها، مثلما قال النبي: ينزل في السنة وباء فيُخشى على صاحبها.\nس: هل يشمل هذا البيالات والفناجين؟\nج: الظاهر كل إناء، البيالة يكفأها، والفنجان كذلك، والحمد لله، والغضارة..... يحط عليها شيئًا، ولو أن يعرض عليها عودًا، أو يكفأها، أو يُطبقها بطباقة، هذا أحوط عملًا بالحديث.","link":"https://binbaz.org.sa/fatwas/21613/هل-تغطية-الاواني-يشمل-الفارغة-والملانة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تخمير الأواني هل يشمل الأواني الفارغة أم المراد الملآنة.mp3","categories":["الآنية","شروح الحديث"]},{"id":1518,"question":"كيف الجمع بين دعوة أم جريج: اللهم لا تُمته حتى ينظر إلى وجوه المُومسات وحديث يُستجاب لأحدكم ما لم يدع بإثمٍ أو قطيعةٍ؟","title":"سبب إجابة دعوة أم جُرَيْج وفوائد من الحديث","answer":"الجواب:\nدعت لأنها ترى أنه قطع رحمها، ولها حقٌّ عليه، فأجاب الله دعوتها ليُري عباده العِبَر، فله الحكمة البالغة ، فقد يُجاب الكافر وقد يُجاب غيره لحكمٍ بالغةٍ.\nس: هل يُدْعَى عليه بالمعصية؟ يعني: مَن أراد أن يدعو على ظالمٍ يدعو عليه بالزنا أو بشرب الخمر؟\nج: لا، ما ينبغي، بل يُدْعَى له بالهداية، إلا إنسانًا يُؤذي المسلمين فيُدعى عليه بالموت، أن يأخذه الله أخذ عزيز مقتدر، كما دعا النبيُّ ﷺ على أبي جهل وأشباهه، أما الباقين فيُدعى لهم بالهداية.\nس: الصومعة هل هي غرفة أم غار؟\nج: هي محل عبادة، قد تكون غرفةً، وقد تكون بيتًا كاملًا.\nس: العابد هل ثبت أنه صلَّى قبل وغزه الطفل ركعتين؟\nج: نعم، صلى ركعتين، قال: \"أمهلوني حتى أصلي ركعتين\" ثم دعا ربَّه.\nس: إذن يُشرع عند الحاجة أن يُصلّي ركعتين؟\nج: عند المصائب الصلاة من وسائل الخير، والله يقول: يَا أَيُّهَا الَّذِينَ آمَنُوا اسْتَعِينُوا بِالصَّبْرِ وَالصَّلَاةِ [البقرة:153].\nس: هل يؤخذ من هذا الحديث أنَّ الشخص إذا كان في صلاة نافلةٍ فناداه أحدُ أبويه يقطعها؟\nج: نعم، فقد كان الواجب عليه أن يقطعها؛ لأنَّ برّها واجب، والنافلة يجوز قطعها، لكنه تحرَّج واشتبه عليه الأمر فاستمر في صلاته.\nس: وإذا كان في فريضةٍ؟\nج: لا، لا يقطعها إلا عند الضرورة، كرجل أعمى يخشى سقوطه في شيءٍ، أو حية يخشى منها، أو سبع يخشى منه، المقصود عند الضَّرورة يقطعها.\nس: في سورة يوسف: وَشَهِدَ شَاهِدٌ مِنْ أَهْلِهَا [يوسف:26] ألم يكن رضيعًا؟\nج: هذا ما فيه دليل على أنه صغير.\nس: هل كان جريج قوي اليقين حتى نصره الله؟\nج: عابدٌ يعبد الله من عباد الله حتى أجاب الله دعوته، وأبرأ ساحته، ابتلاه ثم أنجاه، ابتلاه بدعوة أمه، ثم أنجاه وبيَّن براءته.","link":"https://binbaz.org.sa/fatwas/21617/سبب-اجابة-دعوة-ام-جريج-وفواىد-من-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/فوائد من قصة العابد جريج وأمه.mp3","categories":["شروح الحديث"]},{"id":1568,"question":"\"يمين الله في الأرض\" الحديث؟","title":"ما صحة ومعنى \"يمين الله في الأرض\"؟","answer":"الجواب:\nلا، هذا أثر عن ابن عباس، ما هو مرفوع، بل موقوف.\nس: يُحمَل على أي شيءٍ؟\nج: معناه: أن استلامه قربةٌ إلى الله، كأنَّه صافح الله، مَن استلمه كأنَّه صافح ربَّه؛ حثًّا على استلامه وترغيبًا في ذلك.\nس: حث على الاستلام؟\nج: ترغيب في الاستلام.\nس: لكن بعيد عن التشبيه؟\nج: لا ما فيه تشبيه ولهذا قال: \"فكأنما\"، \"فكأنما\" دال على التشبيه.","link":"https://binbaz.org.sa/fatwas/21671/ما-صحة-ومعنى-يمين-الله-في-الارض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل قول يمين الله في الأرض حديث وما معناه.mp3","categories":["شروح الحديث","الأسماء والصفات"]},{"id":1569,"question":"كيف نجمع بين هذين الحديثين: قوله عليه الصلاة والسلام: ومَن يستغنِ يُغنه الله، ومَن يستعفف يُعفّه الله ووصيته للصحابة بأن يجمعوا لأهل الصُّفَّة ما يجمعوا؟","title":"لماذا أوصى النبيﷺبالصدقة لأهل الصُّفَّة؟","answer":"الجواب:\nالصدقة على الفقراء، يُحسنوا إلى الفقراء، يعني: كان النبي ﷺ يُعطيهم ويُحسن إليهم، وإذا جاءت صدقة حوَّلها لهم، فأهل الصُّفَّة مهاجرون فقراء.","link":"https://binbaz.org.sa/fatwas/21672/لماذا-اوصى-النبيﷺبالصدقة-لاهل-الصفة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الجميع بين حديث ومَن يستغنِ يُغنه الله.. ووصيته للصحابة بأن يجمعوا لأهل الصفة.mp3","categories":["شروح الحديث"]},{"id":1589,"question":"زوجتي عندي تصوم الخميس والإثنين، وتسأل هل يجوز أن أصوم قبل دخول الشهر؟","title":"حكم صيام آخر شعبان لمن له عادة صوم؟","answer":"الجواب:\nتصوم؛ لأن هذا عادة لها، فالذي له عادة يصومها، أما مَن لم يكن له عادة فلا يصم، لا يصم يوم الثلاثين ولا تسعة وعشرين، لا يصم بعد نصف شعبان، أما مَن له عادة فلا بأس، كمَن يصوم يومًا ويُفْطر يومًا، أو يصوم الإثنين والخميس، فله أن يصوم، قال النبيُّ ﷺ: إلا رجل كان يصوم صومًا فليصُمْه.\nس: يشمل ذلك يوم الشك؟\nج: كله يوم الشك.","link":"https://binbaz.org.sa/fatwas/21692/حكم-صيام-اخر-شعبان-لمن-له-عادة-صوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم تقدم شهر رمضان بيوم أو يومين لمن كان له عادة الصوم.mp3","categories":["شروح الحديث","صيام التطوع"]},{"id":1606,"question":"الرواية التي في مسلم: إذا ولغ الكلبُ في الإناء فاغسلوه سبع مراتٍ، وعَفِّروه الثامنة بالتُّراب، كيف الجمع بينها وبين الرِّوايات الأُخرى؟","title":"كيفية الجمع بين روايات حديث ولوغ الكلب","answer":"الجواب:\nالثامنة يعني: بالنسبة إلى التراب هو الثامن، وإلا فهي سبع ثامنها التراب، يُضمّ إلى إحدى الغَسَلات.\nس: يكون في الأُولى؟\nج: أَوْلى في الأُولى؛ لرواية أبي هريرة: أولاهنَّ بالتراب، وذلك أحسن؛","link":"https://binbaz.org.sa/fatwas/21710/كيفية-الجمع-بين-روايات-حديث-ولوغ-الكلب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/شرح حديث إذا ولغ الكلبُ في الإناء فاغسلوه سبع مرات.mp3","categories":["شروح الحديث"]},{"id":1609,"question":"هل مُواصلة المُكافئ تُعتبر من صلة الرحم؟","title":"حكم الواصل المكافئ ومعنى زيادة العمر","answer":"الجواب:\nج: نعم، مكافأةٌ وصلة رحمٍ جميعًا.\nس: زيادة العمر هل هي حقيقيَّة: مَن أحبَّ أن يُنْسَأ له في أثره؟\nج: نعم، يكون هذا، تكون الزيادة بالبركة، وتكون الزيادة بالسنين، قد تكون مُعلَّقةً، فقد يكتب اللهُ لإنسانٍ مئة سنةٍ على صلة رحمه، والآخر كتب له ثمانين على صلة رحمه، والثالث كتب له ستين على صلة رحمه، قَدَرٌ مُعلَّقٌ على هذه الأسباب.","link":"https://binbaz.org.sa/fatwas/21713/حكم-الواصل-المكافى-ومعنى-زيادة-العمر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/شرح ما يتعلق بصلة الأرحام.mp3","categories":["شروح الحديث"]},{"id":1626,"question":"قوله عليه الصلاة والسلام: فإنَّ لهم ذِمَّةً وصهرًا، كيف كان الصِّهْر؟","title":"معنى قول النبيﷺ: \"فإنَّ لهم ذِمَّةً وصهرًا\"","answer":"الجواب:\nالظاهر -والله أعلم- ما حصل من كون هاجر منهم وتسرَّاها إبراهيمُ، وكون مارية منهم وتسرَّاها النبيُّ ﷺ وجاءت منه بإبراهيم، أما سارة أم إسحاق فليست منهم، ولا أذكر من أين كانت رضي الله عنها ورحمها.","link":"https://binbaz.org.sa/fatwas/21731/معنى-قول-النبيﷺ-فان-لهم-ذمة-وصهرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/قال عليه الصلاة والسلام فإنَّ لهم ذِمَّةً وصهرًا، كيف كان الصِّهْر.mp3","categories":["شروح الحديث"]},{"id":1631,"question":"معاملة الزيارة بالمثل: بعضهم يقيس على أنهم إذا زاروه زارهم؟","title":"حكم المعاملة بالمثل في زيارة الرحم","answer":"الجواب:\nيقول النبيُّ ﷺ: ليس الواصِلُ بالمكافئ، ولكن الواصلَ الذي إذا قطعت رحمُه وصلها، هذا الواصل الذي لا يُكافئهم يقول: ما جاءوني فلستُ آتيهم، لا، يذهب إليهم، ويُحسِن إليهم ولو قطعوه، ولو أساؤوا، هكذا الكمال.","link":"https://binbaz.org.sa/fatwas/21736/حكم-المعاملة-بالمثل-في-زيارة-الرحم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/زيارة الرحم هل تجب المعاملة بالمثل.mp3","categories":["شروح الحديث"]},{"id":1654,"question":"أُذكِّركم الله في أهل بيتي كررها ثلاث مرات؟","title":"معنى حديث \"أُذكِّركم الله في أهل بيتي\"","answer":"الجواب:\nيعني: يُذكِّرهم أن يحرصوا على إكرامهم، فهي توصية مكررة للتأكيد.","link":"https://binbaz.org.sa/fatwas/21759/معنى-حديث-اذكركم-الله-في-اهل-بيتي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/وصية النبي عليه الصلاة والسلام بإكرام أهل البيت.mp3","categories":["شروح الحديث"]},{"id":1662,"question":"في حديث أبي هريرة، ما المقصود بـ الأرواح جنودٌ مُجنَّدةٌ؟","title":"معنى حديث \"الأرواح جنود مجندة..\"","answer":"الجواب:\nيقصد أنها أصناف، فما تعارف منها ائتلف، ما تعارف منها بالتقوى والإيمان أو بالرفق ائتلف، وما تناكر منها اختلف.  فالواجب على أهل الإيمان أن يكونوا إخوةً متحابين في الله، متعاونين على البر والتَّقوى، متعاونين على كل خيرٍ، ضد الباطل وأهله.","link":"https://binbaz.org.sa/fatwas/21768/معنى-حديث-الارواح-جنود-مجندة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما المقصود بـ الأرواح جنود مجندة.mp3","categories":["شروح الحديث"]},{"id":1665,"question":"كيف الجمع بين استئذان عمر  النبيَّ ﷺ للعمرة وطلبه للعلم على يد النبي ﷺ؟","title":"كيف يجمع الطالب بين العُمرة وطلب العلم؟","answer":"الجواب:\nالحديث في سنده ضعف؛ لأنه من رواية عاصم بن عبيدالله، والعمرة مطلوبة ولو أنه عند خيار الناس، ولو أنه عند الأنبياء، فالعمرة عملٌ صالح، وكونه عند النبي ﷺ يطلب العلم ما يمنع، فطالب العلم يحجّ ويعتمر ولو أنه يطلب العلم أو يُدرّس الناس، فهي قُربة مستقِلَّة.\nس: إذن لا تعارض؟\nج: ليس هناك تعارض.","link":"https://binbaz.org.sa/fatwas/21771/كيف-يجمع-الطالب-بين-العمرة-وطلب-العلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الجمع بين استئذان عمر النبيَّ للعمرة وطلبه للعلم على يد النبي.mp3","categories":["شروح الحديث","الحكم على الأحاديث"]},{"id":1669,"question":"حديث سبعةٌ يُظِلُّهم الله في ظِلِّه .. إلى آخره، بالنسبة لرجلٍ دعته امرأةٌ ذات منصبٍ وجمالٍ: هذه المسألة هل تنطبق أيضًا على المرأة إذا دعاها رجلٌ ذو منصبٍ وجمالٍ؟","title":"ما فضلُ المرأة لو دعاها ذو منصب وجمال؟","answer":"الجواب:\nنعم، يُظلها الله في ظِلِّه يوم لا ظِلَّ إلا ظِلُّه، فالحكم واحد.","link":"https://binbaz.org.sa/fatwas/21775/ما-فضل-المراة-لو-دعاها-ذو-منصب-وجمال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/رجل دعته امرأة ذات منصب وجمال، ماذا لو دعا رجل امرأة.mp3","categories":["شروح الحديث"]},{"id":1671,"question":"السبعة الذين يُظلهم الله في ظِلِّه هل الرجال والنساء سواء فيها؟","title":"هل حديث السبعة الذين يُظلهم الله يَعُمُّ النساء؟","answer":"الجواب:\nلا، الإمام ما يكون إلا رجلًا، فالمساجد للرجال، فتشترك في الأشياء التي ما تخصّ الرجال: المحبَّة في الله، والخوف من الله، والبكاء من خشية الله، والصَّدقة، هذا يعمّ، أما إمام عادل ورجل قلبه معلَّقٌ بالمساجد فهذا يختص بالرجال.","link":"https://binbaz.org.sa/fatwas/21777/هل-حديث-السبعة-الذين-يظلهم-الله-يعم-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث السبعة الذين يُظلهم الله في ظِلِّه هل الرجال والنساء سواء فيه.mp3","categories":["شروح الحديث"]},{"id":1674,"question":"في حديث معاذ: ما المقصود بقوله في آخر الحديث: لهم منابر من نور؟","title":"معنى حديث \"المتحابُّون بجلالي لهم منابر..\"","answer":"الجواب:\nعلى ظاهره، يوم القيامة، يعني: في الجنة.\nس: يغبطهم النَّبيُّون؟\nج: يعني: في الجنة، هذا فضلٌ كبيرٌ إن صحَّ، رواه الترمذي، ويحتاج إلى نظرٍ في سنده، لكن يكفي عنه الحديث الذي رواه البخاري في \"الصحيح\": يقول الله جلَّ وعلا: أين المتحابُّون في جلالي؟ اليوم أُظلُّهم في ظلِّي، يوم لا ظلَّ إلا ظلِّي.\nس: يقول: يغبطهم النَّبيون والأنبياء أعلى منهم؟!\nج: لا مانع من كونهم يغبطونهم وهم أعلى منهم، من الممكن أن تغبط المستقيم وإن كنتَ أفضل منه، فتغبط المستقيم على الحق، والثابت على الحق، يغبطونهم لما أعطاهم الله من الخير. الشيخ: أيش قال المُحَشِّي عليه؟ الطالب: قال: رواه الترمذي وسنده قوي؟\nج: لعله، على كل حالٍ، ما دام ما فيه بأس، يغبطهم الأنبياءُ وإن كان الأنبياءُ أفضلَ منهم، فأنت تغبط مَن استقام على الصلاة وحافظ عليها في الجماعة وإن كنتَ أفضلَ منه.\nس: المحبَّة هل تختصُّ بالرجال أو تعمّ؟\nج: عامَّة، تعمّ الرجالَ والنِّساء.","link":"https://binbaz.org.sa/fatwas/21780/معنى-حديث-المتحابون-بجلالي-لهم-منابر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/شرح حديث المتحابُّون بجلالي لهم منابر من نور...mp3","categories":["شروح الحديث"]},{"id":1678,"question":"بالنسبة للغة: كيف يُفْهَم قوله: \"والله إني لأُحبُّك في الله\"؟","title":"معنى \"والله إني لأُحبُّك في الله\" في اللغة","answer":"الجواب:\n\"لَأُحِبُّ\" هذه اللام مُوطِّئة للقسم، للتثبيت، ما هي: \"لا أحبك\"، بل \"إني أحبك\"، فهي لام موطئة للقسم. \"والله إني لرسول الله\": لام التثبيت والتأكيد، وَإِنَّهُ لَتَنْزِيلُ رَبِّ الْعَالَمِينَ [الشعراء:192]، إِنَّهُ لَقَوْلُ رَسُولٍ كَرِيمٍ [الحاقة:40]، هذه للتثبيت.","link":"https://binbaz.org.sa/fatwas/21784/معنى-والله-اني-لاحبك-في-الله-في-اللغة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/كيف يفهم قوله والله إني لأُحبُّك في الله.mp3","categories":["شروح الحديث"]},{"id":1679,"question":"هل من تثبيت المحبَّة أن يُوصيه كما وصَّى رسولُ الله ﷺ معاذًا؟","title":"هل مِن تثبيت المحبة الوصية بالتقوى ونحوها؟","answer":"الجواب:\nإذا أخبره ما هو بلازمٍ، وإن وصَّاه زاد خيرًا، فإذا أخبره بالمحبَّة تكفي، وإذا وصَّاه وقال: اتَّقِ الله، أو: أُوصِيك بتقوى الله، أو: أُوصيك بصلة الرحم، أو: أُوصيك بطلب العلم، زيادة خير.","link":"https://binbaz.org.sa/fatwas/21785/هل-من-تثبيت-المحبة-الوصية-بالتقوى-ونحوها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل من تثبيت المحبة أن يوصيه كما وصى رسول الله معاذا.mp3","categories":["شروح الحديث"]},{"id":1681,"question":"في الحديث الأخير: مَن صلَّى الفجرَ في جماعةٍ؟","title":"معنى حديث \"من صلى الفجر في جماعة\"","answer":"الجواب:\nكذلك لا بأس به، صحيح، وهو في ذمَّة الله، يجب الحذر من ظلم المسلم.\nس: ما معنى الحديث؟\nج: التَّحذير من ترك الصلاة، ويُؤيد القول بأنَّ تركها كافر؛ لأنه إذا لم يصلِّ فليس في ذمَّة الله - نسأل الله العافية.\nس: هل يُقال: أنَّ مَن صلَّى الصُّبحَ فهو في ذمَّة الله: أنَّها تحفظه من السّحر والعين؟\nج: ما هو بلازمٍ، المقصود أنَّه في أمان الله يعني: احذروا ظلمَه، احذروا العدوانَ عليه - نسأل الله العافية - والأدواء الأخرى لها أسباب أخرى: التَّعوذ بكلمات الله التامَّات من شرِّ ما خلق، وسؤال الله العافية جلَّ وعلا، وتعاطي الأذكار الشرعية والأوراد الشرعية، كلها من أسباب السلامة.\nس: مَن لم يُصلِّ الصبحَ في غير جماعةٍ فهو مطالبٌ بالذمة؟\nج: لا، قيَّده بجماعةٍ، هذا فيه الحثّ على صلاة الجماعة، والمحافظة عليها.\nس: مناسبة ذكر هذا الحديث في باب التَّحذير من إيذاء المُسلمين؟\nج: لأنَّه إذا تعدَّى عليه فقد أتى منكرًا عظيمًا، وهو مؤمنٌ قد يُصلي في جماعةٍ، يعني: يكون ظلمه أشدَّ - نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/21787/معنى-حديث-من-صلى-الفجر-في-جماعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى حديث من صلى الفجر في جماعة.mp3","categories":["شروح الحديث"]},{"id":1693,"question":"الرجل الوارد في حديث النعمان (إن أهْوَن أهل النار عذابا..) هو أبوطالب؟","title":"مَن المراد بحديث \"إن أهْوَن أهل النار عذابًا\"؟","answer":"الجواب:\nجاء في حديثٍ آخر: أنَّ أبا طالب أهْوَن أهل النار عذابًا، وأنه يُوضَع في أخمص قدميه نارٌ يغلي منهما دماغه - نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/21799/من-المراد-بحديث-ان-اهون-اهل-النار-عذابا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من هو الرجل الوارد في حديث إن أهون أهل النار عذابا.mp3","categories":["شروح الحديث"]},{"id":1694,"question":"الذي يعمل بعمل أهل النار (في حديث يعمل بعمل أهل الجنة فيما يبدو للناس..) خاصّ بالمنافق؟","title":"معنى \"يعمل بعمل أهل الجنة فيما يبدو للناس\"","answer":"الجواب:\nهذا عاملٌ بما قدَّر الله له ذلك.\nس: ورد في بعض ألفاظ الحديث: فيما يظهر للناس؟\nج: وفي بعضها: فيما يبدو للناس فقد يكون هذا وهذا، قد يعمل بعمل أهل الجنة فيما يبدو للناس وهو من أهل النار، وقد يعمل بعمل أهل النار فيما يبدو للناس وهو من أهل الجنة، يُحسن اللهُ له الخاتمة، كما أسلم كثيرٌ من الناس في عهد النبي ﷺ وبعده، ثم قُتِلوا في الحال، وماتوا على الإسلام في الحال بعد دقائق قليلة.\nس: المقصود بقوله: فيكون من أهل النار يعني: أهل الخلود فيها؟\nج: نعم - نسأل الله العافية - يعني: سبقت لهم الشَّقاوة.\nس: مثلًا الكفار الذين يُسْلِمُون الآن؟\nج: هذا مثله، عاش في عمل أهل النار، ثم هداه الله، وصار إلى الجنة إذا أسلم، ولو مات بعد الإسلام بدقائق.\nس: حتى ولو بعد الشَّهادة؟\nج: الإسلام يَجُبُّ ما قبله، فإذا أسلم محا الله عنه كُفْرَه.","link":"https://binbaz.org.sa/fatwas/21800/معنى-يعمل-بعمل-اهل-الجنة-فيما-يبدو-للناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/فائدة من حديث يعمل بعمل أهل الجنة فيما يبدو للناس..mp3","categories":["شروح الحديث"]},{"id":1701,"question":"هل يُؤخذ من هذا أنَّ الإنسان مهما كان صالحًا أو فاجرًا من صفاته أنه يُذْنِب؟","title":"هل حديث \"كل بني آدم خطّاء\" يفيد العموم؟","answer":"الجواب:\nنعم، كل بني آدم خطَّاء، من صفاته الخطأ، لكن إذا تاب تاب اللهُ عليه.\nس: وإذا استمرَّ في الذنب؟\nج: وإذا استمرَّ في الذنب استحقَّ العقوبة، إلا أن يعفو الله: إِنَّ اللَّهَ لا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ [النساء:48]، فهو تحت العفو.","link":"https://binbaz.org.sa/fatwas/21807/هل-حديث-كل-بني-ادم-خطاء-يفيد-العموم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/كل بني آدم خطّاء يفيد العموم.mp3","categories":["شروح الحديث"]},{"id":1704,"question":"بالنسبة للحديث السابق وهو قوله ﷺ: لو لم تُذْنِبُوا لأتى الله بقومٍ يُذْنِبون فيستغفرون، ما معنى هذا الحديث؟","title":"معنى \"لو لم تُذْنِبُوا لأتى الله بقومٍ يُذْنِبون..\"","answer":"الجواب:\nعلى ظاهره: أنَّ الله جلَّ وعلا خلق قومًا يُذْنِبون حتى تظهر آثار رحمته وعفوه ومغفرته، وآثار انتقامه، فهو سبحانه رحيم ودود شديد العقاب، كما قال تعالى: نَبِّئْ عِبَادِي أَنِّي أَنَا الْغَفُورُ الرَّحِيمُ ۝ وَأَنَّ عَذَابِي هُوَ الْعَذَابُ الأَلِيمُ [الحجر:49- 50]، وقال تعالى: غَافِرِ الذَّنْبِ وَقَابِلِ التَّوْبِ شَدِيدِ الْعِقَابِ [غافر:3]، فلو كانوا كلهم مسلمين ما فيهم أحد كافر ولا عاصٍ لم تظهر آثار الرحمة والعفو والمغفرة.","link":"https://binbaz.org.sa/fatwas/21810/معنى-لو-لم-تذنبوا-لاتى-الله-بقوم-يذنبون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى حديث لو لم تُذْنِبُوا لأتى الله بقومٍ يُذْنِبون فيستغفرون..mp3","categories":["شروح الحديث"]},{"id":1705,"question":"(هل صح ما جاء في) فعل موسى (عليه السلام)  مع مَلَك الموت؟","title":"ما صحة ومعنى فعل موسى مع مَلَك الموت؟","answer":"الجواب:\nهذه قصة صحيحة: ضرب ملكَ الموت حتى فقأ عينَه.\nس: ما المقصود من فعله مع حديث: مَن أحبَّ لقاء الله أحبَّ اللهُ لقاءَه؟\nج: كل الناس يكرهون الموت، فهذا من كراهة الموت، ما هو من جهة الله، فجنس الموت مكروهٌ، ما هو محبوب.","link":"https://binbaz.org.sa/fatwas/21811/ما-صحة-ومعنى-فعل-موسى-مع-ملك-الموت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/شرح حديث مَن أحبَّ لقاءَ الله أحبَّ الله لقاءَه...mp3","categories":["شروح الحديث"]},{"id":1708,"question":"قول النبي ﷺ: سبعةٌ يُظِلُّهم الله في ظِلِّه جاء في بعض الأقوال أنَّ المقصود هنا بالسبعة ليس العدد وإنما القوة؟","title":"هل المراد العدد أم القوة في \"سبعةٌ يُظِلُّهم..\"؟","answer":"الجواب:\nلا، جنس السبعة.","link":"https://binbaz.org.sa/fatwas/21814/هل-المراد-العدد-ام-القوة-في-سبعة-يظلهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/فوائد من حديث سبعةٌ يُظِلُّهم الله في ظِلِّه...mp3","categories":["شروح الحديث"]},{"id":1710,"question":"قوله عليه السلام: سبعة يُظلّهم الله ما المراد بالظل عند أهل السُّنة؟","title":"ما المراد بالظِّل في حديث \"سبعة يُظلّهم الله\"؟","answer":"الجواب:\nالله أعلم، ظلٌّ يليق بالله، لا يعلم كيفيته إلا هو سبحانه.\nس: ظلّ عن الشمس؟\nج: نعم.","link":"https://binbaz.org.sa/fatwas/21816/ما-المراد-بالظل-في-حديث-سبعة-يظلهم-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المراد بالظل في قوله عليه الصلاة والسلام سبعة يُظلّهم الله عند أهل السنة.mp3","categories":["شروح الحديث","مسائل متفرقة في العقيدة"]},{"id":1726,"question":"كذلك بالنسبة للأيام العشر: كثيرٌ من الناس يصومون من أولها إلى اليوم العاشر، فهل هناك دليل يُثبت ذلك؟","title":"ما الدليل على فضل صيام عشر ذي الحجة","answer":"الجواب:","link":"https://binbaz.org.sa/fatwas/21833/ما-الدليل-على-فضل-صيام-عشر-ذي-الحجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم صيام عشر ذي الحجة كاملة.mp3","categories":["شروح الحديث","صيام التطوع"]},{"id":1733,"question":"حديث أبي هريرة: إذا عطس وضع يده أو ثوبه على فيه؟","title":"حكم وضع اليد على الفم في التثاؤب والعطاس","answer":"الجواب:\nحتى لا يخرج منه ما يُؤذي أحدًا.\nس: صحته؟\nج: صحيح.\nس: هل يكظم التَّثاؤب باليد اليسرى؟\nج: نعم.\nس: يكون على الوجوب؟\nج: هذه السنة، والأصل في الأوامر الوجوب.","link":"https://binbaz.org.sa/fatwas/21840/حكم-وضع-اليد-على-الفم-في-التثاوب-والعطاس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/فوائد من حديث إذا عطس وضع يده أو ثوبه على فيه.mp3","categories":["شروح الحديث"]},{"id":1749,"question":"قول الرسول ﷺ: اللهم ربَّ الناس، مُذهب البأس .. هل يُكره هذا الدعاء لمَن حضر مريضًا طلعت عليه علاماتُ الموت؟","title":"هل يُدعى بالشفاء لمن به علامات الموت؟","answer":"الجواب:\nلا.\nس: طيب، روى مسلمٌ عن عائشة قالت: كان رسولُ الله ﷺ إذا اشتكى منا إنسانٌ مسحه بيمينه، ثم قال: أذهب البأس رب الناس، واشفِ أنت الشافي، لا شفاء إلا شفاؤك، شفاءً لا يُغادر سقمًا، فلما مرض رسولُ الله ﷺ وثَقُل أخذتُ بيده لأصنع نحو ما كان يصنع، فانتزع يده من يدي، ثم قال: اللهم اغفر لي، واجعلني مع الرفيق الأعلى، قالت: فذهبتُ أنظر فإذا هو قد قضى؟\nج: اللهم صلِّ عليه، عرف نزولَ الأجل عليه الصلاة والسلام، ولهذا قال: اللهم في الرفيق الأعلى في الجنة.","link":"https://binbaz.org.sa/fatwas/21856/هل-يدعى-بالشفاء-لمن-به-علامات-الموت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/شرح حديث اللهم ربَّ الناس، مُذهب البأس.mp3","categories":["شروح الحديث"]},{"id":1754,"question":"إذا أثنى المسلمون على إنسانٍ بخيرٍ أو شرٍّ هل يُقال: وَجَبَتْ؟","title":"حكم ثناء المسلمين على إنسانٍ بخيرٍ أو شر","answer":"الجواب:\nمثلما قال ﷺ، إذا عَرَف الذي حصل عنده الثناء.....، ويعرف أنَّهم عُدول، يقول: وجبت.\nس: أليس هذا شهادة للمُعَيَّن؟\nج: هذا قاله جماعةٌ من أهل العلم، فالإمام أحمد رحمه الله وجماعة قالوا: إنه يُشهد للمُعَيَّن بالجنة، حتى قال فيه جماعة: إنَّه من أهل الجنة بهذه الشَّهادة، لكن المعروف في العقائد أنه لا يُشْهَد إلا بنصٍّ من الكتاب أو السنة، لكن بعض أهل العلم أخذ بهذا في شهادة المعين أيضًا: كأحمد بن حنبل، والقاضي عياض، والشافعي، ومالك، وجماعة، ممن أُثني عليه خيرًا وعُرِفَ بالخير.","link":"https://binbaz.org.sa/fatwas/21861/حكم-ثناء-المسلمين-على-انسان-بخير-او-شر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/فوائد من حديث أنتم شُهداء الله في الأرض..mp3","categories":["شروح الحديث"]},{"id":1755,"question":"إذا ناحَت المرأةُ على ابنها هل يحصل لها هذا الثَّواب (في حديث: ما مِن مُسلِمٍ يَموتُ لَه ثَلاثةٌ مِنَ الولَدِ ما لَم يَبلُغوا الحِنثَ إلا تلقَّوهُ مِن أبوابِ الجنَّةِ الثَّمانيةِ مِن أيِّها شاءَ دخَل)؟","title":"هل يحصل ثواب موت الولد للنائحة؟","answer":"الجواب:\nيُخشى عليها، الحديث مُطلق لكن يُخشى عليها، فالمراد الاحتساب والصبر، والنياحة منكر، وهي من أسباب العذاب، فيُخشى عليها، ولهذا جاء في الحديث: النَّائحة إذا لم تتب قبل موتها تُقام يوم القيامة وعليها سربالٌ من قطران ودرعٌ من جربٍ.\nس: حديث: لعن الله النَّائحة والمُسْتَمِعَة؟\nج: كذلك حديث أم عطية -نسأل الله العافية- والحديث الآخر: أنا بريءٌ من الصَّالقة والحالقة والشَّاقَّة، ليس منا من ضرب الخدود، أو شقَّ الجيوب، أو دعا بدعوى الجاهلية. س: يُشترط أن تكون له عقيقة؟ ج: العقيقة سنة، فإذا صبر واحتسب ولو ما عقَّ عنه له أجر. س: في حديث: الولد مُرْتَهِنٌ بعقيقته؟ ج: مُرْتَهِنٌ ما بَيَّنَ الارتهان، فالله أعلم بالارتهان، هذا علمه إلى الله، وقول بعض الناس: من الشَّفاعة، ما عليه دليل.","link":"https://binbaz.org.sa/fatwas/21862/هل-يحصل-ثواب-موت-الولد-للناىحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسائل من حديث مَا مِنْ مُسلِمٍ يَمُوتُ لَهُ ثلاثَةٌ لَمْ يَبْلُغُوا الحِنْثَ إِلَّا أدخلَهُ اللَّهُ الجنَّةَ.mp3","categories":["شروح الحديث"]},{"id":1765,"question":"مَن قال: حديث خَولة (مَنْ نَزلَ مَنزِلًا ثُمَّ قَالَ أَعُوذُ بِكَلِمات اللَّهِ التَّامَّاتِ...) لا تقربه الهوامّ أم تقربه وتُؤذيه ولكن لا تضرّه؟","title":"معنى وأثر قول \"أَعُوذُ بِكَلِمات اللَّهِ التَّامَّاتِ..\"","answer":"الجواب:\nقد يقع هذا، ولكن كما قال النبيُّ: لم تضرّك، ما قال: \"لم تقربك\"، قال: لم تضرك، فهي كلمات إذا قلتها لم تضرك.\nس: حديث خولة يُقال ثلاث مرات؟\nج: نعم، جاء في روايةٍ: \"ثلاث مرات\"، من غير هذه الطريق.\nس: يقول هذا عند بداية سكنه المنزل الجديد؟\nج: يقول: \"أعوذ بكلمات الله التَّامات من شرِّ ما خلق\" طيب، إذا دخل في الليل، أو دخل في النهار، يعتادها.\nس: دائمًا يُكرر؟\nج: يكون أحسن وأكمل.","link":"https://binbaz.org.sa/fatwas/21872/معنى-واثر-قول-اعوذ-بكلمات-الله-التامات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/فوائد من حديث مَنْ نَزلَ مَنزِلًا ثُمَّ قَالَ أَعُوذُ بِكَلِمات اللَّهِ التَّامَّاتِ...mp3","categories":["شروح الحديث"]},{"id":1767,"question":"حديث جابر (إِذَا أَطالَ أَحدُكم الغَيْبَةَ فَلا يَطْرُقَنَّ أَهْلَهُ لَيْلًا) النَّهي فيه للوجوب أم للاستحباب؟","title":"هل النَّهي عن طرق الأهل ليلًا للوجوب؟","answer":"الجواب:\nهذا ظاهر الأحاديث؛ لأن الأصل في النهي التحريم، والأصل في الأوامر الوجوب، يقول النبي ﷺ: ما نهيتُكم عنه فاجتَنِبُوه، وما أمرتُكم به فأتوا منه ما استطعتم، ويقول الله جل وعلا: وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانْتَهُوا [الحشر:7]، فالأصل في النَّواهي التحريم، هذا هو الأصل، إلا بدليلٍ يدل على الكراهة فقط، والأصل في الأوامر الوجوب، إلا بدليلٍ يدل على الاستحباب.","link":"https://binbaz.org.sa/fatwas/21874/هل-النهي-عن-طرق-الاهل-ليلا-للوجوب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/قوله عليه الصلاة والسلام إِذَا أَطالَ أَحدُكم الغَيْبَةَ فَلا يَطْرُقَنَّ أَهْلَهُ لَيْلًا النَّهي للوجوب أم للاستحباب.mp3","categories":["شروح الحديث"]},{"id":1775,"question":"حديث ابن عمر: \"مَن فعل هذا لعنه الله\" ألا يُستدل به على لعن المُعين؟","title":"ما دلالة أثر ابن عمر \"مَن فعل هذا لعنه الله\"؟","answer":"الجواب:\nيُحتج بهذا على لعن المعين، لكن الأحاديث الأخرى تدل على أنه ينبغي عدم لعن المعين؛ لأن هذا من فعل ابن عمر، أما الرسول ﷺ فلعن العموم.","link":"https://binbaz.org.sa/fatwas/21882/ما-دلالة-اثر-ابن-عمر-من-فعل-هذا-لعنه-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث مَن فعل هذا لعنه الله ألا يُستدل به على لعن المُعين.mp3","categories":["شروح الحديث"]},{"id":1793,"question":"هل يدل الحديثُ (إنَّ أوَّلَ النَّاسِ يُقْضَى يَوْمَ الْقِيامَةِ عَليْهِ رجُلٌ اسْتُشْهِدَ... الحديث) على أنهم مخلَّدون في النار؟","title":"هل يُخَلَّد المرائي بعبادته في النار؟","answer":"الجواب:\nمحتمل، إن كانوا منافقين فهم مخلدون في النار، وإن كان للرياء فلا، وإنما هو من باب الوعيد.","link":"https://binbaz.org.sa/fatwas/21900/هل-يخلد-المراىي-بعبادته-في-النار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/قال عليه الصلاة والسلام إنَّ أوَّلَ النَّاسِ يُقْضَى يَوْمَ الْقِيامَةِ عَليْهِ رجُلٌ اسْتُشْهِدَ.. هل فيه دلالة على خلودهم في النار.mp3","categories":["شروح الحديث","الرياء والسمعة"]},{"id":1803,"question":"معنى حديث: مَن سَمَّع سَمَّع الله به؟","title":"معنى حديث: \"مَن سَمَّع سَمَّع الله به\"","answer":"الجواب:\nعلى ظاهره: مَن سَمَّع بالقراءة أو بالدعوة إلى الله رياءً؛ سمَّع الله به وفضحه؛ نسأل الله العافية.\nس: في الآخرة أو في الدنيا؟\nج: في الآخرة.","link":"https://binbaz.org.sa/fatwas/21911/معنى-حديث-من-سمع-سمع-الله-به","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى حديث مَن سمَّع سمَّع الله به.mp3","categories":["شروح الحديث"]},{"id":1814,"question":"بالنسبة لحديث الرسول ﷺ الذي جاء فيه: أجعل لك صلاتي، ربع صلاتي، يا رسول الله، فقال الرسول ﷺ...؟","title":"ما معنى \"أجعل لك صلاتي\" في الحديث؟","answer":"الجواب:\nيعني: الدعاء، هذا له دعاء خاصّ.\nس: هل يُشرع أن أدعو للرسول ﷺ في صلاتي؟\nج: نعم.\nس: لا بأس يعني؟\nج: نعم، في السجود، ومثلما تدعو في آخر التحيات.\nس: يعني: بدل أن أدعو لنفسي أدعو للرسول ﷺ؟\nج: اللهم صلِّ على محمدٍ... من أسباب الإجابة: إذن تُكْفَى همُّك، ويُغْفَر ذنبك.","link":"https://binbaz.org.sa/fatwas/21922/ما-معنى-اجعل-لك-صلاتي-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/فوائد من حديث أجعل لك صلاتي.mp3","categories":["شروح الحديث","الأدعية والأذكار"]},{"id":1817,"question":"حديث نساء الأنصار (كَأَنَّ عَلَى رُءُوسِهِنَّ الْغِرْبَانَ) هل يُستدل به في هذا الباب (النقاب)؟","title":"هل في حديث نساء الأنصار دلالة للنقاب؟","answer":"الجواب:\nنعم من هذا الباب، لكن ليس بالصريح.\nس: عندنا هناك يستحيل أن تلبس النساءُ النقابَ، فهل عندكم نصيحة لهن؟\nج: نسأل الله أن يهدينا وإياهم، هناك رسالة في الحجاب لنا ولشيخ الإسلام ابن تيمية وللشيخ محمد بن صالح العثيمين وغيرهم، فهناك رسائل في الحجاب، نُعطيهم منها؛ إن شاء الله.","link":"https://binbaz.org.sa/fatwas/21925/هل-في-حديث-نساء-الانصار-دلالة-للنقاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث نساء الأنصار كأنهنَّ الغربان هل يُستدل به على النقاب.mp3","categories":["شروح الحديث","قضايا المرأة"]},{"id":1848,"question":"حديث عمر: \"الميت يُعذَّب بما نِيحَ عليه\" ما أصحّ ما قيل في معناه؟","title":"معنى \"الميت يُعذَّب بما نِيحَ عليه\" في الحديث","answer":"الجواب:\nأي أنه يُعذَّب بما يعلمه الله، هذا من باب التحذير، هذه أمور غيبية، وهذا مستثنى من قوله جل وعلا: وَلَا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَى [الإسراء:15]، والغالب أنَّهم إذا علموا أن الميت لا يرضى بهذا فإنه يُؤثِّر فيهم ويكفّهم بعض الشيء.\nس: مَن قال أنه يحمل على مَن كان يعلم من أهله النياحة، ولم ينههم عنها؟\nج: الحديث عام، وهو مستثنى من: وَلَا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَى [الإسراء:15].\nس: يعني يُقال: الله أعلم به؟\nج: نعم، عذابٌ الله أعلم بصفته.","link":"https://binbaz.org.sa/fatwas/21957/معنى-الميت-يعذب-بما-نيح-عليه-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أصح ما قيل في حديث الميت يُعذَّب بما نِيحَ عليه.mp3","categories":["شروح الحديث"]},{"id":1849,"question":"هل للمُبَلِّغ بنقل الوفاة تأثير على أهل الميت؟ فعليه أن يُبَلِّغهم مثلًا بتدريج وكذا؛ لأنهم يمكن أن ينصدموا، ثم هو يُسبب النياحة بانصدامهم بسماع الخبر بالوفاة وكذا؟","title":"ما حكم التَّدَرُّج في إبلاغ أهل الميت بموته؟","answer":"الجواب:\nلا بد أن يسمعوه، لو ما سمعوه اليوم سمعوه غدًا، لكن يُسمعهم إياه ويُعزيهم والحمد لله، أما أنه يكذب لا يكذب.\nس: يُخفف مثلًا فيقول: هو مريض، أو في حالةٍ خطرةٍ، يعني تدريجيًّا.\nج: وهم ما عندهم خبر أنه مريض؟\nس: ما عندهم خبر، مثلًا: حصل له حادثٌ فمات فيُخبرهم بالتَّدريج، فيقول مثلًا أنه في حالةٍ خطرةٍ وكذا، ويحتمل أنه في سكرات الموت وكذا؟\nج: الله أعلم.","link":"https://binbaz.org.sa/fatwas/21958/ما-حكم-التدرج-في-ابلاغ-اهل-الميت-بموته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إبلاغ أهل الميت بموت قريبهم.mp3","categories":["شروح الحديث","مسائل متفرقة في الجنائز"]},{"id":1850,"question":"البراءة في الحديث ماذا تقتضي؟","title":"ما دلالة \"أنا بريء\" و\"ليس منا\" في الحديث؟","answer":"الجواب:\nمن باب الوعيد، وبعضهم يُلحقها بالكبائر، قوله ﷺ: أنا بريءٌ بعضُ أهل العلم كشيخ الإسلام ابن تيمية وجماعة يقولون: هذا يُلحق بالكبائر، إذا قال فيها: أنا بريء أو ليس منا.","link":"https://binbaz.org.sa/fatwas/21959/ما-دلالة-انا-بريء-وليس-منا-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إذا قال رسول الله أنا بريء فماذا تقتضي البراءة.mp3","categories":["شروح الحديث"]},{"id":1851,"question":"ما ذنب الميت أنه يُعذَّب بسبب نياحة قريبه؟","title":"لماذا يُعذَّب الميت بسبب نياحة قريبه؟","answer":"الجواب:\nالله أعلم، هذا إلى الله، مثلما قلتُ لك: هذا مُستثنى من: وَلَا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَى [الإسراء:15]، هذا أمره إلى الله.","link":"https://binbaz.org.sa/fatwas/21960/لماذا-يعذب-الميت-بسبب-نياحة-قريبه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما ذنب الميت أنه يُعذَّب بسبب نياحة قريبه.mp3","categories":["شروح الحديث"]},{"id":1864,"question":"معنى قوله ﷺ: أَوْ لَيَضْرِبَنَّ اللَّه بقُلُوبِ بَعْضِكُمْ عَلَى بَعْضٍ؟","title":"معنى حديث: \"أَوْ لَيَضْرِبَنَّ اللَّه بقُلُوبِ بَعْضِكُمْ\"","answer":"الجواب:\nمن مقتضاها هذا، يعني: تتشابه قلوبهم، ويكونون على الشرِّ جميعًا -نسأل الله العافية- كل واحد يتأسَّى بالآخر.\nس: منها التفرق والاختلاف؟\nج: منها ذلك.","link":"https://binbaz.org.sa/fatwas/21973/معنى-حديث-او-ليضربن-الله-بقلوب-بعضكم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى قوله أَوْ لَيَضْرِبَنَّ اللَّه بقُلُوبِ بَعْضِكُمْ عَلَى بَعْضٍ.mp3","categories":["شروح الحديث"]},{"id":1873,"question":"الشر الذي اقترب ما هو؟ الذي حذَّر منه النبيُّ ﷺ؟","title":"معنى حديث \"ويل للعرب من شر قد اقترب\"","answer":"الجواب:\nخروج يأجوج ومأجوج، وخروج الدجال، هذه الشرور القريبة. الدجال شرُّ، ويأجوج ومأجوج شرٌّ، وانتشار المعاصي شرٌّ، كلها شرٌّ.","link":"https://binbaz.org.sa/fatwas/21982/معنى-حديث-ويل-للعرب-من-شر-قد-اقترب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ويل للعرب من شر قد اقترب ما هو الشر الذي اقترب.mp3","categories":["شروح الحديث"]},{"id":1876,"question":"في حديث ابن مسعود: ليس وراء ذلك حبَّة خردل؟","title":"معنى حديث \"ليس وراء ذلك حبَّة خردل\"","answer":"الجواب:\nيعني فيما يتعلق بالإيمان بالأمر والنهي، وليس معناه أنه كافر، ليس بكافر، الإنكار آخرها القلب، ما بقي شيءٌ بعد القلب.","link":"https://binbaz.org.sa/fatwas/21985/معنى-حديث-ليس-وراء-ذلك-حبة-خردل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/قال عليه الصلاة والسلام ليس وراء ذلك حبَّة خردل هل يعني الكفر.mp3","categories":["شروح الحديث"]},{"id":1877,"question":"كيف نجمع بين قوله في الحديث: لا تأخذنا في الله لومة لائم وبين تقديم المصالح في مسألة الأمر بالمعروف والنهي عن المنكر؟","title":"كيف يُجمع بين النصيحة ومراعاة المصلحة؟","answer":"الجواب:\nهذا إلى ولي الأمر، ولي الأمر يُنظِّم الأمور؛ لئلا تحصل فوضى وفتنة.\nس: أقصد الآمر العادي، الفرد العادي؟\nج: يتكلم على حسب طاقته بالكلام الطيب: ادْعُ إِلَى سَبِيلِ رَبِّكَ بِالْحِكْمَةِ [النحل:125]، يكون بالكلام الطيب والفعل الطيب، هذا الإنكار باللسان، إذا رأى مَن يحلف بغير الله يقول: اتق الله، هذا ما يجوز. رأى مَن يشتم ويسب يقول: ما يجوز. رأى مَن ينظر للنساء ويفعل المشاكل التي يُخشى منها يُنكر عليه، يرى مَن يتخلف عن الصلاة في الجماعة ينصحه، وهكذا.","link":"https://binbaz.org.sa/fatwas/21986/كيف-يجمع-بين-النصيحة-ومراعاة-المصلحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الجمع بين حديث لا تأخذنا في الله لومة لائم وبين تقديم المصالح في الأمر بالمعروف والنهي عن المنكر.mp3","categories":["شروح الحديث"]},{"id":1909,"question":"قوله ﷺ: كان نبيٌّ من الأنبياء يَخُطُّ؟","title":"معنى حديث \"كان نبيٌّ من الأنبياء يَخُطُّ\"","answer":"الجواب:\nيُخَط، هذا من الطيرة، الخطوط كما تقدم: إنَّ العيافة والطِّيرة من الجبت، هذا يُلَبِّس به العرَّافون والمنجِّمون والكهنة، حيث يقومون بالخطوط في الأرض ويقولون: سوف يقع كذا. وكان نبيٌّ يخط بأمر الله، إذا أراد شيئًا بأمر الله، وخطُّه ما يُعْرَف، انتهى بانتهائه عليه الصلاة والسلام، خطّ النبي ما يعرفه أحدٌ، ولهذا زجر الرسولُ عن الطيرة، ونهى عنها، وأخبر أنها شركٌ مطلقًا.","link":"https://binbaz.org.sa/fatwas/22022/معنى-حديث-كان-نبي-من-الانبياء-يخط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/شرح حديث كان نبيٌّ من الأنبياء يَخُطُّ.mp3","categories":["شروح الحديث"]},{"id":1913,"question":"كيف الجمع بين قوله ﷺ الطيرة شرك وكذلك قوله في حديث عروة بن عامر عندما ذكرت عنده ﷺ الطيرة فقال أحسنها الفأل؟","title":"ما كيفية الجمع بين أحاديث الفأل والطيرة؟","answer":"الجواب:\nيعني: ما هو منها، يعني: هو أحسنها، فيه نوعُ من الارتياح له، لكن ليس منها، هذا حسن يُخرجه منها، ولهذا قال: يُعجبني الفأل.\nس: لكن قوله: أحسنها؟\nج: ما يُوجب دخوله فيها، أحسنها يعني: ما يصير منها.","link":"https://binbaz.org.sa/fatwas/22026/ما-كيفية-الجمع-بين-احاديث-الفال-والطيرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الجمع بين حديث الطيرة شرك، وحديث أحسنها الفأل.mp3","categories":["شروح الحديث","التشاؤم والتطير"]},{"id":1917,"question":"السيارة تُطلق على الدابة؟","title":"هل حديثُ \"الشؤم في ثلاث\" يعُمُّ السيارةَ؟","answer":"الجواب:\nوأيش فيه؟\nس: مثلًا في التَّشاؤم من الفرس أو كذا هل تُطلق عليها؟\nج: الله أعلم، جاء في حديث الدابة الفرس والمرأة، هذه قد يقع فيها شؤم، يعني: قد لا تكون مباركةً على صاحبها، ما هو بعيدٌ أن تكون السيارة والسفينة مثل الدَّابة؛ لأنَّها مركوبة.","link":"https://binbaz.org.sa/fatwas/22030/هل-حديث-الشوم-في-ثلاث-يعم-السيارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/قياس السيارة على الفرس.mp3","categories":["شروح الحديث","التشاؤم والتطير"]},{"id":1933,"question":"قول عمر: \"لو كنتم من أهل المدينة لأَوْجَعْتُكما ضربًا\" يعني أنَّ هناك فرقًا بين المدينة والطائف؟","title":"معنى قول عمر: \"لو كنتم مِن أهل المدينة..\"","answer":"الجواب:\nلا، يعني أنهم جُهَّال، يعني أنَّ أهل المدينة عندهم علمٌ وبصيرةٌ في احترام هذا المسجد، لكن أنتم جُهَّال.","link":"https://binbaz.org.sa/fatwas/22046/معنى-قول-عمر-لو-كنتم-من-اهل-المدينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بقول عمر لو كنتم من أهل المدينة لأَوْجَعْتُكما ضربًا.mp3","categories":["شروح الحديث"]},{"id":1944,"question":"في حديث \"مَسْتَرِقي السمع\" ورد أنه ذكر أنَّ بعضهم فوق بعضٍ، قال: وبدَّد سفيانُ أصابعه، فكيف هي صفة التبديد؟","title":"ما صفة مَسْتَرِقي السمع من الجن؟","answer":"الجواب:\nيعني ما هم بمُتلاصقين، واحدٌ فوق واحدٍ، لكن ما يمسّه.\nس: إذن كيف يرقى بعضُهم فوق بعضٍ؟\nج: فوق بعضٍ ولا يمسّه؛ لأنهم يطيرون طيرانًا.\nس: بعض الإخوان فسَّر التَّبديد بالعَرَض؟\nج: لا، الجن منهم طوائف يطيرون، والجن أقسام.","link":"https://binbaz.org.sa/fatwas/22058/ما-صفة-مسترقي-السمع-من-الجن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/شرح حديث مسترق السمع.mp3","categories":["شروح الحديث"]},{"id":1946,"question":"إن كان كاذبًا فهو كما قال يعني: يخرج من الإسلام؟","title":"معنى حديث \"إن كان كاذبًا فهو كما قال\"","answer":"الجواب:\nمن باب الوعيد.\nس: لا يَكْفُر؟\nج: لا، من باب الوعيد، مثل: مَن حلف بالأمانة فليس منَّا من باب الوعيد، ليس منَّا مَن ضرب الخدود، وشقَّ الجيوب، ودعا بدعوى الجاهلية.","link":"https://binbaz.org.sa/fatwas/22060/معنى-حديث-ان-كان-كاذبا-فهو-كما-قال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بحديث إن كان كاذبًا فهو كما قال.mp3","categories":["شروح الحديث"]},{"id":1954,"question":"قول الرسول ﷺ في الحديث: وحرَّم الله الجنةَ عليه يدل على خلوده في النار؟","title":"معنى \"وحرَّم الله الجنةَ عليه\" في الحديث","answer":"الجواب:\nهذا من باب الوعيد عند أهل العلم، مَن لقي الله وهو عليه غضبان فقد أوجب الله له النار، وحرَّم عليه الجنة، كله من باب الوعيد والتحذير.  والوعيد قد يعفو الله عن الموعود بسبب حسناته الكثيرة، وبسبب شفاعة الشفعاء؛ لأنه مُوحِّد، فقد يُعفى عنه، ولهذا قال : إِنَّ اللَّهَ لَا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ [النساء:48] يعني: ما دون الشرك، يدخل في هذا جميع الذنوب.\nس: عند عوام الناس أحاديث الوعيد تُذْكَر بدون تفصيلٍ أفضل وأوْلى؟\nج: نعم، عند الاستفتاء والحاجة يُوضّح، أطلقها النبي وأطلقها القرآن للتَّحذير والزَّجر.","link":"https://binbaz.org.sa/fatwas/22069/معنى-وحرم-الله-الجنة-عليه-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/قوله عليه الصلاة والسلام وحرَّم الله الجنةَ عليه هل يدل على الخلود في النار.mp3","categories":["شروح الحديث"]},{"id":1960,"question":"البََيِّعان بالخِيَار يشترط استلام النقود، أم أنه لو قال مثلًا: \"غدًا أُعطيك الفلوس\" وتفارقوا، فهل البيع تم دون استلام النقود؟","title":"معنى حديث \"البََيِّعان بالخِيَار\"","answer":"الجواب:\nيختلف: إن كان ربويًّا ما يتم، وإن لم يكن ربويًّا يتم، فلو قال: تمت المبايعةُ بينه وبينه على سيارةٍ، أو على كتابٍ، أو على ثوبٍ، أو ما أشبه ذلك؛ وتفرَّقوا، فالبيع يتم، والثمن على ما أجَّله.\nس: لو رجع هل يأثم البائع؟\nج: لا، إذا تفرَّقوا لزم البيع، إلا إذا تسامحوا ورَضَوا بالفسخ، ما يُخالف، الحق لهم.","link":"https://binbaz.org.sa/fatwas/22075/معنى-حديث-البيعان-بالخيار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/شرح حديث البيعان بالخيار.mp3","categories":["البيوع","شروح الحديث"]},{"id":1962,"question":"الأوامر للوجوب في حديث ابن عمر منِ استعاذ بِالله فأَعيذوه، ومن سأَل بالله فأَعطوه؟","title":"هل حديث \"منِ استعاذ بِالله فأَعيذوه\" للوجوب؟","answer":"الجواب:\nهذا الأصل، الأصل في الشريعة الوجوب.","link":"https://binbaz.org.sa/fatwas/22077/هل-حديث-من-استعاذ-بالله-فاعيذوه-للوجوب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الأوامر في حديث منِ استعاذ بِالله فأَعيذوه، ومن سأَل بالله فأَعطوه...mp3","categories":["شروح الحديث"]},{"id":1982,"question":"قوله ﷺ: لا صلاة المراد منه الكمال أو الصحة؟","title":"معنى \"لا صلاة..\" في بعض أحاديث النَّهْي","answer":"الجواب:\nالمعروف عن العلماء الكمال، فلو صلَّى وأتمها صحَّت، ولكن في خطرٍ؛ لأنَّ الأصل في الصلاة النفي، والمسمَّى الشرعي لا يُنْفَى إلا إذا ترك الإنسانُ بعضَ الواجبات، ما يُنْفَى نفي كمال، لا، هذا يدل على وجوب التَّخلص من مُدافعة الأخبثين، وكذلك كونه يتناول من الطعام ما يسدّ حاجته، فالأظهر أنه لا يجوز له.","link":"https://binbaz.org.sa/fatwas/22098/معنى-لا-صلاة-في-بعض-احاديث-النهي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المراد بقوله عليه الصلاة والسلام في الحديث لا صلاة.mp3","categories":["شروح الحديث"]},{"id":1990,"question":"لو صادف يوم عرفة أو عاشوراء يوم الجمعة هل يُصام؟","title":"حكم صوم الجمعة يوم عرفة أو عاشوراء","answer":"الجواب:\nصامه لأجل ما هو الجمعة، صامه لأنه يوم عرفة، ما في بأس.\nس: هل يُستحب له أن يضيف يومًا لصيام يوم عرفة في يوم الجمعة؟\nالشيخ: إذا صام يوم الخميس أفضل مع الجمعة، كالسُّنة يصوم يومًا قبله ولا يومًا بعده، فإذا صام معه الخميس يكون أكمل وأطيب.\nس: كذلك في عاشوراء أحسن الله إليك، لو أضاف يوما آخر...؟\nالشيخ: يوم السبت، وإلا يوم الخميس أحسن.\nس: حتى لا يُفْرِدَه لوحده.\nالشيخ: نعم.","link":"https://binbaz.org.sa/fatwas/22106/حكم-صوم-الجمعة-يوم-عرفة-او-عاشوراء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صادف يوم عرفة يوم الجمعة أو عاشوراء هل يصام.mp3","categories":["شروح الحديث","صيام التطوع"]},{"id":1991,"question":"إذا بقي عليه ركعة من الراتبة يقطعها؟","title":"ماذا يفعل مَنْ يصلي الراتبة وأقيمت الصلاة؟","answer":"الجواب:\nيقطعها نعم، إلا إذا كان قد ركع الركوع الثاني، انتهت.\nس: بعضهم يقول أن الرسول ﷺ يقول: فلا صلاة ولم يقل: \"ولا بعض صلاة\" وهو في بعض الصلاة؟\nالشيخ: الركعة تسمى صلاة.","link":"https://binbaz.org.sa/fatwas/22107/ماذا-يفعل-من-يصلي-الراتبة-واقيمت-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إذا أقيمت الصلاة فلا صلاة.mp3","categories":["شروح الحديث","صلاة التطوع"]},{"id":1993,"question":"(حديث) أبِيتُ عند رَبِّي يُطْعِمنُي وَيَسْقِينِي...؟","title":"معنى حديث \"أبِيتُ عند ربي يُطْعِمنُي..\"","answer":"الجواب:\nإطعامٌ خاص، يعني: ما يفتح الله عليه من مواد الأُنْس ونفحات القُدُس والتلذذ بمناجاته، ما هو بالطعام الأكل، لو صار يأكل ما صار صائمًا، لكن ما يفتح الله على قلبه من الأنس بذكر الله وطاعته يقوم مقام الطعام والشراب.","link":"https://binbaz.org.sa/fatwas/22109/معنى-حديث-ابيت-عند-ربي-يطعمني","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بقوله عليه الصلاة والسلام أبيت عند ربي يطعمني ويسقيني.mp3","categories":["شروح الحديث"]},{"id":2005,"question":"هل حديث الرسول ﷺ: من سمع النداء فليُجِب هل هذا خاص بالحضر، أم أنه عام للحضر والسفر؟","title":"حكم صلاة الجماعة في الحضر والسفر","answer":"الجواب:\nللحاضرين.  المسافرون لهم الصلاة وحدهم، إلا إذا كان واحدٌ؛ يلزمه يصلي مع الجماعة.  أما المسافرون ما يلزمهم يصلون مع المُتِمِّين، إلا إذا كان واحدٌ يلزمه.","link":"https://binbaz.org.sa/fatwas/22121/حكم-صلاة-الجماعة-في-الحضر-والسفر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث من سمع النداء فليجب هل هو عام للحضر والسفر أم خاص بالحضر.mp3","categories":["شروح الحديث"]},{"id":2014,"question":"التغيير بالسواد؟","title":"ما حكم تغيير الشيب بالسواد؟","answer":"الجواب:\nلا يجوز، يقول النبي ﷺ: غَيِّروا هذا الشيب واجتنبوا السَّوَاد رواه مسلم في الصحيح.\nس: الزيادة في آخر الحديث مدرجة أو من الحديث وجَنِّبوه السَّوَاد؟\nالشيخ: لا، صحيحة متصلة، وقول أنها مدرجة غلط.\nس: من أعلها بتدليس ابن الزبير؟\nالشيخ: لا هذا غلط، الأحاديث متصلة.\nس: حديث: يكون في آخر الزمان قوم يَخْضِبون بالسواد؟\nالشيخ: حديث صحيح عن ابن عباس لا يَرِيحون رائحة الجنة رواه أبو داود والنسائي بإسناد جيد عن ابن عباس.","link":"https://binbaz.org.sa/fatwas/22130/ما-حكم-تغيير-الشيب-بالسواد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/غيروا هذا الشيب واجتنبوا السواد.mp3","categories":["شروح الحديث"]},{"id":2019,"question":"حديث الطاعون يدل على إثبات العدوى بإذن الله؟","title":"هل يدل حديث الطاعون على إثبات العدوى؟","answer":"الجواب:\nيدل على أنها قد تقع، ما هو بلازم العدوى على طريقة الجاهلية، يدل على أن اختلاط المرضى بالأصحاء قد يكون سببًا للمرض، ولهذا قال ﷺ: لا يُورِد مُمْرِضٌ على مُصِحٍّ، وقال: فِرَّ من المجذوم فرارك من الأسد. الأمراض التي جرت العادة بأنها تنتقل لا يُخالَط أهلها من باب وَلَا تُلْقُوا بِأَيْدِيكُمْ إِلَى التَّهْلُكَةِ [البقرة:195]، وليست تُعدِي بطبعها، بل بأمر الله وإذنه جل وعلا، فكم من صحيح خالط المرضى ولم يُصِبْه شيء، والنبي ﷺ أكل في بعض الأحيان مع المجذوم، وقال: كل بسم الله ثقةً بالله. فالمقصود أن وجود الأمراض التي قد تَقَرر وعُلِم أنها تنتقل أمر النبي ﷺ بالبعد عنها، قال: لا يُورِد مُمْرِضٌ على مُصِحٍّ معناه: صاحب الإبل المِراض لا يوردها على صاحب الإبل الصِّحاح، هذا له مورد وهذا له مورد، وهكذا فر من المجذوم فالأمراض التي عرف أنها تنتقل وأنها إذا خالطها الإنسان انتقلت مثل الجَرَب، صاحب الإبل السليمة لا يحطها مع الجرباء.\nس: بالنسبة في فترة الحج أحيانَا يقول: يُطَعَّم كي إذا اختلط بأناس..\nالشيخ: التطعيم ما يخالف، من باب الدواء لا بأس به، التطعيم مثل ما قال ﷺ: مَنْ تصبَّح بسبع تمرات من تمر عجوة لم يضره سحر ولا سُم هذا مثل التطعيم، إذا أكلته من أول الصبح من أسباب السلامة، هذا من جنس التطعيم.","link":"https://binbaz.org.sa/fatwas/22135/هل-يدل-حديث-الطاعون-على-اثبات-العدوى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يدل حديق الطاعون على إثبات العدوى بإذن الله.mp3","categories":["شروح الحديث"]},{"id":2030,"question":"الكفر هنا (في حديث فمَن رَغِبَ عن أَبِيهِ فَهو كُفْرٌ)؟","title":"معنى حديث \"فمَن رَغِبَ عن أَبِيهِ فَهو كُفْرٌ\"","answer":"الجواب:\nكفر أصغر إلا مَن استحلَّه.\nس: في هذا الباب وفي غيره من الأبواب: إذا أطلق الكفر والمراد الكفر الأصغر هل هو أكبر من الكبائر؟\nالشيخ: نعم، عند أهل العلم الشرك الأصغر والكفر الأصغر أكبر من الكبائر، نسأل الله العافية، جنس الكفر أعظم من جنس المعاصي.","link":"https://binbaz.org.sa/fatwas/22146/معنى-حديث-فمن-رغب-عن-ابيه-فهو-كفر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تفسير الكفر في حديث فمن رغب عن أبيه فهو كفر.mp3","categories":["شروح الحديث","مسائل متفرقة في العقيدة"]},{"id":2037,"question":"قوله ﷺ: لا تجعلوا بيوتكم قبورًا يفيد عدم الدفن في البيوت؟","title":"معنى حديث \"لا تجعلوا بيوتكم قبورًا..\"","answer":"الجواب:\nلا، المقصود من ذلك مثل ما في اللفظ الآخر: اجعلوا من صلاتكم في بيوتكم ولا تتخذوها قبورًا؛ لأن القبور ما هي محل صلاة، قال: اجعلوا من صلاتكم في بيوتكم ولا تتخذوها قبورًا القبور لا يُصلى عندها؛ لأن الصلاة عندها وسيلة إلى الشرك، فالصلاة محلها المساجد والبيوت وأما القبور لا، المقابر ما هي محل الصلاة، محل الدعاء لهم والزيارة والدعاء لهم.\nس: الدفن في البيوت؟\nالشيخ: لا، ما ينبغي الدفن في البيوت، لا ما ينبغي، الدفن في المقابر، في الصحراء، كما فعل النبي ﷺ، في المدينة كان يدفن في البقيع وغير البقيع.\nس:... دفن عمر...؟\nالشيخ: هذا النبي ﷺ خافوا عليه من الغلو إذا برز، ودفنوا معه صاحبيه ؛ لخوف الغلو فيهم.","link":"https://binbaz.org.sa/fatwas/22154/معنى-حديث-لا-تجعلوا-بيوتكم-قبورا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بحديث لا تجعلوا بيوتكم قبورًا.mp3","categories":["شروح الحديث"]},{"id":2042,"question":"بالنسبة لإخراج بعث النار؟","title":"معنى \"إخراج بعث النار\" في الحديث","answer":"الجواب:\nبعث النار: من كل ألف تسعمائة وتسعة وتسعون، يأمر الله آدم ويخرج بعث النار من يأجوج ومن غير يأجوج، من يأجوج معهم تسع وتسعون، ومن هؤلاء واحد من بقية الناس، مثل ما قال الله جل وعلا: وَمَا أَكْثَرُ النَّاسِ وَلَوْ حَرَصْتَ بِمُؤْمِنِينَ [يوسف:103]، وَإِنْ تُطِعْ أَكْثَرَ مَنْ فِي الْأَرْضِ يُضِلُّوكَ عَنْ سَبِيلِ اللَّهِ [الأنعام:116] أكثر الخلق على الباطل، ويأجوج ومأجوج كلهم شر، نسأل الله العافية.\nس: هل يدل على أن أهل النار أكثر من أهل الجنة؟\nالشيخ: نعم، ما في شك، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/22159/معنى-اخراج-بعث-النار-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث إخراج بعث النار.mp3","categories":["شروح الحديث"]},{"id":2056,"question":"(حديث \"يتبع الميت..\") حسب علمي: ثلاثة، ويرجع اثنان؟","title":"معنى حديث \"يتبع الميت ثلاثة..\"","answer":"الجواب:\nيرجع اثنان: أهله وماله، ويبقى عمله.\nس: يعني هنا بالعمل يعني...؟\nج: يبقى العمل، لو معه إخوانه وأبوه وأمه ورقيقه، كلهم يرجعون، ما ينفعونه إلا إذا دعوا له واستغفروا، إنما ينفعه عمله الصالح.\nحلوة خضرة: بالنسبة إلى غالب الناس؛ يرتاحون لها، ويتنعَّمون فيها، وهي مذمومة ملعونة، إلا ذكر الله وما والاه، وعالم ومتعلم، لكن بالنسبة إلى أغلب الخلق هي حلوة خضرة عندهم، يُشْغَلُون بها، ويُغَرّون بها -نسأل الله العافية- فليس هناك منافاة، فالصدقة تبقى، والعلم يبقى، وأهله وماله يرجعون، ولا يبقى له إلا ما تصدَّقوا به عنه، أو علم خلَّفه، فإذا تصدَّقوا عنه ودعوا له فهذا ينفعه، فالصدقة تنفع قبل الموت وبعد الموت، كلها تنفع.","link":"https://binbaz.org.sa/fatwas/22174/معنى-حديث-يتبع-الميت-ثلاثة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث يتبع الميت ثلاثة أهله وماله وعمله..mp3","categories":["شروح الحديث"]},{"id":2057,"question":"كيف تكون الدنيا ملعونةً وفيها البهائم والشَّجر؟","title":"ما معنى ما جاء في لَعْن الدنيا؟","answer":"الجواب:\nمعناها: مذمومة، فاللعن هنا الذم، يعني: مذمومة ومذموم ما فيها، إلا ذكر الله وما والاه من طاعة الله جلَّ وعلا، لا بأس به.","link":"https://binbaz.org.sa/fatwas/22175/ما-معنى-ما-جاء-في-لعن-الدنيا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/كيف تكون الدنيا ملعونةً وفيها البهائم والشَّجر.mp3","categories":["شروح الحديث"]},{"id":2059,"question":"قول الرسول ﷺ: أعظم الشرك أن يزني الرجلُ بحليلة جاره. هل يكون الزِّنى من الشرك؟","title":"هل يوصف الزِّنى بالشرك؟","answer":"الجواب:\nهذا أعظم الزنى، ما هو بأعظم الشرك، أن يُزاني بحليلة جاره، وليس أعظم الشرك.\nس: ولا يكون الزِّنى شركًا؟\nج: لا، هذا قرين، فالشرك أولًا، ثم القتل، ثم الزنى بزوجة الجار –نسأل الله العافية- لما قيل: أيُّ الذَّنب أعظم؟ قال: أن تجعل لله ندًّا وهو خلقك، قال: ثم أي؟ قال: أن تقتل ولدك خشية أن يطعم معك، قال: ثم أي؟ قال: أن تُزاني بحليلة جارك، وفي اللفظ الآخر: قال: أكبر الكبائر: الإشراك بالله، ثم عقوق الوالدين، ثم شهادة الزور  نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/22177/هل-يوصف-الزنى-بالشرك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يكون الزنى من الشرك.mp3","categories":["شروح الحديث"]},{"id":2070,"question":"ما معنى \"فَكِلْتُه فَفَنِيَ\"؟","title":"معنى قول عائشة: \"فَكِلْتُه فَفَنِيَ\"","answer":"الجواب:\nيعني: لما كالته فني، أكلوه حتى فني، ومعناه: أنَّ عدم الكيل أحسن، فيأكل مما تيسَّر حتى يفنى.\nس: هل يُؤخَذ بالفعل أن يكون الأفضل عدم الكيل؟\nج: عدم الكيل أحسن، فلا يختبره كل ساعة ويقول: إلى أين وصل؟ لا، يأكل والحمد لله، فيأكل حتى يفنى؛ فهذا أبرك.","link":"https://binbaz.org.sa/fatwas/22188/معنى-قول-عاىشة-فكلته-ففني","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى قول عائشة معنى فكلته ففني.mp3","categories":["شروح الحديث"]},{"id":2078,"question":"هل اللام هنا لام التوكيد: والله إني لأحبُّك؟","title":"ما دلالة اللام في حديث \"والله إني لأحبُّك\"؟","answer":"الجواب:\nلام الابتداء، مثل: وَإِنَّهُ لَتَنْزِيلُ رَبِّ الْعَالَمِينَ [الشعراء:192]، إِنَّهُ لَقَوْلُ رَسُولٍ كَرِيمٍ [الحاقة:40].","link":"https://binbaz.org.sa/fatwas/22196/ما-دلالة-اللام-في-حديث-والله-اني-لاحبك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/اللام في حديث والله إني لأحبُّك.mp3","categories":["شروح الحديث"]},{"id":2079,"question":"النساء أكثر أهل النار، فهل هُنَّ في الجنة أقلّ أم أكثر أيضًا؟","title":"لماذا كانت النساء أكثر أهل النار؟","answer":"الجواب:\nلما سئل ﷺ قال: لأنَّكُنَّ تكفرن العشير، وتُكْثِرْنَ اللَّعن، ومَن صدق منهن فلها الجنة، مثلما قال جلَّ وعلا: إِنَّ الْمُسْلِمِينَ وَالْمُسْلِمَاتِ وَالْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ وَالْقَانِتِينَ وَالْقَانِتَاتِ وَالصَّادِقِينَ وَالصَّادِقَاتِ وَالصَّابِرِينَ وَالصَّابِرَاتِ وَالْخَاشِعِينَ وَالْخَاشِعَاتِ وَالْمُتَصَدِّقِينَ وَالْمُتَصَدِّقَاتِ وَالصَّائِمِينَ وَالصَّائِمَاتِ وَالْحَافِظِينَ فُرُوجَهُمْ وَالْحَافِظَاتِ وَالذَّاكِرِينَ اللَّهَ كَثِيرًا وَالذَّاكِرَاتِ أَعَدَّ اللَّهُ لَهُمْ مَغْفِرَةً وَأَجْرًا عَظِيمًا [الأحزاب:35]، وقال تعالى: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ وَيُقِيمُونَ الصَّلَاةَ وَيُؤْتُونَ الزَّكَاةَ وَيُطِيعُونَ اللَّهَ وَرَسُولَهُ أُولَئِكَ سَيَرْحَمُهُمُ اللَّهُ إِنَّ اللَّهَ عَزِيزٌ حَكِيمٌ  ۝ وَعَدَ اللَّهُ الْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ جَنَّاتٍ تَجْرِي مِنْ تَحْتِهَا الْأَنْهَارُ [التوبة:71- 72]، هؤلاء وهؤلاء: فكل مؤمنٍ ومؤمنةٍ موعود بالجنة، والكافر والكافرة موعودون بالنار، لكن لما كان يكثر في أعمال النساء: كفر العشير، والسّب، واللعن، وعدم الاستقامة على الحق؛ صار أكثرهنَّ إلى النار –نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/22197/لماذا-كانت-النساء-اكثر-اهل-النار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/لماذا النساء أكثر أهل النار.mp3","categories":["شروح الحديث"]},{"id":2081,"question":"قول الرسول ﷺ: فإنَّ الفقر أسرع إلى مَن يُحبُّني دليلٌ على أنَّ أصحاب النبي ﷺ أكثرهم الفقراء؟","title":"معنى حديث \"الفقر أسرع إلى مَن يُحبُّني\"","answer":"الجواب:\nنعم؛ لشُغلهم بعمل الآخرة وطاعة الرسول ﷺ.\nس: ومَن تمسَّك بالسنة؟\nج: مَن تمسَّك بالسنة، وجاهد في الله، واتَّقى الله؛ قد يُصاب بالفقر، لكن ليس معناه أن يترك الأسباب، لكن قد يُشغل بالأعمال الصَّالحة وتقوى الله والجهاد في سبيله عن جمع الدنيا، وعن التَّسبب فيها.","link":"https://binbaz.org.sa/fatwas/22199/معنى-حديث-الفقر-اسرع-الى-من-يحبني","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث فإنَّ الفقر أسرع إلى مَن يُحبُّني.mp3","categories":["شروح الحديث"]},{"id":2085,"question":"في الحديث: اطَّلعتُ في الجنة فرأيتُ أكثر أهلها الفقراء، وذكر ابنُ القيم أنَّ فتنةَ المال أعظمُ من فتنة الضَّراء، يعني: فتنة الفقر؟","title":"هل فتنة المال أعظم من فتنة الفقر؟","answer":"الجواب:\nإِنَّمَا أَمْوَالُكُمْ وَأَوْلَادُكُمْ فِتْنَةٌ [التغابن:15].\nس: هل يُؤخذ من هذا أنَّ الغالب على أهل الطاعة وأهل الصلاح أن يكونوا من الفُقراء ويوجد من الأغنياء؟\nج: هذا الغالب، مثلما كان في الصَّحابة.","link":"https://binbaz.org.sa/fatwas/22203/هل-فتنة-المال-اعظم-من-فتنة-الفقر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/فتنة المال أعظم من فنة الفقر.mp3","categories":["شروح الحديث"]},{"id":2107,"question":"حديث الرسول ﷺ عن الكسب باليد: هل المقصود به الحِرَف، أو كل الأعمال التي تُفْعَل باليد؟","title":"هل \"كَسْبُ اليَدّ\" في الحديث يُقصد به الحِرَف؟","answer":"الجواب:\nكل الأعمال التي تكون باليد، حتى البيع والشراء.","link":"https://binbaz.org.sa/fatwas/22225/هل-كسب-اليد-في-الحديث-يقصد-به-الحرف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث الكسب باليد هل المقصود به الحرف.mp3","categories":["شروح الحديث"]},{"id":2111,"question":"ما معنى قوله ﷺ: يَشْهَدُونَ ولا يُسْتَشَهدون؟","title":"معنى \"يَشْهَدُونَ ولا يُسْتَشَهدون\" في الحديث","answer":"الجواب:\nيعني: يشهدون بالباطل.\nس: تقدَّموا ولم تُطْلَب منهم أصلًا؟\nج: لاـ يعني: يشهدون بغير الحق، ولا يُسْتَشْهدون، بل يشهدون بالباطل، أمَّا مَن كانت عنده شهادة ويُؤدِّيها بحقٍّ: ألا أُنبئكم بخير الشُّهداء؟ الذي يأتي بالشهادة قبل أن يُسألها، إذا كانت عنده شهادةُ حقٍّ وأدَّاها فهو مأجورٌ.\nس: يعني: لأجل ذلك يزهد الناسُ في شهادتهم؛ لأنَّهم أهل خيانةٍ، فلا تُطلب منهم الشَّهادة؟\nج: لا، معناه: أنهم ما استُشْهِدُوا، وما عندهم شهادة، إنما هي خيانة، وشهادة بالزور، إمَّا لمالٍ، أو لصداقةٍ، أو لغير ذلك –نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/22229/معنى-يشهدون-ولا-يستشهدون-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى قوله عليه الصلاة والسلام ولا يستشهدون.mp3","categories":["شروح الحديث"]},{"id":2115,"question":"ما معنى: وكان عَيْشُهُ كَفَافًا؟","title":"معنى \"وكان عَيْشُهُ كَفَافًا\" في الحديث","answer":"الجواب:\nيعني: يكفيه ولا يحتاج معه إلى الناس.","link":"https://binbaz.org.sa/fatwas/22233/معنى-وكان-عيشه-كفافا-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى وكان عيشُه كفافًا.mp3","categories":["شروح الحديث"]},{"id":2117,"question":"ما معنى: طُوبى لمَن هُدِيَ إلى الإسلام؟","title":"ما معنى \"طُوبى لمن هُديَ إلى الإسلام\"؟","answer":"الجواب:\nمثلما تقدم قد أفلح من أسلم، المعنى هدي إلى الإسلام ورُزِقَ كفافًا، وقنَّعه الله بما آتاه، وطوبى: الجنة.","link":"https://binbaz.org.sa/fatwas/22235/ما-معنى-طوبى-لمن-هدي-الى-الاسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى طوبى لمن هدي إلى الإسلام.mp3","categories":["شروح الحديث"]},{"id":2120,"question":"قوله: إنَّك أنْ تُمْسِك الفَضْل شرٌّ لك من أن تنفقه ما زاد عن حاجته؟","title":"معنى \"أنْ تُمْسِك الفَضْل شرٌّ لك\" في الحديث","answer":"الجواب:\nنعم، فكون الإنسان عنده مال وسعة ولا يُنْفِق شرٌّ له، والإنفاق خيرٌ له.","link":"https://binbaz.org.sa/fatwas/22238/معنى-ان-تمسك-الفضل-شر-لك-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى إنك أن تمسك الفضل شر لك من أن تنفقه ما زاد عن حاجته.mp3","categories":["شروح الحديث"]},{"id":2126,"question":"نهي الرسول ﷺ للصحابة عن قولهم: أنت سيدنا، بأن قال: إنما السيد الله، كيف نجمع بينه وبين قوله ﷺ: أنا سيد ولد آدم ولا فخر؟","title":"الجمع بين حديثي \"سيد ولد آدم\" و\"السيد الله\"","answer":"الجواب:\nقال لهم هذا لئلا يجرّهم إلى الغلو، فقد خاف عليهم الغلو، قال: قولوا بقولكم أو ببعض قولكم، ولا يَسْتَهْوِيَنَّكم الشيطان، أما بعد موته ما عاد يستهوي...\nس: أيضًا لم يكن يُخبر بأنه سيد ولد آدم؟\nج: هو سيد ولد آدم، لكن كره أن يُشافهوا بهذا في حياته ﷺ، خاف عليهم من الغلو.","link":"https://binbaz.org.sa/fatwas/22244/الجمع-بين-حديثي-سيد-ولد-ادم-والسيد-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الجمع بين حديث النهي عن قول أنت سيدنا وحديث أنا سيد ولد آدم ولا فخر.mp3","categories":["شروح الحديث"]},{"id":2135,"question":"ما معنى : \"ثم قال فيه رسولُ الله ﷺ ما شاء الله أن يقول\" (للطعام)؟","title":"ما المشروع من الدعاء على الطعام؟","answer":"الجواب:\nيعني: دعا فيه بالبركة: بارك الله في الخبز، بارك الله في اللَّحم.\nس: هل يُؤخَذ من ذلك أنَّ من السنة أن ندعو على الطعام؟\nج: يُدْعَى، فإذا دعا وقال: اللهم بارك لنا فيه، اللهم اجعله مباركًا؛ فكله طيب.\nس: وإذا قرأ القرآن: كالفاتحة وآية الكرسي؟\nج: لا، له أن يدعو.","link":"https://binbaz.org.sa/fatwas/22253/ما-المشروع-من-الدعاء-على-الطعام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الدعاء في الطعام بالبركة.mp3","categories":["شروح الحديث"]},{"id":2137,"question":"في حديث النبي ﷺ: طعام الواحد يكفي الاثنين، وطعام الاثنين .. إلى آخر الحديث؟","title":"معنى حديث \"طعام الواحد يكفي الاثنين..\"","answer":"الجواب:\nصحيح، نعم.\nس: فإن دعا الإنسانُ مجموعةً من الناس، وفي نظره أنه في عصره...؟\nج: إذا كان طعام أربعة ودعا ثمانيةً يكفيهم، وإذا كان طعام عشرةٍ ودعا عشرين ما يُخالف.\nس: وإذا توكَّل ودعا أكثر هل يكون محمودًا؟\nج: إذا دعت الحاجةُ لا بأس، يسأل الله فيه البركة، والحمد لله.","link":"https://binbaz.org.sa/fatwas/22255/معنى-حديث-طعام-الواحد-يكفي-الاثنين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث طعام الواحد يكفي الاثنين..mp3","categories":["شروح الحديث"]},{"id":2143,"question":"ما معنى قولهﷺ: ولكن إنما أُعطي أقوامًا لما أرى في قلوبهم من الجزع والهلع؟","title":"معنى إعطائه ﷺ لمَن في قلوبهم جزع","answer":"الجواب:\nالجزع، وهو شدة الحرص على المال، ويدع آخرين لما يرى في قلوبهم من الغنى والسّعة، فبعض الناس ما عنده مال، ولكنه غني القلب، كما تقدم: ليس الغنى عن كثرة العَرَضِ، ولكن الغنى غنى النفس، فبعض الناس فقيرٌ ولكن قلبه غني، ما عنده جزع، ولا حرص، ولا جشع، فهو غني القلب.","link":"https://binbaz.org.sa/fatwas/22262/معنى-اعطاىه-ﷺ-لمن-في-قلوبهم-جزع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى قوله ولكن إنما أُعطي أقوامًا لما أرى في قلوبهم من الجزع والهلع.mp3","categories":["شروح الحديث"]},{"id":2154,"question":"كيف نجمع بين حديث: أي الإسلام خير؟ والحديث الذي فضَّل فيه النبيُّ ﷺ الإيمان، ثم الصلاة، والجهاد، وبرّ الوالدين .. إلخ، فأي الأعمال أفضل؟","title":"ما الصحيح في أفضل الأعمال؟","answer":"الجواب:\nالظاهر أنه لا منافاة، فهذا في التَّطوعات، وهذا في الفرائض، لما سُئل: أي العمل أفضل؟ قال: الصلاة على وقتها، قلتُ: ثم أي؟ قال: برّ الوالدين، قلت: ثم أي؟ قال: الجهاد في سبيل الله، وفي حديث أبي ذرٍّ لما سئل: أي الإسلام أفضل؟ قال: إيمانٌ بالله، وجهادٌ في سبيله، فالألفاظ متنوعة، فلا شكَّ أنَّ أفضلها الإيمان بالله والجهاد في سبيله، ومن الإيمان: الصَّلوات الخمس، وكذلك الجهاد من الإيمان، وهو داخلٌ في قوله: إيمانٌ بالله، وجهادٌ في سبيله، والصلاة من أعظم خِصال الإيمان، وعتق الرِّقاب من خصال الإيمان كذلك، وبذل السلام، وإطعام الطعام من خصال الإيمان، فقد يكون واجبًا، وقد يكون مستحبًّا، فهو يختلف، قد يكون إطعامُ الطعام واجبًا عند الحاجة، وقد يكون مستحبًّا، وإفشاء السلام: البدء به مستحبٌّ، وقال بعض أهل العلم بوجوبه، وردّ السلام واجبٌ، فكل هذا خيرٌ، المهم أنه من باب تنويع الأعمال.","link":"https://binbaz.org.sa/fatwas/22273/ما-الصحيح-في-افضل-الاعمال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الجمع بين حديث أي الإسلام خير والحديث الذي فضَّل فيه النبيُّ ﷺ الإيمان، ثم الصلاة..mp3","categories":["شروح الحديث"]},{"id":2157,"question":"ما المقصود بالتَّلَف في قوله: أَعْطِ مُمْسِكًا تَلَفًا؟","title":"معنى \"أَعْطِ مُمْسِكًا تَلَفًا\" في الحديث","answer":"الجواب:\nيُخشى أن ينزع اللهُ البركةَ من ماله ويُتلفه عليه بأنواع الإتلاف –نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/22276/معنى-اعط-ممسكا-تلفا-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بالتَّلَف في قوله أَعْطِ مُمْسِكًا تَلَفًا.mp3","categories":["شروح الحديث"]},{"id":2160,"question":"ما المراد بصلة الرّحم في الأحاديث؟","title":"ما المراد بصلة الرّحم في الأحاديث؟","answer":"الجواب:\nصلة الرحم تعني: القرابات، فكل القرابات رحم، وأقربهم: الآباء، والأمهات، والأولاد، وأولادهم.\nس: لو أنَّ أهله في بلدٍ ثانٍ وأراد أن يصلهم؟\nج: يصلهم ولو في بلدٍ ثانٍ، يصلهم بالمكاتبة وإرسال الهدية والمساعدة.\nس: يعني: يكفي أن يُرسِل لهم؟\nج: البُرُد موجودة.","link":"https://binbaz.org.sa/fatwas/22281/ما-المراد-بصلة-الرحم-في-الاحاديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المراد بصلة الرّحم في الأحاديث.mp3","categories":["شروح الحديث"]},{"id":2165,"question":"جاء في الحديث: وعبد لم يُعطه الله مالًا ولا علمًا، فهو يقول: لو أنَّ لي مالًا لعملتُ فيه بعمل فلانٍ، فهو بنيَّته هل يأثم الرجلُ بنيته فقط؟","title":"متى يأثم الإنسان بنيته فقط؟","answer":"الجواب:\nبنيَّته الخبيثة.\nس: يأثم؟\nج: نعم بنيَّته الخبيثة، هذا ظاهر الحديث، يقول: لو أنَّ لي مالًا مثل فلانٍ لعملتُ مثل عمله.\nس: وكيف نقول في الحديث الآخر، وهو قول الرسول ﷺ ..؟\nج: إذا همَّ بسيئةٍ فلم يعملها لم تكتب، هذا له نيَّة صادقة أو قويّة، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/22286/متى-ياثم-الانسان-بنيته-فقط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/النية الصالحة والنية الخبيثة في العمل.mp3","categories":["شروح الحديث"]},{"id":2172,"question":"كيف يكون الجمع بين حديث الدرس السابق؛ وهو قول الرسول ﷺ: وعبد لم يرزقه الله مالًا ولا علمًا فهو يقول: لو أنَّ لي مالًا لعملتُ فيه بعمل فلان، فهو بنيته، ووزرهما سواء، وقوله ﷺ: إنَّ الله تجاوز عن أمتي ما حدَّثَتْ به أنفسها ما لم تعمل به أو تكلَّم؟","title":"حكم مَن ينوي الإنفاق في الخير لو تيسّر المال","answer":"الجواب:\nحديث الوساوس ما يضرّ، وليس عليه عمل، أما هذا فهو عازمٌ صادقٌ: لو كان له مِثْل فلان، فقد علم، وليس الأمر وسوسةً، عزمٌ وصدقٌ.\nس: يعني: النَّوايا في الخير تُكتب؟\nج: نوايا الخير تُكتب له إذا كان صادقًا.","link":"https://binbaz.org.sa/fatwas/22293/حكم-من-ينوي-الانفاق-في-الخير-لو-تيسر-المال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الجمع بين حديث وعبد لم يرزقه الله مالًا ولا علمًا.. وحديث إنَّ الله تجاوز عن أمتي ما حدَّثَتْ به أنفسها..mp3","categories":["شروح الحديث"]},{"id":2179,"question":"حديث: ولا تتنافسوا، ولا تحاسدوا؟","title":"معنى حديث \"ولا تتنافسوا ولا تحاسدوا\"","answer":"الجواب:\nالمقصود التنافس في الحسد، وليس التنافس في الخير، يعني: تنافسوا ولا تحاسدوا.","link":"https://binbaz.org.sa/fatwas/22300/معنى-حديث-ولا-تتنافسوا-ولا-تحاسدوا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بالتنافس في حديث ولا تتنافسوا، ولا تحاسدوا.mp3","categories":["شروح الحديث"]},{"id":2182,"question":"إذا حسد الشخصُ في غير هاتين الخصلتين (المذكورتين في حديث \"لا حسد إلا في اثنتين..\" القرآن والحكمة)، فما حكمه؟","title":"معنى حديث \"لا حسد إلا في اثنتين..\"","answer":"الجواب:\nحسد الغبطة لا بأس به، كأن يحسده في اتِّباع الجنائز، أو في كثرة الحج، فلا يضرّ.  والحسد الممنوع هو: أن يتمنى زوال النّعمة عنه، هذا هو الحسد المذموم الذي قال فيه جلَّ وعلا: وَمِنْ شَرِّ حَاسِدٍ إِذَا حَسَدَ [الفلق:5]، فيتمنى أن تزول النّعمةُ عن أخيه. أمَّا كونه يتمنى أن يكون مثله، ويحرص على أن يكون مثله؛ فكله خير، سواء في القرآن، أو في الحج، أو في الصيام، أو في الصّدقات، أو في المشاريع الأخرى الخيرية.\nس: هل الحسد معصية؟\nج: الحسد من أقبح السيئات، ومن خصال اليهود –نعوذ بالله.","link":"https://binbaz.org.sa/fatwas/22304/معنى-حديث-لا-حسد-الا-في-اثنتين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/لا حسد إلا في اثنتين.. إذا حسد الشخصُ في غيرها.mp3","categories":["شروح الحديث"]},{"id":2183,"question":"ما جاء عن رسول الله ﷺ..... أنَّ مَن لم يكن له مال ويتمنى لو أنَّ عنده مالًا لأنفقه في الشرّ كُتبت عليه سيئات، وفي الحديث الآخر إذا همَّ بالسيئة ولم يعملها لم تُكتب عليه؟","title":"حكم مَنْ ينوي المعصية لو تمكّن منها","answer":"الجواب:\nإذا همَّ بها ولم يعملها ما تُكتب عليه، وإن تركها من أجل الله صارت حسنة، وإذا همَّ بالصدقة ولم يعملها صارت حسنةً واحدةً، فإن عمل صارت عشر حسناتٍ إلى أضعافٍ كثيرةٍ.\nس: الذي في هذا: رجل ما عنده مال ويتمنى أن لو كان عنده مال لفسق وعصى؟\nج: على نيته الخبيثة –نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/22305/حكم-من-ينوي-المعصية-لو-تمكن-منها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الهم بالعمل السيء.mp3","categories":["شروح الحديث"]},{"id":2186,"question":"فاطمة بنت قيس حين سألت النبيَّ عليه الصلاة والسلام أنَّ معاوية خطبها فقال: إنَّه رجلٌ صعلوكٌ، ألا يتنافى هذا مع حديث: إذا أتاكم مَن ترضون خُلُقَه ودِينَه فزَوِّجوه؟","title":"حكم التنبيه على عيوب المُتَقَدِّم لخطبة امرأة","answer":"الجواب:\nلا، هذا من باب النصيحة، فهي تستشير النبي ﷺ، فيقول لها: إنه صعلوك لا مال له، فقد يضرها كونه ما عنده مال، وأما أبو جهم فلا يضع عصاه عن عاتقه، ضَرَّابٌ للنساء، فالمستشار مؤتمن، يُشير بما يعلم، ولا يُسَمَّى هذا: غيبة، ولا يُسَمَّى: غِشًّا.\nس: لا، كونه رجلًا صعلوكًا هل هذا يكون عيبًا؟\nج: لا، المعنى أنه ما عنده شيء يُنفقه عليها.","link":"https://binbaz.org.sa/fatwas/22309/حكم-التنبيه-على-عيوب-المتقدم-لخطبة-امراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الجمع بين حديث إنَّه رجلٌ صعلوكٌ، وحديث إذا أتاكم مَن ترضون..mp3","categories":["شروح الحديث"]},{"id":2190,"question":"ما المقصود بقوله: هل تنتظرون إلا فقرًا مُنْسِيًا؟","title":"معنى حديث \"هل تنتظرون إلا فقرًا مُنْسِيًا\"","answer":"الجواب:\nيعني: ما يدري الإنسان: قد ينزل به الفقر فيُنسيه كلَّ شيءٍ، أو غنى يُطغيه، أو مرض يُفسد عليه قوته، أو موت يُنجزه، يعني: يهجم عليه الأجل، أو هرم يجعله يكبر ويتفنّد ولا يتمكن معه من العمل بسبب ضياع العقل.\nس: والدّجال؟\nج: شرُّ غائبٍ يُنْتَظر، فخطره عظيم إذا حضر –نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/22313/معنى-حديث-هل-تنتظرون-الا-فقرا-منسيا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بحديث هل تنتظرون إلا فقرًا مُنْسِيًا..mp3","categories":["شروح الحديث"]},{"id":2199,"question":"قوله ﷺ عند موته: اللهم الرفيق الأعلى هل يُستدل به على جواز تمني الموت أم أنه خاصّ بالنبي؟","title":"هل يجوز للمؤمن تَمَنِّي الموت؟","answer":"الجواب:\nهذا إن وجد علاماته يقول: اللهم الرفيق الأعلى، يعني: الجنة، أي: اللهم أدخلني الجنة، حتى لو كان حيًّا له أن يقول هذا: اللهم أدخلني الجنة، اللهم اجعلني مع الرفيق الأعلى، ولو كان صحيحًا.\nس: قوله: بعلمك الغيب؟\nج: هذا مُعلَّق، ما هو تمنٍّ مطلق: اللهم بعلمك الغيب، مثلما في الحديث: اللهم أحيني إذا كانت الحياة خيرًا لي، وتوفني إذا كانت الوفاةُ خيرًا لي، أما التَّمني فأن يقول: ربي أمتني، ليتني أموت، فيُطْلِق، أمَّا إذا علَّق فليس فيه شيء.\nس: في ترجمة النووي أن تمني الموت مخافة الفتنة في الدين لا بأس به؟\nج: ليس عليه دليل واضح، والأحاديث عامَّة، فإذا قال: اللهم أحيني إذا كانت الحياة خيرًا لي، وتوفني إذا كانت الوفاة خيرًا لي؛ فهذا كافٍ والحمد لله، في الفتن، وفي غير الفتن.","link":"https://binbaz.org.sa/fatwas/22322/هل-يجوز-للمومن-تمني-الموت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث اللهم الرفيق الأعلى هل يُستدل به على جواز تمني الموت.mp3","categories":["شروح الحديث"]},{"id":2215,"question":"ما نقصت صدقةٌ من مال هل المقصود زيادةٌ في نفس المال أم الأجر؟","title":"معنى حديث \"ما نقصت صدقةٌ من مال\"","answer":"الجواب:\nالأجر والبركة في المال والخَلَف: وَمَا أَنْفَقْتُمْ مِنْ شَيْءٍ فَهُوَ يُخْلِفُهُ [سبأ:39] يأتيه الخَلَف وهو ما يدري من بعض الجهات الأخرى، فيُخْلِف الله عليه في الدنيا، ويأجره في الآخرة.","link":"https://binbaz.org.sa/fatwas/22338/معنى-حديث-ما-نقصت-صدقة-من-مال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بحديث ما نقصت صدقةٌ من مال..mp3","categories":["شروح الحديث"]},{"id":2216,"question":"هل يُؤخذ من حديث أبي رفاعة أن الإمام إذا دعت الحاجةُ لا بأس أن يقطع خطبته؟","title":"حكم قطع الإمام خطبة الجمعة لحاجة","answer":"الجواب:\nنعم، يقطعها لحاجةٍ عارضةٍ ويُتمّها، كإرشاد إنسانٍ على خطر، وإنكار منكرٍ، وغير ذلك، مثلما كان يخطب ﷺ فدخل إنسانٌ فجلس، فقال له: قم، فصلِّ ركعتين.","link":"https://binbaz.org.sa/fatwas/22339/حكم-قطع-الامام-خطبة-الجمعة-لحاجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث انْتَهَيْتُ إِلى رَسولِ اللَّه وَهُوَ يَخْطُبُ فقلتُ يَا رسولَ اللَّه.. هل يجوز أن يقطع الإمام خطبة الجمعة.mp3","categories":["صلاة الجمعة","شروح الحديث"]},{"id":2223,"question":"هل يأثم إذا سقطت اللقمةُ ولم يأخذها؟","title":"هل يأثم مَن لا يأخذ اللقمةُ إذا سقطت؟","answer":"الجواب:\nالأفضل أن يأخذها ويُميط ما بها من الأذى ويأكلها؛ إرغامًا للشيطان.\nس: يقول: هل يأثم إذا تركها؟\nج: يَحْتَمِل، والله أعلم.","link":"https://binbaz.org.sa/fatwas/22346/هل-ياثم-من-لا-ياخذ-اللقمة-اذا-سقطت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من حديث إِذَا سَقطَتْ لُقْمَةُ أَحَدِكُمْ فَلْيُمِطْ عَنْها الأَذى.. هل يأثم إذا سقطت اللقمةُ ولم يأخذها.mp3","categories":["شروح الحديث"]},{"id":2227,"question":"حديث أبي هريرة: لا ينظر الله إلى مَن جرَّ إزاره بطرًا ما معنى بطرًا؟","title":"معنى الوعيد في \"مَن جرَّ إزاره بطرًا\"","answer":"الجواب:\nوعيدٌ يُفيد الحذر.\nس: معنى بَطَرًا؟\nج: تكبُّرًا.","link":"https://binbaz.org.sa/fatwas/22350/معنى-الوعيد-في-من-جر-ازاره-بطرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث لا ينظر الله إلى مَن جرَّ إزاره بطرًا، ما معنى بطرًا.mp3","categories":["شروح الحديث"]},{"id":2228,"question":"لماذا اختصَّ الشيخ في الحديث: شيخٌ زانٍ؟","title":"لماذا اختصَّ الشيخ في حديث \"شيخٌ زانٍ\"؟","answer":"الجواب:\nهذا يُفيد أن الشباب قد يُطغيه شبابه ويغُرّه، لكن إذا اعتاد هذا الشرَّ وهذا الفسادَ شيخٌ شيبةٌ يكون إثمه أكبر -نسأل الله العافية-. كذلك العائل المُسْتَكْبِر، فالتّكبر يكون من الغني، لكن كونه يأتي من العائل يجعله أشد إثمًا؛ لعدم وجود ما يدعوه إلى ذلك -نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/22351/لماذا-اختص-الشيخ-في-حديث-شيخ-زان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/لماذا اختصَّ الشيخ في الحديث شيخٌ زانٍ.mp3","categories":["شروح الحديث"]},{"id":2232,"question":"صيام شعبان يكون كاملًا أو نصفه؟","title":"هل السُّنة صومُ شعبان كله أو بعضه؟","answer":"الجواب:\nيصوم أكثره أو كله، فقد كان عليه الصلاة والسلام يصوم أكثره أو كله إلا قليلًا.\nس: والقول بأن يصوم الخمسة عشر الأولى من بداية شعبان؟\nج: لا، يصوم أكثره أو كله، هذه السنة.\nس: إذا تابع الصيامَ من أوله هل له أن يصله برمضان أم يفطر يومًا أو يومين بينهما؟\nج: إن أفطر بينهما حسن، وإلا فله، تقول أم سلمة: \"كان يصومه كله\"، وفي روايةٍ عن عائشة: \"كان يصومه كله\".","link":"https://binbaz.org.sa/fatwas/22355/هل-السنة-صوم-شعبان-كله-او-بعضه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صيام شهر شعبان.mp3","categories":["شروح الحديث","صيام التطوع"]},{"id":2236,"question":"حديث رؤوسهنَّ كأَسْنِمَة البُخْت ما المراد بذلك؟","title":"معنى \"رؤوسهنَّ كأَسْنِمَة البُخْت\" في الحديث","answer":"الجواب:\nذكر العلماء أنهم يُعظِّمونها بالخِرَق وغيرها حتى تكون عظيمةً مثل أسنمة البخت، فتكون عريضةً وواسعةً؛ لأن أسنمة البُخْت مثل السنامين.\nس: طيب، هناك ما تفعله بعضُ النّساء الآن مما يكون مُرتفعًا؛ تسريحات تكون مرتفعةً فوق الرأس، فهل تدخل في هذا الحديث؟\nج: الشيء اليسير ليس داخلًا، ما تكون مثل أسنمة البُخْت، فأسنمة البُخْت عظيمة مثل السنامين.","link":"https://binbaz.org.sa/fatwas/22359/معنى-رووسهن-كاسنمة-البخت-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المراد بحديث رؤوسهنَّ كأَسْنِمَة البُخْت.mp3","categories":["شروح الحديث"]},{"id":2238,"question":"قوله ﷺ: أقربكم مني مجلسًا يوم القيامة هل هذا في الجنة؟","title":"معنى حديث \"أقربكم مني مجلسًا يوم القيامة\"","answer":"الجواب:\nيحتمل هذا، ويحتمل أنه في الموقف، والأقرب أنه في الموقف يوم القيامة.","link":"https://binbaz.org.sa/fatwas/22361/معنى-حديث-اقربكم-مني-مجلسا-يوم-القيامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أين يكون القرب في حديث أقربكم مني مجلسًا يوم القيامة.mp3","categories":["شروح الحديث","الحكم على الأحاديث"]},{"id":2262,"question":"ما معنى قوله: تُسفّهم المَلَّ؟","title":"معنى \"تُسفّهم المَلَّ..\" في الحديث","answer":"الجواب:\nالتّراب، وفي الحديث: أنه كانت له قرابةٌ يصلهم ويقطعونه، ويَحْلُم عليهم ويجهلون عليه، ويُحسن إليهم ويُسيئون إليه، فقال له رسولُ الله ﷺ: إن كنتَ كما قلتَ فكأنما تُسفّهم المَلَّ يعني: الرماد الحامي ولا يزال معك من الله ظَهيرٌ عليهم ما دمتَ على ذلك، ومن هذا الحديث الآخر: يقول ﷺ: ليس الواصلُ بالمُكافئ، ولكن الواصلَ الذي إذا قُطِعت رحمُه وصلها، هذا الواصل الكامل، الذي لا يُقابلهم بالقطيعة، بل إذا قطعوا وصلهم وأحسن إليهم، ولم يُكافئهم على قطيعتهم بالقطيعة.\nس: مَن أكثر عليه قرابته بما يُؤذيه وهو لا يتحمّل، هل له أن يبتعد عنهم؟\nج: عليه أن يتحمّل ويصبر، ويصلهم بالإحسان، والدعوة إلى الله، والأمر بالمعروف، والنّهي عن المنكر، ولا يكون مثلهم.\nس: إذا كانت للرجل قرابةٌ يُجاهرون بالمعاصي؟\nج: يُنكر عليهم وينصحهم؛ لعلَّ الله يهديهم بأسبابه، فإذا لم ينفع فيهم استحقُّوا الهجر.\nس: الوالدان لا تَرِد فيهما المقاطعة والهجر في النهاية؟\nج: لا، ينصحهم ولا يهجرهم، ينصحهم بالكلام الطّيب.","link":"https://binbaz.org.sa/fatwas/22385/معنى-تسفهم-المل-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى تُسفّهم المَلَّ في الحديث.mp3","categories":["شروح الحديث"]},{"id":2271,"question":"رجلٌ اعتاد صيامَ ثلاثة أيامٍ من كل شهرٍ -الثلاثة أيام البيض- والثلاثة الأيام هذه سافر، فيقول: هل إذا رجع يصوم ثلاثة أيام في نهاية شهر شعبان؟","title":"حكم الصوم آخر شعبان لمن فاته صوم اعتاده","answer":"الجواب:\nما هو بلازمٍ، لا، هي سنة فات محلُّها، وإذا صامها في بقية الأيام لا بأس، ما هو من أجل رمضان، وإنما صامها من أجل أنه يصوم ثلاثة أيام من كل شهرٍ، فلا بأس ولا حرج، مثلما قال ﷺ: لا تقدموا رمضان بصوم يومٍ أو يومين، إلا أن يكون صومٌ يصومه أحدُكم، فإذا كان يصوم الثلاثة أيام البيض وفاتته وأحبَّ أن يصومها فلا بأس.","link":"https://binbaz.org.sa/fatwas/22394/حكم-الصوم-اخر-شعبان-لمن-فاته-صوم-اعتاده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/اعتاد صيامَ ثلاثة أيامٍ من كل شهرٍ وسافر فهل يصوم نهاية شعبان.mp3","categories":["شروح الحديث","صيام التطوع"]},{"id":2274,"question":"ما معنى: تُصلُّون عليهم، ويُصلُّون عليكم؟","title":"معنى حديث \"تُصلُّون عليهم ويُصلُّون عليكم\"","answer":"الجواب:\nتدعون لهم، ويدعون لكم، فالصلاة: الدعاء، فمن محبَّتهم لهم يدعون لهم دائمًا، والأئمة يدعون للرعية، ضد اللعن، وضد تُبغضونهم ويُبغضونكم، وتسبُّونهم ويسبُّونكم.","link":"https://binbaz.org.sa/fatwas/22397/معنى-حديث-تصلون-عليهم-ويصلون-عليكم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى تُصلُّون عليهم، ويُصلُّون عليكم.mp3","categories":["شروح الحديث"]},{"id":2280,"question":"ما المقصود بـ مَن خلع يدًا...؟","title":"معنى قوله ﷺ: \"مَن خَلَع يدًا مِن طاعة\"","answer":"الجواب:\nيعني: ما يسمع ويُطيع، يعني: يُخالفهم في الأوامر، مثلًا يقولون له: لا تُخالف الطريق، امشِ على التَّعليمات في الطريق، ويُخالفهم، أو يأمرونه بما أمر الله به ويُخالفهم، وهكذا.","link":"https://binbaz.org.sa/fatwas/22403/معنى-قوله-ﷺ-من-خلع-يدا-من-طاعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بقوله مَن خلع يدًا.mp3","categories":["شروح الحديث"]},{"id":2281,"question":"ما الصَّحيح في معنى تقارب الزمان وآخر الزمان؟ أهو سرعة الأيام؟","title":"ما معنى \"تقارب الزمان\" في الحديث؟","answer":"الجواب:\nالظاهر: نزع البركة -والله أعلم.\nس: أليس المقصود سرعة الأيام؟\nج: الأيام هي هي.","link":"https://binbaz.org.sa/fatwas/22404/ما-معنى-تقارب-الزمان-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى تقارب الزمان.mp3","categories":["شروح الحديث"]},{"id":2282,"question":"قوله: الإثم: ما حاك في نفسك؟","title":"معنى حديث \"الإثم ما حاك في نفسك\"","answer":"الجواب:\nهذا معناه: الذي تشتبه عليه الأمور، والإثم: ما حاك في نفسه، يعني: صدره، فاشتبه عليه أهو حلال، أو حرام يتركه؟ حتى يتبين أمره.\nس: اللفظة: \"صدرك\" أم \"نفسك؟\nج: المعروف في الحديث: ما حاك في نفسك.","link":"https://binbaz.org.sa/fatwas/22405/معنى-حديث-الاثم-ما-حاك-في-نفسك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الإثم ما حاك في نفسك.mp3","categories":["شروح الحديث"]},{"id":2285,"question":"(معنى حديث): وسيُصيب آخرها بلاءٌ وأمورٌ تُنكرونها؟","title":"معنى \"سيُصيب آخرها بلاءٌ وأمورٌ تُنكرونها\"","answer":"الجواب:\nمثلما وقع.\nس: يُعرف من هذا أنه في آخر الزمان يقع هذا؟\nج: نعم، وقد مضى قبلُ؛ فمضى في دولة بني العباس ودولة بني أمية أمورٌ عظيمة.\nس: يعني: ما يُشترط أن يكون في آخر الزمان؟\nج: كلها آخر الزمان، فما بعد السلف هو آخر الزمان، ما بعد القرون المفضلة الثَّلاثة.","link":"https://binbaz.org.sa/fatwas/22408/معنى-سيصيب-اخرها-بلاء-وامور-تنكرونها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث وسيُصيب آخرها بلاءٌ وأمورٌ تُنكرونها.mp3","categories":["شروح الحديث"]},{"id":2287,"question":"الجماعة إذا خرجوا في سفرٍ وأمَّروا أميرًا، فهل يدخل في قول الرسول ﷺ: مَن أطاعني فقد أطاع الله؟","title":"هل يشمل وجوبُ طاعة الأمير أميرَ السفر؟","answer":"الجواب:\nنعم يدخل فيه، فالمقصود من تأميره السمع والطاعة؛ حتى يتم أمرُهم ويسيروا مُطمئنين.","link":"https://binbaz.org.sa/fatwas/22410/هل-يشمل-وجوب-طاعة-الامير-امير-السفر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مَن أطاعني فقد أطاع الله فهل يدخل فيه أمير السفر.mp3","categories":["شروح الحديث"]},{"id":2290,"question":"كيف يمكن الجمعُ بين قول يوسف عليه السلام: اجْعَلْنِي عَلَى خَزَائِنِ الْأَرْضِ [يوسف:55]، وقول الرسول ﷺ: لا تسأل الإمارة؟","title":"الجمع بين موقف يوسف وعدم طلب الإمارة","answer":"الجواب:\nهذا إذا دعت المصلحةُ، وشَرْعُ مَن قبلنا شرعٌ لنا ما لم يأتِ شرعُنا بخلافه، فشرعنا جاء بالنَّهي عن تولي الخلافة، لكن ذكر العلماء أنه إذا تعيَّنت عليه واحتِيج إليه فلا بأس إذا رأى المصلحة في ذلك، لا للعلو في الأرض، ولا للفساد، ولا للطمع، ولكن لمصلحة المسلمين؛ تأسِّيًا بيوسف عليه الصلاة والسلام.\nس: وإذا رأى الرجلُ في نفسه أنه كفؤٌ لهذا؟\nج: إذا رأى المصلحة للمسلمين، وليس لنفسه هو، والأحوط أن لا يسأل.\nس: نهيه ﷺ لأبي ذرٍّ  ألا يدل على أنَّ هذا عامٌّ في الموظف الصَّغير أو الإمارة الكبيرة؟\nج: لا تُوَلَّيَنَّ مال يتيمٍ؛ هذا اليتيم، والإمارة لا تَأَمَّرَنَّ على اثنين؛ فيصير أميرًا.\nس: يعني: هو عامٌّ أم خاصٌّ فقط؟\nج: لا، ينبغي للضعيف أن يحذر حتى لا يضرَّ نفسه، ولا يضرَّ الناس.\nس: أليس كلام يوسف عليه السلام شرع مَن قبلنا؟\nج: شرعٌ لنا ما لم يأتِ شرعُنا بخلافه، وشرعنا نهى عن سؤال الإمارة.\nس: وهو شرع مَن قبلنا أليس كذلك؟\nج: شرع مَن قبلنا ما لم يأتِ شرعُنا بخلافه.","link":"https://binbaz.org.sa/fatwas/22413/الجمع-بين-موقف-يوسف-وعدم-طلب-الامارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الجمع بين قوله تعالى اجْعَلْنِي عَلَى خَزَائِنِ الْأَرْضِ، وقول الرسول لا تسأل الإمارة.mp3","categories":["التفسير","شروح الحديث"]},{"id":2341,"question":"قول الرسول ﷺ هنا: وليؤمّكم أكبرُكم؟","title":"معنى حديث \"وليؤمّكم أكبرُكم\"","answer":"الجواب:\nيعني: سنًّا؛ لأنَّهم كانوا شَبَبَةً مُتقاربين في العلم، قال: \"كنا شَبَبَة متقاربين\"، فلهذا قال: يؤمّكم أكبرُكم؛ لأنَّهم إذا تساووا في القراءة والعلم يؤمّهم أكبرهم.","link":"https://binbaz.org.sa/fatwas/22465/معنى-حديث-وليومكم-اكبركم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بحديث وليؤمّكم أكبرُكم.mp3","categories":["شروح الحديث"]},{"id":2342,"question":"حديث عائشة رضي الله عنها أنها كانت تقول: \"كان عليَّ الصومُ من رمضان، فلا أقضيه إلا في شعبان\"، ما العِلَّة من تأخيرها؟","title":"ما علة تأخير عائشة قضاء الصوم إلى شعبان؟","answer":"الجواب: تقول: \"لمكان رسول الله ﷺ\"؛ لأجل اتِّصالها بالرسول وحاجته منها.\nس: لو أخَّره لغير حاجةٍ إلى شعبان؟\nج: ما فيه بأس، ما بين رمضان إلى رمضان لا بأس.\nس: لو أخَّره بعد رمضان؟\nج: ما يجوز، أفتى جماعةٌ من الصَّحابة أنَّ عليه مع القضاء إطعامَ مسكينٍ عن كلِّ يومٍ.","link":"https://binbaz.org.sa/fatwas/22466/ما-علة-تاخير-عاىشة-قضاء-الصوم-الى-شعبان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/العلة في تأخير عائشة قضاء الصوم إلى شعبان.mp3","categories":["شروح الحديث","قضاء الصيام"]},{"id":2355,"question":"\"مَن ترك شيئًا لله عوَّضه الله خيرًا منه\" هل هذا حديث؟","title":"هل صح حديث \"مَن ترك شيئًا لله عوَّضه..\"؟","answer":"الجواب:\nجاء بمعناه: مَن ترك شيئًا اتِّقاء الله عوَّضه الله خيرًا منه، وهو بمعنى: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا [الطلاق:2].","link":"https://binbaz.org.sa/fatwas/22480/هل-صح-حديث-من-ترك-شيىا-لله-عوضه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مَن ترك شيئًا لله عوَّضه الله خيرًا منه.mp3","categories":["شروح الحديث"]},{"id":2358,"question":"ما معنى قوله: ليس منا؟ (في حديث مَن لم يَتَغَنَّ بالقرآن فليس منا)","title":"معنى حديث \"مَن لم يَتَغَنَّ بالقرآن فليس منا\"","answer":"الجواب:\nوعيد، ظاهره الوعيد، يدل على أنه يجب العناية بالقرآن، بهذا الصيغة صيغة الوعيد تدل على الوجوب، وتقدم حديث: ما أذِنَ الله لشيء ما أذِنَ الله لنبي حسن الصوت بالقرآن يجهر به فالمؤمن يتحرى هذا الخير.","link":"https://binbaz.org.sa/fatwas/22483/معنى-حديث-من-لم-يتغن-بالقران-فليس-منا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بلفظ ليس منها في حديث من لم يتغن بالقرآن فليس منا.mp3","categories":["شروح الحديث"]},{"id":2366,"question":"هل يؤخذ من قصة أبي هريرة مع الشيطان قبول الحق إذا جاء به الكافر أو المبتدع وعدم رَدِّ كلامه جُملة وتفصيلًا؟","title":"هل يُقبل الحق إذا جاء به كافر أو مبتدع؟","answer":"الجواب:\nأبو هريرة حريص على الخير، والصحابة كذلك، فهو قبله لما عرضه على النبي ﷺ وصَدَّقه النبي ﷺ، لكن كون أبا هريرة أطلقه وهو مجهول يدل على الرحمة، وأن الإنسان إذا جاء فقير يقول إني فقير وإني محتاج وهو مجهول فيتصدق عليه أحسن؛ لأنه قد يكون صادقًا، فأبو هريرة تصدق عليه وسمح له، ولم ينكر عليه النبي ﷺ فدل على أن من ادّعى الفقر والحاجة وأنت لا تعرف حاله تتصدق عليه؛ لأنه قد يكون صادقًا، تعطيه ما يَسُدُّ حاجته، إلا إذا علمت أنه كذّاب تنصحه.\nس: قصدي قبول الحق من الكافر أو المبتدع؟\nالشيخ: هذا له آخر؛ لأن هذا الدليل أبو هريرة ما قبله إلا بعدما عرضه على النبي ﷺ وصَدَّقه النبي في الآية الكريمة.\nس: ما هو الدليل الآخر؟\nالشيخ: لكن الحق يُقبل من أدلة أخرى، من جاء بالحق وجب قبول الحق ولو أتى مِن كافر.","link":"https://binbaz.org.sa/fatwas/22491/هل-يقبل-الحق-اذا-جاء-به-كافر-او-مبتدع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يقبل الحق إذا جاء به كافر أو مبتدع.mp3","categories":["شروح الحديث"]},{"id":2368,"question":"حديث أبي هريرة يُؤخذ منه إمهال السارق ثلاث مرات؟","title":"معنى حديث أبي هريرة في قصة سارق الزكاة","answer":"الجواب:\nثلاث مرات صريح، ثلاث مرات، لكن أبو هريرة سمح له، ما منعه، رحمه...\nس: يُؤخذ من الحديث إمهال السارق ثلاث مرات؟\nالشيخ: لا ما في إمهال، ما يجوز هذا، لكن هذا صدقة وهذا فقير ورحمه أبو هريرة، فما دام صدقة يعطيه منها، مجهول  ادعى أنه فقير والنبي ﷺ أقره، دَلَّ على أن الوكيل يجتهد، الوكيل في الصدقة لو أعطى بعض الفقراء المجهولين لا بأس؛ لأن الرسول ﷺ ما أنكر عليه، على الصدقة للفقراء.","link":"https://binbaz.org.sa/fatwas/22493/معنى-حديث-ابي-هريرة-في-قصة-سارق-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/فوائد من حديث أبي هريرة وكلني رسول الله بحفظ زكاة رمضان...mp3","categories":["شروح الحديث"]},{"id":2377,"question":"مَن سمع النداء فلم يُجبه فلا صلاة له إلا من عذر؟","title":"حكم مَن سمع النداء للصلاة فلم يُجبه","answer":"الجواب:\nيعني صلاة كاملة تامة، وإلا هي صحيحة ما هي باطلة؛ لأن الأدلة الأخرى فيها أنه هَمَّ أن يحرّق عليهم بيوتهم ولم يأمرهم بقضائها، لم يأمرهم بالإعادة، والذي جاء وصلى معه الفجر في مِنَى ما أمره بالإعادة، وقال: \"إذا صلى أحدكم في بيته ثم أدركتم الصلاة فصل\"، وقال لأبي ذر: إذا أدركت الصلاة فصل فإنها لك نافلة.","link":"https://binbaz.org.sa/fatwas/22502/حكم-من-سمع-النداء-للصلاة-فلم-يجبه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من سمع النداء فلم يجبه فلا صلاة له.mp3","categories":["شروح الحديث"]},{"id":2402,"question":"بعضهم يقول إن الحديث: كان يُلزِق أحدُنا قَدَمَه بقدم صاحبه، محمول على شدة المبالغة، صحيح؟","title":"معنى \"كان يُلزِق أحدُنا قَدَمَه بقدم صاحبه\"","answer":"الجواب:\nعلى الحقيقة، القدم جنب القدم مُلْزق به، لكن ما هو معناه أن يؤذيه بحكحكة، يؤذيه، لاـ يَحُطُّه جنبه بس؛ حتى لا يكون فُرجة، ويكفي، هذا سَدُّ الخَلَل.","link":"https://binbaz.org.sa/fatwas/22527/معنى-كان-يلزق-احدنا-قدمه-بقدم-صاحبه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بحديث كان يلصق أحدنا قدمه بقدم صاحبه.mp3","categories":["شروح الحديث"]},{"id":2431,"question":"ما رأيكم في حديث لا تشتروا السمك في الماء...؟","title":"ما صحة حديث \"لا تشتروا السمك في الماء\"؟","answer":"الجواب:\nما له أصل، إلا إذا عرف إذا لم يتيسر شراؤه، أما إذا كان في ماء محصور في بركة ما يضر، أما إذا كان في البحر لا يبيعه؛ غرر، لا يدري يحصّله وإلا ما يحصّله.","link":"https://binbaz.org.sa/fatwas/22559/ما-صحة-حديث-لا-تشتروا-السمك-في-الماء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث لا تشتروا السمك في الماء..mp3","categories":["شروح الحديث","الحكم على الأحاديث","فتاوى متنوعة","البيوع"]},{"id":2434,"question":"كيف يُجمع بين حديث ابن عمر وحديث علي أن الرسول ﷺ كان يصلي أحيانًا أربعا وكان يصلي أحيانا ثنتين؟","title":"ما الأصح في الركعتين والأربع قبل العصر؟","answer":"الجواب: في صحته نظر، الثابت من قوله: رحم الله امرءًا.. أما قول المؤلف: إسناده صحيح، هذا محل نظر، النووي رحمه الله قد يخفى عليه بعض الشيء من جهة الأسانيد.\nس:أربع متصلة؟\nالشيخ: لا، يُسَلِّم من كل ثنتين، يقول النبي ﷺ: صلاة الليل والنهار مثنى مثنى ثنتين ثنتين، أيش قال المحشي على الأول؟\nالطالب: رواه أبو داود وسنده حسن، لكن رواية الأربعة أصح.\nالشيخ: نعم ما في شك؛ رواية الأربعة أصح. وأيش رواية علي الأولى عَلَّق عليها؟\nالطالب: سنده حسن بس.\nالشيخ: من هو المحشي؟\nالطالب: الشيخ شعيب الأرنؤوط.\nالشيخ: يراجع إن شاء الله، الذي أعرف أن روايات شعيب فيها نظر، المحفوظ رواية القول.","link":"https://binbaz.org.sa/fatwas/22563/ما-الاصح-في-الركعتين-والاربع-قبل-العصر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الجمع بين حديث أن النبي كان يصلي قبل العصر أربعا وحديث أنه كان يصلي ركعتين.mp3","categories":["شروح الحديث"]},{"id":2437,"question":"(حديث صلُّوا قبلَ المغربِ رَكعتَينِ لمن شاءَ) قوله: لمن شاء خوف عليه أن تكون بدرجة الراتبة؟","title":"معنى \"صلُّوا قبلَ المغربِ رَكعتَينِ لمن شاءَ\"","answer":"الجواب:\nخشية أن يظنوها لازمة؛ لأن الأمر أصله للوجوب، فإذا قال: لمن شاء دل على أنه ليس بواجب، سُنَّة.\nس:هل تكون لازمة؟\nالشيخ: سنة مستحبة دائمة، لكن غير واجبة.","link":"https://binbaz.org.sa/fatwas/22566/معنى-صلوا-قبل-المغرب-ركعتين-لمن-شاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بلفظ لمن شاء في حديث صلوا قبل المغرب.mp3","categories":["شروح الحديث"]},{"id":2448,"question":"قوله: فلْيَجْعَل لبيته نصيبًا مِنْ صلاته؟","title":"معنى حديث \"فلْيَجْعَل لبيته نصيبًا من صلاته\"","answer":"الجواب:\nسُنَّة مُسْتَحَبة، نافلة مستحبة، ولهذا قال: أفضل صلاة المرء في بيته أفضل.","link":"https://binbaz.org.sa/fatwas/22577/معنى-حديث-فليجعل-لبيته-نصيبا-من-صلاته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/فليجعل لبيته نصيبا من صلاته.mp3","categories":["شروح الحديث","صلاة التطوع"]},{"id":2470,"question":"حديث أبي هريرة من توضأ فأحسن الوضوء ثم أتى الجمعة هل هذا صارف لحديث: غسل الجمعة واجب على كل محتلم؟","title":"هل غُسْل الجمعة واجب أم مستحب؟","answer":"الجواب:\nهذا من أدلة عدم الوجوب؛ لأن قوله ﷺ: من توضأ يدل على أن الغسل ما هو بواجب، سُنة مؤكّدة.","link":"https://binbaz.org.sa/fatwas/22599/هل-غسل-الجمعة-واجب-ام-مستحب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث من توضأ فأحسن الوضوء ثم أتى الجمعة هل يدل على الوجوب.mp3","categories":["صلاة الجمعة","شروح الحديث"]},{"id":2482,"question":"قوله وهو قائم يصلي ألا تكون مُقَيَّدة بالقيام؟","title":"معنى \"وهو قائم يصلي\" في ساعة الجمعة","answer":"الجواب:\nيعني مشغول بالصلاة؛ لأن الصلاة فيها قيام وفيها ركوع وفيها سجود، يعني مُشْتِغل، إذا كان مستعدًا ينتظر الصلاة بعد العصر ينتظر المغرب فهو في حكم الصلاة كما في الحديث الصحيح: لا يزال في صلاة ما انتظر الصلاة ما دامت ينتظرها فهو في صلاة.\nس: حتى ولو كان يقرأ القرآن؟\nالشيخ: يقرأ القرآن أو يقرأ العلم.","link":"https://binbaz.org.sa/fatwas/22611/معنى-وهو-قاىم-يصلي-في-ساعة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/وهو قائم يصلي ألا تكون مقيدة بالقيام.mp3","categories":["شروح الحديث"]},{"id":2492,"question":"بالنسبة للشيطان الذي بال في أذنيه: نام عن صلاة الفجر أو عن قيام الليل؟","title":"معنى ما جاء بالحديث \"بال الشيطان في أذنيه\"","answer":"الجواب:\nعن قيام الليل.\nس: لو صلى العشاء ونام إلى الفجر إلى الأذان هذا معناه يبول الشيطان؟\nالشيخ: ظاهر الحديث هذا، ظاهر الحديث إذا نام وما صلى شيئًا.\nس: لو نوى القيام ولم يقم هل يصدق عليه أن الشيطان بال في أذنيه؟\nالشيخ: الله أعلم، قد يكون إذا كان عازمًا ولكن غُلب قد يسلم بنيته الطيبة، غلبه النوم، لكن ينبغي للمؤمن أن يكون له نية وعناية، يبكّر ويُرَكِّب الساعة ويتخذ الأسباب، ما هو يسهر ولا يوقِّت الساعة، هذا مُفَرِّط، لكن الإنسان الحريص الصادق إذا كان عنده ساعة رَكَّب الساعة وبكر بالنوم حتى يتيسر له النشاط، يأخذ بالأسباب.","link":"https://binbaz.org.sa/fatwas/22622/معنى-ما-جاء-بالحديث-بال-الشيطان-في-اذنيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/شرح حديث بال الشيطان في أذنيه.mp3","categories":["شروح الحديث"]},{"id":2493,"question":"أيها الناس أفشوا السلام الأمر للوجوب؟","title":"هل الأمر للوجوب في \"أفشوا السلام\"؟","answer":"الجواب:\nالمعروف عند العلماء أنه سُنة، والقول بالوجوب قول قوي، لكن المعروف عند العلماء أنه سُنة، والرد واجب وَإِذَا حُيِّيتُمْ بِتَحِيَّةٍ فَحَيُّوا بِأَحْسَنَ مِنْهَا أَوْ رُدُّوهَا [النساء:86] فالرد واجب والبدء سنة. وهكذا إطعام الطعام وصلاة الليل والناس نيام؛ كلها سُنة. الفريضة الخمس صلوات.\nس: ترجيحكم؟\nالشيخ: الظاهر قول الأئمة أنه سُنة، أما الرد وَإِذَا حُيِّيتُمْ بِتَحِيَّةٍ فَحَيُّوا بِأَحْسَنَ مِنْهَا أَوْ رُدُّوهَا [النساء:86] الرد واجب.","link":"https://binbaz.org.sa/fatwas/22623/هل-الامر-للوجوب-في-افشوا-السلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أيها الناس أفشوا السلام هل الأمر للوجوب.mp3","categories":["شروح الحديث","الآداب والأخلاق المحمودة"]},{"id":2495,"question":"إذا كان الرسول ﷺ يقوم في آخر الليل، فكيف يُخَرَّج قول أنس: كان لا تشاء أن تراه مِن الليل مصلِّيًا؟","title":"هل كان النبيﷺيقوم من الليل كله أم آخِرَه؟","answer":"الجواب:\nيعني تارة وتارة، يعني يختلف ما هو بدائم، قد يصلي من أول الليل مثل ما قالت عائشة: من كل الليل قد أوتر من أوله وأوسطه وآخره، وأنس في الغالب يطلع عليه في السفر، في الأسفار، ونساؤه أعلم به في البيوت، والصحابة أعلم به في السفر.","link":"https://binbaz.org.sa/fatwas/22625/هل-كان-النبيﷺيقوم-من-الليل-كله-ام-اخره","audio":"undefined","categories":["شروح الحديث"]},{"id":2496,"question":"قول الرسول ﷺ: أفضل الصيام بعد رمضان شهر الله المحرم يقصد به عاشوراء أو نفس الشهر؟","title":"هل فضلُ صيام المُحَرَّم يُقصد به عاشوراء؟","answer":"الجواب:\nالشهر كله، وإذا ما صامه كله وصام العاشر والتاسع أو العاشر والحادي، كله خير إن شاء الله.","link":"https://binbaz.org.sa/fatwas/22626/هل-فضل-صيام-المحرم-يقصد-به-عاشوراء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بحديث أفضل الصيام بعد رمضان شهر الله المحرم.mp3","categories":["شروح الحديث","صيام التطوع"]},{"id":2503,"question":"قوله: \"هَمَمْت بأمر سوء\" هل يُؤخذ منه أن الإمام إذا أطال الصلاة أن الرجل يتأخر عنه أو يصلي في مسجد آخر؟","title":"معنى قول ابن مسعود \"هَمَمْت بأمر سوء\"","answer":"الجواب:\nيعني، أمر نسبي كونه يجلس والنبي ﷺ واقف وإلا هو جائز، النافلة يجوز أن تصلي قاعدًا، لكن قصده أنه أمر ما هو مناسب أن أجلس والنبي ﷺ قائم وابن مسعود شباب وقوي.","link":"https://binbaz.org.sa/fatwas/22633/معنى-قول-ابن-مسعود-هممت-بامر-سوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إذا أطال الإمام الصلاة هل يتأخر عنه أو يصلي في مسجد آخر.mp3","categories":["شروح الحديث","صلاة الجماعة"]},{"id":2515,"question":"الحديث في استياك النبي ﷺ في رمضان؟","title":"هل صح استياكُ النبي ﷺ في رمضان؟","answer":"الجواب:\nفي حديث عامر بن ربيعة: رأيت النبي ﷺ يستاك ما لا أحصي وهو صائم، لكن لا أعرف حال سنده الآن، يحتاج إلى مراجعة. لكن قوله ﷺ: مع كل وضوء يكفي، يَعُمُّ رمضان وغيره، ويَعُمُّ الصائم وغير الصائم، مع كل وضوء، مع كل صلاة، يعم الظهر والعصر في حق الصائم وغيره.\nس: في أثناء المضمضة؟\nالشيخ: عند المضمضة، عندما يبدأ الوضوء.","link":"https://binbaz.org.sa/fatwas/22645/هل-صح-استياك-النبي-ﷺ-في-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/استياك النبي عليه الصلاة والسلام في رمضان.mp3","categories":["سنن الفطرة","شروح الحديث"]},{"id":2520,"question":"حديث: لا صلاة لمن سمع النداء ولم يلبِّ يعني لا صلاة كاملة؟","title":"معنى \"لا صلاة لمن سمع النداء ولم يلبِّ\"","answer":"الجواب: الصواب عند أهل العلم يعني صلاة كاملة؛ لأن الجماعة ما هي بشرط للصحة، واجبة، لكن لو صلى بغير جماعة صحت مع الإثم.","link":"https://binbaz.org.sa/fatwas/22651/معنى-لا-صلاة-لمن-سمع-النداء-ولم-يلب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى حديث لا صلاة لمن سمع النداء ولم يلبِّ.mp3","categories":["شروح الحديث"]},{"id":2524,"question":"في بعض الروايات أحْفُوا الشَّواربَ ؟","title":"معنى \"أحْفُوا الشَّواربَ\" في الحديث","answer":"الجواب: يعني: أخذها أخذًا جيد، قصها قصًّا جيدًا، ما هو بحلق، قص لكن قص قوي.\nس: الحلق ليس من السنة؟\nالشيخ: لا لا، تركها أوْلى، السنة القص..... الحديث صحيح لا بأس به، أخذ الشارب واجب، لكن رخَّص النبي ﷺ في أقل من أربعين.","link":"https://binbaz.org.sa/fatwas/22655/معنى-احفوا-الشوارب-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى أحفوا الشوارب.mp3","categories":["سنن الفطرة","شروح الحديث"]},{"id":2531,"question":"هذه الكتابة حقيقية (كاف فاء راء بين عيني الدجال)؟","title":"ما صحة كتابة \"ك ف ر\" بين عيني الدجال؟","answer":"الجواب: نعم، كاف فاء راء مكتوبة بين عينيه.\nس: ورد أنها ما يقرؤها إلا المسلمون فقط؟\nالشيخ: يقرأها كل مؤمن، قرأ أو لم يقرأ.\nس: من قال إن الدجال هو ابن صياد؟\nالشيخ: لا، ما هو ابن صياد، ابن صياد مات، ليس هو ابن صياد.","link":"https://binbaz.org.sa/fatwas/22662/ما-صحة-كتابة-ك-ف-ر-بين-عيني-الدجال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حقيقة كتابة كاف فاء راء بين عيني الدجال.mp3","categories":["شروح الحديث"]},{"id":2533,"question":"قوله ﷺ: ليس بأعور فيه إثبات العينين لله؟","title":"هل في حديث \"ليس بأعور\" إثبات العينين لله؟","answer":"الجواب: نعم إثبات العين لله والسمع والبصر في القرآن العظيم والسنة المطهرة.\nس: من باب القياس..؟\nالشيخ: لا، صريح النص ليس بأعور، يعني أن ربك ذو عينين، والدجال ذو عين واحدة والباقي عنبة طافية، وربك سميع بصير رؤوف رحيم يغضب ويرضى ويعطي ويمنع جل وعلا، ليس كمثله شيء وهو السميع البصير .","link":"https://binbaz.org.sa/fatwas/22664/هل-في-حديث-ليس-باعور-اثبات-العينين-لله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/قوله ليس بأعور هل فيه إثبات العينين لله.mp3","categories":["شروح الحديث"]},{"id":2536,"question":"في حديث يقول: تكونُ النُّبوَّةُ فيكم ما شاء اللهُ أنْ تكونَ، ثُمَّ يَرفَعُها إذا شاء أنْ يَرفَعَها، ثُمَّ تكونُ خِلافةٌ على مِنهاجِ النُّبوَّةِ، فتكونُ ما شاء اللهُ أنْ تكونَ، ثُمَّ يَرفَعُها إذا شاء اللهُ أنْ يَرفَعَها، ثُمَّ تكونُ مُلكًا عاضًّا...","title":"معنى حديث \"تكون النبوة فيكم ما شاء الله..\"","answer":"الجواب: كل هذا وقع، الخلفاء الراشدون، في زمن الصحابة، فيه خير عظيم، ثم القرون المفضلة، ثم جاءت الفتن بعد ذلك، والله المستعان.\nس: صحيح؟\nالشيخ: نعم.","link":"https://binbaz.org.sa/fatwas/22667/معنى-حديث-تكون-النبوة-فيكم-ما-شاء-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث تكون النبوة فيكم ما شاء الله أن يكون...mp3","categories":["شروح الحديث"]},{"id":2544,"question":"الجمع بين هذا الحديث إذا أُنزل بقوم عذاب.. وبين أن أمة محمد لا يُعَذّبون عامة؟","title":"ما معنى أن أمة محمد لا يُعَذّبون بعذاب عام؟","answer":"الجواب: إذا أنزل على قوم ما هم كُلَّهُم، إذا أُنزل على قوم طائفة اجتمعت مثلًا في قرية وأظهروا المنكر وعَمّت العقوبة تَعُمُّ الصالح والطالح، مثل الذين يغزون مكة في آخر الزمان، ينزل بهم عقوبة في بيداء من الأرض فيُخْسَف بأوَّلِهم وآخِرِهم، قيل: يا رسول الله كيف يُخْسُف بأولهم وآخرهم وفيهم أسواقهم ومن ليس منهم؟ قال: يُخْسُف بهم جميعًا ثم يُبعثون على نِّيَّاتهم. الذي نفاه النبي ﷺ العقوبات العامة، يعني تعم أهل الأرض كلهم.","link":"https://binbaz.org.sa/fatwas/22675/ما-معنى-ان-امة-محمد-لا-يعذبون-بعذاب-عام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الجمع بين حديث إذا أنزل بقوم عذاب وبين أن أمة محمد لا يعذبون.mp3","categories":["شروح الحديث"]},{"id":2550,"question":"من قال: إنها ثلاث نفخات؟","title":"ما الصواب في عدد مرات النفخ في الصور؟","answer":"الجواب: الصواب أنها نفختان، نفخة الفزع هي نفخة الصعق. أما ما في حديث الصور أنها ثلاث؛ فحديث الصور ضعيف، حديث الصور الذي فيه النفخات الثلاث ضعيف، والصواب الذي دل عليه القرآن: نفختان.\nس: الذي في القرآن أنها نفختان؟\nالشيخ: نفختان في الزمر وغيرها، صريحة في الزمر، الأولى: نفخة الصعق، وهي نفخة الفزع التي في سورة النمل، والثانية: نفخة البعث والنشور، نسأل الله حسن الختام، نسأل الله السلامة، اللهم سَلِّم سَلِّم.","link":"https://binbaz.org.sa/fatwas/22681/ما-الصواب-في-عدد-مرات-النفخ-في-الصور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث بين النفختين أربعون فهل هي نفختين أم ثلاث.mp3","categories":["شروح الحديث","اليوم الآخر"]},{"id":2567,"question":"من قال أن هذه الأيام السبعة التي وردت في الحديث (خلق الله التربة يوم السبت..) هي غير الأيام الستة التي القرآن؟","title":"هل الأيام الستة في القرآن هي نفسها بالسُّنَّة؟","answer":"الجواب: لا، هي هي، هي التي في القرآن وهي التي في السنة.\nس: يقول زيادة على ما في القرآن؟\nالشيخ: لا ، غلط غلط.","link":"https://binbaz.org.sa/fatwas/22699/هل-الايام-الستة-في-القران-هي-نفسها-بالسنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث خلق الله التربة يوم السبت... هل الأيام هذه غير الأيام الستة التي القرآن.mp3","categories":["شروح الحديث"]},{"id":2572,"question":"حديث: الحُمّى حَظُّ المؤمن من النار؟","title":"ما صحة أن \"الحُمَّى حظ المؤمن من النار\"","answer":"الجواب: ما أتذكر فيه شيئًا، وعلى كل حال هي من أسباب تكفير السيئات، الحُمّى من أسباب التكفير وحط الخطايا كسائر الأمراض.\nس: حتى لو كان أصابته حُمى في أيام الشتاء يتروّش بماء بارد؟\nالشيخ: ظاهر الحديث، لا ما هو بماء بارد، مناسب، يعني لا يزعجه، النبي ﷺ ما قال بالماء البارد، إنما قال: الماء يُبْرِدُها يخفّفها، يكون بماء مناسب حتى لا يشوّش عليه.","link":"https://binbaz.org.sa/fatwas/22705/ما-صحة-ان-الحمى-حظ-المومن-من-النار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث الحمى حظ المؤمن من النار.mp3","categories":["شروح الحديث"]},{"id":2578,"question":"قوله: إنِّي فَرَطٌ لَكُمْ؟","title":"معنى \"إنِّي فَرَطٌ لَكُمْ\" في الحديث","answer":"الجواب: يعني: أمامكم، سابق لكم، أمامهم في الجنة، وأمامهم في الحوض عليه الصلاة والسلام، الفرط: السابق قبل القوم، الذي يسبقهم حتى يهيّئ لهم المنزل والماء ونحو ذلك، يعني: أنا أمامكم وأنا قُدّامكم، وسوف يَرِدون عليه الحوض عليه الصلاة والسلام .\nس: يسبقهم بالموت؟\nالشيخ: لا، يعني أمامهم يوم البعث والنشور.","link":"https://binbaz.org.sa/fatwas/22711/معنى-اني-فرط-لكم-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى فرط في حديث إني بين أيديكم فرط وأنا شهيد عليكم.mp3","categories":["شروح الحديث"]},{"id":2586,"question":"حديث الوَزَغ ألا يَدُلُّ على أن الحيوانات لها قَصْدُ خير وشر؟","title":"ما دلالة الأمر بضرب الوَزَغ وفضله؟","answer":"الجواب: هذا ورد في الوزغ، والله ألهمها أشياء ، لكنها غير مُكَلَّفة لكن بعضها شرير أمر الله بقتله، كما يُقتل الكلب العَقُور، كما تُقتل الحية والعقرب، ونحو ذلك؛ لما فيها من الخُبْث والشر والأذى، وهي غير مُكَلَّفة.\nس: من يقول أن ضربها باليد أكثر أجرًا من ضربها بالحذاء أو كذا؟\nالشيخ: لا، ما له أصل، المقصود ضربها بما يقتلها وبس، بعصا أو بغيرها.\nس: بعض الناس يقول الحيوانات ما لها عقل؟\nالشيخ: عقل يليق بها، لها عقول تليق بها، العقل البهيمي يليق به، يعقل يشرب يأكل ويسافد وهكذا.\nس: بالنسبة للأجر في الضربة الثانية؟\nالشيخ: مثل ما قال النبي ﷺ؛ الضربة الأولى أفضل، والثانية دونها، والثالثة دونها، والمقصود على هذا الحث على العناية بالضرب، هذا المقصود.\nس: ما ورد سبعين وخمسين؟\nالشيخ: ما أذكر إلا ثلاث.","link":"https://binbaz.org.sa/fatwas/22719/ما-دلالة-الامر-بضرب-الوزغ-وفضله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يدل حديث الوزغ على أن الحيوانات لها قصد خير وشر.mp3","categories":["شروح الحديث"]},{"id":2595,"question":"بالنسبة لقوله ﷺ: لو لَمْ تُذْنِبُوا لَذَهَبَ اللَّهُ بِكُمْ، وَلَجَاءَ بِقَوْمٍ يُذْنِبُونَ، فَيَسْتَغْفِرُونَ اللَّهَ فَيَغْفِرُ لهمْ هو أحيانًا يصير خطأ  مثلًا في غيبة أو نميمة في بعض الأحيان، هل هذا المقصود؟","title":"معنى حديث \"لو لَمْ تُذْنِبُوا لَذَهَبَ اللَّهُ بِكُمْ..\"","answer":"الجواب: لا..... الله كتب على عباده الذنوب، لو كانوا معصومين جاء بغيرهم حتى يتبين أثر أنه غفور وأنه رحيم وأنه جواد وأنه كريم؛ بسبب وقوع الذنوب فيتوب عليهم ويغفر لهم إذا تابوا إليه وأنابوا إليه، وقد يعفو عنهم لأسباب أخرى.","link":"https://binbaz.org.sa/fatwas/22728/معنى-حديث-لو-لم-تذنبوا-لذهب-الله-بكم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بقوله عليه الصلاو والسلام لو لم تذنبوا..mp3","categories":["شروح الحديث"]},{"id":2596,"question":"الأحاديث أليس فيها دلالة على الجهر بالاستغفار؟","title":"هل الأفضل في الاستغفار الجهر أم الإسرار؟","answer":"الجواب: إنْ جهر وإنْ أسرّ؛ كله طيب، وهو دعاء، الدعاء الإسرار به أفضل، وإذا دعت الحاجة إلى إظهاره كالخطيب الذي يعظ الناس في الاستسقاء يجهر، كالقنوت الذي يقنت بالناس، وأما الإنسان بينه وبين ربه: السِّرُّ به أفضل ادْعُوا رَبَّكُمْ تَضَرُّعًا وَخُفْيَةً إِنَّهُ لَا يُحِبُّ الْمُعْتَدِينَ [الأعراف:55].","link":"https://binbaz.org.sa/fatwas/22729/هل-الافضل-في-الاستغفار-الجهر-ام-الاسرار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أحاديث الاستغفار فيها دلالة على الجهر بالاستغفار.mp3","categories":["شروح الحديث","الأدعية والأذكار"]},{"id":2603,"question":"بالنسبة لحديث الشفاعة: تأخير أهل الإيمان طلب الشفاعة من الرسول ﷺ ومرورهم على الأنبياء؟","title":"حكمة طلب شفاعة الأنبياء قبل النبي","answer":"الجواب: هذا علمنا إياه، عرفه المسلمون، عرف المسلمون النصوص، الشفاعة تنتهي إليه عليه الصلاة والسلام؛ لإظهار فضله وعُلُو منزلته بين الخلائق يوم القيامة.","link":"https://binbaz.org.sa/fatwas/22737/حكمة-طلب-شفاعة-الانبياء-قبل-النبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكمة في تأخير أهل الإيمان طلب الشفاعة من الرسول ومرورهم على الأنبياء.mp3","categories":["شروح الحديث","التوسل والشفاعة"]},{"id":2607,"question":"كيف يمكن الجمع بين قوله: إِنَّمَا تُجْزَوْنَ مَا كُنْتُمْ تَعْمَلُونَ [التحريم:7] وحديث النبي ﷺ: لا يدخل الجنة أحَدُكُم بعمله قالوا: ولا أنت يا رسول الله؟ قال: ولا أنا إلا أن يتغمدني الله برحمته.","title":"معنى ودلالة {إِنَّمَا تُجْزَوْنَ مَا كُنْتُمْ تَعْمَلُونَ}","answer":"الجواب: هذه باءُ العِوَض، المَنْفِيَة باءُ العِوَض، أما المُثْبَتَة فباءُ السبب، يدخلون الجنة بأسباب أعمالهم، والمُعَوَّل فيها على عفو الله ورحمته جل وعلا، لا يدخل الجنة أحَدُكُم بعمله -يعني بِعِوَض- لأن عمله كله ما يقابل نعمة من نعم الله عليه سبحانه وتعالى في صحته وعافيته وما رزقه الله في الدنيا، فالأعمال الصالحة أسباب، هو الذي جعلها أسبابًا وأوجب بها الرحمة، هو ربنا ، فضلًا منه وإحسانًا جل وعلا، ولكن يتغَمَّدُهم الله برحمته بأسباب أعمالهم الصالحة.","link":"https://binbaz.org.sa/fatwas/22742/معنى-ودلالة-انما-تجزون-ما-كنتم-تعملون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الجمع بين قوله تعالى إِنَّمَا تُجْزَوْنَ مَا كُنْتُمْ تَعْمَلُونَ، وحديث لا يدخل الجنة أحدكم بعمله..mp3","categories":["شروح الحديث","التفسير"]},{"id":2625,"question":"قول الرسول ﷺ لمعاذ  فإن هم أطاعوك فأعْلِمْهم أن الله ...؟","title":"معنى حديث \"فإن هم أطاعوك فأَعْلِمْهم...\"","answer":"الجواب: يعني: لا يُخاطبون بالصلاة إلا إذا أجابوا إلى التوحيد، فإذا أجابوا للتوحيد ودخلوا في الإسلام؛ يُؤمرون بالصلاة وبقية الأركان، وإذا امتنعوا من الصلاة؛ ما لهم دين حتى يُصَلُّوا، فإذا أدَّوا الصلاة عُلِّمُوا بالزكاة وبقية أمور الإسلام.\nس: إذا كان فيهم شرك؟\nالشيخ: لا بدّ يبدأ بالتوحيد أولًا، يُعَلَّمون التوحيد وترك الشرك، ثم الصلاة، ثم الزكاة، وهكذا.","link":"https://binbaz.org.sa/fatwas/22760/معنى-حديث-فان-هم-اطاعوك-فاعلمهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/على ماذا يدل حديث معاذ فإن هم أطاعوك فأعلمهم أن الله..mp3","categories":["شروح الحديث"]},{"id":2635,"question":"ما معنى قوله: ومِنْ حَقِّها حَلَبُها يَومَ وِرْدِها؟","title":"معنى حديث \"ومِنْ حَقِّها حَلَبُها يَومَ وِرْدِها\"","answer":"الجواب: يعني: يحلبها ويعطي الفقراء الذين حوله، هذا من الحق عليها.","link":"https://binbaz.org.sa/fatwas/22770/معنى-حديث-ومن-حقها-حلبها-يوم-وردها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى ومن حقها حلبها يوم وردها.mp3","categories":["شروح الحديث"]},{"id":2638,"question":"يقول من صام يوما في سبيل الله، الذي يصوم في التقاء الصفين؟","title":"ما حكم الصوم في حال الجهاد؟","answer":"الجواب: لا ما ينبغي له الصوم، في الجهاد لا، ما ينبغي؛ لأن النبي ﷺ لما دنا من مكة عام الفتح أمرهم بالإفطار وقال: أفطروا فإن الفِطْر أقوى لكم في جهاد عدوكم فلما بلغه أن بعضهم صام قال: أولئك العصاة، أولئك العصاة وقت الحاجة لا يصوموا؛ لأن الفِطر أقوى، في سبيل الله، يعني في طاعة الله وابتغاء مرضاته، لا رياء ولا سمعة.\nس: والراجح عندكم؟\nالشيخ: هذا أحسن ما قيل في الحديث.\nس: إذا كان في مرابطة؟\nالشيخ: إذا كان في مرابطة أو في وقت لا يضعفه الصيام ما فيه ملاقاة؛ لا بأس، فيه فضل.\nس: يدخل فيه الفرض والنافلة؟\nالشيخ: لا، المراد هنا النافلة.","link":"https://binbaz.org.sa/fatwas/22773/ما-حكم-الصوم-في-حال-الجهاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الذي يصوم في الجهاد.mp3","categories":["شروح الحديث","صيام التطوع"]},{"id":2640,"question":"معنى صيام ثلاثة أيام من كل شهر كصيام الدهر؟","title":"معنى أن ثلاثة أيام كل شهر كصوم الدهر","answer":"الجواب: الحسنة بعشر أمثالها، كل يوم عن عشرة.","link":"https://binbaz.org.sa/fatwas/22775/معنى-ان-ثلاثة-ايام-كل-شهر-كصوم-الدهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى صيام ثلاثة أيام من كل شهر كصيام الدهر.mp3","categories":["شروح الحديث","صيام التطوع"]},{"id":2642,"question":"سبب سؤال الصِّدِّيق: \"هل على مَن دُعي من جميع الأبواب من ضرورة\" السؤال هل استبعاد أنه يُدعى الرجل من جميع الأبواب؟","title":"معنى سؤال الصدّيق عن أبواب الجنة","answer":"الجواب: يعني يسأل يستفهم: هل يدعى أحد منها كلها؟ قال النبي ﷺ: نعم، وإني لأرجو أن تكون منهم.","link":"https://binbaz.org.sa/fatwas/22777/معنى-سوال-الصديق-عن-ابواب-الجنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/سؤال الصدّيق هل على من دعي من جميع الأبواب من ضرورة.mp3","categories":["شروح الحديث"]},{"id":2643,"question":"هل اشترط النبي ﷺ على عليٍّ عدم الزواج على ابنته فاطمة؟","title":"هل اشترط النبيﷺعدم الزواج على ابنته؟","answer":"الجواب: لما أراد أن يتزوج أنكر ذلك عليه، قال ﷺ: إنه يؤذيني ما يؤذيها، وهذا خاص بفاطمة.","link":"https://binbaz.org.sa/fatwas/22778/هل-اشترط-النبيﷺعدم-الزواج-على-ابنته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل اشترط النبي على علي عدم الزواج على ابنته فاطمة.mp3","categories":["شروح الحديث","التاريخ والسيرة"]},{"id":2644,"question":"ما يكون \"شَدّ المِئْزَر\" كناية عن ترك الجماع؟","title":"معنى \"شَدّ المِئْزَر\" في الحديث","answer":"الجواب: بعض أهل العلم فسّره بذلك، لكنه أعم؛ لأن المعتكف ما يجامع وَلَا تُبَاشِرُوهُنَّ وَأَنْتُمْ عَاكِفُونَ فِي الْمَسَاجِدِ [البقرة:187]. جاء في الرواية الأخرى: شَدّ المِئْزَر واعتزل النساء.","link":"https://binbaz.org.sa/fatwas/22779/معنى-شد-المىزر-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى شد المئزر في الحديث.mp3","categories":["شروح الحديث"]},{"id":2660,"question":"إذا كان الإنسان يصوم يومًا ويفطر يومًا ووافق يوم الجمعة؟","title":"حكم الجُمعة لمن يصوم يومًا ويفطر يومًا","answer":"الجواب: يصوم يوم الجمعة ويفطر يوم السبت؛ لأنه ما صام لأجل الجمعة، صام لأجل القاعدة: يصوم يومًا ويفطر يومًا. س: إنْ كان عليه قضاء؟ الشيخ: يصوم الجمعة؛ لأنه واجب عليه.","link":"https://binbaz.org.sa/fatwas/22796/حكم-الجمعة-لمن-يصوم-يوما-ويفطر-يوما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/يصوم يوما ويفطر يوما ووافق يوم الجمعة.mp3","categories":["شروح الحديث","صيام التطوع"]},{"id":2661,"question":"قول الرسول ﷺ: فقد أفطر الصائم من باب الأمر؟","title":"هل قوله ﷺ: \"فقد أفطر الصائم\" للأمْر؟","answer":"الجواب: يعني حُكْمًا، يعني دخل وقته، قد أفطر حُكْمًا، يعني وإن لم يأكل هو زال حكم الصيام.","link":"https://binbaz.org.sa/fatwas/22798/هل-قوله-ﷺ-فقد-افطر-الصاىم-للامر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل قول النبي عليه الصلاة والسلام فقد أفطر الصائم من باب الأمر.mp3","categories":["شروح الحديث"]},{"id":2664,"question":"فقد أفطر الصائم حتى وإن لم يجد أكلًا أو شُربًا؟","title":"ما معنى \"فقد أفطر الصائم\" في الحديث؟","answer":"الجواب: أفطر حكما، زال الحكم، زال حكم الصوم، دخل في وقت الإفطار، متى تيسر الأكل أكل.\nس: ينوي؟\nالشيخ: نوى وإلا ما نوى، أفطر الصائم مطلقًا حُكْمًا.\nس: إذا أراد الوِصَال؟\nالشيخ: لا بأس بالوصال إلى آخر الليل بس، والباقي مكروه.","link":"https://binbaz.org.sa/fatwas/22802/ما-معنى-فقد-افطر-الصاىم-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى فقد أفطر الصائم في الحديث.mp3","categories":["شروح الحديث"]},{"id":2670,"question":"قوله: فَلْيُفْطِرْ على ماءٍ فإنه طَهُورٌ ماذا يقصد بطهور؟","title":"معنى حديث \"فَلْيُفْطِرْ على ماء فإنه طَهُورٌ\"","answer":"الجواب: يعني: الماء طَهُورٌ، هذا معناه، يعني: يطهر المعدة، أقول: الماء طهور، غُسْلٌ طيِّب طَهُورٌ مُطَهِّر.","link":"https://binbaz.org.sa/fatwas/22808/معنى-حديث-فليفطر على-ماء-فانه-طهور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بطهور في حديث فليفطر على ماء فإنه طهور.mp3","categories":["شروح الحديث"]},{"id":2681,"question":"إذا صام التاسع والعاشر والحادي عشر، ألا يُنهى عن صيام يوم العيد؟","title":"ما الأفضل في الصوم قبل عاشوراء وبعده؟","answer":"الجواب: لا هذا في عاشوراء، يصوم التاسع والعاشر والحادي عشر، عاشوراء، أما ذو الحجة ما فيه إلا التاسع والثامن، يبغى يصوم يصوم مع التاسع الثامن. ويوم العيد ما يُصام بإجماع المسلمين، يوم النحر ما يُصام لا عن فرض ولا عن نفل.  هذا الكلام في عاشوراء: يصوم يومًا قبله أو يومًا بعده، والأفضل التاسع، وإن صام الاثنين العاشر والحادي والتاسع كله طيب.\nس: الأحوط صيام التاسع حتى يتحرى العاشر؟\nالشيخ: ما في بأس التاسع والعاشر أو العاشر والحادي عشر، لكن إذا صام التاسع يكون أفضل لأن الاحتياط فيه أكثر.\nس: قد يكون صادف العاشر؟\nالشيخ: قد يصادف العاشر... ويكون معه العاشر والحادي.\nس:ألا يدل قوله: \"وأمر بصيامه\" على الوجوب؟\nالشيخ: كان هذا في أول الأمر، ثم نسخ الوجوب، قال قوم من أهل العلم: لم يُكتب صيامه، إنما تأكّد قبل صيام رمضان، كان متأكّدًا ثم لما فرض رمضان صار صومه مستحبًّا بغير تأكيد.","link":"https://binbaz.org.sa/fatwas/22819/ما-الافضل-في-الصوم-قبل-عاشوراء-وبعده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صيام يوم عاشوراء.mp3","categories":["شروح الحديث","صيام التطوع"]},{"id":2682,"question":"من كان عنده بعض الكبائر هل يصوم يوم عرفة؟","title":"ما حكم التطوعات لمن عنده بعض الكبائر؟","answer":"الجواب: الذي عنده كبائر والذي ما عنده كبائر يستحب له صيام عرفة، كل مسلم يستحب له صيام عرفة؛ يخفف الله فيه من ذنوبه، عمل صالح.\nس: العاصي المصر على معصية؟\nالشيخ: كل مسلم يستحب له التطوعات ولو أنه عاصٍ، العاصي أوْلى الناس بأن يحرص على وجوه الخير؛ لعله يخفف عنه.","link":"https://binbaz.org.sa/fatwas/22820/ما-حكم-التطوعات-لمن-عنده-بعض-الكباىر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/التطوعات لمن كان عنده بعض الكبائر.mp3","categories":["شروح الحديث","صيام التطوع"]},{"id":2683,"question":"هل تُكفّر  الصغائر أم الكبائر؟","title":"هل تكفير السيئات يَخُصُّ الصغائر فقط؟","answer":"الجواب: يقول الله جل وعلا: إِنْ تَجْتَنِبُوا كَبَائِرَ مَا تُنْهَوْنَ عَنْهُ نُكَفِّرْ عَنْكُمْ سَيِّئَاتِكُمْ [النساء:31] يعني الصغائر، ويقول النبي ﷺ: الصلوات الخمس، والجمعة إلى الجمعة، ورمضان إلى رمضان كفارات لما بينهن ما لم تُغْشَ الكبائر وفي اللفظ الآخر: إذا اجْتُنِبَتْ الكبائر.","link":"https://binbaz.org.sa/fatwas/22821/هل-تكفير-السيىات-يخص-الصغاىر-فقط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/اجتناب الكبائر شرط لتكفير الصغائر.mp3","categories":["شروح الحديث","الرقائق"]},{"id":2686,"question":"يوم الإثنين هل له خاصية معينة؟","title":"هل ليوم الإثنين خاصية معينة؟","answer":"الجواب: لا، بس من جهة الصوم، قد يستغله أصحاب المولد وهذا غلط، إنما هذا من جهة الصوم وأنه يصام؛ لأنه يومٌ بُعث فيه وأُنزل عليه فيه ويوم وُلد فيه عليه الصلاة والسلام، فصار فيه فضلان: فضل كونه يوم مولده، وفضل كونه أنزل عليه الوحي فيه عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/22825/هل-ليوم-الاثنين-خاصية-معينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل ليوم الاثنين خاصية معينة.mp3","categories":["شروح الحديث","صيام التطوع"]},{"id":2687,"question":"صيام النافلة بعد انتصاف الشهر، شهر شعبان؟","title":"ما حكم صوم التطوع بعد انتصاف شعبان؟","answer":"الجواب: إذا ما صام النصف الأول، لا يصوم بعد النصف إذا كان ما صام في النصف الأول.\nس:أي نافلة مطلقًا؟\nالشيخ: الصوم يعني، إلا إذا كان يصوم الإثنين والخميس فيصوم ما في بأس، إذا كان من عادته يصوم الإثنين والخميس ما يخالف.\nس: أو البيض؟\nالشيخ: البيض قبل النصف الأول.\nس: لو أخرها مثلًا؟\nالشيخ: لا، البيض في ثلاثة عشر وأربعة عشر وخمسة عشر هذه البيض.\nس: إذا ما نوى إلا بعد خمسة عشر شعبان؟\nالشيخ: لا يبتدئ؛ للحديث: إذا انتصف شعبان فلا تصوموا.\nس: إذا صام يومًا واحدًا في النصف الأول من شعبان هل يصوم النصف الثاني؟\nالشيخ: ظاهره لا بأس، إذا كان قبله شيء لا بأس أن يستمر، المقصود أن يصوم أكثر شعبان، هذا المقصود أكثر شعبان.","link":"https://binbaz.org.sa/fatwas/22826/ما-حكم-صوم-التطوع-بعد-انتصاف-شعبان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم صيام التطوع بعد انتصاف شهر شعبان.mp3","categories":["شروح الحديث","صيام التطوع"]},{"id":2688,"question":"إذا كان الهجر يسبب شرًَا هل يدخل في الحديث (النهي عن الهجر فوق ثلاث)؟","title":"حكم الهجر لسبب شرعي أكثر من ثلاث","answer":"الجواب: لا لا، هذا الهَجْر الذي لأمور الدنيا، لحاجاتهم، أما لأمر شرعي ما يدخل، مأجور صاحبه حتى يزول السبب، النبي ﷺ هجر كعب بن مالك وصاحبيه خمسين ليلة حتى تاب الله عليهم وتابوا.","link":"https://binbaz.org.sa/fatwas/22827/حكم-الهجر-لسبب-شرعي-اكثر-من-ثلاث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الهجر لأمر شرعي أكثر من ثلاث هل يدخل في النهي.mp3","categories":["شروح الحديث"]},{"id":2691,"question":"إذا كان الصائم تطوعًا لأيِّ من الأسباب أفطر؟","title":"حكم الصائم تطوعًا لو عَرَض له سببٌ للفطر","answer":"الجواب: ما في بأس، المتطوع أمير نفسه؛ إذا أفطر لا بأس، دعت حاجة يفطر، الضيف عنده أو حاجة يفطر.\nس: أو يتقوّى بها على بعض أعمال الدنيا؟\nالشيخ: ما في بأس، ما في حرج.","link":"https://binbaz.org.sa/fatwas/22830/حكم-الصاىم-تطوعا-لو-عرض-له-سبب-للفطر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صيام التطوع والفطر فيه.mp3","categories":["شروح الحديث","صيام التطوع"]},{"id":2692,"question":"حديث أبي هريرة: تعرض الأعمال يوم الإثنين والخميس؟","title":"ما صحة عرض الأعمال الإثنين والخميس؟","answer":"الجواب: حديث صحيح، قد تقدم.\nس: قال: فيه محمد بن رفاعة بن ثعلبة، لم يوثقه إلا ابن حبان.\nالشيخ: الحديث صحيح خرّجه مسلم في الصحيح تعرض الأعمال على الله يوم الإثنين والخميس، فيغفر لكل مسلم لا يشرك بالله شيئًا إلا رجل كانت بينه وبين أخيه شحناء فيقول الله دعوا هذين حتى يصطلحا.","link":"https://binbaz.org.sa/fatwas/22831/ما-صحة-عرض-الاعمال-الاثنين-والخميس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث تعرض الأعمال يوم الإثنين والخميس.mp3","categories":["شروح الحديث","الحكم على الأحاديث"]},{"id":2693,"question":"مَنْ كان عليه قضاء مِنْ رمضان هل يبدأ بالست أم بالقضاء؟","title":"هل يصوم سِتّ شوال مَنْ عليه قضاء؟","answer":"الجواب: يبدأ من القضاء، القضاء أهم.","link":"https://binbaz.org.sa/fatwas/22832/هل-يصوم-ست-شوال-من-عليه-قضاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يصوم ست شوال من عليه قضاء من رمضان.mp3","categories":["شروح الحديث","صيام التطوع"]},{"id":2722,"question":"يحصل له هذا الأجر العظيم (الرباط) الذي حافظ على الصلاة؟","title":"هل يرجى أجر الرباط للمحافظ على الصلاة؟","answer":"الجواب: يرجى له؛ لأن النبي ﷺ سماه رِباطا فذلكم الرباط، فذلكم الرباط يرجى له فضل المرابطة.","link":"https://binbaz.org.sa/fatwas/22868/هل-يرجى-اجر-الرباط-للمحافظ-على-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/فذلكم الرباط هل يحصل الأجر لمن حافظ على الصلاة ومن كان في الثغور.mp3","categories":["شروح الحديث","حكم الصلاة وأهميتها"]},{"id":2723,"question":"بالنسبة للرباط يكون في جلوسه في المسجد، أو أنه ينتظر الصلاة بعد الصلاة؟","title":"معنى \"الرباط\" في فضل انتظار الصلاة","answer":"الجواب: ما هو معنى ذلك يبقى في المسجد، لا، معناه أنها على باله لا يضيّعها ولو ذهب في حاجاته، لكنها على باله، إذا انتهى من صلاة على باله الأخرى حتى يؤديها.","link":"https://binbaz.org.sa/fatwas/22869/معنى-الرباط-في-فضل-انتظار-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/فذلكم الرباط هل يشترط أو يكون جلوسه في المسجد أو ينتظر الصلاة.mp3","categories":["شروح الحديث"]},{"id":2726,"question":"يكفي المرء المسلم أن يقرأ أحاديث الجهاد والغزو حتى يسلم مِن هذا (وعيد حديثمن مات ولم يَغْزُ..) ؟","title":"كيف يُتجنّب وعيدُ \"من مات ولم يَغْزُ\"؟","answer":"الجواب: يقرأ حتى يستفيد؛ حتى تكون له نية صالحة لو قام الجهاد.\nس: حتى يسلم مما ورد...؟\nالشيخ: نعم، من مات ولم يغزُ ولم يحدّث نفسه بالغزو مات على شُعبة مِن النفاق.","link":"https://binbaz.org.sa/fatwas/22872/كيف-يتجنب-وعيد-من-مات-ولم-يغز","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث من مات ولم يغزُ، ولم يحدث نفسه بالغزو.. هل تكفي قراءة أحاديث الجهاد.mp3","categories":["شروح الحديث","الجهاد والسير"]},{"id":2727,"question":"الذين يطلقون على الشخص: الشهيد فلان، أو المرحوم، أو المغفور له؟","title":"حكم لفظ \"الشهيد\" و\"المرحوم\" ونحوهما","answer":"الجواب: \"الشهيد\" أطلقه النبي ﷺ، إذا قتل في سبيل الله فهو شهيد، إن كان له نية داخلية الله أعلم به، لكنه شهيد لا يُغَسَّل ولا يُصلى عليه، إذا مات في المعركة يسمى شهيدًا؛ فإن كان صادقًا مخلصًا فله الجنة، وإن كان مرائيًا فإثمه عليه.\nوأما المرحوم المغفور له لا، يقال: رحمه الله، غفر الله له، أهل السنة والجماعة لا يشهدون لأحد لا بجنة ولا نار إلا من شهد له الرسول ﷺ، لكن يقال رحمه الله، غفر الله له، عفا الله عنه. أيش يدريه أنه مرحوم؟! وأيش يدريه أنه مغفور له؟! لكن تقول: فلان رحمه الله، فلان غفر الله له.\nس: ما تلحق بها كلمة \"شهيد\"؟\nالشيخ: لا ما تلحق بها؛ لأن الرسول ﷺ أطلق عليهم الشهداء، المقتول في سبيل الله يطلق عليه الشهادة فلا يغسل ولا يصلى عليه، شهيد في الحكم الشرعي، أما فيما يتعلق بالجنة والنار هذا إلى الله سبحانه وتعالى.","link":"https://binbaz.org.sa/fatwas/22873/حكم-لفظ-الشهيد-والمرحوم-ونحوهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إطلاق لفظ الشهيد أو المرحوم.mp3","categories":["شروح الحديث","مسائل متفرقة في الجنائز"]},{"id":2743,"question":"قول أنس بن النضر: لئن الله أشهدني قتال المشركين... نذر؟","title":"هل مِن النَّذْر قول: لئن الله أشهدني كذا لأفعلن؟","answer":"الجواب: قريب من النذر، ولكن ما هو بواضح النذر، ما قال: لله عليّ، بل إخبار بمعنى الوعد والمعاهدة.\nس:ما يكون النذر غير المشروط مباحًا؟\nالشيخ: محتمل أنه: ليرين الله ما أفعل، ما قال: \"علي\" ما أتى بصيغة الالتزام، لكنه وعد، والمؤمن إذا وعد وفّى، ولهذا وفّى  واجتهد يوم أُحُد.","link":"https://binbaz.org.sa/fatwas/22891/هل-من-النذر-قول-لىن-الله-اشهدني-كذا-لافعلن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/قول أنس بن النضر لئن الله أشهدني قتال المشركين هل هو نذر.mp3","categories":["الأيمان والنذور","شروح الحديث","الحلف بغير الله"]},{"id":2745,"question":"قول أم حارثة: اجْتَهَدْتُ عليه بالبكاء (أي على ولدها حارثة)، يعني تنوح عليه؟","title":"معنى قول أم حارثة \"اجْتَهَدْتُ عليه بالبكاء\"","answer":"الجواب: لا، بكاء ما فيه نِياحة، ما طلبت النِّياحة، ولهذا ما أنكر عليها النبي ﷺ، البكاء ما يضرّه، إنما يعذّب الله باللسان، بالصياح. س: الخطابي قال: هذا دل على الجواز أو يكون الحديث قبل التحريم؟ الشيخ: لا ما في بأس، البكاء لا حرج، مثل ما قال ﷺ: إن الله لا يعذّب بحزن القلب ولا بدمع العين وإنما يعذّب بهذا أو يرحم وأشار إلى لسانه. ولما مات ابنه إبراهيم قال عليه الصلاة والسلام: العين تدمع والقلب يحزن، ولا نقول إلا ما يرضي الرب، وإنا بفراقك يا إبراهيم لمحزونون.","link":"https://binbaz.org.sa/fatwas/22893/معنى-قول-ام-حارثة-اجتهدت-عليه-بالبكاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يعد من النياحة قول أم حارثة اجتهدت عليه بالبكاء.mp3","categories":["شروح الحديث"]},{"id":2751,"question":"في الحديث الثاني قال النبي ﷺ: تأتي في ميزانه، لم يقل في ميزان حسناته؟","title":"هل يُقال: في ميزانك، أم ميزان حسناتك؟","answer":"الجواب: يعني ميزان حسناته، هذا المراد، النصوص يفسّر بعضُها بعضًا.\nس: إذا أراد أن يدعو إنسان لأخيه يقول: الله يجعل في ميزان حسناتك، أو: في ميزانك، فقط؟\nالشيخ: لا، في ميزان حسناتك.","link":"https://binbaz.org.sa/fatwas/22899/هل-يقال-في-ميزانك-ام-ميزان-حسناتك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى حديث تأتي في ميزانه.mp3","categories":["شروح الحديث"]},{"id":2755,"question":"النَّضْح الذي ورد في أحاديث غَسْل الثوب الذي أصابه دم الحيض هل يراد به الغَسْل؟","title":"هل المقصود بالنَّضْح على الثوب الغَسْل؟","answer":"الجواب: الغَسْل الغَسْل، تَنْضَحُه: تغسله، يعني كما في الرواية الأخرى: تغسل الدم حتى يزول.","link":"https://binbaz.org.sa/fatwas/22903/هل-المقصود-بالنضح-على-الثوب-الغسل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل المقصود بالنضح الغسل.mp3","categories":["شروح الحديث","النجاسات وإزالتها"]},{"id":2756,"question":"الحديث الأول: منْ عَلِم الرَّمْي ثم تركه فليس منّا أو فقد عصى هل يأثم إذا نسيه؟","title":"معنى حديث \"منْ عَلِم الرَّمْي ثم تركه..\"","answer":"الجواب: نعم، هذا يعني: أعرض عنه حتى ينساه، ينبغي أن يكون بين وقت وآخر يرمي مع إخوانه، يحطون الشبح ويرمون، ولهذا حث النبي ﷺ على الرمي.\nس: ألا يدل هذا أن ترك الرمي كبيرة؟\nالشيخ: لا ما يلزم أنه كبيرة، فقد عصى المعصية ما يلزم أنها كبيرة، وليس منا بعض أهل العلم يرى أن ليس منا أنها من الكبائر، ولكن محل نظر عند الجمهور، الكبائر عند الجمهور: ما فيه وعيد بالنار أو لعنة أو حد في الدنيا كحد الزنا وحد السرقة، على كل حال معصية، ويكفي كونه معصية.","link":"https://binbaz.org.sa/fatwas/22904/معنى-حديث-من-علم-الرمي-ثم-تركه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث من علم الرمي ثم تركه فليس منا...mp3","categories":["شروح الحديث"]},{"id":2757,"question":"يقول الرسول ﷺ: إن الله يدخل بالسهم الواحد ثلاثة الجنة هل نقل الدروس من العلماء أو الدعاة أو المحاضرات والخطب لنفع المسلمين، كالتسجيلات تنقلها من المشايخ وبثها للناس، هل يدخلون الجنة؟","title":"هل يدخل العلمُ في دخول الجنة بالسهم الواحد؟","answer":"الجواب: يُرجى فيه إن شاء الله، هذا من تعليم العلم.\nس: سواء كان كتيبات أو أشرطة؟\nالشيخ: نعم محاضرات أو أشرطة أو كتب، كلها يُرجى فيها الخير، قال النبي ﷺ في الحديث الصحيح: من سلك طريقًا يلتمس فيه علمًا سهّل الله به طريقًا إلى الجنة، منْ دلّ على خير فله مثل أجر فاعله هذا دلالة على الخير، التَّعَلُّم.","link":"https://binbaz.org.sa/fatwas/22905/هل-يدخل-العلم-في-دخول-الجنة-بالسهم-الواحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث إن الله يدخل بالسهم الواحد ثلاثة الجنة.. هل نقل العلم داخل فيه.mp3","categories":["شروح الحديث"]},{"id":2759,"question":"قول الرسول ﷺ: من مات ولم يغزُ مات علي شعبة من النفاق هل المراد به أي مسلم، أو الجندي؟","title":"ما معنى حديث \"من مات ولم يغزُ...\"؟","answer":"الجواب: يعني: يحدث نفسه، يكون عنده نية لو قام سوق الغزو يغزو. لا غزا ولا حدث نفسه، ما هو على باله، يعني ينبغي أن يكون على باله يحدّث نفسه لو قام الجهاد لجاهدت.","link":"https://binbaz.org.sa/fatwas/22907/ما-معنى-حديث-من-مات-ولم-يغز","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من مات ولم يغزو مات على شعبة من النفاق.. هل هو عام.mp3","categories":["شروح الحديث"]},{"id":2770,"question":"صحة إسناد حديث أبي أمامة (سياحة أمتي الجهاد)؟","title":"ما صحة حديث \"سياحة أمتي الجهاد\"؟","answer":"الجواب: قوّاه المؤلف، والوليد بن مسلم ثقة لكن إذا دلس، إذا عنعن يكون مدلسًا، لكن يشهد له الحديث المتقدم الذي رواه مسلم.","link":"https://binbaz.org.sa/fatwas/22918/ما-صحة-حديث-سياحة-امتي-الجهاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث إن سياحة أمتي الجهاد.mp3","categories":["شروح الحديث","الحكم على الأحاديث"]},{"id":2774,"question":"الذهاب إلى زيارة أماكن القوم المُعَذّبين كمدائن صالح؟","title":"حكم زيارة أماكن القوم المُعَذّبين","answer":"الجواب: النبي ﷺ قال: لا تدخلوا على هؤلاء المُعَذّبين إلا أن تكونوا باكين لئلا يصيبكم ما أصابهم ولما مَرَّ عليهم أسرع عليه الصلاة والسلام وقَنَّع رأسه.\nس: ما ورد التباكي أو تتباكوا؟\nالشيخ: في سنده مقال، لكن المقصود أنه لا يدخل عليهم إلا بسرعة مارَّا إذا دعت الحاجة.\nس: إذًا يَحْرُم السفر؟\nالشيخ: مثل ما تقدم في بلاد المشركين، فيه تفصيل.\nس:للآثار؟\nالشيخ: للآثار لا، إذا كان الآثار مثل قوم صالح والنبي ﷺ نَبَّه عليه، وقال: لا تدخلوا عليهم إلا وأنتم باكين لأنه ما في حاجة.","link":"https://binbaz.org.sa/fatwas/22922/حكم-زيارة-اماكن-القوم-المعذبين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم زيارة أماكن القوم المعذبين.mp3","categories":["شروح الحديث","الحكم على الأحاديث"]},{"id":2782,"question":"الكُفّار لا يدخلون في الثلاث والسبعين؟","title":"معنى حديث الافتراق على ثلاث وسبعين فرقة","answer":"الجواب: لا، هذا في حق المنتسبين للأمة، المنتسبين للإجابة، لإجابة النبي ﷺ المدعون للإسلام يعني.\nس: هل يجوز الربط بين هذا الحديث وبين قوله تعالى: وَلَقَدْ صَدَّقَ عَلَيْهِمْ إِبْلِيسُ ظَنَّهُ فَاتَّبَعُوهُ إِلَّا فَرِيقًا مِنَ الْمُؤْمِنِينَ [سبأ:20]؟\nالشيخ: لا شك، يدخل فيه، هذا داخل فيه الفريق، هم أهل السنة والجماعة، هم الناجون، والبقية أصابهم ما أصابهم ما بين عاصٍ وما بين كافر.\nس: بعضهم خص الطائفة الناجية بأهل العلم وبعضهم أهل الحديث؟\nالشيخ: هذا خواصهم يعني، وإلا أهل السنة يعم العامي وغير العامي، من اتبع الرسول ﷺ ولو كان عاميًّا فهو من أهل السنة والجماعة، لكن أئمتهم هم العلماء الأخيار من الصحابة ومن بعدهم وأهل الحديث الشريف....... زوجته وأمه وأخته ولو عامية مثله تبعًا له.\nس: ألا يكون قصد الإمام أحمد بأهل الحديث هم المتبعون للحديث لا هم العلماء فقط؟\nالشيخ: لا، مراده علماء الحديث لكن مراده الباقين تبع لهم، يعني البقية تبع علماءهم.\nس: الأشاعرة يدخلون في أهل السنة والجماعة؟\nالشيخ: لا، ما هم من أهل السنة والجماعة، متوعدون؛ لأنهم نفاة الصفات إلا سبع وإلا عشر  وإلا عشرين على اختلاف بينهم.\nس: يعني مذهب العوام مذهب علمائهم ولا يجوز لهم الخروج عن ذلك؟\nالشيخ: نعم العامة تبع علمائهم.","link":"https://binbaz.org.sa/fatwas/22930/معنى-حديث-الافتراق-على-ثلاث-وسبعين-فرقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/شرح حديث افترقت اليهود على إحدى وسبعين فرقة...mp3","categories":["شروح الحديث"]},{"id":2790,"question":"ما معنى قوله: لا شرطان في بيع؟","title":"ما معنى \"لا شرطان في بيع\"؟","answer":"الجواب: على ظاهره عند جمع من أهل العلم، وآخرون أوّلوها على بيعتين في بيعة. وظاهره أنه ما يشترط شرطان في بيع، خارج عن مقتضى العقد، شرطين زائدين، لكن واحد لا بأس، واحد مثل ما اشترط جابر لما باع البعير على النبي ﷺ قال: يا رسول الله أشترط أني أبقى عليه حتى أصل إلى المدينة، فأعطاه النبي ﷺ الشرط. فإذا اشترى البيت على أن يسكنه شهرًا شهرين سنة، أو سيارة قال: أبيعك إياها لكن بشرط أني أذهب عليها للمحل الفلاني، وما أشبه ذلك، أما الشرطان كأن يشترط البائع أو المشتري شرطين خارجين عن البيع بخلاف المتعلقة بالثمن أو بالمبيع، هذه من أوصافها، كأن يقول: أبيعك عبدًا كاتبًا بالغًا صفته كذا، هذه ولو كَثُرت من صفة المبيع، لكن الشيء الخارج البعيد ما هو من صفات المبيع، مثل ما قال الفقهاء: حمل الحطب وتكسيره، شرطي أن تحمله وتكسره، شرطي أن تحمل الدواب وتطبخها، عند جمع من أهل العلم أن هذا لا يصلح، شرط واحد بس.","link":"https://binbaz.org.sa/fatwas/22938/ما-معنى-لا-شرطان-في-بيع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى لا شرطان في بيع.mp3","categories":["البيوع","شروح الحديث"]},{"id":2791,"question":"الأمر بقوله: فَلْيُطْعِمْهُ للوجوب؟","title":"هل الأمر للوجوب في \"فَلْيُطْعِمْهُ ممَّا يَأْكُلُ\"؟","answer":"الجواب: ما هو بلازم، للسُّنِّية؛ لأنه في الحديث..... طعامه وكسوته، ولا يكلف من العمل إلا ما يُطاق، إذا أطعمه ما يليق وكساه ما يليق؛ كفى، لكن كونه من جنسه، مثلما فعل أبو ذر؛ يكون أكمل.","link":"https://binbaz.org.sa/fatwas/22939/هل-الامر-للوجوب-في-فليطعمه-مما-ياكل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث فليطعمه ممّا يأكل... هل الأمر للوجوب.mp3","categories":["شروح الحديث"]},{"id":2801,"question":"حديث معقل (الْعِبادَةُ في الهَرْجِ كَهِجْرَةٍ إلَيَّ) ما يكون خاصًّا بوقوع القتل؟","title":"معنى حديث \"العبادة في الهرج كهجرة إليّ\"","answer":"الجواب: الفتن، الخلاف فتنة، بين القبيلة أو بين الشِّعب أو بين القرية.\nس: ضابط الفتنة التي تُجْتَنب؟\nالشيخ: اللي ما يظهر فيها الحق، أما إذا عرفت الحق مع فلان تساعد صاحب الحق ويُنصر انصر أخاك ظالمًا أو مظلومًا، المظلوم يُنصر بإعطائه حقه والظالم يُمْنَع.","link":"https://binbaz.org.sa/fatwas/22949/معنى-حديث-العبادة-في-الهرج-كهجرة-الي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث العبادة في الهرج كهجرة إليّ.. خاصا بوقوع القتل.mp3","categories":["شروح الحديث"]},{"id":2805,"question":"حديث السبعة الذين يُظِلِّهُم الله في ظله يوم لا ظل إلا ظله يُفسر بهذا الحديث (سبعة في ظِلِّ العَرشِ) أنه ظل العرش؟","title":"معنى الظِّلّ في حديث السبعة الذين يُظِلِّهُم الله","answer":"الجواب: يفسر بهذا وهذا، فالعرش له ظل، والله له ظل لا يعلم كيفيته إلا هو ، جاء هذا وهذا، جاء ظل العرش، وجاء ظله جل وعلا.","link":"https://binbaz.org.sa/fatwas/22954/معنى-الظل-في-حديث-السبعة-الذين-يظلهم-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تفسير حديث السبعة الذين يظلهم الله في ظله بظل العرش.mp3","categories":["شروح الحديث"]},{"id":2818,"question":"يفهم من الحديث: من يرد الله به خيرًا يفقهه في الدين الذي ما يتفقه في الدين ما أراد الله به خيرًا؟","title":"هل مَنْ لم يتفقه في الدين لم يُرِد الله به خيرًا؟","answer":"الجواب: ما أراد الله به خيرًا، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/22967/هل-من-لم-يتفقه-في-الدين-لم-يرد-الله-به-خيرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل الذي لم يتفقه في الدين لم يرد الله به خيرا.mp3","categories":["شروح الحديث"]},{"id":2819,"question":"قول الرسول ﷺ: بلغوا عني ولو آية هل هي خاصة بطالب العلم؟","title":"معنى \"بلغوا عني ولو آية\" ومن المكلّف بها؟","answer":"الجواب: لا، حتى غيره، كل مؤمن يستطيع يبلغ ولو آية، طالب العلم وكل مؤمن.\nس: بعض الناس يفهم أن بلغوا عني ولو آية على ظاهره، ويخرج إلى القرى وإلى الدول ويدعو الناس ثم يتعرض إلى الفتاوى الكبرى بحيث ممكن يقع في حرج؟\nالشيخ: إذا عَلَّم الناس القرآن، إذا خرج يعلّم القرآن فلا حرج، لكن لا يجوز له يدخل فيما لا يعنيه، لا يجوز له يتكلم في العلم وهو على غير بصيرة، لكن يعلّمهم القرآن، يعلّمهم الفاتحة، يعلّمهم المُفَصّل، جزاه الله خيرًا يعلمهم، تعليم القرآن متيسّر ولو ما كان عنده علم، يعلمهم القرآن، يقول النبيﷺ: خيركم من تعلم القرآن وعلمه. تعلّمنا على ناس لا يعرفون شيئًا من العلم، لكن أخذنا عنهم القرآن ونحن صغار، فيهم خير وفيهم بركة غفر الله لهم، صبروا على التعليم وصبروا على توجيه الطلبة ولو ما كان عندهم علم، لكن عندهم صبر على تعليم الناس القرآن وتردداه عليهم وتفقيههم فيه حتى يحفظوه، هذا عمل شرعي، يقول عثمان  عن النبي ﷺ: خيركم من تعلم القرآن وعلمه بلغوا عني ولو آية.\nس: الآية هنا: الحكمة، أو آية القرآن؟\nالشيخ: آيات القرآن.","link":"https://binbaz.org.sa/fatwas/22968/معنى-بلغوا-عني-ولو-اية-ومن-المكلف-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/بلغوا عني ولو آية هل هي خاصة بطالب العلم.mp3","categories":["شروح الحديث"]},{"id":2829,"question":"حديث: لعن الله مَنْ آوَى محدثًا هل يدخل فيه مَن امتدح المبتدع؟","title":"هل يدخل مَدْحُ المبتدع في \"مَن آوى محدثا\"؟","answer":"الجواب: الإيواء: نصره وحمايته، آوى محدثًا إنْ نصره وحماه من إقامة الحد عليه أو تأديبه، وإذا أيّده أو نصره هذا أعظم.\nس: هل هناك زيادة على الثلاث هذه؟\nالشيخ: غيرها داخلٌ فيها، ما أخْبُر شيئًا يخرج يشذّ عنها.","link":"https://binbaz.org.sa/fatwas/22978/هل-يدخل-مدح-المبتدع-في-من-اوى-محدثا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث لعن الله من آوى محدثا.. هل يدخل فيه من امتدح المبتدع.mp3","categories":["شروح الحديث"]},{"id":2833,"question":"حديث الرسول ﷺ: من خرج في طلب العلم فهو في سبيل الله فالمقصود -أحسن الله إليك- دروس للسفر لها أو طلب ـمثلًاـ الدروس أو المحاضرات أو الخطب؟","title":"ما العلمُ الذي يكون الخروج له في سبيل الله؟","answer":"الجواب: كل وُجوه العلم.","link":"https://binbaz.org.sa/fatwas/22982/ما-العلم-الذي-يكون-الخروج-له-في-سبيل-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بحديث من خرج في طلب العلم فهو في سبيل الله.mp3","categories":["شروح الحديث"]},{"id":2840,"question":"من فقد والديه وصبر واحتسب... هل يُرجى له أن يدخل في حديث مَن فقد ولده؟","title":"هل يدخل فقدانُ الوالدين في أجر فَقْد الوَلَد؟","answer":"الجواب: إن شاء الله، عام، الوالدان والأقارب، كلهم إن شاء الله يُرجى له الخير، إن حمد الله واسترجع: إنا لله وإنا إليه راجعون.","link":"https://binbaz.org.sa/fatwas/22990/هل-يدخل-فقدان-الوالدين-في-اجر-فقد-الولد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/فقدان الوالدين هل يدخل في حديث من فقد ولده..mp3","categories":["شروح الحديث"]},{"id":2847,"question":"حديث أنس: جاهدوا المشركين بأموالكم وبألسنتكم الترتيب على الأفضلية هنا؟","title":"ما الحكمة من تقديم الجهاد بالمال في الترتيب؟","answer":"الجواب: الواجب الجميع، كلها واجبة؛ بالمال والنفس واللسان.\nس: لكن تقديم المال؟\nالشيخ: المال قدّمه الله في غالب الآيات؛ لأنه أعم نفعًا، يُشترى منه السلاح ويُجهّز به الجيش، ويُنْفَق على أهل المجاهدين إلى غير هذا، فيه مصالح كثيرة ولهذا قدّمه الله على النفس في مواضع كثيرة إلا في آية التوبة إِنَّ اللَّهَ اشْتَرَى مِنَ الْمُؤْمِنِينَ أَنْفُسَهُمْ وَأَمْوَالَهُمْ [التوبة:111] قدم النفس.  فالمقصود أن الجهاد بالمال أعم وأنفع، فقد يُحتاج إلى المال ولا يُحتاج للشخص.","link":"https://binbaz.org.sa/fatwas/23000/ما-الحكمة-من-تقديم-الجهاد-بالمال-في-الترتيب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث جاهدوا المشركين بأموالكم وبألسنتكم هل الترتيب على الأفضلية.mp3","categories":["شروح الحديث"]},{"id":2856,"question":"حديث من قرأ آية الكرسي بعد كل صلاة لم يحل بينه وبين دخول الجنة إلا الموت؟","title":"ما صحة فضل آية الكرسي بعد كل صلاة؟","answer":"الجواب: لا بأس، جاء حديث له طرق بعضها جيد، يستحب بعد الصلاة بعد الذكر، يأتي بآية الكرسي، وهذا من أسباب دخول الجنة لمن مات على غير الكبائر، أما من مات على الكبائر فهو مُعَرّض للوعيد مطلقًا، من مات على بعض كبائر الذنوب فهو مُعَرّض للوعيد، وهو مُقَيِّد لأحاديث الفضائل، مثل ما قال ﷺ: الصلوات الخمس، والجمعة إلى الجمعة، ورمضان إلى رمضان مكفرات لما بينهن ما لم تُغْشَ الكبائر، والله يقول: إِنْ تَجْتَنِبُوا كَبَائِرَ مَا تُنْهَوْنَ عَنْهُ نُكَفِّرْ عَنْكُمْ سَيِّئَاتِكُمْ وَنُدْخِلْكُمْ مُدْخَلًا كَرِيمًا[النساء:31] فشرط في التكفير ودخول الجنة: اجتناب الكبائر، فالواجب الحذر من المعاصي وألا يموت على شيء منها مصرًّا، نسأل الله للجميع العافية والسلامة.","link":"https://binbaz.org.sa/fatwas/23009/ما-صحة-فضل-اية-الكرسي-بعد-كل-صلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من قرأ آية الكرسي بعد كل صلاة لم يحل بينه وبين دخول الجنة إلا الموت.mp3","categories":["شروح الحديث"]},{"id":2867,"question":"ما يقال أن المقصود بالآل: الأزواج والذرية، كما في رواية أبي حميد؟","title":"هل المقصود بالآل: الأزواج والذرية؟","answer":"الجواب: يدخلون فيه مثل ما قال جل وعلا: أَدْخِلُوا آلَ فِرْعَوْنَ أَشَدَّ الْعَذَابِ [غافر:46] يعني أتباع فرعون، فالأزواج والذرية هم من الآل، ولا يدخل فيهم من ليس منهم كأبي لهب وأبي طالب وأم النبي ﷺ وأبيه، غير داخلين؛ لأنهم ليسوا من المؤمنين.","link":"https://binbaz.org.sa/fatwas/23021/هل-المقصود-بالال-الازواج-والذرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل المقصود بالآل الأزواج والذرية.mp3","categories":["شروح الحديث"]},{"id":2868,"question":"حديث: إذا استيقظ أحدكم فلا يغمس يده في الإناء الحديث للوجوب؟","title":"هل حديث \"فلا يغمس يده في الإناء\" للوجوب؟","answer":"الجواب: هذا هو الأصل، النهي للتحريم، والأمر للوجوب، في لفظ: لا يغمس، وفي اللفظ الآخر: فليغسل يديه قبل أن يدخلهما في الإناء ثلاث مرات فالأصل للوجوب.","link":"https://binbaz.org.sa/fatwas/23022/هل-حديث-فلا-يغمس-يده-في-الاناء-للوجوب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث إذا استيقظ أحدكم فلا يغمس يده في الإناء هل الأمر للوجوب.mp3","categories":["شروح الحديث"]},{"id":2872,"question":"حديث عائشة...؟","title":"معنى حديث \"كان يذكر الله على كل أحيانه\"؟","answer":"الجواب: الحديث الصحيح: «كان الرسول ﷺ يذكر الله على كل أحيانه» رواه مسلم في الصحيح من حديث عائشة رضي الله عنها، وأصله في البخاري «كان الرسول ﷺ يذكر الله في كل أحيانه».","link":"https://binbaz.org.sa/fatwas/23027/معنى-حديث-كان-يذكر-الله-على-كل-احيانه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث كان الرسول يذكر الله على كل أحيانه.mp3","categories":["شروح الحديث"]},{"id":2874,"question":"حديث: لعن الله زوّارات القبور صيغة زوّارات؟","title":"هل صيغة \"زوّارات القبور\" تعني الكثرة فقط؟","answer":"الجواب: جاء زوّارات وجاء زائرات كلها ممنوعة، لا كثرة ولا قلة، لا يزرن القبور.","link":"https://binbaz.org.sa/fatwas/23029/هل-صيغة-زوارات-القبور-تعني-الكثرة-فقط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صيغة زوارات في حديث لعن الله زوارات القبور.mp3","categories":["شروح الحديث"]},{"id":2888,"question":"ما جاء أن \"من أعتق أربعة أنفس من ولد إسماعيل...\" ما الحكمة من أربعة أنفس؟","title":"لماذا خُصَّ \"وَلْد إسماعيل\" في فضل العتق؟","answer":"الجواب: يعني أولاد الأنبياء، الإحسان فيهم أكثر أجرًا.","link":"https://binbaz.org.sa/fatwas/23043/لماذا-خص-ولد-اسماعيل-في-فضل-العتق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكمة من ذكر من أعتق أربعة أنفس من ولد إسماعيل.mp3","categories":["شروح الحديث"]},{"id":2890,"question":"حديث سعد (عن الأعرابي جاء إلى النبي ﷺ وسأل... وفيه: قُل لا إله إلا الله وحده لا شريك له الله أكبر كبيرًا...) هل يُؤخذ منه استحباب الثناء على الله قبل الدعاء؟","title":"حكم الثناء على الله قبل الدعاء","answer":"الجواب: سأل عن هذا، وسأل عن هذا، ولكنه يعرف مِن أدلة أخرى، يُثني على الله، ثم يصلي على النبي ﷺ، ثم يدعو، هذا معروف من أدلة أخرى، وإلا هذا السائل سأل عما يُرضِي الله وعما يَخُصُّ نفسه.\nس: هل يُستثنى من ذلك، أحسن الله إليك، دعاء الوتر، دعاء القنوت؟\nالشيخ: ما ورد فيه أن يُقَدَّم شيء، يبدأ: اللهم اهدنا.","link":"https://binbaz.org.sa/fatwas/23045/حكم-الثناء-على-الله-قبل-الدعاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث قُل لا إله إلا الله وحده لا شريك له الله أكبر كبيرا.. هل يؤخذ منه استحباب الثناء.mp3","categories":["شروح الحديث","الأدعية والأذكار"]},{"id":2906,"question":"في حديث سعد بن أبي وقاص (أَيَعْجِزُ أَحَدُكُمْ أَنْ يَكْسِبَ، كُلَّ يَومٍ أَلْفَ حَسَنَةٍ؟ فَسَأَلَهُ سَائِلٌ مِن جُلَسَائِهِ: كيفَ يَكْسِبُ أَحَدُنَا أَلْفَ حَسَنَةٍ؟ قالَ: يُسَبِّحُ مِئَةَ تَسْبِيحَةٍ، فيُكْتَبُ له أَلْفُ حَسَنَةٍ، أَوْ يُحَطُّ عنْه أَلْفُ خَطِيئَةٍ) قال: فيكتب له ألف حسنة أو يحط عنه ألف خطيئة . أو هنا للتنويع أو للشك من الراوي؟","title":"معنى \"يُكتب له.. أو يُحَط عنه\" في الحديث","answer":"الجواب: محتمل أنه شك، أو أنه يحصل له هذا وهذا، إما مائة حسنة أو يمحى عنه مائة سيئة، والمعروف، مثل ما تقدّم، الحسنة بعشر أمثالها.","link":"https://binbaz.org.sa/fatwas/23062/معنى-يكتب-له-او-يحط-عنه-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث يكتب له ألف حسنة أو يحط عنه ألف خطيئة.. هل هذا للتنويع أو للشك من الراوي.mp3","categories":["شروح الحديث"]},{"id":2908,"question":"لمّا سأل الصحابي  الرسول ﷺ مرافقته للجنة فقال الرسول ﷺ: أعِنِّي على نفسك بكثرة السجود هل المقصود الفروض أو النوافل؟","title":"معنى حديث \"أعنِّي على نفسك بكثرة السجود\"","answer":"الجواب: النوافل نعم، الفريضة مفروغٌ منها؛ مِن أسباب السعادة، لكن زيادة في النوافل، كثرة السجود يعني كثرة الصلوات، ما سجد العبد لله سجدة إلا رفعه الله بها درجة وحط عنه بها خطيئة، والله المستعان.","link":"https://binbaz.org.sa/fatwas/23064/معنى-حديث-اعني-على-نفسك-بكثرة-السجود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بحديث أعني على نفسك بكثرة السجود.mp3","categories":["شروح الحديث"]},{"id":2911,"question":"حديث الفضل بن عباس الذي قال فيه إن النبي ﷺ زار العباس بن عبدالمطلب في بادية لهم وصلى عنده، وكان أمامه كلبة وحمارة، كيف يوجه مع الأحاديث الصحيحة بأن الكلب والحمار والمرأة تقطع الصلاة؟","title":"حكم مَنْ صلى وأمامه حيوان دون مرور؟","answer":"الجواب: ما في مرور، ما في إلا وجدت قُدامه، ما في مرور، هذه رواه النسائي. القاطع: المرور، أما وجودها أمامه من غير مرور من جانب إلى جانب ما يسمى مرورًا.\nس: عن بُعد؟\nالشيخ: إيه، وليس له سُترة فمكانها بعيدة، ما له سترة صلاها إلى غير سُترة.\nس: ما يحمل على أنه كان له سُترة؟\nالشيخ: لا، جاء في الحديث وليس له سُترة وهو دليل على عدم وجوب السترة، ولكنها سنة.\nس: ما هو ضعيف حديث الفضل؟\nالشيخ: لا، له أسانيد جيدة، بعضها ضعيف وبعضها جيد.","link":"https://binbaz.org.sa/fatwas/23067/حكم-من-صلى-وامامه-حيوان-دون-مرور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الجمع بين حديث أن النبي صلى عند العباس بن عبدالمطلب وكان أمامه كلبة وحمارة.mp3","categories":["شروح الحديث"]},{"id":2914,"question":"من يقول أن وصية الرسول ﷺ لأم المؤمنين جويرية (سبحان الله عدد خلقه...) أنها تكفي عن الجلوس بعد صلاة الفجر وذكر الله حتى الإشراق؟","title":"فضل الذكر بعد الفجر إلى الإشراق","answer":"الجواب: هذا زُود خير؛ إذا ضمها إلى الجلوس كما كان النبي ﷺ يجلس، كان يجلس في مصلاه حتى تطلع الشمس طلوعًا حسنًا مع إتيانه بالأذكار عليه الصلاة والسلام، إن ضمت الأذكار إلى جلوسها كان هذا أكثر للخير وأكثر للفضل وأكثر للأجر.","link":"https://binbaz.org.sa/fatwas/23070/فضل-الذكر-بعد-الفجر-الى-الاشراق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الجمع بين الجلوس لذكر الله بعد صلاة الفجر وصلاة الضحى.mp3","categories":["شروح الحديث"]},{"id":2915,"question":"في كتاب فتح المجيد في إبطال السحر أنه يأخذ سبع ورقات من سدر أخضر فيدقه بين حجرين ثم يضربه بالماء، ويقرأ فيه آية الكرسي والقوافل. ما المقصود بالقوافل؟","title":"ما السُّوَرُ المسمّاةُ بالقواقل؟","answer":"الجواب: قُلْ يَا أَيُّهَا الْكَافِرُونَ [الكافرون:1] و قُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص: 1] و قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ [الفلق:1] و قُلْ أَعُوذُ بِرَبِّ النَّاسِ [الناس:1] هذا من علاج السحر.\nس: تسمى القوافل أو القواقل؟\nالشيخ: القواقل؛ التي أولها قُلْ.","link":"https://binbaz.org.sa/fatwas/23071/ما-السور-المسماة-بالقواقل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إبطال السحر بآية الكرسي والقوافل ما المقصود بالقوافل.mp3","categories":["شروح الحديث","الطب والتداوي"]},{"id":2925,"question":"في الحديث أن أحب الكلام إلى الله سبحان الله وبحمده، وفي الحديث الذي مَرّ بنا: أفضل الذكر لا إله إلا الله؟","title":"ما الأصح في أحب الكلام إلى الله؟","answer":"الجواب: لا إله إلا الله منها، هي أحد الأربع.\nس: لا، سبحان الله وبحمده حديث أبي ذر؟\nالشيخ: هذا فيه نظر، قد يكون منسوخًا، قد يكون: مِن أحب، معنى مِن، التقدير مِن، مِن أحب الأعمال إلى الله؛ لأن أحاديث أحب الكلام إلى الله صريحة في التفضيل، وفي حديث الصحيح الآخر: الإيمان بضع وسبعون شعبة، فأفضلها قول: لا إله إلا الله، وأدناها.. صريح، أدناها إماطة الأذى عن الطريق بعض الأشياء التي قد يُخشى أنها تؤول على أنها \"مِن أحب\" يعني.","link":"https://binbaz.org.sa/fatwas/23081/ما-الاصح-في-احب-الكلام-الى-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الجمع بين حديث أحب الكلام إلى الله سبحان الله وبحمده، وحديث أفضل الذكر لا إله إلا.mp3","categories":["شروح الحديث"]},{"id":2926,"question":"حديث عائشة: كان ﷺ يذكر الله على كل أحيانه. في قول لمن استدل به على أن الجُنُب يقرأ القرآن؟","title":"حكم قراءة الجُنُب القرآن","answer":"الجواب: ما هو بدليل، هذا ذِكر مستقل، والخلاف مشهور، لكن ما هو بدليل، حديث علي صريح.\nس: ذَكَرَت أنه كان يذكر الله على كل أحيانه، يُستثنى من ذلك أحوال مثلًا لو كان...؟\nالشيخ: على حال حال الحمام معروفة، كان إذا دخل الخلاء وضع خَاتَمَه، من باب أوْلى بالنسبة لمحل قضاء الحاجة يَكفّ عن ذلك، إلا في قلبه؛ ذكر الله في قلبه لا بأس.","link":"https://binbaz.org.sa/fatwas/23082/حكم-قراءة-الجنب-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يستدل بحديث أن النبي يذكر الله على كل أحيانه على جواز قراءة الجنب للقرآن.mp3","categories":["شروح الحديث"]},{"id":2933,"question":"بالنسبة للسكينة (في حديث ونَزَلَتْ عليهم السَّكِينَة)؟","title":"ما معنى \"ونَزَلَتْ عليهم السَّكِينَة..\"؟","answer":"الجواب: مثل ما تقدم: مخلوق عظيم ينزل يكون معه ملائكة، يَسْمَعُ الذكر، بعض أهل العلم قال: إنه نوع من الملائكة، وظاهر النصوص أنه نوع كالسحابة تكون فيها ملائكة تستمع الذكر وتستمع القراءة، مثل ما رأى أُسيد بن حضير رضي الله عنه أنه كان يصلي في الليل فنزلت تلك السكينة، فيها أمثال السُّرُُج، فأخبر النبي ﷺ أنها تنزّلت لقراءة القرآن.\nس: علاماتها على البشر وأهل العلم وطلاب العلم؟\nالشيخ: ما في علامات، ما في علامات على طالب العلم، لكن فيه الحث على الإخلاص والعناية بذكر الله وقراءة القرآن عن رغبة وعن إخلاص لله جل وعلا، هذه من أسباب تَنَزُّل الملائكة، ومن أسباب انتفاع العبد بعمله ومضاعفته له إذا أخلص لله وصدق في العمل.\nس: عرّفها بعضُهم بقوله: حالة يطمئن بها القلب فيسكن عن الميل إلى الشهوات؟\nالشيخ: لا، ما هي بهذه السكينة، السكينة تنزل من السماء في الجو بين السماء والأرض.\nس: في لفظ للحديث يقول النبي ﷺ: تلك الملائكة..؟\nالشيخ: يعني: في السكينة تنزل في السحابة تستمع القرآن.","link":"https://binbaz.org.sa/fatwas/23089/ما-معنى-ونزلت-عليهم-السكينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث ونزلت عليهم السّكينة... ما هي السكينة.mp3","categories":["شروح الحديث"]},{"id":2934,"question":"قوله: فُضَلا (في حديث إِن لله ملائكة سيارة فُضَلا) يعني: زيادة على الحفظة؟","title":"معنى حديث \"إِن لله ملائكة سيارة فُضَلا..\"؟","answer":"الجواب: فُضَلا يعني كأنهم مفرّغون لهذا الشيء.  وفي اللفظ الآخر: إن لله ملائكة سياحين يبلّغوني عن أمتي السلام عليه الصلاة والسلام.\nس: يَحُفُّونهم بأجنحتهم؟\nالشيخ: يعني: يَقْرُبُون منهم، يعني: قريبين منهم، ما هو بعيدين.","link":"https://binbaz.org.sa/fatwas/23090/معنى-حديث-ان-لله-ملاىكة-سيارة-فضلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بقوله في الحديث إِن لله ملائكة سيارة فضلاء...mp3","categories":["شروح الحديث"]},{"id":2937,"question":"ينالون الأجر بقوله: قوموا مغفورًا لكم من بمجالس الذكر؟","title":"معنى \"قوموا مغفورًا لكم\" لمجالس الذكر","answer":"الجواب: ما في شك؛ تنزل عليهم السكينة، وغشيتهم الرحمة، وحفتهم الملائكة، وذكرهم الله فيمن عنده، هذا فضل عظيم، الرحمة تحفهم ويذكرهم الله فيمن عنده، الله يجعلنا وإياكم منهم، هذا فضله ، لكن المهم الإخلاص لله في ذلك، والصدق، وعدم الرياء.","link":"https://binbaz.org.sa/fatwas/23093/معنى-قوموا-مغفورا-لكم-لمجالس-الذكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث قوموا مغفورا لكم.. هل نال الأجر كل من كان في مجالس الذكر.mp3","categories":["شروح الحديث"]},{"id":2956,"question":"يقول إلى آخر الحديث فكم مِمّن لا كافي له ... إلى آخره؟","title":"ما معنى حديث \"فكم ممن لا كافي له..\"؟","answer":"الجواب: نعم، الحمد لله الذي أطعمنا وسقانا وكفانا وآوانا، فكم مِمّن لا كافي له ولا مؤوي، يعني أمة كثيرة ليس لها كافٍ ولا مؤوٍ، بل مطرَّدة في كل مكان، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/23112/ما-معنى-حديث-فكم-ممن-لا-كافي-له","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث ... فكم ممن لا كافي له...mp3","categories":["شروح الحديث"]},{"id":2960,"question":"أفضل الدعاء والإنسان ساجد؟","title":"ما أفضل أوقات الدعاء؟","answer":"الجواب: مثل ما قال ﷺ: أقرب ما يكون العبد من ربه وهو ساجد فأكثروا الدعاء رواه مسلم في الصحيح، وفي الحديث الآخر يقول ﷺ: أما الركوع فعظّموا فيه الرب، وأما السجود فاجتهدوا في الدعاء فقَمِنٌ - يعني حَرِيٌّ - أن يُستجاب لكم رواه مسلم أيضًا. وفي آخر الصلاة قبل أن يسلم محل دعاء أيضًا، وبين السجدتين: ربي اغفر لي، ربي اغفر لي، فإذا دعا مع المغفرة فلا بأس.\nس: سواء كان في الفريضة أو في النفل؟\nالشيخ: في الفرض والنفل، نعم.","link":"https://binbaz.org.sa/fatwas/23116/ما-افضل-اوقات-الدعاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أقرب ما يكون العبد من ربه وهو ساجد.mp3","categories":["شروح الحديث","الأدعية والأذكار"]},{"id":2965,"question":"حديث أنس الذي في الصحيحين أنهم مَرُّوا بجنازة فأثنَوْا عليها شرًّا فقال الرسول ﷺ وَجَبَتْ؟","title":"معنى حديث \"مَرُّوا بجنازة فأثنَوْا عليها شرَّا..\"","answer":"الجواب: المعنى صحيح، المعنى: من أظهر الفسوق لا غيبة له، من أظهر الشر لا غيبة له، ولهذا قال: وجبت وجبت يعني وجبت له النار، الذي أظهر شره قالوا لما مر بجنازة قالوا: إنه ما فيه خير، وأنه كذا وكذا وكذا، فقال: وجبت ما له غيبة، من أظهر الفسق، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/23121/معنى-حديث-مروا-بجنازة-فاثنوا-عليها-شرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى حديث مروا بجنازة فأثنوا عليها شرا فقال الرسول وجبت..mp3","categories":["شروح الحديث"]},{"id":2966,"question":"كيف الجمع بين حديث أبي هريرة - تعوّذوا بالله من جهد البلاء، ودرك الشقاء، وسوء القضاء، وشماتة الأعداء- وما ورد في الأحاديث من النهي عن السجع؟","title":"ما السَّجْعُ المَنْهِيُّ عنه في الخُطُب؟","answer":"الجواب: السجع المقصود: الذي يتكلّفه. وأما السجع الذي غير مقصود ما فيه شيء، كثيرٌ في القرآن وفي السنة، غير مقصود. أما التَّكَلُّف ما ينبغي التَّكَلُّف، كما قال ﷺ في الذي رد على النبي ﷺ قال: كيفَ أَغْرَمُ مَن لا شَرِبَ وَلَا أَكَلَ، وَلَا نَطَقَ وَلَا اسْتَهَلَّ، فَمِثْلُ ذلكَ يُطَلُّ؟ قال ﷺ: سَجْع مِن سجع الكهان؛ لأنه عارض به الحق، وردّ به الحق، فالسجع الذي يُتكلّف أو يُردّ به الحق ويُعترض به على الحق يكون ممقوتًا ومردودًا، نسأل الله العافية.\nس: السجع حال الخطبة؟\nالشيخ: المقصود إذا كان مناسبًا ما فيه تكلف؛ ما فيه شيء، واقع في الأحاديث وواقع في القرآن.","link":"https://binbaz.org.sa/fatwas/23122/ما-السجع-المنهي-عنه-في-الخطب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما المقصود بالسجع المنهي عنه في الخطب.mp3","categories":["شروح الحديث"]},{"id":2973,"question":"قال النووي بعد حديث أبي بكر: ورُوِيَ ظُلمًا كثيرًا وروي كبيرًا؟","title":"هل يجمع كثيرًا وكبيرًا بدعاء \"ظلمت نفسي\"؟","answer":"الجواب: واحدة تكفي، كثيرًا تكفي، جاء بها روايات كثيرة.\nس: ما يُجمع بينها؟\nالشيخ: ما حاجة.","link":"https://binbaz.org.sa/fatwas/23130/هل-يجمع-كثيرا-وكبيرا-بدعاء-ظلمت-نفسي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الجمع بين لفطي كثيرا وكبيرا في دعاء اللّهم إني ظلمت نفسي ظلما كثيرا.mp3","categories":["شروح الحديث"]},{"id":2975,"question":"حديث زيد بن أرقم ما ورد في بعض ألفاظه: ومن عين لا تدمع؟","title":"هل صح في السُّنَّة التعوُّذ مِن \"عين لا تدمع\"؟","answer":"الجواب: بلى، في بعض الروايات ومن عين لا تدمع؛ لأن دمع العين من خشية الله، مثل ما في الحديث الصحيح: سبعة يظلهم الله في ظله يوم لا ظل إلا ظله -وذكر منهم السابع- ورجل ذكر الله خاليًا ففاضت عيناه وحديث آخر: عينان لا تمسّهما النار، عين بكت من خشية الله، وعين سهرت في سبيل الله.","link":"https://binbaz.org.sa/fatwas/23132/هل-صح-في-السنة-التعوذ-من-عين-لا-تدمع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث اللهم إني أعوذ بك من العجز والكسل.. هل ورد في بعض ألفاظه ومن عين لا تدمع.mp3","categories":["شروح الحديث"]},{"id":2976,"question":"قَرَنَ في الحديث العجز والكسل والبخل والهرم؟","title":"لماذا قُرِن العجز والكسل مع البخل والهرم؟","answer":"الجواب: كلها أدواء، العجز ما قد يكون عجزًا نفسيًّا وقد يكون عجزًا له أسباب، وقد يكون عجزًا بسبب الكسل، فهو يستعيذ بربه من هذا وهذا، ومن البخل كذلك، من البخل والكسل كله.","link":"https://binbaz.org.sa/fatwas/23133/لماذا-قرن-العجز-والكسل-مع-البخل-والهرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/قرن العجز والكسل مع البخل والهرم في الحديث.mp3","categories":["شروح الحديث"]},{"id":2977,"question":"العلم الذي لا ينفع هي علوم الدنيا؟","title":"ما هو العلم الذي لا ينفع؟","answer":"الجواب: كل علم لا ينفع داخل فيه، حتى علم الشرع إذا ما نفعه صار حجة عليه، نسأل الله العافية، إذا لم يعمل به صار حُجة عليه.\nس: علوم الدنيا ألا تدخل في العلم الذي لا ينفع؟\nالشيخ: لا، علوم الدنيا قد تنفع، النجار ينفعه علمه، والحداد ينفعه علمه، والسواق ينفعه علمه، لكن بعض الناس عنده علوم شرعية مثل اليهود وعلوم السوء لا تنفعهم، علومهم حجة عليهم يوم القيامة إلى النار، نسأل الله العافية.\nس: المقصود بالمنفعة في الدنيا والآخرة؟\nالشيخ: يَعُمُّ هذا وهذا.","link":"https://binbaz.org.sa/fatwas/23134/ما-هو-العلم-الذي-لا-ينفع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما هو العلم الذي لا ينفع.mp3","categories":["شروح الحديث","العالم والمتعلم"]},{"id":2980,"question":"حديث عائشة اللهم إني أعوذ بك من فتنة النار.. ما هي فتنة النار؟ قال بعض الشراح إن فتنة النار هي سؤال الخزنة؛ لقوله تعالى: تَكَادُ تَمَيَّزُ مِنَ الْغَيْظِ كُلَّمَا أُلْقِيَ فِيهَا فَوْجٌ سَأَلَهُمْ خَزَنَتُهَا أَلَمْ يَأْتِكُمْ نَذِيرٌ [الملك:8]؟","title":"ما معنى حديث \"أعوذ بك من فتنة النار\"؟","answer":"الجواب: الله أعلم، الله أعلم، النار فتنة، فَتَن الشيء: إذا عذبه وزيَّنه ذُوقُوا فِتْنَتَكُمْ [الذاريات:14] يعني عذابكم، الفتنة، تطلق على العذاب، فتنة النار عذاب النار يعني.","link":"https://binbaz.org.sa/fatwas/23137/ما-معنى-حديث-اعوذ-بك-من-فتنة-النار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث عائشة اللهم إني أعوذ بك من فتنة النار.. ما هي فتنة النار.mp3","categories":["شروح الحديث"]},{"id":2985,"question":"معنى وعليك البلاغ؟","title":"معنى حديث \"وأنتَ المُستعانُ وعليكَ البَلاغُ\"","answer":"الجواب: الله هو الذي يُبَلِّغُه، الله هو الذي بيده تبليغه.","link":"https://binbaz.org.sa/fatwas/23142/معنى-حديث-وانت-المستعان-وعليك-البلاغ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث وعليك البلاغ، ما معنى وعليك البلاغ.mp3","categories":["شروح الحديث"]},{"id":2986,"question":"عزائم المغفرة؟","title":"ما معنى عزائم المغفرة؟","answer":"الجواب: يعني: المغفرة التامة.","link":"https://binbaz.org.sa/fatwas/23143/ما-معنى-عزاىم-المغفرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى عزائم المغفرة في الحديث.mp3","categories":["شروح الحديث"]},{"id":2996,"question":"من كان يؤمن بالله واليوم الآخر فليقل خيرا أو ليَصْمُت يقال: المقصود هل هو مثلًا إذا صار في مجلس فيه غِيبة يسكت عنهم وإلا يشاركهم؟","title":"معنى \"فليقل خيرًا أو ليَصْمُت\" في الحديث؟","answer":"الجواب: فليقل خيرًا: يُنْكِر، يُنْكِر إذا سمعهم، ينبّههم يقول: اتقوا الله، دعوا الغيبة، وإذا كان في مجلس فيه نميمة كذلك، وإذا كان فيه خمر نهاهم عنه، وإذا كان فيه زنا نهاهم عنه، وهكذا إذا رأى المنكر أنكره وإلا فليفارق المحل، يبتعد، لا يجلس معهم على منكر.\nس: أو يغيّر الموضوع؟\nالشيخ: لا بدّ من إنكار المنكر مع تغيير الموضوع، إنكار المنكر لا بدّ وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ [التوبة:71]، ويقول سبحانه: كُنْتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ تَأْمُرُونَ بِالْمَعْرُوفِ وَتَنْهَوْنَ عَنِ الْمُنْكَرِ وَتُؤْمِنُونَ بِاللَّهِ [آل عمران:110] قدم الأمر والنهي قبل الإيمان لعِظَم الأمر.\nس: لمّا يكون في المجلس رجال كبار صعب لو قال لهم؟\nالشيخ: الحق أكبر منهم، الحق أكبر، ولهذا لما استحيا عبدالله بن عمر كما تقدم أن يتكلم في النخلة قال أبوه عمر: لئن كنت تكلمت أحب إلي من كذا وكذا، الإنسان ما يَحْقِر نفسه عن الخير، يتكلم بالخير وينكر المنكر ولو كان أصغر القوم.","link":"https://binbaz.org.sa/fatwas/23153/معنى-فليقل-خيرا-او-ليصمت-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بحديث فليقل خيرا أو ليصمت.mp3","categories":["شروح الحديث"]},{"id":2999,"question":"إذا كان فاعل المعروف كافرًا (هل يُكافأ)؟","title":"هل يُكافأ فاعلُ المعروف إذا كان كافرًا؟","answer":"الجواب: ولو كافر، تدعو له بالهداية، إن كان مالًا تعطيه مكافأة مثل ما أعطاك، تكافئه، إنْ كان دلّك على الطريق أو أرشدك إلى شيء ينفعك، تقول: جزاه الله خيرًا، هداه الله، نسأل الله له الهداية.\nس: هداك الله؟\nالشيخ: هداك الله، أسأل الله لك الهداية، أو جزاه الله خيرًا، الخير يكون مِن خير الدنيا ومِن خير الآخرة.\nس: أولًا يكون المكافأة.....؟\nالشيخ: إذا كان ماليًّا يكافئه بالمال، كان النبي ﷺ يقبل الهدية ويكافئ عليها، اللهم صل وسلم عليه.","link":"https://binbaz.org.sa/fatwas/23157/هل-يكافا-فاعل-المعروف-اذا-كان-كافرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من صنع إليكم معروفا فكافئوه، فإذا كان فاعل المعروف كافرا.mp3","categories":["شروح الحديث"]},{"id":3001,"question":"قول مَنْ تَعارّ من الليل وذكر الله ثم دعا يعني الدعاء بعد القنوت...؟","title":"متى يُقال دعاء: «مَنْ تَعارّ من الليل..»؟","answer":"الجواب: يُرجى له، يقول ﷺ: ما مِن عبدٍ يتعارّ من الليل -يعني يستيقظ- فيقول: لا إله إلا الله وحده لا شريك له، له الملك وله الحمد وهو على كل شيء قدير، سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر، ولا حول ولا قوة إلا بالله، ثم يقول: اللهم اغفر لي، أو يدعو؛ فيستجاب له، فإن قام وصلى قُبلت صلاته. هذا من أسباب الإجابة، إذا أتى بهذا الذكر ثم قال: اللهم اغفر لي، أو دعا، اللهم أصلحني، اللهم يسّر لي زوجة صالحة، اللهم ارزقني ذرية طيبة، إلى غير هذا، هذا من أسباب الإجابة، فإذا قام مع هذا توضأ وصلى قُبلت صلاته، هذا في الصحيحين من حديث عبادة، حديث عظيم صحيح.\nس: الدعاء قبل الصلاة وإلا بعد؟\nالشيخ: قبل الصلاة وبعد الصلاة وفي الصلاة، كلها.","link":"https://binbaz.org.sa/fatwas/23159/متى-يقال-دعاء-من-تعار-من-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من تعار من الليل وذكر الله... هل يعني الدعاء.mp3","categories":["شروح الحديث"]},{"id":3002,"question":"قوله الله أكثر؟","title":"معنى \"الله أكثر\" في الحديث","answer":"الجواب: يعني: أكثر إجابة، وأكثر خيرًا منك أيها العبد، أكثر إجابة وأكثر خيرًا.","link":"https://binbaz.org.sa/fatwas/23160/معنى-الله-اكثر-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى الله أكثر.mp3","categories":["شروح الحديث"]},{"id":3010,"question":"(في قصة أبي بكر وأضيافه): قوله: \"غُنْثَرُ\" ما معناه؟","title":"ما معنى \"غُنْثَرُ\" في قصة أبي بكر وأضيافه","answer":"الجواب: كلمة زجر كأنه يقول: يا غادر، أو يا كذا.\nس: مكتوب عندنا \"غبي\"؟\nالشيخ: محتمل، يُراجع كتب اللغة، المقصود أنها زجر له.\nس: فجَدَع؟\nالشيخ: يعني سَبّهُم.","link":"https://binbaz.org.sa/fatwas/23168/ما-معنى-غنثر-في-قصة-ابي-بكر-واضيافه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما معنى غنثر.mp3","categories":["شروح الحديث"]},{"id":3016,"question":"الحديث القدسي: وإنْ تقرَّب إليّ شِبْرا تقرَّبت إليه باعًا... إلى آخر الحديث، يُعتبر مِنْ أحاديث الصفات؟","title":"معنى الصِّفَة في حديث \"تقرَّبت إليه باعًا..\"؟","answer":"الجواب: نعم، يُجرى على ظاهره، على الوجه اللائق بالله، من أحاديث الصفات، على الوجه اللائق بالله.","link":"https://binbaz.org.sa/fatwas/23174/معنى-الصفة-في-حديث-تقربت-اليه-باعا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث وإن تقرب إليّ شبرا تقربت إليه باعا.. هل هذا من أحاديث الصفات.mp3","categories":["شروح الحديث","الأسماء والصفات"]},{"id":3025,"question":"حديث: لا تصاحب إلا مؤمنًا، ولا يأكل طعامَك إلا تقيٌّ؟","title":"ما معنى حديث \"لا تصاحب إلا مؤمنًا\"؟","answer":"الجواب: لا بأس به.\nس: يعني بضمه إلى النصوص الأخرى في نفس الموضوع، كيف يكون العمل بهذا الحديث؟\nالشيخ: يعني لا يتخذهم أصحابًا وهم ليسوا بجيدين، ليكن أصحابه من أهل التقوى والخير، ولكن الشيء العارض كالضيف ونحوه والطعام المُصادف ما هو بداخل في هذا، لكن الإنسان لا يتخذ أصحابًا ليسوا بطيبين. أما كون النبي ﷺ استضافه ناس كثيرون مِن نصارى نجران ومِن وثنية ثقيف ومن غيرهم، الضيف والشيء الذي يُبتلى به الإنسان له حالة أخرى، أو صادف إنسان ضيوفًا يأكل معهم أو عمالًا يأكل معهم؛ ما تلزم منه الصحبة.","link":"https://binbaz.org.sa/fatwas/23184/ما-معنى-حديث-لا-تصاحب-الا-مومنا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/العمل بحديث لا تصاحب إلا مؤمنا، ولا يأكل طعامك إلا تقي.mp3","categories":["شروح الحديث","الحكم على الأحاديث"]},{"id":3031,"question":"قوله في حديث أبي سعيد: إن الأعضاء تُكفّر اللسان.. كيف يُجمع بينه وبين حديث النعمان بن بشير: إن في الجسد مُضْغة..؟","title":"معنى ما جاء في الحديث عن القلب واللسان","answer":"الجواب: ما ينافي هذا وهذا، الأصل القلب، واللسان، والأعضاء تلوم اللسان أيضًا؛ لأن اللسان يجرُّها إلى البلاء أو إلى الخير.","link":"https://binbaz.org.sa/fatwas/23191/معنى-ما-جاء-في-الحديث-عن-القلب-واللسان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الجمع بين حديث إن الأعضاء تكفر اللسان.. وحديث إن في الجسد مضغة..mp3","categories":["شروح الحديث"]},{"id":3033,"question":"حديث أنس (مررت بقوم لهم أظفار من نحاس يَخْمِشُون وجوههم) : العذاب هذا في فترة البرزخ؟","title":"هل الوعيد \"يَخْمِشُون وجوههم\" في البرزخ؟","answer":"الجواب: الظاهر -والله أعلم- أن هذا البرزخ، يعني ما بين موته وبين بعثه ونشوره، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/23193/هل-الوعيد-يخمشون-وجوههم-في-البرزخ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بحديث مررت بقوم لهم أظفار من نحاس يخمشون وجوههم.mp3","categories":["شروح الحديث"]},{"id":3037,"question":"حديث عائشة الذي رواه الدارقطني، لما قالت: أتممت؟","title":"ما صح قول عائشة \"أتممت وقصرت...\"؟","answer":"الجواب: لا لا، الثابت عنها أنها كانت تُتِم وتقول إنه لا يشق عليها، وأما رواية \"أتممت وقصرت وصمت وأفطرت\" فهذا ذكر الشيخ تقي الدين وجماعة أنه لا يصح، وإنما الصحيح عنها أنها أخيرًا بعد موت النبي ﷺ كانت تتم وتقول: \"إنه لا يشق عليّ\"، كما قال الحافظ في البلوغ رحمه الله، والمحفوظ عنها مِن فعلها.","link":"https://binbaz.org.sa/fatwas/23197/ما-صح-قول-عاىشة-اتممت-وقصرت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث خرجت مع النبي في عمرة رمضان فأفطر وصمت، وقصر وأتممت.mp3","categories":["شروح الحديث","الحكم على الأحاديث"]},{"id":3041,"question":"كيف الجمع بين حديث عائشة في البخاري لا تَسُبُّوا الأموات وبين ثناء الصحابة على جنازة؟","title":"ما الضابط في عدم سَبِّ الأموات؟","answer":"الجواب: إذا دعت الحاجة لا بأس، سب الأموات يُنهي عنه إلا أن تدعو الحاجة إلى سَبِّه، إلى بيانه، مثل إنسان مبتدع له كتاب أو له كتب مبتدعة، يقال: احذروا كتب فلان، أو له كلمات أو تُنشر في الصحف أو غيره، إذا كان لإظهار شره مصلحة؛ لا بأس.","link":"https://binbaz.org.sa/fatwas/23201/ما-الضابط-في-عدم-سب-الاموات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الجمع بين حديث لا تسبوا الأموات وبين ثناء الصحابة على جنازة.mp3","categories":["شروح الحديث"]},{"id":3048,"question":"عندما النبي ﷺ عَرّف بالصحابة قال: وأما هذا ما يَضَعُ عصاه... ما معنى ما يضع عصاه؟","title":"معنى \"ما يضع عصاه\" و\"صعلوك\" بالحديث","answer":"الجواب: يقول إنه ضرّاب للنساء، يَطُقّ النساء، يعني أنه سيئ السيرة مع النساء ضرّاب، وبعضهم قال: إنه كثير الأسفار، يُخلّي امرأته في البيت، أسفاره كثيرة، ولكن الأول هو الأظهر: أنه ضراب للنساء.\nس: وكلمة صُعلوك؟\nالشيخ: صُعلوك: فقير ما عنده شيء، يقول دَوّرِي واحد عنده مال ينفق عليك.","link":"https://binbaz.org.sa/fatwas/23208/معنى-ما-يضع-عصاه-وصعلوك-بالحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بحديث معاوية صلعوك لا مال له، وأبو جهم...mp3","categories":["شروح الحديث"]},{"id":3055,"question":"وَجْهُ إيراد شيخ الإسلام محمد بن عبدالوهاب في كتاب التوحيد الحديث الأخير (ألَا أُنبِّئُكم ما العَضْهُ؟)؟","title":"ما صلة حديث \"ألَا أُنبِّئُكم ما العَضْهُ\" بالتوحيد؟","answer":"الجواب: لأنه ذكره في بيان أنواع من السحر، يعني أن العَضْهُ يطلق على السحر، فالنميمة نوع من السحر الذي يسبّب الشر، وإنْ كان ليس بسحر، لكن تسبّب ما يسبّبه السحر من التفريق بين الناس والشحناء.","link":"https://binbaz.org.sa/fatwas/23215/ما-صلة-حديث-الا انبىكم ما العضه-بالتوحيد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/لماذا أورد محمد بن عبدالوهاب في كتاب التوحيد حديث ألا أنبئكم ما العضه..mp3","categories":["شروح الحديث"]},{"id":3059,"question":"حديث لا يدخل الجنة نَمّام هل هو يعني ...؟","title":"معنى الوعيد بحديث \"لا يدخل الجنة نَمّام\"","answer":"الجواب: مِن باب الوعيد، مِن باب الوعيد، مَعْصية.","link":"https://binbaz.org.sa/fatwas/23219/معنى-الوعيد-بحديث-لا-يدخل-الجنة-نمام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث لا يدخل الجنة نمام.mp3","categories":["شروح الحديث"]},{"id":3065,"question":"قوله ﷺ: الناس معادن يخص أنسابهم أم أعمالهم؟","title":"هل \"الناس معادن\" في أنسابهم أم أعمالهم؟","answer":"الجواب: معادن في العمل وفي الأخلاق، وخيارهم في الجاهلية خيارهم في الإسلام إذا فَقُهُوا. معادن: منهم الجبان ومنهم البخيل، ومنهم الجواد والكريم، ومنهم القوي في أمر الله ومنهم الضعيف. فخيارهم في الجاهلية: هذا لأهل الجود والكرم ومساعدة المظلوم ومساعدة المنكوب ومساعدة الفقير، هؤلاء هم خيار الناس في الجاهلية وهم خيار الناس في الإسلام ولو كان عبدًا أسود.","link":"https://binbaz.org.sa/fatwas/23225/هل-الناس-معادن-في-انسابهم-ام-اعمالهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الناس معادن.. في أنسابهم أم أعمالهم.mp3","categories":["شروح الحديث"]},{"id":3066,"question":"الحديث كفى بالمرء كذبًا أن يحدّث بكل ما سَمِع يدخل فيه من يحدّث عن الآخرين يريد أن يتبيّن فقط؟","title":"معنى\"كفى بالمرء كذبًا أن يحدّث بكل ما سَمِع\"","answer":"الجواب: المقصود: يدخل فيه مَنْ يحدّث بكل ما هبّ ودبّ ما يبالي، المؤمن ينتقي، لا يحدث إلا بشيء ينتقيه، ينفع، شيء ينتقيه، يحفظ الحديث الصحيح من كان يؤمن بالله واليوم الآخر فليقل خيرًا أو ليصمت هذا الكلام الجامع.","link":"https://binbaz.org.sa/fatwas/23226/معنىكفى-بالمرء-كذبا-ان-يحدث-بكل-ما-سمع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بحديث كفى بالمرء كذبا أن يحدث بكل ما سمع.mp3","categories":["شروح الحديث"]},{"id":3081,"question":"قوله ﷺ: ثم ليأكلها ولا يَدَعْها للشيطان للوجوب؟","title":"هل الأمر للوجوب في \"ولا يَدَعْها للشيطان\"؟","answer":"الجواب: هذا الأصل في الأوامر، لكن المعروف عند أهل العلم للسُّنية، سُنة، وإلا الأصل في الأوامر الوجوب.","link":"https://binbaz.org.sa/fatwas/23241/هل-الامر-للوجوب-في-ولا-يدعها-للشيطان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ثم ليأكلها ولا يدعها لشيطان هل الأمر للوجوب.mp3","categories":["شروح الحديث"]},{"id":3090,"question":"كيف الجمع بين الحديث نهي الرسول ﷺ عن التنفس في الإناء، والحديث الذي في مسلم عن أنس أن الرسول ﷺ كان يتنفس في الإناء ثلاثًا؟","title":"ما معنى حديث \"كان يتنفس في الإناء ثلاثًا\"؟","answer":"الجواب: يعني عند الشرب، ما هو معناه في وسط الإناء، عند فَصْل الإناء.","link":"https://binbaz.org.sa/fatwas/23250/ما-معنى-حديث-كان-يتنفس-في-الاناء-ثلاثا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الجمع بين حديث النهي عن التفس في الإناء، وحديث أن الرسول كان يتنفس في الإناء ثلاثا.mp3","categories":["شروح الحديث"]},{"id":3117,"question":"بالنسبة لأبي هريرة: سَقَى القوم، ولم يكن آخِرَهم شرابًا؟","title":"هل يجب أن يكون ساقي القوم آخرَهم شُرْبًا؟","answer":"الجواب: لا حرج، لكن الأفضل أن يكون هو الآخِر. س: إذا كان ساقي القوم أكبرهم؟ الشيخ: ولو كان أكبرهم، يطوف عليهم بالسقيا، يكون هو الآخر، سواء شايب أو صغير.","link":"https://binbaz.org.sa/fatwas/23277/هل-يجب-ان-يكون-ساقي-القوم-اخرهم-شربا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث ساقي القوم آخرهم شربًا..mp3","categories":["شروح الحديث"]},{"id":3137,"question":"قوله: أنا رسول الله الذي إذا أصابك ضر فدعوته كشف الله ضرك؟","title":"معنى حديث \"الذي إذا أصابك ضر فدعوته..\"","answer":"الجواب: صحيح كله أَمَّنْ يُجِيبُ الْمُضْطَرَّ إِذَا دَعَاهُ [النمل:62]، وَإِذَا سَأَلَكَ عِبَادِي عَنِّي فَإِنِّي قَرِيبٌ أُجِيبُ دَعْوَةَ الدَّاعِ إِذَا دَعَانِ [البقرة:186] هذا وصفه سبحانه وبحمده، قد يُؤخّر الإجابة لحكمة بالغة.\nس: يعني ما يقصد الرسول ﷺ نفسه؟\nالشيخ: لا، لا.\nس: يقصد الله سبحانه؟\nالشيخ: أنا رسولُ مَنْ؟ رسولُ الله، يعني رسول الربِّ .","link":"https://binbaz.org.sa/fatwas/23299/معنى-حديث-الذي-اذا-اصابك-ضر-فدعوته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بحديث أنا رسول الله الذي إذا أصابك ضر فدعوته كشف الله ضرك.mp3","categories":["شروح الحديث"]},{"id":3144,"question":"يقول النبي ﷺ: وإن أعوج ما في الضِّلع أعلاه بعض العلماء قالوا إن هذا بلسان المرأة، فهل هذا وجيه معناه؟","title":"معنى حديث \"خُلقت مِن ضِلع أعوج\"","answer":"الجواب: الكلام في المرأة؛ خُلقت مِن ضِلع أعوج، لا بد فيها عيب، لا يزال فيها عيب، فالذي ينبغي للمؤمن أن يتغاضى عن بعض الشيء، فإنْ ذَهَبْت تُقِيمُها كَسَرْتَها.\nس: إذن \"أعلاه\" ليس وجيهًا بلسان المرأة؟\nالشيخ: الله أعلم.","link":"https://binbaz.org.sa/fatwas/23306/معنى-حديث-خلقت-من-ضلع-اعوج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بحديث وإن أعوج ما في الضلع أعلاه.mp3","categories":["شروح الحديث"]},{"id":3157,"question":"إن الله يحب أن يُرى أثر نعمته على عبده ويش الضابط، يعني ظهور أثر النعمة على العبد؟","title":"ما الضابط في إظهار أثر النِّعْمة؟","answer":"الجواب: في مأكله ومشربه، ما يتزيَّا بزيّ الفقراء، نوع بُخْل وجُحْد.\nس: تاجر أصبح دخله عشرة.....؟\nالشيخ: المقصود يأكل ويشرب ويلبس زي أمثاله من الأغنياء؛ حتى لا يَجْحَد نعمة الله.","link":"https://binbaz.org.sa/fatwas/23320/ما-الضابط-في-اظهار-اثر-النعمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث إن الله يحب أن يرى أثر نعمته على عبده.. ضابط ظهور أثر النعمة.mp3","categories":["شروح الحديث"]},{"id":3160,"question":"(لابس الحرير في الدنيا لا يلبسه في الآخرة) لأنه يلبس في الجنة، هذا هو السبب؟","title":"معنى وعيد الحرير \"لم يلبسه في الآخرة\"؟","answer":"الجواب: عدم لُبْسُه في الجنة وعيد، لعل السر في ذلك -والله أعلم- أن لبس الحرير والذهب قد يُكسب التَّخَنُّث والتساهل في الرجولة، وهي أليق بالنساء.","link":"https://binbaz.org.sa/fatwas/23323/معنى-وعيد-الحرير-لم-يلبسه-في-الاخرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بحديث فإن من لبسه في الدنيا لم يلبسه في الآخرة.mp3","categories":["شروح الحديث"]},{"id":3169,"question":"(معنى)  إنّ مِنْ أعْظَم الفِرَى...؟","title":"ما معنى \"إنّ مِنْ أعْظَم الفِرَى...\"؟","answer":"الجواب: من أعظم الكذب يعني، أن يُري الإنسان ما لم ير، يقول: رأيت كذا، رأيت كذا، أو يكذب على الله جل وعلا، أو يكذب على رسوله عليه الصلاة والسلام، فالواجب على المؤمن أن يتحرى الصدق في رؤياه وفي كلامه جميعًا.","link":"https://binbaz.org.sa/fatwas/23332/ما-معنى-ان-من-اعظم-الفرى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إن من أعظم الفرى.mp3","categories":["شروح الحديث"]},{"id":3179,"question":"امرأة جاءتها الدورة في رمضان ثم قضت تلك الأيام ثم أتبعتها ستة من شوال؛ فهل في ذلك أجر؟","title":"حكم قضاء ستِّ شوال بعد انتهاء شوال","answer":"الجواب: صامت في شوال؟\nس: لا؛ لأن شوال انتهى ولم تصم ستة الأيام؟\nالشيخ: إذا انتهى شوال ما عاد الصيام، مضى وقتها. لكن تصوم...، تصوم من كل شهر ثلاثة أيام، أو تصوم الإثنين والخميس من كل شهر، كله خير، فضل الله واسع.","link":"https://binbaz.org.sa/fatwas/23342/حكم-قضاء-ست-شوال-بعد-انتهاء-شوال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/امرأة تصوم قضاء رمضان، ثم تتبعها بست شوال.mp3","categories":["شروح الحديث","صيام التطوع"]},{"id":3194,"question":"النبي ﷺ أحسن الله إليك يقول: غُسْلُ الجمعة واجب على كل مُحْتِلم ما الذي يحمله من الوجوب إلى السُّنية؟","title":"هل حكم غُسل الجمعة الوُجوب أم السُّنِّيَّة؟","answer":"الجواب: وأن يستاك وأن يتطيّب، وقوله ﷺ: من توضأ يوم الجمعة فبها ونعمت، ومن اغتسل فالغسل أفضل، وقوله ﷺ: من توضأ يوم الجمعة ثم أتى المسجد فصلى ما قُدر له ثم أنصت حتى يفرغ من الخطبة غفر له ما بينه وبين الجمعة الأخرى رواه مسلم بلفظ من توضأ.","link":"https://binbaz.org.sa/fatwas/23357/هل-حكم-غسل-الجمعة-الوجوب-ام-السنية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث غسل الجمعة واجب على كل محتلم.. ما الذي يحمله من الوجوب إلى السنية.mp3","categories":["شروح الحديث"]},{"id":3197,"question":"بالنسبة للتكفير يكون للصغائر فقط؟","title":"هل تكفير السيئات يكون للصغائر فقط؟","answer":"الجواب: الأصل للصغائر إذا اجتنبت الكبائر بشرط اجتناب الكبائر كما قال الله تعالى: إِنْ تَجْتَنِبُوا كَبَائِرَ مَا تُنْهَوْنَ عَنْهُ نُكَفِّرْ عَنْكُمْ سَيِّئَاتِكُمْ [النساء:31]، قال ﷺ: الصلوات الخمس، والجمعة إلى الجمعة، ورمضان إلى رمضان كفارة لما بينهن إذا اجتنبت الكبائر، إذا كانت هذه الأمور العظمية التي هي من أركان الإسلام إنما تكون كفارة إذا اجتنبت الكبائر؛ فغيرها من باب أولى.\nس: يا شيخ بعضهم، بارك الله فيك، يجلس في المجلس ويَغْتاب ويَنِمّ ثم يقول :قولوا كفارة المجلس حتى...؟\nالشيخ: على كل حال يُرجى إن شاء الله الخير.\nس: خير المجالس يدخل فيه العدد، يعني كثرة الناس؟\nالشيخ: المقصود سعة المكان.","link":"https://binbaz.org.sa/fatwas/23360/هل-تكفير-السيىات-يكون-للصغاىر-فقط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تكفير السيئات للصغائر فقط.mp3","categories":["الرقائق","شروح الحديث"]},{"id":3203,"question":"بالنسبة لليد اليُسرى...: إذا وضع يده اليسرى وراء ظهره، تكون داخل الصلاة أو خارج الصلاة؟","title":"حكم وضع اليد اليُسرى وراء الظَّهر","answer":"الجواب: اتكأ عليها يعني؟\nالطالب: أي نعم.\nالشيخ: ظاهر الحديث المنع، أنه ما ينبغي، جِلْسَة أهل النار.\nس: خارج الصلاة، أحسن الله إليك؟\nالشيخ: داخل الصلاة، خارج الصلاة، الله أعلم.\nس: داخل الصلاة أو خارجها؟\nالشيخ: داخل الصلاة وخارجها، ظاهر الحديث العموم.","link":"https://binbaz.org.sa/fatwas/23366/حكم-وضع-اليد-اليسرى-وراء-الظهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/وضع اليد اليسرى وراء الظهر في المجلس.mp3","categories":["شروح الحديث"]},{"id":3212,"question":"(معنى) إنّ مِنْ أعظم الفِرَى (مَنْ أرَى عينيه ما لم ترَ)؟","title":"معنى \"إن من أعظم الفِرَى..\" في الحديث","answer":"الجواب: من أعظم الكذب يعني أن يري الإنسان ما لم ير، يقول: رأيت كذا، رأيت كذا، أو يكذب على الله جل وعلا، أو يكذب على رسوله عليه الصلاة والسلام؛ فالواجب على المؤمن أن يتحرى الصدق في رؤياه وفي كلامه جميعًا.","link":"https://binbaz.org.sa/fatwas/23375/معنى-ان-من-اعظم-الفرى-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إن من أعظم الفرى.mp3","categories":["شروح الحديث"]},{"id":3222,"question":"قوله : إن هذا الدين مَتِينٌ فأوغلوا فيه برفق ما المقصود به؟","title":"معنى حديث \"إن هذا الدين مَتِين...\"","answer":"الجواب: يعني: عدم التَّكَلُّف وعدم التَّنَطُّع، يؤدي ما شرع الله من دون تنطع، لا يزيد في الدين ما لم يشرعه الله.","link":"https://binbaz.org.sa/fatwas/23385/معنى-حديث-ان-هذا-الدين-متين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بحديث إن هذا الدين متين فأوغلوا فيه برفق.mp3","categories":["شروح الحديث"]},{"id":3226,"question":"أربع من كن فيه كان منافقًا خالصًا؟","title":"معنى النفاق في حديث \"أربع من كن فيه..\"","answer":"الجواب: النفاق العملي، هذا الذي يسمونه النفاق العملي، وقد يَجُرُّه إلى النفاق الاعتقادي، نسأل الله السلامة، قد يجره، لكن ما يصير كافرًا به، إلا إذا جرّه إلى النفاق الاعتقادي أو استحل هذه الخِصال.","link":"https://binbaz.org.sa/fatwas/23389/معنى-النفاق-في-حديث-اربع-من-كن-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بالنفاق في حديث أربع من كن فيه كان منافقا خالصا.mp3","categories":["شروح الحديث"]},{"id":3236,"question":"قوله: فليس منا على ظاهره؟","title":"ما معنى \"فليس مِنّا..\" في الحديث النبوي","answer":"الجواب: من باب الوعيد عند أهل السنة، يُمَرّ كما جاء، من باب الوعيد، ما هو معناه أنه كافر، لا، ليس بكافر، مثل قوله: ليس منا من ضرب الخدود أو شق الجيوب أو دعا بدعوى الجاهلية، ومثل: أنا بريء من الصالقة والحالقة والشاقة.\nس: مَنْ خَبَّبَ زوجة؟\nالشيخ: كذلك حديث مَنْ خَبَّبَ زوجة على زوجها أو مملوكه فليس منا، هذا لا يجوز له تخبيبها، يعني: جَعْلَها تنفر منه، يعني يفعل أشياء يُزَهِّدُها في زوجها، أو يُزَهِّدُ المملوك في سيده حتى يكره سيده وحتى تكره زوجها، يقول: زوجك ما فيه خير، زوجك بخيل، زوجك تراه يروح للحريم، تراه يبي يتزوج، المقصود: يأتي بأشياء تكدّرها على زوجها، هذا من الظلم والعدوان والسعي بالفساد في الأرض، نسأل الله العافية.\nهكذا المملوك: سيدك ما هو طيب، سيدك فيه كذا وفيه كذا، احرص على أن يبيعك أو يعتقك، وما أشبه ذلك؛ حتى يُفْسِد عليه مملوكه.","link":"https://binbaz.org.sa/fatwas/23399/ما-معنى-فليس-منا-في-الحديث-النبوي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بقوله فليس منا.. في الحديث.mp3","categories":["شروح الحديث","مسائل متفرقة في العقيدة"]},{"id":3237,"question":"دياركم دياركم تُكتب آثارُكم حتى في السيارة تُكتب آثار الرِّجْل؟","title":"\"دياركم تُكتب آثارُكم\" هل يعمُّ راكبَ السيارة؟","answer":"الجواب: نعم وأيش المانع؟ الحديث رواه مسلم في الصحيح، ومعناه عام.\nس: ما فيه كُلْفة؟\nالشيخ: ولَوْ ما فيه كُلْفة ،الشاب اللي يمشي ما عليه كُلْفة.","link":"https://binbaz.org.sa/fatwas/23400/دياركم-تكتب-اثاركم-هل-يعم-راكب-السيارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/دياركم دياركم تكتب آثاركم هل تكتب آثار الرجل في السيارة.mp3","categories":["شروح الحديث"]},{"id":3240,"question":"قوله: إني غفرت له وأحبطت عملك؟","title":"معنى حديث \"إني غفرت له وأحبطت عملك\"","answer":"الجواب: هذا من باب الوعيد، لمّا أُعجب بعمله جاء الوعيد في حقه.","link":"https://binbaz.org.sa/fatwas/23404/معنى-حديث-اني-غفرت-له-واحبطت-عملك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بحديث إلا غفرت له وأحبطت عملك..mp3","categories":["شروح الحديث"]},{"id":3242,"question":"كيف الجمعُ بين حديث: إن الله جميل يحب الجمال والحديث الآخر: البذاذة من الإيمان؟","title":"كيف يُجْمَع بين حديث \"يحب الجمال\" والبذاذة؟","answer":"الجواب: إذا فعلها الإنسان بعض الأحيان بنية غَمْط النفس واحتقار النفس؛ حتى لا يتكبر؛ لا بأس يفعله بعض الأحيان.","link":"https://binbaz.org.sa/fatwas/23406/كيف-يجمع-بين-حديث-يحب-الجمال-والبذاذة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الجمع بين حديث إن الله جميل يحب الجمال وحديث البذاذة من الإيمان.mp3","categories":["شروح الحديث"]},{"id":3244,"question":"حديث: ليس منا من لم يَتَغَنَّ بالقرآن؟","title":"معنى حديث \"ليس مِنا مَنْ لم يَتَغَنَّ بالقرآن\"","answer":"الجواب: يعني: يُحَسِّن صوته، يَجْهَر به.\nس: صحيح؟\nالشيخ: صحيح.\nس: الوعيد الذي ورد فيه يدل على وجوب التحسين؟\nالشيخ: هذا ظاهر في الوعيد؛ لأنه لا بد يعتني بالقرآن حتى يخشع قلبه، وحتى ينتفع من يسمعه، يتحرى يتحرى.\nس: معنى التَّغَنِّي؟\nالشيخ: تحسين الصوت، والجهر به إذا دعت الحاجة إلى الجهر.\nس: قول سفيان بن عيينة: يستغني به؟\nالشيخ: لا لا، ما هو بمعنى الاستغناء، يتغنّى به: يجهر به ويحسّن صوته.","link":"https://binbaz.org.sa/fatwas/23408/معنى-حديث-ليس-منا-من-لم-يتغن-بالقران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بحديث ليس منا من لم يتغن بالقرآن.mp3","categories":["شروح الحديث"]},{"id":3245,"question":"حديث عائشة والذي يقرأ القرآن وهو عليه شاق؟","title":"معنى \"الذي يقرأ القرآن وهو عليه شاق\"","answer":"الجواب: له أجران، أيش فيه؟ يعني يتعب، يعني يتعتع فيه ويشق عليه بعض الحرو،ف يجتهد حتى يتعلم، لا يقول أنا لا أعرف، ولا يقرأ.  يقرأ ويتعلم ويصبر ويسأل إخوانه، وهكذا حتى ينجح، له أجران: أجر القراءة وأجر الاجتهاد.","link":"https://binbaz.org.sa/fatwas/23409/معنى-الذي-يقرا-القران-وهو-عليه-شاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى حديث والذي يقرأ القرآن وهو عليه شاق.mp3","categories":["شروح الحديث"]},{"id":3259,"question":"لعنُها الدابة (أي المرأة التي لعنت الدابة) معناها: الدعاء عليها؟","title":"ما معنى وحكم لعن الدابة؟","answer":"الجواب: يعني: الدعاء عليها، لعنُها يعني سَبَّها: اللهم العنها، هي ملعونة، وإذا سَبَّتها بغير ذلك كذلك لا يجوز.","link":"https://binbaz.org.sa/fatwas/23423/ما-معنى-وحكم-لعن-الدابة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى لعن الدابة.mp3","categories":["شروح الحديث","الأخلاق المذمومة"]},{"id":3266,"question":"لعن الله السارق يسرق البيضة المقصود بالبيضة هنا البيضة المعروفة؟","title":"معنى حديث \"لعن الله السارق يسرق البيضة\"","answer":"الجواب: قال العلماء: معناه أنه يسرق الشيء الحقير فيجره إلى الشيء الكبير، يسرق الحبل فتُقطع يده، ويسرق البيضة فتقطع يده، يعني أنه يتجرأ على الشيء الصغير ثم يعتاد ذلك حتى يتجرأ على الشيء الكبير الذي تقطع به يده. وقال بعضهم: إن المراد بهذا البيضة التي يستعملها، بيضة الدرع التي تستعمل في الجهاد تُوضع على الرأس، والحبل حبال السفن، والأصح خلاف ذلك، الأصح أن المراد أنه يتساهل يسرق البيضة ويسرق الشيء القليل ثم تجره هذه العادة إلى وقوعه في الكبير، نسأل الله العافية.\nس: البيضة هي النصاب؟\nالشيخ: نعم بيضة الرأس عظيمة غالية، لكن مقصوده على الصحيح مراده جنس البيضة المعروفة، والحبل المعروف؛ لأن هذا يجره إلى الشيء الكثير، يعني يتساهل حتى يقع فيما تقطع به يده، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/23430/معنى-حديث-لعن-الله-السارق-يسرق-البيضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بالبيضة في حديث لعن الله السارق يسرق البيضة.mp3","categories":["شروح الحديث"]},{"id":3267,"question":"الذي يتعاون مع أهل الرِّبا كمُوَرِّد لهم هل يدخل في اللعن؟","title":"هل يدخل في اللَّعن مَنْ يتعاون مع أهل الربا؟","answer":"الجواب: يدخل في قوله جل وعلا: وَلَا تَعَاوَنُوا عَلَى الْإِثْمِ وَالْعُدْوَانِ [المائدة:2] الله جل وعلا حذّر عباده من التعاون على الإثم والعدوان على الرّبا، وعلى السرقة، وعلى قطع الطريق، وعلى الغش في المعاملات، وعلى كل ما يضر الناس، والذي يعينهم على عمل الرّبا يجلب لهم السلع التي يستعينون بها في الربا يُخشى عليه من هذا، وإن كان ما أكل لكن يُخشى عليه؛ لأن الأثمان التي يأخذها منهم تدخل في أكله.","link":"https://binbaz.org.sa/fatwas/23431/هل-يدخل-في-اللعن-من-يتعاون-مع-اهل-الربا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يدخل في اللعن من يتعاون مع أهل الربا.mp3","categories":["شروح الحديث","الربا والصرف"]},{"id":3275,"question":"مفهوم الحديث الأخير (وليأت إلى الناس الذي يُحبّ أن يؤتي...) أنه أيضًا يَكْرَهُ للناس ما يَكْرَهُ لنفسه؟","title":"هل يجب أن يَكْرَه المسلم للناس ما يَكْرَهُ لنفسه؟","answer":"الجواب: نعم، ويَكْرَهُ لهم من الشر ما يَكْرَهُ لنفسه، لكن بعض الناس قد يكره أشياء ما ينبغي أن تُكره، لكن: مِن الشر، ما يخالف.  بعض الناس عنده نقص في دينه، قد يكره التوحيد، قد يكره الإيمان، قد يكره، المقصود: يكره الشر، إذا كره الشر يكرهه للناس كما يكرهه لنفسه، المؤمن يكره المعاصي كلها ويكرهها لإخوانه.","link":"https://binbaz.org.sa/fatwas/23439/هل-يجب-ان-يكره-المسلم-للناس-ما-يكره-لنفسه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث وليأت إلى الناس الذي يُحبّ أن يؤتي إليه هل مفهومه أنه يكره للناس ما يكره لنفسه.mp3","categories":["شروح الحديث"]},{"id":3278,"question":"يغْفر لِكُلِّ عَبْدٍ (لَا يُشْرِكُ).. غفران الصغائر؟","title":"معنى حديث \"يغفر لِكلِ عَبْد لَا يُشْرِكُ..\"","answer":"الجواب: على ما دارت عليه الآية وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ [النساء:48] إذا كان بالتوبة تُغفر الذنوب كلها لكل عبد لا يشرك بالله شيئًا، هذا فيه وعد بالمغفرة للعصاة، لكن دلت الأحاديث الأخرى والآية على أن إصرارهم على الكبائر من أسباب حرمان المغفرة.\nس: قوله: لا يشرك بالله؟\nالشيخ: عام يعم النوعين.","link":"https://binbaz.org.sa/fatwas/23442/معنى-حديث-يغفر-لكل-عبد-لا-يشرك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بحديث يغفر لكل عبد...mp3","categories":["شروح الحديث"]},{"id":3279,"question":"كلكم يناجي ربه: لو كان في مثلًا مجموعة منهم من يقرأ القرآن ومنهم من يصلي، وكان بينهم واحد مرتفع صوته: هل يقال له: كلكم يناجي ربه؛ اخفض صوتك؟","title":"معنى \"كلكم يناجي ربه..\" في الحديث","answer":"الجواب: نعم يُبَيّن له، يُخْفِض صوته مثل ما بَيَّن النبي ﷺ للذين يصلّون في المسجد قال: كلكم يناجي ربه فلا يؤذ بعضكم بعضًا.","link":"https://binbaz.org.sa/fatwas/23443/معنى-كلكم-يناجي-ربه-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/كلكم يناجي ربه.. فلو كان مجموعة هل يقال لهم كلكم يناجي ربه اخفض صوتك.mp3","categories":["شروح الحديث"]},{"id":3289,"question":"لا يبع بعضكم على بيع بعض؟","title":"معنى حديث \"لا يبع بعضكم على بيع بعض\"","answer":"الجواب: لا يبع،... شُفْتُه باعها إياها بألف ريال، تقول: يا فلان أنا أعطيك إياها بتسعمائة تعال اشتر من عندي، أو أعطيك أحسن منها بألف حتى يهوّن عن صاحبه، هذا بيعٌ على بيعِ أخيه.","link":"https://binbaz.org.sa/fatwas/23454/معنى-حديث-لا-يبع-بعضكم-على-بيع-بعض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بحديث لا يبع بعضكم على بعض.mp3","categories":["شروح الحديث"]},{"id":3290,"question":"الأعمال بالنيات مِن كمال الإيمان أو من صحتها (الأعمال)؟","title":"هل النيّة شرطٌ لصحة العمل أم لكمال الإيمان؟","answer":"الجواب: ما تصح إلا بالنيّة، أعمال العبادة ما تصح إلا بالنيّة: إنما الأعمال بالنيات.","link":"https://binbaz.org.sa/fatwas/23455/هل-النية-شرط-لصحة-العمل-ام-لكمال-الايمان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بحديث إنما الأعمال بالنيات..mp3","categories":["شروح الحديث"]},{"id":3292,"question":"هل يدل (حديث بدء الوحي) على إسلام ورقة؟","title":"هل يدلّ حديث بدء الوحي على إسلام ورقة؟","answer":"الجواب: ظاهره أنه مؤمن، ظاهره الإسلام؛ ولهذا قال: (إن يدركني يومك أنصرك نصرًا مؤزرً) وقال: (هذا الناموس الذي أنزل على موسى) الناموس يعني: وصلة الخير وسبيل الخير.","link":"https://binbaz.org.sa/fatwas/23457/هل-يدل-حديث-بدء-الوحي-على-اسلام-ورقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث بدء الوحي.. هل يدل على إسلام ورقة بن نوفل.mp3","categories":["شروح الحديث"]},{"id":3294,"question":"لماذا قال (وَرَقَة): \"الناموس الذي أنزل على موسى\" ولم يقل: الذي أنزل على عيسى؟","title":"ما سبب قول ورقة: ناموس موسى؟","answer":"الجواب: لأن عيسى تابع، رسالتُه تابعة لرسالة موسى.","link":"https://binbaz.org.sa/fatwas/23459/ما-سبب-قول-ورقة-ناموس-موسى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هذا الناموس الذي نزل الله على موسى.. لماذا لم يقل عيسى.mp3","categories":["شروح الحديث"]},{"id":3296,"question":"صفة مدارسة جبريل للرسول ﷺ  (القرآن) في رمضان؟","title":"ما صفة مدارسة جبريل للنبيﷺ برمضان؟","answer":"الجواب: على ظاهره، يقرأ جبريل ويقرأ النبي ﷺ، يقرأ هذا ويقرأ هذا، حتى يستفيد مما جاء به جبرائيل؛ لأنه يأتي به عن الله جل وعلا.","link":"https://binbaz.org.sa/fatwas/23461/ما-صفة-مدارسة-جبريل-للنبيﷺ-برمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صفة مدارسة جبريل للرسول في رمضان.mp3","categories":["شروح الحديث"]},{"id":3307,"question":"إطعام الطعام عامٌّ للمسلم والكافر جميعًا؟","title":"هل فضل إطعام الطعام عام للمسلم والكافر؟","answer":"الجواب: نعم، إلا الحَرْبِيّ.","link":"https://binbaz.org.sa/fatwas/23473/هل-فضل-اطعام-الطعام-عام-للمسلم-والكافر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث تطعم الطعام.. هل للمسلم والكافر جميعًا.mp3","categories":["شروح الحديث"]},{"id":3313,"question":"ما جاء عند أبي داود من أن الزاني يرتفع الإيمان فوقه؟","title":"معنى ما جاء أن الزاني يرتفع الإيمان فوقه؟","answer":"الجواب: كما جاء في الحديث: لا يزني الزاني حين يزني وهو مؤمن يعني الإيمان الكامل، ولا يسرق السارق حين يسرق وهو مؤمن يعني الإيمان الكامل، ما يَكْفُر، خلافًا للخوارج، ولهذا يُقام عليه الحد الشرعي ويُصلّى عليه.\nس: ما فيه معنى زائد: أنه يرتفع ويكون فوقه كالظلة؟\nالشيخ: المعنى مقارب، المعنى إيضاح أن إيمانه معه؛ أصل الإيمان، ويرتفع عنه كمال الإيمان، فإذا تاب رجع إليه.","link":"https://binbaz.org.sa/fatwas/23479/معنى-ما-جاء-ان-الزاني-يرتفع-الايمان-فوقه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الزاني يرتفع الإيمان فوقه، هل فيه معنى زائد.mp3","categories":["شروح الحديث"]},{"id":3314,"question":"المقصود من الغِنى (في حديث: ليس الغِنى عن كثرة العَرَض): غِنى النفس أو غِنى المال؟","title":"معنى حديث \"ليس الغِنى عن كثرة العَرَض\"","answer":"الجواب: يقول النبي ﷺ: ليس الغِنى عن كثرة العَرَض، ولكن الغنى غنى النفس الغنى غنى القلب، كثرة العرض: قد يكون عنده مال قارون وهو فقير، ولهذا في الحديث الصحيح: إن الله يحب العبد التقي الغني الخفي يعني غني القلب.","link":"https://binbaz.org.sa/fatwas/23480/معنى-حديث-ليس-الغنى-عن-كثرة-العرض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث ليس الغنى... ما المقصود بالغنى.mp3","categories":["شروح الحديث"]},{"id":3318,"question":"هل جاء في لفظ الحديث: ما تقدم من ذنبه وما تأخر؟","title":"معنى \"ما تقدم من ذنبه وما تأخر\" في الحديث","answer":"الجواب: جاء في بعض الروايات \"وما تأخر\".\nس: على ما تحمل؟\nالشيخ: يعني أن الله يوفقه ويسدده.","link":"https://binbaz.org.sa/fatwas/23484/معنى-ما-تقدم-من-ذنبه-وما-تاخر-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/على ماذا يحمل حديث ...ما تقدم من ذنبه وما تأخر.mp3","categories":["شروح الحديث"]},{"id":3319,"question":"بعض أهل العلم يُخَطِّئ من قال بإثبات الملل له تعالى؟","title":"حكم إثبات صفة الملل لله عز وجل","answer":"الجواب: لا هذا غلط، ملل يليق بالله مثل، وَمَكَرُوا وَمَكَرَ اللَّهُ [آل عمران: 54]، يُخَادِعُونَ اللَّهَ وَهُوَ خَادِعُهُمْ [النساء: 142]، اللَّهُ يَسْتَهْزِئُ [البقرة: 15] كلها تليق بالله، إِنَّهُمْ يَكِيدُونَ كَيْدًا  ۝  وَأَكِيدُ كَيْدًا [الطارق: 15 - 16] كلها أوصاف تليق بالله على الوجه الذي يليق به، لا يشبه صفات المخلوقين كسائر الصفات.","link":"https://binbaz.org.sa/fatwas/23485/حكم-اثبات-صفة-الملل-لله-عز-وجل","audio":"undefined","categories":["شروح الحديث","الأسماء والصفات"]},{"id":3322,"question":"حديث أبي سعيد السابق ذكره البخاري في لفظ: إذا أسلم العبد فحَسُن إسلامُه يكفّر الله عنه كل سيئة كان زَلَفَها ذكر الحافظ في الشرح أن الحديث بلفظ: ما من عبد يُسلم فيحسن إسلامُه إلا كتب الله له كل حسنة زَلَفَها ومحا عنه كل خطيئة زَلَفَها ثم قال: وقد ثبت في جميع الروايات ما سقط من رواية البخاري وهو كتابة الحسنات المتقدمة قبل الإسلام.","title":"معنى حديث \"إذا أسلم العبد فحسن إسلامه..\"","answer":"الجواب: في اللفظ الآخر: أسلمت على ما أسلفت من خير إذا أسلم الكافر أعطاه الله حسناته الماضية وكفّر عنه سيئاته الماضية، إلا إذا بقي على سيئة من سيئاته الماضية؛ يؤخذ بالأول والآخر، كما في الرواية الأخرى، فإن أساء في الإسلام أُخذ بالأول والآخِر.\nس: لكن أحسن الله إليك قال في الشرح: فقيل إن المصنف أسقط ما رواه غيره عمدًا؛ لأنه مشكل على القواعد، وقال المازري: الكافر لا يصح منه تقرُّب فلا يثاب على العمل الصالح.\nالشيخ: لا، في الحديث الصحيح: أسلمت على ما أسلفت من خير الروايات يفسر بعضها بعضًا.\nس: لكن التعبير هذا سليم؟\nالشيخ: الله أعلم، المقصود أن العمدة على الأحاديث: أسلمت على ما أسلفت من خير أما البخاري الله أعلم بقصده.","link":"https://binbaz.org.sa/fatwas/23488/معنى-حديث-اذا-اسلم-العبد-فحسن-اسلامه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/شرح حديث إذا أسلم العبد فحسن إسلامه يكفر الله عنه كل سيئة...mp3","categories":["شروح الحديث"]},{"id":3324,"question":"هل يلزم من اتباع الجنازة المشاركة في دفن الجنازة؟","title":"هل يلزم مَنْ اتبع الجنازة المشاركة في دفنها؟","answer":"الجواب: لا، ما هو بلازم، ولو ما شارك، لكن إذا شارك أفضل؛ لأنه قد يكون العدد كبيرًا فما يتيسر له المشاركة.","link":"https://binbaz.org.sa/fatwas/23490/هل-يلزم-من-اتبع-الجنازة-المشاركة-في-دفنها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث من اتبع جنازة مسلم.. فإن تبع أكثر من جنازة.mp3","categories":["شروح الحديث"]},{"id":3336,"question":"ما هي الأغلوطات التي نهى الرسول ﷺ عنها؟","title":"معنى الأغلوطات وهل صح النهى عنها؟","answer":"الجواب: إن صح حديثها معناه: الشيء يشتبه على الناس ولا يُفهم، يُحدّث بأشياء ما يوضحها للناس، يقع فيها مشاكل، تلبّس عليهم الأمور.","link":"https://binbaz.org.sa/fatwas/23502/معنى-الاغلوطات-وهل-صح-النهى-عنها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الأغلوطات التي نهى الرسول عنها.mp3","categories":["شروح الحديث"]},{"id":3339,"question":"يحتج بعض الناس بحديث: لا غيبة لفاسق؟","title":"حكم غيبة الفاسق ومَنْ أظهر المعاصي","answer":"الجواب: لا، الحديث ما أدري بصحته، لكن معروف من أدلة أخرى؛ يقول النبي ﷺ في الرجل الذي دخل عليه: بئس أخو العشيرة، احتجوا به على أن من أظهر المعاصي لا غيبة له.  لكن المؤمن يتحرّى، قد يكون في غيبته وهو مُظْهر فساد يترتب عليه شر، كَوْنُه ينصحه ويوجهه أحسن من كونه يغتابه مهما أمكن. لكن إثم الغيبة إنما يحصل فيمن لم يُعلِن المعاصي، أما من كان يُعلِن المعاصي، ويظهرها بين الناس، يشرب الخمر بين الناس، لا يصلي مع الجماعة، هذا لا غيبة له فيما أظهر، يدخّن في الأسواق عند الناس لا غيبة له، حالق لحيته الناس يرونها لا غيبة له، لكن إذا رأى من المصلحة أن ينصحه سرًّا، وأن لا يتكلم في عرضه؛ لعله يهتدي؛ قد يكون هذا خيرًا، وقد يترتب عليه خير عظيم.","link":"https://binbaz.org.sa/fatwas/23505/حكم-غيبة-الفاسق-ومن-اظهر-المعاصي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم غيبة الفاسق، ومن أظهر المعاصي.mp3","categories":["شروح الحديث","الآداب والأخلاق"]},{"id":3340,"question":"(معنى) أرْبَى الرِّبا أن يستطيل الرجل في عِرْض أخيه؟","title":"ما معنى استطالة الرجل في عِرْض أخيه؟","answer":"الجواب: يعني: يبالغ في الغيبة، نسأل الله العافية.\nس: صحيح هذا؟\nالشيخ: ما أتذكر حاله، لكن في الغالب حاله أن سنده ماشٍ مقارب. وأعظم من هذا نص القرآن ولَا يَغْتَبْ بَعْضُكُمْ بَعْضًا.. [الحجرات:12].","link":"https://binbaz.org.sa/fatwas/23506/ما-معنى-استطالة-الرجل-في-عرض-اخيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أربا الربا أن يستطيل الرجل في عرض أخيه.mp3","categories":["شروح الحديث"]},{"id":3347,"question":"مرور ابن عباس رضي الله عنهما أمام الرسول ﷺ أو أمام الصفوف فقط؟","title":"حكم المرور أمام المصلّين في صلاة الجماعة","answer":"الجواب: في الصف.\nالطالب: ليس أمام الرسول ﷺ؟\n الشيخ: من أمام بعض الصف.\nس: يؤخذ من هذا عدم قطع الصلاة...؟\nالشيخ: هذا مِنْ حُجَّة أن المأموم سُتْرةُ إمامِه سُتْرةٌ له.","link":"https://binbaz.org.sa/fatwas/23513/حكم-المرور-امام-المصلين-في-صلاة-الجماعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث فمررت بين يدي بعض الصف... حجة أن المأموم سترة إمامه سترة له.mp3","categories":["شروح الحديث","سترة المصلي"]},{"id":3352,"question":"ما معنى قول \"يترجم بين ابن عباس وبين الناس\"؟","title":"معنى الأثر: \"يترجم بين ابن عباس والناس\"","answer":"الجواب: يعني: يُبَلّغ الناس، يرفع صوته يبلّغ الناس؛ لأنهم كثير، يأتي إليه وفود ألوف، رضي الله عنهما، ورحمه.","link":"https://binbaz.org.sa/fatwas/23518/معنى-الاثر-يترجم-بين-ابن-عباس-والناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى قول يترجم بين ابن عباس والناس.mp3","categories":["شروح الحديث"]},{"id":3357,"question":"قال رجل: يا رسول الله لا أكاد أدرك الصلاة مما يطوِّل بنا فلان، المعنى؟","title":"معنى \"لا أكاد أدرك الصلاة مما يطوّل فلان\"","answer":"الجواب: يعني أنه يُطَوِّل، وما يكاد يدرك الصلاة معه؛ لأنه يشق عليه الحضور، والمقام معه مما يطوِّل، يعني: يشق علينا حتى أني يشق علي أني أصلي معه.","link":"https://binbaz.org.sa/fatwas/23523/معنى-لا-اكاد-ادرك-الصلاة-مما-يطول-فلان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى حديث يا رسول الله لا أكاد أدرك الصلاة مما يطول بنا فلان.mp3","categories":["شروح الحديث"]},{"id":3361,"question":"في الحديث الأول: فدخلت على حفصة فإذا هي تبكي؟","title":"هل آلى النبي ﷺ من أزواجه؟","answer":"الجواب: لما أشيع أنه ﷺ طلق نساءه، أشاع الناس أنه طلق نساءه فبكت خوفًا من الطلاق، فلما جاء عمر سأل النبي ﷺ قال: ما طلقت نسائي فقال عمر: الله أكبر.\nس: هل كان إيلاء؟\nالشيخ: نعم... هجرهن شهرًا، آلى منهن شهرًا، وليس بطلاق.","link":"https://binbaz.org.sa/fatwas/23527/هل-الى-النبي-ﷺ-من-ازواجه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث فدخلت على حفصة فإذا هي تبكي..mp3","categories":["شروح الحديث"]},{"id":3367,"question":"ما رأيت من ناقصات عقل، ودين: يدل على نقص أجرها بناء عليه، وإلا تكون معذورة؟","title":"هل \"ناقصات عقل ودين\" يعني نقص الأجر؟","answer":"الجواب: لا ما عليها شيء في هذا؛ لأن هذا شيء كتبه الله عليها، إنما هو وصف لها.","link":"https://binbaz.org.sa/fatwas/23534/هل-ناقصات-عقل-ودين-يعني-نقص-الاجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما رأيت من ناقصات عقل، ودين... هل يدل على نقصان الأجر.mp3","categories":["قضايا المرأة","شروح الحديث"]},{"id":3369,"question":"قوله ﷺ: رأيتكن أكثر أهل النار: بعد خروج الموحدين من النار؟","title":"معنى حديث \"رأيتكن أكثر أهل النار\"","answer":"الجواب: عام، ظاهر الحديث العموم.","link":"https://binbaz.org.sa/fatwas/23536/معنى-حديث-رايتكن-اكثر-اهل-النار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/رأيتكن أكثر أهل النار.. بعد خروج الموحدين من النار.mp3","categories":["شروح الحديث"]},{"id":3394,"question":"النصر بالرعب مسيرة شهر هذا خاص بالنبي ﷺ؟","title":"هل \"النَّصر بالرعب\" خاصٌّ بالنبي ﷺ؟","answer":"الجواب: لا، ومن تبعه إلى يوم القيامة.","link":"https://binbaz.org.sa/fatwas/23563/هل-النصر-بالرعب-خاص-بالنبي-ﷺ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/نصرت بالرعب.. هل هو خاص بالنبي فقط.mp3","categories":["شروح الحديث"]},{"id":3405,"question":"لما رجع النبي ﷺ هنا في الرواية قال: فوضع شطرها؟","title":"معنى \"فوضع شطرها \"في حديث الإسراء","answer":"الجواب: الروايات معروفة، يُفسّر بعضها بعضًا، خمسًا خمسًا حتى جعلها خمسة، كما في الرواية الأخرى، وشريك له أوهام في بعض الروايات.\nوالله جل وعلا ألهم موسى أن يقول لنبيه هذا، وقد سبق في علمه أنه يجعلها خمسًا، وجعل موسى يراجع محمدًا في هذا عليه الصلاة والسلام؛ فهذا كله من فضل الله جل وعلا الذي ألهم موسى أن يقول للنبي، والنبي رجع إلى الله بعدما استشار جبرائيل فأشار إليه بالرجوع، وهذا كله من فضل الله جل وعلا، هو الذي ألهم موسى، وألهم محمدًا، وألهم جبرائيل، وتفضل بالعفو حتى جعلها خمسًا .\nس: المراد بالشطر هو النصف؟\nالشيخ: نعم.","link":"https://binbaz.org.sa/fatwas/23577/معنى-فوضع-شطرها-في-حديث-الاسراء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/وضع الصلاة في حديث الإسراء.mp3","categories":["شروح الحديث"]},{"id":3407,"question":"بعض الأصوليين يقول أن رؤية ابن عمر هذه (للنبي ﷺ يقضي حاجته مستقبل الشام مستدبر الكعبة) كانت خاصة من خواص الرسول ﷺ فلا حجة فيها؟","title":"هل يجوز استدبار الكعبة في قضاء الحاجة؟","answer":"الجواب: لا، ما لهذا الكلام سَنَد، فِعْلُه ﷺ حجة، وقوله حجة: لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ [الأحزاب: 21].\nس: إذا تعارض القول مع الفعل؟\nالشيخ: القول مُقَدّم، لكن الفعل يُفَسِّر القول؛ أنه ليس للوجوب: إذا كان في الصحراء وَجَب، وفي البيوت لا، ما يلزم، لكن إذا ترك الاستقبال في البيوت فيكون حسنًا إن شاء الله، مثل ما قال أبو أيوب: ننحرف عنها، ونستغفر الله.","link":"https://binbaz.org.sa/fatwas/23579/هل-يجوز-استدبار-الكعبة-في-قضاء-الحاجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث رأيت النبي يقضي حاجته مستقبل الشام مستدبر الكعبة... خاصة من خواص الرسول؟.mp3","categories":["شروح الحديث","أصول الفقه","رؤيا الهلال"]},{"id":3409,"question":"أحسن الله إليك مثل حديث البطاقة؟","title":"الجمع بين: «من شهد أن لا إله إلا الله» وحديث البطاقة","answer":"الجواب: وهكذا حديث البطاقة، وغيره يعني إذا التزم بحق الشهادتين، أما إذا شهد أن لا إلا الله، وأن محمدًا رسول الله، وترك الصلاة، أو جحد وجوبها كفر، أو جحد الصيام، أو جحد الزكاة، أو جحد حج البيت، أو فعل الزنا، أو فعل الخمر يستحق ما يجب عليه لا بدّ أن يلتزم بحق لا إله إلا الله بحق الشهادتين من أداء فرائض الله، وترك محارم الله.","link":"https://binbaz.org.sa/fatwas/23581/الجمع-بين-من-شهد-ان-لا-اله-الا-الله-وحديث-البطاقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الجمع بين حديث من شهد أن لا إله إلا الله، واستقبل قبلتنا... وحديث البطاقة.mp3","categories":["شروح الحديث"]},{"id":3411,"question":"(قول) \"لو مِتَّ مِتَّ على غير سنة محمد ﷺ\"، ما المقصود من هذا؟","title":"معنى: \"لو مِتَّ مِتَّ على غير سنة محمد\"","answer":"الجواب: على دين الله، على الإسلام.","link":"https://binbaz.org.sa/fatwas/23583/معنى-لو-مت مت-على-غير-سنة-محمد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بقول لو مت مت على غير سنة محمد.mp3","categories":["شروح الحديث"]},{"id":3413,"question":"(معنى) فلا تُخْفِروا الله في ذِمَّته؟","title":"معنى حديث \"فلا تُخْفِروا الله في ذِمَّته..\"","answer":"الجواب: يعني: احفظوا، لا تُخْفِروا ذِمَّته بأن تعتدوا عليه.","link":"https://binbaz.org.sa/fatwas/23585/معنى-حديث-فلا-تخفروا-الله-في-ذمته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى حديث .. فلا تخفروا الله في ذمته.mp3","categories":["شروح الحديث"]},{"id":3414,"question":"المراد (بأن) الحيض يعتزلن المصلى؟","title":"معنى حديث \"ويعتزل الحيض عن مصلاهنّ\"","answer":"الجواب: عن مضايقة الناس.\nس: لا يختلطن يعني؟\nالشيخ: يجلسن على حدة؛ لئلا يؤذين المصليات.","link":"https://binbaz.org.sa/fatwas/23586/معنى-حديث-ويعتزل-الحيض-عن-مصلاهن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بحديث ويعتزل الحيض عن مصلاهنّ...mp3","categories":["شروح الحديث"]},{"id":3440,"question":"قوله: هل عندكم شيء من الوحي إلا ما في كتاب الله؟ \"إلا\" بمعنى \"غير\" هنا؟","title":"معنى حديث \"هل عندكم شيء من الوحي إلا\"","answer":"الجواب: ما في تخصيص، يعني: ما عندنا شيء إلا هذا.\nس: الاستثناء بقوله إلا ما في كتاب الله؟\nالشيخ: ليس تخصيصًا، وإنما سمعه من النبي ﷺ، وحفظه..... العقل، وفكاك الأسير، وألا يقتل مسلم بكافر، ورواه غيره أيضًا من الصحابة.","link":"https://binbaz.org.sa/fatwas/23615/معنى-حديث-هل-عندكم-شيء-من-الوحي-الا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى الاستثناء في حديث هل عندكم شيء من الوحي إلا ما في كتاب الله.mp3","categories":["شروح الحديث"]},{"id":3454,"question":"قول الرسول ﷺ لعنة الله على اليهود، هل يجوز لعن اليهود؟","title":"هل يجوز لعن اليهود والكافرين؟","answer":"الجواب: نعم، العنهم، لعن الله اليهود، ولعن الله النصارى، ولعن الله الكافرين مثل ما لعنهم النبي ﷺ.","link":"https://binbaz.org.sa/fatwas/23630/هل-يجوز-لعن-اليهود-والكافرين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث لعنة الله على اليهود.. هل يجوز لعن اليهود.mp3","categories":["شروح الحديث"]},{"id":3455,"question":"لو أنهم رفقة فهل لهم أن يصلوا جماعة؟","title":"حكم وموضع سُنَّة القدوم من السفر","answer":"الجواب: ما أعلم مانعًا، وإن صلى كل واحد ركعتين فلا بأس، وإن صلوها جماعة فلا بأس، يعني جماعة لعارض لا أعلم حرجًا في ذلك.\nس: إذا كان القدوم بعد العصر مثلًا؟\nالشيخ: الأحوط أن يتحرى غير وقت النهي، يتحرى الضحى، أو الظهر، أو الليل، هذا هو الأحوط؛ لأنه في يده الأمر.\nس: أحسن الله إليك لو كان المسجد مغلقًا، وصلى في البيت يكون أدرك السنة؟\nالشيخ: الله أعلم.\nس: صلى في مصلاه؟\nالشيخ: لا، المسجد، السنة في المسجد.\nس: هل هذا يدل على جواز قضاء الدين في المسجد؟\nالشيخ: لا بأس به.","link":"https://binbaz.org.sa/fatwas/23632/حكم-وموضع-سنة-القدوم-من-السفر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/كان النبي إذا قدم من سفر يبدأ بالمسجد يصلي فيه ركعتين، فإذا كانوا رفقة.mp3","categories":["شروح الحديث","صلاة التطوع"]},{"id":3457,"question":"قوله في مصلاه المراد البقعة التي صلى فيها أم يشمل جميع المسجد؟","title":"معنى \"المصلّى\" في فضل صلاة الملائكة","answer":"الجواب: الظاهر يشمل المسجد كله؛ لأنه مصلى، لكن إذا جلس في محله يكون أحسن، وإذا انتقل إلى محل ثانٍ لأجل يستند؛ لا بأس.","link":"https://binbaz.org.sa/fatwas/23634/معنى-المصلى-في-فضل-صلاة-الملاىكة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث الملائكة تصلي على أحدكم ما دام في مصلاه، ما المقصود بالمصلى.mp3","categories":["شروح الحديث"]},{"id":3462,"question":"قول النبي ﷺ: ويح عمّار حصل مرتين، في حفر الخندق....؟","title":"متى قال النبي ﷺ لعمّار \"ويح عمّار\"؟","answer":"الجواب: هذا مما جاء به الوحي ما أخبر به الله جل وعلا.\nس: لكن جاء في البخاري أيضاً أنه قاله في حفر الخندق؟\nالشيخ: يحتمل أنه الخندق، ويحتمل أنه في مسجد النبي ﷺ؛ لأن هذا في البناء، الخندق ما فيه بناء، حفر، هذا لبنتين لبنتين في بناء مسجد النبي.\nس: ما يُجمع أنه قال هذا مرتين؟\nالشيخ: إنْ صح.","link":"https://binbaz.org.sa/fatwas/23639/متى-قال-النبي-ﷺ-لعمار-ويح-عمار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/متى قال النبي لعمار ويح عمار.mp3","categories":["شروح الحديث"]},{"id":3471,"question":"قول ثُمامة \"تقتل ذا دم\" ........؟","title":"معنى قول ثُمامة: \"تقتل ذا دم\"","answer":"الجواب: يعني: ذا دم عظيم، رجل كبير في قومه.\nس: أليس هو ممن قتل عددًا من الصحابة، بمعنى يستحق القتل؟\nالشيخ: لا، ما بلغني، مقصوده إن تقتل ذا دم، يعني: ذا دم رفيع في قومه.","link":"https://binbaz.org.sa/fatwas/23648/معنى-قول-ثمامة-تقتل-ذا-دم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بحديث تقتل ذا دم.mp3","categories":["شروح الحديث"]},{"id":3472,"question":"كونه (أي: ثُمامة) اغتسل من نفسه قبل أن يسلم يدل على عدم وجوب الغسل؟","title":"هل يجب الاغتسال لمن أراد أن يُسلِم؟","answer":"الجواب: نعم، هذا من أدلة عدم الوجوب؛ لأن الرسول ﷺ ما أمره، هو الذي راح وفعل، ولم يأمره بعدما أسلم قال اغتسل.","link":"https://binbaz.org.sa/fatwas/23649/هل-يجب-الاغتسال-لمن-اراد-ان-يسلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الاستدلال بحديث ثمامة على عدم وجول الاغتسال لمن أسلم.mp3","categories":["شروح الحديث"]},{"id":3479,"question":"الواعظ إذا قام يعظ الناس بعد الصلاة، وخرج بعض المأمومين، هل يدخل في هذا الحديث: فأعرض فأعرض الله عنه...-؟","title":"حكم مَنْ يخرج أثناء الموعظة بعد الصلاة","answer":"الجواب: يُخشى أن يكون ممن أعرض فأعرض الله عنه.  ينبغي إذا قام الواعظ أن يستمع الحاضرون، ويستفيدوا.","link":"https://binbaz.org.sa/fatwas/23656/حكم-من-يخرج-اثناء-الموعظة-بعد-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/خروج بعض المأمومين أثناء الموعظة بعد الصلاة.mp3","categories":["شروح الحديث","صلاة الجماعة"]},{"id":3482,"question":"لما قال عليه الصلاة والسلام: إن سعد بن معاذ قد ضمه القبر، وسئل أهله عن ذلك، وهل بلغهم أن النبي قال في ذلك شيئًا، قالوا: النبي ﷺ قال: كان يقصّر في بعض الطهور من البول، فهل هذا صحيح؟","title":"معنى \"لو سَلِمَ أحدٌ من ضَمّة القبر لسلم سعد\"","answer":"الجواب: لو سَلِمَ أحد من ضَمّة القبر لسَلِم سعد فهي ضمة الحبيب لحبيبه، وهي ضمة لا تضر.\nس: هل كان يقصر في بعض الطهور؟\nالشيخ: الله أعلم، الرسول ﷺ قال: استنزهوا من البول فإن عامة القبر منه أما ما يُحكى عن سعد فيحتاج إلى مراجعة طرق الرواية.\nالطالب: أحسن الله إليك، ذكر البيهقي قال: حدثنا أبو عبد الله الحافظ حدثنا أبو العباس حدثنا أحمد بن عبد الجبار حدثنا يونس عن ابن إسحاق حدثني أمية بن عبد الله أنه سأل بعض أهل سعد: ما بلغكم من قول رسول الله ﷺ في هذا؟ فقالوا: ذكر لنا أن رسول الله ﷺ سئل عن ذلك فقال: كان يقصّر في بعض الطهور من البول.\nالشيخ: ما يُعتمد عليه؛ لأن بعض آل سعد مجهول، لا يعوّل على هذا نعم.","link":"https://binbaz.org.sa/fatwas/23659/معنى-لو-سلم-احد-من-ضمة-القبر-لسلم-سعد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/لو سلم أحد من ضمة القبر لسلم سعد.mp3","categories":["شروح الحديث"]},{"id":3488,"question":"قولهم (أي الكفار للنبي ﷺ): ألا تنظرون إلى هذا المرائي. يكون أنه تجرأ بالصلاة أمامهم، أم يقصدون الرياء المعروف؟","title":"مراد الكفار بقولهم: ألا تنظرون إلى المرائي","answer":"الجواب: هذا مرادهم؛ يعني: يصلي أمامنا ليرائينا.  هذا قليل من كثير من شرهم.","link":"https://binbaz.org.sa/fatwas/23666/مراد-الكفار-بقولهم-الا-تنظرون-الى-المراىي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بألا تنظرون إلى هذا المرائي.mp3","categories":["شروح الحديث"]},{"id":3496,"question":"يُؤخّر الأذان (في حال الإبراد بالظهر)؟","title":"هل يُؤخّر الأذان في حال الإبراد بالظهر؟","answer":"الجواب: لا مانع حتى لو قدّمه لا يعجّل بالإقامة، لكن تأخير الأذان أوْلى مثل ما أمر النبي ﷺ المؤذن في حديث أبي ذر قال: أبرد أبرد؛ لأن الناس إذا سمعوا الأذان جاءوا، ما كلٌّ يعلم أنه سيُبْرِد الإمام، فإذا أبرد بالأذان أرفق في الناس.","link":"https://binbaz.org.sa/fatwas/23674/هل-يوخر-الاذان-في-حال-الابراد-بالظهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث فأبردوا عن الصّلاة...، هل يؤخر الأذان.mp3","categories":["شروح الحديث","الأذان والإقامة"]},{"id":3499,"question":"معنى كأنما وُتِرَ أهلَه ومالَه..؟","title":"معنى \"كأنما وُتِرَ أهلَه ومالَه\" في الحديث","answer":"الجواب: سُلِبَ، سُلِبَ هو. س: الجماعة أو خروج الوقت؟ الشيخ: محتمل هذا وهذا.","link":"https://binbaz.org.sa/fatwas/23677/معنى-كانما-وتر-اهله-وماله-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى كأنما وتر أهله وماله في الحديث.mp3","categories":["شروح الحديث"]},{"id":3516,"question":"الذي يقول إن الدرجة الرفيعة: أن يجلس مع الرحمن على عرش الرحمن، هل له أصل؟","title":"ما \"الدرجة الرفيعة\" المذكورة في الدعاء؟","answer":"الجواب: فيه حديث، لكن في سنده مقال، وفسره النبي ﷺ ببيت في الجنة.","link":"https://binbaz.org.sa/fatwas/23696/ما-الدرجة-الرفيعة-المذكورة-في-الدعاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما هي الدرجة الرفيعة المذكورة في الدعاء.mp3","categories":["شروح الحديث"]},{"id":3522,"question":"بين كل أذانين: العصر والمغرب ما هو بوقت نهي؟","title":"ما معنى حديث \"بين كل أذانين صلاة\"؟","answer":"الجواب: بين كل أذانين يعني الإقامة، هذا هو المقصود: الأذان والإقامة. العصر ما هو بداخل.","link":"https://binbaz.org.sa/fatwas/23703/ما-معنى-حديث-بين-كل-اذانين-صلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بحديث بين كل أذانين صلاة.mp3","categories":["الأذان والإقامة","شروح الحديث"]},{"id":3523,"question":"ابتدار الصحابة للسواري يدل على الصف الأول أين هم؟","title":"معنى ابتدار الصحابة السواري يصلون إليها","answer":"الجواب: يدل على استقبال السترة وقت الصلاة.\nس: ولو كان الصف الأول فاتهم؟\nالشيخ: ظاهر السياق أنهم يبتدرون السواري حتى يصلون إليها السنة،  سنة المغرب، السنة التي بين الأذانين، بين الأذان والإقامة.","link":"https://binbaz.org.sa/fatwas/23704/معنى-ابتدار-الصحابة-السواري-يصلون-اليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بحديث ..قام ناس من أصحاب النبي يبتدرون السواري...mp3","categories":["سترة المصلي","شروح الحديث"]},{"id":3528,"question":"قول النبي ﷺ: ليؤمكم أكبركم؟","title":"معنى حديث \"ليؤمكم أكبركم\"","answer":"الجواب: لأنهم متقاربون، شببة متقاربون في العلم والفضل، فقال: أكبركم، مثل ما قال في الرواية: وكنا شببة متقاربين كلهم مهاجرون وكلهم شببة.","link":"https://binbaz.org.sa/fatwas/23709/معنى-حديث-ليومكم-اكبركم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بحديث ليؤمكم أكبركم.mp3","categories":["شروح الحديث","صلاة الجماعة"]},{"id":3541,"question":"معنى قوله: فقال من كان عنده شيء فليجئ به وبسط نطعًا فجعل الرجل...؟","title":"معنى حديث \"من كان عنده شيء فليجئ به..\"","answer":"الجواب: هذه وليمة، أمر ﷺ الصحابة أن يحضروا ما عندهم من تمر، ومن أقط، ومن سمن؛ فصار حيسًا، وليمة صفية رضي الله عنها.\nس: ولمن يأتون بها؟\nالشيخ: للجميع.","link":"https://binbaz.org.sa/fatwas/23723/معنى-حديث-من-كان-عنده-شيء-فليجى-به","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/معنى حديث من كان عنده شيء فليجئ به وبسط نطعا..mp3","categories":["شروح الحديث"]},{"id":3553,"question":"الصواب في قوله: ألا صلوا في رحالكم، إذا بلغ حي على الصلاة، أو بعد؟","title":"متى تُقال \"صلوا في رحالكم\" في الأذان؟","answer":"الجواب: الظاهر أن فعلها عند \"حي على الصلاة\"، أو بعدها، في الرواية الأخرى أنه أمر بعد الأذان؛ حتى لا يستنكر الناس تغيير الأذان حتى يبقى الأذان على حاله، ثم يقول لهم: صلوا في بيوتكم.","link":"https://binbaz.org.sa/fatwas/23735/متى-تقال-صلوا-في-رحالكم-في-الاذان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الصواب في قوله ألا صلوا في رحالكم.mp3","categories":["الأذان والإقامة","شروح الحديث"]},{"id":3575,"question":"هل معنى هذا قول أبي هريرة  \"لا تسبقني\" والإمام في الصلاة؟","title":"معنى قول أبي هريرة: لا تسبقني بـ\"آمين\"","answer":"الجواب: يقول: لا تعجل، يعني بالإحرام حتى أَصِل، حتى لا يسبقه بـ\"آمين\"؛ لأنه يشتغل بتعديل الصفوف.","link":"https://binbaz.org.sa/fatwas/23757/معنى-قول-ابي-هريرة-لا-تسبقني-بـامين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى قول أبي هريرة لا تفتني بآمين.mp3","categories":["شروح الحديث"]},{"id":3598,"question":"التعوذ بالله من الأربع هذه واجب أم سنة؟","title":"هل التعوذ من أربع في التشهد واجب أم سنة؟","answer":"الجواب: عند الجمهور سنة، ويروى عن طاوس أنه كان يأمر ابنه بالإعادة إذا تركها لأن الرسول ﷺ أمر بها: إذا تشهد أحدكم فليستعذ بالله من أربع فينبغي للمؤمن ألا يدعها وإن كان الجمهور يرونها سنة، لكن ينبغي له ألا يدعها؛ لأن الرسول أمر بها عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/23780/هل-التعوذ-من-اربع-في-التشهد-واجب-ام-سنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث إذا تشهد أحدكم فليستعذ بالله من أربع... التعوذ واجب أم سنة.mp3","categories":["التشهد والتسليم","شروح الحديث"]},{"id":3628,"question":"قوله -عفا الله عنك-: والتي ينامون عنها أفضل؟","title":"ما معنى \"والتي ينامون عنها أفضل\"؟","answer":"الجواب: يعني صلاة آخر الليل أفضل، لكن جمع الناس في أول الليل أيسر عليهم أسهل عليهم.\nس: لكن ما يفهم منها عدم التجميع؟\nالشيخ: معناه أن صلاة آخر الليل لو فعلوها أفضل.","link":"https://binbaz.org.sa/fatwas/23812/ما-معنى-والتي-ينامون-عنها-افضل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى والتي ينامون عنها أفضل.mp3","categories":["شروح الحديث","صلاة التطوع"]},{"id":3634,"question":"جريان الشيطان في دم ابن آدم على الحقيقة؟","title":"ما معنى جريان الشيطان في دم ابن آدم؟","answer":"الجواب: على الحقيقة نعم.","link":"https://binbaz.org.sa/fatwas/23819/ما-معنى-جريان-الشيطان-في-دم-ابن-ادم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى حديث إن الشيطان يجري من ابن آدم مجرى الدم.mp3","categories":["شروح الحديث"]},{"id":3664,"question":"المقصود بقوله عليه الصلاة والسلام اطلب؟","title":"معنى \"اطلب ولو خاتما من حديد\" في الحديث","answer":"الجواب: يعني يروح لأهله، يدوّر عند أهله، وهذا يفيد ما أصاب الناس من الحاجة في عهده ﷺ من أول الإسلام، وأنه أصابهم حاجة شديدة، رجل من المسلمين يعجز عن خاتم من حديد، ليس عليه إلا إزاره، هذا يدل على فاقة عظيمة وشدة؛ ولكن الله فرّج بعد ذلك.","link":"https://binbaz.org.sa/fatwas/23852/معنى-اطلب-ولو-خاتما-من-حديد-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/اطلب ولو خاتما من حديد، ما المقصود بالأمر اطلب.mp3","categories":["شروح الحديث"]},{"id":3678,"question":"معنى قوله -أحسن الله إليك- أتوب إلى الله وأتوب إلى رسوله؟","title":"معنى \"وأتوب إلى رسوله..\" في الحديث","answer":"الجواب: إذا صار الحق إلى المخلوق يُتاب إليه، يعني يعتذر، أعتذر إلى الله من المعصية ومن الرسول ومن حقه، وفي اللفظ الآخر: أتوب إلى الله ولا أتوب إلى محمد، قال: عرفت الحق لأهله.\nس: الواو هنا ما تكون للإشراك؟\nالشيخ: لا، هذا معناه التنصل: أتوب إلى الله من حقه وأتوب إليك من حقك يا رسول الله.","link":"https://binbaz.org.sa/fatwas/23867/معنى-واتوب-الى-رسوله-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى حديث أتوب إلى الله وأتوب إلى رسوله.mp3","categories":["شروح الحديث"]},{"id":3680,"question":"المؤمن القوي خير من المؤمن الضعيف...","title":"معنى أن المؤمن القوي خير من الضعيف","answer":"الجواب: نعم، هكذا قال النبي ﷺ، والمؤمن القوي هو الذي يأمر بالمعروف وينهى عن المنكر، يقوم بأمر الله وينصح لله ولعباده، هذا القوي.","link":"https://binbaz.org.sa/fatwas/23869/معنى-ان-المومن-القوي-خير-من-الضعيف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المؤمن القوي خير من المؤمن الضعيف.mp3","categories":["شروح الحديث"]},{"id":3699,"question":"الفرق بين الهجر والإيلاء؟","title":"ما الفرق بين الهجر والإيلاء؟","answer":"الجواب: قد يؤلي ولا يهجر.  الهجر: ترك الكلام معهن بالكلية أو ترك الجماع معهن، يختلف الهجر. والإيلاء: قد يؤلي وهو يكلمها، ولكن يؤلي من الوطء لا يجامع، قد يبيت عندها وقد يكلمها؛ ولكن لا يجامعها.","link":"https://binbaz.org.sa/fatwas/23889/ما-الفرق-بين-الهجر-والايلاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الفرق بين الهجر والإيلاء.mp3","categories":["شروح الحديث","الإيلاء"]},{"id":3716,"question":"قوله - أحسن الله إليكم - ثوبي زور؟","title":"معنى \"ثوبي زور\" في الحديث","answer":"الجواب: كذب، يعني ثوبي كذب.","link":"https://binbaz.org.sa/fatwas/23907/معنى-ثوبي-زور-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى ثوبي زور في الحديث.mp3","categories":["شروح الحديث"]},{"id":3718,"question":"في بعض النسخ لا شخص..؟","title":"هل صح بالحديث \"لا شخص أغير من الله\"؟","answer":"الجواب: كذلك كلها، لا شخص، ولا أحد، ولا شيء، كلها معناها صحيح، هو شيء عظيم، وهو أحد عظيم، وهو شخص عظيم، لا يشبه الأشخاص ولا الأشياء: لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ الْبَصِيرُ [الشورى:11] .","link":"https://binbaz.org.sa/fatwas/23909/هل-صح-بالحديث-لا-شخص-اغير-من-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/روايات لا شيء أغير من الله.mp3","categories":["شروح الحديث"]},{"id":3723,"question":"قول المصنف: مِنْ غير رِيبة؟","title":"كيف يكون نظر المرأة من غير رِيبة؟","answer":"الجواب: يعني إذا كان لرِيبة: أن تنظر إليه بقصد التلذّذ ويحصل به فتنة.\nس: إذا كانوا جماعة كثيرين يحصل رِيبة؟\nالشيخ: مثل هذا ما فيه رِيبة، نظر المتلاعبين ما فيه رِيبة، هذا مقصوده.","link":"https://binbaz.org.sa/fatwas/23915/كيف-يكون-نظر-المراة-من-غير-ريبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ماذا قصد البخاري بتويبه باب نظر المرأة إلى الحبش ونحوهم من غير ريبة.mp3","categories":["شروح الحديث"]},{"id":3733,"question":"لا تباشر المرأة المرأة، معنى المباشرة هنا؟","title":"معنى \"لا تباشر المرأة المرأة\" في الحديث","answer":"الجواب: يعني تصف بشرتها وتصف صفتها كأنه ينظر إليها، ما هو معناه أنها تلتحم بها أو تجمع معها في ثوب واحد لا، المراد يعني تباشرها بالوصف يعني صفتها كذا وصفتها كذا.\nس: المرأة من المعلوم أنها ذات غيرة فلا تصف النساء ولو هو ذكر النساء غضبت؟\nالشيخ: هذا فيه فساد على الجميع قد يضرها ويضر زوجه، أيش قال الشارح على لا تباشر؟\nالطالب: قَوْلُهُ لَا تُبَاشِرِ الْمَرْأَةُ الْمَرْأَةَ زَادَ النَّسَائِيُّ فِي رِوَايَتِهِ: فِي الثَّوْبِ الْوَاحِدِ، قَوْلُهُ: فَتَنْعَتُهَا لِزَوْجِهَا كَأَنَّهُ يَنْظُرُ إِلَيْهَا قَالَ الْقَابِسِيُّ: هَذَا أَصْلٌ لِمَالِكٍ فِي سَدِّ الذَّرَائِعِ فَإِنَّ الْحِكْمَةَ فِي هَذَا النَّهْيِ خَشْيَةُ أَنْ يُعْجِبَ الزَّوْجَ الْوَصْفُ الْمَذْكُورُ فَيُفْضِي ذَلِكَ إِلَى تَطْلِيقِ الْوَاصِفَةِ أَوْ الِافْتِتَانِ بِالْمَوْصُوفَةِ، وَوَقَعَ فِي رِوَايَةِ النَّسَائِيِّ مِنْ طَرِيقِ مَسْرُوق عَن ابن مَسْعُودٍ بِلَفْظِ: لَا تُبَاشِرُ الْمَرْأَةُ الْمَرْأَةَ وَلَا الرَّجُلُ الرَّجُلَ وَهَذِهِ الزِّيَادَةُ ثَبَتَتْ فِي حَدِيثِ ابن عَبَّاسٍ عِنْدَهُ وَعِنْدَ مُسْلِمٌ وَأَصْحَابُ السُّنَنِ مِنْ حَدِيثِ أَبِي سَعِيدٍ بِأَبْسَطَ مِنْ هَذَا وَلَفْظُهُ.","link":"https://binbaz.org.sa/fatwas/23925/معنى-لا-تباشر-المراة-المراة-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى المباشرة في حديث لا تباشر المرأة المرأة.mp3","categories":["شروح الحديث"]},{"id":3739,"question":"معنى قوله ليسوا بأوليائي؟","title":"معنى قوله \"ليسوا بأوليائي\" في الحديث","answer":"الجواب: ليسوا بأحبابي ولا أنصاري حقيقة، الولي هو المحب الناصح، الولي المحب والناصح، يقال له ولي، فالمؤمنون بعضهم أحباء بعض وأنصار بعض.","link":"https://binbaz.org.sa/fatwas/23931/معنى-قوله-ليسوا-باولياىي-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى قوله ليسوا بأوليائي في الحديث.mp3","categories":["شروح الحديث"]},{"id":3740,"question":"... يكون عامًّا؟","title":"معنى \"من ابتلي بشيء من البنات\" في الحديث","answer":"الجواب: يكون على ظاهره؛ لأن كونه يرزق بنات هذا ابتلاء وامتحان؛ لأن من عادة الناس الرغبة في الذكور، فإذا ابتُلي بهن فهو من باب الاختبار هل يشكر الله على هذه النعمة وهل يحسن إليهن؟ فكم من بنت أصلح من ذكر وأنفع. فمن ابتُلي بهن فأحسن إليهن وشكر الله على ذلك؛ كان هذا من أسباب دخوله الجنة ونجاته من النار. ومن كفر النعمة وساءت أخلاقه معهن ورأى أنه منكوس الحظ أو مظلوم أو كذا فساءت حاله -نعوذ بالله- وصار من أشباه من قال الله فيهم وَإِذَا بُشِّرَ أَحَدُهُمْ بِالْأُنْثَى ظَلَّ وَجْهُهُ مُسْوَدًّا وَهُوَ كَظِيمٌ  ۝  يَتَوَارَى مِنَ الْقَوْمِ مِنْ سُوءِ مَا بُشِّرَ بِهِ أَيُمْسِكُهُ عَلَى هُونٍ أَمْ يَدُسُّهُ فِي التُّرَابِ أَلَا سَاءَ مَا يَحْكُمُونَ [النحل:59]، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/23932/معنى-من-ابتلي-بشيء-من-البنات-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الابتلاء في حديث من ابتلي بشيء من هذه البنات...mp3","categories":["شروح الحديث"]},{"id":3744,"question":"الحديث في النظر والباب في الاستئذان؟","title":"ما سبب دخول غض النظر في باب الاستئذان؟","answer":"الجواب: لأجل هذا، المقصود من الاستئذان خوف النظر؛ لأن الإنسان إذا لم يستأذن اطلع على عورات الناس ونظر إلى عورات الناس.","link":"https://binbaz.org.sa/fatwas/23936/ما-سبب-دخول-غض-النظر-في-باب-الاستىذان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/وجه دخول أحاديث غض النظر في باب الاستئذان.mp3","categories":["شروح الحديث"]},{"id":3764,"question":"\"هو كما قال\" يعني؟","title":"معنى \"هو كما قال\" فيمن حلف بغير الإسلام","answer":"الجواب: هذا من باب الوعيد، يعني هو كما قال يهودي أو نصراني، نسأل الله العافية، هذا معناه الزجر والتحذير، وأن عليه التوبة إلى الله من ذلك.","link":"https://binbaz.org.sa/fatwas/23957/معنى-هو-كما-قال-فيمن-حلف-بغير-الاسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى هو كما قال في حديث من حلف بغير ملة الإسلام فهو كما قال.mp3","categories":["شروح الحديث"]},{"id":3768,"question":"يُستثنى من كون آخر الكلام: لا إله إلا الله (الذكر عند النوم آخر ما يقول: اللهم أسلمت نفسي... الحديث)؟","title":"معنى \"من كان آخر كلامه لا إله إلا الله..\"","answer":"الجواب: هذا عند الموت، هذا جاء في حديث عند الموت، هذا خاص وذاك عام، هذاك يستحب يكثر من ذكر الله في المرض ولاسيما عند أمارات الموت حتى يكون آخر كلامه لا إله إلا الله.  وهذا عند النوم يكون آخر ما يقول: اللهم أسلمت...","link":"https://binbaz.org.sa/fatwas/23963/معنى-من-كان-اخر-كلامه-لا-اله-الا-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الجمع بين حديث من كان آخر كلامه لا إله إلا الله دخل الجنة، وحديث إذا أردت مضجعك.mp3","categories":["شروح الحديث"]},{"id":3769,"question":"الجمع بين حديث صلاة الليل مثنى مثنى وحديث: \"ما زاد على إحدى عشرة ركعة لا في رمضان ولا في غيره\"؟","title":"حكم زيادة صلاة الليل على إحدى عشرة ركعة","answer":"الجواب: هذا كلام عائشة يعني حسب اجتهادها... من كلام عائشة رضي الله عنها، ومن الصلوات أنه صلى ثلاث عشرة... قد تكون نسيت.","link":"https://binbaz.org.sa/fatwas/23964/حكم-زيادة-صلاة-الليل-على-احدى-عشرة-ركعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الجمع بين حديث صلاة الليل مثنى مثنى وحديث ما زاد على إحدى عشرة ركعة.mp3","categories":["شروح الحديث"]},{"id":3770,"question":"يجمعهما، يجمع الثلاث مرة ثم ينفث، أو كل سورة؟","title":"ما يُستحب عند النوم وكيفية النفث بالمعوذات","answer":"الجواب: كل واحدة لحالها يقرأ الثلاث ويمسح، ثم يقرأ الثلاث ويمسح، ثم يقرأ الثلاث ويمسح، كل واحدة لحالها، ثلاث مرات، يكررها ثلاث مرات.\nس: وإن قرأ كل سورة ثلاث مرات؟\nالشيخ: لكن كونه يفعل مثل ما فعل النبي يكون أفضل، كونه يقرأ قل هو الله أحد والمعوذتين ويمسح، ثم يعيد قراءتها؛ هذا هو الأكمل، ثلاث مرات.\nس: الأحسن أن يختم بـ قل يا أيها الكافرون.. أو: رب قني عذابك؟\nالشيخ: هذا عند النوم يختم بقوله: اللهم أسلمت نفسي إليك، هذه الخاتمة، اللهم أسلمت نفسي إليك إلى آخره، والأمر في هذا واسع، والحمد لله.\nس: ظاهر الحديث الآن أنه يقرأ السور الثلاث ثم يمسح..؟\nالشيخ: روايات عائشة كثيرة متعددة، لكن صريحة بأنه يفعلها ثلاث مرات، يجمع السور ثم يعيدها، ثلاث مرات يمسح بعدما يقرأ الثلاث.\nس: والمسبحات؟\nالشيخ: المسبحات: سورة الحديد، وسورة الجمعة، وسورة الصف، وسورة التغابن، هذه المسبحات. \nلكن الروايات التي فيها قراءة تحتاج إلى عناية بأسانيدها.\nس: الحديث الثاني ينفض فراشه بداخلة إزاره..؟\nالشيخ: هذا أفضل، من باب التحرز، الله جعل هذا من باب الوقاية، ينفض بداخلة إزاره من باب الوقاية.\nس: يعني مستحب؟\nالشيخ: مستحب، ولا شك.\nس: وإذا نفضه بغير داخلة إزاره؟\nالشيخ: كفى ذلك، المقصود حاصل مثل فوطة مثل غيرها.","link":"https://binbaz.org.sa/fatwas/23965/ما-يستحب-عند-النوم-وكيفية-النفث-بالمعوذات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/شرح حديث كان إذا أخذ مضجعه نفث في يديه وقرأ بالمعوذات ومسح بهما جسده.mp3","categories":["شروح الحديث"]},{"id":3772,"question":"غسل الفَرْج بعد الجماع للنزاهة أو للنجاسة؟","title":"هل يجب غسل الفَرْج بعد الجماع؟","answer":"الجواب: للاستنجاء لأجل الخارج، خروج المني بعد الجماع.\nس: ما أنزل؟\nالشيخ: ولو ما أنزل؛ لأن إدخال الفرج في الفرج لا بدّ أن يناله شيء من رطوبة البول، وغيره.","link":"https://binbaz.org.sa/fatwas/23968/هل-يجب-غسل-الفرج-بعد-الجماع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث إذا أراد أن ينام وهو جنب غسل فرجه، غسل الفرج للنزاهة أو للنجاسة.mp3","categories":["شروح الحديث","النجاسات وإزالتها"]},{"id":3775,"question":"من قال الماء من الماء هو مَنِى المرأة، ومَنِي الرجل؟","title":"ما معنى \"الماء من الماء\" في الحديث؟","answer":"الجواب: لا، الماء من الماء من المني، ماء الغسل من ماء المني، هذا المراد.","link":"https://binbaz.org.sa/fatwas/23971/ما-معنى-الماء-من-الماء-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى الماء من الماء.mp3","categories":["شروح الحديث"]},{"id":3782,"question":"ينفث في يده؟","title":"كيفية الدعاء المأثور لمن آلمه شيءٌ من جسده","answer":"الجواب: من غير نفثٍ، يضع يده على محلِّ [الألم] ويقول: \"بسم الله، بسم الله، بسم الله، أعوذ بعزة الله وقُدرته من شرِّ ما أجد وأُحاذر\" رواه مسلم في \"الصحيح\"، ورواه أحمد أيضًا بإسنادٍ جيدٍ.\nس: جاء \"وقدرته\" يا شيخ؟\nج: جاء بالله وقُدرته، وجاء بعزة الله وقُدرته، كلها نعم.\nس: هل الدعاء: ثلاث مرات بسم الله، ثم الدعاء سبع مرات؟\nج: إذا آلمه شيء من جسده، هكذا جاء الحديث.\nس: سلمك الله، إذا شخص آخر مريض أدعو له بهذا الدعاء أم القصد لنفسه؟\nج: ما له مانع، إذا وضعت يدك [على] الألم وقلتَها فلا مانع، فضل الله واسع، والمسلم أخو المسلم.","link":"https://binbaz.org.sa/fatwas/23979/كيفية-الدعاء-الماثور-لمن-المه-شيء-من-جسده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/شرح حديث إذا تألم شيءٌ من جسد أحدكم فليضع يده عليه...mp3","categories":["شروح الحديث"]},{"id":3783,"question":"في واقعنا الآن أكثر المساجد مُغلقة، فهل يُصلي في بيته؟","title":"ما السُّنة في الركعتين للقادم من السفر؟","answer":"الجواب: الظاهر حسن إن شاء الله، إذا صلَّى في بيته حسن، ما لا يُدرك كله لا يُترك جلُّه.\nس: ما تكون من ذوات الأسباب؟\nج: ما هو الظاهر.\nس: قوله \"الضُّحى\" قيد؟\nج: ما هو بقيدٍ، لو قدم الظهر أو في الليل كله واحد.\nس: ما تكون من ذوات الأسباب؟\nج: ما هو بظاهر، يعني: يستطيع أن يُؤخِّر القدوم، أو يُؤجّل القدوم، يستطيع [أن] يُؤخِّر وقت العصر، يُؤخره للمغرب، والفجر يُؤخره حتى تطلع الشمس.\nس: يعني قبل الدخول في البيت، هاتان الركعتان قبل أن يدخل بيته؟\nج: نعم، هكذا كان النبيُّ يقصد المسجد يُصلي ثم يجلس للناس عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/23980/ما-السنة-في-الركعتين-للقادم-من-السفر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/كان النبي إذا قدم من سفر ضحى دخل المسجد فصلى ركعتين، وقال ادخل، فصلِّ ركعتين.mp3","categories":["شروح الحديث","صلاة التطوع"]},{"id":3784,"question":"ما ثبت أنَّ النبي فعله من باب العادات يُعتبر سنةً أو عادةً؟ يعني: \"ما أكل على خوانٍ قط\" سنة ألا يأكل الإنسانُ على خوانٍ؟","title":"ما معنى \"خوان\"؟ وهل يجوز الأكل عليه؟","answer":"الجواب: هو جاء في بعض الروايات ما يدل على أنه أكل على خوانٍ في بعض الأحيان.  وهذه الأمور هي أشبه بالعادات، مثل: الملابس، والمآكل، والأواني، وأشباه ذلك، إلا الشيء الذي ثبت النَّهي عنه، مثل: الذهب والفضة، وإلا فالأصل أنَّ هذه من الأمور العادية التي يتفاوت الناسُ فيها ويختلفون، لا يُنكر فيها شيء.\nس: الخوان هو السُّفرة؟\nج: الخوان: شيء مُرتفع له قوائم، والسفرة أعم: الشيء الذي على قوائم، والشيء المبسوط في الأرض، مثل: الأنطاع يُقال لها: سفرة، والسفرة التي على قوائم كذلك مثل: الخوان.","link":"https://binbaz.org.sa/fatwas/23981/ما-معنى-خوان-وهل-يجوز-الاكل-عليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما أكل على خوانٍ قط هل من السنة ألا يأكل الإنسانُ على خوانٍ.mp3","categories":["شروح الحديث","الآداب والأخلاق"]},{"id":3785,"question":"وصف الكامل لبعض الرجال من حديث: كَمُلَ من الرجال كثير؟","title":"معنى \"كَمُلَ من الرجال كثير\" في الحديث","answer":"الجواب: يعني: الذي يليق ببني آدم، كمال بني آدم من الحلم والتقوى والاستقامة، ابن آدم لا بدّ فيه من نقصٍ، لكن الكمال نسبي في بني آدم، أما الكمال الحقيقي فلله وحده .","link":"https://binbaz.org.sa/fatwas/23983/معنى-كمل-من-الرجال-كثير-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث كمل من الرجال كثير..، وصف الكامل لبعض الرجال.mp3","categories":["شروح الحديث"]},{"id":3792,"question":"خاصٌّ بتمر المدينة يا شيخ؟","title":"هل التصبُّح بسبع تمرات خاص بتمر المدينة؟","answer":"الجواب: هذا ظاهر الحديث، ويُرجى في أنواع التمر كذلك؛ لأنَّ في بعض الروايات: من تمر، في بعض الروايات: مَن تصبَّح سبع تمرات من تمرٍ، فيعمّ التمر كله؛ لأنَّ رواية من عجوة المدينة، و مما بين لابتيها هذا يدل على الخصوصية، وأن هذا أولى من غيرها، وأقرب من غيرها.","link":"https://binbaz.org.sa/fatwas/23991/هل-التصبح-بسبع-تمرات-خاص-بتمر-المدينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث من تصبّح كلّ يوم سبع مرات عجوة... هل هو خاص بتمر المدينة.mp3","categories":["شروح الحديث"]},{"id":3793,"question":"معنى التَّعبير بـ\"زعم\"؟","title":"معنى \"زعم\" فيما يرويه الصحابي","answer":"الجواب: يعني: قال، زعم تأتي بمعنى قال، مثل.....: زعم رسولك. يعني: قال رسولك.  وتأتي بمعنى الكناية عن الكذب: أَلَمْ تَرَ إِلَى الَّذِينَ يَزْعُمُونَ أَنَّهُمْ آمَنُوا... [النساء:60].","link":"https://binbaz.org.sa/fatwas/23992/معنى-زعم-فيما-يرويه-الصحابي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى زعم في حديث أنّ جابر بن عبدالله زعم عن النّبيّ قال من أكل ثوما أو بصلًا..mp3","categories":["شروح الحديث"]},{"id":3794,"question":"للكراهة يا شيخ أو للتحريم؟","title":"حكم حضور من أكل الثوم والكراث للمسجد","answer":"الجواب: هذا ما ينبغي أن يَحْضُر، ظاهر النهي التحريم، لا يجوز له أن يحضر وفيه رائحة الثوم والكراث، أما أكل الثوم والكراث فمُباح، إذا دعت الحاجةُ إليه يأكل، لكن لا يحضر الجماعة.\nس: هل يكون حرامًا؟\nج: لا، ما هو بحرام، لكن لا يجوز له حضور الجماعة حتى يذهب الريح.\nس: لأيش ما يحضر الجماعة؟\nج: لأجل رائحته الكريهة.\nس: قول عمر : \"مَن أرادهما فليُمتهما طبخًا\"؟\nج: يعني: إذا احتاج إليهما يطبخهما.\nس: النار تُزيل الرائحة؟\nج: تُخفف الرائحة، أما البصل تزول الرائحة، والثوم قد يبقى بعض الشيء، لكن إذا اجتهد في طبخه قد يزول، أو يتعاطى شيئًا من الأدوية التي تُزيل الرائحة.","link":"https://binbaz.org.sa/fatwas/23993/حكم-حضور-من-اكل-الثوم-والكراث-للمسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/النهي لمن أكل الثوم والكراث للكراهة أو للتحريم أن يحضر المسجد.mp3","categories":["شروح الحديث","صلاة الجماعة"]},{"id":3798,"question":"معنى مودع؟","title":"معنى \"غير مكفيّ ولا مودّع..\" في الحديث","answer":"الجواب: متروك يعني.\nس: معنى غير مكفي.\nالشيخ: لا نستطيع مكافأته سبحانه؛ فله الفضل دائماً والمنة.","link":"https://binbaz.org.sa/fatwas/23997/معنى-غير-مكفي-ولا-مودع-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى مودع وغير مكفي في حديث الحمد لله كثيرا طيّبا مباركا فيه غير مكفيّ ولا مودّع..mp3","categories":["شروح الحديث"]},{"id":3800,"question":"في الحديث مثل: الفقير الصابر كالطاعم الشاكر، والفقير الصابر كالصائم الصابر؟","title":"هل \"الطاعم الشاكر كالصائم الصابر\" حديث؟","answer":"الجواب: الحديث: الطاعم الشاكر كالصائم الصابر هذا لفظ المؤلف، هو جاء له طرق، طرق بعضها جيد بعضها صحيح.\nس: لا يستويان في المشقة؟\nالشيخ: قد لا يستويان، لكن موانع المعاصي في حق الفقير أكثر، وتوفرها في حق الطاعم أكثر؛ فإن الذي ملك نفسه عند النعمة وشَكر له مزية عظيمة، من يملك نفسه عند القدرة إلا القليل؟","link":"https://binbaz.org.sa/fatwas/24000/هل-الطاعم-الشاكر-كالصاىم-الصابر-حديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث الطاعم الشاكر كالصائم الصابر.mp3","categories":["شروح الحديث"]},{"id":3801,"question":"البداءة بالطعام خاص بالعَشاء؟","title":"هل تقديم الطعام على الصلاة خاص بالعِشاء؟","answer":"الجواب: إذا قُدِّم، عام في العشاء، وغير العشاء، ولهذا في حديث عائشة: لا صلاة بحضرة الطعام، ولا وهو يدافعه الأخبثان حتى الغداء لو قدم عند أذان العصر وأشباه ذلك أو عند أذان الظهر.\nس: يا شيخ يقال أن هذا في زمن الجوع وليس في زماننا هذا؟\nالشيخ: لا، غلط الذي قال هذا قاله من كيسه، لكن ما ينبغي اعتياد هذا وأن يُجعل عذرًا للناس لا، هذا إذا صادف، أما كونه يعلمهم يقول إذا أذن قدموه؛ هذا معناه ما يريد يصلي مع الجماعة، إنما هذا إذا صادف قُدّم العشاء للضيوف، قُدّم له وما طلبه؛ فليبدأ به حتى لا يتعلق به قلبه؛ حتى يأتي الصلاة وهو خاشع حاضر القلب مطمئن، لا يكون عادة، يجعله عادة عند الصلاة.\nسؤال عن التأخير في تقديم الطعام وفرش السفر؟\nالشيخ: المقصود إذا قُدّم يأكلون، وأما إذا ما قُدّم يُؤجل حتى يصلون.","link":"https://binbaz.org.sa/fatwas/24001/هل-تقديم-الطعام-على-الصلاة-خاص-بالعشاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تقديم العَشاء على العِشاء.mp3","categories":["شروح الحديث"]},{"id":3821,"question":"ما المراد بالعَتُود؟","title":"معنى \"العَتُود\" في حديث عقبة بن عامر","answer":"الجواب: الجذع، كما في الرواية الأخرى، يعني: قوي، قد اشتدَّ.","link":"https://binbaz.org.sa/fatwas/24022/معنى-العتود-في-حديث-عقبة-بن-عامر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث عقبة بن عامر أن النبي أعطاه غنما يقسمها على صحابته ضحايا، فبقي عتود، المراد.mp3","categories":["شروح الحديث"]},{"id":3823,"question":"حديث... يكون لخمسين امرأة قيم، المقصود بالقيِّم؟","title":"معنى \"يكون لخمسين امرأة قَيِّم\" في الحديث","answer":"الجواب: يعني يقوم عليهن، على شؤونهن: بالنفقة والملاحظة ونحو ذلك، بسبب قلَّة الرجال.  وهذا قد يكون لأسبابٍ؛ منها:  الحروب والفتن الكثيرة التي تأكل الرجالَ ويبقى النساء.  ومنها أنه قد يقدر الله أن النساء يكثر حملهنّ بالنساء، ويقل حملهنَّ بالرجال، ويكون غالب الذرية من النساء، حتى يكثر النساء، ويقل الرجال، وربك على كل شيء قدير.  وقد يكون بأسباب الوباء، قد يكون وباء في آخر الزمان فيكون موت الرجال أكثر.\nالحاصل: أنَّ ما أخبر به ﷺ واقعٌ لا محالةَ، سواء كان كثرة النساء من كثرة الحروب، أو الأوبئة، أو من أجل قلة حملهن بالرجال، وأن النساء يقدّر الله عز وجل أن يكون الحمل أقلّ من جهة الرجال.  وهذا الآن له وجود في كثيرٍ من الأسر، نعرف من هذا الشيء الكثير، تجد كثيرًا من الأسر عندهم بنات كثيرات، والأولاد قليل، إما معدومون، وإلا واحد، وإلا اثنان، والنساء كثير، تجد: عنده رجل واحد، وعنده سبع بنات، عشر بنات، فالآن موجود في كثير من المملكة هذه، أما الدول الأخرى والممالك الأخرى فلا نعلمها، ولعله موجود فيها أكثر، فالرسول ﷺ لا ينطق عن الهوى  إنْ هُوَ إلَّا وَحْيٌ يُوحَى، وأما بعد هذا مما يكون في آخر الزمان بعدنا فالله أعلم.","link":"https://binbaz.org.sa/fatwas/24024/معنى-يكون-لخمسين-امراة-قيم-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بالقيم في حديث ..حتّى يكون لخمسين امرأة قيمهنّ رجل واحد.mp3","categories":["شروح الحديث"]},{"id":3824,"question":"ما أسكر كثيره فقليله حرام، قرأتُ بالأمس بحثًا لأحدهم يقول: قليل ما أسكر حرام هذا إذا كان مائعًا، أما إذا كان جامدًا فالقليل ليس حرامًا، ما مدى صحَّة هذا؟","title":"ما معنى \"ما أسكر كثيره فقليله حرام\"؟","answer":"الجواب: هذا من كيسه، ما عليه عمل، هذا النبي عليه الصلاة والسلام قال: ما أسكر كثيره فقليله حرام، ولم يقل: إذا كان رطبًا وإلا جامدًا، ما أسكر كثيره فقليله حرام، سواء كان يُؤكل وإلا يُشرب.","link":"https://binbaz.org.sa/fatwas/24025/ما-معنى-ما-اسكر-كثيره-فقليله-حرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما أسكر كثيره فقليله حرام.mp3","categories":["شروح الحديث"]},{"id":3825,"question":"المسخ على الحقيقة مسخ وجه؟","title":"هل المسخ قردة وخنازير يكون على الحقيقة؟","answer":"الجواب: هذا هو الأصل، المسخ على الحقيقة.  وقد تمسخ القلوب -نسأل الله العافية-، لكن الأصل في إطلاق المسخ هو مسخ الصورة، كما فعل الله في بني إسرائيل لما غيَّروا وبدَّلوا.","link":"https://binbaz.org.sa/fatwas/24026/هل-المسخ-قردة-وخنازير-يكون-على-الحقيقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل المسخ على الحقيقة في حديث ..ويمسخ آخرين قردة وخنازير إلى يوم القيامة.mp3","categories":["شروح الحديث"]},{"id":3826,"question":"استحلال هذه الأشياء كفر (في حديث يَسْتَحِلُّونَ الحِرَ والحَرِيرَ)؟","title":"معنى \"يَسْتَحِلُّونَ الحِرَ والحَرِيرَ..\" في الحديث","answer":"الجواب: نعم، ما في شك، مَن استحلَّ الزنا كفر والخمر كفر، وهكذا.\nس: طعن ابن حزم في هذا الحديث؛ لأنه مُعلَّق؟\nج: ما وُفّق ابن حزم في هذا، معلّقات البخاري ومسلم صحيحة، المجزوم بها.\nس: تكريم بعض المغنين ما يعتبر تحليلًا لهذا الشيء؟\nالشيخ: لا، ما يعتبر.","link":"https://binbaz.org.sa/fatwas/24027/معنى-يستحلون-الحر-والحرير-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسائل تتعلق بحديث ليكوننّ من أمّتي أقوام يستحلّون الحر والحرير..mp3","categories":["شروح الحديث"]},{"id":3828,"question":"كيف يكون النيل والفرات من أنهار الجنة؟","title":"كيف يكون النيل والفرات من أنهار الجنة؟","answer":"الجواب: بيَّن العلماء هذا، وأنها أسماء متوافقة: نهران باطنان، ونهران ظاهران، الظاهران: النيل والفرات، والباطنان: سيحون وجيحون. وقال جمعٌ أنها أسماء مُتوافقة، وافقت ما في الدنيا. وقال آخرون: لا مانع من أن يكون ما في الدنيا أصله من هذه الأنهار، وأن الله أنزل منها شيئًا فجعله سببًا لهذه الأنهار التي في الأرض: سيحون، وجيحون، والنيل، والفرات. محتمل هذا وهذا.","link":"https://binbaz.org.sa/fatwas/24030/كيف-يكون-النيل-والفرات-من-انهار-الجنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/كيف يكون النيل والفرات من أنهار الجنة.mp3","categories":["شروح الحديث"]},{"id":3831,"question":"النَّهي للتَّحريم أو التَّنزيه؟","title":"حكم اختناث الأسقية (الشرب من فم القربة)","answer":"الجواب: ظاهره التنزيه؛ لأنه ورد الشرب منها عند الحاجة، فالأصل في هذا التحريم، لكن المراد من شربه منها في بعض الأحيان... للأدب والكراهة والحماية مما يضرّ الإنسان.","link":"https://binbaz.org.sa/fatwas/24033/حكم-اختناث-الاسقية-الشرب-من-فم-القربة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث سمعت رسول الله ينهى عن اختناث الأسقية، النهي للتحريم أو التنزيه.mp3","categories":["شروح الحديث","الآداب والأخلاق"]},{"id":3835,"question":"علة التحريم..؟","title":"علة تحريم أواني الذهب والفضة","answer":"الجواب: اختلفوا في هذا: منهم مَن قال إنَّ فيها كسرًا لقلوب الفقراء. ومنهم مَن قال إنَّ فيها فخرًا وخيلاء...","link":"https://binbaz.org.sa/fatwas/24037/علة-تحريم-اواني-الذهب-والفضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/علة تحريم الأكل والشرب في أواني الذهب والفضة.mp3","categories":["الآنية","شروح الحديث"]},{"id":3841,"question":"تشبيه المؤمن: خامة من الزرع؟","title":"ما معنى تشبيه المؤمن بخامة الزرع بالحديث؟","answer":"الجواب: مثل ما بيَّن النبي ﷺ: تفيؤه الرياح هكذا وهكذا، المؤمن يصيبه تارة كذا، تارة موت ولد، تارة زوجة، تارة أمراض عارضة، يعني يصاب بأشياء متنوعة.","link":"https://binbaz.org.sa/fatwas/24044/ما-معنى-تشبيه-المومن-بخامة-الزرع-بالحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث مثل المؤمن كمثل الخامة من الزرع..mp3","categories":["شروح الحديث"]},{"id":3842,"question":"هل مستمرة هذه الدعوة؟","title":"هل دعوة \"وانقل حمّاها بالجحفة\" مستمرة؟","answer":"الجواب: الظاهر أنها مستمرة، خراب الجحفة.","link":"https://binbaz.org.sa/fatwas/24047/هل-دعوة-وانقل-حماها-بالجحفة-مستمرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الدعوة في حديث ..وانقل حمّاها فاجعلها بالجحفة..mp3","categories":["شروح الحديث"]},{"id":3844,"question":"هل مستثنى من هذا (حديث إنّ المسلم ليؤجر في كل شيْء ينفقه إلّا في شيء يجعله في هذا التراب) ما يحتاجه الإنسانُ، يعني من مسكنٍ؟","title":"هل يُؤجر المرءُ في بناء مسكن لحاجته؟","answer":"الجواب: كأنَّ قصاراه أنه مباح، ليس بقربةٍ، قد يُستثنى من هذا أنه إذا فعله لأجل قصدٍ صالح، وهو الستر والاستغناء عن الناس، والاستفادة من هذا في شيءٍ ينفع الأهل والعائلة والضيف.  هو ما رفعه، لكنه في حكم الرفع، لكن هذا ما يُقال بالرأي.","link":"https://binbaz.org.sa/fatwas/24051/هل-يوجر-المرء-في-بناء-مسكن-لحاجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث إنّ المسلم ليؤجر في كل شيْء ينفقه، إلّا في شيء يجعله في هذا التراب.mp3","categories":["شروح الحديث"]},{"id":3845,"question":"شراء العقار، التجارة في العقار والأراضي؟","title":"ما حكم التجارة في العقار وفضل النية فيها؟","answer":"الجواب: هذه أبواب التّجارة، لها شأنٌ آخر، إن كانت له نيَّة صالحة في البيع والشراء لينفع عباد الله، وليستغني هو مأجورٌ، وإن كان ما له نيَّة فيها، إنما هي للدنيا؛ فلا له ولا عليه، ليس له ولا عليه.\nوفي الحديث الصحيح يقول ﷺ: الساعي على الأرملة والمسكين كالمجاهد في سبيل الله، أو قال: كالصائم لا يُفطر، والقائم لا يفتر، وفي الحديث الآخر: التاجر المسلم الصدوق الأمين يُحشر مع النَّبيين والصّديقين، أخرجه أبو داود بإسنادٍ جيدٍ وغيره.\nالمقصود على حسب النية، والاستقامة في العمل، وتحري الحق، وتحري البُعد عمَّا حرم الله من الغشِّ والخيانة والربا ونحو ذلك، هذا يُؤجر على حسب تحريه ونيته في تجارته وغيرها.","link":"https://binbaz.org.sa/fatwas/24052/ما-حكم-التجارة-في-العقار-وفضل-النية-فيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/التجارة في العقار مع حديث إنّ المسلم يؤجر في نفقته كلها إلّا ما يجعله في التّراب.mp3","categories":["شروح الحديث"]},{"id":3846,"question":"حديث يأتي على الناس زمان يمر الرجل على القبر فيقول ليتني مكانك؟","title":"حكم تمني الموت والدعاء خشية الفتن","answer":"الجواب: جاء في الصحيح، لكن هذا ما هو بحجَّة، من كلام الناس، من شدة الهول، من شدة الأهوال، لا به الدين، ولكنه من شدة الهول، يعني: من شدة الفتن، نسأل الله العافية. س: حديث معاذ وإذا أردت بقوم فتنة فاقبضني إليك.. ج : هذا مُعَلّق. س: إذا خشي على نفسه من الفتن؟ ج: مثلما قال: اللهم أحيني إذا كانت الحياةُ خيرًا لي، وتوفَّني إذا كانت الوفاةُ خيرًا لي.","link":"https://binbaz.org.sa/fatwas/24053/حكم-تمني-الموت-والدعاء-خشية-الفتن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/شرح حديث ..ولا يتمنَّينّ أحدكم الموت...mp3","categories":["شروح الحديث"]},{"id":3847,"question":"الجمع بين هذا وبين حديث السبعين ألف؟","title":"كيف يُجمع بين التداوي وفضل السبعين ألفًا؟","answer":"الجواب: ما في منافاة؛ لأنَّ السبعين تركوا شيئًا ينبغي تركه، وهو الاسترقاء، سؤال الناس والكي مكروه، قال النبي ﷺ: وأنهى أمتي عن الكيِّ، والطيرة شرك، فهم تركوا أشياء ينبغي تركها، ما قال: لا يتعاطون الأسباب كلها.","link":"https://binbaz.org.sa/fatwas/24055/كيف-يجمع-بين-التداوي-وفضل-السبعين-الفا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الجمع بين حديث الشفاء في ثلاثة..، وحديث السبعين ألف.mp3","categories":["شروح الحديث"]},{"id":3850,"question":"إذا فعل الاسترقاء عند الحاجة إليه اختلَّ فيه شرط السبعين؟","title":"هل يخرج من السبعين ألفًا من استرقى للحاجة؟","answer":"الجواب: الظاهر أنه ما يختل؛ لأنه أمر به النبيُّ ﷺ، من تركه عند عدم الحاجة إليه.","link":"https://binbaz.org.sa/fatwas/24059/هل-يخرج-من-السبعين-الفا-من-استرقى-للحاجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يختلَّ شرط السبعين إذا فعل الاسترقاء عند الحاجة.mp3","categories":["شروح الحديث"]},{"id":3855,"question":"ما العود الهندي؟","title":"ما العود الهندي المذكور في الحديث؟","answer":"الجواب: المعروف الآن بالقسط، يُسمونه: القسط، يعرفونه الآن، يُحك بالماء، أو بماء الورد، وتُرفع به اللهاة.","link":"https://binbaz.org.sa/fatwas/24066/ما-العود-الهندي-المذكور-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث ..عليكم بهذا العود الهندي.. ما هو العود الهندي.mp3","categories":["شروح الحديث"]},{"id":3856,"question":"قوله ﷺ: صدق الله؟ (في حديث صدق الله وكذب بطن أخيك)؟","title":"معنى حديث \"صدق الله وكذب بطن أخيك\"","answer":"الجواب: في قوله: فِيهِ شِفَاءٌ لِلنَّاسِ [النحل:69].","link":"https://binbaz.org.sa/fatwas/24067/معنى-حديث-صدق-الله-وكذب-بطن-اخيك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بقوله صدق الله في حديث صدق الله وكذب بطن أخيك.mp3","categories":["شروح الحديث"]},{"id":3859,"question":"قوله ﷺ: وأكره أن أُثير على أحدٍ شرًّا (في قصة سحر لبيد اليهودي)؟","title":"معنى حديث \"وأكره أن أُثير على أحدٍ شرًّا\"","answer":"الجواب: ما تعرَّض لها الشارح، وكأنَّ المقام فيه شيء من الحذف، وأن مُراده أن يفعل شيئًا يَعْلَمُه الناسُ، يعني: يصنع شيئًا بلبيد ومَن ساعد لبيدًا، وأحبّ أن يموت الأمر وينتهي؛ لما حصل له إخراج السحر والقضاء عليه.","link":"https://binbaz.org.sa/fatwas/24070/معنى-حديث-واكره-ان-اثير-على-احد-شرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى حديث ...وأكره أن أُثير على أحدٍ شرًّا.mp3","categories":["شروح الحديث"]},{"id":3860,"question":"هل يقاس عليه سائر التمرات؟","title":"هل يشمل \"مَن تصبَّح بسبع تمرات\" كل التمر؟","answer":"الجواب: يُرجى، لكن ظاهر النص أنه خاصٌّ بالمدينة، ولكن بالنظر إلى قرب المادة لما في التمر... متقارب، كما في بعض الروايات: مِنْ تَمْرٍ، يُرجى أنه إذا تصبَّح بتمرٍ آخر يُرجى أنه يكون ذلك يحصل به المقصود، لكن ما كان من المدينة يكون أكمل ومُتيقن.","link":"https://binbaz.org.sa/fatwas/24071/هل-يشمل-من-تصبح-بسبع-تمرات-كل-التمر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث مَن تصبَّح بسبع تمرات مما بين لابتيها.. هل يقاس عليه سائر التمر.mp3","categories":["شروح الحديث"]},{"id":3861,"question":"تحديد المؤلف بسبع ورقات؟","title":"ما أصل تحديد سبع ورقات للتداوي من السحر؟","answer":"الجواب: هذا نُقل عن كتب الأقدمين، مجرَّب، والسبع لها مزية مثلما قال النبيُّ ﷺ: أريقوا عليَّ من سبع قربٍ لم تُحل أوكيتُها، سبع تمرات في قصة عجوة المدينة مَن تصبَّح بها، السبع لها شأن.\nس: يجوز بأجر؟\nج: يجوز من باب الدواء.\nس: تكرر أو مرة واحدة؟\nج: الغالب أنَّ مرةً واحدة تكفي، ولكن إذا لم يزل المحذور يُعيد، يُكرر مرتين، ثلاثًا، أكثر حتى يزول البلاء.","link":"https://binbaz.org.sa/fatwas/24072/ما-اصل-تحديد-سبع-ورقات-للتداوي-من-السحر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تحديد سبع ورقات للتداوي من السحر.mp3","categories":["شروح الحديث","الطب والتداوي"]},{"id":3862,"question":"إذا كان الشرابُ حارًّا؟","title":"حديث غمس الذّباب.. هل يشمل الشراب الحار؟","answer":"الجواب: ولو حار، ظاهره العموم، لكن الغالب أنه إذا وقع في حارٍّ لا يستطيع أن يُسوِّي شيئًا، الغالب أنه ما يحتاج إلى غمسه، تأكله النار، هذا الغالب؛ لأنه إنما يستطيع الغالب الرفع إذا كان الشرابُ باردًا، أما إذا كان الشرابُ حارًّا ما يستطيع أن يغمس.","link":"https://binbaz.org.sa/fatwas/24073/حديث-غمس-الذباب-هل-يشمل-الشراب-الحار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث إذا وقع الذّباب في إناء أحدكم فليغمسه... فإن كان الشراب حاراً.mp3","categories":["شروح الحديث"]},{"id":3863,"question":"إلى أين حد التَّشمير  (رفع الثوب عن الكعب)؟","title":"ما حد التشمير (رفع الثوب عن الكعب)؟","answer":"الجواب: إلى نصف الساق، ما بين الكعب والنّصف.","link":"https://binbaz.org.sa/fatwas/24074/ما-حد-التشمير-رفع-الثوب-عن-الكعب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما أسفل من الكعبين من الإزار ففي النّار، ما حد التشمير.mp3","categories":["شروح الحديث"]},{"id":3864,"question":"لا ينظر الله إليه، يعني: لا يرحمه؟","title":"هل يصح تأويل \"لا ينظر الله إليه\" بالرحمة؟","answer":"الجواب: هذا تأويل ما هو بصحيحٍ، لكن مقصود النظر هنا يعني: النظر، لا ينظر الله إليه يعني: غضبًا عليه، وإلا هو جلَّ وعلا يرى كلَّ أحدٍ سبحانه، لا تخفى عليه خافية، لكن تعبير لا ينظر الله لا يُكلمه، إشارة إلى غضبه ، وإلا ما يؤول بالرحمة، لكن هذا من مضمون: لا ينظر الله إليهم، لا يرحمهم، ولا يرضى عنهم، بل يغضب عليهم لأعمالهم القبيحة، هذا من مقتضى اللفظ. انظر كلامه على كتاب اللباس.\nس: يُقال يُجرى على ظاهره؟\nج: على ظاهره، مع كونه يفيد الغضب، لا يُكلمهم الله، ولا يُزكيهم، ولهم عذاب أليم، هذه إشارة إلى غضبه عليهم.","link":"https://binbaz.org.sa/fatwas/24076/هل-يصح-تاويل-لا-ينظر-الله-اليه-بالرحمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى لا ينظر الله إليه في حديث من جرّ ثوبه مخيلة لم ينظر الله إليه...mp3","categories":["شروح الحديث","مسائل متفرقة في العقيدة"]},{"id":3865,"question":"قوله ولا حقّ للكعبين..، وقوله ما أسفل من الكعبين؟","title":"معنى \"ما أسفل من الكعبين\"، \"ولا حق للكعبين\"","answer":"الجواب: كلها معناها واحد، يعني: ما يجوز أن يُرخيها حتى تتجاوز الكعب، الحدُّ الكعب.","link":"https://binbaz.org.sa/fatwas/24078/معنى-ما-اسفل-من-الكعبين-ولا-حق-للكعبين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى حديث ولا حق للكعبين، وحديث ما أسفل من الكعبين.mp3","categories":["شروح الحديث"]},{"id":3866,"question":"بالنسبة لإعطاء أبي جهم مع أنها أشغلته؟","title":"لماذا أهدى النبي ﷺ الخميصة التي أشغلته؟","answer":"الجواب: يدل على أن الأمر فيها واسع، وأنه ﷺ كره لبسها؛ لأن أمره أهم من أمر فلان، ولا يدل على التحريم... ولكن الإنسان مأمور بأن يتقي هذا الشيء الذي يشغله.","link":"https://binbaz.org.sa/fatwas/24079/لماذا-اهدى-النبي-ﷺ-الخميصة-التي-اشغلته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إهداء النبي الخميصة التي ألهته لأبي جهم.mp3","categories":["شروح الحديث"]},{"id":3867,"question":"ما في رواية أن النبي ﷺ قال لعكاشة أنت منهم؟","title":"هل صح قول النبي ﷺ لعكاشة \"أنت منهم\"؟","answer":"الجواب: بلى جاء هذا وهذا، اللهم اجعله منهم، ولعلها من تصرف الرواة والله أعلم، يعني أن دعاءه في هذا مستجاب فتصرّف الرواة والله أعلم،. محتمل أنه قال: أنت منهم، وأن الوحي جاء بهذا، وفي اللفظ الآخر قال: اللهم اجعله منهم، محتمل أن إحداهما بالمعنى، رواها الراوي بالمعنى.","link":"https://binbaz.org.sa/fatwas/24081/هل-صح-قول-النبي-ﷺ-لعكاشة-انت-منهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/رواية حديث عكاشة أنت منهم، واللهم اجعله منهم.mp3","categories":["شروح الحديث"]},{"id":3868,"question":"معنى قول العراقي: عبَّر عن المعنى الكائن عند النظر بالنَّظر؟","title":"معنى \"لا ينظر الله ولا يُكلمهم\" بغير تأويل","answer":"الجواب: ما في تصريح بالنفي..... بس أنه لا ينظر الله ولا يُكلمهم إشارة إلى غضبه عليهم ، مع إثبات النظر والتَّكليم، لو أنه ينظر ويتكلم لما عبَّر بذلك، لكن النظر نظران: نظر محبَّةٍ ورضا، ونظر غضبٍ، وهكذا التَّكليم؛ قد يكلم الإنسانُ أخاه عن محبَّةٍ، وقد يُكلمه عن غضبٍ، فأشار بالآية الكريمة أنَّ الله جلَّ وعلا يغضب على أولئك الذين خالفوا أمره فلا ينظر إليهم ولا يُكلمهم كلامًا فيه خيرٌ لهم، ولا نظر فيه خيرٌ لهم، بل نظر غضبٍ، ونظر سخطٍ عليهم، ويُوجب العذاب، وهكذا التَّكليم، وهو سبحانه معلومٌ أنه يكلم يوم القيامة جميع الخلق: ما منكم من أحدٍ إلا سيُكلِّمه ربُّه ليس بينهما ترجمان،  وينظر جميع الخلق، لكن نظر يليق به ، وكلام يليق به ، لا يُشابه خلقه.\nس: يؤخذ من الحديث إثبات النظر ومن ثمرات النظر...؟\nج: نعم، إثبات النظر، وإثبات الكلام، ولكنه هنا نفاه لأجل غضبه عليهم.\nس: العراقي يُؤول؟\nج: ما أدري، ما أعرف عنه شيئًا، ولا هو ببعيدٍ؛ لأنَّ مذهب الأشاعرة غلب على غالب الناس في القرون المتقدمة: في القرن الرابع وما بعده، ولم يسلم إلا القليل.","link":"https://binbaz.org.sa/fatwas/24082/معنى-لا-ينظر-الله-ولا-يكلمهم-بغير-تاويل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى قول العراقي عبَّر عن المعنى الكائن عند النظر بالنَّظر.mp3","categories":["شروح الحديث"]},{"id":3870,"question":"ما يُقال أن تحريم الإسبال له سبب.. هو التكبر؟","title":"هل تحريم الإسبال مقيّد بالتكَبُّر؟","answer":"الجواب: هو وسيلة لذلك، وأيش الذي حمله على جرِّه إلا التكبر؟ ما حمله إلا التَّكبر.\nس: إذا كان من الخياط؟\nج: إذا كان من الخياط يغيّر، خليه يرفعه، ترفعه الزوجة، يرفعه أخوه، ما يحملهم إلا التكبر والتساهل في أمر الله، وعدم المبالاة.  ثم هذا فتح باب الإسبال، فتح باب البلاء، ثم بعض الناس ما يبالي إذا كان مكروهًا ما يبالي، عنده المكروه لا بأس، يُرتكب ولا يبالى به.","link":"https://binbaz.org.sa/fatwas/24084/هل-تحريم-الاسبال-مقيد-بالتكبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/علة تحريم الإسبال التكبر.mp3","categories":["شروح الحديث","اللباس والزينة"]},{"id":3871,"question":"مَن يقول إن اللبس إلى نصف الساقين الآن من الشُّهرة؟","title":"هل يُعَدُّ اللبس إلى نصف الساقين من الشُّهرة؟","answer":"الجواب: لا، غلط، إلى نصف الساق جائز، بل هو أفضل عند جماعةٍ من أهل العلم، إلا إذا كان يترتب عليه شيء، يرخيه إلى الكعب، والحمد لله، ولا يعرض نفسه لشيءٍ يُؤذيه، فما بين نصف الساق والكعب كله جائز.","link":"https://binbaz.org.sa/fatwas/24085/هل-يعد-اللبس-الى-نصف-الساقين-من-الشهرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الرد على من يقول أن اللبس إلى نصف الساقين الآن من الشُّهرة.mp3","categories":["شروح الحديث","اللباس والزينة"]},{"id":3883,"question":"بالنسبة لمن لبسه في الدنيا لم يلبسه في الآخرة؟","title":"معنى \"من لبس الحرير... لم يلبسه في الآخرة\"","answer":"الجواب: من باب الوعيد، من باب التحذير، من باب الوعيد عند أهل السنة؛ لأن أهل الجنة لباسهم الحرير، فظاهره يعني يُمنع من دخول الجنة، من باب الوعيد مثل: لا يدخل الجنة نمام من باب الوعيد؛ للحذر من هذه المعاصي، فإذا تاب الله عليه وعفا عنه؛ دخل.","link":"https://binbaz.org.sa/fatwas/24099/معنى-من-لبس-الحرير-لم-يلبسه-في-الاخرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بحديث من لبس الحرير في الدنيا لم يلبسه في الآخرة.mp3","categories":["شروح الحديث"]},{"id":3884,"question":"من يوقظ صواحب الحجرات، ما المقصود؟","title":"معنى حديث \"من يوقظ صواحب الحجرات؟\"","answer":"الجواب: يعني: ليجتهدن في طاعة الله والصلاة في آخر الليل؛ لأن هذا من أسباب العافية والسلامة، المراد به زوجاته عليه الصلاة والسلام، حث لهن على قيام الليل والتهجد في آخر الليل، والله المستعان.\nوفي هذا قوله: ماذا أنزل من الخزائن وماذا أنزل من الفتن، فيه أن الدنيا جاءت بعده ﷺ؛ جاءت الفتن، وجاءت الخزائن، جاء المال، وجاءت الفتن مع المال، بسط الله على أمته من المال والخير العظيم، وجاء معه الفتن الكثيرة، ولهذا قال بعض الصحابة: أو يأتي الخير بالشر؟ قال: أو خير هو؟ إنما أخشى ما أخشى عليكم ما يفتح عليكم من زهرة الدنيا ثم قال بعد ذلك: إني أخشى أن تبسط لكم كما بسطت على من كان قبلكم فتنافسوها كما تنافسوها فتهلككم كما أهلكتهم، ولا حول ولا قوة إلا بالله.\n.......\nومن هذا حديث أبي سعيد رواه مسلم: إن الدنيا حلوة خضرة، وإن الله مستخلفكم فيها فينظر كيف تعملون، فاتقوا الدنيا، واتقوا النساء، فإن أول فتنة بني إسرائيل كانت في النساء.","link":"https://binbaz.org.sa/fatwas/24100/معنى-حديث-من-يوقظ-صواحب-الحجرات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بحديث من يوقظ صواحب الحجرات..mp3","categories":["شروح الحديث"]},{"id":3887,"question":"قوله: \"مَن ضفَّر فليحلق\" هذا خاصٌّ بالمحرم؟","title":"\"من ضفّر فليحلق\" هل هذا خاصٌّ بالمحرم؟","answer":"الجواب: الأمر مطلق، يحتمل أنه أراد هذا، ويحتمل أنه أراد في بقية السنة، ولكن الكلام في هذه المسائل يتعلق بالعبادات، حَمْلُه على أنه أراده في الحج أظهر؛ لأن المسائل العاديات أمرها واسع، فمَن ضفَّر بغير الحج وأراد أن يقصر فهو محتاج إلى هذا، فإن الناس في عادتهم في غير الحجِّ إنما يحلقون يستريحون .. فالأظهر أن مراده في الحج، هذا مُراده أو في العمرة.\nوقد يكون من باب المشورة، لا من باب الإلزام؛ لأنه إذا لبَّد تجمع الشعر وصعب التقصير من بعضه، بخلاف الحلق فإنه يأتي عليه.","link":"https://binbaz.org.sa/fatwas/24103/من-ضفر-فليحلق-هل-هذا-خاص-بالمحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من ضفّر فليحلق هل هذا أمر للمحرم.mp3","categories":["شروح الحديث"]},{"id":3893,"question":"يَحْرُمُ السواك آخر النهار في العصر؟","title":"ما حكم السواك للصائم؟","answer":"الجواب: هذا ضعيف، يُكره عند بعض الناس، لكن الصواب أنه لا يكره؛ لأنه لا يُزيل الخلوف، خلوف الصائم من الجوف، والسواك مشروعٌ للمؤمن في جميع الأحوال، ولو كان صائمًا.  ولهذا كان النبيُّ ﷺ يستاك دائمًا عليه الصلاة والسلام ويقول: السواك مطهرة للفم، مرضاة للربِّ، ويقول ﷺ: لولا أن أشقَّ على أمتي لأمرتهم بالسواك مع كل وضوءٍ عند كل صلاةٍ، وهذا يدخل فيه صلاة العصر وصلاة الظهر في حقِّ الصائم.  فالصواب أنه لا يُكره في جميع النهار للصائم، بل يُستحب.","link":"https://binbaz.org.sa/fatwas/24109/ما-حكم-السواك-للصاىم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث وَلَخُلُوفُ فَمِ الصَّائِمِ.. هل فيه دليل على حرمة السواك آخر النهار في العصر.mp3","categories":["شروح الحديث"]},{"id":3894,"question":"النَّهي عن ردِّه يقتضي التحريم؟","title":"هل النَّهي عن ردِّ الطيب يقتضي التحريم؟","answer":"الجواب: جاء في اللفظ الآخر: مَن عُرض عليه ريحان فلا يرده، أما هذا من سنة النبي ﷺ أنه كان لا يرد الطيب ﷺ، أما رواية فلا يرده فمحل نظرٍ، أقل ما تُفيد كراهة الرد، أقل ما تُفيد.","link":"https://binbaz.org.sa/fatwas/24110/هل-النهي-عن-رد-الطيب-يقتضي-التحريم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/النَّهي عن ردِّ الطيب.mp3","categories":["شروح الحديث"]},{"id":3896,"question":"هل يدخل في هذا تركيبُ الأسنان؟","title":"هل يدخل تركيبُ الأسنان في التفليج؟","answer":"الجواب: لا، تركيب الأسنان ما هو داخل في هذا، ما هو التفليج، التفليج كونه يحكك ويتزين.","link":"https://binbaz.org.sa/fatwas/24112/هل-يدخل-تركيب-الاسنان-في-التفليج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يدخل في التفليج تركيبُ الأسنان المتساقطة.mp3","categories":["شروح الحديث"]},{"id":3897,"question":"في الحديث: لعن الواشمة والواصلة المستوصلة وهناك رأيت الواشرة والمستوشرة؟","title":"معنى \"الوشر\" وحكمه","answer":"الجواب: الوشر هو التفليج، ولعنه يدل على أنه من الكبائر، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/24113/معنى-الوشر-وحكمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى الواشرة والمستوشرة.mp3","categories":["شروح الحديث"]},{"id":3898,"question":"المِدْرَى هو المشط؟","title":"ما معنى \"المِدْرَى\" المذكور في الحديث؟","answer":"الجواب: المِدْرَى ونحوه الذي يعدّل به الرأس، قد يُسمَّى: المفراق، يُسمونه الآن: المفراق، له حدٌّ يحكّ به الرأس.","link":"https://binbaz.org.sa/fatwas/24114/ما-معنى-المدرى-المذكور-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما هو المدرى.mp3","categories":["شروح الحديث"]},{"id":3900,"question":"معنى لا تدخل في حديث لا تدخل الملائكة بيتا فيه كلب ولا تصاوير؟","title":"معنى عدم دخول الملائكة بيتًا به كلب أو صورة","answer":"الجواب: ملائكة الخير والرحمة، وإلا فالملك الملازم مع العبد لا يُفارقه، من غير الحفظة، نعم.","link":"https://binbaz.org.sa/fatwas/24116/معنى-عدم-دخول-الملاىكة-بيتا-به-كلب-او-صورة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى حديث لا تدخل الملائكة بيتا فيه كلب ولا تصاوير.mp3","categories":["شروح الحديث"]},{"id":3903,"question":"معنى الحلية.....؟","title":"معنى حلية المؤمن المذكورة في الحديث","answer":"الجواب: حلية المؤمن في الجنة، أبو هريرة فعل هذا ليُزاد له في الحلية، جاء في الحديث: تبلغ الحلية من المؤمن حيث يبلغ الوضوء، فجعل يزيد حتى تكون الحليةُ تستمر، ولكن هذا لا يدل على شرعية الزيادة، يكون مبلغ الحلية مبلغ الوضوء إلى منتهى المرفقين، ما بعد المرفقين.","link":"https://binbaz.org.sa/fatwas/24119/معنى-حلية-المومن-المذكورة-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث تبلغ الحلية من المؤمن حيث يبلغ الوضوء.mp3","categories":["شروح الحديث"]},{"id":3909,"question":"امتناع الملائكة من دخول البيت الذي فيه كلب، يشمل كلب الصيد؟","title":"هل يمنع كلب الصيد دخول الملائكة للبيت؟","answer":"الجواب: لا ما يشمل، هذا المراد به الكلب اللي ما هو مأذون فيه، مثل ما تقدم في الدرس الماضي، أما الكلاب المأذون فيها والصور المأذون فيها ما تمنع، الصور الممتهنة لا تمنع دخول الملائكة، ولهذا قال جبرائيل: اجعل منه وسادتين ودخل جبرائيل لما جعل الستر وسادة، وكذلك الكلب الغير مأذون فيه هو الذي يمنع، أما المأذون فيه ككلب الصيد والماشية والزرع فلا يمنع؛ لأنه مأذون فيه.","link":"https://binbaz.org.sa/fatwas/24127/هل-يمنع-كلب-الصيد-دخول-الملاىكة-للبيت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تمتنع الملائكة من دخول البيت الذي فيه كلب صيد.mp3","categories":["شروح الحديث"]},{"id":3911,"question":"مناسبة الحديث (ركب على حمار على إكاف عليه قطيفة فدكيّة...)  في كتاب اللباس؟","title":"معنى \"ركب على حمار على إكاف..\" بالحديث","answer":"الجواب: لأن -والله أعلم- الجلوس على الشيء نوع من اللباس، ولأنه ألصق به.. تواضع، فكما يتواضع الناس في مجالسهم وفرشهم، وما يتكئون عليه، كذلك فيما يركبون.\nس: يقول في الحديث: ركب على حمار على إكاف عليه قطيفة فدكيّة..\nالشيخ: فوق الإكاف، يعني مفروشة فوق الإكاف.\nس: ما هو الإكاف؟\nالشيخ: الظاهر مثل بردعة التي تكون على الحمار، شيء يُوَطَّأ ويُجعل على ظهر الحمار، يكون في حشوه ليف، وإلا شبهه، فوق الحمار، يركب عليه الراكب، يسمونه عندنا بردعة، ويسمى \"إكاف\" في اللغة.","link":"https://binbaz.org.sa/fatwas/24129/معنى-ركب-على-حمار-على-اكاف-بالحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسائل تتعلق بحديث ركب على حمار على إكاف عليه قطيفة فدكيّة..mp3","categories":["شروح الحديث"]},{"id":3913,"question":"شرح الحديث بأن من أدى الصلاة على وقتها..؟","title":"فضل الصلاة لوقتها وحكم تركها","answer":"الجواب: ذكر أن هذا أحب الأعمال، فأخذ بطلانها قبل وقتها أو بعد وقتها من أدلة أخرى؛ لأن الواجب أن تُؤدى العبادة على وجهها الذي شرعه الله، فتقديمها على وقتها أداء لها على الوجه الذي لم يشرعه الله، وهكذا إذا أخّرها عمدًا بطلت على الأصح من قولي أهل العلم، كأنه لا صلاة له في الحقيقة، وكفر بذلك إذا تعمد ذلك.  لهذا قال عليه الصلاة والسلام: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر، ما هو بمعنى تركها دائمًا دائمًا حتى ولو ترك وقتين أو ثلاثة، وهكذا قوله ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة رواه مسلم، هذا يعمها تركها بالكلية ويعم تركها فروضًا أخرى متعمدًا، فإذا تاب تاب الله عليه.  لكن إن تركها عن نسيان عن نوم عن شبهة في بعض المرضى، لم يتعمد تركها بقصد المخالفة، ولكن بعض الناس يظن أن تركها حتى يطيب حتى يشفى أنه أولى حتى يصليها صلاة كاملة، وهذا من الجهل، فهذا لا يكفر؛ لأنه متأول، ولكن يُنبّه أن الواجب أن يفعلها ولو في المرض، إذا عجز أن يصلي قائمًا صلى قاعدًا، وإذا عجز أن يصلي قاعدًا يصلي على جنبه، وإذا عجز عن جنبه يصلي مستلقيًا.  أما التأخير فلا يجوز؛ لكنه لا يكفر لأجل التأويل؛ لأنه ما أخرها تساهلًا بها، إنما أخرها بزعمه ليصليها على وجه أكمل، فغلط في هذا، وهكذا من أخرها عن نوم يعني معذور، أو عن نسيان معذور، فيأمر بها أيضًا، ولهذا في الحديث الصحيح: من نام عن الصلاة أو نسيها فليصلها إذا ذكرها لا كفارة لها إلا ذلك. بخلاف المتعمد المتلاعب فهذا له شأن آخر، فالجمهور من المتأخرين على أنه كفر دون كفر، وأنه قد أتى كبيرة عظيمة، ومعصية عظيمة، لكن لا يخرج من الإسلام، والقول الثاني وهو الصواب أنه يخرج من الإسلام إذا تعمد ذلك، تعمد بغير شبهة، إن تعمد ذلك تساهلًا متهاونًا.  أما لو جحد وجوبها، وقال إنها لا تجب ومثله يعلم الحكم؛ يقام عليه الدليل إذا كان في جاهلية بعيدة عن الإسلام، فإذا أصر كفر عند الجميع، عند جميع أهل العلم، ولو صلى، ولو كان يصلي مع الناس، إذا جحد وجوبها كفر إجماعًا، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/24131/فضل-الصلاة-لوقتها-وحكم-تركها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/شرح حديث أيّ العمل أحبّ إلى الله...mp3","categories":["شروح الحديث"]},{"id":3914,"question":"هذا التوقيت يشمل عموم الوقت أوله وآخره؟","title":"معنى حديث \"الصّلاة على وقتها\"","answer":"الجواب: أول الوقت على وقتها أول الوقت، لكن إذا صلاها في أثناء الوقت أو في آخر الوقت صحت، ولا إثم عليه، لكن كونها يصليها في أول الوقت كما فعل النبي ﷺ يراعي أوائل الأوقات هذا هو الأفضل، إلا في مسائل مستثناة: كمسألة شدة الحر في الظهر، الإبراد بها أفضل.  وكالعشاء إذا لم يجتمعوا شرع له أن يراعيهم حتى يجتمعوا، كما قال جابر: كان النبي إذا رآهم اجتمعوا عجل، وإذا رآهم أبطؤوا أخر، يعني في العشاء، أو لأسباب أخرى اقتضت ذلك رآها الإمام أو ولي الأمر لأمر حدث فأخّره لأجل أمر حدث.  وإلا فالأصل مراعاة أول الوقت، لكن مراعاة أول الوقت مع مراعاة وقت يتسع للوضوء وقضاء الحاجة، يعني بعد أول الوقت بربع ساعة بنصف ساعة؛ لمراعاة هذا الشيء الذي يتمكن منه الناس للوضوء والحضور للمسجد.","link":"https://binbaz.org.sa/fatwas/24132/معنى-حديث-الصلاة-على-وقتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى حديث ..الصّلاة على وقتها.mp3","categories":["شروح الحديث"]},{"id":3920,"question":"هذا الحديث يدل على تفضيل بر الوالدين على الجهاد؟","title":"هل يدل \"أيّ العمل أحبّ\" على أفضلية البر؟","answer":"الجواب: نعم، لكن عند أهل العلم الجهاد جنس الجهاد، أما إذا تعين إذا هجم العدو على البلد؛ وجب عليهم أن يدافعوا، ولو أبى الوالد، إذا هُجم على البلد.","link":"https://binbaz.org.sa/fatwas/24138/هل-يدل-اي-العمل-احب-على-افضلية-البر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يستدل بحديث أيّ العمل أحبّ إلى الله... على تفضيل بر الوالدين على الجهاد.mp3","categories":["شروح الحديث"]},{"id":3925,"question":"قول النبي ﷺ: لو أقسم على الله لأبره..؟","title":"معنى حديث \"لو أقسم على الله لأبره..\"","answer":"الجواب: هذا حديث آخر، هذا لصلاحه وتقواه قد يقع هذا، مثل ما جرى للبراء بن مالك وغيره، ومثل ما جرى أيضًا في قصة الربيّع.","link":"https://binbaz.org.sa/fatwas/24143/معنى-حديث-لو-اقسم-على-الله-لابره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث لو أقسم على الله لأبره..mp3","categories":["شروح الحديث"]},{"id":3926,"question":"هذا الرجل الذي سابَّه أبو ذر..؟","title":"من الذي سابَّه أبو ذر؟ وماذا فعل معه؟","answer":"الجواب: غلام لأبي ذر مملوك.\nس: هنا يقول: كان بيني وبين رجل كلام؟\nالشيخ: هو خادم وهو رجل، لكن أبهمه هنا وبيّن في رواية أخرى أنه غلام له.\nس: ذكر أنه بلال (الشارح)؟\nالشيخ: رواية؟\nالطالب: \"ساببت رجلًا\" وقد تقدم شرحه في كتاب الإيمان وأن الرجل المذكور هو بلال. الشيخ: لا، ما هو الظاهر، المقصود غلام له كما في الرواية الأخرى: غلام له مملوك له، لأبي ذر؛ ولهذا كان يعطيه مثل حلته، يُلبسه مثل حلته، إذا لبس حلة جديدة أعطاه حلة جديدة، والرائي رأى معه حلة مختلفة، الرداء من نوع والإزار من نوع، وعلى أبي ذر مثل ذلك الرداء من نوع والإزار من نوع، فقال له الرجل: لو أنك أخذت الذي على الغلام من الإزار الذي يوافق الرداء الذي يوافق إزارك فجعلته عليك؛ حتى يكون عندك حلة كاملة وهو يكون عنده حلة كاملة. ففعل ما قال، أراد أن يساويه في الطَّيِّب والخَلَق.","link":"https://binbaz.org.sa/fatwas/24144/من-الذي-سابه-ابو-ذر-وماذا-فعل-معه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من الذي سابَّه أبو ذر؟ وماذا فعل معه؟.mp3","categories":["شروح الحديث"]},{"id":3929,"question":"قوله ما لم يَيْبَسا؟","title":"معنى حديث \"لعلّه يخفّف عنهما ما لم يَيْبَسا\"","answer":"الجواب: هذا لحِكمة بالغة أنهما تنفعان ما دامتا رَطْبَتَين، وقال بعض السلف أنهما تسبّحان، والله أعلم.","link":"https://binbaz.org.sa/fatwas/24148/معنى-حديث-لعله-يخفف-عنهما-ما-لم-ييبسا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بقوله ما لم ييبسا، في حديث لعلّه يخفّف عنهما ما لم ييبسا.mp3","categories":["شروح الحديث"]},{"id":3932,"question":"ما معنى ويَكْلَح؟","title":"معنى حديث \"..فيأكله ويَكْلَحُ \" في الغِيبة","answer":"الجواب: هذا ظاهر، يعني يُظهر الكراهة، تُرى على وجهه، الكراهة لما ألزم به، يأكله كارهًا لهذا الشيء، كالِح في وجهه لما ألزم به، نسأل الله العافية، والكالِح: غير المُنْبَسِط.","link":"https://binbaz.org.sa/fatwas/24151/معنى-حديث-فياكله-ويكلح-في-الغيبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى ويكلح في حديث من أكل لحم أخيه في الدّنيا قُرّب له يوم القيامة... فيأكله ويكلح.mp3","categories":["شروح الحديث"]},{"id":3935,"question":"قول عائشة للنبي ﷺ: \"هلّا تَنَشَّرْتَ\"؟","title":"معنى قول عائشة للنبي ﷺ: \"هلّا تَنَشَّرْتَ\"","answer":"الجواب: هذا هو الأصل، لكن المقصود حصل لما أزيل هذا انتهى الموضوع، لما أخذوه وأتلفوه انتهى الموضوع ولا حاجة إلى  غير هذا. والرواية الأخرى تدل على يعني: ألا انتقمت من فعل ذلك؟ فأحب أن يملك الأمر وألا يبعث على الناس شرًّا عليه الصلاة والسلام، يظهر من السياق أنها أرادت بهذا: ألا أظهرت هذا الأمر وانتقمت ممن فعله؟ وبينت للناس سوء صنيعه.  فأراد ﷺ أن يملك الأمر وألا يبعث على الناس شرًّا عليه الصلاة والسلام؛ فالإنسان وإن كان مظلومًا قد يعفو وَجَزَاءُ سَيِّئَةٍ سَيِّئَةٌ مِثْلُهَا فَمَنْ عَفَا وَأَصْلَحَ فَأَجْرُهُ عَلَى اللَّهِ [الشورى : 40] فالعفو مطلوب من المؤمن إذا رأى فيه المصلحة.","link":"https://binbaz.org.sa/fatwas/24155/معنى-قول-عاىشة-للنبي-ﷺ-هلا-تنشرت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بقول عائشة للنبي هلا تنشرت..mp3","categories":["شروح الحديث"]},{"id":3936,"question":"الكَنَف (في حديث يضع كَنَفَه عليه..) ؟","title":"معنى \"يضع كَنَفَه عليه..\" في الحديث","answer":"الجواب: الله أعلم، نؤمن به ونقول لا يعلم كيفيته إلا هو .\nس: ما جاء أنه الرحمة؟\nالشيخ: هذا تأويل، لا يعلم صفته إلا هو .","link":"https://binbaz.org.sa/fatwas/24156/معنى-يضع-كنفه-عليه-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بالكنف في حديث يدنو أحدكم من ربّه حتّى يضع كنفه عليه..mp3","categories":["شروح الحديث","الأسماء والصفات"]},{"id":3942,"question":"يا شيخ يرتد عن الدين أو كيف؟","title":"معنى \"إذا قال:... يا كافر فقد باء به أحدهما\"","answer":"الجواب: من باب الوعيد، من باب التحذير، ما هو معناه أنه ارتد عن الإسلام، معناه أنه باء بهذه الكلمة؛ استحق أن يُوصف بها، فليحذر أن يقول ذلك، وليس معناه أنه كفر وارتد عن الإسلام، لا، معناه أنه تعرض لأمر عظيم فيه شر عليه.","link":"https://binbaz.org.sa/fatwas/24165/معنى-اذا-قال-يا-كافر-فقد-باء-به-احدهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بحديث إذا قال الرّجل لأخيه يا كافر، فقد باء به أحدهما.mp3","categories":["شروح الحديث"]},{"id":3943,"question":"(الذي) انفرد عن معاذ.. صلى وحده؟","title":"متى يجوز للمأموم الانفراد عن الإمام؟","answer":"الجواب: نعم، انفرد عن معاذ، صلى وحده.\nس: هل فيه جواز  الانفرد عند الحاجة؟\nالشيخ: يجوز إذا طوّل الإمام، يكون يشق على بعض المأمومين يكون له حاجة أو عنده ضعف؛ لأن الرسول ﷺ ما أنكر عليه، بل أنكر على معاذ.","link":"https://binbaz.org.sa/fatwas/24166/متى-يجوز-للماموم-الانفراد-عن-الامام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسائل من حديث يا معاذ، أفتّان أنت..mp3","categories":["شروح الحديث"]},{"id":3945,"question":"قوله \"بأبي وأمي\"؟","title":"معنى القول: \"بأبي وأمي\"","answer":"الجواب: يعني: أفديك بأبي وأمي، كلمة تقولها العرب في تعظيم المخاطب.","link":"https://binbaz.org.sa/fatwas/24168/معنى-القول-بابي-وامي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى بأبي وأمي.mp3","categories":["شروح الحديث"]},{"id":3951,"question":"المقصود بالغضب هنا في الأمر الدنيوي فقط...؟","title":"ما الفرق بين الغضب لله والغضب المذموم؟","answer":"الجواب: يعني: الغضب فيما يقع بين الناس.  أما الغضب لله فهذا محمود، الغضب لله في إنكار المنكر في الوعظ والتذكير ليس مرادًا هنا، هذا غيرة لله، هذا غضب مقصود.","link":"https://binbaz.org.sa/fatwas/24174/ما-الفرق-بين-الغضب-لله-والغضب-المذموم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الجمع بين النهي عن الغضب والغضب لله.mp3","categories":["شروح الحديث"]},{"id":3954,"question":"قوله: (في حديث مكتوب في الحكمة إنّ من الحياء وقارًا) المقصود بالحكمة هنا؟","title":"معنى حديث \"في الحكمة إنّ من الحياء وقارا\"","answer":"الجواب: يعني يقصد: كُتُب الحِكمة التي تُنقل عن الأوائل.","link":"https://binbaz.org.sa/fatwas/24177/معنى-حديث-في-الحكمة-ان-من-الحياء-وقارا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى الحكمة في حديث مكتوب في الحكمة إنّ من الحياء وقارا.mp3","categories":["شروح الحديث"]},{"id":3957,"question":"ما يعتمد على الحديث؟","title":"معنى \"احترسوا من الناس بسوء الظن\"","answer":"الجواب: لا، ضعيف، لكن معناه صحيح احترسوا من الناس بسوء الظن يعني الظن الذي في محله.","link":"https://binbaz.org.sa/fatwas/24182/معنى-احترسوا-من-الناس-بسوء-الظن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى حديث احترسوا من الناس بسوء الظن.mp3","categories":["شروح الحديث","الحكم على الأحاديث"]},{"id":3962,"question":"الغضب مكروه دائمًا، لكن تخصيصه عند الضيف..؟","title":"هل يُنهى عن الغضب في حضور الضيف؟","answer":"الجواب: زيادة، يتأكد يعني: لأن الضيف يتكدر، الغضب بين أهل البيت يتكدر، ولاسيما إذا كان بأسبابه.","link":"https://binbaz.org.sa/fatwas/24190/هل-ينهى-عن-الغضب-في-حضور-الضيف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تخصيص الغضب عند الضيف في حديث أبي بكر دونك أضيافك فإنّي منطلقٌ إلى النّبيّ...mp3","categories":["شروح الحديث"]},{"id":3963,"question":"كلمة يا \"غُنْثَر\" كلمة سب؟","title":"معنى وحكم كلمة \"غُنْثَر\"","answer":"الجواب: نعم كلمة سب، ما تكلم على غُنْثَر؟\nالطالب: قال: قوله \"غُنْثَر\" بضم الغين المعجمة والنون الساكنة وبفتح الثاء المثلثة وبالراء، ومعناه: الجاهل، وقيل: اللئيم، وقيل: السقيم، وروي \"يا عَنْتَر\" بفتح العين المهملة وسكون النون وفتح التاء المثناة من فوق، وهو الذباب، وشَبَهَه حين حقره بالذباب. انتهى.\nالشيخ: المقصود أنها كلمة توبيخ.","link":"https://binbaz.org.sa/fatwas/24191/معنى-وحكم-كلمة-غنثر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى كلمة يا غنثر.mp3","categories":["شروح الحديث"]},{"id":3966,"question":"هذه خاصة بالنخلة أنها لا تَحُتُّ ورقها؟","title":"ما الشجرة التي لا تَحُتُّ ورقها؟","answer":"الجواب: هذا الظاهر أنها معروفة بهذا، وقد يكون هناك شجر لا تَحُتُّ، ولكن ما هو معروف وما هو مشهور، النخلة معروفة بهذا...تؤتي أكلها كل حين بإذن ربها.","link":"https://binbaz.org.sa/fatwas/24194/ما-الشجرة-التي-لا-تحت-ورقها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/النخلة شجرة لا تحت ورقها.mp3","categories":["شروح الحديث"]},{"id":3978,"question":"في الحديث قال ﷺ: إن الشيطان يعقد على قافية أحدكم ثلاث عقد.. ثم قال في آخره: فإذا أصبح أصبح خبيث النفس كسلان؟","title":"ما الفرق بين الخُبْث واللَّقس في وصف النفس؟","answer":"الجواب: هذا من أسباب طاعته للشيطان.... لعل المعنى، مراعاة المعنى، أن المعنى واحد، المراد بالخُبْث: تَغَيُّر، واللَّقس تَغَيُّر، لَقِسِت: تغيرت إلى شيء ما هو أحسن، لكن لفظ اللَّقس أحسن من لفظ الخبث؛ لأن الخبث يُطلق على المحرمات وعلى النجائس وعلى المعاصي، فكان التعبير بـ\"لَقِست\" أنسب، أفضل؛ لأنه لفظ لا يُطلق على تلك الأشياء، فلما صار المعنى متقاربًا صار الأمر للنَّدب، لا للوجوب.","link":"https://binbaz.org.sa/fatwas/24206/ما-الفرق-بين-الخبث-واللقس-في-وصف-النفس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/شرح حديث إن الشيطان يعقد على قافية أحدكم ثلاث عقد..mp3","categories":["شروح الحديث"]},{"id":3981,"question":"النهي عن سب الدهر؛ لأن فيه اعتراضًا على القضاء والقدر؟","title":"الحكمة من النهي عن سب الدهر","answer":"الجواب: الأولى -والله أعلم- أنه سب لمن لا يستحق السب، ما له تصرف، سب لمن لا يستحق السب، فيرجع في الحقيقة إلى من صرفه ودبره ؛ وهذا معلوم أنه ما يقصده الساب، لكن سوء أدب، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/24209/الحكمة-من-النهي-عن-سب-الدهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/لماذا نهينا عن سب الدهر.mp3","categories":["شروح الحديث","مسائل متفرقة في العقيدة"]},{"id":3982,"question":"وَضْع ثَوبِه على وجهه (أي: أبا طلحة لمّا رأى النبي ﷺ وصفية حين عثرت النّاقة)..؟","title":"حكم ستر الرجل وجهه لغض بصره","answer":"الجواب: لئلا يرى منها شيئًا، هذا من شدة حرصه . ويكفي غض البصر؛ لكن كأنه من حرصه ؛ لأنها ساقطة عن البعير فقد تبدو عورة منها، لا يكفي فيها غض البصر.\nس: هل يستشهد بها الإنسان من ضمن ستر الوجه؟\nالشيخ: إذا دعت الحاجة إليه كما فعل أبو طلحة.","link":"https://binbaz.org.sa/fatwas/24210/حكم-ستر-الرجل-وجهه-لغض-بصره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/لماذا وضع أبو طلخة الثوب على وجهه حين رآى النبي وصفية حين عثرت النّاقة.mp3","categories":["شروح الحديث"]},{"id":3983,"question":"أصل معنى التفدية؟","title":"ما معنى التفدية في قول \"فداك نفسي\"؟","answer":"الجواب: يعني يكون الشخص .... فداء له من الحوادث والبلايا.\nس: يعني عوضًا عنه؟\nالشيخ: عوضًا عنه نعم، هذا هو الأصل، يعني يفدي له حتى لا يقع عليه شيء، يعني إذا كان فيه شيء يكون فيهم لا فيه.\nس: تقال مع كل أحد؟\nالشيخ: ممكن، مثل ما فعل النبي ﷺ في هذه الأخبار، ومثل ما فعل الصديق.","link":"https://binbaz.org.sa/fatwas/24211/ما-معنى-التفدية-في-قول-فداك-نفسي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى التفدية في قول فداك نفسي.mp3","categories":["شروح الحديث"]},{"id":3985,"question":"امتناعه عن تغيير اسمه (حَزْن جد ابن المسيّب)؟","title":"حكم تغيير الاسم للحي وبعد الموت","answer":"الجواب: لعله قبل أن يسلم؛ لكن ما بلغنا أنه غيّره، شف حَزْن في التقريب.\nس: معنى قوله : فلا زالت الحزونة فينا؟\nالشيخ: من الحَزْن يعني كلمة حَزْن يعني كأنها نوع غربة، ما قبلوا الاسم الذي قاله النبي ﷺ \"سهل\".\nس: بعد وفاة أبيهم ما يجوز لهم تغييره؟\nالشيخ: لا اشتهر ولم يُغيّر في حياته، ولو مات لا تُغيّر أسماؤه.\nالطالب: حَزْن بوزن الذي قبله لكن آخره نون: ابن أبي وهب بن عمرو بن عائذ بن عمران بن مخزوم، صحابي، استشهد باليمامة، وهو جد سعيد بن المسيب. البخاري وأبو داود.","link":"https://binbaz.org.sa/fatwas/24214/حكم-تغيير-الاسم-للحي-وبعد-الموت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/شرح حديث مَا اسمك قال حزن، قال أنت سهل قال لا أغيّر اسمًا سمّانيه أبي..mp3","categories":["شروح الحديث"]},{"id":3986,"question":"قوله ﷺ: من رآني في المنام فقد رآني؟","title":"ما معنى \"من رآني في المنام فقد رآني\"؟","answer":"الجواب: فإن الشيطان لا يتمثل بصورتي، يعني: رآه حقيقة على صورته، ربعة من الرجال، أبيض مشرب بحمرة، كث اللحية، أسود اللحية إلا شعرات قليلة من الشيب، يعني على صورته التي هو عليها، اللهم صل عليه وسلم.","link":"https://binbaz.org.sa/fatwas/24215/ما-معنى-من-راني-في-المنام-فقد-راني","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى حديث من رآني في المنام فقد رآني.mp3","categories":["شروح الحديث"]},{"id":3987,"question":"قوله: \"فيأمر بالبساط الّذي تحته فيكنس وينضح..\"؟","title":"معنى ما جاء في كنس البساط ونضحه","answer":"الجواب: هذا في قصة أخرى، كان النبي ﷺ زار بيت أنس، جدة له دعته إلى طعام فزارهم ثم قال: قوموا فلأُصَلِّ لكم فقاموا إلى حصير كنسوا مما عليه ورشوه بالماء، وصلى عليه النبي ومن معه من أهل البيت صلاة الضحى.","link":"https://binbaz.org.sa/fatwas/24216/معنى-ما-جاء-في-كنس-البساط-ونضحه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المراد بحديث فيأمر بالبساط الّذي تحته فيكنس وينضح.mp3","categories":["شروح الحديث"]},{"id":3991,"question":"ما هو... في قوله: إنْ وجدناه لبحرًا؟","title":"ما المقصود في حديث \"إنْ وجدناه لبحرًا\"؟","answer":"الجواب: يعني الفرس، يعني جيد، كان الفرس يقولون عنه أنه ما هو بجيد، كان يبطئ، يتهمون الفرس أنه لبس بسبوق، فقال النبيﷺ: إنْ وجدناه لبحرًا يعني لما ركبه النبي ﷺ جعل الله فيه البركة، وصار بعد ذلك جيداً سريعًا سابقًا.","link":"https://binbaz.org.sa/fatwas/24221/ما-المقصود-في-حديث-ان-وجدناه-لبحرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بحديث إنا وجدناه لبحرًا.mp3","categories":["شروح الحديث"]},{"id":3993,"question":"قوله ﷺ كاسيات عاريات قصده عاريات؟","title":"ما معنى \"نساء كاسيات عاريات\" في الحديث؟","answer":"الجواب: رب كاسية في الدنيا عارية في الآخرة على ما قال العلماء: كاسية في الدنيا من الشكر، عارية من الثواب، أو كاسية كسوة لا تستر؛ لرقتها أو قصرها، عارية في الآخرة عقوبة لها على ذلك، مثل ما في الحديث الآخر: صنفان من أهل النار لم أرهما: رجال بأيديهم سياط كأذناب البقر يضربون بها الناس، ونساء كاسيات عاريات مائلات مميلات، رؤوسهن مثل أسنمة البخت المائلة، لا يدخلن الجنة، ولا يجدن ريحها، وإن ريحها لتوجد من مسيرة كذا وكذا رواه مسلم في الصحيح. هذا فيه أقوال العلماء المعروفة: كاسيات عاريات يعني كاسيات من النعم عاريات من الشكر.  أو كاسيات ثيابًا لا تستر عاريات في الحقيقة، نسأل الله العافية، وهذا هو الأليق بالمقام مائلات مميلات مائلات عن الحق إلى الفواحش وإلى المنكرات، مميلات لغيرهن إلى الفواحش والفساد، وهذا هو الواقع، وما أكثر ذلك.\nس: العري في الآخرة ما هو يكون لكل النساء؟\nالشيخ: هذا عري غير العري العام، الناس يوم القيامة عراة كلهم الرجال والنساء، ولكن هذا عري آخر، عري مما يحصل للشاكرين والمستقيمين على طاعة الله من الثواب الجزيل، والفوائد العظيمة، والغرف العالية، ونحو ذلك.\nس: \"عارية\" وصف؟\nالشيخ: وصف الكاسية، نعم..\nس: ما يصلح حال؟\nالشيخ: لا، بالجر أحسن، لأنها نكرة كاسية، والنكرة أقرب إلى الوصف منها إلى الحال.","link":"https://binbaz.org.sa/fatwas/24224/ما-معنى-نساء-كاسيات-عاريات-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/شرح حديث نساء كاسيات عاريات.mp3","categories":["شروح الحديث"]},{"id":3996,"question":"المياثر ما هي؟","title":"معنى المياثر في \"ونهانا عن سبع... والمياثر\"","answer":"الجواب: أشياء توضع على سرج الدابة من الفرس والبعير، يكون فوقه من الحرير، تضعه العجم.","link":"https://binbaz.org.sa/fatwas/24227/معنى-المياثر-في-ونهانا-عن-سبع-والمياثر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما هي المياثر في حديث ...ونهانا عن سبع عن خاتم الذّهب...mp3","categories":["شروح الحديث"]},{"id":3997,"question":"معنى قوله وخيرهما؟","title":"ما معنى \"وخيرهما الّذي يبدأ بالسّلام\" بالحديث؟","answer":"الجواب: يعني أفضلهما، أفضل المتهاجرين: الذي يبدأ بالسلام قبل أخيه، يبدأ ويقول: يا أخي سامحني، ويسلم عليه.","link":"https://binbaz.org.sa/fatwas/24228/ما-معنى-وخيرهما-الذي-يبدا-بالسلام-بالحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى خيرهما في حديث وخيرهما الّذي يبدأ بالسّلام.mp3","categories":["شروح الحديث"]},{"id":3999,"question":"كيف يجاب عن حديث الخثعمية؟","title":"كيف يُجاب عن حديث الخثعمية في الحجاب؟","answer":"الجواب: تقدم الكلام فيه، وأن الخثعمية ليس فيه صريح أنها كانت كاشفة، وأما قول النبي: لا تنتقب المعنى لا تلبس النقاب المعروف الذي يخاط على الوجه، ولا يلزم من ذلك عدم الحجاب؛ لأنها تحتجب بالخمار وبالجلباب، ولهذا قالت عائشة: \"وكنا إذا دنا منا الرجل سدلت إحدانا جلبابها على وجهها\" وقالت: \"كنا نكشف قبل الحجاب، فلما نزل الحجاب خمرنا وجوهنا\".","link":"https://binbaz.org.sa/fatwas/24231/كيف-يجاب-عن-حديث-الخثعمية-في-الحجاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الجواب عن حديث الخثعمية في الحجاب.mp3","categories":["شروح الحديث"]},{"id":4000,"question":"معنى \"ليلًا إلى ليل..\"؟","title":"معنى \"وكان أزواج النبيّ يخرجن ليلًا إلى ليل\"","answer":"الجواب: يعني ما يخرجن في النهار لقضاء حاجتهن، يخرجن في الصحراء لقضاء الحاجة في الليل، ما في البيوت كُنُف، ما عندهم كنف البيوت، ما فيها يعني محلات قضاء الحاجة، هذا من عادات العرب القدامى، ثم اتخذوا الكنف بعد ذلك، وكانوا لا يأكلون إلا قليلًا، عُلْقة؛ لئلا يحتاجوا إلى الحاجة في النهار، لا يأكلون إلا قليلًا، والله المستعان.","link":"https://binbaz.org.sa/fatwas/24232/معنى-وكان-ازواج-النبي-يخرجن-ليلا-الى-ليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى حديث وكان أزواج النبيّ يخرجن ليلا إلى ليل.mp3","categories":["شروح الحديث"]},{"id":4001,"question":"والمناصع أيش هي (في حديث يخرجن ليلًا إلى ليل قِبَلَ المناصع)؟","title":"معنى \"المناصع\" في الحديث","answer":"الجواب: محل قضاء الحاجة. تكلم عندك على المناصع؟\nالطالب: قال -أحسن الله إليك- بكسر القاف وفتح الباء الموحدة (قِبَلَ)، وهو موضع معروف بالمدينة.\nالشيخ: يعني موضع تقضى فيه الحاجات، واد واسع، أرض واسعة، يتفرقون فيها لقضاء الحاجات.","link":"https://binbaz.org.sa/fatwas/24233/معنى-المناصع-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى المناصع في حديث يخرجن ليلا إلى ليل قبل المناصع.mp3","categories":["شروح الحديث"]},{"id":4016,"question":"تصديق الرسول ﷺ لحاطب؟","title":"لماذا صدَّق الرسول ﷺ حاطباً في كلامه؟","answer":"الجواب: لأنه ما قصد ردة ولا كفرًا ولا ضلالاً وإنما تأوّل، والتأويل يُدفع به عن القتل إذا استحق القتل؛ لأنه بالكتاب هذا صار جاسوسًا، ولكن هذا التجسس غلط فيه وتأوّل فيه فصفح عنه النبي ﷺ، وأنزل الله فيما أنزل تحذير الأمة أن يفعلوا فعله.","link":"https://binbaz.org.sa/fatwas/24251/لماذا-صدق-الرسول-ﷺ-حاطبا-في-كلامه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/لماذا صدَّق الرسول حاطب في كلامه.mp3","categories":["شروح الحديث"]},{"id":4032,"question":"قوله ﷺ: لا صوم فوق صوم داود خبر؟","title":"معنى حديث \"لا صوم فوق صوم داود\"","answer":"الجواب: خبر معناه النهي، مثل: لا صام من صام الأبد، لا صام ولا أفطر.","link":"https://binbaz.org.sa/fatwas/24268/معنى-حديث-لا-صوم-فوق-صوم-داود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم على قول لا صوم فوق صوم داود.mp3","categories":["شروح الحديث"]},{"id":4034,"question":"صيام الإثنين فقط من كل أسبوع؟","title":"حكم صيام الإثنين فقط من كل أسبوع","answer":"الجواب: ما في بأس، يصوم الاثنين، أو الخميس، أو يصومهما جميعاً، كله خير.","link":"https://binbaz.org.sa/fatwas/24270/حكم-صيام-الاثنين-فقط-من-كل-اسبوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم صيام الإثنين فقط من كل أسبوع.mp3","categories":["شروح الحديث","صيام التطوع"]},{"id":4044,"question":"س: الفويسقة..؟","title":"الحكمة من إطفاء المصابيح ليلًا ومعنى الفويسقة","answer":"الجواب: الفأرة، هم كانوا يتخذون السُّرُج فيها فتائل على الزيت والدهن، وربما جرّت الفتيلة لأجل ريح الدهن والزيت، وربما جرت الفتيلة على المتاع فتشتد النار على الأمتعة، وبكل حال فقد يختل الكهرب أيضًا؛ فإطفاء السُّرُج أمر مشروع.","link":"https://binbaz.org.sa/fatwas/24280/الحكمة-من-اطفاء-المصابيح-ليلا-ومعنى-الفويسقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/علة إطفاء الأنوار في الليل في حديث أطفئوا المصابيح باللّيل إذا رقدتم..mp3","categories":["شروح الحديث"]},{"id":4049,"question":"قوله: مع النبي ﷺ في زمن النبي ﷺ حديث ابن عمر: رأيتني مع النبيّ ﷺ بَنَيْتُ بيدي بيتًا..؟","title":"معنى حديث \"رأيتني مع النبيّ بنيت بيدي بيتًا\"","answer":"الجواب: نعم، يعني بنى البيت وهو في آخر حياة النبي ﷺ.","link":"https://binbaz.org.sa/fatwas/24286/معنى-حديث-رايتني-مع-النبي-بنيت-بيدي-بيتا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى مع النبي في حديث رأيتني مع النبيّ بنيت بيدي بيتا...mp3","categories":["شروح الحديث"]},{"id":4050,"question":"س:... التطاول في البينان؟","title":"ما حكم رفع البنيان والتطاول فيه؟","answer":"الجواب: لا ما هو على كل حال، من المكروهات يعني؛ لأن الصحابة بنوا ورفعوا البنيان، إذا كان للحاجة ما في شيء، لكن هذا يخبر النبي ﷺ عن العرب، وأنهم بعدما كانوا في رعاء الشاة وفي بيوت الشعر تطاولوا في البينان، هذا من علامات الإقبال على الدنيا، وأمور الساعة، الرسول ﷺ  ما نهى عن هذا، إنما أخبر عنه.\nس: الارتفاع الزائد..؟\nالشيخ: محل نظر، الشيء الذي ما له حاجة ما ينبغي.","link":"https://binbaz.org.sa/fatwas/24287/ما-حكم-رفع-البنيان-والتطاول-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في رفع البنيان والتطاول فيه.mp3","categories":["شروح الحديث"]},{"id":4054,"question":"س: حديث أبرأ إليك ممّا صنع خالد؟","title":"شرح حديث \"أبرأ إليك ممّا صنع خالد\"","answer":"الجواب: خالد بن الوليد لما قتل جماعةً قالوا: صبأنا... بعث إليهم قالوا: صبأنا، صبأنا، ظنَّ أنهم باقون على دينهم فقتلهم، وكانوا أرادوا الإسلام يعني، وهذا غلطٌ من خالدٍ، تبرّأ من عمله النبيُّ ﷺ ووداهم، وأدَّى ما تلف عليه، عليه الصلاة والسلام.\nس: الحديث معلق أحسن الله إليك هذا؟\nج: نعم، ولكن أسنده في مواضع أخرى في يوم الفتح، هذه القصة بعد الفتح.","link":"https://binbaz.org.sa/fatwas/24291/شرح-حديث-ابرا-اليك-مما-صنع-خالد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/شرح حديث اللهم إني أبرأ إليك ممّا صنع خالد.mp3","categories":["شروح الحديث"]},{"id":4065,"question":"معنى: لكن البائس سعد بن خولة؟","title":"ما معنى \"لكن البائس سعد بن خولة\"؟","answer":"الجواب: يعني توجَّع له؛ لأنه مات في مكة محلّ هجرته.","link":"https://binbaz.org.sa/fatwas/24303/ما-معنى-لكن-الباىس-سعد-بن-خولة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى لكن البائس سعد ابن خولة.mp3","categories":["شروح الحديث"]},{"id":4070,"question":"معنى \"جف\" وكلمة \"مشط\" و\"مشطات\"؟","title":"معنى \"جف ومشط ومشطات\" في الحديث","answer":"الجواب: يعني الذي وضعوا فيه السحر، والمشط معروف، المشط: الذي يمشط به الرأس، والمشاطة: ما يُؤخذ من الرأس، ما يسقط من الرأس، وجفّ طلعة ذكر يعني: كافور النخل.","link":"https://binbaz.org.sa/fatwas/24309/معنى-جف-ومشط-ومشطات-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى جف مشط ومشطات في حديث مشط ومشاطة وجفّ طلعة.mp3","categories":["شروح الحديث"]},{"id":4071,"question":"قوله: وكرهتُ أن أُثير على الناس شرًّا.. (أي: بإخراج السحر الذي عمل له ﷺ)؟","title":"معنى \"وكرهتُ أن أُثير على الناس شرًّا\"","answer":"الجواب: هذه رواية: أنه ﷺ تركه ولم يُخرجه.  وفي الرواية الأخرى أنه أخرجه وأتلفه.","link":"https://binbaz.org.sa/fatwas/24310/معنى-وكرهت-ان-اثير-على-الناس-شرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى حديث وكرهتُ أن أُثير على الناس شرًّا.mp3","categories":["شروح الحديث"]},{"id":4077,"question":"تخصيص ولد إسماعيل؟","title":"لماذا خُصَّ ولدُ إسماعيل في فضل التهليل؟","answer":"الجواب: مزية؛ لأنهم أولاد الأنبياء، إسماعيل نبي، والرسول عليه الصلاة والسلام مثلما قال في قصة عائشة في الجارية: اعتقيها؛ فإنها من ولد إسماعيل، وقد جاء في الحديث الصحيح: إنَّ الله اختار من بني آدم بني إسماعيل، واختار من بني إسماعيل كنانة، واختار من كنانة قريشًا، واختار من قريش بني هاشم، واصطفاني من بني هاشم رواه مسلم في \"الصحيح\"، لهم مزية، ولهم فضلٌ خاصٌّ.","link":"https://binbaz.org.sa/fatwas/24316/لماذا-خص-ولد-اسماعيل-في-فضل-التهليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تخصيص ولد إسماعيل في حديث كان كمَن أعتق أربعة أنفسٍ من ولد إسماعيل.mp3","categories":["شروح الحديث"]},{"id":4078,"question":"قوله ﷺ: مَن كان قبلكم المقصود به بني إسرائيل؟","title":"من المقصود بـ \"مَن كان قبلكم\" في الحديث؟","answer":"الجواب: عام، عام.","link":"https://binbaz.org.sa/fatwas/24317/من-المقصود-بـ-من-كان-قبلكم-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من المقصود بمَن كان قبلكم في الحديث.mp3","categories":["شروح الحديث"]},{"id":4082,"question":"أيش معنى قول ابن عباس: لا كبيرة مع الاستغفار، ولا صغيرة مع الإصرار ؟","title":"ما معنى \"لا كبيرة مع الاستغفار...\"؟","answer":"الجواب: على ظاهره لا كبيرة مع الاستغفار: مع التوبة يعني، ولا صغيرة مع الإصرار، إذا أصرَّ ولم يتب صارت كبيرة، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/24322/ما-معنى-لا-كبيرة-مع-الاستغفار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى لا كبيرة مع الاستغفار، ولا صغيرة مع الإصرار.mp3","categories":["شروح الحديث"]},{"id":4083,"question":"قوله: \"ينزو بعضهم على بعض\"؟","title":"معنى \"ينزو بعضهم على بعض\" في الحديث","answer":"الجواب: يعني مثل البهائم، وهذا موجود في دول كثيرة الآن، في الأسواق ينزو بعضُهم على بعضٍ، يُجامعها عند الناس، يركبها عند الناس، يركب بعضُهم بعضًا، الآن موجودة عند الناس في فرنسا، وفي إنجلترا، وفي دول كثيرة في الأسواق، وفي الحدائق -نسأل الله العافية- وهكذا في آخر الزمان أردأ من هذا، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/24323/معنى-ينزو-بعضهم-على-بعض-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى قوله ينزو بعضهم على بعض.mp3","categories":["شروح الحديث"]},{"id":4089,"question":"يُؤخذ منه - حديث: لَمْ يَأْكُلِ النَّبِيُّ ﷺ عَلَى خِوَانٍ حَتَّى مَاتَ..- كراهة الأكل على الخِوان؟","title":"ما معنى الخوان وحكم الأكل عليه؟","answer":"الجواب: ما هو ظاهر؛ لأنه فِعْل تَرْك.\nس: هل يُقصد بالخوان ما ارتفع؟\nج: الذي أفهمه أنه الشيء يكون رفيعًا، لكن المؤلف صاحب \"القاموس\" ما فصَّل...... السفرة التي يُوضع عليها الطعام تُسمَّى: خوانًا، كالسفرة من أي نوعٍ يُقال لها: خوان، وقول الحاشي: \"ما أكل على خوان\" ما هو المراد هذا، توضع على السفرة، ويوضع عليها الطعام، هذا موجود في عهده ﷺ، لكن الأظهر -والله أعلم- هو ما كان معروفًا عند الأعاجم من وضع (أشياء) مرتفعة، يجلسون على الكراسي، مثلما يفعل الآن الكثير من الناس، فيأكلون وهم جالسون على الكراسي وهي مرتفعة، هذا وقع في الناس لما خالطوا الأعاجم، وخالطوا الخارج، دخل عليهم هذا.","link":"https://binbaz.org.sa/fatwas/24329/ما-معنى-الخوان-وحكم-الاكل-عليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما هو الخوان، وحكم الأكل عليه.mp3","categories":["شروح الحديث","الأطعمة والأشربة"]},{"id":4092,"question":"قولها: \"ما أكل آل محمدٍ ﷺ أكلتين في يومٍ إلا إحداهما تمر\"؟","title":"معنى \"ما أكل آل محمدٍ أكلتين إلا إحداهما تمر\"","answer":"الجواب: الغالب أنه من القلَّة، الغالب أنَّ هذا من القلَّة.","link":"https://binbaz.org.sa/fatwas/24332/معنى-ما-اكل-ال-محمد-اكلتين-الا-احداهما-تمر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى ما أكل آل محمدٍ أكلتين في يومٍ إلا إحداهما تمر.mp3","categories":["شروح الحديث","التاريخ والسيرة"]},{"id":4096,"question":"حديث عائشة... ما مرَّ وقتُ السحر إلا ورسول الله نائم؟","title":"توجيه ما جاء في نومه ﷺ وقت السحر","answer":"الجواب: هذا بعض الأحيان، هذا بعض الأحيان، أو مُرادها ما قد يقع له عليه الصلاة والسلام، مثل عمل داود؛ كان نصف الليل، ويقوم ثلثه، وينام سدسه، ينام شيئًا منه في بعض الأحيان ليستعين به على عمل النهار إذا بكَّر بالقيام عليه الصلاة والسلام، فالأحاديث المجملة تُفسّر الأحاديث الواضحة المفسرة.","link":"https://binbaz.org.sa/fatwas/24336/توجيه-ما-جاء-في-نومه-ﷺ-وقت-السحر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الجمع بين قوله تعالى وَبِالْأَسْحَارِ هُمْ يَسْتَغْفِرُونَ ، وحديث عائشة ما مرَّ وقتُ السحر إلا.mp3","categories":["شروح الحديث"]},{"id":4097,"question":"قوله ﷺ: وشيء من الدُّلْجَة؟","title":"معنى \" وشيء من الدُّلْجَة\" في الحديث","answer":"الجواب: تشبيه لنشاطه بالدُّلجة التي يفعلها المسافر، المسافر قد يدلج في أول الليل أو في آخر الليل، وقد ينام أول الليل، ويقوم آخر الليل، يتحرى النشاط. فالمعنى: العامل يأخذ في أوقات نشاطه، كما يأخذ المسافرُ بأوقات نشاطه.","link":"https://binbaz.org.sa/fatwas/24337/معنى-وشيء-من-الدلجة-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بقوله وشيء من الدُّلْجَة.mp3","categories":["شروح الحديث"]},{"id":4100,"question":"معنى الاسترقاء لا يسترقون؟","title":"ما معنى \"لا يسترقون\" في الحديث؟","answer":"الجواب: يطلب الناس، يقولون: اقرؤوا عليَّ، أو على أولادي.  إذا تيسر الاستغناء عن هذا فلا بأس، لكن إذا رقاه أخوه من دون طلبٍ فهذا طيبٌ، مثلما قال ﷺ في الحديث الآخر في رواية مسلم: مَن استطاع منكم أن ينفع أخاه فلينفعه، فإذا رقاه أخوه من دون طلبٍ أو دعت الحاجةُ إلى الاسترقاء؛ فلا كراهةَ، ولهذا أمر أمَّ أولاد جعفر أن تسترقي، وهي أسماء بنت عميس، وأمر عائشة في الحديث الآخر أن تسترقي.","link":"https://binbaz.org.sa/fatwas/24340/ما-معنى-لا-يسترقون-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما معنى لا يسترقون في الحديث.mp3","categories":["شروح الحديث"]},{"id":4101,"question":"رقية جبريل له، ما كانت بطلب منه عليه الصلاة والسلام؟","title":"كيف كانت رقية جبريل للنبي عليه الصلاة والسلام؟","answer":"الجواب: ما بلغني.\nس: رقية جبريل؟\nج: من تبرع جبرائيل، ما بلغنا أنه استرقى ﷺ، وهكذا رقيته لنفسه عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/24341/كيف-كانت-رقية-جبريل-للنبي-عليه-الصلاة-والسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في رقية جبريل للنبي عليه الصلاة والسلام.mp3","categories":["شروح الحديث","الرقى والتمائم"]},{"id":4103,"question":"ما بين المشرق؟","title":"ما معنى \"أبعد مِمَّا بَين الْمشرق\"؟","answer":"الجواب: هذا من التَّنبيه، وأن المشرق له مقابل وهو المغرب، فالشارع قد يكتفي بأحد المتقابلين عن الآخر، مثل: سَرَابِيلَ تَقِيكُمُ الْحَرَّ [النحل:81] يعني: والبرد، ولهذا في رواية مسلم: أبعد مما بين المشرق والمغرب، نسأل الله العافية، يعني: بُعدًا واسعًا، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/24343/ما-معنى-ابعد-مما-بين-المشرق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى قوله في الحديث أبعد مِمَّا بَين الْمشرق.mp3","categories":["شروح الحديث"]},{"id":4106,"question":"س: هذه القصة (قصة الذي أوصى بتحريقه) مما لا يقر في شرعنا؟","title":"ما حكم تحريق الميت ووصيته بذلك؟","answer":"الجواب: نعم، هذا مما جرى فيمَن قبلنا، وأقرَّه النبيُّ ﷺ، لم يُنكرها عليه الصلاة والسلام، ذكرها لنا وأقرَّها.\nس: بالنسبة لمن يحرّقون الميت؟\nج: ما يجوز العمل، لكن المقصود أن هذا الذي وقع منه الخوف من الله أنه حصلت له المغفرة بسبب جهله بسعة قدرة الله ، أما شرعنا فجاء بأنه يُغسَّل ويُصلَّى عليه ويُدفن، ولا يُسحق، ولا يُحرّق، هذا ما يجوز ـ في شرعنا عدم التحريق بالنار، وعدم تحريق الميت، هذا العمل لا يزال عليه الهندوس الآن، نسأل الله السلامة.\nس: لو طلب الشخص في وصيته...؟\nج: ما يُطاع، هذا يُخالف الشرع.","link":"https://binbaz.org.sa/fatwas/24346/ما-حكم-تحريق-الميت-ووصيته-بذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسائل تتعلق بحديث ..فإذا متّ فأحرقوني حتّى إذا صرت فحمًا فاسحقوني..mp3","categories":["شروح الحديث"]},{"id":4107,"question":"قوله ﷺ: إني أنا النذير العريان؟","title":"معنى قوله ﷺ: \"إني أنا النذير العريان\"","answer":"الجواب: يعني المبالغة في النَّذارة، فإن بعض النُّذر إذا خاف ألا يفطنوا له خلع رداءه من على جسده، وجعل يلوي به هكذا حتى يفطنوا له، ولهذا ما على جسده شيء، ما عليه إلا الإزار، كان يحمله حتى الحرص على خلع الإزار، وأخذ إزاره يلوي به.\nالمقصود أنه النذير العُريان، يعني: مبالغ في النَّذارة، حمله شدة الحرص على أن يخلع ثوبه الذي عليه ويلوي به: الحذر، الحذر، النجاء، النجاء.","link":"https://binbaz.org.sa/fatwas/24347/معنى-قوله-ﷺ-اني-انا-النذير-العريان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى قوله إني أنا النذير العريان.mp3","categories":["شروح الحديث"]},{"id":4108,"question":"كيف تُكتب عليه وهو لم يعملها؟ من هم بسيئة ولم يعملها؟","title":"هل تكتب السيئة على من همَّ بها ولم يعملها؟","answer":"الجواب: إذا اجتهد في فعلها، وبذل المستطاع، ولكن حِيل بينه وبين ذلك، مثل الذي أراد قتل صاحبه، ومثل الذي نقر البيتَ ودخل، ولما أراد السرقة حيل بينه وبين ذلك، وما أشبه ذلك..... شرع فيها، ولهذا قال: القاتل والمقتول في النار.","link":"https://binbaz.org.sa/fatwas/24349/هل-تكتب-السيىة-على-من-هم-بها-ولم-يعملها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تكتب السيئة على العبد وهو لم يعملها.mp3","categories":["شروح الحديث"]},{"id":4109,"question":"فهما في الوزر سواء؟","title":"شرح حديث \"فهما في الوزر سواء\"","answer":"الجواب: هذا في حديثٍ آخر، هذا إذا كان الإنسانُ آتاه الله مالًا ولم يُعطه علمًا، فهو يتخبَّط في ماله، فلا يصل فيه رحمه، ولا يتَّقي فيه ربَّه، ولا يعرف لله حقًّا، هذا في أخبث المنازل، والثاني: مَن لم يُعطَ علمًا ولا مالًا، فهو يقول: لو أُعطيتُ مالًا لعملتُ مثل عمل فلانٍ، قال: هذا بنيَّته، فهما في الوزر سواء ...... رواه الترمذي وغيره.","link":"https://binbaz.org.sa/fatwas/24350/شرح-حديث-فهما-في-الوزر-سواء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/شرح حديث فهما في الوزر سواء.mp3","categories":["شروح الحديث"]},{"id":4110,"question":"معنى: مُحقّرات؟","title":"ما معنى \"محقّرات الذّنوب\"؟","answer":"الجواب: التي يحتقرها الإنسانُ، يعني: يراها صغيرةً ويجترئ عليها، مثل: سرقة المال القليل الذي لا يُوجب قطع اليد، ومثل: مُلامسة النساء، ومثل: النظر إلى بعض النساء وهن غير محارم، وأشباه ذلك التي ليس فيها وعيد بغضبٍ ولا لعنٍ ولا نارٍ ولا حدٍّ في الدنيا، الجمهور على أنَّ هذه هي الصغيرة المحقّرة.","link":"https://binbaz.org.sa/fatwas/24351/ما-معنى-محقرات-الذنوب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى مُحقّرات في حديث إيّاكم ومحقّرات الذّنوب..mp3","categories":["شروح الحديث"]},{"id":4111,"question":"قوله: إنّ العبد ليعمل فيما يرى النّاس عمل أهل الجنّة..؟","title":"معنى \"العبد ليعمل فيما يرى النّاس\" بالحديث","answer":"الجواب: يعني: هذا يَظهر منه أنه منافق، أو مُراءٍ بالأعمال التي يُظهرها، وإنْ كان ليس مُنافقًا بالباطن، ولكن جرَّه الرياء وجرَّه التساهل حتى ساءت خاتمته، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/24353/معنى-العبد-ليعمل-فيما-يرى-الناس-بالحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/شرح حديث إنّ العبد ليعمل فيما يرى النّاس عمل أهل الجنّة..mp3","categories":["شروح الحديث"]},{"id":4112,"question":"معنى قوله ﷺ: وكان من أعظم المسلمين غناء عنهم؟","title":"ما حكم من قاتل رياءً أو حمية ونَفَع المسلمين؟","answer":"الجواب: يعني: نفعاً، الغناء النفع، قتل ناسًا كثيرين من المشركين، وأعجب الناس بنشاطه في القتال، فكان فيما سبق من علم الله أنه يقتل نفسه -نسأل الله العافية- وهذا من باب الوعيد، إذا كان ما هو منافق يكون من باب الوعيد، أما إن كان منافقًا فجاء في بعض الروايات أنه سُئل، هذا أو غيره، قال: أنا لم أُقاتل لدينكم، وإنما قاتلتُ لحماية قومي. فظهر نفاقه، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/24354/ما-حكم-من-قاتل-رياء-او-حمية-ونفع-المسلمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى قوله وكان من أعظم المسلمين غناء عنهم.mp3","categories":["شروح الحديث"]},{"id":4114,"question":"قولهﷺ: ويدع الناس من شرِّه...؟","title":"معنى قوله ﷺ: \"ويدع الناس من شرِّه..\"","answer":"الجواب: يعني: يدع إيذاء الناس: من غيبةٍ، أو نميمةٍ، أو ضربٍ، أو غير هذا من أنواع الشرِّ، إذا اعتزل صار بعيدًا عن الشرِّ، فإيذاء الناس أن يُؤذيهم أو يُؤذوه جميعًا.","link":"https://binbaz.org.sa/fatwas/24356/معنى-قوله-ﷺ-ويدع-الناس-من-شره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى قوله ويدع الناس من شرِّه.mp3","categories":["شروح الحديث"]},{"id":4115,"question":"في الحديث قال رسول الله ﷺ المؤمن الذي يخالط الناس ويصبر على أذاهم أفضل من المؤمن الذي لا يخالط الناس ولا يصبر على أذاهم؟ الجمع بينه وبين حديث يُوشك أن يكون خير مال المسلم غنم يتبع بها شعف الجبال..","title":"هل مخالطة الناس والصبر أفضل أم اعتزالهم؟","answer":"الجواب: ما يُنافي هذا، لا بأس به، إسناده حسن، رواه ابن ماجه بإسنادٍ حسنٍ لا بأس به، لكن هذا عند النفع، وعند حصول الفائدة.  أما إذا كان يخشى على نفسه فبُعده أسلم؛ لأنَّ هذا الحديث أصحّ منه، رواية البخاري، هذا أصح.","link":"https://binbaz.org.sa/fatwas/24357/هل-مخالطة-الناس-والصبر-افضل-ام-اعتزالهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الجمع بين حديث يُوشك أن يكون خير مال المسلم غنم يتبع بها شعف الجبال، وحديث.mp3","categories":["شروح الحديث","الحكم على الأحاديث"]},{"id":4116,"question":"كيف نوفق بين حديث بدأ الإسلام غريبًا وسيعود غريبًا..، وبين حديث لا تزال طائفة من أمتي..؟","title":"معنى \"لا تزال طائفة\" مع غربة الإسلام","answer":"الجواب: ما في منافاة، تكون الغربة مع الطائفة المنصورة، يكون غريبًا، والطائفة المنصورة موجودة، لكنها قليلة بالنسبة لأهل الشر.","link":"https://binbaz.org.sa/fatwas/24358/معنى-لا-تزال-طاىفة-مع-غربة-الاسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الجمع بين حديث بدأ الإسلام غريبا وسيعود غريبا، وحديث لا تزال طائفة من أمتي.mp3","categories":["شروح الحديث"]},{"id":4117,"question":"هل ينطبق على تاركي الصلاة في هذا العصر [حديث]: ما أجلده! وما في قلبه مثقال حبّة خردل من إيمان؟","title":"هل يصح وصف \"ما أجْلدَه\" لتاركي الصلاة؟","answer":"الجواب: نعم، ينطبق عليهم وعلى غيرهم من المشركين والضّلال والمنافقين..... يوصفون بالإسلام وهم بعيدون عنه.","link":"https://binbaz.org.sa/fatwas/24359/هل-يصح-وصف-ما-اجلده-لتاركي-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يقال لتارك الصلاة ما أجلده! وما في قلبه مثقال حبّة خردل من إيمان.mp3","categories":["شروح الحديث"]},{"id":4119,"question":"هل يؤخذ من الحديث - من عادى لي ولياً- أن بعض الأولياء  يُعرفون؟","title":"شرح الحديث القدسي: \"من عادى لي وليًّا\"","answer":"الرسل من أولياء الله يقينًا، والأنبياء من أولياء الله، والمؤمنون من أولياء الله، كل مؤمنٍ هو من أولياء الله، فمَن عادى المؤمنين فقد عادى أولياء الله، مَن عادى أهل الاستقامة في طاعة الله فقد عادى أولياء الله، هم مؤمنون، لكن الإنسان لا يُزَكِّي نفسه، يقول: أنا ولي الله؛ لأنه لا يدري؛ قد يكون قصَّر، لكن في نفس الأمر المؤمنون هم أولياء الله، المطيعون لله، المتبعون لشريعته هم أولياء الله.","link":"https://binbaz.org.sa/fatwas/24361/شرح-الحديث-القدسي-من-عادى-لي-وليا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/شرح حديث من عادى لي وليا فقد آذنته بالحرب...mp3","categories":["شروح الحديث"]},{"id":4120,"question":"قوله: كنتُ سمعه وبصره..؟","title":"معنى \"كنتُ سمعه وبصره\" في الحديث القدسي","answer":"الجواب: يعني: تسديده وتوفيقه لهذا الشيء؛ لأنه قال بعده: ولئن سألني لأُعطينَّه، ولئن استعاذني لأُعيذنَّه، وفي اللفظ الآخر: وبي يسمع، وبي يُبصر، وبي يمشي يعني: أنه يُوفَّق في حركاته، وفي سكناته، وفي حواسه، وفي جوارحه؛ بسبب طاعته لله، وإيمانه به، وتقواه لله، يُوفَّق في أعماله وتصرُّفاته، هذا من ثواب الله له؛ أنه يُوفِّقه للعمل الصالح، ولإصابة الحقِّ فيما يأتي ويذر.","link":"https://binbaz.org.sa/fatwas/24362/معنى-كنت-سمعه-وبصره-في-الحديث-القدسي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى قوله كنتُ سمعه وبصره ..mp3","categories":["شروح الحديث"]},{"id":4121,"question":"معنى: حُفاةً؟","title":"معنى \"حُفاةً\" في حديث \"إنكم محشورون حفاة\"","answer":"الجواب: على ظاهره، حُفاة: بدون نعالٍ.","link":"https://binbaz.org.sa/fatwas/24364/معنى-حفاة-في-حديث-انكم-محشورون-حفاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى حُفاةً في حديث إنكم محشورون حفاة.mp3","categories":["شروح الحديث"]},{"id":4125,"question":"مفهوم العدد في سبعين؟","title":"هل صح شيء في الزيادة على السبعين ألفًا؟","answer":"الجواب: جاء في رواية أخرى: وزادني مع كل ألف سبعين ألفًا كما ذكره المؤلف، وذكره الحافظ ابن كثير عند قوله سبحانه: كُنْتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ [آل عمران:110] فإنه جاء له طرق فيها: زادني مع كل ألف سبعين ألفًا وفي لفظ: مع كل واحد سبعين ألفًا وفي بعضها: وثلاث حثيات من حثيات ربي فالذين يدخلون الجنة بغير حساب ولا عذاب لا يحصيهم إلا الله .","link":"https://binbaz.org.sa/fatwas/24370/هل-صح-شيء-في-الزيادة-على-السبعين-الفا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مفهوم العدد في سبعين في حديث ثمّ يشفع كلّ ألف في سبعين ألفا..mp3","categories":["شروح الحديث"]},{"id":4128,"question":"يقول السبعين ألفًا أفضل...؟","title":"هل \"السبعين ألفًا\" أفضل ممن سواهم؟","answer":"الجواب: ما يلزم من هذا الفضل الذي خصهم الله أن يكون غيرهم دونهم؛ لكن فيه فضل أنهم يدخلون الجنة بغير حساب، ثم دخول الجنة بغير حساب متفاوت قد يدخلون جميعًا وهم ملايين بغير حساب؛ ولكنهم طبقات بعضهم فوق بعض، فالصديق مثلًا يدخل الجنة بغير حساب، وعمر يدخل الجنة بغير حساب، والصديق أفضل من عمر، ما يلزم من كونهم يدخلون الجنة بغير حساب أن تكون حالهم واحدة، قد يكون \"السبعين\" والملايين من الداخلين الجنة بغير حساب معلوم أنهم طبقات في فضلهم عند الله  ومقامهم عنده .","link":"https://binbaz.org.sa/fatwas/24374/هل-السبعين-الفا-افضل-ممن-سواهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تفاوت السبعين ألف الذين يدخلون الجنة بغير حساب.mp3","categories":["شروح الحديث"]},{"id":4129,"question":"حديث لا يدخلون الجنة حتى تبلغوا أنتم منازلكم؟","title":"هل يدخل الصحابة الجنة قبل السبعين ألفًا؟","answer":"الجواب: هذا يدل على أنه لا يلزم أن يكونوا سابقين، وإن كانوا دخلوها بغير حساب، لكن لا يلزم أن يكونوا أسبق الناس إليها، قد يسبقهم غيرهم كالصحابة  بالنسبة إلى من بعدهم، ولهذا قال: إني أرجو ألا يدخلوها إلا وقد تبوأتم منازلكم أنتم في الجنة يعني الصحابة ومن صلح من أزواجهم وذرياتهم.\nس: يدل على تفضيل الصحابة على السبعين؟\nالشيخ: على من دونهم.","link":"https://binbaz.org.sa/fatwas/24375/هل-يدخل-الصحابة-الجنة-قبل-السبعين-الفا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/شرح حديث لا يدخلون الجنة حتى تبلغهم منازلهم.mp3","categories":["شروح الحديث"]},{"id":4135,"question":"قوله: يأتيهم الله في الصورة التي يعرفونها؟","title":"معنى \"يأتيهم الله في الصورة التي يعرفونها\"","answer":"الجواب: التي وعدهم بها: يَوْمَ يُكْشَفُ عَنْ سَاقٍ [القلم:42]، ساقه يعني .","link":"https://binbaz.org.sa/fatwas/24381/معنى-ياتيهم-الله-في-الصورة-التي-يعرفونها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى قوله يأتيهم الله في الصورة التي يعرفونها.mp3","categories":["شروح الحديث","الأسماء والصفات"]},{"id":4142,"question":"المراد -بارك الله فيكم- أنه بفعلهما أو بإهمالهما له وعدم توجيهه للإسلام يُنصِّرانه ويُمجِّسانه؟","title":"ما معنى أن أبويه \"يُنصِّرانه ويُمجِّسانه\"؟","answer":"الجواب: كله داخلٌ: توجيههم، وإذا أهملاه وصار على ما هم عليه.","link":"https://binbaz.org.sa/fatwas/24389/ما-معنى-ان-ابويه-ينصرانه-ويمجسانه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المراد بقوله يُنصِّرانه ويُمجِّسانه.mp3","categories":["شروح الحديث"]},{"id":4143,"question":"قول (حذيفة): إن كنتُ لأرى الشيء قد نسيتُه فأعرفه؟","title":"معنى قول حذيفة: إنْ كنتُ أرى الشيء نسيتُه...","answer":"الجواب: من الخطبة، يقول أنه خطبهم ﷺ خطبةً عظيمةً طوَّل فيها، حتى دخل أهلُ الجنة منازلهم، وأهل النار منازلهم، يعني: أخبر ما يكون في مستقبل الزمان مما أوحى الله إليه، وعلم هذا من علمه، وجهله مَن جهله، ونسيه مَن نسيه.  يقول أنه تحدث بعض الأشياء أذكرها في خطبة النبي ﷺ كما يذكر الإنسانُ الشخصَ الذي رآه سابقًا ثم غاب عنه، نسيه ثم يراه، فإذا رآه عرفه وذكر أنه صاحبه الذي رآه سابقًا.","link":"https://binbaz.org.sa/fatwas/24390/معنى-قول-حذيفة-ان-كنت-ارى-الشيء-نسيته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى قوله وإن كنتُ لأرى الشيء قد نسيتُه فأعرفه.mp3","categories":["شروح الحديث"]},{"id":4144,"question":"إن الله ليؤيد هذا الدين بالرجل الفاجر؟","title":"معنى \"إن الله ليؤيد هذا الدين بالرجل الفاجر\"","answer":"الجواب: كذلك فيه دلالة على أنَّ الحقَّ قد يُؤيَّد برجلٍ فاجرٍ لأسبابٍ: إما لريائه، أو لينصر قومه، أو لينصر وطنه، أو لغير هذا، لم يقصد الدين، وقد يقصد الدين، ويُؤيد الدين، لكن لغرضٍ آخر غير الإخلاص لله وطلب الثواب من الله ، بل لأسبابٍ أخرى، فكم من مُقاتلٍ، وكم من مجاهدٍ، وكم من يرائي نفع الله به في الإسلام، وهو ليس من أهل الخير، وهذا الواقع شاهد بذلك.","link":"https://binbaz.org.sa/fatwas/24391/معنى-ان-الله-ليويد-هذا-الدين-بالرجل-الفاجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تأييد الحق بالرجل الفاجر.mp3","categories":["شروح الحديث"]},{"id":4149,"question":"بطانة تأمره بالشرِّ؟","title":"ما معنى \"بطانة تأمره بالشرِّ..\" في الحديث؟","answer":"الجواب: هذا ظاهر الحديث، لكن الله يحفظهم، والمعصوم مَن عصمه الله.\nس: تأمره صراحةً؟\nج: قد يكون صراحةً، وقد يكون إشارةً، على حسب ما يعنّ لهم، قد يكون بالصراحة إذا كان في الأمر خفاء، وقد يكون بالطرق الأخرى المعوجة.\nس: هذا خاصٌّ بالأمراء؟\nج: عام، جاء في النص الآخر في الصحيح: ما بعث الله من نبيٍّ ولا استخلف من خليفةٍ....\nس: يعني: خاص بالأمراء ومَن يتولى شيئًا؟\nج: نعم، لكن المعنى مطلوب كذلك، مثلما جاء في الجليس الصالح وجليس السوء، المعنى: إذا كان في الأمراء والملوك والزعماء فكذلك الآخرون ينبغي أن يحذروا أيضًا، فكل له ما يخصُّه.","link":"https://binbaz.org.sa/fatwas/24399/ما-معنى-بطانة-تامره-بالشر-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/شرح حديث ما استخلف خليفة إلّا له بطانتان بطانة تأمره بالخير.mp3","categories":["شروح الحديث"]},{"id":4151,"question":"اللعن: الطرد من رحمة الله؟","title":"هل اللعن يعني الطرد من رحمة الله؟","answer":"الجواب: جنس اللعن، لكن ما هو... السبّ والشتم والذم والدعاء، يُسمَّى: لعنًا، إذا قال: أخزاك الله، قبَّحك الله، أو أن فلانًا قبيح، أو أن فلانًا يعصي الله، أو فلانًا كذا وكذا، فقد لعنه، يعني: ذمَّه.","link":"https://binbaz.org.sa/fatwas/24401/هل-اللعن-يعني-الطرد-من-رحمة-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل اللعن الطرد من رحمة الله مطلقًا.mp3","categories":["شروح الحديث"]},{"id":4153,"question":"التقدير بأربعين سنة (في حديث أتلومني على أمر قدّره الله عليّ قبل أن يخلقني بأربعين سنة)؟","title":"معنى التقدير بأربعين في حديث آدم وموسى","answer":"الجواب: هذا تقدير خاصٌّ، غير التَّقدير العام.\nس: تقدير خاص بآدم فقط؟\nج: نعم، يعني: نوع إيضاحٍ، مثل: التقدير العمري -العمري في بطن أمه- هذا تقدير خاص، غير التقدير العام: كالتفصيل من القدر العام، وهكذا التقدير السنوي في ليلة القدر تفصيل من القدر السابق.  أنواع القدر أقسام: القدر السابق، والتقدير العمري، والتقدير الذي كتبه الله على آدم..... قبل خلقه بأربعين سنة، تفصيل من القدر السابق، التقدير السنوي الذي يكون في ليلة القدر، التقدير اليومي، كل هذه أنواع من القدر السابق، وتفصيل من القدر السابق، وكلها ترجع إلى القدر السابق.\nس: عفا الله عنك ياشيخ، هنا صاحب المعصية إذا احتج بهذا الحديث فقال إن هذا مكتوب عليّ..؟\nج: لا حجَّة له في ذلك إذا كان ليس من فعله، أما كونه يُلام على الزنا، يُلام على قطيعة الرحم، يُلام على العقوق، يُلام حتى يتوب، فإذا تاب وجب الكفُّ عنه.","link":"https://binbaz.org.sa/fatwas/24403/معنى-التقدير-باربعين-في-حديث-ادم-وموسى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/التقدير بأربعين سنة في حديث أتلومني على أمر قدّره الله عليّ قبل أن يخلقني بأربعين سنة.mp3","categories":["شروح الحديث"]},{"id":4158,"question":"س: يجوز أن يسأل الإمارة؟","title":"هل يجوز سؤال الإمارة؟","answer":"الجواب: الإمارة مثلما سمعت الحديث، لا ينبغي سؤالها إلا إذا اقتضت المصلحةُ ذلك، الأصل أنه لا ينبغي سؤالها؛ لأنها خطر، الإمارة والقضاء ونحو ذلك من الأمور التي يترتب عليها أمانات وحقوق للناس، لكن إذا بُلي بها أعانه الله عليها، إذا بُلي بها ولم يطلبها أعانه الله عليها، ولهذا قال النبيُّ لعبدالرحمن: إنَّك إن أُعطيتها عن مسألةٍ وُكِلْتَ إليها يعني: حري ألا يُوفق عليها إذا أخذها عن مسألةٍ. أما إذا أخذها عن إلزامٍ له ولم يطلبها فهو حريٌّ بالإعانة والتوفيق. لكن إذا اقتضت المصلحةُ أن يطلبها فقد قرر المحققون من أهل العلم جواز ذلك للمصلحة، إذا رأى المصلحة للمسلمين والخير للمسلمين في أن يطلبها؛ لأنه يرى نفسه أهلًا لها، ويرى أن الأمور ضائعة، وأن الذين فيها ليسوا أهلًا لها، أو أنها متروكة هذه المسألة أو هذه الوظيفة فلا بأس أن يسألها للمصلحة، واحتجُّوا على هذا بقصة يوسف؛ أن الله ذكرها وأقرَّها: قَالَ اجْعَلْنِي عَلَى خَزَائِنِ الْأَرْضِ إِنِّي حَفِيظٌ عَلِيمٌ [يوسف:55] يعني: يجعله على المالية، وزيرًا للمالية، ثم تولى الملك بعد ذلك، فهو طلب هذا لمصلحة المسلمين؛ حتى يصرف الأموال على الوجه المرضي.\nوكذلك قصة عثمان بن أبي العاص الثقفي حين قال لرسول الله: اجعلني إمام قومي، قال: أنت إمامهم واقتدِ بأضعفهم، فلم يُنكر عليه ذلك؛ لأنَّ عثمان رأى المصلحة في ذلك، رأى المصلحة في أن يكون وليًّا لأهل الطائف؛ ليُصلح شُؤونهم، ويقوم على أمرهم.\nفإذا كان الإنسانُ في قريةٍ أو في قبيلةٍ ويرى أن غيره لا يقوم بالواجب، وأن الواجب عليه متعين أن يقوم بالواجب هو، وقال لولي الأمر: اجعلني عليهم؛ ليتولى مصالحهم، وينظر في أمورهم، فليس قصده الدنيا، ولا الرغبة فيما عند الناس، وإنما قصده وجه الله والدار الآخرة، ليس قصده إلا الإصلاح؛ هذا مأجور، ولا حرج، يُرجى أن يُعان لصلاح نيته، وللأسباب التي حملته على ذلك، فهذا شيء مخصوص، هذا شيء مُستثنى.\nس: الإمارة تشمل الإدارة؟\nج: حتى ولو على اثنين.\nس: إدارة المدارس؟\nج: عام، وإن سمّوها إدارةً هي إمارة.\nس: له أن يسأل القضاء؟\nج: من هذا الباب إذا رأى المصلحة الشرعية.\nس: النهي عن سؤال الإمارة؟\nج: الأصل في النهي التحريم.","link":"https://binbaz.org.sa/fatwas/24409/هل-يجوز-سوال-الامارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الإمارة وحكم سؤالها، ومتى يجوز سؤال الإمارة.mp3","categories":["شروح الحديث"]},{"id":4166,"question":"هل يُعتبر معصيةً الحلف ألا يُنفق عليه؟","title":"ما توجيه حَلِف الصِّدّيق ألا ينفق على مِسْطَح؟","answer":"الجواب: الذي يظهر منه أنه لما أظهر الدَّعوة الخبيثة ورمى عائشة بما رماها به صار فاسقًا، ليس أهلًا لأن يُحسن إليه، لكن كان يمكن أن يُؤمر بالعمل والكسب، وهو شابٌّ، فهو من باب الإحسان، من باب الصلة التي لا تلزم الصديق؛ لأن مسطحًا أولًا بعيد، وثانيًا بالإمكان أن يعمل ويكتسب، ولها أسباب أخرى، ما هناك دليلٌ على وجوب النَّفقة على الصدّيق، إنما هو من باب التَّكرم، من باب الإحسان، فلما سمع ما قال منه قطعها عنه، فلما نزلت الآيةُ ردَّها إليه، وليست صلة الرحم كلها واجبة، فيها الواجب، وفيها المستحبّ.","link":"https://binbaz.org.sa/fatwas/24420/ما-توجيه-حلف-الصديق-الا-ينفق-على-مسطح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حلف الصديق على ألا ينفق على مسطح.mp3","categories":["شروح الحديث"]},{"id":4169,"question":"الإيلاء خاصٌّ وإلا عام؟","title":"هل يجوز للمسلم الإيلاء من زوجته؟","answer":"الجواب: آلى من زوجاته.\nس: يجوز للمُسلم؟\nج: يجوز إذا رأى المصلحة في ذلك، لكن لا يجعله أربعة أشهر، لا يزيد على أربعة أشهر كما قال تعالى: لِلَّذِينَ يُؤْلُونَ مِنْ نِسَائِهِمْ تَرَبُّصُ أَرْبَعَةِ أَشْهُرٍ [البقرة:226]، أربعة أشهر فأقل يجوز إذا رأى المصلحة في ذلك.","link":"https://binbaz.org.sa/fatwas/24423/هل-يجوز-للمسلم-الايلاء-من-زوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجوز للمسلم أن يولي عن زوجته.mp3","categories":["شروح الحديث","الإيلاء"]},{"id":4175,"question":"س: المراد بـ لا يمل..؟","title":"معنى \"لا يمل حتى تملّوا\" في الحديث","answer":"الجواب: كسائر الصفات؛ صفة تليق بالله، قد يكون من ثمراتها قطع الثواب كما قال السلف..... أن الله يُحب نشاطهم في الأعمال حتى يملُّوا، فإذا ملُّوا ينبغي لهم أن يستريحوا حتى لا يملُّوا العبادة، يكلفون ما يُطيقون.  فالملل الذي نُسب إليه غير الملل الذي يُنسب إلينا، مللنا نقص، والملل الذي نُسب إليه سبحانه ملل ليس فيه نقص؛ كالمكر والخداع والكيد، كلها تليق بالله، ليس فيها نقص، تليق بالله  وتُناسبه على وجهٍ لا يُشابه فيه خلقه .","link":"https://binbaz.org.sa/fatwas/24431/معنى-لا-يمل-حتى-تملوا-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الملل في حديث فإن الله لا يمل حتى تملّوا..mp3","categories":["شروح الحديث","الأسماء والصفات"]},{"id":4176,"question":"قوله: من ذهب أو فضة؟","title":"هل صح اتخاذ النبي ﷺ خاتمًا من ذهب؟","answer":"الجواب: شكٌّ من الراوي، والصواب: من ذهبٍ، هذا المحفوظ، اتَّخذه من ذهبٍ، ثم طرحه، واتَّخذ خاتمًا من فضَّةٍ.\nوكان رواه مسلم في \"الصحيح\" أنه ربما لبسه في اليمين، وربما لبسه في اليسار عليه الصلاة والسلام، فيدل هذا على أنَّ الأفضل أن يكون فصُّه من الداخل، ويُشبه هذا الساعة؛ فإنها من جنس هذا، لا بأس أن تكون في اليمين، ولا بأس أن تكون في اليسار؛ لأنها لحاجةٍ مثل الخاتم.","link":"https://binbaz.org.sa/fatwas/24432/هل-صح-اتخاذ-النبي-ﷺ-خاتما-من-ذهب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث أن رسول الله اتخذ خاتما من ذهب أو فضّة..mp3","categories":["شروح الحديث","اللباس والزينة"]},{"id":4179,"question":"وتيماء تكون من خارج الجزيرة، لما أجلاهم عمر إلى تيماء؟","title":"هل كانت تيماء من الجزيرة زمن إجلاء اليهود؟","answer":"الجواب: يظهر أنها تابعة للشام وهذه من تبع المملكة تيماء وتبوك، ولكن ظاهر الإجلاء لهم إلى تيماء أنها تابعة في ذلك الوقت للشام وكانت في حدود الشام ذاك الوقت ما بعد فتحت، أما الآن فهي تبع الجزيرة.\nالطالب: المحشي قال: هما ممدوتان وهما قريتان معروفتان وفي هذا دليل على أن مراد النبي ﷺ بإخراج اليهود والنصارى من جزيرة العرب إخراجهم من بعضها وهو الحجاز خاصة؛ لأن تيماء من جزيرة العرب لكنها ليست من الحجاز.\nالشيخ: لا، الصواب الجزيرة كلها، الحجاز بعضها، نعم.\nس: لكن خيبر تكون من الجزيرة؟\nالشيخ: نعم خيبر من بطن الجزيرة. ومن الحجاز.\nس: كيف نجمع بينها وبين أمر النبي بإخراجهم من جزيرة العرب؟ \nالشيخ: أخرجهم عمر بعد ذلك.\nالطالب: ذكر القاضي عياض قال: وأريحاء وتيماء قريتان بالشام؟\nالشيخ: على حسب اجتهاده.","link":"https://binbaz.org.sa/fatwas/24436/هل-كانت-تيماء-من-الجزيرة-زمن-اجلاء-اليهود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أجلى عمر بن الخطاب اليهود والنّصارى من أرض الحجاز إلى تيمة.mp3","categories":["شروح الحديث","التاريخ والسيرة"]},{"id":4194,"question":"مراجعة عمر يا شيخ (في آية الكلالة)؟","title":"لماذا كانت مراجعة عمر في آية الكلالة؟","answer":"الجواب: أشكلت عليه، الرجل العظيم قد يخفى عليه بعض الشيء. وفي هذا فائدة: أن الإنسان لا يستحي إذا خفي عليه بعض الشيء، ولا يستحي يسأل، ولا يقول أنا كبير أستحي، لا ـ يسأل، عمر سأل عن هذه المسألة كرر وألح فيها مع وضوحها؛ لأنه لم ينشرح صدره لمعناها، ما اتضح له الأمر حتى كرر، فالإنسان قد يكون عظيمًا وكبيرًا وعالمًا ولكن يخفى عليه بعض المسائل.\nس: طعن النبي له غضب؟\nالشيخ: ما هو بالظاهر، لا، من باب المداعبة.","link":"https://binbaz.org.sa/fatwas/24451/لماذا-كانت-مراجعة-عمر-في-اية-الكلالة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مراجعة عمر بن الخطاب في آية الكلالة.mp3","categories":["شروح الحديث","التفسير"]},{"id":4203,"question":"الرحمة فيها مخلوقة... والتسعة والتسعين غير مخلوقة؟","title":"هل الرحمة منها مخلوقة وغير مخلوقة؟","answer":"الجواب: كل المائة مخلوقة \"إن الله خلق مائة رحمة\"، لكن الوصف القائم بالله غير مخلوق، وهو وصفه ، أما هذه فرحمة خارجية.","link":"https://binbaz.org.sa/fatwas/24464/هل-الرحمة-منها-مخلوقة-وغير-مخلوقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إن الله خلق مائة رحمة... كل المائة مخلوقة.mp3","categories":["شروح الحديث","الأسماء والصفات"]},{"id":4204,"question":"قوله \"لم يعمل حسنة قط\" يعني مع التوحيد..؟","title":"معنى ما جاء في الحديث \"لم يعمل حسنة قط..\"","answer":"الجواب: لا بد، هذا غير التوحيد، مثل ما قال :... يخرجون من النار بعدما يشفع الشفعاء، يخرج الله قومًا من النار لم يفعلوا خيرًا قط، يعني إلا التوحيد، يخرجهم الله بغير شفاعة من النار بعدما يمتحشون فيها ويعذبون..... يخرجون من النار، قال في رواية في الصحيح: لم يفعلوا خيرًا قط، وزاد في رواية: إلا أنهم يقولون لا إله إلا الله، وفي رواية: إلا أنهم موحدون.  قد أجمع العلماء قاطبة على أن من مات على الشرك وهو غير معذور ليس من أهل الفترات ولم يعذر، أنه مخلد في النار ولا يخرج منها. وإنما البحث والخلاف بينهم وبين المعتزلة والخوارج في العصاة، فأهل السنة والجماعة يقولون إن العصاة يخرجون ولا يعذبون عذابًا دائمًا أبدًا، بل لهم نهاية، فالعصاة لهم نهاية، وإن وصف بعض عذابهم بالخلود فهو خلود له نهاية، خلود مؤقت مثل خلود الزاني والقاتل وقاتل نفسه، لكن هذا له نهاية. أما خلود الكفار فليس له نهاية، خلودهم مستمر, نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/24465/معنى-ما-جاء-في-الحديث-لم-يعمل-حسنة-قط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في الخروج من النار، والخلود فيها.mp3","categories":["شروح الحديث","اليوم الآخر"]},{"id":4207,"question":"الحديث ما هو مفسر للغيرة غيرة الله...","title":"معنى \"وغيرة الله أن يأتي المؤمن ما حرم عليه\"","answer":"الجواب: يعني: غيرته عليه، يعني إنكاره عليه وبغضه لعمله، غيرته وصف خاص يليق بالله لا يشبه صفات المخلوقين..... إنكاره على عبده إذا انتهك محارمه، وكراهته لعمله، ونهيه إياه، وهكذا البغض، وهكذا الإنكار والنهي، كله مقتضى منع الناس من هذه الأشياء.\nس: النووي ما زاد على هذا؟\nالشيخ: الغيرة وصف خاص.\nس: فسرها بقوله في الحديث\nالشيخ: يريد بأن الغيرة المنع، ولكن هذا غير المنع... مقتضاها المنع، الغيرة وصف لله لائق بالله..... بمعنى البغضاء والكراهة، وقريب من هذا المعنى، هو الإنكار وليس المنع.","link":"https://binbaz.org.sa/fatwas/24469/معنى-وغيرة-الله-ان-ياتي-المومن-ما-حرم-عليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى حديث وغيرة الله أن يأتي المؤمن ما حرم عليه..mp3","categories":["شروح الحديث"]},{"id":4210,"question":"الكنف؟","title":"معنى حديث \"حتّى يضع عليه كنفه..\"","answer":"الجواب: الله أعلم، ... كما قال، كما جاء في الحديث، لا يعلم كيفيته إلا هو ، وقال بعضهم: هو سترة، ولهذا قال: سترتها عليك. والله أعلم، مثل هذا مثل سائر الصفات، فالأوْلى أن يقال: الله أعلم بمراده، يُروى كما جاء على الوجه الذي يليق بالله .","link":"https://binbaz.org.sa/fatwas/24473/معنى-حديث-حتى-يضع-عليه-كنفه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى الكنف، في حديث..حتّى يضع عليه كنفه...mp3","categories":["شروح الحديث","الأسماء والصفات"]},{"id":4213,"question":"يؤخذ من هذا الحديث - إنّه ليأتي الرجل العظيم السّمين يوم القيامة، لا يزن عند الله جناح بعوضة- أنهم يبعثون يوم القيامة على أوزانهم وأطوالهم؟","title":"كيف تكون أعمار وأطوال الناس يوم القيامة؟","answer":"الجواب: يختلف بعض  الناس في هذا فيما يتعلق بالكفرة.  أما أهل الجنة فهم في سِنٍّ واحدة، وفي طول واحد ستين ذراعًا.  وأما أهل النار فهم يختلفون، بعضهم سِنُّه كأُحُد، السن فقط، يُعَظَّمون في جهنم، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/24477/كيف-تكون-اعمار-واطوال-الناس-يوم-القيامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/شرح حديث إنه ليأتي الرجل العظيم السّمين يوم القيامة.mp3","categories":["شروح الحديث"]},{"id":4218,"question":"شجرة الأرز المعروفة الآن؟","title":"ما الأرزة في حديث \"ومثل الكافر مثل الأرزة\"؟","answer":"الجواب: الأرزة شجرة، وأما المأكول هذا أرز هذا زرع.  الأرزة هذه تشبه الصنوبر كما قال، شجرة عظيمة طويلة قوية ضخمة صلبة تكون في الشام... موجودة في لبنان كما ذكروا، معروفة عندهم، وموجودة في دمشق.","link":"https://binbaz.org.sa/fatwas/24483/ما-الارزة-في-حديث-ومثل-الكافر-مثل-الارزة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بالأرزة في حديث ومثل الكافر مثل الأرزة..mp3","categories":["شروح الحديث"]},{"id":4220,"question":"راغبة في الصدقة أو في الإسلام؟","title":"معنى حديث \"إن أمي قدمت عليّ وهي راغبة..\"","answer":"الجواب: لا، في الصدقة، في المساعدة يعني.","link":"https://binbaz.org.sa/fatwas/24487/معنى-حديث-ان-امي-قدمت-علي-وهي-راغبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى راغبة في حديث يا رسول الله إن أمي قدمت عليّ وهي راغبة..mp3","categories":["شروح الحديث"]},{"id":4227,"question":"من استرقى هل يخرج من الحديث؟","title":"هل يخرج من استرقى من فضل السبعين ألفا؟","answer":"الجواب: لا لا، السبعين الألف زاده الله مع كل سبعين ألفًا، لا يخرج منهم؛ لأن العمدة في هذا ترك ما حرم الله وأداء ما أوجب الله، لكن هذا من الكمال ولا يخرج بذلك من السبعين، لو استرقى للحاجة أو اكتوى للحاجة؛ لأن هذا من كمالهم.","link":"https://binbaz.org.sa/fatwas/24494/هل-يخرج-من-استرقى-من-فضل-السبعين-الفا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث هم الذين لا يَسْتَرقون.. هل يخرج من الحديث من استرقى.mp3","categories":["شروح الحديث"]},{"id":4228,"question":"السبب في عدم قراءة النبي ﷺ على أم المؤمنين عائشة وأمره لها بالاسترقاء؟","title":"ما سبب أمر النبي ﷺ لعائشة بالاسترقاء؟","answer":"الجواب: كأنه للحاجة، احتاجت للاسترقاء فأمرها أن تسترقي، وهكذا أم أولاد جعفر أسماء بنت عميس أمرها أن تسترقي لأولاد جعفر. س: يعني لم يقرأ عليها هو ﷺ؟ ج: لعله شغل عن ذلك، أو لأسباب أخرى.","link":"https://binbaz.org.sa/fatwas/24495/ما-سبب-امر-النبي-ﷺ-لعاىشة-بالاسترقاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/سبب أمر النبي لأم المؤمنين عائشة بالاسترقاء.mp3","categories":["الطب والتداوي","شروح الحديث"]},{"id":4230,"question":"أمثلة الحاجات التي يجوز للإنسان أن يكتوي فيها أو يسترقي فيها؟","title":"ما الأحوال التي يجوز فيها الاسترقاء والاكتواء؟","answer":"الجواب: الأمراض التي تصيب الإنسان، أقول أنواع الأمراض.","link":"https://binbaz.org.sa/fatwas/24497/ما-الاحوال-التي-يجوز-فيها-الاسترقاء-والاكتواء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما هي الأمور التي يجوز للإنسان أن يكتوي فيها.mp3","categories":["الطب والتداوي","شروح الحديث"]},{"id":4231,"question":"ما الحكمة لما سأله السائل وقال ﷺ: سبقك بها عكاشة","title":"الحكمة من قول النبي ﷺ \"سبقك بها عكاشة\"","answer":"الجواب: هذا لسد الباب؛ حتى لا ينجر الباب إلى أناس ليسوا بأهل فيقال لست منهم فيُفتضح.","link":"https://binbaz.org.sa/fatwas/24498/الحكمة-من-قول-النبي-ﷺ-سبقك-بها-عكاشة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكمة من قول النبي سبق بها عكاشة.mp3","categories":["شروح الحديث"]},{"id":4232,"question":"يقول الشيخ عبدالرحمن في قوله: ولا يكتوون أي لا يسألون غيرهم أن يكويهم؟","title":"معنى \"ولا يكتوون..\" في الحديث","answer":"الجواب: لا لا، ولا يكتون مطلقًا ولو بغير سؤال، هذا غلط.\nس: لكن قوله: كما لا يسألون غيرهم أن يرقيهم استسلامًا للقضاء وتلذذًا .. هل ورد في هذا حديث؟\nج: ما أخْبُر شيئًا، لكن أسباب جائزة، الله أمر بالأسباب لكن الكي نوع تعذيب، يستغنى عنه إذا تيسر ما يغني عن الكي؛ لأنه نوع من التعذيب، فإذا دعت الحاجة إليه فلا بأس. والاسترقاء نوع من الحاجة إلى الناس، ترك الحاجة إليه إذا تيسر أوْلى.","link":"https://binbaz.org.sa/fatwas/24499/معنى-ولا-يكتوون-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى قوله لا يسترقون، ولا يكتوون... في الحديث.mp3","categories":["شروح الحديث"]},{"id":4249,"question":"قوله: ما زادتك إلا وهنًا بعض الناس يستدل بهذا على أنها صحيًّا تضر؟","title":"معنى \"ما زادتك إلا وهنًا..\" في الحديث","answer":"الجواب: يعني التعلق بغير الله يزيده ضعفًا ويزيده بلاء، وقد يُملى عليه كما قال الله جل وعلا: وَلَا تَحْسَبَنَّ اللَّهَ غَافِلًا عَمَّا يَعْمَلُ الظَّالِمُونَ إِنَّمَا يُؤَخِّرُهُمْ لِيَوْمٍ تَشْخَصُ فِيهِ الْأَبْصَارُ [إبراهيم:42] ويقول جل وعلا: سَنَسْتَدْرِجُهُمْ مِنْ حَيْثُ لَا يَعْلَمُونَ [القلم:44] وَأُمْلِي لَهُمْ إِنَّ كَيْدِي مَتِينٌ [القلم:45] قد يُملى له، وقد تضره عاجلا، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/24519/معنى-ما-زادتك-الا-وهنا-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بقوله في الحديث ما زادتك إلا وهنا..mp3","categories":["شروح الحديث","نواقض الإسلام"]},{"id":4267,"question":"صحة حديث: أيما امرئ جلس على مائدة خمر.","title":"معنى حديث \"أيما امرئٍ جلس على مائدة خمر\"","answer":"الجواب: لا بأس به... فيه وعيد، المقصود التحذير من كونه يجلس معهم؛ لأن هذا نوع مشاركة.\nس: للتحريم؟\nج: ما في شك، لفظه: من كان يؤمن بالله واليوم الآخر فلا يجلس على مائدة يدار عليها الخمر.\nس: لكن لأجل هذه الضرورة لا بأس؟\nج: للدعوة بس، إذا ما تيسر إلا في هذا الوقت للدعوة ما هو لأجل الجلوس على المائدة.\nس: يكون كالميتة؟\nج: إذا تيسر هذا لا يأكل معهم، ولا يشرب معهم، ولكن يدعوهم إلى الله وينصرف، إذا لم يتيسر إلا هذا الوقت.","link":"https://binbaz.org.sa/fatwas/24537/معنى-حديث-ايما-امرى-جلس-على-ماىدة-خمر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم على حديث أيما امرئ جلس على مائدة خمر..mp3","categories":["شروح الحديث","الحكم على الأحاديث"]},{"id":4272,"question":"ما المقصود بأذناب البقر في هذا الحديث الذي يرويه ابن عمر أن النبي ﷺ قال: إذا ضن الناس بالدينار والدرهم وتبايعوا بالعينة واتبعوا أذناب البقر.","title":"المقصود بـ \"أذناب البقر\" في الحديث","answer":"الجواب: يعني في الحرث، في الزراعة، اشتغلوا بالزراعة وضيّعوا الجهاد؛ لأن الناس من أول يزرعون على البقر، وبعضهم على الإبل، الغالب على الناس البقر قبل أن تجيء المكائن.\nس: يعني انشغال الناس  بالزراعة؟\nج: يعني اشتغالهم بالزراعة عن الجهاد.","link":"https://binbaz.org.sa/fatwas/24542/المقصود-بـ-اذناب-البقر-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بأذناب البقر في الحديث.mp3","categories":["شروح الحديث"]},{"id":4282,"question":"كيف نجمع بين الأدلة التي تأمر بذكر محاسن الموتى، والأدلة التي تنهى عن النعي؟","title":"ما هو \"النعي\" المنهي عنه؟","answer":"الجواب: النعي: رفع الصوت بالنياحة، هذا النعي، النعي هو أن ينعى الميت إذا مات، يرفع صوته بالنعي أو يطوف بالقبائل يقول: مات فلان، كعادة الجاهلية.  أما البكاء من غير نعي فهذا لا بأس به، ما يسمى نياحة ولا يسمي \"نعي\"، البكاء العادي مثل ما بكى النبي ﷺ على بنته، وبكى على ولد بنته عليه الصلاة والسلام، وقال: إن الله لا يعذب بدمع العين ولا بحزن القلب؛ ولكن يعذب بهذا أو يرحم، وأشار إلى لسانه، وقال ﷺ لما مات ابنه إبراهيم: العين تدمع والقلب يحزن ولا نقول إلا ما يرضي الرب، وإنا بفراقك يا إبراهيم لمحزونون، هذه من طبيعة الناس، ولما زار بنتًا له وابنها في الاحتضار نفسه تقعقع عند الخروج بكى ﷺ، فقال له بعض الحاضرين سعد بن عبادة ومن معه: ما هذا يا رسول الله؟ قال: إنها رحمة، وإنما يرحم الله من عباده الرحماء.","link":"https://binbaz.org.sa/fatwas/24552/ما-هو-النعي-المنهي-عنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الجمع بين الأدلة التي تأمر بذكر محاسن الموتى، والنهي عن النعي.mp3","categories":["شروح الحديث"]},{"id":4285,"question":"من أتى كاهنا أو عرافا نفس الذي يسأل؟","title":"حكم من أتى أو سأل كاهنًا أو عرافًا","answer":"الجواب: فقد كفر بما أنزل على محمد إذا صدقه في علم الغيب، أما إن كان عامي أتاه ما يدري؛ هذا يُعَلّم أن هذا لا يجوز، ولا يلحقه الكفر، أما إذا صدقه بعلم الغيب أنه يعلم الغيب.\nس: الذي يعلم الحكم ويذهب ليسأل عن الضائع؟\nج: ما يجوز، لا يجوز إتيانه؛ لأن الرسول قال لا تأتوهم ولا تسألوهم، نهى عن إتيانهم وعن سؤالهم.\nس: يعني يدخل تحت؟\nج: تحت الوعيد.","link":"https://binbaz.org.sa/fatwas/24556/حكم-من-اتى-او-سال-كاهنا-او-عرافا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من المقصود بحديث من أتى كاهنا أو عرافا.mp3","categories":["شروح الحديث","السحر والكهانة"]},{"id":4287,"question":"ما المقصود بأن الذي يشرب الخمر أنه لا تقبل صلاته أربعين يومًا، وهل يترك الصلاة؟","title":"ما معنى عدم قبول صلاة شارب الخمر؟","answer":"الجواب: لا، لا يتركها، لكن يفوته ثوابها، مثل من أتى عرافًا فسأله عن شيء لم تُقبل له صلاة أربعين ليلة، تجزئه ويفوته ثوابها. أما إذا ترك الصلاة كَفَر، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/24559/ما-معنى-عدم-قبول-صلاة-شارب-الخمر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بأن الذي يشرب الخمر أنه لا تقبل صلاته أربعين يوما.mp3","categories":["شروح الحديث","حكم الصلاة وأهميتها"]},{"id":4297,"question":"قوله في المسائل: الشاهد لكون الأعمال بالخواتيم؛ لأنه لو قالها لنفعته؟","title":"معنى \"الأعمال بالخواتيم\"","answer":"الجواب: نعم، شاهد، لو أسلم عند موته قال: لا إله إلا الله؛ نفعته فالأعمال بالخواتيم، وقد يكون مسلمًا ثم يكفر عند الموت، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/24570/معنى-الاعمال-بالخواتيم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الأعمال بالخواتيم.mp3","categories":["شروح الحديث","مسائل متفرقة في العقيدة"]},{"id":4299,"question":"معنى أنها تقبل التوبة ما لم يغرغر؟","title":"معنى \"تقبل التوبة ما لم يغرغر\"","answer":"الجواب: يعني ما لم تبلغ الروح الغرغرة عند خروجها إذا عاين ملك الموت.\nس: قول فرعون آمَنتُ أَنَّهُ لَا إِلَـٰهَ إِلَّا الَّذِي آمَنَتْ بِهِ بَنُو إِسْرَائِيلَ؟\nج: هذا ما نفعه إيمانه؛ لأنه نزل البلاء، قال تعالى: فَلَمَّا رَأَوْا بَأْسَنَا قَالُوا آمَنَّا بِاللَّهِ وَحْدَهُ وَكَفَرْنَا بِمَا كُنَّا بِهِ مُشْرِكِينَ  ۝  فَلَمْ يَكُ يَنْفَعُهُمْ إِيمَانُهُمْ لَمَّا رَأَوْا بَأْسَنَا  [غافر:85] إذا نزلت العقوبة ماعاد ينفع، لما حلّت العقوبة في ثمود ما نفعتهم التوبة، أو في عاد ما نفعتهم التوبة، إنما التوبة قبل ذلك.\nس: مثل فرعون؟\nج: الله بس أخرج لهم جسده لينظروا أنه مات حتى لا يسوِّل لهم الشيطان أنه حي في المحل الفلاني، حتى يشاهدوا جسده؛ لأنه في نفوسهم عظيم هو إلههم.","link":"https://binbaz.org.sa/fatwas/24572/معنى-تقبل-التوبة-ما-لم-يغرغر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى تقبل التوبة ما لم يغرغر.mp3","categories":["شروح الحديث"]},{"id":4321,"question":"قوله ﷺ: وتبسمك في وجه أخيك صدقة، هل هذا يدل على أنه لا يبتسم في وجه المشرك ولا الكافر؟","title":"حكم التبسم في وجه الكافر للدعوة","answer":"الجواب: المشرك ينبغي فيه الغلظة والكراهة وإظهار البراءة، أما المودة فبين المسلمين والابتسام والتعاون، فهذا بين المسلمين، أما مع الكفار فالكراهة والبغضاء والعداوة إلا عند رجاء المصلحة؛ كونه يؤلف قلوبهم يدعوهم إلى الله، هذا لا بأس.\nس: هل يبتسم في وجهه لدعوته إلى دين الله لا بأس؟\nج: ما في بأس، ما في بأس للدعوة إلى الله إذا رأى مصلحة في ذلك.","link":"https://binbaz.org.sa/fatwas/24596/حكم-التبسم-في-وجه-الكافر-للدعوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث وتبسمك في وجه أخيك صدقة.. التبسم في وجه الكافر.mp3","categories":["شروح الحديث","الدعوة والدعاة"]},{"id":4322,"question":"ما المقصود: فيستبيح بيضتهم؟","title":"معنى ما جاء في الحديث \"فيستبيح بيضتهم...\"","answer":"الجواب: يعني مجتمعهم وزبدة ما عندهم من الخير.","link":"https://binbaz.org.sa/fatwas/24597/معنى-ما-جاء-في-الحديث-فيستبيح-بيضتهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بحديث فيستبيح بيضتهم...mp3","categories":["شروح الحديث"]},{"id":4324,"question":"قوله: حتى يسبي بعضهم بعضًا يدل على أنهم يكفّر بعضهم بعضًا.. التأويل؟","title":"معنى حديث \"حتى يسبي بعضهم بعضًا..\"","answer":"الجواب: قد يقع، قد يقع...، نسأل الله العافية، قد وقع أول ذلك في عهد عثمان وعلي، أول الفتنة وقعت في عهد عثمان وعلي.\nس: السبي يقع؟\nج: قد يقع... ، قد يقع، يعتقد كفره ويسبيه، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/24599/معنى-حديث-حتى-يسبي-بعضهم-بعضا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/شرح حديث حتى يسبي بعضهم بعضًا..mp3","categories":["شروح الحديث"]},{"id":4334,"question":"قول النبي ﷺ: من أتى عرافا وقوله: من أتى كاهنا يشمل هذا الساحر؟","title":"هل وعيد من أتى كاهنًا يشمل من أتى ساحرًا؟","answer":"الجواب: الساحر قد يدخل في هذا بمعنى أنه يدعي معرفة الأمور الغيبية يدخل في العرافين، أما الكاهن في الغالب المراد بالكاهن اللي يدعي علم المغيبات من طريق مسترق السمع، أما السحرة فشأنهم إما إدخال ضرر على الناس أو جمع بين الرجل والمرأة أو تفريق بينهما من طريق الشياطين، هذا عمل السحرة، أما الكهانة يدعون علم الغيب يخبرون أنه سوف يكون كذا، سوف يسافر فلان، سوف يموت فلان، سوف يهزم آل فلان، سوف يقع مصائب كذا، هذه غالب أخبار الكهنة، نسأل الله السلامة.","link":"https://binbaz.org.sa/fatwas/24609/هل-وعيد-من-اتى-كاهنا-يشمل-من-اتى-ساحرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من أتى كاهنا هل يشمل هذا الساحر.mp3","categories":["شروح الحديث","السحر والكهانة"]},{"id":4344,"question":"سوّى رجل حادثًا في طريق وكره أنه يمر بها مرة ثانية ألبتة؟","title":"حكم التشاؤم من مكان حصل فيه مكروه","answer":"الجواب: الجواب: لا، لا، ما ينبغي هذا لا، لا يتشاءم، يسأل ربه، في توكله على الله.. الخير إن شاء الله.","link":"https://binbaz.org.sa/fatwas/24619/حكم-التشاوم-من-مكان-حصل-فيه-مكروه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/التشاؤم من مكان حصل فيه مكروه.mp3","categories":["شروح الحديث","التشاؤم والتطير"]},{"id":4367,"question":"رجل صام ثم قال: دعاني رجل آخر، وبعد أن دعاني تركت دعوته، نويت أن أجيب دعوته ثم حصل ظرف ثم تركت دعوته، هل صيامي باقٍ؟","title":"حكم من نوى الفطر من صومه ولم يفعل؟","answer":"الجواب: على صيامه حتى يفطر.","link":"https://binbaz.org.sa/fatwas/24644/حكم-من-نوى-الفطر-من-صومه-ولم-يفعل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أصبح صائمًا ثم نوى الفطر، فهل يُفطر.mp3","categories":["شروح الحديث","صيام التطوع"]},{"id":4370,"question":"في آثار رويت عن عمر وعن عائشة وعن أبي طلحة عند الطبراني وعند أبي بكر الفريابي وابن سعد أنهم كانوا يسردون الصوم، وبعضهم كان يسرد الدهر كله، فعلى ماذا تُحمل هذه الروايات؟","title":"علام يُحمل سَرْدُ بعض الصحابة الصوم؟","answer":"الجواب: من يسرد خَفِي عليه الدليل، النبي ﷺ نهى عن الوصال، ونهى عن صوم الدهر، لا صام من صام الأبد ومن فعله من الصحابة فقد خفيت عليه السنة، فالسنة هي الحاكمة على الناس فَإِنْ تَنَازَعْتُمْ فِي شَيْءٍ [النساء:59] وإلا إلى زيد وعمرو، فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ [النساء:59].\nس: شهرة مثل هذا الأمر في النهي عن سرد الصوم؟\nج: على كل حال الإنسان يتحرَّى السنة، ولا عليه من زيد وعمرو، يتحرَّى السنة إذا أراد يصوم يومًا ويفطر يومًا، ويصوم الاثنين والخميس، ثلاثة أيام من كل شهر طيب، أما أن يسرد الصوم الدهر كله هذا ما له صوم، النبي ﷺ قال: لا صام ولا أفطر، لا صام من صام الأبد، نهى عن هذا عليه الصلاة والسلام، ولما طلبوا الوصال واصل بهم يومًا، ثم يومًا، ثم رأوا الهلال فقال: لو تأخر لزدتكم كالمُنَكِّل لهم حين أبَوا أن ينتهوا.","link":"https://binbaz.org.sa/fatwas/24647/علام-يحمل-سرد-بعض-الصحابة-الصوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/على ماذا تُحمل الروايات التي عن الصحابة أنهم كانوا يسردون الصوم.mp3","categories":["شروح الحديث","صيام التطوع"]},{"id":4377,"question":"في قول: فليس من الله؟","title":"معنى حديث: \"من حلف له بالله فليرض...\"","answer":"الجواب: من باب الوعيد، مثل: ليس منا من ضرب الخدود، أو شق الجيوب، أو دعا بدعوى الجاهلية.\nس: يعني ليس منا، مثل ليس من الله؟\nج: نعم من باب الوعيد.\nس: الوعيد في الدنيا وفي الآخرة؟\nج: نعم وعيد يطلق، من باب الوعيد.\nس: المقصود بالوعيد؟\nج: الوعيد يعني العقوبة.","link":"https://binbaz.org.sa/fatwas/24654/معنى-حديث-من-حلف-له-بالله-فليرض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى فليس من الله، في حديث ..ومن حُلِف له بالله فليْرض، ومن لم يرض فليس من الله.mp3","categories":["شروح الحديث"]},{"id":4387,"question":"هل تتابع صيام ست من شوال أفضل من تفرقتها؟","title":"هل التتابع أفضل في صيام ست شوال؟","answer":"الجواب: المتابعة نعم، الست إذا تابعها أفضل لأنه مسارعة في الخير.\nس: إذا صام الست مع أيام البيض ووافق الاثنين والخميس هل يأخذ الأجر؟\nالشيخ: إذا نوى الست له أجرها.\nس: مع الأيام البيض؟\nالشيخ: لا، له أجر الست التي نواها.","link":"https://binbaz.org.sa/fatwas/24664/هل-التتابع-افضل-في-صيام-ست-شوال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أيهما أفضل في صيام ست شوال التتابع أم التفريق.mp3","categories":["شروح الحديث","صيام التطوع"]},{"id":4388,"question":"البيض هل جاء في فضل صيامها حديث؟","title":"هل صيام الأيام البيض ثابت بالسنة؟","answer":"الجواب: أحاديث نعم، الثالث عشر، والرابع عشر، والخامس عشر.\nس: تحديدها بهذا من الرسول ﷺ؟\nالشيخ: نعم نعم.","link":"https://binbaz.org.sa/fatwas/24665/هل-صيام-الايام-البيض-ثابت-بالسنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل ورد حديث في فضل صيام الأيام البيض.mp3","categories":["شروح الحديث","صيام التطوع"]},{"id":4426,"question":"الإناء يُغطَّى ولو لم يكن بداخله شيء؟","title":"هل يُسنُّ تغطية الإناء ولو كان فارغا؟","answer":"الجواب: ولو ما فيه شيء يُغطَّى، أو يُكفأ؛ لأنه قد ينزل شيء يجلس فيه.","link":"https://binbaz.org.sa/fatwas/24704/هل-يسن-تغطية-الاناء-ولو-كان-فارغا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث ..غطِّ إناءك واذكر اسم الله.. هل يُغطَّى الإناء ولو لم يكن بداخله شيء.mp3","categories":["الآنية","شروح الحديث"]},{"id":4436,"question":"حديث \"خالفوهم\" ما الذي صرفها عن الوجوب؟","title":"ما حكم مخالفة اليهود والنَّصارى في الصبغ؟","answer":"الجواب: كأنه - والله أعلم - وجود البياض في عهد النبي ﷺ، فالصحابة كانوا في بعض الأحيان يتأخَّر عليهم الصبغُ أيامًا.","link":"https://binbaz.org.sa/fatwas/24714/ما-حكم-مخالفة-اليهود-والنصارى-في-الصبغ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الأمر بالمخالفة في حديث إنَّ اليهود والنَّصارى لا يصبغون، فخالفوهم.mp3","categories":["شروح الحديث"]},{"id":4437,"question":"في حديث أنسٍ: \"لم يكن شابَ إلا يسيرًا\"، وحديث أم سلمة: \"فإذا هو مخضوبٌ بالحناء والكتم\"؟","title":"الجمع بين حديثين في شيبه ﷺ وصبغه؟","answer":"الجواب: هذا يدل على أنَّ شعرات صبغها عليه الصلاة والسلام، لكن خفي على أنسٍ، والسر في ذلك أن النبي ﷺ قد يجعلها بيضاء في بعض الأحيان بسبب مشاغله عليه الصلاة والسلام، فظنَّ أنسٌ وغيره من بعض الصحابة الذين قالوا: \"ما صبغ\" بأنه خفي عليهم هذا؛ لأنَّ الشيب قليل، وفي آخر حياته قد يتخلَّف بعض الأحيان للشغل، ويبقى أبيض؛ فظنّوا أنه لم يصبغ، ومَن حفظ حُجَّة على مَن لم يحفظ.","link":"https://binbaz.org.sa/fatwas/24715/الجمع-بين-حديثين-في-شيبه-ﷺ-وصبغه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الجمع بين حديث لم يكن شابَ إلا يسيرًا، وحديث فإذا هو مخضوبٌ بالحناء والكتم.mp3","categories":["شروح الحديث"]},{"id":4467,"question":"الاستدلال بحديث عائشة: افعلي ما يفعل الحاج إلا أن تطوفي بالبيت على جواز مسّ المصحف بغير طهارة؟","title":"(افعلي ما يفعل الحاج) هل يعمّ مسّ المصحف؟","answer":"الجواب: ما هو بكفء، هذا عام مخصوص، أقول: عام مخصوص، العمومات ما تنقض الخاص، ولا تُبطل الخاص.","link":"https://binbaz.org.sa/fatwas/24745/افعلي-ما-يفعل-الحاج-هل-يعم-مس-المصحف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الاستدلال بحديث افعلي ما يفعل الحاج، إلا أن تطوفي بالبيت على جواز مسّ المصحف.mp3","categories":["الغسل","الحيض والنفاس","شروح الحديث"]},{"id":4481,"question":"نقض الشعر لغسل الحيض يجب؟","title":"حكم نقض الشعر لغسل الحيض","answer":"الجواب: لا، مُستحبٌّ فقط، ولهذا في حديث أم سلمة عند مسلم: \"أفأنقضه من الحيض؟\" قال: لا، إنما يكفيك أن تحثي.","link":"https://binbaz.org.sa/fatwas/24761/حكم-نقض-الشعر-لغسل-الحيض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم نقض الشعر لغسل الحيض.mp3","categories":["الغسل","الحيض والنفاس","شروح الحديث"]},{"id":4497,"question":"الحديث قوله: \"يبتدرون السواري\" يعني: سترةً؟","title":"معنى حديث \"يبتدرون السواري\"","answer":"الجواب: نعم، سترة يُصلون إليها يعني.\nس: يبتدرون السَّواري؟\nج: للسترة.\nس: ويتركون الصفَّ الأول؟\nج: يتقدَّمون للسواري ثم يعودون إلى أماكنهم.","link":"https://binbaz.org.sa/fatwas/24777/معنى-حديث-يبتدرون-السواري","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى حديث يبتدرون السواري.mp3","categories":["سترة المصلي","شروح الحديث"]},{"id":4528,"question":"إنَّ الله جميل؟","title":"معنى \"إنَّ الله جميل..\"","answer":"الجواب: وصف لله بالجمال، والجمال معروف ضد الدَّمامة والقباحة، فهو أجمل شيء سبحانه، وأكرم شيء، وأكمل في كل شيء سبحانه، فهو أكمل في جميع الأوصاف: من علم، وفضل، وحكمة، وحلم، وقوة، وقدرة، وعلم، وغير هذا، فله الجمال من جميع الوجوه، والكمال من كل الوجوه .","link":"https://binbaz.org.sa/fatwas/24808/معنى-ان-الله-جميل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى إنَّ الله جميل.mp3","categories":["شروح الحديث","الأسماء والصفات"]},{"id":4531,"question":"حديث البذاذة من الإيمان، ومعناه؟","title":"درجة حديث \"البذاذة من الإيمان\" ومعناه","answer":"الجواب: في غالب ظني أنه لا بأس به، إسناده حسن، لا بأس به، وهو قد يُقوي رواية سهل بن معاذ، وإن كان سهل فيه ضعف، والمحمول على مثل ما تقدم محمول على بعض الأحيان، لا أن تكون سجيةً للمؤمن.\nس: حسَّنه الشيخُ ناصر في \"الطحاوية\".\nج: نعم.","link":"https://binbaz.org.sa/fatwas/24811/درجة-حديث-البذاذة-من-الايمان-ومعناه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى حديث البذاذة من الإيمان.mp3","categories":["شروح الحديث","الحكم على الأحاديث"]},{"id":4532,"question":"لا يدخلن الجنةَ، ولا يجدن ريحها؟","title":"معنى \"لا يدخلن الجنةَ ولا يجدن ريحها\"","answer":"الجواب: هذا من باب الوعيد، مثل أحاديث الزجر: لا يدخل الجنةَ قاطعُ رحمٍ، لا يدخل الجنةَ نمَّامٌ، كل هذا من باب الزجر والوعيد، وليس معناه أنه كافر، لا.","link":"https://binbaz.org.sa/fatwas/24812/معنى-لا-يدخلن-الجنة-ولا-يجدن-ريحها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الوعيد في حديث لا يدخلن الجنةَ، ولا يجدن ريحها.mp3","categories":["شروح الحديث"]},{"id":4533,"question":"الاحتمالات التي ذُكرت في نساء كاسيات عاريات يعني: التَّشبه بالرجل، أو تفتن الرجال، هذه الاحتمالات في حديث أبي هريرة، أو في حديث أسامة: نهى أن تلبس لبسة الرجل، في حديث أبي هريرة: أن يلبس الرجلُ لبسة المرأة، والمرأة لبس الرجل؟","title":"معنى \"نساء كاسيات عاريات\"","answer":"الجواب: هذا على ظاهره، في الملابس تلبس لبسته حتى تظنّ أنها رجل أو العكس، وهذا معنى الحديث الآخر: \"لعن رسول الله المخنثين من الرجال، والمترجلات من النساء\"، قال .....: رواه البخاري رحمه الله، فالمعنى هو هذا: إما في اللباس، وإما في شيءٍ آخر من المشية أو الكلام أو نحو ذلك مما يتأسّى بهؤلاء وهؤلاء بهؤلاء، والواجب أن تمتاز هي عن الرجل، وهو يمتاز عنها في كلامه ومشيته وملابسه وغير ذلك؛ حتى لا يكون هناك اشتباه، واللبسة من ذلك، اللبسة ..... قد تتشبه به في كلامه، تتشبَّه به في المشي.","link":"https://binbaz.org.sa/fatwas/24813/معنى-نساء-كاسيات-عاريات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى نساء كاسيات عاريات.mp3","categories":["شروح الحديث"]},{"id":4535,"question":"قوله: رجال معهم سياط كأذناب البقر؟","title":"معنى \"رجال معهم سياط كأذناب البقر\"","answer":"الجواب: هذا قيل فيهم أنهم الشّرط وأشباههم، وكل مَن يأخذ السياط لظلم الناس، سواء سمّوا شرطًا أو جنودًا أو عساكر أو غير ذلك، فيه وعيدٌ لمن ظلم الناس.  أما إذا كانوا بحقٍّ؛ فلا خطرَ عليهم، لكن في الغالب أنهم قد يظلمون الناس؛ ولهذا جاء الحديثُ في ذمِّهم.","link":"https://binbaz.org.sa/fatwas/24815/معنى-رجال-معهم-سياط-كاذناب-البقر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى حديث رجال معهم سياط كأذناب البقر.mp3","categories":["شروح الحديث"]},{"id":4573,"question":"في العالمين إنك حميد مجيد...؟","title":"حكم زيادة \"في العالمين\" في التشهد","answer":"الجواب: هذه في الصلاة على النبي ﷺ، هذه ما هي في التشهد، في الصلاة على النبي ﷺ، إذا قال: \"في العالمين\" لا بأس، جاء في رواية أبي مسعود: \"اللهم صلِّ على محمدٍ وعلى آل محمدٍ كما صليتَ على آل إبراهيم، وبارك على محمدٍ وعلى آل محمدٍ كما باركتَ على آل إبراهيم في العالمين ..\".","link":"https://binbaz.org.sa/fatwas/24856/حكم-زيادة-في-العالمين-في-التشهد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/زيادة في العالمين إنك حميد مجيد في التشهد.mp3","categories":["شروح الحديث","التشهد والتسليم"]},{"id":4584,"question":"الكلب الأسود في نفسه شيطان، أو في المعنى؟","title":"معنى حديث: \"الكلب الأسود شيطان\"","answer":"الجواب: مثلما قال النبيُّ ﷺ: الكلب الأسود شيطان يعني: شيطان في جنسه، شيطان الكلاب.","link":"https://binbaz.org.sa/fatwas/24871/معنى-حديث-الكلب-الاسود-شيطان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى الكلب الأسود شيطان.mp3","categories":["شروح الحديث"]},{"id":4585,"question":"ركعتان بعد العشاء، هي ركعتا السنة؟","title":"هل الركعتان بعد العشاء هما السنة الراتبة؟","answer":"الجواب: هذه السنة الراتبة؛ راتبة العشاء. أما الإيتار فيكون بعد ذلك، يُصلِّي ثنتين ويُوتر بواحدةٍ، أو يُصلي واحدةً فقط لا بأس، لو صلَّى بعد الراتبة ركعةً واحدةً تمَّ له الوتر، وإن زاد صلَّى ثلاثًا أو خمسًا أو أكثر زاد أجره.","link":"https://binbaz.org.sa/fatwas/24872/هل-الركعتان-بعد-العشاء-هما-السنة-الراتبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بقوله في الحديث وركعتين بعد العشاء.mp3","categories":["شروح الحديث","صلاة التطوع"]},{"id":4596,"question":"محضورة مشهودة؟","title":"معنى وصف الضحى بأنها \"محضورة مشهودة\"","answer":"الجواب: يشهدها الله وملائكته، أو الملائكة كما في الرواية الأخرى.","link":"https://binbaz.org.sa/fatwas/24885/معنى-وصف-الضحى-بانها-محضورة-مشهودة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما معنى محضورة مشهودة.mp3","categories":["شروح الحديث"]},{"id":4603,"question":"قوله ﷺ: أعطاني ثلث أمتي؟","title":"معنى قوله: \"أعطاني ثلث أمتي\"","answer":"الجواب: يعني أمة الإجابة الذين أجابوا دعوته عليه الصلاة والسلام أن يُنجيهم من النار ويُخلِّصهم من النار إذا ماتوا على دينه، ومَن مات على الكبيرة فهو تحت مشيئته.\nس: يعني يشفع في الجميع؟\nج: شفاعته للجميع؛ الله وعده بأنه يُعطيه للجميع.\nس: كيف الجمع بينه وبين أحاديث أنه تبقى بقيةٌ فيُخرجهم الله برحمته؟\nج: أعطاهم إياه بالشروط، الذين ما توفرت [فيهم] الشروط ما لهم حقّ في الشفاعة، أعطاه ما أعطاه بالشروط: أن يموتوا على الإسلام، وعدم الموت على الكفر، فإنَّ مَن خرج عن الإسلام فليس من أمته على الحقيقة... من أمة الدعوة: كاليهود والنصارى وغيرهم، أمة الدَّعوة.\nس: من أمة الإجابة هل يبقى في النار؟ هل يبقى في النار ثم يُخرجهم الله؟\nج: هذا قد يكون في الشيء القليل الذي يبقى، والحديث فيه ضعف، هذا الحديث فيه ضعف، والمقصود... الشفاعة، أعطاه الله وأرضاه فيهم، والشيء القليل الذي قد يبقى ويُخرجهم الله كما جاء في الأحاديث الصحيحة لا يخرج عن ذلك، العبرة بالأكثر والأغلب.","link":"https://binbaz.org.sa/fatwas/24892/معنى-قوله-اعطاني-ثلث-امتي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى قوله في الحديث أعطاني ثلث أمتي.mp3","categories":["شروح الحديث"]},{"id":4648,"question":"لا يحجّ بعد العام مُشركٌ؟","title":"معنى حديث \"لا يحجّ بعد العام مُشركٌ\"","answer":"الجواب: المشرك ما له حجٌّ، يُمنع، قال تعالى: إِنَّمَا الْمُشْرِكُونَ نَجَسٌ فَلَا يَقْرَبُوا الْمَسْجِدَ الْحَرَامَ بَعْدَ عَامِهِمْ هَذَا [التوبة:28]، إن استطاع وليُّ الأمر أن يمنعهم منعهم.","link":"https://binbaz.org.sa/fatwas/24938/معنى-حديث-لا-يحج-بعد-العام-مشرك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث لا يحجّ بعد العام مُشركٌ.mp3","categories":["شروح الحديث"]},{"id":4668,"question":"كيف الجمع بين تطيب عائشة مع أنَّ النساء منهيات عن الطِّيب؟","title":"ما الذي يُسمح به من الطِّيب للنساء؟","answer":"الجواب: طيب ما يضرّ، رائحته ما هي ظاهرة، الشيء الذي لا تكون رائحته بارزة للناس؛ لأنهن وحدهن، ما هن مع الرجال، والطيب الذي يُنهى عنه في الأسواق مع الناس أو بين الرِّجال.","link":"https://binbaz.org.sa/fatwas/24960/ما-الذي-يسمح-به-من-الطيب-للنساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الجمع بين حديث كنا نخرج مع النبي إلى مكة، فنضمد جباهنا بالسك المطيب ونهي النساء.mp3","categories":["شروح الحديث"]},{"id":4705,"question":"في الحديث يقول: ففعل على المروة كما فعل على الصفا. معناه يقول: إِنَّ الصَّفَا وَالْمَرْوَةَ مِنْ شَعَائِرِ اللَّهِ [البقرة:158]؟","title":"هل يُشرع على المروة مثل ما يفعل في الصفا؟","answer":"الجواب: لا، فعل عليها من الدعاء والذكر ورفع اليدين، وإلا إِنَّ الصَّفَا وَالْمَرْوَةَ مِنْ شَعَائِرِ اللَّهِ عند البدء فقط.","link":"https://binbaz.org.sa/fatwas/24997/هل-يشرع-على-المروة-مثل-ما-يفعل-في-الصفا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بحديث ففعل على المروة كما فعل على الصفا.mp3","categories":["شروح الحديث"]},{"id":4724,"question":"قول رسول الله ﷺ لعمر: هنا تُسكب العبرات يا عمر؟","title":"ما معنى وصحة أثر «هنا تُسكب العبرات يا عمر»؟","answer":"جاء هذا، لكن ما أعرف حال سنده، ولا شكَّ أنها مواضع خشوع، ومواضع تقرب إلى الله، ومواضع بكاء عند الحجر، والصلاة في الكعبة، وفي الحِجر، مواضع فيها الخشية، وفيها البكاء، وفيها الضراعة إلى الله جلَّ وعلا، أعظم موضع، وأفضل موضع، وأفضل بقعةٍ.","link":"https://binbaz.org.sa/fatwas/25026/ما-معنى-وصحة-اثر-هنا-تسكب-العبرات-يا-عمر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بقول رسول الله لعمر هنا تُسكب العبرات يا عمر.mp3","categories":["شروح الحديث","الحكم على الأحاديث"]},{"id":4730,"question":"قول عليٍّ : \"لَا تَتَّبِعُونَ شَيْئًا أَفْضَلَ مِنْ سُنَّةِ نَبِيِّكُمْ\"؟","title":"معنى قول عليٍّ «لَا تَتَّبِعُونَ شَيْئًا أَفْضَلَ مِنْ سُنَّةِ نَبِيِّكُمْ»","answer":"يعني سنته، الذي أباح من سنته، والذي أوجب من سنته، والذي حرَّم من سنته، كل ما جاء عنه ﷺ من الأحكام هو من سنته.","link":"https://binbaz.org.sa/fatwas/25039/معنى-قول-علي-لا-تتبعون-شيىا-افضل-من-سنة-نبيكم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى قول عليٍّ لَا تَتَّبِعُونَ شَيْئًا أَفْضَلَ مِنْ سُنَّةِ نَبِيِّكُمْ.mp3","categories":["شروح الحديث"]},{"id":4739,"question":"القدرية مجوس هذه الأمة؟","title":"لماذا كانت القدرية مجوس هذه الأمة؟","answer":"جاء في عدة أحاديث، ذكر شيخُ الإسلام ابن تيمية وغيره أنها بمجموعها يشدّ بعضها بعضًا؛ لأنهم أنكروا بعضَ أفعال الله، والمجوس قالوا بالإلهين؛ ولهذا شابهوا المجوس.","link":"https://binbaz.org.sa/fatwas/25067/لماذا-كانت-القدرية-مجوس-هذه-الامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/لماذا كانت القدرية مجوس هذه الأمة.mp3","categories":["شروح الحديث","الفرق والمذاهب"]},{"id":4741,"question":"لكن وجه الشاهد من حديث أطَّت السماء أليس هذا متعلقًا بالملائكة؟","title":"ما معنى حديث «أطَّت السماءُ وحُقَّ لها أن تئطَّ»؟","answer":"بلى، لكن وإن كانت السَّماوات أعظم شيءٍ إحكامًا وقوةً فكونها تئطّ أو كون العرش يئطّ لا مانع؛ لأنَّ الله جلَّ وعلا هو الذي أمسكها ، وأطيطها لا يمنع من كونها ممسكة، عظيمة، قوية، الله أمسكها جلَّ وعلا، وليس يدل على أنَّ هذا ممتنع، فهي أطت كما أنها قوية ممسكة، فالعرش كما أنه ممسك قوي قد يئط من تعظيم الله، من خوف الله؛ لكبريائه، لا لأنه محتاج إليه، بل تئط من خوفها، ومن تعظيمها لله، والعرش من تعظيمه لله، من خجله، لا شكَّ في ذلك، الإنسان قد يتحرج، قد يرتعد، لا عن ثقلٍ عليه، ولكن لتعظيم وخجل، أو لأمرٍ آخر من الأمراض العارضة، فالعرش مخلوق من المخلوقات قد يئط لأسبابٍ كثيرةٍ، لا للثَّقل، ولا للحاجة. فإذا استقام السندُ فلا حاجةَ إلى التأويل.\nس: أيش معنى الأطيط؟\nج: الأطيط هو الاهتزاز والحركة لثقل ما عليه، أو من رعدةٍ، أو من خوفٍ، أو من نحو ذلك، قريب من معنى الصَّرصرة، إذا حمل الإنسانُ شيئًا من الثِّقل، مثل: الشداد والمسامة وأشباهها، قد تكون لها حركة وصوت من ثقل ما عليها.\nوالسَّقف الضَّعيف كذلك إذا وُضعت عليه الأشياء الثِّقال.","link":"https://binbaz.org.sa/fatwas/25070/ما-معنى-حديث-اطت-السماء-وحق-لها-ان-تىط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/شرح حديث أطَّت السماءُ وحُقَّ لها أن تئطَّ.mp3","categories":["شروح الحديث"]},{"id":4752,"question":"الحكايات والأخبار التي تُروى في مشاهدة بعض الناس لشيءٍ من النَّعيم؟","title":"ما صحة الأخبار في رؤية نعيم القبر أو أهواله؟","answer":"هذا واقع، ذكره ابنُ رجبٍ رحمه الله وغيره، ذكره ابنُ رجب في \"أهوال القبور\"، والقرطبي في \"التذكرة\"، والسَّفاريني في \"البحور الزاخرة\"، وغيرهم ذكروا أشياء من هذا كثيرة، ابن رجب ذكر من هذا أشياء في \"أهوال القبور\"، أطلع الله الناس على ما يشاء ؛ عبرةً، للعظة والتَّذكر، مثلما أطلع اللهُ نبيَّه ﷺ على القبرين، قال: إنهما ليُعذَّبان، وما يُعذَّبان في كبيرٍ، أما أحدهما فكان لا يستتر من بوله، وأما الآخر فكان يمشي بالنَّميمة، هذا مما أطلع عليه النبيَّ ﷺ، وفي غلام -مولاه كركرة- قال: إنَّ الشَّملة التي غلَّها لتشتعل عليه نارًا، وأشياء من هذا جاءت عن النبي ﷺ.","link":"https://binbaz.org.sa/fatwas/25096/ما-صحة-الاخبار-في-روية-نعيم-القبر-او-اهواله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الأخبار التي تُروى في مشاهدة بعض الناس لشيءٍ من نعيم القبر أو أهواله.mp3","categories":["شروح الحديث","الحكم على الأحاديث","فتاوى متنوعة","البيوع"]},{"id":4757,"question":"كيف نُفرق بين المعجزة والكرامات؟","title":"ما الفرق بين المعجزات والكرامات؟","answer":"الأصل فيها أنها واحد، الكرامة والمعجزة هي الخارق للعادة، فإذا كان من باب التَّحدي كما جاءت به الرسل فهذه يُقال لها: معجزات في الاصطلاح، وتُسمَّى: كرامات في المعنى أيضًا. وإن كانت على يد المؤمنين وليسوا ممن ادَّعى الرسالةَ، بل هم من أتباع الرسل، فهذه أخص باسم الكرامة، وهي معجزة أيضًا للنبي الذي جاء بما عليه هذا المؤمن. فإن كانت ليست مع الأنبياء ولا مع المؤمنين؛ فهي من الشَّعاوذ التي تأتي بها الشياطين، وإن سُميت: خارقًا، لكنَّها في الحقيقة شعوذة من الشيطان، وتزيين من الشيطان وتلبيس؛ حتى يظنَّ الناسُ أنَّ هذا مؤمن، أو أنَّ هذا نبي، وليس كذلك.\nولهذا قال العلماء كما تقدم: الميزان التزامه بالشرع، مَن كان مُلتزمًا بالشرع مُستقيمًا عليه ظاهرًا وباطنًا؛ فما وقع له من الخوارق فهو كرامة، وإن كان غير ملتزمٍ فإنه مما تأتي به الشَّياطين من الخوارق لأربابها؛ للتلبيس على الناس، أو لقضاء حوائج أوليائهم من الإنس، كما قد يفعل السَّحرة والكهان والمنجمون؛ تلبيسًا من الشياطين وتغريرًا بهؤلاء.","link":"https://binbaz.org.sa/fatwas/25111/ما-الفرق-بين-المعجزات-والكرامات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما الفرق بين المعجزات والكرامات.mp3","categories":["شروح الحديث","فتاوى متنوعة"]},{"id":4760,"question":"ما الفرق بين السَّائل والدَّاعي؟","title":"ما الفرق بين معنى السَّائل والدَّاعي في الأحاديث؟","answer":"السائل أخص، فإنه يسأل شيئًا خاصًّا، فالغالب أنَّ السائل يسأل شيئًا خاصًّا يُعجل له في الدنيا: هل من سائلٍ فيُعطى سؤله، فالسائل أخص من الدَّاعي، الدَّاعي قد يكون عابدًا، وقد يكون سائلًا، يقول الله تعالى: ادْعُونِي فُسِّرت بـ\"اعبدوني\"، وفُسِّرت بـ\"اسألوني\"، فكل سائلٍ عابد، وليس كل عابدٍ سائلًا، فالمصلي عابد وداعٍ بفعله، والمتصدق داعٍ، والمجاهد داعٍ بعمله، والذي يقول: \"ربّ اغفر لي وارحمني\" داعٍ، لكنه أخصّ بالسؤال، فالذي يقول: \"أعطني كذا، وارزقني ولدًا صالحًا\" أخص بالسؤال، وإن كان عابدًا بالسؤال، لكنه أخصّ بالسؤال، فما كان بلفظ السؤال: اغفر لي، ارحمني، وأعطني زوجةً صالحةً، أغنني عن فلانٍ، أغنني بفضلك، هذا أخص بالسؤال، والصلاة والصوم أخصّ بالعبادة، وكلاهما يُطلق عليه دعاء، يقال: دعا بمعنى: عبد، ودعا بمعنى: سأل، والسؤال أخصّ.","link":"https://binbaz.org.sa/fatwas/25119/ما-الفرق-بين-معنى-الساىل-والداعي-في-الاحاديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما الفرق بين السَّائل والدَّاعي في حديث من يدعوني فأستجيب له؟ من يسألني فأعطيه.mp3","categories":["شروح الحديث"]},{"id":4761,"question":"معنى خداج؟","title":"ما معنى: «فهي خداج» في الحديث؟","answer":"يعني فاسدة، إذا صلى بغير قراءة الصلاة فاسدة، يقال: أخدجت الناقة: إذا أسقطت الجنين ميتًا، أسقطت ولدًا ميتًا.","link":"https://binbaz.org.sa/fatwas/25120/ما-معنى-فهي-خداج-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث من صلّى صلاة لم يقرأ فيها بفاتحة الكتاب فهي خداج.. ما معنى خداج.mp3","categories":["القراءة في الصلاة","صلاة الجماعة","شروح الحديث"]},{"id":4767,"question":"ما معنى والشر ليس إليك يا شيخ؟","title":"ما معنى «والشر ليس إليك» في الحديث؟","answer":"يعني: لا يتقرب به إليك ولا ينسب إليك؛ لأنه له الحكمة البالغة فيما خلقه، فهو خير بالنسبة إليه وإن قدره بالنسبة إلى المخلوقين شرًّا، كتقديره الزنا وما يقع من المعاصي حكمة من الله يُحمد عليها، وله الحكمة البالغة، ولكنها ذم بالنسبة إلى المخلوق إذا فعلها لأنها معاصٍ في حق المخلوق.","link":"https://binbaz.org.sa/fatwas/25128/ما-معنى-والشر-ليس-اليك-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما معنى والشر ليس إليك.mp3","categories":["شروح الحديث"]},{"id":4768,"question":"سورة تبارك شفعت لرجل لقراءته أو لحفظه؟","title":"ما معنى ما جاء أن سورة تبارك تشفع لصاحبها؟","answer":"لقراءتها والعمل بها، العمل بما فيها، يعني مع الاستقامة على طاعة الله ورسوله.","link":"https://binbaz.org.sa/fatwas/25129/ما-معنى-ما-جاء-ان-سورة-تبارك-تشفع-لصاحبها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما معنى سورة تبارك شفعت لرجل.mp3","categories":["شروح الحديث","القرآن وعلومه","الحيض والنفاس"]},{"id":4769,"question":"في قول الرسول ﷺ: لا يرد القدر إلا الدعاء، ولا يزيد في العمر إلا البر فكيف يرد القدر؟ وكيف يؤخر الله فيزيد العمر والله يقول: وَلَنْ يُؤَخِّرَ اللَّهُ نَفْسًا إِذَا جَاءَ أَجَلُهَا [المنافقون:11]؟","title":"ما شرح حديث «لا يرد القدر إلا الدعاء»؟","answer":"لا منافاة بين هذا وهذا، البر يزيد في العمر وصلة، ومن أحب أن ينسأ له في أجله ويبسط له في رزقه فليصل رحمه فالدعاء من أسباب رد القدر المعلق، وصلة الرحم والبر من أسباب زيادة العمر المعلقة، فإن القدر قدران: قدر معلق، وقدر ناجز غير معلق، فالناجز لا حيلة فيه كالموت المحدد ونحو ذلك، أما المعلق: فهذا معلق على أسبابه فقد يعلق الله سبحانه بسط الرزق وطول الأجل على صلة الرحم وعلى البر، فيكون زاد في عمره بما قدره من أنه يبر والديه ويصل رحمه، وأن هذا القدر يرده الدعاء، فهو يصيبه كذا وكذا إلا إذا دعا بكذا، قد قدر الله أنه يدعو فزال هذا القدر المعلق بالدعاء، فالقدر المعلق هو الذي ينفع فيه بسط الرزق، وينفع فيه البر، وينفع فيه الدعاء، أما المحتم غير المعلق؛ فهذا يقع في وقته لا يرده شيء وَلَنْ يُؤَخِّرَ اللَّهُ نَفْسًا إِذَا جَاءَ أَجَلُهَا [المنافقون:11] فأجلها إذا جاء المعلق، وغير المعلق انتهى.","link":"https://binbaz.org.sa/fatwas/25131/ما-شرح-حديث-لا-يرد-القدر-الا-الدعاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى حديث لا يرد القدر إلا الدعاء.mp3","categories":["شروح الحديث"]},{"id":4771,"question":"أثابكم الله يقول: ما ورد في صلاة النبي ﷺ أربعًا قبل الظهر بغير سلام، هل هو صحيح؟ وهل صح حديث صلاة الليل والنهار مثنى مثنى وكيف يجمع بينها؟","title":"هل صح صلاة النبي أربعًا قبل الظهر دون فصل؟","answer":"هذه الصلاة بعد الزوال أربعًا بلا سلام فيه ضعف، ليس فيما أعلم ثابتًا، وإنما السنة أن يسلم من كل ثنتين صلاة الليل والنهار مثنى مثنى وهو حديث صحيح: صلاة الليل والنهار مثنى مثنى، وفي الحديث الصحيح عن ابن عمر: صلاة الليل مثنى مثنى، وكان ﷺ يسلم في تطوعاته من كل ثنتين، يسلم من كل ثنتين، قالت عائشة رضي الله عنها: «كان يصلي من الليل عشرًا يسلم من كل ثنتين ثم يوتر بواحدة» لكن يجوز أن يوتر بخمس جميعًا، أو بثلاث جميعًا، أو بسبع جميعًا، ورد هذا عنه عليه الصلاة والسلام، لكن لا يتطوع بأربع في سلام واحد، أو بست شفع أو بثمان لا يسلم من كل ثنتين، أما إذا سرد وترًا ثلاثًا سبعًا خمسًا وترًا لا بأس، أما التطوع بأن يصلي أربعًا جميع بسلام واحد، أو ستًّا جميع بسلام واحد؛ فهذا خلاف السنة، السنة أن يسلم من كل ثنتين.","link":"https://binbaz.org.sa/fatwas/25133/هل-صح-صلاة-النبي-اربعا-قبل-الظهر-دون-فصل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الجع بين حديث صلى النبي أربعًا قبل الظهر بغير سلام، وحديث صلاة الليل والنهار مثنى مثنى.mp3","categories":["شروح الحديث"]},{"id":4776,"question":"رجل يغني بالقرآن على اللحن الموسيقي هل يكفر بذلك؟","title":"ما حكم من يغني بالقرآن على لحن الموسيقا؟","answer":"لا يجوز هذا الكلام، لكن قد يتأول ليس منا من لم يتغن بالقرآن يعني يحسّن صوته، هذا معنى التغني بالقرآن، يعني تحسين الصوت بالتلاوة، ما هو يقرأه على نغمات الشعر والغناء، لا، هذا غلط، ينبَّه أن هذا غلط، ما يكفر بذلك، لكن يعلم أن هذا خلاف السنة، غلط، وأن السنة في التغني معناه تحسين الصوت تحسين التلاوة.","link":"https://binbaz.org.sa/fatwas/25140/ما-حكم-من-يغني-بالقران-على-لحن-الموسيقا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما معنى التغني بالقرآن.mp3","categories":["شروح الحديث"]},{"id":4786,"question":"الصيام خاص بالولي؟","title":"هل يجوز الصوم عن الميت من وليّه وغيره؟","answer":"الأقارب، الولي هو القريب، وإذا صام غيره؛ فلا بأس، من باب الإحسان.\nس: على سبيل الوجوب؟\nالشيخ: المعروف عند العلماء الاستحباب؛ لقوله جل وعلا: وَلَا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَى [الأنعام:164] فالأقرب -والله أعلم- أنه للتأكيد والمشروعية.","link":"https://binbaz.org.sa/fatwas/25154/هل-يجوز-الصوم-عن-الميت-من-وليه-وغيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من مات وعليه صيام صام عنه وليه، ما المقصود بالولي، وما حكم صيامه.mp3","categories":["شروح الحديث","مسائل متفرقة في الصيام"]},{"id":4802,"question":"مَن قال: مَن فطَّر صائمًا فله مثل أجره لا بدّ من الإشباع، ما رأيكم في هذا الأمر؟","title":"هل يلزم الإشباع في أجر مَن فطَّر صائمًا؟","answer":"لا، الأحاديث تدل على أنه ما هو لازم الإشباع.\nس: يحصل الأجرُ بدون إشباعٍ؟\nج: ولو ما أشبعه نعم.","link":"https://binbaz.org.sa/fatwas/25189/هل-يلزم-الاشباع-في-اجر-من-فطر-صاىما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث مَن فطَّر صائمًا فله مثل أجره، هل المقصود الإشباع.mp3","categories":["شروح الحديث","مسائل متفرقة في الصيام"]},{"id":4805,"question":"إذا كان المسلمُ سلك طريقًا يلتمس به علمًا: كالطب، والهندسة، فهل يدخل في هذا الحديث، يعني غير العلوم الشرعية؟","title":"«من سلك طريقًا يلتمس فيه علمًا» هل يشمل العلم الدنيوي؟","answer":"الأقرب -والله أعلم- أنَّ المراد به العلوم الشرعية، أما العلوم الأخرى فهي مباحة، إذا كان أراد بها الخير يُرجى له الخير، إذا أراد بها نفع المسلمين: كطبٍّ، أو هندسةٍ، أو حسابٍ، وأراد به نفع المسلمين؛ يُرجى له الخير إن شاء الله، لكن العلم إذا أُطلق: قال الله، قال رسوله، هذا العلم.","link":"https://binbaz.org.sa/fatwas/25200/من-سلك-طريقا-يلتمس-فيه-علما-هل-يشمل-العلم-الدنيوي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث من سلك طريقًا يلتمس فيه علمًا... هل يدخل في هذا علم الطب، والهندسة ونحوه.mp3","categories":["شروح الحديث","العالم والمتعلم"]},{"id":4814,"question":"قوله ﷺ: الغيبة ذكرك أخاك بما يكره، هل هذا يشمل غيبته حال حضوره أم حال غيبته إن لم يكن حاضرًا؟","title":"هل تقع الغِيبة في حق من كان حاضرًا؟","answer":"لا، هذا الذكر في حال غيبته أو حال حضوره، فهذا شيء بينه وبينه، كونه يذكره عند الناس في حال غيبته.","link":"https://binbaz.org.sa/fatwas/25214/هل-تقع-الغيبة-في-حق-من-كان-حاضرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث ذكرك أخاك بما يكره... هل يشمل غيبته حال حضوره أم إن لم يكن حاضرًا.mp3","categories":["شروح الحديث","الأخلاق المذمومة"]},{"id":4827,"question":"مَن قال أنَّ القوة في قوة البدن: المؤمن القوي خيرٌ وأحبُّ إلى الله منه؟","title":"ما المقصود بحديث «المؤمن القوي خيرٌ وأحبُّ إلى الله»؟","answer":"لا، ما هو بالبدن، وأيش يبغى بالبدن إذا ما نفع؟ القوة قوة العمل، لو كان أقوى من الفيل ولكن ما يأمر ولا ينهى فهو ما يُسمَّى: قويًّا، يُسمَّى: ضعيفًا، ولو كان أقوى من الفيل.","link":"https://binbaz.org.sa/fatwas/25244/ما-المقصود-بحديث-المومن-القوي-خير-واحب-الى-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بحديث المؤمن القوي خيرٌ وأحبُّ إلى الله.mp3","categories":["شروح الحديث"]},{"id":4831,"question":"مَن فسَّر صلاة الليل بصلاة العشاء: صلوا بالليل؟","title":"ما المراد بالصلاة في حديث «وصلوا بالليل والناس نيام»؟","answer":"لا، التهجد بالليل؛ لأنه قال: والناس نيام، التهجد بالليل.","link":"https://binbaz.org.sa/fatwas/25251/ما-المراد-بالصلاة-في-حديث-وصلوا-بالليل-والناس-نيام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بالصلاة في حديث وصلوا بالليل والناس نيام.mp3","categories":["الوتر وقيام الليل","شروح الحديث"]},{"id":4833,"question":"ما ورد من الأحاديث فيها نفي الإيمان، هل يدل ذلك على أنَّ هذا المنفي عنه الإيمان كبيرة من كبائر الذُّنوب؟","title":"على ماذا تدل الأحاديث التي فيها نفي الإيمان؟","answer":"عند بعض أهل العلم يُعدُّ كبيرةً؛ كشيخ الإسلام ابن تيمية وجماعة يعدّونه كبيرة؛ لأنه نفى عنه الإيمان، مثل قوله ﷺ: لا يزني الزاني حين يزني وهو مؤمن، ولا يشرب الخمرَ حين يشربها وهو مؤمن، وقوله ﷺ: ليس منا مَن ضرب الخدود، أو شقَّ الجيوب، أو دعا بدعوى الجاهلية.","link":"https://binbaz.org.sa/fatwas/25254/على-ماذا-تدل-الاحاديث-التي-فيها-نفي-الايمان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/على ماذا تدل الأحاديث التي فيها نفي الإيمان.mp3","categories":["شروح الحديث","مسائل متفرقة في العقيدة"]},{"id":4836,"question":"الأمر بلعق الأصابع للوجوب أم للاستحباب؟","title":"هل الأمر بلعق الأصابع للوجوب أم للاستحباب؟","answer":"الأصل في الأوامر للوجوب، والمعروف عند العلماء أنه للاستحباب، فالأصل في أوامر الرسول ونواهيه الوجوب في الأوامر، والتحريم في النواهي.","link":"https://binbaz.org.sa/fatwas/25262/هل-الامر-بلعق-الاصابع-للوجوب-ام-للاستحباب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الأمر في حديث فلا يمسح يده بالمنديل حتى يلعقها أو يلعقها.mp3","categories":["شروح الحديث"]},{"id":4839,"question":"حطّت عنه خطاياه خاصّ بصغائر الذّنوب؟","title":"ما معنى قوله «حطّت عنه خطاياه» في الحديث؟","answer":"عام، إذا كان معها توبة، ومعها ندم، والنصوص يُفسّر بعضُها بعضًا، يعني: سبَّح مع توبةٍ وندمٍ، كما قال في الحديث: الصَّلوات الخمس، والجمعة إلى الجمعة، ورمضان إلى رمضان، كفَّارات لما بينهنَّ إذا اجتنب الكبائر، والنصوص يُفسِّر بعضها بعضًا، ما هو مجرد أن يقول: هو، هو، هو، ويُصرّ على السيئات.","link":"https://binbaz.org.sa/fatwas/25275/ما-معنى-قوله-حطت-عنه-خطاياه-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بقوله حطّت عنه خطاياه في الحديث.mp3","categories":["شروح الحديث"]},{"id":4840,"question":"من قال بأنه إذا استحل قتاله كفر؟","title":"هل قوله: «وقتاله كفر» يعني استحلال القتل؟","answer":"إذا استحل المعصية المحرمة بالإجماع؛ كفر.\nس: وإن لم يستحله؟\nج: كفر دون الكفر، لكن من استحل الزنى أو ظلم الناس أو شرب الخمر؛ كفر الكفر الأكبر.","link":"https://binbaz.org.sa/fatwas/25276/هل-قوله-وقتاله-كفر-يعني-استحلال-القتل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث سباب المسلم فسوق وقتاله كفر، هل إذا استحله فقط أم في كل حال.mp3","categories":["شروح الحديث","مسائل متفرقة في العقيدة"]},{"id":4841,"question":"معنى قوله: إلا حرَّم الله عليه الجنة؟","title":"ما معنى الوعيد في حديث «إلا حرَّم الله عليه الجنة»؟","answer":"من باب الوعيد، دخول النار وتحريم الجنة من باب الوعيد، إلا من كفر كفرًا أكبر فهذا يخلد في النار إِنَّ اللَّهَ لَا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ [النساء:48] داخل فيه هذا، حرم الله عليه الجنة ودخل النار، مثل: وَمَنْ يَقْتُلْ مُؤْمِنًا مُتَعَمِّدًا فَجَزَاؤُهُ جَهَنَّمُ خَالِدًا فِيهَا وَغَضِبَ اللَّهُ عَلَيْهِ وَلَعَنَهُ وَأَعَدَّ لَهُ عَذَابًا عَظِيمًا [النساء:93] كذلك: من انتسب إلى غير أبيه؛ حرم الله عليه الجنة، وأشباهه.","link":"https://binbaz.org.sa/fatwas/25279/ما-معنى-الوعيد-في-حديث-الا-حرم-الله-عليه-الجنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الوعيد في حديث إلا حرم الله عليه الجنة.mp3","categories":["شروح الحديث"]},{"id":4842,"question":"معنى:قوله: ليس أكرم على الله من الدعاء؟","title":"ما صحة ومعنى حديث \"ليس أكرم على الله من الدعاء\"؟","answer":"لأن الدعاء أفضل العبادة، لكنه ضعيف، والرواية الثابتة الدعاء هو العبادة، وأما الدعاء مخ العبادة، وليس أكرم على الله من الدعاء؛ فيه ضعف.","link":"https://binbaz.org.sa/fatwas/25280/ما-صحة-ومعنى-حديث-ليس-اكرم-على-الله-من-الدعاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى حديث ليس أكرم على الله من الدعاء.mp3","categories":["شروح الحديث","الأدعية والأذكار"]},{"id":4856,"question":"حديث النهي عن أكل الضب كيف توجه؟","title":"هل صح حديث النهي عن أكل الضب؟","answer":"ما ورد في النهي فهو ضعيف، والصواب أنه حلال كما ثبت في الصحيحين.\nس: قول الشارح: واستدل القائلون بالتحريم بما رواه أبو داود: نهى عن الضب؟\nج: لا، ليس بصحيح.","link":"https://binbaz.org.sa/fatwas/25316/هل-صح-حديث-النهي-عن-اكل-الضب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/توجيه حديث النهي عن أكل الضب.mp3","categories":["شروح الحديث"]},{"id":4861,"question":"الأحاديث التي فيها النَّهي عن الفرع والعتيرة، والأحاديث التي فيها الرُّخصة فيها، ما الجمع بين النَّهي والرخصة؟","title":"ما كيفية الجمع بين النَّهي والرخصة في الفرع والعتيرة؟","answer":"الفرع والعتيرة من أمور الجاهلية، والإسلام نسخ أمر الجاهلية، وفي الحديث الصحيح: لا فرعَ في الإسلام.","link":"https://binbaz.org.sa/fatwas/25332/ما-كيفية-الجمع-بين-النهي-والرخصة-في-الفرع-والعتيرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الجمع بين الأحاديث التي فيها النَّهي عن الفرع والعتيرة، والأحاديث التي فيها الرُّخصة فيها.mp3","categories":["الأطعمة والأشربة","شروح الحديث"]},{"id":4919,"question":"يقول السائل: ما هو صيام الدهر؟ وهل يجوز صيام أيام متتالية استنادًا للحديث الذي فيما معناه أن النبي ﷺ كان يسأل أهله عن الإفطار فإذا لم يجد ينوي الصيام، ثم يقول: وهل يجوز لي الصيام لظروف مادية صعبة؟","title":"ما معنى صوم الدهر وحكم الصوم لظروف المعيشة؟","answer":"لا بأس في النافلة؛ إن شاء صام من أثناء النهار إذا لم يأكل سابقًا، يصوم من أثناء النهار، لا بأس، وله أن يفطر، المتنفل. ولكن سَرْدُ الصيام ينبغي له أن يكون يوم بعد يوم، إذا أراد السَّرْد يفطر يومًا ويصوم يومًا، وإنْ سَرَدَ أيامًا ثم أفطر بعددها؛ فلا بأس، كما كان عبدالله بن عمرو يفعل في آخر حياته، لما تعب كان يصوم أيامًا كثيرة يسردها، ثم يفطر بعددها؛ لأنها أقوى له.","link":"https://binbaz.org.sa/fatwas/25436/ما-معنى-صوم-الدهر-وحكم-الصوم-لظروف-المعيشة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما هو صيام الدهر وهل يجوز الصيام لظروف مادية صعبة.mp3","categories":["شروح الحديث","صيام التطوع"]},{"id":4920,"question":"يقول السائل: هل يشترط تبييت النية لصيام الست من شوال؟ وإذا استيقظ إنسان في الضحى في يوم من أيام شوال ولم يأكل شيئًا فهل يُحسب صيام  هذا اليوم؟","title":"هل يشترط تبييت النية لصيام الست من شوال؟","answer":"التطوع ما يشترط له التبييت بالنية، لو صام من أثناء النهار لا بأس، يكون ناقصًا، وإذا صام من أول النهار أفضل أكمل. وإذا ما صام إلا من أثناء النهار صار صيامه ناقصًا.","link":"https://binbaz.org.sa/fatwas/25438/هل-يشترط-تبييت-النية-لصيام-الست-من-شوال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم تبييت النية لصيام الست من شوال.mp3","categories":["شروح الحديث","صيام التطوع"]},{"id":4925,"question":"أحيا ليله أي أن النبي ﷺ كان لا ينام ليالي العشر؟","title":"ما معنى \"أحيا ليله\" في الحديث؟","answer":"إيه هذا معناه؛ أنه كان يحيي ليله بالقراءة والصلاة والدعاء.","link":"https://binbaz.org.sa/fatwas/25443/ما-معنى-احيا-ليله-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما معنى أحيا ليله في الحديث.mp3","categories":["شروح الحديث","صلاة التطوع"]},{"id":4927,"question":"قول الرسول ﷺ: الدنيا ملعونة ملعون ما فيها..؟","title":"معنى حديث \"الدنيا ملعونة ملعون ما فيها\"","answer":"الجواب: أي مذمومة، يعني الذم، مثل: شجرة الزقوم طعام الأثيم، سماها ملعونة قال: وَالشَّجَرَةَ الْمَلْعُونَةَ فِي الْقُرْآنِ يعني مذمومة، والدنيا مذمومة؛ لأنها تشغل عن الآخرة، وتصد عن الهدى، إلا من استعان بها على الخير.","link":"https://binbaz.org.sa/fatwas/26089/معنى-حديث-الدنيا-ملعونة-ملعون-ما-فيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى حديث الدنيا ملعونة...mp3","categories":["شروح الحديث"]},{"id":4928,"question":"قوله: أنا الدهر؟","title":"معنى \"أنا الدهر\" في الحديث القدسي","answer":"الشيخ: يعني مقلب خالق الدهر، ومكون كائنات الدهر، ومقلب ليله ونهاره .","link":"https://binbaz.org.sa/fatwas/26088/معنى-انا-الدهر-في-الحديث-القدسي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى قوله أنا الدهر.mp3","categories":["شروح الحديث"]},{"id":4939,"question":"حديث ابن صياد؟","title":"حكم حديث ابن صيّاد وهل هو الدجال؟","answer":"الجواب: ثابت، حديث ابن صياد ثابت، لكن الشكَّ: هل هو الدجال أو ما هو الدجال؟ هذا محل الشكِّ.","link":"https://binbaz.org.sa/fatwas/27094/حكم-حديث-ابن-صياد-وهل-هو-الدجال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم حديث ابن صيّاد وهل هو الدجال؟.mp3","categories":["شروح الحديث","الحكم على الأحاديث"]},{"id":4940,"question":"قوله: أتُرى بي بأس..؟ (لما قيل له في غضبه: قل أعوذ بالله من الشيطان الرجيم - في الحديث)","title":"معنى قول الغاضب \"أتُرى بي بأس؟\" بالحديث","answer":"الجواب: يعني خلل في عقلي، يوم تقول أتعوذ بالله، ترى أني مختل العقل؟ هذا معناه، يعني: أنا صاحٍ ما أنا مختل العقل؛ فلا حاجة إلى أن أقول أعوذ بالله من الشيطان الرجيم.","link":"https://binbaz.org.sa/fatwas/27144/معنى-قول-الغاضب-اترى-بي-باس-بالحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى رد الغاضب أترى بي بأس بالحديث.mp3","categories":["شروح الحديث"]},{"id":4967,"question":"يدخل في تخبيب الزوجة: أم الزوج أو أم الزوجة لو خببت بنتها على زوجها؟","title":"هل تدخل أم الزوجة وأهلها في وعيد تَخْبِيبِها؟","answer":"الجواب: عامٌّ، يَعُمُّ الزوج، يَعُمُّ أمها وأباها وأخاها وجارها، يعم كل أحد.\nس: ترى أن هذا مصلحة لها، ليس عن قصد؟\nالشيخ: لا ما يجوز لها تخبِّبها على زوجها، إذا كان عنده مشكلة يطلبون من الزوج يطلقها ويعطونها \"فلوس\"، إذا كانوا يرونه أنه ما هو أهل.","link":"https://binbaz.org.sa/fatwas/27667/هل-تدخل-ام-الزوجة-واهلها-في-وعيد-تخبيبها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تدخل أم الزوجة وأهلها في وعيد تخبيبها.mp3","categories":["شروح الحديث"]},{"id":4981,"question":"بالنسبة للذين على الحدود الذين يحفظون الحدود من الجنود، هؤلاء الذي يسمى \"سلاح الحدود\"، هل يكون هذا رِباطًا؟","title":"هل يدخل جنود الحدود في فضل \"الرباط\"؟","answer":"الجواب: كل من كان في الثغور يُسمّى \"رباط\" إذا أصلح الله نيّته.","link":"https://binbaz.org.sa/fatwas/28389/هل-يدخل-جنود-الحدود-في-فضل-الرباط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يدخل جنود الحدود في فضل الرباط.mp3","categories":["شروح الحديث"]},{"id":4982,"question":"قوله ﷺ: ولك أجره عن الحج بالصبي؟","title":"هل في حج الصبيِّ يشمله الأجر ومَنْ حَجَّ به؟","answer":"الجواب: يعني على أعمالها، كونها تطوف به وتسعى به وتنوي عنه؛ لها أجر.\nس: والصبي؟\nالشيخ: والصبي له أجر، كله؛ لأنه حاج هو، له أجر حجة.\nس: والعمرة؟\nالشيخ: والعمرة كذلك.","link":"https://binbaz.org.sa/fatwas/28390/هل-في-حج-الصبي-يشمله-الاجر-ومن-حج-به","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل في حج الصبيِّ يشمله الأجر ومَنْ حَجَّ به؟.mp3","categories":["شروح الحديث"]},{"id":4983,"question":"الصيام غدًا على أنه يوم الإثنين وهو يوم خمسة عشر؟","title":"حكم الجمع بين صيام الإثنين وخمسة عشر","answer":"الجواب: ما في حرج، لا بأس؛ يصوم يوم الإثنين سواء كان خمسة عشر ولا غيره، ما في بأس.","link":"https://binbaz.org.sa/fatwas/28482/حكم-الجمع-بين-صيام-الاثنين-وخمسة-عشر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الجمع بين صيام الاثنين وخمسة عشر.mp3","categories":["شروح الحديث","صيام التطوع"]},{"id":5032,"question":"أخونا يسأل سؤال آخر مماثل يقول: أرجو شرح هذا الحديث مع بيان مقارنته بالآية القرآنية الآتية، قال تعالى: وَإِنْ تُبْدُوا مَا فِي أَنفُسِكُمْ أَوْ تُخْفُوهُ يُحَاسِبْكُمْ بِهِ اللَّهُ... [البقرة:284] إلى آخر الآية.. والحديث عن أبي هريرة  قال: قال رسول الله ﷺ: إن الله تجاوز عن أمتي ما حدثت به أنفسها ما لم تعمل أو تتكلم؟","title":"ما معنى: «إن الله تجاوز عن أمتي ما حدثت به أنفسها»؟","answer":"الجواب:\nهذه الآية الكريمة لما نزلت شقت على الصحابة ، فأمرهم النبي ﷺ أن يقولوا: سمعنا وأطعنا، لما أنزل الله قوله تعالى: لِّلَّهِ ما فِي السَّمَاواتِ وَمَا فِي الأَرْضِ وَإِن تُبْدُواْ مَا فِي أَنفُسِكُمْ أَوْ تُخْفُوهُ يُحَاسِبْكُم بِهِ اللّهُ فَيَغْفِرُ لِمَن يَشَاء وَيُعَذِّبُ مَن يَشَاء وَاللّهُ عَلَى كُلِّ شَيْءٍ قَدِيرٌ [البقرة:284]. شق عليهم، وجاءوا إلى النبي ﷺ وقالوا: إن هذا شيء لا نطيقه، فقال: أتريدون أن تقولوا كما قالت بني إسرائيل سمعنا وعصينا؟ قولوا: سمعنا وأطعنا، فقالوا: سمعنا وأطعنا، فلما قالوها وذلت بها ألسنتهم أنزل الله قوله –تعالى-: آمَنَ الرَّسُولُ بِمَا أُنزِلَ إِلَيْهِ مِن رَّبِّهِ وَالْمُؤْمِنُونَ كُلٌّ آمَنَ بِاللّهِ وَمَلآئِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ لاَ نُفَرِّقُ بَيْنَ أَحَدٍ مِّن رُّسُلِهِ وَقَالُواْ سَمِعْنَا وَأَطَعْنَا غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ [البقرة:285]. ثم أنزل الله بعدها: لاَ يُكَلِّفُ اللّهُ نَفْسًا إِلاَّ وُسْعَهَا [البقرة:286]. فنسخت قوله: وَإِن تُبْدُواْ مَا فِي أَنفُسِكُمْ أَوْ تُخْفُوهُ يُحَاسِبْكُم بِهِ اللّهُ. ونسخ الله قوله: أو تخفوه. وسامحهم عما وقع في النفوس في قوله ﷺ في الحديث الصحيح: إن الله تجاوز عن أمتي ما حدثت به أنفسها ما لم تعمل أو تتكلم. فما كان من وساوس الصدور فهو معفو عنه ما لم يعمل العبد أو يتكلم كما دل عليه الحديث الصحيح، ودلت عليه قوله تعالى: لاَ يُكَلِّفُ اللّهُ نَفْسًا إِلاَّ وُسْعَهَا [البقرة:286]. لكن إذا استقر في القلب، وصار عملاً يؤاخذ به الإنسان، إذا استقر في قلبه، من المنكر، ومن الكبر والخيلاء أو نفاق أو غير هذا من أعمال القلوب الخبيثة يؤخذ به الإنسان. أما إذا كان عوارض تخطر في البال، ولا تستقر، فالله لا يحاسبه عليها ، بل يتجاوز عنها -جل وعلا -. فقوله : وَإِن تُبْدُواْ مَا فِي أَنفُسِكُمْ أَوْ تُخْفُوهُ يُحَاسِبْكُم بِهِ اللّهُ هذا بالنسبة إلى المستقر في القلوب، المقيم في القلوب من أعمال القلوب يؤاخذ به الإنسان، من نفاق ورياء وكبر وغير هذا من أعمال القلوب، واعتقاداتٍ باطلة، سواء أظهرها أو أخفاها فهو مؤاخذ بها. أما ما يعرض للإنسان فالله قد سامحه فيه وعفا عنه ، ودلت السنة على أن قوله: يحاسبكم به الله. يعني فيما يستقر، وفيما يبقى في القلوب، أما ما يعرض لها ويزول فالله يسامحه  لقوله ﷺ: إن الله تجاوز عن أمتي ما حدثت به نفسها ما لم تعمل أو تتكلم. فالعمل يكون بالقلب ويكون بالجوارح، فإذا عمل بقلبه، أبغض في الله، وأحب في الله أخذ بهذا، أجر على المحبة، وأثم بالبغضاء إذا أبغض من لا يستحق البغضاء، فالمقصود أن أعمال القلب إذا استقرت يؤخذ بها كالمحبة في الله والبغضاء في الله يؤجر المؤمن. وإذا فعل بقلبه خلاف ذلك من بغض المؤمنين أو التكبر على أحد أو النفاق أو الرياء أخذ بذلك؛ لأن هذه أعمال قلبية كالأعمال الإيمانية سواء سوا. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/28958/ما-معنى-ان-الله-تجاوز-عن-امتي-ما-حدثت-به-انفسها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/شرح حديث إن الله تجاوز عن أمتي ما حدثت به أنفسها ما لم تعمل أو تتكلم.mp3","categories":["شروح الحديث"]},{"id":5044,"question":"ما معنى عرَّس؟","title":"ما معنى \"عَرَّس\" و\"الدُّلَجَة\" في الحديث؟","answer":"الجواب: نزل آخر الليل، التعريس: النزول آخر الليل.\nس: الدُّلَجَة خاصَّة بالدابة أم عامَّة؟\nج: الظاهر أنها عامَّة، ..... الأرض تُطوى، فيحسن للإنسان السير في الليل، وهذا مُجَرَّب، فالسير في الليل سهلٌ على النفوس، خفيفٌ، يقطع مسافةً طويلةً ولا يشعر بالتَّعب، في الغالب يكون برادًا وهدوءًا.","link":"https://binbaz.org.sa/fatwas/29088/ما-معنى-عرس-والدلجة-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما معنى عَرَّس، والدُّلَجَة في الحديث؟.mp3","categories":["شروح الحديث"]},{"id":5051,"question":"المُتحابُّون في الله في نفس الدرجة في الجنة أم يختلفون؟","title":"هل تتفاوت درجات المُتحابِّين في الله في الجنة؟","answer":"الجواب: يقول الله جلَّ وعلا يوم القيامة: أين المتحابون بجلالي؟ اليوم أُظِلُّهم في ظِلِّي يوم لا ظِلَّ إلا ظِلِّي، والحديث الآخر: سبعةٌ يُظِلُّهم اللهُ في ظِلِّه وذكر منهم: المتحابين في الله.","link":"https://binbaz.org.sa/fatwas/29289/هل-تتفاوت-درجات-المتحابين-في-الله-في-الجنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تتفاوت درجات المتحابين في الله في الجنة؟.mp3","categories":["شروح الحديث"]},{"id":5059,"question":"المقصود بنزول السكينة؟","title":"ما معنى نزول \"السكينة\" في الحديث؟","answer":"الجواب: ظاهره أنه مَلَك من الملائكة يُسمَّى السكينة، يَقْرُب وينزل عند سماع الخير وعند سماع الذكر ويرتفع، فالنبي ﷺ لما ذكر له أُسيد بن حُضير أنه كان يقرأ وكان عنده فرس وصار لها..... حتى خشي على ولده، قال لأسيد: تلك السكينة نزلت لسماع القرآن، وكان يرى في السَّماء مثل السُّرُج.","link":"https://binbaz.org.sa/fatwas/29323/ما-معنى-نزول-السكينة-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما معنى نزول السكينة في الحديث.mp3","categories":["شروح الحديث"]},{"id":5065,"question":"أحسن الله إليك، وإن الرَّجُل ليَصْدُق هذا خاص بالرجل أو بالرجل والمرأة؟","title":"هل حديث \"وإن الرَّجُل ليَصْدُق\" يشمل المرأة؟","answer":"الجواب: لا، كل ما قيل للرجل فالمرأة مثله، هذه قاعدة.","link":"https://binbaz.org.sa/fatwas/29362/هل-حديث-وان-الرجل-ليصدق-يشمل-المراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل حديث وإن الرجل ليصدق يشمل المرأة؟.mp3","categories":["شروح الحديث"]},{"id":5070,"question":"ما معنى: خمس رضعات مُشبعات؟","title":"ما معنى: خمس رضعات مُشبعات؟","answer":"الجواب: خمس رضعات، ما في مشبعات، ما أحد يقول: مشبعات، خمس رضعات، لكن ولو غير مشبعات، إذا رضع وابتلع اللبنَ ووصل إلى جوفه اللبنُ ولو ما شبع يُعدّ رضعةً، فإذا عاد وارتضع ثانيةً ولو ما شبع يُعدّ رضعةً ثانيةً، وهكذا، ليس من شرطها أن تكون مُشبعةً.\n س: ولو في مجلسٍ واحدٍ؟\nالشيخ: ولو في مجلسٍ واحدٍ، أو في مجالس.","link":"https://binbaz.org.sa/fatwas/29380/ما-معنى-خمس-رضعات-مشبعات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما معنى خمس رضعات مشبعات؟.mp3","categories":["الرضاع","شروح الحديث"]},{"id":5125,"question":"سائل يقول: ما صحة حديث: إنَّ الله خلق آدم على صورته أو: على صورة الرحمن؟","title":"ما صحة ومعنى حديث \"إنَّ الله خلق آدم على صورته\"؟","answer":"الجواب: الحديث صحيحٌ. ومعنى خلق آدم على صورته أي: سميعًا، بصيرًا، يتكلَّم، ذا عينٍ، وذا يدٍ، وذا قدمٍ، وليس معناه المُشابهة، فإنَّ الله لا يُشبهه شيء: وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ [الإخلاص:4]، لكن معناه: خلقه الله على صورته: سميعًا، بصيرًا، له وجهٌ، وله يدٌ، وله قدمٌ، يعلم، ويسمع، ويُبْصِر، هكذا قال أهلُ السنة: كأحمد وإسحاق وغيرهم، رحمة الله عليهم.","link":"https://binbaz.org.sa/fatwas/30039/ما-صحة-ومعنى-حديث-ان-الله-خلق-ادم-على-صورته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 60.mp3","categories":["شروح الحديث","الحكم على الأحاديث"]},{"id":5127,"question":"ما صفات السبعين ألفًا الذين يدخلون الجنة بغير حسابٍ؟","title":"ما صفات السبعين ألفًا الذين يدخلون الجنة بغير حسابٍ؟","answer":"الجواب: بيَّن النبيُّ ﷺ أنَّهم المُستقيمون على دين الله، فهم سبعون ألفًا، ومع كل ألفٍ سبعون ألفًا، وهم مقدّم هذه الأمة المؤمنة، يتقدَّمونهم في دخول الجنة على صورة القمر ليلة البدر، وهم الذين جاهدوا بأمر الله، واستقاموا على دين الله أينما كانوا، بأداء الفرائض، وترك المحارم، والمُسابقة إلى الخيرات. ومن صفاتهم أنهم: لا يسترقون، ولا يكتوون، ولا يتطيَّرون. لا يسترقون أي: لا يطلبون مَن يرقيهم، ولا يكتوون، وليس معناه تحريم هذا، فلا بأس بطلب الرقية، ولا بأس بالكي عند الحاجة إليهما، ولكن من صفاتهم: ترك ذلك والاستغناء بالأسباب الأخرى. لا يسترقون أي: لا يطلبون مَن يرقيهم، أي: لا يقولون: يا فلان، ارقنا، وإذا دعت الحاجةُ فلا بأس، لا يُخرجه ذلك -إذا دعت الحاجةُ- عن السبعين. ولهذا أمر النبيُّ ﷺ عائشة أن تسترقي في بعض مرضها، وأمر أمَّ أيتام جعفر بن أبي طالب أن تسترقي لهم، كما في الحديث الصَّحيح. وهكذا الكي، فقد كوى بعض أصحابه عليه الصلاة والسلام، وقال: الشفاء في ثلاثٍ: كيَّة نار، أو شرطة محجم، أو شربة عسل، وما أحبُّ أن أكتوي، وقال: أنهى أمتي عن الكي، فالكي آخر الطب، فإذا تيسر الطبُّ الآخر فهو أوْلى، وإذا دعت الحاجةُ إليه فلا بأس. س: إذا ذهب لأحدٍ يرقيه؟ ج: لا بأس، إذا دعت الحاجةُ إلى هذا فلا بأس، لكن تركه أفضل، فإذا تيسر له سببٌ آخر فهو أفضل، إن تيسر له أن يرقيه بدون سؤالٍ أو بسببٍ آخر من الأسباب التي تنفعه فلا بأس وهو أحسن.","link":"https://binbaz.org.sa/fatwas/30043/ما-صفات-السبعين-الفا-الذين-يدخلون-الجنة-بغير-حساب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 64.mp3","categories":["شروح الحديث"]},{"id":5186,"question":"ورد في الحديث الصَّحيح: لعن الله الواشمات والمُستوشمات، والنامصات والمُتنمصات .. إلى آخره، فهل التَّنمُّص مقيدٌ بنتف الحواجب أم بالإمكان إزالة بعض شعر الوجه؟ ثم هل يدخل الرجلُ تحت هذا النَّهي أم هو للنساء فقط؟","title":"ما ضابط النمص؟ وهل يشمل النهيُّ الرجال؟","answer":"الجواب: الحديث صحيحٌ في \"الصحيحين\"، والنَّامصات: اختلف أئمَّةُ اللغة وغريب الحديث؛ فبعضهم خصَّ به الحواجب، وقال: إنه نتف شعر الحواجب، الإنماص هو الإنقاش، وقال آخرون: بل يعمُّ الحاجب، ويعم الوجه كله، وهو نتف الشعر من الوجه مطلقًا: من الخدّين، ومن الحاجبين. ولم يذكروه إلا في النِّساء عند حديث النَّامصات، ولكن مقتضى العلَّة قد يُقال أنه يعمُّ، والحديث جاء في النامصات، ولكن مقتضى العلة -وهو أنه تغييرٌ لخلق الله وتشويه لخلق الله- يعمُّهما جميعًا، فلا يخصّ النساء وإن كان الحديثُ ورد فيهنَّ، فالسبب -والله أعلم- أنهنَّ المُعتادات لذلك، وهن الحريصات على هذا الشيء، يزعمن أنهن يتزيّن بذلك لأزواجهن، فلهذا جاء الحديثُ فيهن، وإلا فالذي يظهر أنه عامٌّ. ولهذا فالوشم حرامٌ حتى على الذكور، وجاء في الحديث: الواشمات، ولو فعلها الرجلُ حرم عليه، فهكذا مسألة النَّمص، فالذي يظهر أنه عامٌّ، وأنه ليس للرجل أن ينمص حاجبيه، وهكذا شعر الوجه؛ لأنَّ الخدين من اللحية، وقد قال في \"القاموس\" وغيره: \"اللحية: ما نبت على الخدّين والذقن\"، وعلى كل حالٍ، فأشده النَّمص، أشد النَّمص ما تعلَّق بالحاجبين.","link":"https://binbaz.org.sa/fatwas/30125/ما-ضابط-النمص-وهل-يشمل-النهي-الرجال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 150.mp3","categories":["شروح الحديث"]},{"id":5254,"question":"يقول السائل: ذُكر في الحديث الشريف عن ابن عباسٍ رضي الله عنهما: أنَّ رسول الله ﷺ ذكر أنه يدخل الجنةَ من أمَّته سبعون ألفًا من غير حسابٍ ولا عذابٍ، فسُئل عنهم ﷺ فقال: هم الذين لا يرقون، ولا يسترقون، ولا يتطيرون، وعلى ربهم يتوكَّلون، فهل معنى هذا أنَّ الرقية الشرعية حرامٌ أو العلاج حرامٌ، وجزاكم الله خيرًا؟","title":"معنى «لا يرقون ولا يسترقون» في الحديث؟","answer":"الجواب: ليس مقصود النبي ﷺ أنَّ هذه الأعمال حرامٌ، مقصوده أنَّ هؤلاء السّبعين ومَن كان مثلهم ومَن أُلحق بهم معناه: أنهم استوفوا ما أوجب الله، وتركوا ما حرَّم الله، حتى تركوا الاسترقاء الذي هو مباحٌ، لكنه مكروهٌ، الاسترقاء: طلب الرقية، الذي يسترقي يطلب الرقية، إلا من حاجةٍ، إن كان من حاجةٍ فلا كراهةَ، والكيّ من حاجةٍ لا كراهة، الطيرةُ شركٌ، ما تجوز مطلقًا، أما الاسترقاء والكي فيجوز عند الحاجة، ويُكره عند عدم الحاجة. والنبي أمر أن يُسترقى لبني جعفر، وأمر عائشة أن تسترقي لما احتاجت، فالاسترقاء لا بأس به عند الحاجة، فالمعنى أنهم تركوا الأشياء المفضولة والمكروهة لكمال إيمانهم وتوكُّلهم، وليس معنى هذا أن الاسترقاء محرمٌ، ولا أنَّ الكي محرَّمٌ، لكنه من كمال توكّلهم تركوا ذلك، واستغنوا عنه، فمَن لم يستغنَ عن ذلك، بل احتاج إلى ذلك؛ فلا جُرم عليه ولا حرج، ولا يخرج بذلك عن السبعين؛ لأنَّ النبي ﷺ رقى ورُقِيَ، وكوى بعض أصحابه، وأمر بالاسترقاء. أما زيادة ولا يرقون فقد أنكرها بعضُ أهل العلم، وإن كان رواها مسلمٌ، لكن جزم بعضُ الحفاظ أنها غلطٌ، وهم من بعض الرواة، وإنما الصواب لا يسترقون، وأما لا يرقون فالصواب أنها وَهْمٌ من بعض الرواة؛ لأن النبي ﷺ رقى ورُقِيَ، ولا يتَّصف بخلاف عمل السّبعين عليه الصلاة والسلام، بل هو رأس السبعين وأفضلهم وخيرهم، عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/30786/معنى-لا-يرقون-ولا-يسترقون-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 1063.mp3","categories":["شروح الحديث"]},{"id":5262,"question":"ما معنى قوله ﷺ عن ليلة القدر، فقال: رأيتها وأنسيتها، ما معناه؟","title":"ما معنى «رأيتها وأنسيتها» في حديث ليلة القدر؟","answer":"الجواب: يعني: أنسيها، ذهبت عن باله، هذا أحسن من نسيها، أُنسيت أحسن من نَسيت؛ لأن أنساه هي من الشيطان، لحكمة بالغة، لكن إذا عرفوا أنها في العشر، وأنه لا يُعلم متى تكون في العشر اجتهدوا في العشر كلها؛ فصار أعظم لأجورهم وأكثر لحسناتهم. س: هل ليلة القدر ثابتة في سبع وعشرين أو متنقلة؟ ج: جاء فيها أحاديث تدل على أن أرجاها ليلة سبع وعشرين، وأنها متنقلة في الأوتار.[1]","link":"https://binbaz.org.sa/fatwas/30876/ما-معنى-رايتها-وانسيتها-في-حديث-ليلة-القدر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/wazayif ramadan 012.mp3","categories":["شروح الحديث"]},{"id":5272,"question":"ما هو قول الزور؟","title":"ما معنى قول الزور والعمل به؟","answer":"الجواب: يعني الكذب. س: الكذب فقط؟ الشيخ: قول الزور الكذب. س: ما يدخل فيه شيء من المُحرَّمات؟ الشيخ: قول الزور غير فعل المحرمات، ذلك العمل به. س: والعمل به؟ الشيخ: العمل به: يعني تعاطي المحرمات؛ لأنه يدعي الإيمان، هو بمعنى عنده شيء من الزور، من الكذب، بتعاطيه المحرمات التي تنقُص إيمانه، تُضْعِف إيمانه، كل المعاصي تضعف الإيمان.[1]","link":"https://binbaz.org.sa/fatwas/30887/ما-معنى-قول-الزور-والعمل-به","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/wazayif ramadan 015.mp3","categories":["شروح الحديث"]},{"id":5297,"question":"يقول في حديث الرسول ﷺ: صنفان من أهل النار لم أرهما بعد: قوم معهم سياط كأذناب البقر يضربون بها الناس ونساء كاسيات عاريات مميلات مائلات رؤوسهن كأسنمة البُخت المائلة لا يدخلن الجنة ولا يجدن ريحها.. إلى آخر الحديث.. ما المقصود بقوله ﷺ: مميلات مائلات رؤوسهن كأسنمة البخت المائلة، هل المراد بذلك هو جعل المرأة شعرها على جهة واحدة من الرأس؟","title":"ما معنى حديث \"رؤوسهن كأسنمة البُخت..\"؟","answer":"الجواب: وضح ﷺ أنهن من أهل النار، وأنهن نساء كاسيات عاريات يلبسن لباسًا لا يسترهن، وهن في الاسم كاسيات والحقيقة عاريات؛ إما لرقته وإما لقصوره وعدم ستره، فهذا من المعاصي التي فعلنها \"كاسيات عاريات\" يعني ملابس غير ساترة، مائلات عن الرشد والهدى، عن العفة، مميلات لغيرهن؛ من الفساد والزنا، فهن لا يبالين بأسباب الزنا كاسيات عاريات، ومع هذا مائلات عن الرشد والهدى إلى الباطل مميلات لغيرهن، ولهذا أخبر أنهن من أهل النار، ورؤوسهن كأسنمة البخت المائلة قال بعض أهل العلم في ذلك: يعني يضخمنها، يحطين عليها تضخيمات فتبدو كبيرة كأنها رأسان كأسنمة البخت المائلة التي لها شبه السنامين لكونهن يضخمن بالخرق أو بغير ذلك مما يكبّر الرؤوس يُلَبّدنهن على رؤوسهن كعلامة لهن، كعنوان لهن، نسأل الله العافية.[1]","link":"https://binbaz.org.sa/fatwas/30947/ما-معنى-حديث-رووسهن-كاسنمة-البخت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 017.mp3","categories":["قضايا المرأة","شروح الحديث"]},{"id":5320,"question":"وما توجيه قوله ﷺ: اللهم إني أسألك بوجهك؟","title":"ما معنى حديث: \"اللهم إني أسألك بوجهك..\"؟","answer":"الجواب: جاء في بعض الأحاديث لا يُسأل بوجه الله إلا الجنة وفي إسناده بعض المقال، ولا ينبغي أن يُسأل بوجه الله إلا الجنة وما يقرب إليها؛ عملًا بالحديث، وإن كان في سنده بعض المقال اليسير، لكن إذا أراد الإنسان يسأل ربه بأسمائه الحسنى غير الوجه، وإذا سأل الله بوجهه الجنة فلا بأس؛ لأنه مما يقرِّب إليها.[1]","link":"https://binbaz.org.sa/fatwas/30981/ما-معنى-حديث-اللهم-اني-اسالك-بوجهك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 039.mp3","categories":["شروح الحديث"]},{"id":5357,"question":"قول النبي ﷺ: أنا بريء ممن أقام بين أظهر المشركين؟","title":"ما معنى \"أنا بريء ممن أقام بين أظهر المشركين\"؟","answer":"الجواب: بريء من كلِّ مسلمٍ يُقيم بين المشركين إذا كان قادرًا. أما إذا عجز يتَّقي الله، فإذا استطاع هاجر، وإذا عجز فهو معذور، لكن يتَّقي الله.[1]","link":"https://binbaz.org.sa/fatwas/31057/ما-معنى-انا-بريء-ممن-اقام-بين-اظهر-المشركين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fat7_majed 011.mp3","categories":["شروح الحديث"]},{"id":5358,"question":"هل يقصد هنا بالنَّفس الذَّات، أحسن الله إليك؟","title":"ما معنى النفس في حديث \"ذكرته في نفسي\"؟","answer":"الجواب: نعم. س: يرد على مَن أنكروا أنَّ لله  ذاتًا؟ ج: الذات والنفس، النفس نفسه، ذاته جلَّ وعلا . س: يعني النفس هي الذات، مُترادفتان؟ ج: الذات وما أراده الله  لا يعلم كيفيتها إلا هو ، نؤمن بنفسه؛ أنَّ له نفسًا على الوجه اللائق به جلَّ وعلا، لا يعلم كيفيتها إلا هو .[1]","link":"https://binbaz.org.sa/fatwas/31059/ما-معنى-النفس-في-حديث-ذكرته-في-نفسي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/tawheed_ibnkhozaima001.mp3","categories":["شروح الحديث","الأسماء والصفات"]},{"id":5375,"question":"في الإسراء أعيدت أجساد الأنبياء؟","title":"هل أُعيدت أجساد الأنبياء في ليلة الإسراء؟","answer":"الجواب: قاموا، مثَّلهم الله بالسَّماوات بأجسادهم أحياء، ثمانية: آدم وعيسى ويحيى ويوسف وإدريس وموسى وهارون وإبراهيم عليهم الصلاة والسلام، رآهم على صفتهم، سلَّموا عليه وكلَّمهم، ولا يمنع هذا موتهم، إلا عيسى فلم يمت، عيسى حتى الآن لم يمت، يموت في آخر الزمان، ينزل إلى الأرض ويحكم بشريعة محمدٍ ثم يموت عند خروج الدَّجال.[1]","link":"https://binbaz.org.sa/fatwas/31109/هل-اعيدت-اجساد-الانبياء-في-ليلة-الاسراء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/dorar_saniya_najdiya005.mp3","categories":["شروح الحديث","فتاوى متنوعة"]},{"id":5386,"question":"مداخل الشيطان الثلاثة السالفة الذكر عليها دليل؟","title":"ما مداخل الشيطان الثلاثة؟ وما أدلتها؟","answer":"الجواب: من القرآن، إذا تأمَّلتَ: الغضب: معلوم أنَّه من أسباب الشيطان، ولما غضب موسى ألقى الألواح، وفيها كلام الرب . والغفلة: مثل ما قال الله جل وعلا: وَلَقَدْ ذَرَأْنَا لِجَهَنَّمَ كَثِيرًا مِنَ الْجِنِّ وَالإِنسِ لَهُمْ قُلُوبٌ لا يَفْقَهُونَ بِهَا وَلَهُمْ أَعْيُنٌ لا يُبْصِرُونَ بِهَا وَلَهُمْ آذَانٌ لا يَسْمَعُونَ بِهَا أُوْلَئِكَ كَالأَنْعَامِ بَلْ هُمْ أَضَلُّ أُوْلَئِكَ هُمُ الْغَافِلُونَ [الأعراف:179]، وقال تعالى: وَمَنْ يَعْشُ عَنْ ذِكْرِ الرَّحْمَنِ نُقَيِّضْ لَهُ شَيْطَانًا فَهُوَ لَهُ قَرِينٌ [الزخرف:36] يعني: ومَن يغفل. وأمَّا الشهوة : فأدلتها كثيرة -نسأل الله العافية- قال جل وعلا في كتابه الكريم: إِنْ يَتَّبِعُونَ إِلَّا الظَّنَّ وَمَا تَهْوَى الأَنْفُسُ [النجم:23]، وقال تعالى: فَإِنْ لَمْ يَسْتَجِيبُوا لَكَ فَاعْلَمْ أَنَّمَا يَتَّبِعُونَ أَهْوَاءَهُمْ (الشهوات) وَمَنْ أَضَلُّ مِمَّنِ اتَّبَعَ هَوَاهُ بِغَيْرِ هُدًى مِنَ اللَّهِ [القصص:50]، نسأل الله العافية، وَأَمَّا مَنْ خَافَ مَقَامَ رَبِّهِ وَنَهَى النَّفْسَ عَنِ الْهَوَى ۝ فَإِنَّ الْجَنَّةَ هِيَ الْمَأْوَى [النازعات:40، 41].[1]","link":"https://binbaz.org.sa/fatwas/31126/ما-مداخل-الشيطان-الثلاثة-وما-ادلتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alwabel _alsaib 002.mp3","categories":["شروح الحديث","فتاوى متنوعة"]},{"id":5387,"question":"لعن الشيطان؟","title":"ما حكم لعن الشيطان؟ وهل التعوُّذ أفضل؟","answer":"الجواب: جائز كما لعنه الله، لكن التَّعوذ بالله من شرِّه أحسن؛ لأنه عند اللعن قد يتعاظم كما جاء في الحديث، لكن عند التعوُّذ بالله من شرِّه يتصاغر. س: الحديث صحيح؟ ج: لا بأس به: لا تقُلْ: تَعِسَ الشيطانُ، بل قُلْ: بسم الله، المقصود أن التعوُّذ بالله من شرِّه أفضل من لعنه، والله لعنه وطرده. س: حديث: لا تلعنوا الشيطان واستعيذوا منه؟ ج: ما أعرفه. س: قصة آدم عليه السلام مع الشيطان: فَلَمَّا آتَاهُمَا صَالِحًا جَعَلَا لَهُ شُرَكَاءَ [الأعراف:190]، صحيحة؟ ج: نص القرآن أنه مع آدم؛ لأن الله قال: هُوَ الَّذِي خَلَقَكُمْ مِنْ نَفْسٍ وَاحِدَةٍ وَجَعَلَ مِنْهَا زَوْجَهَا لِيَسْكُنَ إِلَيْهَا فَلَمَّا تَغَشَّاهَا ... الآية [الأعراف:189]، فالقصة قصة آدم مع زوجته، وقال بعض السلف أن المراد به الذرية، ولكن نص القرآن واضح.[1]","link":"https://binbaz.org.sa/fatwas/31127/ما-حكم-لعن-الشيطان-وهل-التعوذ-افضل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alwabel _alsaib 003.mp3","categories":["شروح الحديث","فتاوى متنوعة"]},{"id":5388,"question":"تعس عبدُ الدينار هنا وقع في الشِّرك؟","title":"ما حكم من جاء فيه «تعس عبدُ الدينار»؟","answer":"الجواب: مَن يعمل للدينار يكون شركًا أصغر، إذا أراد الإنسانُ بعمله الدنيا.\nفإذا كان ما عنده إيمان ولا تقوى صار شركًا أكبر.\nلكن إذا كان إنما علَّم لأجل الدنيا، أو أمر لأجل الدنيا، أو نهى لأجل الدنيا، ما هو لأجل الله؛ يكون من باب الشرك الأصغر: تعس عبد الدينار. \nأما إذا كان لله ولكن أُعطي ما يُعينه؛ فلا بأس، يُعطى من المعاش ما يُعينه على ذلك فلا حرج عليه.[1]","link":"https://binbaz.org.sa/fatwas/31130/ما-حكم-من-جاء-فيه-تعس-عبد-الدينار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alwabel _alsaib 005.mp3","categories":["شروح الحديث"]},{"id":5389,"question":"يقول: (لا طريق إلى الله تعالى أقرب من العبودية، ولا حجابَ أغلظ من الدَّعوى) ما الدعوى؟","title":"ما معنى عبارة \"لا حجابَ أغلظ من الدَّعوى\"؟","answer":"الجواب: العبودية: الانكسار بين يدي الله وطاعته. والدَّعوى: كونه يدَّعي أنه كذا، وأنه كذا، ويمُنُّ بأعماله بأنه تقيّ، وأنه يقوم الليل، وأنه صوَّام، فيُبتلى بالرياء، ويُبتلى بالمنَّة على الله.[1]","link":"https://binbaz.org.sa/fatwas/31128/ما-معنى-عبارة-لا-حجاب-اغلظ-من-الدعوى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alwabel _alsaib 004.mp3","categories":["شروح الحديث","فتاوى متنوعة"]},{"id":5391,"question":"إذا أصرَّ على الكبائر هل تُكفَّر السيئاتُ الصَّغائر؟","title":"هل تُكفَّرُ الصَّغائرُ للمصرِّ على كبيرة؟","answer":"الجواب: مثل ما قال ربك: إِنْ تَجْتَنِبُوا كَبَائِرَ مَا تُنْهَوْنَ عَنْهُ نُكَفِّرْ عَنْكُمْ سَيِّئَاتِكُمْ [النساء:31] يعني: الصغائر، فضل من الله. لكن اختلف الناس في حدِّ الكبيرة، قد يظنها صغيرةً وهي كبيرة، فليحذر السّيئات كلها، صغيرها وكبيرها، يكون عنده حذر؛ لأنه قد يقع في الكبيرة ويحسب أنها صغيرة. س: ما دام مُصِرًّا على كبيرةٍ وصلَّى الصلوات هل تُكفَّر عنه الصَّغائر؟ ج: لا، ما تُكفَّر، الشرط اجتناب الكبائر.[1]","link":"https://binbaz.org.sa/fatwas/31134/هل-تكفر-الصغاىر-للمصر-على-كبيرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alwabel _alsaib 007.mp3","categories":["شروح الحديث","فتاوى متنوعة"]},{"id":5394,"question":"الجمع بين حديث: ولولا أنا لما كان في ضحضاح من النار، والنهي عن قول: لو؟","title":"كيف الجمع بين ورود \"لو\" في بعض الحديث مع النهي عنها؟","answer":"الجواب: محتمل، محتمل؛ لأنَّ هذا من تصرُّف الرواة وغلط بعض الرواة، فيحتمل أنه يجوز؛ لأنَّ بعضَ أهل العلم قال: يجوز، واحتجَّ بهذا الحديث، لولا فلان لهلك فلان، لولا فلان ما نجح فلان. ولكن الذي ينبغي أن يأتي بـ\"ثم\"؛ عملًا بالأدلة كلها: لا تقولوا: ما شاء الله وشاء فلان، قولوا: ما شاء الله ثم شاء فلان، وحديث الأبرص والأقرع: فلا بلاغَ لي اليوم إلا بالله ثم بك، فالسنة هكذا، والأحوط للمؤمن هكذا.","link":"https://binbaz.org.sa/fatwas/31142/كيف-الجمع-بين-ورود-لو-في-بعض-الحديث-مع-النهي-عنها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alwabel _alsaib 011.mp3","categories":["شروح الحديث"]},{"id":5402,"question":"قوله: وإنْ صام وصلَّى وزعم أنه مسلم؟","title":"معنى حديث «وإنْ صام وصلَّى وزعم أنه مسلم»؟","answer":"الجواب: هذا من باب الوعيد، يعني: يحصل له هذا الوعيد، فيكون مُتوعَّدًا بالنار وإن صام وصلَّى، مثل الزاني فهو مُتوعَّد بالنار وإنْ صام وصلَّى.[1]","link":"https://binbaz.org.sa/fatwas/31152/معنى-حديث-وان-صام-وصلى-وزعم-انه-مسلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alwabel _alsaib 017.mp3","categories":["شروح الحديث"]},{"id":5406,"question":"هل الستر على المسلم له ضابط؟","title":"ما ضابط الستر على المسلم العاصي؟","answer":"الجواب: إذا ما أظهر المعصية. أمَّا المجاهر ما له ستر: كُلُّ أُمَّتي مُعافًى إلَّا المُجاهِرِينَ ما دام تستَّر؛ لا تفضحه. س: لو أنَّ واحدًا عُرِف عنه الصلاح، ولكن وقع في معصيةٍ، فهل يُستر عليه؟ ج: يُستر عليه، نعم.[1]","link":"https://binbaz.org.sa/fatwas/31168/ما-ضابط-الستر-على-المسلم-العاصي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alwabel _alsaib 022.mp3","categories":["شروح الحديث"]},{"id":5413,"question":"حديث أبي قتادة: إذا دخل أحدُكم المسجدَ فلا يجلس حتى يُصلي ركعتين الأمر للاستحباب أم للوجوب؟","title":"هل تحية المسجد واجبة أم مستحبة؟","answer":"الجواب: المشهور عند العلماء أنه للاستحباب؛ لقوله ﷺ لما سأله الأعرابي عن الصَّلوات الخمس: هل عليَّ غيرها؟ قال: لا، إلا أن تطوع، ولكن القول بالوجوب قولٌ قويٌّ؛ لأنَّ فيه الأمر: فليركع ركعتين، وفيه النهي فلا يجلس، فينبغي ألا يتساهل في هذا، فإذا دخل وهو طاهر؛ صلَّى ركعتين، ويحذر التَّساهل في هذا. س: إذا كان الأمرُ للاستحباب وأتى للمسجد في وقت نهيٍ يُصلي أم يجلس؟ ج: ولو في وقت نهيٍ، السنة أن يُصلي؛ لأنَّ الأمر عامّ، وهذه من ذوات الأسباب، مثل: صلاة الكسوف، فلو كسفت الشمسُ في العصر يُصليها على الصَّحيح. س: قول الرسول ﷺ للرجل عندما تخطَّى الرقابَ في المسجد يوم الجمعة، قال: اجلس، فقد آذيتَ وآنيتَ فلم يأمره بتحيَّة المسجد؟! ج: لعله قد صلاها، وهذا ما هو بصريح.[1]","link":"https://binbaz.org.sa/fatwas/31181/هل-تحية-المسجد-واجبة-ام-مستحبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alwabel _alsaib 029.mp3","categories":["الأدعية والأذكار","شروح الحديث","مسائل متفرقة في الصلاة"]},{"id":5422,"question":"التعصب لمذاهب أو لأشخاص أو لجماعات، هل يُعتبر من عبادة غير الله؟","title":"حكم التعصب للمذاهب والأشخاص والجماعات؟","answer":"الجواب: لا، هذا منكر لا يجوز. س: ما يعتبر من عبادة غير الله؟ ج: هذا إذا استحلَّه، إذا استحلَّه وأن متبوعه معصومٌ وما قاله حقّ؛ فهذا يدخل في الردة، أمَّا عموم التقليد ففيه تفصيل. س: يقول بعضُهم: \"كلّ ما خالف نصَّ الإمام يُؤول\"؟ ج: هذا غلط، يُنكر عليه ولا بُدَّ، فتراجع النصوص وتُقدَّم النصوص.[1]","link":"https://binbaz.org.sa/fatwas/31209/حكم-التعصب-للمذاهب-والاشخاص-والجماعات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alwabel _alsaib 047.mp3","categories":["شروح الحديث","فتاوى متنوعة"]},{"id":5425,"question":"الأطفال الذين رأوا النبيَّ ﷺ، كالطفل الذي رفعته أمُّه الخثعمية، هل هؤلاء صحابة؟","title":"هل الطفل الذي رأى النبي يُعَدُّ صحابيًا؟","answer":"الجواب: الذي رأى النبيَّ وهو مؤمنٌ تَبَعٌ لأهله: صحابي، رآه النبيُّ ﷺ أو قُدِّم للنبي فحنَّكه. س: ما يُشترط البلوغ؟ ج: لا، ما يُشترط.[1]","link":"https://binbaz.org.sa/fatwas/31206/هل-الطفل-الذي-راى-النبي-يعد-صحابيا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alwabel _alsaib 044.mp3","categories":["شروح الحديث","فتاوى متنوعة"]},{"id":5429,"question":"اسم الله الأعظم ورد في أكثر من حديثٍ أنه الحي القيوم؟","title":"هل \"الحي القيوم\" هو اسم الله الأعظم؟","answer":"الجواب: بمعنى العظيم، مقتضى هذا -والله أعلم- لأنه جاء هذا في أحاديث كثيرة الأعظم، والله أعلم بمعناها، فهو اسم تفضيل بمعنى: العظيم، وكل أسماء الله عظيمة جل وعلا.[1]","link":"https://binbaz.org.sa/fatwas/31202/هل-الحي-القيوم-هو-اسم-الله-الاعظم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alwabel _alsaib 040.mp3","categories":["شروح الحديث","مسائل متفرقة في العقيدة"]},{"id":5440,"question":"بعض الناس إذا أصابه حادثٌ في يوم السبت مثلًا يقول: هذا يوم السبت الأسود، أو المشؤوم، فما حكمه؟","title":"ما حكم التشاؤم بيوم السبت ووصفه بالأسود؟","answer":"الجواب: ما يقول هذا، السبت والأحد ما عنده شيء، لكن يُقال لها: \"أيام نحسات\"، كما قال الله في أيام عادٍ أنها \"أيام نحسات\"، فاليوم الذي أصابه فيه حادث إذا قال أنه \"يوم نحس\" و\"يوم مشؤوم\" فهذا عليه هو، بالنسبة إليه هو، كما قال الله في قصة عادٍ: فَأَرْسَلْنَا عَلَيْهِمْ رِيحًا صَرْصَرًا فِي أَيَّامٍ نَحِسَاتٍ [فصلت:16]. س: بعض الإخوة المقيمين مثلًا يقول بعضُهم لبعضٍ: يومك أسود، فما رأيك في هذا؟ ج: لا ينبغي أن يقول مثل هذا، ينبغي له أن يُخفف عليه ويقول: اصبر يا أخي واحتسب، لا يزيد البلاءَ بلاءً، ويقول له: والأمور بيد الله، والإنسان يُؤجر على المصيبة، مثلما قال ﷺ: عجبًا لأمر المؤمن، إن أمره كله له خير، إن أصابته ضَرَّاء صبر فكان خيرًا، وإن أصابته سَرَّاء شكر فكان خيرًا له، وليس ذلك لأحدٍ إلا للمؤمن، ما يقول: يوم أسود، يوم كذا، أنت ما فيك خير، يقول: اصبر يا أخي، والأمور بيد الله، واصبر وما صبرك إلا بالله، قل: إنا لله وإنا إليه راجعون، وما أشبه هذا من الكلام الطيب.[1]","link":"https://binbaz.org.sa/fatwas/31238/ما-حكم-التشاوم-بيوم-السبت-ووصفه-بالاسود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alwabel _alsaib 057.mp3","categories":["شروح الحديث","التشاؤم والتطير"]},{"id":5444,"question":"حكم قول \"لو\" مُحرَّم أم مكروه؟","title":"ما حكم قول \"لو\"؟ ومتى يجوز استعمالها؟","answer":"الجواب: في الحديث النهي عنها، فهي مُحرَّمة؛ لأن الرسول قال: فلا تقل: لو. س: متى يجوز استعمالها؟ ج: يقولها الإنسانُ في استحباب الخيرات، مثل: لو استقبلتُ من أمري ما استدبرتُ ما أهديتُ كما قال النبي ﷺ يوم الحج، حجة الوداع، قال: لو استقبلتُ من أمري ما استدبرتُ ما أهديتُ ولجعلتُها عمرةً، لو علمتُ أنَّ فلانًا هنا لجئتُه وأكرمتُه، وما أشبه ذلك، لو علمتُ أنَّ الطريق آمنٌ حجزتُ. ما في بأس، من باب تمنّي الخير. س: قَدَرُ الله أم قدَّر الله؟ ج: يُقال: قدَّر الله وقَدَر الله، قَدَرُ الله يعني: هذا قَدَر الله، وقدَّر الله: المفعول محذوف، يعني: قدَّر الله هذا الشيء.[1]","link":"https://binbaz.org.sa/fatwas/31244/ما-حكم-قول-لو-ومتى-يجوز-استعمالها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alwabel _alsaib 060.mp3","categories":["شروح الحديث","فتاوى متنوعة"]},{"id":5452,"question":"النجاشي هل هو صحابي أم تابعي؟","title":"هل النجاشي صحابي أم تابعي؟","answer":"الجواب: لا، ما لقي النبي ﷺ. تابعي؛ لأنه ما لقي النبي ﷺ، إنما مكاتبة.[1]","link":"https://binbaz.org.sa/fatwas/31287/هل-النجاشي-صحابي-ام-تابعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/nuzhat_alnthar 008.mp3","categories":["شروح الحديث","فتاوى متنوعة"]},{"id":5453,"question":"من أدرك النبي ﷺ ولم يلقه؟","title":"هل يكون صحابيًّا من أدرك النبي ولم يلقه؟","answer":"الجواب: هذا ما يُسمى \"صحابي\"، يُسمى \"تابعي\"، مثل الصنابحي، وكعب الأحبار، هؤلاء يقال لهم تابعيون، وإن كانوا أدركوا النبي ﷺ، لكن ما لقوه، مات ولم يلقوه، قدموا المدينة بعد موته ﷺ.[1]","link":"https://binbaz.org.sa/fatwas/31288/هل-يكون-صحابيا-من-ادرك-النبي-ولم-يلقه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/nuzhat_alnthar 009.mp3","categories":["شروح الحديث","فتاوى متنوعة"]},{"id":5477,"question":"ما الفائدة من أخذ العهد عليهم في ظهر أبيهم آدم؟","title":"ما الحكمة من أخذ العهد من ظهور بني آدم؟","answer":"الجواب: هذا يعني على آدم، لا يُؤاخذ به الإنسان، أُخذ هذا العهد على آدم نفسه، أما الإنسان فيُؤخذ بالرسل التي جاءته. س: قوله تعالى: أَلَسْتُ بِرَبِّكُمْ قَالُوا بَلَى [الأعراف:172] ما المراد به؟ ج: هذا في الأصلاب، ولا يُؤاخذ به إلا إذا جاءته الرسل.[1]","link":"https://binbaz.org.sa/fatwas/31369/ما-الحكمة-من-اخذ-العهد-من-ظهور-بني-ادم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al tabseir 002.mp3","categories":["شروح الحديث","فتاوى متنوعة"]},{"id":5485,"question":"رؤية الله في المنام حسيًّا هل ثبت فيها شيء؟","title":"هل رأى النبي ربَّه في المنام؟","answer":"الجواب: رآه النبيُّ ﷺ في حديث الرؤية، رآه النبيُّ عليه الصلاة والسلام في المنام، وصنَّف في ذلك ابنُ رجبٍ رحمه الله تعالى كتابًا.[1]","link":"https://binbaz.org.sa/fatwas/31383/هل-راى-النبي-ربه-في-المنام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al tabseir 009.mp3","categories":["شروح الحديث","فتاوى متنوعة"]},{"id":5487,"question":"ما المراد بقوله ﷺ: \"مَن ترك الجمعة ثلاث مرات تهاونًا بها طبع الله على قلبه\"؟ هل يدخل في هذا الوعيد مَن يتأخر حتى يخرج الإمامُ للخطبة؟ أفيدونا جزاكم الله خيرًا.","title":"ما معنى الوعيد في ترك الجمعة ثلاث مرات تهاونًا؟","answer":"الجواب: هذا الوعيد فيمن فاتته الجمعة ثلاث مرات بغير عذرٍ، طُبع على قلبه، وعيد شديد، وفي الحديث الآخر يقول ﷺ: لينتهينَّ أقوام عن ودعهم الجمعات -يعني: تركهم الجمعات- أو ليختمنَّ الله على قلوبهم، ثم ليكوننَّ من الغافلين رواه مسلم في الصحيح، وكما في الحديث: مَن ترك ثلاث جمعٍ بغير عذرٍ طُبع على قلبه، هذا وعيد عظيم، نسأل الله العافية.[1]","link":"https://binbaz.org.sa/fatwas/31391/ما-معنى-الوعيد-في-ترك-الجمعة-ثلاث-مرات-تهاونا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/sharh_alosol 003.mp3","categories":["شروح الحديث"]},{"id":5490,"question":"الصالحون: ود، وسواع، ويغوث، هل كانوا في زمن نوحٍ أو قبله؟","title":"هل صح أن عبادة الأصنام ستعود مجددًا؟","answer":"الجواب: في زمن نوحٍ. س: لما كانوا أحياء؟ ج: هم موجودون في زمن نوحٍ، ووجودهم قبل نوحٍ، لكن موجودة في زمانه، ثم بقيت في الناس، نسأل الله العافية. س: هناك حديث بأنها ستعود وتُعبد بأعيانها هذه الأصنام؟ ج: لا، في الحديث الصحيح: لا تقوم الساعةُ حتى لا يُقال في الأرض: الله، الله يعني: حتى يعمَّ الشرك -نسأل الله العافية- هي وغيرها إن وُجدت، إن وُجد منها شيء، يعني: تُطبق البلاد على الشرك -نسأل الله العافية- بعدما يُنزع الإيمانُ من قلوب الناس، فإنَّ الله يُرسل ريحًا طيبةً تقبض أرواح المؤمنين، فلا يبقى إلا الكفار، وعليهم تقوم الساعة، نسأل الله العافية.[1]","link":"https://binbaz.org.sa/fatwas/31395/هل-صح-ان-عبادة-الاصنام-ستعود-مجددا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/kashf alshubuhat 003.mp3","categories":["شروح الحديث","فتاوى متنوعة"]},{"id":5492,"question":"هل يجوز أن يُقال لعالم: قد أقامكم الله مفزعًا للمسلمين، وملاذًا للمؤمنين؟","title":"ما حكم قول: \"قد أقامكم الله مفزعًا للمسلمين..\"؟","answer":"الجواب: معناه صحيح: مفزعًا لهم في تحصيل حقوقهم من طريق المحاكم الشرعية، من طريق الإمارة، يفزع لهم الناس لإعطائهم حقوقهم، هذا معناه صحيح، الدعاء لولي الأمر: أن الله يجعله مُوفَّقًا، وأنَّ الله يُعينه على التَّحقيق في حاجات المسلمين، وأن يكون إذا فزعوا إليه حقق طلباتهم من جهة إقامة الحدود، ومن جهة تخليص الحقوق، ومن جهة ردع الظالم، إلى غير ذلك.[1]","link":"https://binbaz.org.sa/fatwas/31396/ما-حكم-قول-قد-اقامكم-الله-مفزعا-للمسلمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/kashf alshubuhat 004.mp3","categories":["شروح الحديث","فتاوى متنوعة"]},{"id":5511,"question":"إذا صارت مُصيبة للكفار، هل يجوز للمسلم أن يفرح؟","title":"هل للمسلم أن يفرح بالمصيبة في بلد الكفار؟","answer":"الجواب: يفرح لها، إذا كان فيها نفعٌ للمسلمين يفرح لها: قُلْ بِفَضْلِ اللَّهِ وَبِرَحْمَتِهِ فَبِذَلِكَ فَلْيَفْرَحُوا هُوَ خَيْرٌ مِمَّا يَجْمَعُونَ [يونس:58]، إذا كان شيء ينفع المسلمين: انهزم جيشهم، هداهم الله للإسلام؛ يفرح. س: إذا كانت زلزلة مثلًا في بلدٍ كافرٍ؟ ج: يفرح؛ لأنها قد تكون موعظةً، قد تكون فيها هداية.[1]","link":"https://binbaz.org.sa/fatwas/31443/هل-للمسلم-ان-يفرح-بالمصيبة-في-بلد-الكفار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/kashf alshubuhat 026.mp3","categories":["شروح الحديث","فتاوى متنوعة"]},{"id":5545,"question":"حديث: من لغا فلا جمعةَ له؟","title":"ما معنى حديث \"مَنْ لغا فلا جمعةَ له\"؟","answer":"الجواب: هذا جاء في \"صحيح مسلم\": مَن مسَّ الحصى فقد لغا، ومَن لغا فلا جمعةَ له، يعني: يفوته فضلها، وأما الحديث هذا فهو كمثل الحمار يحمل أسفارًا فهذا في صحَّته نظر، فمجالد ليس ممن يعتمد عليه؛ اختلط، روايته فيها لين، إلا أن تكون له شواهد، هذا التَّشبيه: \"مَن لغا مثله كمثل الحمار\" أمر عظيم. س: تكون باطلةً أم ناقصةً مَن مسَّ الحصى؟ ج: يفوته فضلها، يعني: ليست له جمعة، يعني: فضل الجمعة، ولا يُعيد، ليس عليه الإعادة. س: مَن لغا فلا جمعةَ له؟ ج: لا فضلَ له، ليس له جمعة، فضل الجمعة. س: الحديث صحّته؟ ج: رواه مسلم في الصحيح.[1]","link":"https://binbaz.org.sa/fatwas/31488/ما-معنى-حديث-من-لغا-فلا-جمعة-له","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/zad almaad 008.mp3","categories":["صلاة الجمعة","شروح الحديث"]},{"id":5550,"question":"وصفه لخطبة رسول الله ﷺ بقوله: خطبةً بليغةً؟","title":"معنى وصف خطبة النبي عليه الصلاة والسلام بأنها بليغةً","answer":"الجواب: يعني عظيمة، بالغ فيها ﷺ، يعني: حمد الله، وأثنى عليه، وذكَّر الناس، وبالغ في تذكيرهم؛ ليحذروا نقمةَ الله. والبليغة هي التي اشتملت على الوعظ والتَّذكير والتَّحذير بألفاظٍ واضحةٍ وبينةٍ، مع الشدة في ذلك وإظهار الخوف عليهم والحذر عليهم. وكان ﷺ إذا خطب اشتدَّ غضبُه، وعلا صوته عليه الصلاة السلام، واحمرَّت عيناه كأنه مُنذر جيشٍ، يقول: صبَّحكم ومسَّاكم، ليست خطبةً ميتةً ضعيفةً، بعض الناس إذا خطب كلامه ضعيف، وكلامه ميت لا يُؤثر في القلوب، بخلاف مَن خطب بقوةٍ وبلاغةٍ، وإيجاد الألفاظ المؤثرة، والصوت المؤثر الذي يشمل اختيار الألفاظ المؤثرة، وإظهار الحزن والخوف على المخاطَبِين.[1]","link":"https://binbaz.org.sa/fatwas/31496/معنى-وصف-خطبة-النبي-عليه-الصلاة-والسلام-بانها-بليغة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/zad almaad 013.mp3","categories":["شروح الحديث","فتاوى متنوعة"]},{"id":5554,"question":"قوله: إنَّ النبي ﷺ أبو المؤمنين؟","title":"هل يصح أن يُقال: النبي عليه الصلاة والسلام أبو المؤمنين؟","answer":"الجواب: نعم. س: الله يقول: مَا كَانَ مُحَمَّدٌ أَبَا أَحَدٍ مِنْ رِجَالِكُمْ [الأحزاب:40]؟ ج: يعني من جهة نفي التَّبني: ادْعُوهُمْ لِآبَائِهِمْ [الأحزاب:5]؛ لهذا في قراءة بعض القُرّاء قوله جلَّ وعلا: النَّبِيُّ أَوْلَى بِالْمُؤْمِنِينَ مِنْ أَنْفُسِهِمْ وَأَزْوَاجُهُ أُمَّهَاتُهُمْ [الأحزاب:6]، قرأ بعضُهم: وهو أبوهم من حيث التربية، أبوة التربية والتَّوجيه، لا أبوة التَّبني، المنفية أبوة التَّبني؛ ولهذا كان يقول لبعض أصحابه: يا بني.[1]","link":"https://binbaz.org.sa/fatwas/31500/هل-يصح-ان-يقال-النبي-عليه-الصلاة-والسلام-ابو-المومنين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/zad almaad 017.mp3","categories":["شروح الحديث","فتاوى متنوعة"]},{"id":5556,"question":"حديث: إذا انتصف شعبان فلا تصوموا؟","title":"ما صحة حديث: «إذا انتصف شعبان فلا تصوموا»؟","answer":"الجواب: صحيحٌ، لا بأس به، رواه الخمسة..... سدًّا لذريعة الزيادة في رمضان، إذا ما صام قبل النصف لا يصوم بعد النصف.\nس: النَّهي للكراهة أم للتَّحريم؟\nج: ظاهره للتَّحريم، هذا الأصل.\nس: في غير مَن كانت له عادة: كأن يصوم يومًا ويُفطر يومًا؟\nج: مَن له عادة لا بأس، مثلما تقدم: إلا رجل كان يصوم صومًا فليصمه، مَن كانت له عادة: يصوم الاثنين والخميس، مثلًا: صادف الاثنين أو الخميس آخر الشهر، يصومه، أو يصوم يومًا ويُفطر يومًا، فصادف يوم صومه يوم الثلاثين، لا بأس.\nس: الجمع بينه وبين حديث: لا تقدموا رمضان بصوم يومٍ ولا يومين؟\nج: حديث: إذا انتصف شعبان فلا تصوموا لفظ نطق به، مُقدم على المفهوم، حديث أبي هريرة مفهومه أنه لا بأس بتقديمه إلى أكثر من يومين، لكن هذا المفهوم غير مُرادٍ، بدليل قوله: إذا انتصف شعبان فلا تصوموا بالنسبة إلى ما بعد النصف يعني.[1]","link":"https://binbaz.org.sa/fatwas/31508/ما-صحة-حديث-اذا-انتصف-شعبان-فلا-تصوموا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/zad almaad 019.mp3","categories":["شروح الحديث"]},{"id":5634,"question":"غيِّروا الشيب للوجوب؟","title":"هل الأمر في حديث \"غيِّروا الشيب\" للوجوب؟","answer":"الجواب: الأصل في الأوامر للوجوب مثل ما قال ﷺ في قصة الصديق غيروا هذا الشيب واجتنبوا السواد، ولكن يظهر من فعل النبي ﷺ وبعض الصحابة ما يدل على عدم وجوبه وأنه سنة مؤكدة التغيير؛ لأنه جاء ما يدل على أنه قد ترى في لحيته شعرات بيض ما غيّرها، وفي الصحابة  كذلك جاء ما يدل على أنه قد يبقون الأيام والليالي والشعر أبيض ثم يغير، فالأقرب -والله أعلم- أنها سنة مؤكدة. س: الحديث صحيح؟ الشيخ: لا بأس به، سنده جيد لا بأس به. س: هل يُستثنى منه أحد، من قال: أن الغزاة في سبيل الله يُستثنون من هذا؟ الشيخ: لا أعلم فيه استثناء.[1]","link":"https://binbaz.org.sa/fatwas/31631/هل-الامر-في-حديث-غيروا-الشيب-للوجوب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/sunan alnisayiy 003.mp3","categories":["شروح الحديث"]},{"id":5635,"question":"الشيب في الجسد كله منهي عن نتفه؟","title":"هل النهي عن نتف الشيب يشمل الجسد كله؟","answer":"الجواب: ظاهر الحديث العموم، نعم، شعر اللحية والرأس يغيّر بالصُّفرة والحُمرة لا بالسواد. س: في الأيدي والأرجل كذلك؟ الشيخ: الأيدي ما فيها شعر، الذي فيه شعر يروح يزيله ما فيه شيء، الكلام في شعر الرأس، وفي شعر اللحية، والشارب، والأيدي والرجل ما هي محل شعر، وبعض الناس يُبتلى بالشعر. س: يدل على أنه كبيرة الفعل هذا؟ الشيخ: ظاهره الوعيد نعم يقتضي أنه كبيرة لا يريحون رائحة الجنة وعيد. س: ألا يفرّق بين من خلصت لحيته بياضًا، وبين من فيها بعض شيء من البياض المختلط بالسواد فيقال؟ الشيخ: كلما كثر الشيب؛ تأكد التغيير. س: متكلم فيه، الزيادة هذه \"واجتنبوا السواد\"؟ الشيخ: بعضهم يراها مُدرجة، والصواب أنها من نفس الحديث ما هي مُدرجة.[1]","link":"https://binbaz.org.sa/fatwas/31633/هل-النهي-عن-نتف-الشيب-يشمل-الجسد-كله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/sunan alnisayiy 004.mp3","categories":["شروح الحديث","اللباس والزينة"]},{"id":5639,"question":"المرتد أعرابيًّا بعد الهجرة؟","title":"ما حكم مَن يرتد أعرابيًّا بعد الهجرة؟","answer":"الجواب: ظاهره المنع، لما منّ الله عليه بالهجرة لا يرتد أعرابيًّا إلا لحاجة، إذا ساءت الحال في المدن خرج للبادية لحفظ دينه، كما في الحديث الصحيح أن النبي ﷺ لما سئل عن خير الناس قال: مؤمن مجاهد في سبيل الله، ثم قال: مؤمن في شعب من الشعاب يعبد الله ويدع الناس من شره. س: يكون التعرُّب كبيرة من غير حاجة؟ الشيخ: التعرب بعد الهجرة نعم، من الكبائر، نعم. س: المرتد أعرابيًّا بعد الهجرة هذا الحكم باقٍ إلى الآن؟ الشيخ: نعم إلا لعلة، إذا فسد المجتمع وخرج من المجتمع لحفظ دينه. س: يعني لا يلزم أن يكون هناك هجرة؟ الشيخ: إذا خرج لأجل حفظ دينه؛ لأن المجتمع الحضاري تغير، أبيح له ذلك.[1]","link":"https://binbaz.org.sa/fatwas/31640/ما-حكم-من-يرتد-اعرابيا-بعد-الهجرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/sunan alnisayiy 008.mp3","categories":["شروح الحديث","فتاوى متنوعة"]},{"id":5649,"question":"قول الرسول ﷺ: لا تتمنّوا لقاء العدو، وإذا لقيتُموهم فاصبروا؟","title":"ما معنى حديث \"لا تتمنّوا لقاء العدو..\"؟","answer":"الجواب: حمله العلماءُ على أنَّ المراد: على سبيل العجب بالنَّفس، على سبيل الثِّقة بالنفس، ونحو ذلك. أما إذا تمنى لقاء العدو؛ رغبةً في الجهاد، أو رغبةً في الشَّهادة في سبيل الله، فهو يبدأ بالجهاد؛ لأنَّ الرسول حثَّ على الجهاد ورغَّب فيه: مَن مات ولم يغزُ، ولم يُحدِّث نفسه بالغزو؛ مات على شُعبةٍ من النِّفاق. فالنَّهي عن التَّمني ليس على إطلاقه، وإنما المراد التَّمني الذي يصحبه فخر وخُيلاء، أو ثقة بالنفس، أما مَن يتمنى أن يحضر الجهاد، ويُجاهد في سبيل الله، وأن يلقى عدو الله؛ فلا بأس به، وليس داخلًا في النَّهي هذا.[1]","link":"https://binbaz.org.sa/fatwas/31685/ما-معنى-حديث-لا-تتمنوا-لقاء-العدو","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alaistiqama 011.mp3","categories":["شروح الحديث"]},{"id":5665,"question":"ما معنى قوله ﷺ: ويلٌ للأعقاب من النار؟","title":"ما معنى حديث \"ويلٌ للأعقاب من النار\"؟","answer":"الجواب: معناها: وجوب غسل الأعقاب، والعناية بها، يغسل الكعبين، لا يتساهل؛ لأنَّ الكعبين من المغسولات، الكعبان والمرفقان، المرفقان يُغسلان مع الذِّراع، والكعبان يُغسلان مع القدمين، يجب غسل الكعبين وغسل المرافق؛ لأنَّ الرسول كان إذا توضأ وغسل يديه أشرع في العضد، وإذا غسل رجليه أشرع في الساق، يعني: غسل الكعبين والمرافق، عليه الصلاة والسلام.[1]","link":"https://binbaz.org.sa/fatwas/31702/ما-معنى-حديث-ويل-للاعقاب-من-النار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aldurus almuhima 011.mp3","categories":["شروح الحديث"]},{"id":5668,"question":"ما قول العلماء المحققين في حديث: إن كان الشُّؤم ففي ثلاثة؟ وهل هناك تعارض مع ما يُروى أنه قال لأهل بيتٍ: ذروها فإنها ذميمة؟","title":"ما معنى حديث \"إن كان الشُّؤم ففي ثلاثة..\"؟","answer":"الجواب: النبي ﷺ قال: الشؤم في ثلاثة: في الدابة، والمرأة، والمنزل، قد يكون الشُّؤم في المنزل، قد يقع في المرأة، قد يكون في الدَّابة، فإذا رأى أنَّ البيت غير مناسبٍ، أو الدابة غير مناسبة، أو المرأة غير مناسبة فلا بأس أن يُطلقها، يتبين هذا من حال الدابة، ومن حال المنزل، ومن حال المرأة، جزم النبي قال: الشؤم في ثلاثة.[1]","link":"https://binbaz.org.sa/fatwas/31705/ما-معنى-حديث-ان-كان-الشوم-ففي-ثلاثة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aldurus almuhima 014.mp3","categories":["شروح الحديث","التشاؤم والتطير"]},{"id":5776,"question":"ما هو تفسير الآية في قوله تعالى: حَتَّى إِذَا بَلَغَ أَشُدَّهُ وَبَلَغَ أَرْبَعِينَ سَنَةً [الأحقاف: 15]؟ ما هو صحة الكلام لقد سمعت أن أهل المدينة إذا بلغ منهم الشخص أربعين سنة تفرغ للعبادة؟","title":"الحث على العمل والاجتهاد في العبادة دائماً","answer":"الجواب: الآية واضحة في معناها، أما ما ورد عن أهل المدينة ما عندي خبر عن هذا، قد يكون بعض الناس فعله، لا أعلم هذا، الشرع يدل على أنه ينبغي للمؤمن أن يعمل أبدًا، ويجتهد في العبادة أبدًا، سواء كان ابن أربعين، أو ابن ستين، والآية لا تخالف ذلك.  الآية فيها أنه يشكر الله -جل وعلا- ويحمده، ويثني عليه  ويسأل الله الذرية الصالحة، وليس فيها أن يعطل العمل، بل فيها العمل وَأَنْ أَعْمَلَ صَالِحًا تَرْضَاهُ [الأحقاف:15].","link":"https://binbaz.org.sa/fatwas/1102/الحث-على-العمل-والاجتهاد-في-العبادة-داىما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_108.mp3","categories":["التفسير","شروح الحديث"]},{"id":5838,"question":"ما هو حكم الإسلام فيما ذهب إليه الشيخ محمد عبده في إحلال الربا، وإلغاء تعدد الزوجات؟","title":"الرد على من يحل الربا ويمنع تعدد الزوجات","answer":"الجواب:  إحلال الربا أمر خطير لا يحل الربا إلا كافر، لكن من قال: إنه يحل الربا؟! من قال: إنه يمنع تعدد الزوجات؟! هذا يحتاج إلى مراجعة كتبه، ولا علينا من الأشخاص، إنما علينا من الحكم، حكم الله -جل وعلا- أما الأشخاص فكل يخطئ ويصيب، كل يغلط إلا من عصمه الله، وعافاه، وإلا فبنو آدم معرضون للخطأ، والأغلاط. ومحمد عبده له أغلاط، وغيره له أغلاط، لكن المقصود أن الربا لا يجوز إحلاله من الناس أبدًا، ومن أحله عن عمد، وعن بصيرة يعلم أنه ربا، ثم يحله، يعاند الله، ويخالف أمر الله؛ فيكون كافرًا -نعوذ بالله- كالذي يحل الزنا، أو يحل الخمر؛ يكون كافرًا. أما إذا غلط، واجتهد في بعض أنواع الربا، ورأى أن هذا جائز لأجل كذا وكذا، وشبه عليه؛ فهذا له حكم المجتهدين، إن أصاب؛ فله أجران، وإن أخطأ؛ فله أجر. وكذلك تعدد الزوجات كثير من المستشرقين النصارى، وغيرهم من اليهود، وغيرهم كتبوا في ذلك، وانتقدوا الإسلام! وانتقدوا الشريعة في تعدد الزوجات! وهم الغالطون، وهم المنتقدون، وهم الضالون، وكثير منهم يعرف ذلك، ولكن العناد، والحسد، والبغي، وإلا فكثير منهم يعرف أن ما جاءت به الشريعة من تعدد الزوجات هو الحق، وهو الحل لمشاكل الناس، وقد كتب في ذلك منصفوهم من رجال ونساء، واعترفوا أن ما جاء به الإسلام من التعدد هو الحق والهدى، وهو الطريق لإنقاذ البشرية مما وقعت فيه من الفساد في الأخلاق، ولكنهم يجحدون هذا في بعض الأحيان، إما خوفًا من رؤسائهم، وكبرائهم، وإما لأجل متاع يأخذونه من هناك، فيخافون أن يضيع عليهم، وإما لحسد المسلمين، والبغي على المسلمين، والعدوان على المسلمين -نعوذ بالله- هذه طريقة الكفرة، وإلا فالمنصفون منهم يعلمون أن تعدد الزوجات فيه مصالح كثيرة، وفيه خير كثير، وهو من أسباب حل المشاكل القائمة في العصر، من كثرة السفاح، والزنا، والفواحش. وكثير من هؤلاء النصارى الذين يزعمون أن التعدد منكر يتخذ زوجة واحدة، ويتخذ معها عشرات الخدينات، والمسافحات، فأي فرق بين هذا وهذا؟! المسلم يأخذ زوجات مسلمات، يأخذ زوجات أحلهن الله له، وأولئك يأخذون مسافحات، زانيات، فاجرات، فرق بين المسلم وبين هؤلاء، فالمسلم في خير عظيم إذا تزوج ثنتين، أو ثلاثًا، أو أربعًا على شرع الله، قد أباح الله له ذلك، وإن عدل فهو على خير عظيم، وأولئك الجهلة الظالمون ينتقدون الإسلام في تعدد الزوجات، وهم -والعياذ بالله- يتمتعون بالزانيات، والفاجرات بلا عدد يحصر، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/1173/الرد-على-من-يحل-الربا-ويمنع-تعدد-الزوجات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_171.mp3","categories":["الربا والصرف","زكاة النقدين","قضايا المرأة","شروح الحديث"]},{"id":5958,"question":"يقول الله تعالى في سورة النساء: وَقَدْ نَزَّلَ عَلَيْكُمْ فِي الْكِتَابِ أَنْ إِذَا سَمِعْتُمْ آيَاتِ اللَّهِ يُكْفَرُ بِهَا وَيُسْتَهْزَأُ بِهَا فَلَا تَقْعُدُوا مَعَهُمْ حَتَّى يَخُوضُوا فِي حَدِيثٍ غَيْرِهِ إِنَّكُمْ إِذًا مِثْلُهُمْ [النسا :140] إلى آخر الآية ما معنى الآية؟ وما صفة الاستهزاء، والكفر بها؟ وهل معنى ذلك الجلوس مع  أهل المعاصي، وحضور المنكرات، أم ماذا؟","title":"معنى قوله تعالى: (وقد نزل عليكم في الكتاب...)","answer":"الجواب: هذه آية تمنع من حضور المؤمنين من يخوض في آيات الله بغير حق، بل يجب عليه الإعراض عنهم، وعدم الجلوس معهم إذا خاضوا في الباطل بالمنكرات، يجب أن لا يجلس معهم إلا إذا أنكر عليهم، وأجابوا، وتركوا ما هم فيه، فهذا لا بأس.  أما إذا أصروا على البقاء في خوضهم الباطل، واستهزائهم بآيات الله، فيجب عليه أن يفارقهم، وإنكار ذلك بالفعل، والقول جميعًا. والاستهزاء بآيات الله معروف، والطعن فيها، والسخرية بها هذا كفر، وردة عن الإسلام، نعوذ بالله؛ فيجب الحذر من هؤلاء، ويجب الإنكار عليهم، والتشديد عليهم، ورفعهم إلى ولاة الأمور، حتى يردعوا عن باطلهم، وحتى يعاملوا بما يجب شرعًا.  وأما من أعلن المعاصي فهو أقل من ذلك، من أعلن المعاصي دون الشرك بالله، فيجب أن ينكر عليه أيضًا،ويخوف من أمر الله، ويحذر، لكن إذا أصر على إظهار المعاصي، لا يجلس معه أيضًا، بل يفارق، ولا يحضر؛ لأنه في مفارقته إنكار عليه بالقول، والفعل جميعًا.","link":"https://binbaz.org.sa/fatwas/1331/معنى-قوله-تعالى-وقد-نزل-عليكم-في-الكتاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_300.mp3","categories":["التفسير","شروح الحديث"]},{"id":5959,"question":"أحسن الله إليك، إذا قال: أسألك بنور وجهك الذي أشرقت له؟","title":"حكم قول: أسألك بنور وجهك الذي أشرقت له..","answer":"الجواب: ما فيه بأس، هذا ورد في بعض الأحاديث: أسألك بنور وجهك الذي أشرقت له السماوات، والأرض لا بأس به، نوره عظيم  به أشرقت الدنيا.","link":"https://binbaz.org.sa/fatwas/1326/حكم-قول-اسالك-بنور-وجهك-الذي-اشرقت-له","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_295.mp3","categories":["شروح الحديث","التوسل والشفاعة"]},{"id":5994,"question":"ما معنى قول الرسول ﷺ: نصرت بالرعب مسيرة شهر؟ وهل هو خاص به ﷺ أم له، ولأمته من بعده؟","title":"معنى: «نصرت بالرعب مسيرة شهر»","answer":"الجواب:  قول النبي ﷺ: نصرت بالرعب مسيرة شهر على ظاهره، وأن الله -جل وعلا- يلقي في قلوب أعدائه الرعب، وهم عنه بعيدون مسافة شهر كالشام عن المدينة، والعراق، ونحو ذلك، ينصره الله عليهم بالرعب.  فإذا وصل إليهم إذ الرعب قد تمكن منهم، وكان ذلك من أسباب نصره عليهم، ومن أسباب خذلانهم، وانخلاع قلوبهم عن المقاومة، وهكذا في أمته، هذا ليس خاصًا به ﷺ بل أعطاه الله، وأمته ذلك.  فأمته المستقيمة على دينه، والصابرون على دينه، والمقيمون لشريعته ينصرها الله كما نصره، ويلقي في قلوب عدوها الرعب مسافة شهر، كما نصر نبيه بذلك -عليه الصلاة والسلام- لأن هذا من جملة خصائصه التي له، ولأمته -عليه الصلاة والسلام- فمن استقام على دينه، وجاهد في سبيله ابتغاء مرضاته، وإعلاء لكلمته، فالله ينصره، ويؤيده، ويلقي الرعب في قلوب عدوه مسافة شهر.","link":"https://binbaz.org.sa/fatwas/1412/معنى-نصرت-بالرعب-مسيرة-شهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_358.mp3","categories":["الجهاد والسير","شروح الحديث"]},{"id":6064,"question":"قال تعالى: بسم الله الرحمن الرحيم: وَقُلِ الْحَقُّ مِنْ رَبِّكُمْ فَمَنْ شَاءَ فَلْيُؤْمِنْ وَمَنْ شَاءَ فَلْيَكْفُرْ [الكهف: 29]، ويقول رسول الله ﷺ: أمرت أن أقاتل الناس حتى يشهدوا أن لا إله إلا الله، وأن محمدًا رسول الله إلى آخر الحديث، كيف يمكن التوفيق بين نص الآية، ونص الحديث، والرد على أعداء الإسلام الذين يدعون أن الإسلام انتشر بالسيف؟","title":"الجمع بين: {فَمَنْ شَاءَ فَلْيُؤْمِنْ} و «أمرت أن أقاتل الناس»","answer":"الجواب: هذه الآية مكية قبل أن يؤمر بالقتال، هذه الآية مكية من سورة الكهف، والكهف سورة مكية فيها الإعراض عن الكفرة، وعدم قتالهم، بل يدعو إلى الله من شاء آمن، ومن شاء كفر، يدعو إلى الله، ويعلم الناس الخير، فمن شاء آمن، وقبل، ومن شاء لم يقبل، وحسابه على الله. فأنت الآن بين الناس في غالب الدنيا هكذا ترشد الناس إلى الخير، وتعلمهم دين الله، فمن قبل منك؛ فالحمد لله، ومن لم يقبل فأمره إلى الله، ليس إليك، ليس عليك هداهم، ولكن الله يهدي من يشاء، إنما عليك البلاغ، وعلى الله الحساب  وأما النبي ﷺ فقال هذا بعدما هاجر، بعدما قوي، وعنده قوة، وعنده جيش، قال هذا الكلام أمرت أن أقاتل الناس حتى يشهدوا أن لا إله إلا الله، وأني رسول الله، ويقيموا الصلاة ويؤتوا الزكاة فإذا فعلوا ذلك؛ عصموا مني دماءهم، وأموالهم إلا بحق الإسلام، وحسابهم على الله. وقال -جل وعلا- في كتابه العظيم: فَإِذَا انْسَلَخَ الْأَشْهُرُ الْحُرُمُ فَاقْتُلُوا الْمُشْرِكِينَ حَيْثُ وَجَدْتُمُوهُمْ وَخُذُوهُمْ وَاحْصُرُوهُمْ وَاقْعُدُوا لَهُمْ كُلَّ مَرْصَدٍ فَإِنْ تَابُوا وَأَقَامُوا الصَّلَاةَ وَآتَوُا الزَّكَاةَ فَخَلُّوا سَبِيلَهُمْ [التوبة:5] هذا قاله الله -جل وعلا- لنبيه بعدما هاجر، وبعدما استقر المسلمون، وقوي المسلمون، وصار لهم جيش، وقوة، خاطبهم الله بهذا. فأنت إذا كان عندك جيش، وقوة تستطيع أن تقاتل بها أوروبا، وأمريكا؛ فقم بهذا الأمر، وما دمت لا تستطيع هذا؛ فعليك بالدعوة إلى الله، والإرشاد إليه، وتعليم الناس الخير، وإرشادهم إليه، واحفظ لسانك عما يضر الدعوة، وعما يفرق الكلمة، وعما يسبب المشاكل التي تحرم الناس الخير، وتوقعهم في الشر.","link":"https://binbaz.org.sa/fatwas/1474/الجمع-بين-فمن-شاء-فليومن-و-امرت-ان-اقاتل-الناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_404.mp3","categories":["التفسير","شروح الحديث"]},{"id":6131,"question":"ما معنى العبارة: (لحق بالرفيق الأعلى) عندما مات رسول الله ﷺ؟","title":"بيان معنى قوله: \"لحق بالرفيق الأعلى\"","answer":"الجواب: الرفيق الأعلى هم الرسل، والأنبياء، والصالحون الذين قال فيهم -جل وعلا-: وَمَنْ يُطِعِ اللَّهَ وَالرَّسُولَ فَأُولَئِكَ مَعَ الَّذِينَ أَنْعَمَ اللَّهُ عَلَيْهِمْ مِنَ النَّبِيِّينَ وَالصِّدِّيقِينَ وَالشُّهَدَاءِ وَالصَّالِحِينَ وَحَسُنَ أُولَئِكَ رَفِيقًا [النساء:69] وقال عند الموت: اللهم في الرفيق الأعلى لأن هؤلاء الرفيق الأعلى قد دخلوا الجنة، وصاروا إليها من الرسل، وأتباعهم، وهو يطلب ربه أن يكون معهم، مع أولئك الأخيار الذين أطاعوا الله، ورسوله، وصاروا إلى الجنة، والكرامة، هم الرفيق الأعلى المقصودين في قوله سبحانه: وَمَنْ يُطِعِ اللَّهَ وَالرَّسُولَ فَأُولَئِكَ مَعَ الَّذِينَ أَنْعَمَ اللَّهُ عَلَيْهِمْ مِنَ النَّبِيِّينَ وَالصِّدِّيقِينَ وَالشُّهَدَاءِ وَالصَّالِحِينَ وَحَسُنَ أُولَئِكَ رَفِيقًا [النساء:69] الله يجعلنا وإياكم منهم.","link":"https://binbaz.org.sa/fatwas/1572/بيان-معنى-قوله-لحق-بالرفيق-الاعلى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_477.mp3","categories":["شروح الحديث","الجهاد والسير"]},{"id":6140,"question":"كثير من الناس لا يصلون إلا الجمعة، وأوقات رمضان فقط، ويحتجون بحديث: الجمعة إلى الجمعة ورمضان إلى رمضان مكفرات لما بينهما فهل هذا العمل صحيح؟","title":"حكم ترك الواجبات احتجاجاً بحديث: «الجمعة إلى الجمعة»","answer":"الجواب: هذا الاستدلال جهل جهل صرف، الله أوجب علينا صلاة الجماعة، وأوجب علينا الجمعة، وأوجب علينا صوم رمضان، فعلينا أن نؤدي الواجبات، والصلوات كلها، وأن نؤدي الجمعة، ونصوم رمضان، ونفعل كل ما أوجب الله علينا، ولنا في هذا أجر عظيم، وعسانا إذا فعلنا هذا كله، واجتهدنا، وابتعدنا عما حرم الله؛ عسى أن ننجو، لعلنا ننجو من عذاب الله، لعلنا نقبل. أما أن نحتج بصلاة الجمعة، وما رتب الله عليها من كفارة، أو رمضان، ثم نضيع الواجبات هذا لا يقوله من يؤمن بالله، واليوم الآخر، هذا لا يقوله من يعقل، ومن اعتقد أن صلاة الجمعة تكفي عن بقية الصلوات؛ فهو كافر ضال مضل، نسأل الله العافية. ومن اعتقد أن صوم رمضان يسقط عنه التكاليف، وله أن يفعل ما شاء من المعاصي، فهذا أيضًا ضال مضل، وكافر بالله، نعوذ بالله!. أجمع المسلمون قاطبة على أن رمضان لا يسقط الواجبات عن الآخرين، وأن صلاة الجمعة لا تسقط الواجبات الأخرى، فصلاة الجمعة لا تسقط صلاة الفجر، ولا صلاة العصر، والفجر، ولا صلاة العصر، والمغرب، والعشاء في وقتها في يومها، إذ لا يسقط بها إلا صلاة الظهر فقط الجمعة، وأما بقية الأيام فعند جميع أهل العلم لا بدّ منها، لا بدّ من الصلوات الخمس في بقية الأيام، كما أنه لا بدّ من الصلوات الأربع في يوم الجمعة العصر، والمغرب، والعشاء، والفجر يوم الجمعة هذه لا بدّ منها.  فمن زعم أن صلاة الجمعة تسقط عنه هذه الفرائض كلها، واعتقد ذلك؛ فهذا كفر، وضلال، وعليه أن يبادر بالتوبة إلى الله  لأن هذا إسقاط للواجبات، واستحلال للمحرمات، فمن فعله معتقدًا له بعدما تقام عليه الحجة، ويبين له كفر، وضل بذلك، وهكذا رمضان صوم رمضان لا يسقط الواجبات، لا صلاة، ولا زكاة، ولا غير ذلك مما يجب. صوم رمضان فريضة على العبد أن يقوم بها، وأن يؤدها، والله -جل وعلا- جعل له في ذلك أجرًا، وثوابًا، فلا يكون ثواب رمضان مسقطًا لبقية الواجبات، وقد قال -عليه الصلاة والسلام-: الصلوات الخمس، والجمعة إلى الجمعة، ورمضان إلى رمضان مكفرات لما بينهن ما لم تغش الكبائر فإذا غشي الكبيرة؛ حرم ثواب الصيام -نسأل الله العافية- حرم ثواب الصلوات، حرم ثواب الجمعة، فلا يحصل له ثوابها إلا باجتنابه الكبائر، يعني المعاصي كما قال -جل وعلا-: إِنْ تَجْتَنِبُوا كَبَائِرَ مَا تُنْهَوْنَ عَنْهُ نُكَفِّرْ عَنْكُمْ سَيِّئَاتِكُمْ وَنُدْخِلْكُمْ مُدْخَلًا كَرِيمًا [النساء:31] فلا يحصل تكفير السيئات، وإدخال الجنة إلا لمن تجنب الكبائر. فالمقصود: أن هذا كلام جاهل، الذي يقول: إن صلاة الجمعة، ورمضان تكفي عن بقية الواجبات، ويكفّر بها من جميع المحرمات، هذا من الجهل العظيم الذي لا يعقل له معنى، بل هو مخالف للنصوص، ومخالف لإجماع المسلمين، نسأل الله العافية. ولعله إذا أدى الواجبات كلها، وترك المحارم كلها، لعله يوفق، لعله يقبل، لعله تكفر سيئاته، لعله يفوز بالجنة، وإذا أعجب بذلك، ومنَّ على الله بذلك؛ فهو حري بالحرمان، وعدم القبول، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/1614/حكم-ترك-الواجبات-احتجاجا-بحديث-الجمعة-الى-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_508.mp3","categories":["شروح الحديث","حكم الصلاة وأهميتها"]},{"id":6150,"question":"كثير من الناس لا يصلون إلا الجمعة، وأوقات رمضان فقط، ويحتجون بحديث: الجمعة إلى الجمعة ورمضان إلى رمضان مكفرات لما بينهما فهل هذا العمل صحيح؟","title":"حكم ترك الواجبات احتجاجاً بحديث: «الجمعة إلى الجمعة»","answer":"الجواب: هذا الاستدلال جهل جهل صرف، الله أوجب علينا صلاة الجماعة، وأوجب علينا الجمعة، وأوجب علينا صوم رمضان، فعلينا أن نؤدي الواجبات، والصلوات كلها، وأن نؤدي الجمعة، ونصوم رمضان، ونفعل كل ما أوجب الله علينا، ولنا في هذا أجر عظيم، وعسانا إذا فعلنا هذا كله، واجتهدنا، وابتعدنا عما حرم الله؛ عسى أن ننجو، لعلنا ننجو من عذاب الله، لعلنا نقبل. أما أن نحتج بصلاة الجمعة، وما رتب الله عليها من كفارة، أو رمضان، ثم نضيع الواجبات هذا لا يقوله من يؤمن بالله، واليوم الآخر، هذا لا يقوله من يعقل، ومن اعتقد أن صلاة الجمعة تكفي عن بقية الصلوات؛ فهو كافر ضال مضل، نسأل الله العافية. ومن اعتقد أن صوم رمضان يسقط عنه التكاليف، وله أن يفعل ما شاء من المعاصي، فهذا أيضًا ضال مضل، وكافر بالله، نعوذ بالله!. أجمع المسلمون قاطبة على أن رمضان لا يسقط الواجبات عن الآخرين، وأن صلاة الجمعة لا تسقط الواجبات الأخرى، فصلاة الجمعة لا تسقط صلاة الفجر، ولا صلاة العصر، والفجر، ولا صلاة العصر، والمغرب، والعشاء في وقتها في يومها، إذ لا يسقط بها إلا صلاة الظهر فقط الجمعة، وأما بقية الأيام فعند جميع أهل العلم لا بدّ منها، لا بدّ من الصلوات الخمس في بقية الأيام، كما أنه لا بدّ من الصلوات الأربع في يوم الجمعة العصر، والمغرب، والعشاء، والفجر يوم الجمعة هذه لا بدّ منها.  فمن زعم أن صلاة الجمعة تسقط عنه هذه الفرائض كلها، واعتقد ذلك؛ فهذا كفر، وضلال، وعليه أن يبادر بالتوبة إلى الله  لأن هذا إسقاط للواجبات، واستحلال للمحرمات، فمن فعله معتقدًا له بعدما تقام عليه الحجة، ويبين له كفر، وضل بذلك، وهكذا رمضان صوم رمضان لا يسقط الواجبات، لا صلاة، ولا زكاة، ولا غير ذلك مما يجب. صوم رمضان فريضة على العبد أن يقوم بها، وأن يؤدها، والله -جل وعلا- جعل له في ذلك أجرًا، وثوابًا، فلا يكون ثواب رمضان مسقطًا لبقية الواجبات، وقد قال -عليه الصلاة والسلام-: الصلوات الخمس، والجمعة إلى الجمعة، ورمضان إلى رمضان مكفرات لما بينهن ما لم تغش الكبائر فإذا غشي الكبيرة؛ حرم ثواب الصيام -نسأل الله العافية- حرم ثواب الصلوات، حرم ثواب الجمعة، فلا يحصل له ثوابها إلا باجتنابه الكبائر، يعني المعاصي كما قال -جل وعلا-: إِنْ تَجْتَنِبُوا كَبَائِرَ مَا تُنْهَوْنَ عَنْهُ نُكَفِّرْ عَنْكُمْ سَيِّئَاتِكُمْ وَنُدْخِلْكُمْ مُدْخَلًا كَرِيمًا [النساء:31] فلا يحصل تكفير السيئات، وإدخال الجنة إلا لمن تجنب الكبائر. فالمقصود: أن هذا كلام جاهل، الذي يقول: إن صلاة الجمعة، ورمضان تكفي عن بقية الواجبات، ويكفّر بها من جميع المحرمات، هذا من الجهل العظيم الذي لا يعقل له معنى، بل هو مخالف للنصوص، ومخالف لإجماع المسلمين، نسأل الله العافية. ولعله إذا أدى الواجبات كلها، وترك المحارم كلها، لعله يوفق، لعله يقبل، لعله تكفر سيئاته، لعله يفوز بالجنة، وإذا أعجب بذلك، ومنَّ على الله بذلك؛ فهو حري بالحرمان، وعدم القبول، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/1614/حكم-ترك-الواجبات-احتجاجا-بحديث-الجمعة-الى-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_508.mp3","categories":["شروح الحديث","حكم الصلاة وأهميتها"]},{"id":6256,"question":"ما كلامكم عن الحديث الذي رواه مسلم في صحيحه عن ابن عباس قال: جمع رسول الله ﷺ بين الظهر، والعصر، والمغرب، والعشاء من غير خوف، ولا مطر؟","title":"لما جمع النبي بين الصلاتين من غير خوف ولا مطر؟","answer":"الجواب: هذا حديث مشهور، رواه البخاري ومسلم في الصحيحين: أن النبي -عليه الصلاة والسلام- جمع بين المغرب، والعشاء، صلى ثمان جميعًا، وسبعًا جميعًا، المغرب، والعشاء، والظهر، والعصر، وفي رواية مسلم زيادة: من غير خوف، ولا مطر، وفي رواية أخرى: ولا سفر.  قال العلماء: إنه جمع لعذر غير هذه الثلاث: إما مرض، وإما دحض في الأسواق على آثار المطر، قال ابن عباس: لئلا يحرج أمته، وتحريجها إما بوجود مطر، أو آثاره من وجود الدحض في الأسواق، أو وباء عام، أضعف الناس، وشق عليه، فلهذا جمع -عليه الصلاة والسلام- أو لأنه أراد أن يبين للناس أنه يجوز الجمع، ثم استقرت الشريعة على تحريم الجمع إلا لعذر، كما جاءت الأدلة بعد ذلك، فإنه وقت للناس المواقيت، وبين لهم المواقيت أولها، وآخرها، ثم قال: الصلاة بين هذين الوقتين وقال عمر : الجمع من غير عذر من الكبائر، فالجواب عن هذا من وجوه: أحدها: أنه جمع لعذر شرعي، كالدحض في الأسواق، أو لمرض عام. الوجه الثاني: لئلا يحرج أمته بأسباب وقعت في ذلك الوقت من أجلها جمع؛ لأجل ألا يحرجهم، ولم يبين هذا التحريج ما هو، الذي سبب الجمع.  والوجه الثالث: أنه جمع قبل أن تستقر الشريعة في وجوب كل صلاة في وقتها، وعدم جواز الجمع إلا من علة، ثم استقرت الشريعة على أنه لا يجوز الجمع إلا لعلة واضحة من مرض، أو نحوه، أو سفر. السؤال: ما معنى الدحظ؟ الجواب: الدحظ الزلق، الطين الذي تزل فيه الأقدام.","link":"https://binbaz.org.sa/fatwas/1765/لما-جمع-النبي-بين-الصلاتين-من-غير-خوف-ولا-مطر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_604.mp3","categories":["شروح الحديث","أحكام الجمع"]},{"id":6265,"question":"ما كلامكم عن الحديث الذي رواه مسلم في صحيحه عن ابن عباس قال: جمع رسول الله ﷺ بين الظهر، والعصر، والمغرب، والعشاء من غير خوف، ولا مطر؟","title":"لما جمع النبي بين الصلاتين من غير خوف ولا مطر؟","answer":"الجواب: هذا حديث مشهور، رواه البخاري ومسلم في الصحيحين: أن النبي -عليه الصلاة والسلام- جمع بين المغرب، والعشاء، صلى ثمان جميعًا، وسبعًا جميعًا، المغرب، والعشاء، والظهر، والعصر، وفي رواية مسلم زيادة: من غير خوف، ولا مطر، وفي رواية أخرى: ولا سفر.  قال العلماء: إنه جمع لعذر غير هذه الثلاث: إما مرض، وإما دحض في الأسواق على آثار المطر، قال ابن عباس: لئلا يحرج أمته، وتحريجها إما بوجود مطر، أو آثاره من وجود الدحض في الأسواق، أو وباء عام، أضعف الناس، وشق عليه، فلهذا جمع -عليه الصلاة والسلام- أو لأنه أراد أن يبين للناس أنه يجوز الجمع، ثم استقرت الشريعة على تحريم الجمع إلا لعذر، كما جاءت الأدلة بعد ذلك، فإنه وقت للناس المواقيت، وبين لهم المواقيت أولها، وآخرها، ثم قال: الصلاة بين هذين الوقتين وقال عمر : الجمع من غير عذر من الكبائر، فالجواب عن هذا من وجوه: أحدها: أنه جمع لعذر شرعي، كالدحض في الأسواق، أو لمرض عام. الوجه الثاني: لئلا يحرج أمته بأسباب وقعت في ذلك الوقت من أجلها جمع؛ لأجل ألا يحرجهم، ولم يبين هذا التحريج ما هو، الذي سبب الجمع.  والوجه الثالث: أنه جمع قبل أن تستقر الشريعة في وجوب كل صلاة في وقتها، وعدم جواز الجمع إلا من علة، ثم استقرت الشريعة على أنه لا يجوز الجمع إلا لعلة واضحة من مرض، أو نحوه، أو سفر. السؤال: ما معنى الدحظ؟ الجواب: الدحظ الزلق، الطين الذي تزل فيه الأقدام.","link":"https://binbaz.org.sa/fatwas/1765/لما-جمع-النبي-بين-الصلاتين-من-غير-خوف-ولا-مطر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_604.mp3","categories":["شروح الحديث","أحكام الجمع"]},{"id":6315,"question":"عندنا طائفة في اليمن يقال لهم: المكارمة، يجمعون صلاة الظهر، والعصر باستمرار، ويكون هذا الجمع بين الوقتين، فما رأي الإسلام في ذلك؟ وما هي عقيدة المكارمة؟","title":"حكم الجمع بين الظهر والعصر والمغرب والعشاء من غير عذر","answer":"الجواب: هذا معروف عن الشيعة المكارمة، الشيعة الباطنية، ومعروف عن الشيعة في غالب أنواعهم أنهم يجمعون بين الظهر والعصر، والمغرب والعشاء، وهذا خطأ عند أهل السنة والجماعة، وغلط، النبيﷺ وقت الأوقات، وبينها، فلما بين وقت الظهر، والعصر، وبين المغرب، والعشاء؛ قال: الصلاة بين هذين الوقتين، وعلمه جبرائيل ذلك.. فالوقت محفوظ بينه الله  فهو موضح بالكتاب، والسنة، مبين في القرآن الكريم، وفي السنة المطهرة عن النبي -عليه الصلاة والسلام- فعلى المسلمين أن يعملوا بذلك، وأن يصلوا الصلاة في وقتها، الظهر في وقتها، والعصر في وقتها، والمغرب في وقتها، والعشاء في وقتها، والفجر في وقتها، ولا يجوز لهم التأسي بمن خالف أمر الله، وابتدع في الدين ما لم يأذن به الله من الشيعة، وغير الشيعة، وعلى من يتصل بهم أن ينصحهم، ويقول لهم: إذا كنتم مسلمين؛ فاستقيموا على طريق الإسلام، وصلوا الصلاة لوقتها.  والمكارمة بلغنا عنهم أنهم على دين الباطنية، ولكن يخفون ذلك، وقد سألت بعض رؤسائهم، وقادتهم؛ فأبى أن يخبرني، وقال : نحن على دينكم، وعلى طريقتكم، وليس عندنا ما يخالفكم، فلم يستطع أن يبين لنا شيئًا من عقيدته. ولكن المشهور عن أهل العلم الذين عرفوهم أنهم على دين الباطنية، وعلى دين الرافضة في تعظيم أهل البيت، ودعائهم من دون الله، وعبادتهم من دون الله، كعلي، والحسن، والحسين، وفاطمة، يدعونهم من دون الله، وبهم يستغيثون، ولهم ينذرون، ولهم يذبحون، هكذا بلغنا عن الرافضة، ومن أشباههم من الباطنية.  ولكن بعضهم ينافق؛ إذا كان المسلمون ينافق، ولا يبين ذلك، ويخفيه، ولكنهم قد يتظاهرون بشيء من بدعهم، كهذه البدعة التي هي الجمع بين الصلاتين من دون عذر، أما إن كان لعذر كالمسافر؛ يجمع ما في بأس، المريض يجمع لعذر؛ لا بأس. السؤال: ويقولون في الأذان: حي على خير العمل؟ الجواب:  بدعة أيضًا، قولهم في الأذان: حي على خير العمل، وقولهم في الأذان: أشهد أن عليًّا ولي الله، بدعة، ما هو في الأذان الصحيح، هذه بدعة زادوها، والكلام مثل ما سمعتم، ما في هذه الزيادة، هذه الزيادة باطلة، ولا أساس لها.","link":"https://binbaz.org.sa/fatwas/1896/حكم-الجمع-بين-الظهر-والعصر-والمغرب-والعشاء-من-غير-عذر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_679.mp3","categories":["أحكام الجمع","شروح الحديث"]},{"id":6441,"question":"صلى رجل بالجماعة المغرب في وقت مطر، وجمع العشاء مع المغرب، ولكن قصر العشاء، وذلك عن عدم معرفته بصفة الجمع، وبعد يوم ذلك علمت بهذا، فقلت لهم أعيدوا صلاتكم، هل أنا مخطئ في هذا؟","title":"حكم قصر العشاء بنية الجمع مع المغرب وقت المطر","answer":"الجواب: أنت مصيب، القصر ليس إلا للمسافر خاصة، فالمريض، والذي يجمع في الحضر ما له قصر، بعض العامة يسمى الجمع قصرًا، القصر كونه يصلي الأربع ثنتين، هذا القصر، أما جمع الظهر إلى العصر، والمغرب إلى العشاء هذا يسمى جمعًا، ما يسمى قصرًا، ضم العصر إلى الظهر في المطر، والمرض، وضم المغرب إلى العشاء في المطر، والسفر، والمرض، هذا يسمى جمعًا، ما يسمى قصرًا، وإذا جمع من أجل المرض، أو من أجل المطر؛ فإنه يصلي الظهر أربعًا، والعصر أربعًا، والعشاء أربعًا، ما يصلي ثنتين، ثنتين، هذه للمسافر خاصة، ما نعلم أنه يصلي ثنتين إلا المسافر في السفر خاصة. أما المريض في البلد، أو في المطر حال المطر، أو الدحض هذا يصلي أربعًا، فإذا جمع بين المغرب، والعشاء؛ صلى المغرب ثلاثًا، والعشاء أربعًا، هذا بإجماع أهل العلم، ليس فيه خلاف بين أهل العلم، أجمع المسلمون على أن صلاة الحضر أربع، ولو في حال المطر، والمرض يصلي أربعًا، الظهر والعصر والعشاء يصليها أربعًا، والفجر على حالها ثنتين، والمغرب على حالها ثلاث، في كل وقت في السفر والحضر.  والذين صلوا العشاء ثنتين بسبب المطر، وهم في الحضر، والبلد فهؤلاء قد غلطوا غلطًا قبيحًا بإجماع المسلمين، وعليهم أن يعيدوا صلاة العشاء، عليهم أن يعيدوها إذا طال الفصل، أما إن نبهوا في الحال كملوها في الحال، وكفى، لكن لو طال الفصل، ما تنبهوا إلا بعد ما طال الفصل؛ يعيدونها، الإمام والمأموم يعيدونها جميعًا. السؤال: يعيدونها جماعة؟ الجواب: إن تيسر جماعة فهو أفضل، وإلا كل يعيدها في بيته.","link":"https://binbaz.org.sa/fatwas/2176/حكم-قصر-العشاء-بنية-الجمع-مع-المغرب-وقت-المطر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_802.mp3","categories":["أحكام الجمع","شروح الحديث"]},{"id":6443,"question":"وآخر يقول: بعد أن كثرت الأمطار في هذه الأيام -والحمد لله رب العالمين-  ما حكم جمع المغرب مع العشاء أثناء نزول المطر وقت المغرب؟ وأيهما أفضل الجمع، أم عدمه؟","title":"حكم جمع الصلاة وقت هطول الأمطار","answer":"الجواب: هذا يختلف، إذا كان المطر جيدًا يؤذي المارة؛ فإن هذا يسيغ الجمع، جمع المغرب والعشاء، وعلى الصحيح من الظهر، والعصر أيضًا؛ إذا دعت الحاجة.  أما إذا كان شيئًا خفيفًا، وليس هناك دحض في الأسواق، مسفلتة، معبدة، والمطر شيء يسير، لا يؤذي؛ فلا جمع، تصلي كل صلاة في وقتها، لكن إذا جاءت المشقة من المطر، أو من الدحض في الأسواق؛ لا بأس بالجمع.","link":"https://binbaz.org.sa/fatwas/2155/حكم-جمع-الصلاة-وقت-هطول-الامطار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_797.mp3","categories":["أحكام الجمع","شروح الحديث"]},{"id":6459,"question":"ورد عن الرسول ﷺ أنه قال : من جاءه من أخيه معروف من غير مسألة، ولا بإشراف نفس؛ فليقبله، ولا يرده، فإنما هو رزق ساقه الله إليه نرجو من سماحتكم مشكورين شرح هذا الحديث؟","title":"شرح حديث: «وما جاءك من هذا المال وأنت غير مشرف»","answer":"الجواب: هذا الحديث رواه مسلم في الصحيح عن ابن عمر -رضي الله عنهما- أن النبي ﷺ أعطى عمر شيئًا من المال كان عمر يريد مالًا، فأعطاه النبي بعض الشيء، فقال عمر: يا رسول الله أعطه من هو أحوج إليه مني، فقال له النبي ﷺ: خذه، وتموله، أو تصدق به، وما جاءك من هذا المال وأنت غير مشرف، ولا سائل؛ فخذه، وما لا فلا تتبعه نفسك. فالنبي ﷺ أمر عمر أن يقبل ما جاءه من بيت المال، ومن جنس هذا المال من غير سؤال، ولا إشراف نفس، فإن شاء تموله، وجعله في حاجاته، وإن شاء تصدق به، فأنت إذا جاءك مال ليس من طريق الربا، ولا من طريق القمار، بل هدية من أخيك فاقبله، أو من بيت المال فاقبله، فإن شئت تموله في حاجاتك، في طعامك، وشرابك، وملابسك في أهل بيتك، وإن شئت فتصدق به على من شئت إذا كنت لا تريده، أو تتبرع عنه، تصدق به على من يحتاج إليه من الفقراء، ولا ترده إلا بأسباب، إلا إذا كان له أسباب الرد.  إذا أعطاك المال من أجل أن تشهد له بالزور لا تقبل هذا المال، إذا أعطي القاضي المال ليحكم عليه بالجور، ليس للقاضي أن يقبل هذا المال، ما يجوز له؛ لأنه يكون رشوة إذا أعطاك المال من أجل معصية تفعلها معه، أو له ما يجوز، أما إذا أعطاك المال أحبك في الله، أو لأنك فقير، أو لأجل الرحم فلا ترده إلا إذا كنت تعلم أنه خبيث، أنه سرقه، أنه ظلمه من زيد، أو عمر، فرده حينئذ؛ لأنه اكتسبه بما حرم الله، وتعدى على عباد الله، أو تأخذه منه، وتعطيه صاحبه إذا عرفت أنه سرقه من فلان، أو ظلمه فلان، أو غصبه من فلان؛ فخذه، ورده إلى صاحبه؛ فتكون صاحب خير، وتكون محسنا بذلك. فالحاصل: أن المال إذا جاءك من طريق لا بأس به، فخذه، ولا ترده، إن شئت تتصرف به لنفسك، وإن شئت فتصدق به، أو اصرفه في مشروع الخير، أما إذا جاء من طريق غير شرعية، من طريق الرشوة، من طريق السرقة، والظلم للناس؛ فلا تقبله، ولا تعن على معاصي الله.","link":"https://binbaz.org.sa/fatwas/2209/شرح-حديث-وما-جاءك-من-هذا-المال-وانت-غير-مشرف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_830.mp3","categories":["شروح الحديث","الجهاد والسير"]},{"id":6462,"question":"صلى رجل بالجماعة المغرب في وقت مطر، وجمع العشاء مع المغرب، ولكن قصر العشاء، وذلك عن عدم معرفته بصفة الجمع، وبعد يوم ذلك علمت بهذا، فقلت لهم أعيدوا صلاتكم، هل أنا مخطئ في هذا؟","title":"حكم قصر العشاء بنية الجمع مع المغرب وقت المطر","answer":"الجواب: أنت مصيب، القصر ليس إلا للمسافر خاصة، فالمريض، والذي يجمع في الحضر ما له قصر، بعض العامة يسمى الجمع قصرًا، القصر كونه يصلي الأربع ثنتين، هذا القصر، أما جمع الظهر إلى العصر، والمغرب إلى العشاء هذا يسمى جمعًا، ما يسمى قصرًا، ضم العصر إلى الظهر في المطر، والمرض، وضم المغرب إلى العشاء في المطر، والسفر، والمرض، هذا يسمى جمعًا، ما يسمى قصرًا، وإذا جمع من أجل المرض، أو من أجل المطر؛ فإنه يصلي الظهر أربعًا، والعصر أربعًا، والعشاء أربعًا، ما يصلي ثنتين، ثنتين، هذه للمسافر خاصة، ما نعلم أنه يصلي ثنتين إلا المسافر في السفر خاصة. أما المريض في البلد، أو في المطر حال المطر، أو الدحض هذا يصلي أربعًا، فإذا جمع بين المغرب، والعشاء؛ صلى المغرب ثلاثًا، والعشاء أربعًا، هذا بإجماع أهل العلم، ليس فيه خلاف بين أهل العلم، أجمع المسلمون على أن صلاة الحضر أربع، ولو في حال المطر، والمرض يصلي أربعًا، الظهر والعصر والعشاء يصليها أربعًا، والفجر على حالها ثنتين، والمغرب على حالها ثلاث، في كل وقت في السفر والحضر.  والذين صلوا العشاء ثنتين بسبب المطر، وهم في الحضر، والبلد فهؤلاء قد غلطوا غلطًا قبيحًا بإجماع المسلمين، وعليهم أن يعيدوا صلاة العشاء، عليهم أن يعيدوها إذا طال الفصل، أما إن نبهوا في الحال كملوها في الحال، وكفى، لكن لو طال الفصل، ما تنبهوا إلا بعد ما طال الفصل؛ يعيدونها، الإمام والمأموم يعيدونها جميعًا. السؤال: يعيدونها جماعة؟ الجواب: إن تيسر جماعة فهو أفضل، وإلا كل يعيدها في بيته.","link":"https://binbaz.org.sa/fatwas/2176/حكم-قصر-العشاء-بنية-الجمع-مع-المغرب-وقت-المطر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_802.mp3","categories":["أحكام الجمع","شروح الحديث"]},{"id":6464,"question":"وآخر يقول: بعد أن كثرت الأمطار في هذه الأيام -والحمد لله رب العالمين-  ما حكم جمع المغرب مع العشاء أثناء نزول المطر وقت المغرب؟ وأيهما أفضل الجمع، أم عدمه؟","title":"حكم جمع الصلاة وقت هطول الأمطار","answer":"الجواب: هذا يختلف، إذا كان المطر جيدًا يؤذي المارة؛ فإن هذا يسيغ الجمع، جمع المغرب والعشاء، وعلى الصحيح من الظهر، والعصر أيضًا؛ إذا دعت الحاجة.  أما إذا كان شيئًا خفيفًا، وليس هناك دحض في الأسواق، مسفلتة، معبدة، والمطر شيء يسير، لا يؤذي؛ فلا جمع، تصلي كل صلاة في وقتها، لكن إذا جاءت المشقة من المطر، أو من الدحض في الأسواق؛ لا بأس بالجمع.","link":"https://binbaz.org.sa/fatwas/2155/حكم-جمع-الصلاة-وقت-هطول-الامطار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_797.mp3","categories":["أحكام الجمع","شروح الحديث"]},{"id":6499,"question":"التشاؤم من أعمال الجاهلية، فكيف يجمع بين النهي عن التشاؤم، وبين إثباته في ثلاث، الشؤم في ثلاث المرأة، والمسكن، والمركب؟","title":"الجمع بين النهي عن التشاؤم و «الشؤم في ثلاث»","answer":"الجواب: مثل ما تقدم التشاؤم أصله مذموم، ومن أعمال الجاهلية، وهو من جنس التطير، إلا في ثلاث، يستثنى، هذا مستثنى، قال النبي ﷺ: الشؤم في ثلاث بالجزم، وفي رواية إن كان الشؤم ففي ثلاث وجزم في عدة أحاديث -عليه الصلاة والسلام- بأنه يكون في ثلاث: في المرأة والدابة والمنزل. فهذا قد يقع فيها شؤم، بعض النساء مشؤومات، بعض المنازل مشؤوم، وبعض الدواب مشؤومة، فمن شؤم المنزل أن من دخله يمرض، بعض المنازل من دخلها يمرض، مشؤوم على أهلها، فإذا عرف بهذا المنزل؛ يترك ينتقل عنه، إذا جرب. كذلك بعض الدواب فيها شؤم، من ركبها؛ سقط، تؤذي راكبها، المقصود أنها يظهر منها أشياء تؤذي أهلها بطرح الراكب، أو في إيذاءها للراكب، أو ما أشبه ذلك من كثرة نفورها، وإيذائها للراكب، فإذا عرف منها ذلك؛ تركت، واستعيض عنها بغيرها، واستعمل في شيء آخر مما يستطيع استعمالها، أو تذبح إن كانت تؤكل، ونحو ذلك.  وكذلك المرأة، بعض النساء مشؤوم بسبب سوء خلقها، وبسبب سوء أعمالها، وبسبب ضعف دينها، إلى أسباب أخرى تكون مشؤومة عليه، من أسباب فقره، ومن أسباب أمراضه، ومن أسباب أشياء أخرى تسلط عليه بأسبابها، فلو عرف هذا من سيرتها، ومن أخلاقها، فإذا عرف ذلك؛ فطلاقها أولى، هذا المعنى عند أهل العلم.","link":"https://binbaz.org.sa/fatwas/2254/الجمع-بين-النهي-عن-التشاوم-و-الشوم-في-ثلاث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_877.mp3","categories":["شروح الحديث","التشاؤم والتطير"]},{"id":6503,"question":"إذا هم الإنسان بفعل ذنب ما، ومنعه مانع خارجي، هل عليه نفس الوزر إذا فعل هذا الذنب بنص حديث: هما في الوزر سواء وكيف يوفق بين هذا الحديث وحديث: من هم بسيئة، ولم يفعلها؛ كتبت له حسنة؟","title":"الجمع بين: «مًنْ همَّ بسيئة» و «هما في الوزر سواء»","answer":"الجواب: الرسول -عليه الصلاة والسلام- صرح بأن الله  كتب الحسنات والسيئات، وبين ذلك  كما جاء في الصحيحين من حديث ابن عباس، وأن من هم بالسيئة فلم يعملها، لم تكتب عليه، وإن تركها من أجل الله؛ كتبها الله حسنة؛ لأنه تركها من جراء الله، وإن هم بالحسنة كتبها الله حسنة، فإن عملها؛ كتبها الله عشر حسنات، إلى سبعمائة ضعف، إلى أضعاف كثيرة.  وأما ما جاء في حديث أبي كبشة الأنماري: الدنيا لأربعة ذكر منهم: رجل أعطاه الله مالا وعلما فهو يتقي في ماله ربه ويصل فيه رحمه فهو في أعلى المنازل، ورجل أعطاه الله علما ولم يعطه مالا فقال: لو كان لي مثل فلان لعملت فيه مثل عمله، قال فهما في الأجر سواء، والثالث أعطي مالا ولم يعط علما فهو لا يتقي فيه ربه ولا يصل فيه رحمه ولا يعمل لله فيه حقا فهو بشر المنازل -نعوذ بالله، والرابع رجل لم يعط علما ولا مالا فهو يقول : لو كان لي مالا مثل فلان لعملت فيه مثل عمله قال -عليه الصلاة والسلام-: فهما في الوزر سواء بسبب النية الخبيثة، نسأل الله العافية. لا شك أن هذا قد يشكل مع الحديث الصحيح الذي فيه أن النية الطيبة تنفع، ويؤجر صاحبها، والسيئة إذا لم يعمل لا تكتب عليه، وإن تركها من أجل الله كتبت حسنة، وفي حديث أبي كبشة الأنماري أن هذا الرجل الذي قال : لو كان لي مثل فلان -يعني من المال- لعملت مثل عمله السيئ قال: فهما في الوزر سواء.  والجواب عن هذا -والله أعلم-: أن هذا في حق من صمم على هذا، وعزم عليه، ولم يمنعه إلا العجز، وإلا فهو مصمم على أن يعمل بالمعاصي، والسيئات التي يعملها ذاك الرجل الذي أعطاه الله المال بلا علم، فهو مثله في الوزر لتصميمه، وعزمه الصادق، وما علم الله من قلبه من الخبث، والفساد فهو مثل الذي قال فيه النبي ﷺ: إذا التقى المسلمان بسيفهما؛ فالقاتل والمقتول في النار قيل يا رسول الله: هذا القاتل فما بال المقتول؟ قال: لأنه كان حريصًا على قتل صاحبه فجعله معه في النار -نسأل الله العافية- لأنه حريص، ما منعه إلا العجز، وإلا فقد جاء بالسيف، وأعد العدة، وحاول القتل، لكن غلبه صاحبه، فقتله، فهما في النار سواء، هذا بأنه قتل، وهذا بأنه حاول القتل.  فهذا الرجل الذي في حديث أبي كبشة يقول: لو كان لي من المال مثل فلان لعملت فيه مثل عمله يعني مصمم، ومريد هذا، وعنده عزم عليه، وجد لو وجد ذلك، ولكن منعه الفقر ومنعه العجز، فهذا -والعياذ بالله- حري بأن يكون مثله في الفساد، والشر، والإثم، نسأل الله العافية. بخلاف الذي همَّ، ثم ترك؛ فهذا ما عزم، هم، ثم ترك، فهذا ليس عليه شيء، أو ترك من أجل الله، فهذا له حسنة، أما هذا هم، وعزم، وصمم على أنه يعمل مثل فلان، ولكن غلبه صاحبه بالقتل، أو عزم، وصمم، ولكن لم يقدر له المال، ولم يسعف المال، وهو مصمم، فهذا يفيد الحذر من التصميم على السيئات، والعزم عليها، وأن في ذلك خطر عظيم، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/2245/الجمع-بين-من-هم-بسيىة-و-هما-في-الوزر-سواء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_866.mp3","categories":["شروح الحديث","الجهاد والسير"]},{"id":6509,"question":"كيف الجمع بين حديث قتل السكران بعد الرابعة، أي شربه بعد الرابعة، وحديث لا يحل دم امرئ مسلم إلا بإحدى ثلاث؟","title":"الجمع بين: قتل السكران بعد الرابعة، و «لا يحل دم امرئٍ»","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله، وأصحابه، ومن اهتدى بهداه، أما بعد:  فقد تقدم قبل الصلاة في الندوة، والتعليق عليها ما يدل على شدة تحريم المسكرات، والمخدرات، وعظيم الأضرار، والأخطار المترتبة عليها في الدنيا، والآخرة، وقد ورد عنه ﷺ أنه أمر بقتل شارب الخمر في الرابعة، ولو يحد في الأولى، ويحد في الثانية بالجلد، ويحد في الثالثة بالجلد، فإذا عاد في الرابعة يقتل؛ لأنه بذلك صار معتادًا للفساد، ويعسر تركه، لذلك فكان في قتله إراحة للناس من شره، وحماية له أيضًا من البقاء على التكرار فيما يضره، ولا ينفعه. ولكن جمهور أهل العلم، وأكثر أهل العلم قالوا: إن هذا منسوخ، وإن قتله في الرابعة منسوخ بقوله ﷺ: لا يحل دم امرئ مسلم يشهد ألا إله إلا الله، وأني رسول الله إلا بإحدى ثلاث: الثيب الزاني، والنفس بالنفس، والتارك لدينه المفارق للجماعة. قالوا: وهذا يدل على أن من عدا هؤلاء الثلاثة لا يقتل، بل يعامل بما يجب من حد، وتعزير، ومن قال بقتله قال: إنه مستثنى، وأنه قام عليه الدليل، فيستثنى من هذه الثلاث، ويقتل من أجل فساده في الأرض، وأن تكراره لشرب الخمر، واعتياده لذلك يجعله من المفسدين، ومن المروجين للباطل؛ فيقتل؛ ليراح الناس من شره، والمجتمع من أضراره. وهذا -كما قال المحققون من أهل العلم- محل نظر، فإن ولي الأمر ينظر في هذا الأمر، ويجتهد، فإن رأى قتل من تكررت منه هذه المفسدة؛ قتله، وإن رأى أن يعيد عليه الجلد مرة رابعة، وخامسة، وسادسة؛ فلا بأس، فينظر في الأصلح الذي يرجى فيه مصلحة الأمة، ومرضاة الرب .  وهكذا المروجون من باعة الخمر، وغيرهم من المخدرات، والمفترات، ولي الأمر ينظر في ذلك، فيزيد في العقوبة، والتعزير على حسب كثرة الترويج، والفساد من باعة هذه الأشياء، ومروجيها، وقد يفضي التعزير إلى أن يقتل هذا المروج حتى يراح الناس من نشره الفساد، ولا يصار إلى القتل إلا عند الضرورة، وعند الحاجة القصوى إذا لم يرتدع بالحدود الشرعية، والتعزيرات الشرعية، نسأل الله السلامة.","link":"https://binbaz.org.sa/fatwas/2262/الجمع-بين-قتل-السكران-بعد-الرابعة-و-لا-يحل-دم-امرى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_885.mp3","categories":["شروح الحديث","الجهاد والسير"]},{"id":6525,"question":"إذا هم الإنسان بفعل ذنب ما، ومنعه مانع خارجي، هل عليه نفس الوزر إذا فعل هذا الذنب بنص حديث: هما في الوزر سواء وكيف يوفق بين هذا الحديث وحديث: من هم بسيئة، ولم يفعلها؛ كتبت له حسنة؟","title":"الجمع بين: «مًنْ همَّ بسيئة» و «هما في الوزر سواء»","answer":"الجواب: الرسول -عليه الصلاة والسلام- صرح بأن الله  كتب الحسنات والسيئات، وبين ذلك  كما جاء في الصحيحين من حديث ابن عباس، وأن من هم بالسيئة فلم يعملها، لم تكتب عليه، وإن تركها من أجل الله؛ كتبها الله حسنة؛ لأنه تركها من جراء الله، وإن هم بالحسنة كتبها الله حسنة، فإن عملها؛ كتبها الله عشر حسنات، إلى سبعمائة ضعف، إلى أضعاف كثيرة.  وأما ما جاء في حديث أبي كبشة الأنماري: الدنيا لأربعة ذكر منهم: رجل أعطاه الله مالا وعلما فهو يتقي في ماله ربه ويصل فيه رحمه فهو في أعلى المنازل، ورجل أعطاه الله علما ولم يعطه مالا فقال: لو كان لي مثل فلان لعملت فيه مثل عمله، قال فهما في الأجر سواء، والثالث أعطي مالا ولم يعط علما فهو لا يتقي فيه ربه ولا يصل فيه رحمه ولا يعمل لله فيه حقا فهو بشر المنازل -نعوذ بالله، والرابع رجل لم يعط علما ولا مالا فهو يقول : لو كان لي مالا مثل فلان لعملت فيه مثل عمله قال -عليه الصلاة والسلام-: فهما في الوزر سواء بسبب النية الخبيثة، نسأل الله العافية. لا شك أن هذا قد يشكل مع الحديث الصحيح الذي فيه أن النية الطيبة تنفع، ويؤجر صاحبها، والسيئة إذا لم يعمل لا تكتب عليه، وإن تركها من أجل الله كتبت حسنة، وفي حديث أبي كبشة الأنماري أن هذا الرجل الذي قال : لو كان لي مثل فلان -يعني من المال- لعملت مثل عمله السيئ قال: فهما في الوزر سواء.  والجواب عن هذا -والله أعلم-: أن هذا في حق من صمم على هذا، وعزم عليه، ولم يمنعه إلا العجز، وإلا فهو مصمم على أن يعمل بالمعاصي، والسيئات التي يعملها ذاك الرجل الذي أعطاه الله المال بلا علم، فهو مثله في الوزر لتصميمه، وعزمه الصادق، وما علم الله من قلبه من الخبث، والفساد فهو مثل الذي قال فيه النبي ﷺ: إذا التقى المسلمان بسيفهما؛ فالقاتل والمقتول في النار قيل يا رسول الله: هذا القاتل فما بال المقتول؟ قال: لأنه كان حريصًا على قتل صاحبه فجعله معه في النار -نسأل الله العافية- لأنه حريص، ما منعه إلا العجز، وإلا فقد جاء بالسيف، وأعد العدة، وحاول القتل، لكن غلبه صاحبه، فقتله، فهما في النار سواء، هذا بأنه قتل، وهذا بأنه حاول القتل.  فهذا الرجل الذي في حديث أبي كبشة يقول: لو كان لي من المال مثل فلان لعملت فيه مثل عمله يعني مصمم، ومريد هذا، وعنده عزم عليه، وجد لو وجد ذلك، ولكن منعه الفقر ومنعه العجز، فهذا -والعياذ بالله- حري بأن يكون مثله في الفساد، والشر، والإثم، نسأل الله العافية. بخلاف الذي همَّ، ثم ترك؛ فهذا ما عزم، هم، ثم ترك، فهذا ليس عليه شيء، أو ترك من أجل الله، فهذا له حسنة، أما هذا هم، وعزم، وصمم على أنه يعمل مثل فلان، ولكن غلبه صاحبه بالقتل، أو عزم، وصمم، ولكن لم يقدر له المال، ولم يسعف المال، وهو مصمم، فهذا يفيد الحذر من التصميم على السيئات، والعزم عليها، وأن في ذلك خطر عظيم، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/2245/الجمع-بين-من-هم-بسيىة-و-هما-في-الوزر-سواء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_866.mp3","categories":["شروح الحديث","الجهاد والسير"]},{"id":6651,"question":"معلوم من السنة أن الرسول ﷺ قد سحر، ولكن بعض المسلمين يلبس عليه بعض التساؤلات، والشبهات كيف يسحر الرسول، والله يقول له: وَاللَّهُ يَعْصِمُكَ مِنَ النَّاسِ [المائدة:67]؟ وكيف يسحر وهو يتلقى الوحي عن ربه، ويبلغ ذلك المسلمين؟ فكيف يبلغ وهو مسحور، وقول الكفار، والمشركين: إِنْ تَتَّبِعُونَ إِلَّا رَجُلًا مَسْحُورًا [الإسراء:47] نرجو إيضاح وبيان هذه الشبهات؟","title":"الجمع بين: سحر النبي، وبين: {وَاللَّهُ يَعْصِمُكَ مِنَ النَّاسِ}","answer":"الجواب: هذا ثبت في الحديث الصحيح أنه في المدينة بعدما استقر الوحي، واستقرت الرسالة، وقامت دلائل النبوة، وصدق الرسالة، ونصره الله على المشركين، وأذلهم، تعرض له بعض اليهود، يقال له: لبيد بن الأعصم، تعرض له بعض اليهود بأشياء؛ صار يخيل إليه أنه فعل بعض الشيء ولم يفعله، ولكن لم يزل -بحمد الله- لا عقله، ولا شعوره، ولا تمييزه، بل يحدث الناس ويكلم الناس، لكن إن أحس بشيء؛ أثر عليه بعض الأثر، كما قالت عائشة -رضي الله عنها-: إنه كان ربما يخيل إليه أنه فعل الشيء في البيت مع أهله، ولم يفعله، فجاءه الوحي من ربه  بطريق جبرائيل، وأخبروه بما وقع، فبعث من استخرج ذلك الشيء من بئر في محل الأنصار، وأزيل، وزال عنه ذلك بحمد الله، ولم يترتب على ذلك شيء مما يضر الناس، أو يخل بالرسالة، أو بالوحي، والله -جل وعلا- عصمه من الناس كما أخبر  مما يمنع من الرسالة، وتبليغ الرسالة. أما ما يصيب الرسل -كما أصاب من قبله- فقد أصابه مثل ما أصاب من قبله، وقد جرح يوم أحد، وكسرت البيضة على رأسه، ودخلت حلقات المغفر في وجنته -عليه الصلاة والسلام- وسقط في بعض الحفر التي هناك، وقد ضيقوا عليه في مكة تضيقًا شديدًا، وآذوه أذى كثيرًا، فقد أصابه شيء مما كتب الله عليه، ورفع الله به درجاته، وأعلى به مقامه، وضاعف في حسناته، ولكن الله عصمه منهم، فلم يمنعه من تبليغ الرسالة، ولم يقتلوه، ولم يحولوا بينه وبين الرسالة، بل بلغ الرسالة، وأدى الأمانة عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/2529/الجمع-بين-سحر-النبي-وبين-والله-يعصمك-من-الناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1024.mp3","categories":["شروح الحديث","التفسير"]},{"id":6684,"question":"كيف نوفق بين الأحاديث المتعارضة فكريًا في الشرب واقفًا، وفي التبول واقفًا، وجزاكم الله خيرًا؟","title":"كيفية التوفيق بين الأحاديث المتعارضة ظاهرياً في الشرب والتبول واقفاً","answer":"الجواب: الحقيقة ليس فيها تعارض، فالنبي ﷺ نهى عن الشرب قائمًا، ثم فعل ذلك ﷺ، فدل ذلك على أن الأمر ليس للوجوب، وليس النهي للتحريم، فمن شرب قائمًا فلا حرج، ومن جلس فهو أفضل، هذا الجمع بينهما، النبي شرب قائمًا، وقاعدًا -عليه الصلاة والسلام- فالقعود أفضل، وأروى، وأهنأ، وإذا شرب قائمًا للحاجة، والعجلة، أو لأسباب أخرى؛ فلا بأس، فقد ثبت هذا وهذا عن النبي ﷺ، فيدل أن نهيه عن الكراهة، وأن أمره بالقعود للندب ولا.. في ذلك، ولا تعارض.  وهكذا البول قائمًا، والبول قاعدًا، البول قاعدًا أفضل، وأستر، والبول قائمًا جائز إذا كان ما فيه ظهور العورة، إذا كان ما يراه أحد، إذا كان في مكان لا يراه أحد، أو وقف إلى جدار مثلًا، وبال قائمًا لحاجة، أو لسرعة، أو يكون المكان غير لائق، أو ليبين الجواز للناس؛ فلا حرج، فقد ثبت عنه ﷺ أنه كان يبول قاعدًا في الأغلب، وقد ثبت في حديث حذيفة أنه بال قائمًا؛ أتى سباطة قوم فبال قائمًا، وجاء في أحاديث أخرى. فالصواب: أنه يجوز هذا وهذا لكن بشرط ستر العورة، وألا ترى عورته، يكون في مكان مستور، لا ترى فيه العورة، فلا بأس، ولكن الجلوس أفضل. السؤال: في بعض المحلات أماكن مخصوصة للبول قائما مثل المطارات؟ الجواب: لا حرج لا حرج، إذا دعت الحاجة لا حرج، لكن بشرط ستر العورة. السؤال: ما في حاجة يا شيخ هي دورة مياه؟ الجواب: المقصود إذا كان بوله قائما لا ترى عورته، ولا يطبع ثيابه بالنجاسة؛ فلا حرج.","link":"https://binbaz.org.sa/fatwas/2545/كيفية-التوفيق-بين-الاحاديث-المتعارضة-ظاهريا-في-الشرب-والتبول-واقفا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1040.mp3","categories":["شروح الحديث","الجهاد والسير"]},{"id":6704,"question":"لما خير النبي -عليه الصلاة والسلام- بين الدنيا، والآخرة اختار الآخرة، وقال: اللهم الرفيق الأعلى فما المقصود بالرفيق الأعلى؟","title":"معنى قوله عليه الصلاة والسلام: «اللهم الرفيق الأعلى»","answer":"الجواب:  يعني مع النبيين، والصديقين، والشهداء، والصالحين، وحسن أولئك رفيقًا.","link":"https://binbaz.org.sa/fatwas/2582/معنى-قوله-عليه-الصلاة-والسلام-اللهم-الرفيق-الاعلى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1078.mp3","categories":["شروح الحديث","الجهاد والسير"]},{"id":6850,"question":"ورد حديث عن الرسول ﷺ: إذا التقى المسلمان بسيفهما فالقاتل، والمقتول في النار إذا كان هذا حديث صحيح، فما حكم قتل جيوش المسلمين الذين يقتل بعضهم بعضًا مثل العراق، والإيرانيين، أفيدونا جزاكم الله خيرًا؟","title":"معنى حديث: «إذا التقى المسلمان بسيفيهما»","answer":"الجواب: الحديث صحيح في الصحيحين، عن النبي -عليه الصلاة والسلام- أنه قال: إذا التقى المسلمان بسيفهما فالقاتل، والمقتول في النار قيل يا رسول الله هذا القاتل فما شأن المقتول؟ قال: لأنه كان حريصًا على قتل صاحبه.  فالمسلمان إذا التقوا ظلمًا، وعدوانًا هذا وعيدهم، أما إذا التقوا بشبهة، ولأمر مشروع، كما يقوم أهل العدل في قتال أهل البغي، فهؤلاء الذين قاموا بإزالة البغي محسنون، ومقتولهم شهيد، ويرجى له الخير؛ لأنهم قاموا بإزالة البغي كما قال الله -جل وعلا-: وَإِنْ طَائِفَتَانِ مِنَ الْمُؤْمِنِينَ اقْتَتَلُوا فَأَصْلِحُوا بَيْنَهُمَا فَإِنْ بَغَتْ إِحْدَاهُمَا عَلَى الْأُخْرَى فَقَاتِلُوا الَّتِي تَبْغِي حَتَّى تَفِيءَ إِلَى أَمْرِ اللَّهِ [الحجرات:9].  فقتال الباغية حتى تفيء قتال شرعي، والمقتول في ذلك ليس داخلًا في الحديث؛ لأنه مأمور بالقتال، فالمقتول في هذا شهيد، والقاتل الذي يقاتل -وهو باغي- هو الذي على خطر، أما من قاتل لإزالة البغي، ولإيقاف الباغية عند حدها، ثم قتل؛ فهو شهيد، وإنما الخطر على مقتول الباغية التي أبت أن ترجع الحق، هذا هو الذي عليه الوعيد، وعليه الغضب؛ لأنه بغى، واعتدى، ولم يرجع عن خطئه، وضلاله، وهكذا المتقاتلون ظلمًا، وعدوانًا على الرياسات، أو على أمور فيما بينهم، أو على أشياء فيما بينهم من أحقاد، وشحناء هؤلاء داخلون في الحديث، ولا حول، ولا قوة إلا بالله. وأما ما جرى من القتال في فلسطين، وفي لبنان، وبين البعثيين، وبين الرافضة، فهذه أمور لها أسبابها وَمَا رَبُّكَ بِظَلَّامٍ لِلْعَبِيدِ [فصلت:46] لما حصل من هذا القتال، وهذه الفتن كلها بأسباب الذنوب، والمعاصي، والغواية، والضلال من بعض أولئك وَمَا ظَلَمْنَاهُمْ، وَلَكِنْ كَانُوا هُمُ الظَّالِمِينَ [الزخرف:76] وَمَا رَبُّكَ بِظَلَّامٍ لِلْعَبِيدِ [فصلت:46] وقال سبحانه: وَمَا أَصَابَكُمْ مِنْ مُصِيبَةٍ فَبِمَا كَسَبَتْ أَيْدِيكُمْ، وَيَعْفُو عَنْ كَثِيرٍ [الشورى:30] فما سلط اليهود إلا بذنوبنا، وما جرى في بيروت من العذاب، والشر، والحروب الكثيرة، ووقعت السموم إلا بسبب ما وقع من البعض من الكفر، وفي الآخر من المعاصي، والشرور الكثيرة. وهكذا ما جرى على العراق، وما جرى على الشيعة في إيران، كل هذا بأسباب ما فعلوا، وما قدموا، الرافضة عندهم من الشر، والفساد، وسب الصحابة -رضي الله عنهم وأرضاهم- وعبادة أهل البيت بالشرك، وعبادة القبور، والبناء عليها، وعبادتها.","link":"https://binbaz.org.sa/fatwas/2738/معنى-حديث-اذا-التقى-المسلمان-بسيفيهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1238.mp3","categories":["شروح الحديث","الجهاد والسير"]},{"id":6937,"question":"حديث عائشة: \"لم يزد الرسول في رمضان، ولا غير رمضان على إحدى عشرة ركعة\"؟","title":"ما معنى قول عائشة: «لم يزد الرسول في رمضان ولا في غيره»؟","answer":"الجواب: يعني في الغالب، وإلا فقد ثبت عنه ﷺ أنه صلى ثلاثة عشر ركعة، وثبت عنه أنه أوتر بتسع، وبسبع، وبخمس، نقص عن إحدى عشر. السؤال: لم يزد ... في رمضان، ولا غير رمضان؟ الجواب: المراد أنه في الغالب، هي ممن روت أنه صلى ثلاثة عشر، يعني غالبًا إحدى عشر، وإلا قد يزيد عنها، ويصلي ثلاثة عشر، وقد ينقص، ويصلي تسعًا، وسبعًا، وخمسًا -عليه الصلاة والسلام- وثلاثًا. السؤال: يمكن القيام يصلى ثماني ركعات؟ الجواب: لو صلى ثماني ركعاتٍ، وأوتر في ثلاث، أو صلى عشرًا، وأوتر في ثلاث؛ هذا طيب، أو صلى أقل من ذلك، أو أكثر، الأمر واسع.","link":"https://binbaz.org.sa/fatwas/2867/ما-معنى-قول-عاىشة-لم-يزد-الرسول-في-رمضان-ولا-في-غيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1315.mp3","categories":["الوتر وقيام الليل","شروح الحديث"]},{"id":6940,"question":"هناك شبهة يروجها بعضهم، يقولون: لا تصلوا إليها ولا عليها، فماذا نرد عليهم بهذا؟","title":"معنى اتخاذ القبور مساجد","answer":"الجواب:\nالنبي ﷺ قال: لا تصلوا إلى القبور نهى عن الصلاة إليها، ولعن المتخذين مساجد عليها ألا وإن .. كانوا يتخذون قبور أنبيائهم، وصالحيهم مساجد، ألا فلا تتخذوا القبور مساجد فنهاهم عن الصلاة إليها، وعنها، وعن اتخاذها مساجد، فإذا صلى عندها؛ فقد اتخذت مسجدًا، كما قال النبي ﷺ: جعلت لي الأرض مسجدًا وطهورًا .. .... فإذا صلى عند القبر يمينًا، أو شمالًا، أو خلفًا، أو أمامه؛ فقد اتخذه مسجدًا.","link":"https://binbaz.org.sa/fatwas/2870/معنى-اتخاذ-القبور-مساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1318.mp3","categories":["شروح الحديث","مسائل متفرقة في العقيدة"]},{"id":7000,"question":"يؤتى بثلاثة يوم القيامة.. يقول: يا رب قاتلت في سبيلك... فكيف، والكفار ما يرون ربهم يوم القيامة؟","title":"ما الجمع بين حديث «أول ثلاثة..» وعدم رؤية الكفار ربهم؟","answer":"الجواب:\n\nالرب يكلم، يقول النبي ﷺ: ما منكم من أحد إلا سيكلمه ربه، ليس بينه وبينه ترجمان، فينظر عن يمينه؛ فلا يرى إلا ما قدم، وينظر عن شماله؛ فلا يرى إلا ما قدم، وينظر تلقاء وجهه؛ فلا يرى إلا النار، فاتقوا النار ولو بشق تمرة ما يلزم من الكلام الرؤية، الرؤية شيء، والكلام شيء، فهو يكلم  جميع الخلق، ولكنه لا يراه إلا المؤمنون.\n\nثلاثة يؤتى بهم يوم القيامة: مجاهد، وقارئ، ومتصدق، فيقال العالم: فيم تعلمت العلم، وقرأت القرآن؟ قال: قرأت فيك القرآن، وتعلمت فيك العلم، فيقول الله له: كذبت، وتقول الملائكة: كذبت، ولكنك تعلمت ليقال: عالم، وقرأت ليقال: قارئ، ما تعلم لله، ولا قرأ لله، فيؤمر به، فيسحب إلى النار على وجهه -نسأل الله العافية-. \n\nويؤتى بالمجاهد فيقال له: فيم جاهدت؟ قال: أمرت بالجهاد، وجاهدت في سبيلك، قال: كذبت، تقول له الملائكة: كذبت، ولكنك جاهدت ليقال: هو جريء، يعني هو شجاع، فيؤمر به، فيسحب إلى النار على وجهه -نسأل الله العافية-. \n\nويؤتى بالمتصدق الذي تصدق بماله، فيقال له: فيم تصدقت؟ قال: أمرت بالصدقة في سبيلك، فما تركت من سبيل تحب أن ينفق فيه إلا أنفقت فيه، قال: كذبت، وتقول الملائكة: كذبت، ولكنك تصدقت ليقال: هو جواد، يعني يقال: إنه سخي، ما هو لله، بل لمراءات الناس، حتى يمدحوه، ويثنوا عليه، فيؤمر به إلى النار -نسأل الله العافية-.\n\nهذا معناه الحذر من الرياء، والعمل لغير الله، أنت تقرأ قوله تعالى: فَوَيْلٌ لِلْمُصَلِّينَ ۝ الَّذِينَ هُمْ عَنْ صَلَاتِهِمْ سَاهُونَ ۝ الَّذِينَ هُمْ يُرَاءُونَ ۝ وَيَمْنَعُونَ الْمَاعُونَ [الماعون:4-7] قال: ويل لهم، فالويل معناه الإشارة إلى شدة العذاب -نعوذ بالله-.","link":"https://binbaz.org.sa/fatwas/2950/ما-الجمع-بين-حديث-اول-ثلاثة-وعدم-روية-الكفار-ربهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1401.mp3","categories":["شروح الحديث","الرياء والسمعة"]},{"id":7021,"question":"ما ضابط الجمع بين الصلاتين أثناء المطر، أو وقت المطر؟","title":"حكم الجمع بين الصلاتين أثناء المطر","answer":"الجواب:\n\nإذا جاء العذر يجمع بين الصلاتين، الظهر والعصر، والمغرب والعشاء، كالمريض والمسافر، وهكذا المطر الشديد في أصح قولي العلماء، يجمع بين الظهر والعصر، بعض أهل العلم يقولون: الظهر والعصر في النهار ما فيه مشقة، ولكن الصواب أن فيه مشقة إذا كان المطر شديدًا، والأسواق فيها الماء يشق على الناس الخروج إلى العصر، فإذا جمعوا بين الظهر والعصر جمع تقديم؛ فلا بأس كالمغرب، والعشاء، وكالمسافر، وكالمريض، سواء جمع في أول الوقت، أو في وسط الوقت. \n\nالمهم إذا كان هناك ما يشق  عليهم بأن كانوا في المسجد، وحصل المطر الشديد، والأسواق تضرهم فيها الطين، وفيها المياه؛ جمعوا، لا بأس، وإن لم يجمعوا؛ فلهم عذر أن يصلوا في بيوتهم بوجود الأمطار في الأسواق، ووجود الطين، لهم عذر في الصلاة في البيت، إن جمعوا؛ فلا بأس، وإن صلى المسلم في بيته من أجل العذر؛ فلا بأس.\n\nالسؤال: يعني ما يشترط وجود المطر؟\n\nالجواب: المطر، أو الطين، أو الدحض.","link":"https://binbaz.org.sa/fatwas/2957/حكم-الجمع-بين-الصلاتين-اثناء-المطر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1407.mp3","categories":["أحكام الجمع","شروح الحديث"]},{"id":7030,"question":"يقول الله تعالى: لَا إِكْرَاهَ فِي الدِّينِ قَدْ تَبَيَّنَ الرُّشْدُ مِنَ الْغَيِّ [البقرة:256] إلى آخر الآية، وقال الأنصار: بايعنا الرسول ﷺ على السمع والطاعة في المنشط والمكره، كيف نوفق بين الإكراه في الحالتين؟","title":"الجمع بين: {لَا إِكْرَاهَ فِي الدِّينِ} و«الطاعة في المنشط والمكره»","answer":"الجواب:\n\nما بينهما اختلاف، بايع الرسول ﷺ على السمع والطاعة في كل أمورهم، في منشطهم ومكرههم وعسرهم ويسرهم أن يسمعوا ويطيعوا، ما هو معناه في الإكراه، معناه: أنهم يسمعون ويطيعون، ولو كان هذا الشيء يكرهونه، ويشق عليهم لأجل فقرهم، أو لأجل أسباب أخرى، متى أمر الرسول ﷺ أطاعوه وإن كان شيئًا قد يضرهم، ما عندهم مال ينفقون، ما عندهم مطايا، ما عندهم كذا، يكرهون من جهة الكراهة الطبيعية، من جهة المشقة الطبيعية، لا من جهة الإكراه.\n\nالإكراه شيء آخر، الإكراه كونه يضرب على هذا، أو يهدد بهذا الشيء أنه يفعله، وهو غير مشروع، هذا هو الإكراه، أما كونه يطيع ولي الأمر في منشطه وفي مكره، وفي عسره ويسره، طاعة لله، ومحبة لشرع الله، هو مشكور، ولو أطاعه وهو يمشي على رجليه في الجهاد مشكور بهذا؛ لأنه يريد فضل الله وثوابه .\n\nومعنى لَا إِكْرَاهَ فِي الدِّينِ [البقرة:256] تفسر بمعنيين:\n\nأحدهما: أن هذا كان قبل الجهاد، كان الناس لا يكرهون من دخل في الإسلام قبل، ومن أبى لا يقاتل، هذا أول الأمر، ثم شرع الله الجهاد للمسلمين، فمن دخل في الإسلام وإلا جوهد وقوتل؛ حتى يدخل في الإسلام أو يؤدي الجزية إن كان من أهلها، هذا قول.\n\nوالقول الثاني: معناه لا إكراه في الدين بالنسبة إلى أهل الجزية من اليهود والنصارى والمجوس، لا إكراه عليهم، بل يلزمون بالإسلام، أو بالجزية، فهي آية مطلقة، مخصوصة بآية الجزية، وأدلة الجزية، فمعنى لا إكراه في الدين لأهل الكتاب والمجوس إذا أدوا الجزية؛ فلا يكرهون، بل تقبل منهم الجزية، ويقرون على دينهم حتى يهديهم الله  فالمعنيان معروفان عند أهل العلم. \n\nالمعنى الأول: أن هذا كان قبل شرع الجهاد، يعني لا إكراه، إذا اعتزلونا ولم يقاتلونا؛ اعتزلناهم ولم نقاتلهم، هذا في أول الأمر في مكة، وفي أول الهجرة، من قاتل قتلناه، ودافعنا، ومن لم يقاتل لم ندفعه، ولم نكرهه، هذا في أول الأمر. \n\nثم شرع الله الجهاد، وأمر رسوله بالجهاد وقال الله في ذلك فَإِذَا انْسَلَخَ الْأَشْهُرُ الْحُرُمُ فَاقْتُلُوا الْمُشْرِكِينَ حَيْثُ وَجَدْتُمُوهُمْ وَخُذُوهُمْ وَاحْصُرُوهُمْ وَاقْعُدُوا لَهُمْ كُلَّ مَرْصَدٍ فَإِنْ تَابُوا وَأَقَامُوا الصَّلَاةَ وَآتَوُا الزَّكَاةَ فَخَلُّوا سَبِيلَهُمْ [التوبة:5] هذا آخر الأمر، أمرنا بالجهاد، وألا نتركهم حتى يدخلوا في دين الله إلا من يؤدي الجزية، فإذا بذل الجزية، وأعطى الجزية عن يد؛ قبلناها منه.","link":"https://binbaz.org.sa/fatwas/3017/الجمع-بين-لا-اكراه-في-الدين-والطاعة-في-المنشط-والمكره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1424.mp3","categories":["التفسير","شروح الحديث"]},{"id":7042,"question":"ما معنى مائلات مميلات في حديث الرسول ﷺ: نساء كاسيات عاريات ...  إلى آخره؟","title":"معنى قول النبي: «نساء كاسيات عاريات مائلات مميلات»","answer":"الجواب:\n\nسمعتم الحديث، يقول النبي ﷺ: صنفان من أهل النار لم أرهما بعد: رجال بأيديهم سياط كأذناب البقر يضربون بها الناس يقال عنهم: إنهم الشرطة وأشباههم من الظالمين، الشرطة الظالمة ونساء كاسيات عاريات مائلات مميلات رؤوسهن كأسنمة البخت المائلة لا يدخلن الجنة ولا يجدن ريحها، وإن ريحها ليوجد من مسيرة كذا وكذا.\n\nالمقصود: أن النساء الكاسيات العاريات أصل كما قاله المشايخ في تفسيرها، وأنهن كاسيات من نعم الله، عاريات من شكرها، هذا أحد التفسيرات لها.\n\nوقال آخرون من أهل العلم: معنى كاسيات، يعني: كاسيات ثياب رقيقة، ما تستر البشرة، عاريات في المعنى.\n\nوقال آخرون في تفسير الحديث: معناه كاسيات بثياب قصيرة، لا تستر، كالتي تلبس الثياب التي إلى الركبة، أو إلى بعض الفخذ، أو إلى بعض الساق، وتكشف الرأس، كل هذه كسوة عارية، فلا تكون الكسوة كافية إلا إذا كانت ساترة للمرأة كلها، فالنساء الكاسيات العاريات هن اللاتي يلبسن لباسًا لا يسترهن، إما لقصره، وإما لرقته، وإما لضيقه -والعياذ بالله- حتى تبدو أحجام عورتها، هذه كاسية بالاسم، عارية في الحقيقة.\n\nوأما مائلات مميلات، فهن المائلات عن العفة، مائلات عن الاستقامة إلى الفواحش والمنكرات، يعني مائلات عن الاستقامة والعفة والصبر على ما أوجب الله، إلى ما حرم الله من الزنا، والفواحش، والتهم، مميلات لغيرهن: مميلات للنساء الأخريات، يدعُنَّ إلى الفساد، ويعلمن النساء الفساد، ويشجعن على الفساد -نسأل الله العافية-.","link":"https://binbaz.org.sa/fatwas/3037/معنى-قول-النبي-نساء-كاسيات-عاريات-ماىلات-مميلات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1437.mp3","categories":["شروح الحديث","قضايا المرأة","اللباس والزينة"]},{"id":7067,"question":"ما معنى مائلات مميلات في حديث الرسول ﷺ: نساء كاسيات عاريات ...  إلى آخره؟","title":"معنى قول النبي: «نساء كاسيات عاريات مائلات مميلات»","answer":"الجواب:\n\nسمعتم الحديث، يقول النبي ﷺ: صنفان من أهل النار لم أرهما بعد: رجال بأيديهم سياط كأذناب البقر يضربون بها الناس يقال عنهم: إنهم الشرطة وأشباههم من الظالمين، الشرطة الظالمة ونساء كاسيات عاريات مائلات مميلات رؤوسهن كأسنمة البخت المائلة لا يدخلن الجنة ولا يجدن ريحها، وإن ريحها ليوجد من مسيرة كذا وكذا.\n\nالمقصود: أن النساء الكاسيات العاريات أصل كما قاله المشايخ في تفسيرها، وأنهن كاسيات من نعم الله، عاريات من شكرها، هذا أحد التفسيرات لها.\n\nوقال آخرون من أهل العلم: معنى كاسيات، يعني: كاسيات ثياب رقيقة، ما تستر البشرة، عاريات في المعنى.\n\nوقال آخرون في تفسير الحديث: معناه كاسيات بثياب قصيرة، لا تستر، كالتي تلبس الثياب التي إلى الركبة، أو إلى بعض الفخذ، أو إلى بعض الساق، وتكشف الرأس، كل هذه كسوة عارية، فلا تكون الكسوة كافية إلا إذا كانت ساترة للمرأة كلها، فالنساء الكاسيات العاريات هن اللاتي يلبسن لباسًا لا يسترهن، إما لقصره، وإما لرقته، وإما لضيقه -والعياذ بالله- حتى تبدو أحجام عورتها، هذه كاسية بالاسم، عارية في الحقيقة.\n\nوأما مائلات مميلات، فهن المائلات عن العفة، مائلات عن الاستقامة إلى الفواحش والمنكرات، يعني مائلات عن الاستقامة والعفة والصبر على ما أوجب الله، إلى ما حرم الله من الزنا، والفواحش، والتهم، مميلات لغيرهن: مميلات للنساء الأخريات، يدعُنَّ إلى الفساد، ويعلمن النساء الفساد، ويشجعن على الفساد -نسأل الله العافية-.","link":"https://binbaz.org.sa/fatwas/3037/معنى-قول-النبي-نساء-كاسيات-عاريات-ماىلات-مميلات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1437.mp3","categories":["شروح الحديث","قضايا المرأة","اللباس والزينة"]},{"id":7072,"question":"ما معنى مائلات مميلات في حديث الرسول ﷺ: نساء كاسيات عاريات ...  إلى آخره؟","title":"معنى قول النبي: «نساء كاسيات عاريات مائلات مميلات»","answer":"الجواب:\n\nسمعتم الحديث، يقول النبي ﷺ: صنفان من أهل النار لم أرهما بعد: رجال بأيديهم سياط كأذناب البقر يضربون بها الناس يقال عنهم: إنهم الشرطة وأشباههم من الظالمين، الشرطة الظالمة ونساء كاسيات عاريات مائلات مميلات رؤوسهن كأسنمة البخت المائلة لا يدخلن الجنة ولا يجدن ريحها، وإن ريحها ليوجد من مسيرة كذا وكذا.\n\nالمقصود: أن النساء الكاسيات العاريات أصل كما قاله المشايخ في تفسيرها، وأنهن كاسيات من نعم الله، عاريات من شكرها، هذا أحد التفسيرات لها.\n\nوقال آخرون من أهل العلم: معنى كاسيات، يعني: كاسيات ثياب رقيقة، ما تستر البشرة، عاريات في المعنى.\n\nوقال آخرون في تفسير الحديث: معناه كاسيات بثياب قصيرة، لا تستر، كالتي تلبس الثياب التي إلى الركبة، أو إلى بعض الفخذ، أو إلى بعض الساق، وتكشف الرأس، كل هذه كسوة عارية، فلا تكون الكسوة كافية إلا إذا كانت ساترة للمرأة كلها، فالنساء الكاسيات العاريات هن اللاتي يلبسن لباسًا لا يسترهن، إما لقصره، وإما لرقته، وإما لضيقه -والعياذ بالله- حتى تبدو أحجام عورتها، هذه كاسية بالاسم، عارية في الحقيقة.\n\nوأما مائلات مميلات، فهن المائلات عن العفة، مائلات عن الاستقامة إلى الفواحش والمنكرات، يعني مائلات عن الاستقامة والعفة والصبر على ما أوجب الله، إلى ما حرم الله من الزنا، والفواحش، والتهم، مميلات لغيرهن: مميلات للنساء الأخريات، يدعُنَّ إلى الفساد، ويعلمن النساء الفساد، ويشجعن على الفساد -نسأل الله العافية-.","link":"https://binbaz.org.sa/fatwas/3037/معنى-قول-النبي-نساء-كاسيات-عاريات-ماىلات-مميلات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1437.mp3","categories":["شروح الحديث","قضايا المرأة","اللباس والزينة"]},{"id":7089,"question":"إذا ظهرت المنكرات في قوم؛ فإن الله سوف يعذبهم؛ لحديث عائشة -رضي الله عنها- قالت: يا رسول الله أنهلك وفينا الصالحون؟ قال: نعم وبهم يبدأ العذاب إذًا أيها الصالحون لماذا انتشار هذا؟ وما موقف العلماء الساكتين، وكأن على رؤوسهم الطير؟ وهل انتشار الربا والمسجلات والفيديو وبيع المجلات الخليعة وغيرها، أليس هذا فيه ظهور المنكرات إلى آخره؟","title":"بيان حديث: «أنهلك وفينا الصالحون»","answer":"الجواب:\n\nهذا الحديث عن زينب ليس عن عائشة، وليس هذا لفظه بالتمام، عن زينب بنت جحش أم المؤمنين -رضي الله عنها- أن النبي ﷺ دخل عليها غضبان يقول: ويل للعرب من شر قد اقترب، فتح اليوم من ردم يأجوج ومأجوج مثل هذا وحلق بين أصبعيه السباحة، والوسطى، فقالت له زينب -رضي الله عنها-: يا رسول الله أنهلك وفينا الصالحون؟! قال: نعم إذا كثر الخبث! يعني إذا كثرت المعاصي؛ عم الهلاك، ولا حول ولا قوة إلا بالله.\n\nعمت العقوبات كما قال النبي في الحديث الآخر، في الحديث الصحيح يقول ﷺ: إن الناس إذا رأوا المنكر فلم يغيروه؛ أوشك أن يعمهم الله بعقابه ولا فيه بأنه يبدأ بالصالحين، ليس في الحديث هذا، إنما هذا في أثر آخر: أن ملكًا من الملائكة أمر أن يعذب قرية، فقال: إن فيها فلانًا عبدك الصالح فلان، قال: به فابدأ، فإنه لم يتغير فيَّ قط ،  هذا خبر آخر إسرائيلي.\n\nوأما قولك: لماذا لا تنكرون؟ ولماذا ما أنكروا، ومن قال لك: إنهم ما أنكروا؟ هل أحطت بقلوبهم، وعرفت ما عندهم! قد أنكر العلماء، وكتبوا لولاة الأمور، وبينوا ما يجب، وبينوا أن هذه منكرات، وكلموهم مرات -نسأل الله لنا ولكم ولهم التوفيق-.\n\nلا يجوز للإنسان أن يقول: ما أنكروا وهو ما يعلم، ليس من شرط الإنكار أن يعم في المساجد أن فلانًا أنكر كذا، وفلانًا أنكر كذا، نسأل الله السلامة.","link":"https://binbaz.org.sa/fatwas/3102/بيان-حديث-انهلك-وفينا-الصالحون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1479.mp3","categories":["شروح الحديث","الجهاد والسير"]},{"id":7143,"question":"لقد علمنا أن أمة المسلمين ستفترق من حديث رسول الله كما افترقت اليهود على إحدى وسبعين فرقة، والنصارى اثنين وسبعين فرقة، وستفترق أمتي على ثلاث وسبعين فرقة، كلهم في النار إلى آخر الحديث، فما نوع الفرق التي تسمي نفسها بالتيجانية، والشاذلية، والرفاعية إلى آخره؟ هل تعتبر هذه من ضمن الفرق المنصوص عليها في الحديث؟","title":"مفهوم حديث الافتراق","answer":"الجواب:\n\nالنبي ﷺ لم يبين الفرق، لكن يجمعها أنها على خلاف طريقه ﷺ وما شرع، ثنتان وسبعون على خلاف طريقه -عليه الصلاة والسلام- فيدخل فيها كل الفرق من تيجانية، ومن قادرية، ومن شاذلية، ومن معتزلة، وجهمية، ورافضة، وغيرهم، كل من خالف سبيله -عليه الصلاة والسلام- وسلك غير طريقه؛ دخل في هذه الفرق. \n\nوهذه الفرق ليس كلها كافرة هي متوعدة بالنار كلها، لكن فيها الكافر، وفيها غير الكافر، فيها من بدعته تجعله كافرًا، وفيها من بدعته لا ترقيه، ولا توصله إلى أنه كافر، لكن يكون عاصيًا قد أثم في عمله.\n\nالسؤال: الصوفية؟\n\nالجواب: الصوفية أنواع مثل ما تقدم.","link":"https://binbaz.org.sa/fatwas/3162/مفهوم-حديث-الافتراق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1520.mp3","categories":["مسائل متفرقة في العقيدة","شروح الحديث","الفرق والمذاهب"]},{"id":7247,"question":"من سره أن يبسط له في رزقه، وينسأ له في أجله؛ فليصل رحمه ما معنى الحديث؟ وكيف يطول عمر من وصل الرحم، وفي حديث آخر: أن ابن آدم يكتب أجله وهو في بطن أمه؟","title":"معنى حديث: «من سره أن يبسط له في رزقه»","answer":"الجواب:\n\nسبق الكلام في هذا الحديث الصحيح، ومعنى ذلك: أن الله -جل وعلا- قد سبق في علمه أن هذا الذي وصل رحمه؛ يطول عمره، وينسأ في أجله بأسباب صلة رحمه، والآخر بضد ذلك، كل شيء بقدر الله -جل وعلا- فالإنسان يتعاطى الأسباب، والأمور مقدرة، والله حث على الأسباب التي شرعها وأمر بها، وقد سبق في علمه من يفعل ومن لا يفعل.","link":"https://binbaz.org.sa/fatwas/3318/معنى-حديث-من-سره-ان-يبسط-له-في-رزقه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1642.mp3","categories":["شروح الحديث","الجهاد والسير"]},{"id":7254,"question":"من سره أن يبسط له في رزقه، وينسأ له في أجله؛ فليصل رحمه ما معنى الحديث؟ وكيف يطول عمر من وصل الرحم، وفي حديث آخر: أن ابن آدم يكتب أجله وهو في بطن أمه؟","title":"معنى حديث: «من سره أن يبسط له في رزقه»","answer":"الجواب:\n\nسبق الكلام في هذا الحديث الصحيح، ومعنى ذلك: أن الله -جل وعلا- قد سبق في علمه أن هذا الذي وصل رحمه؛ يطول عمره، وينسأ في أجله بأسباب صلة رحمه، والآخر بضد ذلك، كل شيء بقدر الله -جل وعلا- فالإنسان يتعاطى الأسباب، والأمور مقدرة، والله حث على الأسباب التي شرعها وأمر بها، وقد سبق في علمه من يفعل ومن لا يفعل.","link":"https://binbaz.org.sa/fatwas/3318/معنى-حديث-من-سره-ان-يبسط-له-في-رزقه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1642.mp3","categories":["شروح الحديث","الجهاد والسير"]},{"id":7326,"question":"قول النبي ﷺ: من سأل لي الوسيلة؛ حلت له شفاعتي لو وضحتم؟","title":"شرح قوله عليه الصلاة والسلام: «من سأل لي الوسيلة»","answer":"الجواب: هذا يشرع للمؤمن بعد الأذان، إذا أجاب المؤذن يقول النبي ﷺ: إذا سمعتم المؤذن؛ فقولوا مثل ما يقول، ثم صلوا علي فإنه من صلى علي واحدة؛ صلى الله عليه بها عشرًا اللهم صل عليه وسلم ثم سلوا الله لي الوسيلة فإنها منزلة في الجنة لا تنبغي إلا لعبد من عباد الله، وأرجو أن أكون أنا هو، فمن سأل لي الوسيلة؛ حلت له شفاعتي يوم القيامة وفي لفظ آخر حلت له الشفاعة.  هذه الوسيلة منزلة في الجنة، قصر في الجنة عظيم لنبينا -عليه الصلاة والسلام- فينبغي سؤال الله أن يعطيه هذه الوسيلة، وفي اللفظ الآخر: من قال حين يسمع النداء: اللهم رب هذه الدعوة، والصلاة القائمة، آت محمدًا الوسيلة والفضيلة، وابعثه المقام المحمود الذي وعدته، إنك لا تخلف الميعاد هذا مشروع أيضًا بعد الأذان، دعاء للنبي ﷺ أن الله يعطيه الوسيلة، وهي منزلة في الجنة لا تنبغي إلا لعبد من عباد الله، قال النبي ﷺ: وأرجو أن أكون أنا هو عليه الصلاة والسلام. السؤال: شفاعته في الآخرة؟ الجواب: شفاعته تطلب من الله، هو يشفع للأمة يوم القيامة حتى يقضى بينهم، حتى يدخل المؤمنون الجنة، لكن تقول: اللهم شفع في نبيك، اللهم اجعلني من أهل شفاعته، اللهم لا تحرمني شفاعته، لا تقول: يا رسول الله اشفع لي، ما تدعوه بعد وفاته ﷺ تطلب الله أن الله يشفعه فيك، اللهم شفع في نبيك، اللهم اجعلني من أهل شفاعته، اللهم لا تحرمني شفاعته يا ربي، هكذا المؤمن يسأل ربه قُلْ لِلَّهِ الشَّفَاعَةُ جَمِيعًا [الزمر:44].  أما في حياته لا بأس إن كان حيًا بيننا، بين أصحابه يقول: يا رسول الله اشفع لنا، ادع الله لنا، وهكذا يوم القيامة عندما يقوم الناس من قبورهم، ويجتمعون يقولون له، يجتمع المؤمنون ويقولون له: يا رسول الله اشفع لنا حتى يقضى بيننا.","link":"https://binbaz.org.sa/fatwas/3405/شرح-قوله-عليه-الصلاة-والسلام-من-سال-لي-الوسيلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1718.mp3","categories":["شروح الحديث","الجهاد والسير"]},{"id":7336,"question":"ما معنى: من تقرب مني شبرًا تقربت منه ذراعًا، ومن أتاني يمشي أتيته هرولة؟","title":"معنى حديث: «من تقرب مني شبراً»","answer":"الجواب:  هذا حديث صحيح عن النبي ﷺ: قال الله : أنا عند ظن عبدي بي، وأنا معه حين يذكرني، فإن ذكرني في نفسه؛ ذكرته في نفسي، وإن ذكرني في ملإ؛ ذكرته في ملإ خير منه، وإن تقرب إلي شبرًا؛ تقربت منه ذراعًا، وإن تقرب مني ذراعًا؛ تقربت منه باعًا، وإن أتاني يمشي؛ أتيته هرولة هذا من الرب  حث للعباد على ذكره والمسارعة إلى طاعته . وتفسيرها هذا إليه ، لا يعلم كيفية هذا التقرب منه -جل وعلا- إلا هو  مثل ما نقول في استوائه، ونزوله، وغضبه، ورحمته، كل هذه الصفات تليق به، لا يشابه فيها خلقه، ولا يعلم كيفيتها سواه  فلا نكيف تقربه، ولا نكيف مجيئه ومشيه وهرولته، لا نكيف ذلك، بل نقول على الوجه اللائق بالله  لكن من ثمرة هذا ومن مقتضاه أنه أسرع بالخير إلينا  وأرحم بنا -جل وعلا-.","link":"https://binbaz.org.sa/fatwas/3403/معنى-حديث-من-تقرب-مني-شبرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1716.mp3","categories":["شروح الحديث","الجهاد والسير"]},{"id":7442,"question":"صليت اليوم مع الجماعة المغرب والعشاء جمعًا في وقت المغرب بسبب المطر، فما حكم ذلك، علمًا أن الطرق ليست بذات مشقة، بل معبدة مع وجود شيء قليل من الماء؟ وآخر مثله : أنا صليت في مسجد العليا، وجمعوا بين المغرب والعشاء وخرجت فهل علينا وزر أفيدونا؟ وآخر يقول: ما حكم جمع الصلاة في حال نزول المطر الشديد في مثل هذا اليوم، نرجو التفضل بذلك جزاكم الله خير الجزاء؟","title":"حكم الجمع بين الصلاتين بسبب المطر","answer":"الجواب: أصل الجمع بين الصلاتين بين المغرب والعشاء لوجود المطر أو الدحض أمر جائز، فعله السلف الصالح، فلا بأس بذلك، جاء في الأحاديث الصحيحة ما يدل عليه، فإذا كانت الجهة التي فيها مسجد فيها مطر يؤذي المصلين في خروجهم وفي دخولهم، أو فيها دحض زلق في طرقها، أو طين يؤذيهم؛ فلا بأس بالجمع، أما إذا كانت محلات المسجد -حي المسجد- ليس فيه أذى، وليس فيه مطر يؤذي المصلين؛ فلا وجه للجمع لمجرد وجود آثار المطر، أما إذا كان هناك مطر يصب عليهم وقت الجمع؛ فلا بأس بذلك، أو هناك دحض يعني زلق في الطرقات وطين في الطرقات فلا بأس. السؤال: والصلاة التي صلوها؟ الجواب: على حسب ما سمعت إن كان لهم عذر؛ فصلاتهم صحيحة، وإن كان ما لهم عذر؛ فعليهم أن يعيدوها.","link":"https://binbaz.org.sa/fatwas/3526/حكم-الجمع-بين-الصلاتين-بسبب-المطر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1830.mp3","categories":["أحكام الجمع","شروح الحديث"]},{"id":7451,"question":"هل حديث مضايقة الكفار إلى أضيق الطريق صحيح؟ وإذا كان صحيحًا فكيف يوفق بينه وبين قول الله تعالى: لَا يَنْهَاكُمُ اللَّهُ عَنِ الَّذِينَ لَمْ يُقَاتِلُوكُمْ فِي الدِّينِ [الممتحنة:8] إلى آخر الآية؟","title":"الجمع بين حديث مضايقة الكفار وآية الإحسان إليهم","answer":"الجواب: الحديث صحيح، قول النبي ﷺ: لا تبدؤوا اليهود ولا النصارى بالسلام، وإذا لقيتموهم في طريق فاضطروهم إلى أضيقه أخرجه مسلم في صحيحه، المعنى أنهم لا يبدؤون بالسلام، لكن إذا سلموا رد عليهم، ولا يترك لهم وسط الطريق بل يترك لهم حافات الطريق إذا استطاع المسلمون ذلك، وليس بينه منافاة وبين الآية لَا يَنْهَاكُمُ اللَّهُ عَنِ الَّذِينَ لَمْ يُقَاتِلُوكُمْ فِي الدِّينِ وَلَمْ يُخْرِجُوكُمْ مِنْ دِيَارِكُمْ أَنْ تَبَرُّوهُمْ وَتُقْسِطُوا إِلَيْهِمْ [الممتحنة:8] هذا ممكن وهذا ممكن، يبرهم ويقسط إليهم إذا رأى ذلك لفقرهم وحاجتهم، ولكن مع ذلك يفعل بما قال النبي ﷺ في اضطرارهم إلى أضيق الطريق وألا يكون لهم وسط الطريق، تكون لهم حافات الطريق والمسلمون في وسطه.  هذا ممكن وهذا ممكن ولا منافاة بين هذا وهذا، أن يقسط إليهم ويحسن إليهم إذا كان محتاجًا أو فقيرًا أو قريبًا، ومع ذلك لا يبدأه بالسلام، ولا يجعل له وسط الطريق إذا استطاع ذلك، وهذا كله معناه مضايقتهم حتى يدخلوا في الإسلام إذا كانوا بين المسلمين، إذا عرفوا المضايقة من المسلمين وأنهم لا يبدؤونهم بالسلام وأنهم يضطرونهم إلى أضيق الطريق صار هذا من أعظم الأسباب في دخولهم الإسلام وتركهم الباطل الذي هو سبب إذلال المسلمين لهم وعدم بدئهم بالسلام إلى آخره.","link":"https://binbaz.org.sa/fatwas/3528/الجمع-بين-حديث-مضايقة-الكفار-واية-الاحسان-اليهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1832.mp3","categories":["شروح الحديث","الجهاد والسير"]},{"id":7574,"question":"سماحة الشيخ! هذه الرسالة وردتنا من المعذبة -على حسب كلامها- (س) أسعد الأسمر تقول في رسالتها: إن لدي ولد، وفي أثناء حمله شاهدت في منامي شيخاً عجوزاً يقول لي: إنك ستنجبين ولداً فأسميه يوسف، وحين ولادته أسميته غير هذا الاسم؛ لأنني قد نسيت ذلك الذي تقول: أنا أتخيله أمامي حتى الآن، وقد بلغ الولد العاشرة من عمره، ومنذ ولادته حتى الآن هو مريض ويخرج من مرض ليدخل في المرض الثاني، فلم نشاهد عليه وقت كان متعافياً فيه، فهل لما رأيته في المنام شأن في هذا، أي: هل أغير اسمه إلى يوسف لعل الله يكتب له الشفاء بإذنه سبحانه وتعالى، أرجو إفادتي؟","title":"حكم العمل بالرؤيا المنامية","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، والصلاة والسلام على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فهذه الرؤيا التي رأتها السائلة: أن شيخاً عجوزاً أمرها أن تسمي ولدها يوسف ثم نسيت فلم تسمه يوسف، وابتلي الولد بالمرض إلى حين التاريخ، وتسأل: هل لهذه الرؤيا أثر لهذا وهل تغير اسمه؟ \nليس لهذه الرؤيا أثر، والرؤيا في المنام لا يعول عليها، وليست ملزمة لأحد بشيء، وقد تكون من الشيطان للإيذاء والتحزين، ولاسيما إذا كانت عند رؤيتها لهذا الشيخ قد كرهت ذلك، فإن هذا من الشيطان، والنبي عليه السلام قال: الرؤيا الصالحة من الله، والحلم من الشيطان فإذا رأى أحد ما يكره فلينفث عن يساره ثلاث مرات، وليتعوذ بالله من الشيطان ومن شر ما رأى ثلاث مرات، ثم لينقلب على جنبه الآخر فإنها لا تضره، هكذا ينبغي للرائي، إن رأى ما يسره حمد الله وأخبر به من يحب، وإن رأى ما يكره استعاذ بالله من الشيطان ومن شر ما رآه ثلاث مرات، ونفث عن يساره ثلاث مرات ثم انقلب على جنبه الآخر فإنها لا تضره، كما قاله النبي صلى الله عليه وسلم. \nوهذا الصبي الذي في المرض لله فيه حكم سبحانه وتعالى، وأنت أيها السائلة على خير إن شاء الله، التمريض والتعب هذه من المصائب، والمصائب للعبد عليها خير كثير إذا صبر، كما قال جل وعلا: وَبَشِّرِ الصَّابِرِينَ ۝ الَّذِينَ إِذَا أَصَابَتْهُمْ مُصِيبَةٌ قَالُوا إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ ۝ أُوْلَئِكَ عَلَيْهِمْ صَلَوَاتٌ مِنْ رَبِّهِمْ وَرَحْمَةٌ وَأُوْلَئِكَ هُمُ الْمُهْتَدُونَ [البقرة:155-157] وجاء في الحديث الصحيح عنه عليه الصلاة والسلام أنه قال: ما من عبد يصاب بمصيبة فيقول: إنا لله وإنا إليه راجعون، اللهم آجرني في مصيبتي واخلفني خيراً منها، إلا آجره الله في مصيبته وأخلفه خيراً منها، فالإنسان يصاب بأشياء من أمراض في نفسه، أو في ولده، أو في زوجه، أو في أقاربه، أو بتلف مال، أو بأشياء أخرى مما يكره، فعليه أن يصبر ويحتسب ويقول: إنا لله وإنا إليه راجعون، قدر الله وما شاء فعل، وهو على خير عظيم، ما أصاب العبد من مصيبة مما يكره من مرض أو هم أو حزن أو غير ذلك حتى الشوكة إلا كفر الله بها من خطاياه. \nفعليك يا أخت في الله الصبر والاحتساب وأبشري بالخير، وأسأل الله أن يمنح ولدك الشفاء والعافية، وأن يريك فيه ما يسرك، وأن يمن عليه بالعافية مما أصابه، وعليك أن تسألي الله جل وعلا أن يعافيه ويشفيه من عنده، ولاسيما في آخر الصلاة في السجود في صلاة الليل، سلي الله له الشفاء والعافية، واعرضيه على من تيسر من الأطباء، لعل الله يمن عليه بالشفاء والعافية، وأما الرؤيا فليس لها أثر في هذا. نعم.","link":"https://binbaz.org.sa/fatwas/4580/حكم-العمل-بالرويا-المنامية ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_017/01701.mp3","categories":["شروح الحديث","الرقائق"]},{"id":7593,"question":"سماحة الشيخ: عبد العزيز ! في الأسبوع الماضي لما أجرينا معكم بعض الأسئلة والاستفسارات كان معنا رسالة للمستمعة (م. أ. ع) من تعز وبقي منها سؤال حول حديث من أحاديث المصطفى صلى الله عليه وسلم تقول: عن ما معنى الحديث التالي: عن ابن عباس رضي الله عنهما قال: قال رسول الله ﷺ: الفجر فجران؛ فجر يحرم الطعام وتحل فيه الصلاة، وفجر تحرم فيه الصلاة - أي: صلاة الصبح - ويحل فيه الطعام رواه ابن خزيمة، نرجو الإفادة عن معنى هذا الحديث، والسلام عليكم ورحمة الله وبركاته؟","title":"معنى قوله عليه الصلاة والسلام: (الفجر فجران...)","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، والصلاة والسلام على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه. \nأما بعد: \nهذا الحديث الصحيح عن رسول الله عليه الصلاة والسلام: الفجر فجران هذا معناه: أن الفجر الصادق هو الذي يستطيل الأفق ويعترض ويستنير ولا يزال يزيد نوره حتى يتضح الفجر، هذا هو الفجر الصادق الذي يحرم الطعام على الصائم وتحل فيه صلاة الفجر، أما الفجر الآخر الذي يستطيل في الأفق ويرتفع كذنب السرحان مستطيلاً ثم تعقبه الظلمة، فهذا يقال له: الفجر الكاذب، وهذا تحرم فيه الصلاة ويحل فيه الطعام للصائم؛ لأنه ليل، هذا الفرق بينهما، فالفجر الصادق فجر يستطيل في الأفق كجناحي الطائر، يعني يعترض ويمتد جنوباً وشمالاً حتى يزداد نوره ويتبين الفجر واضحاً، فهذا هو الفجر الصادق الذي يحرم فيه الطعام على الصائم وتحل فيه الصلاة لدخول وقتها. \nأما الفجر الكاذب فهو الذي يستطيل في الأفق يعني: يستطيل طولاً إلى جهة السماء كالعمود مستنيراً ثم يعقبه ظلمة، فهذا يقال له: الفجر الكاذب، الذي يغر الناس ويظنه بعض الناس الصبح وليس بالصبح، هذا الفجر لا تحل به الصلاة ولا يحرم به الطعام؛ لأنه فجر كاذب. نعم.","link":"https://binbaz.org.sa/fatwas/4646/معنى-قوله-عليه-الصلاة-والسلام-الفجر-فجران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_020/02001.mp3","categories":["التفسير","شروح الحديث"]},{"id":7627,"question":"هذه الرسالة من الجمهورية العراقية ناحية التأميم، يقول مرسلها الطالب صالح عواد خلف: أقرأ القرآن الكريم وبعد عندي بيت أجلس فيه أقرأ القرآن الكريم وأصلي فيه، وبعض الأحيان يصير عندي جنابة هل يجوز أن أغتسل في هذا البيت وأن البيت متروك، فيه كتب دينية، وأنا عمري ستة عشر سنة أو أكثر، أرجو الإفادة وفقكم الله؟ المقدم: أعد.المقدم: يقول: إنه يجلس في بيت غير مسكون، ويوجد فيه كتب دينية، وأيضاً بعض الأحيان تكون عليه جنابة، ويغتسل في هذا البيت، الذي فيه الكتب الدينية هل يجوز ذلك أم لا؟","title":"حكم الاغتسال من الجنابة في بيت مهجور به كتب إسلامية","answer":"الجواب: لا حرج في ذلك، لا بأس في ذلك يغتسل، إذا كان فيه ماء، وتيسر له الغسل فيه فلا بأس؛ لأن جعله للمطالعين والمراجعين نوع من الإذن في استعمال الماء في الوضوء والغسل والشرب، لما ترك للمطالعين والمراجعين في هذه الكتب فالمعنى أنهم يتوضئوا من هذا الماء ويغتسلون منه، ولا حرج في ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/4681/حكم-الاغتسال-من-الجنابة-في-بيت-مهجور-به-كتب-اسلامية ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_025/02503.mp3","categories":["شروح الحديث","الغسل"]},{"id":7637,"question":"أيضاً هذه الرسالة من المرسل سابقاً وكتب على هذه اسمه يقول: يبعث بهذه الرسالة علي محمد من الشمال يقول فيه: كم يدوم وقوف الخلق في المحشر قبل أن يقضى بينهم، أفيدونا رحمكم الله؟","title":"مدة وقوف الخلق في المحشر","answer":"الجواب: على كل الموقف عظيم، ومدته كما أخبر الله جل وعلا أن مقدار ذلك اليوم خمسون ألف سنة، فهو يوم طويل عظيم، أما مقدار الوقوف قبل انصرافهم فالله أعلم به، لكنه طويل.. موقف طويل عظيم، أما مقداره وضبطه فالله أعلم به سبحانه وتعالى. نعم.","link":"https://binbaz.org.sa/fatwas/4691/مدة-وقوف-الخلق-في-المحشر ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_026/02604.mp3","categories":["شروح الحديث","الرقائق"]},{"id":7726,"question":"سماحة الشيخ! هذه الرسالة وردتنا من الرياض من المستمع (ع. ع. ح) يقول عن دخول المرأة وزوجها الحمام وكل منهم يرى من الآخر عورته، فما حكم ذلك؟","title":"حكم اغتسال الزوجين وكل منهما يرى عورة الآخر","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله رب العالمين، والصلاة والسلام على عبده ورسوله وخيرته من خلقه نبينا وإمامنا محمد بن عبد الله وعلى آله وأصحابه ومن سلك سبيله واهتدى بهداه إلى يوم الدين. أما بعد:\nفقد ثبت عن رسول الله عليه الصلاة والسلام أنه كان يغتسل مع أزواجه رضي الله عنهن وأرضاهن، وهذا يدل على جواز نظر الزوج إلى عورة زوجته وهي كذلك، وقد أباح الله له جماعها ومباشرتها فلا غرابة في ذلك، ولا كراهة في ذلك، فإذا اغتسلا جميعاً في الحمام أو في حجرة معينة وهما مكشوفا العورة فلا بأس بذلك. نعم، ولا حرج فيه.\nلكن فيما تقدم يلاحظ أن يكون الحمام ليس فيه من ينظر إلى عورتيهما، لا بد أن يكون هذا في محل خاص مستور ليس فيه إلا الزوج والزوجة، أما إذا كان هناك محل.. إذا كان في محل ينظر إلى عورتهما حرم عليهما ذلك، حرم عليه وعليها جميعاً، وإنما يكون الجواز فيما إذا كانا في محل مستور عن غيرهما. نعم..","link":"https://binbaz.org.sa/fatwas/4925/حكم-اغتسال-الزوجين-وكل-منهما-يرى-عورة-الاخر ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_032/03201.mp3","categories":["شروح الحديث","الغسل"]},{"id":7832,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع (م. س. الفيفي )، أخونا له عدد من الأسئلة المختصرة، فيسأل هذا السؤال -مثلاً- ويقول: هل المرض يكفر الذنب؟","title":"تكفير السيئات بالمصائب والأمراض","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nفقد ثبت عن رسول الله عليه الصلاة والسلام أن الأمراض يمحو الله بها الخطايا، ويقول ﷺ: ما أصاب المسلم من هم، ولا غم، ولا نصب، ولا وصب، ولا أذى، حتى الشوكة إلا كفر الله بها من خطاياه، فالمرض من أعظم المصائب، فالله جل وعلا يكفر به السيئات ، نعم.\nالمقدم: جزاكم الله خيرا.","link":"https://binbaz.org.sa/fatwas/5218/تكفير-السيىات-بالمصاىب-والامراض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_052/05201.mp3","categories":["شروح الحديث","الرقائق"]},{"id":7835,"question":"هل هناك من يدخل الجنة بغير حساب؟","title":"بيان من يدخل الجنة بغير حساب","answer":"الجواب: نعم، أخبر عنهم النبي ﷺ حين قال: عرضت علي الأمم، فرأيت النبي ومعه الرهط، والنبي ومعه الرجل والرجلان، والنبي وليس معه أحد حتى قال في آخره: أنه أبلغ أنه يدخل الجنة من أمته سبعون ألفاً بغير حساب ولا عذاب، فسأله الصحابة عنهم فقال: هم الذين لا يسترقون، ولا يكتوون، ولا يتطيرون، وعلى ربهم يتوكلون.\nوالمقصود من هذا أن المؤمن الذي استقام على أمر الله وترك محارم الله، ومات على الاستقامة فإنه يدخل الجنة بغير حساب ولا عذاب، ومنهم هؤلاء الذين أخبر عنهم ﷺ، لا يسترقون يعني: لا يطلبون من الناس أن يرقوهم، يسترقي يعني: يطلب الرقية.\nأما كونهم يرقون غيرهم فلا بأس؛ لأنه محسن، الراقي محسن فإذا رقى غيره ودعا له بالعافية والشفاء هذا محسن، في الحديث الصحيح: من استطاع منكم أن ينفع أخاه فلينفعه.\nأما الاسترقاء فهو طلب الرقية، وهو أن يقول: يا فلان! اقرأ علي، ترك هذا أفضل إلا من حاجة، فإذا كان هناك حاجة فلا بأس أن يطلب الرقية، وقد ثبت عن عائشة رضي الله عنها أن النبي ﷺ قال لها: استرقي من كذا فأمرها بالاسترقاء، وأمر أسماء بنت عميس أن تسترقي لأولاد جعفر لما أصابتهم العين، قال عليه الصلاة والسلام: لا رقية إلا من عين أو حمة فالاسترقاء عند الحاجة لا بأس، لكن تركه أفضل إذا تيسر علاج آخر.\nوهكذا الكي تركه أفضل إذا تيسر علاج آخر؛ لقوله ﷺ: الشفاء في ثلاث: كية نار، وشربة عسل أو شرطة محجم، وما أحب أن أكتوي، وفي اللفظ الآخر قال: وأنا أنهى أمتي عن الكي.\nفدل ذلك على أن الكي ينبغي أن يكون هو آخر الطب عند الحاجة إليه، فإذا تيسر أن يكتفى بغيره من الأدوية فهو أولى.\nوقد ثبت عنه ﷺ أنه كوى بعض أصحابه عليه الصلاة والسلام، فإذا دعت الحاجة للكي فلا كراهة، وإن استغني عنه بدواء آخر، بشربة عسل، أو شرطة محجم يعني: الحجامة، أو قراءة، أو دواء آخر كان أفضل من الكي.\nفالمقصود أن قوله ﷺ: لا يسترقون ولا يكتوون لا يدل على التحريم وإنما يدل على أن هذا هو الأفضل، عدم الاسترقاء، يعني: عدم طلب الرقية وعدم الكي هذا هو الأفضل، ومتى دعت الحاجة إلى الاسترقاء أو الكي فلا حرج ولا كراهة في ذلك.\nولا يتطيرون التطير هو التشاؤم بالمرئيات أو المسموعات، والطيرة شرك من عمل الجاهلية، فهؤلاء السبعون يتركون ما حرم الله عليهم من الطيرة، وما كره لهم من الاسترقاء والكي عند عدم الحاجة إليه . وعلى ربهم يتوكلون يتركون ذلك ثقة بالله واعتماداً عليه وطلباً لمرضاته، والمعنى: أنهم استقاموا على طاعة الله، وتركوا ما حرم الله، وتركوا بعض ما أباح الله إذا كان غيره أفضل منه كالاسترقاء والكي، يرجون ثواب الله ويخافون عقابه، ويتقربون إليه بما هو أحب إليه سبحانه وتعالى، عن توكل، وعن ثقة به واعتماد عليه سبحانه وتعالى.\nوجاء في الروايات الأخرى أن الله زادهم مع كل ألف سبعين ألفاً، وفي بعض الروايات الأخرى وحثيات من حثيات ربي، وهذه الحثيات لا يعلم مقدارها إلا الله سبحانه وتعالى.\nوالجامع في هذا أن كل مؤمن استقام على أمر الله وعلى ترك محارم الله ووقف عند حدود الله هو داخل في السبعين، داخل في حكمهم في أنهم يدخلون الجنة بغير حساب ولا عذاب، نعم.\nالمقدم: جزاكم الله خيرا ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/5220/بيان-من-يدخل-الجنة-بغير-حساب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_052/05202.mp3","categories":["شروح الحديث","الرقائق"]},{"id":7886,"question":"أيضاً هذا سؤال ومهم جداً؛ لأنه يرد لنا كثير من الأسئلة والاستفسارات حتى أنه معي الآن أكثر من (12) رسالة حول التبول بعد الجماع، يقول: هل يجب على الرجل أن يتبول بعد الجماع وقبل الوضوء والغسل مع الدليل وفقكم الله وجزاكم عنا ألف خير؟","title":"حكم التبول بعد الجماع وقبل الاغتسال","answer":"الجواب: النبي ﷺ أمر الجنب أن يتوضأ قبل النوم إذا فرغ من الجماع في الليل فالسنة له أن يتوضأ قبل أن ينام، ومعلوم أنه في ترتيب وضوئه يستنجي يبول بعد الجماع ويستنجي ثم يتوضأ وضوء الصلاة، ولا أعلم شيئاً فيه النص على البول وإنما هذا تابع إذا قام، إذا فرغ من جماعه شرع له أن يتوضأ، ومعلوم أن الذي يريد الوضوء لابد أن يغسل فرجه عما أصابه ويحصل البول حين يتبول ويستنجي ثم يتوضأ وضوء الصلاة، أما شيء منصوص عن البول خاصة فلا أعلم له أصلاً ولكن المشروع له أنه يستنجي يبول بعدما يفرغ من حاجته إذا ذهب للوضوء يبول ويستنجي ويغسل آثار ما أصابه من الأذى ثم يتوضأ وضوء الصلاة كما أخبرت عائشة رضي الله عنها: كان النبي ﷺ إذا فرغ يغسل فرجه ثم يتوضأ وضوء الصلاة ثم ينام ويغتسل في آخر الليل في الغالب عليه الصلاة والسلام، وربما اغتسل في أول الليل، لكن الغالب أنه يغسل فرجه ويتوضأ وضوء الصلاة ثم ينام، وقد أمر بهذا عليه الصلاة والسلام، سأله عمر فأمر عليه الصلاة والسلام الجنب أن يتوضأ ثم ينام. نعم.","link":"https://binbaz.org.sa/fatwas/5356/حكم-التبول-بعد-الجماع-وقبل-الاغتسال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_059/05904.mp3","categories":["شروح الحديث","الغسل"]},{"id":8193,"question":"سؤالها الآخر تقول فيه: لقد قرأت حديث عن النبي ﷺ بما معناه: أن تنزهوا من البول، فإن أكثر عذاب القبر منه، ما معنى هذا؟","title":"ما معنى: «تنزهوا من البول فإن أكثر عذاب القبر منه»؟","answer":"الجواب: هذا حديث جيد، رواه الحاكم في صحيحه ورواه جماعة، ولفظه: استنزهوا من البول؛ فإن عامة عذاب القبر منه، وفي لفظ: أكثر عذاب القبر من البول، فمعناه: التحفظ، معناه: التحفظ من البول والحذر منه، فإذا أراد الإنسان يبول يبول في محل لين، أو في جحر من محل قضاء الحاجة، لئلا يطير إليه الرشاش رشاش البول، فالمرأة والرجل كذلك عليهما جميعاً أن يعتنيا بهذا الأمر، فيكون البول في محل لا يطشش على الإنسان، وإذا أصابه شيء منه، طشش على فخذه، أو طشش على قدمه، فيصب عليه الماء، ويغسله عن ما أصابه، يغسل ما أصابه، حتى يكون قد تحرز من البول، وإذا كان المحل لين كالأرض اللينة، أو وضع الفرج على نفس الجحر الذي يذهب فيه الماء، حتى لا يطشش عليه كفى ذلك، لكن بكل حال التنزه والتحرز طيب، فلو قدر أنه صادف البول حافة المحل البول فطشش على فخذ أو على ساق أو قدم، فإن المسلم والمسلمة عليهما أن يغسلا ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/6002/ما-معنى-تنزهوا-من-البول-فان-اكثر-عذاب-القبر-منه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_093/09303.mp3","categories":["التفسير","شروح الحديث"]},{"id":8194,"question":"سؤالها الآخر تقول فيه: لقد قرأت حديث عن النبي ﷺ بما معناه: أن تنزهوا من البول، فإن أكثر عذاب القبر منه، ما معنى هذا؟","title":"ما معنى: «تنزهوا من البول فإن أكثر عذاب القبر منه»؟","answer":"الجواب: هذا حديث جيد، رواه الحاكم في صحيحه ورواه جماعة، ولفظه: استنزهوا من البول؛ فإن عامة عذاب القبر منه، وفي لفظ: أكثر عذاب القبر من البول، فمعناه: التحفظ، معناه: التحفظ من البول والحذر منه، فإذا أراد الإنسان يبول يبول في محل لين، أو في جحر من محل قضاء الحاجة، لئلا يطير إليه الرشاش رشاش البول، فالمرأة والرجل كذلك عليهما جميعاً أن يعتنيا بهذا الأمر، فيكون البول في محل لا يطشش على الإنسان، وإذا أصابه شيء منه، طشش على فخذه، أو طشش على قدمه، فيصب عليه الماء، ويغسله عن ما أصابه، يغسل ما أصابه، حتى يكون قد تحرز من البول، وإذا كان المحل لين كالأرض اللينة، أو وضع الفرج على نفس الجحر الذي يذهب فيه الماء، حتى لا يطشش عليه كفى ذلك، لكن بكل حال التنزه والتحرز طيب، فلو قدر أنه صادف البول حافة المحل البول فطشش على فخذ أو على ساق أو قدم، فإن المسلم والمسلمة عليهما أن يغسلا ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/6002/ما-معنى-تنزهوا-من-البول-فان-اكثر-عذاب-القبر-منه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_093/09303.mp3","categories":["التفسير","شروح الحديث"]},{"id":8328,"question":"هذه رسالة من المرسل (ك. ح. ص) مصري يعمل بالمملكة، وقد عرضنا في حلقة مضت سؤالين له، وهذه بقية أسئلته يقول في أولها: قال تعالى: يَا أَيُّهَا الَّذِينَ آمَنُوا عَلَيْكُمْ أَنفُسَكُمْ لا يَضُرُّكُمْ مَنْ ضَلَّ إِذَا اهْتَدَيْتُمْ [المائدة:105] كيف نجمع بينها وبين قول الرسول ﷺ: كلكم راع وكلكم مسئول عن رعيته هذه خلاصة سؤاله؟","title":"الجمع بين: {عَلَيْكُمْ أَنفُسَكُمْ} وحديث: «كلكم راع»","answer":"الجواب: ليس بين الآية المذكورة الكريمة وبين الحديث الشريف المذكور تخالف ولا تضاد، بل الآية والحديث متفقان، الله يقول سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا عَلَيْكُمْ أَنفُسَكُمْ لا يَضُرُّكُمْ مَنْ ضَلَّ إِذَا اهْتَدَيْتُمْ [المائدة:105] المعنى: عليكم أن تجاهدوا أنفسكم، عليكم إصلاح أنفسكم فـ: لا يَضُرُّكُمْ مَنْ ضَلَّ إِذَا اهْتَدَيْتُمْ [المائدة:105] أي: لا يضركم من ضل إذا أديتم الواجب بالأمر بالمعروف والنهي عن المنكر والقيام بما أوجب الله على العبد، فإن هذه هي الهداية، ما يكون العبد مهتدياً حتى يقوم بالواجب، وكونه يرعى من تحت يده ويقوم بما يلزم، وكونه يأمر بالمعروف وينهى عن المنكر ويدعو إلى الله كل هذا من طرق الهداية، فلا يكون مهتدياً حتى يؤدي ما أوجب الله عليه من الواجبات العينية والواجبات المتعلقة بالمجتمع من أمر بمعروف ونهي عن منكر، وغير هذا مما يلزم للمجتمع، فالحاصل أن قوله سبحانه: لا يَضُرُّكُمْ مَنْ ضَلَّ إِذَا اهْتَدَيْتُمْ [المائدة:105] معناه إذا أديتم الواجب، ومن ترك الحبل على الغارب ولم يأمر بمعروف ولم ينه عن منكر، ولم يقم بحق الرعية ما أدى الواجب ولا اهتدى الهداية الكاملة، بل هدايته ناقصة غير تامة فيكون مؤاخذ بذلك، يكون هذا الرجل الذي قصر في الواجب يكون مؤاخذاً بما قصر فيه؛ لأن هدايته ناقصة، والله يقول: لا يَضُرُّكُمْ مَنْ ضَلَّ إِذَا اهْتَدَيْتُمْ [المائدة:105] والذي لم يأمر بالمعروف ولم ينه عن المنكر، ولم يقم بالرعاية التي عليه ما يكون مهتدياً الهداية المطلقة الكاملة، بل تكون هدايته ناقصة ضعيفة فيها خلل فيؤاخذ بهذا الخلل وهذا النقص. نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6138/الجمع-بين-عليكم-انفسكم-وحديث-كلكم-راع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_202/20203.mp3","categories":["التفسير","شروح الحديث"]},{"id":8329,"question":"هذه رسالة من المرسل (ك. ح. ص) مصري يعمل بالمملكة، وقد عرضنا في حلقة مضت سؤالين له، وهذه بقية أسئلته يقول في أولها: قال تعالى: يَا أَيُّهَا الَّذِينَ آمَنُوا عَلَيْكُمْ أَنفُسَكُمْ لا يَضُرُّكُمْ مَنْ ضَلَّ إِذَا اهْتَدَيْتُمْ [المائدة:105] كيف نجمع بينها وبين قول الرسول ﷺ: كلكم راع وكلكم مسئول عن رعيته هذه خلاصة سؤاله؟","title":"الجمع بين: {عَلَيْكُمْ أَنفُسَكُمْ} وحديث: «كلكم راع»","answer":"الجواب: ليس بين الآية المذكورة الكريمة وبين الحديث الشريف المذكور تخالف ولا تضاد، بل الآية والحديث متفقان، الله يقول سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا عَلَيْكُمْ أَنفُسَكُمْ لا يَضُرُّكُمْ مَنْ ضَلَّ إِذَا اهْتَدَيْتُمْ [المائدة:105] المعنى: عليكم أن تجاهدوا أنفسكم، عليكم إصلاح أنفسكم فـ: لا يَضُرُّكُمْ مَنْ ضَلَّ إِذَا اهْتَدَيْتُمْ [المائدة:105] أي: لا يضركم من ضل إذا أديتم الواجب بالأمر بالمعروف والنهي عن المنكر والقيام بما أوجب الله على العبد، فإن هذه هي الهداية، ما يكون العبد مهتدياً حتى يقوم بالواجب، وكونه يرعى من تحت يده ويقوم بما يلزم، وكونه يأمر بالمعروف وينهى عن المنكر ويدعو إلى الله كل هذا من طرق الهداية، فلا يكون مهتدياً حتى يؤدي ما أوجب الله عليه من الواجبات العينية والواجبات المتعلقة بالمجتمع من أمر بمعروف ونهي عن منكر، وغير هذا مما يلزم للمجتمع، فالحاصل أن قوله سبحانه: لا يَضُرُّكُمْ مَنْ ضَلَّ إِذَا اهْتَدَيْتُمْ [المائدة:105] معناه إذا أديتم الواجب، ومن ترك الحبل على الغارب ولم يأمر بمعروف ولم ينه عن منكر، ولم يقم بحق الرعية ما أدى الواجب ولا اهتدى الهداية الكاملة، بل هدايته ناقصة غير تامة فيكون مؤاخذ بذلك، يكون هذا الرجل الذي قصر في الواجب يكون مؤاخذاً بما قصر فيه؛ لأن هدايته ناقصة، والله يقول: لا يَضُرُّكُمْ مَنْ ضَلَّ إِذَا اهْتَدَيْتُمْ [المائدة:105] والذي لم يأمر بالمعروف ولم ينه عن المنكر، ولم يقم بالرعاية التي عليه ما يكون مهتدياً الهداية المطلقة الكاملة، بل تكون هدايته ناقصة ضعيفة فيها خلل فيؤاخذ بهذا الخلل وهذا النقص. نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6138/الجمع-بين-عليكم-انفسكم-وحديث-كلكم-راع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_202/20203.mp3","categories":["التفسير","شروح الحديث"]},{"id":8377,"question":"أولى رسائل هذه الحلقة سماحة الشيخ، رسالة وصلت إلى البرنامج من الأخ أحمد شوقي حسن علي مدرس مصري بالمملكة، بمدرسة شداد بن أوس، سراة عبيدة أبها، أخونا يسأل سؤالاً واحد تقريباً متفرع فيقول: يقول الحق تبارك وتعالى، أعوذ بالله من الشيطان الرجيم: إِنَّ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ كَانَتْ لَهُمْ جَنَّاتُ الْفِرْدَوْسِ نُزُلًا[الكهف:107]۝خَالِدِينَ فِيهَا لا يَبْغُونَ عَنْهَا حِوَلًا [الكهف:108]، ويقول سبحانه: أَمَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ فَلَهُمْ جَنَّاتُُ الْمَأْوَى نُزُلًا بِمَا كَانُوا يَعْمَلُونَ [السجدة:19] إلى غير ذلك من الآيات التي توضح ثواب الذين آمنوا وعملوا الصالحات والتي وردت في القرآن الكريم، وقد سمعت حديثاً عن رسول الله ﷺ يقول فيه: لن يدخل أحد عمله الجنة، قالوا: ولاا أنت يا رسول الله؟ قال: ولا أنا، إلا أن يتغمدني الله برحمته.و كيف نوفق بين مفهوم الحديث الشريف، وبين مفهوم الآيات الكريمة، وفقكم الله؟","title":"معنى حديث: «لا يدخل أحد منكم الجنة بعمله»","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فليس بحمد الله بين الآيات وبين الأحاديث اختلاف، فالله جل وعلا بين أن أسباب دخول الجنة أعمالهم الصالحة، كما قال : ادْخُلُوا الْجَنَّةَ بِمَا كُنتُمْ تَعْمَلُونَ [النحل:32] إِنَّ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ كَانَتْ لَهُمْ جَنَّاتُ الْفِرْدَوْسِ نُزُلًا [الكهف:107] والآيات في هذا المعنى كثيرة، تبين أن الأعمال الصالحة هي أسباب دخول الجنة، كما أن الأعمال الخبيثة هي أسباب دخول النار، والحديث يبين أن دخولهم الجنة ليس بمجرد العمل، بل لا بد من عفو الله ورحمته سبحانه وتعالى، فهم دخلوها بأسباب أعمالهم، ولكن الذي أوجب ذلك رحمته سبحانه، وعفوه ومغفرته، ولهذا يقول ﷺ: والذي نفسي بيده، لا يدخل الجنة أحد منكم بعمله، قالوا: ولا أنت يا رسول الله؟ قال: ولا أنا، إلا أن يتغمدني الله برحمة منه وفضل فالباء هنا باء العوض، يعني: ليست عوض العمل، ولكنه مجرد رحمة الله وعفوه سبحانه وتعالى، حصل بذلك قبول العمل، ودخول الجنة والنجاة من النار، فهو الذي تفضل بالقوة على العمل ويسر العمل وأعان عليه، فكل خيرٍ منه سبحانه وتعالى، ثم تفضل بإدخال العبد الجنة، وإنجائه من النار بأسباب أعماله الصالحة، فالمعول على عفوه ورحمته، لا على عمل العبد، فعمل العبد لو شاء الله جل وعلا لما كان هذا العمل، ولما وفق له، فهو الذي وفق له وهداه له، سبحانه وتعالى، فله الشكر وله الحمد جل وعلا، فدخولهم الجنة برحمته وفضله ومغفرته، لا بمجرد أعمالهم، بل أعمالهم أسباب، والذي يسرها وأوجب دخول الجنة ومن بذلك هو الله وحده سبحانه وتعالى. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/6226/معنى-حديث-لا-يدخل-احد-منكم-الجنة-بعمله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_115/11501.mp3","categories":["شروح الحديث"]},{"id":8445,"question":"أختنا تسأل وتقول في الحديث: استوصوا بالنساء خيراً، فإن المرأة خلقت من ضلع أعوج، وإن أعوج ما في الضلع أعلاه .. إلى آخر الحديث، الرجاء توضيح معنى الحديث، مع توضيح: أعوج ما في الضلع أعلاه؟","title":"معنى حديث: (استوصوا بالنساء خيراً..)","answer":"الجواب: هذا حديث صحيح رواه الشيخان في الصحيحين، عن النبي ﷺ أنه قال: استوصوا بالنساء خيراً، هذا أمر للأزواج والآباء والإخوة وغيرهم أن يستوصوا بالنساء خيراً، وأن يحسنوا إليهن، وأن لا يظلموهن، وأن يعطوهن حقوقهن، هذا واجب على الرجال من الآباء والإخوة والأزواج أن يتقوا الله في النساء، وأن يعطوهم حقوقهن، هذا هو الواجب؛ ولهذا قال: استوصوا بالنساء خيراً، وينبغي أن لا يمنع من ذلك كونها قد تسيء إلى زوجها أو إلى أقاربها بلسانها أو بغير ذلك؛ لأنهن خلقن من ضلع كما قال النبي صلى الله عليه وسلم، وإن أعوج ما في الضلع أعلاه، ومعلوم أن أعلاه ما يلي منبت الضلع، فإن الضلع يكون فيه اعوجاج هذا هو المعروف فيه، فالمعنى: أنه لا بد يكون في خلقها شيء من العوج والنقص، ولهذا في الحديث الآخر في الصحيحين: ما رأيت من ناقصات عقل ودين أذهب للب الرجل الحازم من إحداكن، فبين ﷺ أنهن ناقصات عقل ودين، وإن كن لا يرضين بذلك في الغالب، يكرهن أن يسمعن هذا الكلام إلا من هداه الله ووفقه، فالمقصود أن هذا حكم النبي ﷺ، وهو ثابت في الصحيحين من حديث أبي سعيد الخدري .\nومعنى نقص العقل كما قال النبي ﷺ أن شهادة إحداهن بنصف الرجل، فالمرأتان برجل، هذا من نقص العقل، ومن نقص الدين كما قال النبي ﷺ: تمكث الأيام والليالي لا تصلي، يعني: من أجل الحيض، وهكذا في النفاس، وهذا نقص كتبه الله عليها، فينبغي لها أن تعترف بذلك، ولا يمنع من هذا كون بعضهن عندها حذق وعندها معرفة وعندها بصيرة، لكن لا يمنع ذلك من كون النقص موجود، فهي مهما بلغت من العلم، ومهما بلغت من الذكاء والبصيرة، هذا النقص لازم لها، هذا نقص لابد منه، فشهادة المرأتين برجل، وهكذا ما يصيبها من الحيض والنفاس هذا واقع، فينبغي للمرأة أن تعرف قدرها، وأن تقف عند حدها، وأن تسأل الله التوفيق، وأن تجتهد في الخير، أما أن تحاول مخالفة الشريعة فيما بين الله ورسوله فهذا غلط منها ونقص عليها، وهو من نقصها أيضاً، والله المستعان. نعم.","link":"https://binbaz.org.sa/fatwas/6329/معنى-حديث-استوصوا-بالنساء-خيرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_120/12010.mp3","categories":["شروح الحديث"]},{"id":8449,"question":"أختنا أيضاً تسأل عن قول الرسول ﷺ: مائلات مميلات؟","title":"معنى حديث: (صنفان من أهل النار لم أرهما ...)","answer":"الجواب: هذا حديث صحيح رواه مسلم في صحيحه، عن النبي ﷺ أنه قال: صنفان من أهل النار لم أرهما: رجال بأيديهم سياط كأذناب البقر يضربون بها الناس، ونساء كاسيات عاريات، مائلات مميلات، رءوسهن كأسنمة البخت المائلة، لا يدخلن الجنة ولا يجدن ريحها... الحديث، وهذا وعيد عظيم، يجب الحذر مما دل عليه، فالرجال الذين بأيديهم سياط كأذناب البقر هم من يتولى ضرب الناس بغير حق من شرطة، أو رجال آخرين من غيرهم، كل من يتولى ضرب الناس بغير حق هو داخل في هذا الحديث، سواء كان بأمر الدولة أو بغير أمر الدولة؛ لأن الدولة إنما تطاع في المعروف، يقول ﷺ: إنما الطاعة في المعروف، لا طاعة لمخلوق في معصية الخالق، وأما قوله ﷺ: نساء كاسيات عاريات مائلات مميلات فقد فسر ذلك أهل العلم بأن معنى قوله: (كاسيات) يعني: من نعم الله، (عاريات): من شكرها، لم يقمن بطاعة الله، بل تجرأن على المعاصي والسيئات، مع إنعام الله عليهن بالمال وغيره، وفسر أيضاً بمعنى آخر: وهو أن معنى (كاسيات): يعني: كسوة اسمية لا حقيقة لها، يعني: أنها كسوة لا يحصل بها المقصود؛ ولهذا قال: (عاريات)، فهناك كسوة لكنها لا قيمة لها، ولا نفع لها؛ إما لقصرها؛ وإما لرقتها، رقيقة ترى منها العورات، أو قصيرة تبدو منها الأرجل، أو غيرها مما الأيدي والصدور ونحو ذلك.\nفالحاصل أنها كسوة لا يحصل بها المقصود؛ ولهذا سميت عارية؛ لعدم وجود الكفاية في الكسوة، بل هي كسوة رقيقة مبدية للعورات، أو قصيرة لم تستر البدن كله.\n(مائلات) يعني: عن العفة والاستقامة، يعني عندهن معاصي وسيئات؛ ولهذا قيل لهن: مائلات، يعني: عن العفة، كالتي تتعاطى الفاحشة، أو عن أداء الفرائض من الصلوات وغيرها.\n(مميلات): المعنى: مميلات لغيرهن، يعني: أنهن يدعين إلى الشر والفساد، فهن بأفعالهن وأقوالهن يملن غيرهن إلى الفساد والمعاصي وتعاطي الفواحش؛ لعدم إيمانهن أو لضعف إيمانهن وقلة إيمانهن.\nفمقصود النبي ﷺ من ذلك التحذير، المقصود من هذا التحذير من هذا العمل السيئ، والتحذير من اتخاذ هؤلاء الموصوفات صديقات أو جليسات، بل يجب تحذيرهن والإنكار عليهن، وأن لا يتخذن جليسات ولا صديقات وهن بهذه الحال؛ لما عندهن من الفساد والشر.\nوقوله ﷺ: رءوسهن كأسنمة البخت المائلة، قال بعض أهل العلم: معنى ذلك: أنهن يعظمن الرءوس، بما يجعلن عليها من الخرق واللفائف، وغير ذلك حتى تكون مثل أسنمة البخت المائلة، والبخت: نوع من الإبل لها سنامان بينهما شيء من الانخفاض، فهذا مائل إلى جهة، وهذا مائل إلى جهة طرف مائل إلى جهة وطرف مائل إلى جهة، فهؤلاء النسوة لما عظمن رءوسهن وكبرن رءوسهن بما يجعلن عليها، أشبهن هذه الأسنمة.\nقوله: لا يدخلن الجنة ولا يجدن ريحها هذا وعيد شديد يفيد الحذر، ولا يلزم من ذلك الكفر ولا خلودهن في النار كسائر المعاصي، هذا وعيد، فإذا كن مسلمات ولكن تعاطين هذه الفواحش، فهذا من أسباب دخولهن النار والعقاب في النار بقدر معاصيهن، ولا يخلدن في النار إذا كن مسلمات موحدات لله ، مؤمنات بالرسول ﷺ، لا يخلدن في النار، ولكن هن متوعدات بهذا الوعيد الشديد على معاصيهن وسيئاتهن.\nوأهل السنة والجماعة يقولون: إن العاصي ولو دخل النار لا يخلد، هو على خطر لكن لا يخلد إذا دخلها بل يعذب على قدر معاصيه التي مات عليها ولم يتب، ثم يخرجه الله من النار بعد التمحيص والتطهير إلى الجنة، هذا هو قول أهل السنة والجماعة خلافاً للخوارج والمعتزلة ، الخوارج والمعتزلة يقولون: إن من دخل النار يخلد فيها مطلقا، وهذا قول باطل وضلال، فعند المعتزلة وعند الخوارج: أن الزاني مخلد في النار، والزانية مخلدة في النار، والسارق مخلد في النار، والعاق لوالديه مخلد في النار، والقاطع رحمه مخلد في النار، والمرابي مخلد في النار إذا دخلها كلهم؛ لأنهم عندهم أن هذه المعاصي توجب النار، والخلود فيها أبد الآباد كالكفار نعوذ بالله من ذلك، وهذا قول فاسد عند أهل السنة وخطأ، قد ثبت عن رسول الله ﷺ، وقد تواترت عنه الأخبار: أن العصاة يخرجون من النار، وأنه يشفع فيهم النبي ﷺ، ويشفع فيهم المؤمنون، ويشفع فيهم أفراطهم، وتشفع الملائكة، فيخرج الله من النار كل من كان في قلبه مثقال حبة خردل من إيمان، مثقال شعيرة من إيمان، مثقال برة من إيمان.\nالمقصود أن أهل المعاصي الموحدين المسلمين الذين دخلوا النار بمعاصيهم وهم ليسوا كفاراً، فإنهم لا يخلدون في النار، بل متى دخلوها عذبوا فيها بقدر الجرائم التي ماتوا عليها، وبعد التطهير والتمحيص يخرجهم الله من النار فضلاً منه سبحانه وتعالى، إما بشفاعة الشفعاء، وإما بمجرد فضله ورحمته سبحانه وتعالى من دون شفاعة أحد، فضلاً من الله عز وجل.\nهذا هو الذي هو عليه أهل السنة والجماعة من أصحاب النبي ﷺ، ومن أتباعهم بإحسان رضي الله عنهم. نعم.","link":"https://binbaz.org.sa/fatwas/6333/معنى-حديث-صنفان-من-اهل-النار-لم-ارهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_121/12102.mp3","categories":["شروح الحديث"]},{"id":8452,"question":"أولى رسائل هذه الحلقة سماحة الشيخ رسالة وصلت إلى البرنامج من الطائف باعثها أخونا محمد بن زرعة يسأل عن قول النبي ﷺ: ألا إني أوتيت القرآن ومثله معه نرجو أن تتفضلوا ببيان المقصود من قوله ﷺ: وأوتيت مثله معه؟","title":"معنى حديث «ألا إني أوتيت القرآن ومثله معه»","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فهذا الحديث من الأحاديث الصحيحة الثابتة عن رسول الله عليه الصلاة والسلام، ومعنى (ومثله معه) يعني: أن الله أعطاه وحياً آخر وهو السنة التي تفسر القرآن وتبين معناه، كما قال الله : وَأَنزَلْنَا إِلَيْكَ الذِّكْرَ لِتُبَيِّنَ لِلنَّاسِ مَا نُزِّلَ إِلَيْهِمْ [النحل:44] فهو ﷺ أوحى الله إليه القرآن وأوحى إليه أيضاً السنة، وهي الأحاديث التي ثبتت عنه عليه الصلاة والسلام فيما يتعلق بالصلاة والزكاة والصيام والحج والمعاملات وغير ذلك، فالسنة وحي ثاني أوحاه الله إليه عليه الصلاة والسلام، وهو يعبر عن ذلك بأحاديثه التي بينها للأمة، وتلاها على الأمة عليه الصلاة والسلام.\nمثل قوله عليه الصلاة والسلام: إنما الأعمال بالنيات، وإنما لكل امرئ ما نوى ومثل قوله ﷺ: لا تقبل صلاة أحدكم إذا أحدث حتى يتوضأ لا تقبل صلاة بغير طهور، ولا صدقة من غلول ومثل قوله ﷺ: الصلوات الخمس، ورمضان إلى رمضان، والجمعة إلى الجمعة، كفارات لما بينهن ما لم تغش الكبائر إلى غير هذا.\nفأحاديثه ﷺ وحي ثاني غير وحي القرآن، ومعناها وحي وألفاظها من النبي عليه الصلاة والسلام، وقد يكون بعضها أحاديث قدسية من كلام الرب  أوحاها الله إلى نبيه عليه الصلاة والسلام فتسمى أحاديث قدسية، وهي من كلام الله عز وجل وهي وحي ثاني غير وحي القرآن.\nفالقرآن أنزل للإعجاز، وأما الأحاديث القدسية فهي أنزلت لما فيها من العظة والتذكير والأحكام التي تنفع الأمة، فهي وحي ثاني من الله  للرسول عليه الصلاة والسلام، قال تعالى: وَالنَّجْمِ إِذَا هَوَى ۝ مَا ضَلَّ صَاحِبُكُمْ وَمَا غَوَى ۝ وَمَا يَنْطِقُ عَنِ الْهَوَى ۝ إِنْ هُوَ إِلَّا وَحْيٌ يُوحَى [النجم:1-4] فالوحي على هذا أنواع ثلاثة:\nالقرآن الكريم: وهو الذي جعله الله معجزة عظيمة مستمرة لرسول الله عليه الصلاة والسلام لفظه ومعناه، وبين فيه أحكامه ، وهو كلامه  لا يَأْتِيهِ الْبَاطِلُ مِنْ بَيْنِ يَدَيْهِ وَلا مِنْ خَلْفِهِ تَنزِيلٌ مِنْ حَكِيمٍ حَمِيدٍ [فصلت:42].\nوالوحي الثاني: أحاديث قدسية من كلام الله عز وجل، أوحاها الله لنبيه ﷺ وليس من القرآن، مثل قوله ﷺ عن الله  أنه قال سبحانه: يا عبادي! إني حرمت الظلم على نفسي وجعلته بينكم محرماً فلا تظالموا، يا عبادي! كلكم ضال إلا من هديتهه فاستهدوني أهدكم، يا عبادي! كلكم جائع إلا من أطعمته فاستطعموني أطعمكم، يا عبادي! كلكم عار إلا من كسوته فاستكسوني أكسكم،، يا عبادي! إنكم لن تبلغوا ضري فتضروني ولن تبلغوا نفعي فتنفعوني إلى آخره، في أحاديث أخرى عن الله .\nوالوحي الثالث: وحي أوحاه الله إليه وخبر عنه النبي ﷺ وبينه للأمة، فهو من الله وحي وهو من كلام النبي ﷺ لا من كلام الله مثلما تقدم في قوله ﷺ: إنما الأعمال بالنيات، وإنما لكل امرئ ما نوى ومثل قوله ﷺ: البيعان بالخيار ما لم يتفرقا، فإن صدقا وبينا بورك لهما في بيعهما، وإن كتما وكذبا محقت بركة بيعهما ومثل قوله ﷺ: لا تقبل صلاة بغير طهور ولا صدقة من غلول ومثل قوله ﷺ في الحديث الصحيح يقول عليه الصلاة والسلام: لا يحل سلف وبيع، ولا شرطان في بيع، ولا بيع ماا ليس عندك وما أشبه ذلك من الأحاديث الكثيرة الواردة عنه عليه الصلاة والسلام.\nفهي كلها وحي لكنها وحي بالمعنى وألفاظها ألفاظ النبي عليه الصلاة والسلام.\nوهي من جهة الله أوحاها الله إلى نبيه، وأخبره بها ونزل بها الوحي إليه عليه الصلاة والسلام ليبلغها الناس في أحكام دينهم من العبادات وغيرها. نعم.\nالمقدم: بارك الله فيكم، إذاً المثلية من حيث الوحي سماحة الشيخ من حيث كون..\nالشيخ: من حيث الوحي نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6429/معنى-حديث-الا-اني-اوتيت-القران-ومثله-معه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_122/12201.mp3","categories":["شروح الحديث"]},{"id":8453,"question":"الرسالة التالية رسالة وصلت إلى البرنامج من الكويت -السالمية- وباعثها أخونا خالد محمد مناحي أخونا له سؤالان:سؤاله الأول يقول: قال رسول الله ﷺ: ما أصاب المؤمن من هم ولا غم ولا حزن حتى الشوكة يشاكها إلا كفر الله من خطاياه أرجو إفادتي عن صحة هذا الحديث، وإذا كان صحيحاً: هل العقم -أي: عدم الإنجاب- يعتبر مكفراً لسيئات بني آدم، لكون العقم محزناً للإنسان لعدم وجود أولاد، وقد جعل الله الأولاد والمال من زينة الحياة الدنيا، أرجو إرشادي جزاكم الله خيراً؟","title":"ما صحة حديث: «ما أصاب المؤمن من هم» وما معناه؟","answer":"الجواب: نعم هذا الحديث صحيح خرجه مسلم في صحيحه، وهو من نعم الله وفضله سبحانه وتعالى أن ما أصاب العبد من هم ولا غم ولا نصب ولا وصب ولا أذى، حتى الشوكة يشاكها إلا كفر الله بها من خطاياه، ولا ريب أن العقم من المصائب فهو مما يكفر به الخطايا، العقم مصيبة مما يحزن العبد ومما يؤذي العبد والله جل وعلا يكفر به من الخطايا والسيئات كما يكفر بالهم والحزن والوصب والنصب ونحو ذلك، بل هو أعظم من كثير من المصائب، فإذا احتسب العبد وصبر على ذلك ورجا ما عند الله من المثوبة فله عند الله الخير الكثير. نعم.","link":"https://binbaz.org.sa/fatwas/6430/ما-صحة-حديث-ما-اصاب-المومن-من-هم-وما-معناه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_122/12202.mp3","categories":["شروح الحديث","الحكم على الأحاديث"]},{"id":8672,"question":"تقول في سؤال آخر: قال الرسول ﷺ ما معناه لامرأة: اغسلي الدم وصلي أي: دم الحيض، فهل يكون هذا في أي وقت من أوقات نزول الدورة أم قرب انتهائها، وإذا اغتسلت وتطهرت منها وصليت فهل يحل الجماع أم لا؟","title":"معنى حديث: (اغسلي عنك الدم وصلي)","answer":"الجواب: هذا عند انتهاء الحيض، إذا انتهى الحيض أمرها النبي صلى الله عليه وسلم أن تغسل الدم وتغتسل وتصلي، إذا انتهت الدورة وفي ثوبها شيء غسلت ما أصاب الثوب، تقرصه بالماء تحكه بظفرها أو بحجر أو بعظم أو بغيره ثم تغسله بالماء ويطهر الثوب وتصلي فيه بعد ذلك، وكذلك إذا اغتسلت بعد ذلك بعد زوال الدم والطهر ووجود الطهر فإنها تصلي بعد ذلك وتحل لزوجها.\nالمقصود: أن هذا كله عند انتهاء الدورة إذا رأت الطهارة إما بالقصة البيضاء أو حشت بقطن ونحوه في الفرج فخرج نقياً فإنها تغتسل غسل الحيض وتغسل إن كان في بدنها شيء إذا كان أصاب فخذها أو رجلها شيء من الدم تغسله ثم تغتسل غسل الحيض وإذا أصاب ثوبها شيء أو سراويلها غسلته أيضاً وبعد هذا تصلي وتحل لزوجها. نعم.\nالمقدم: جزاكم الله خير، الحقيقة لها كلام بعد هذا يفهم منه أنها فهمت حديث الرسول صلى الله عليه وسلم بأن تغسل المرأة دمها وهي في أثناء الحيض ثم تصلي؛ لأنها تقول: هل كلما عاد علي الدم مرة أخرى طوال اليوم أغتسل وأصلي أم لا؟\nالشيخ: مادام الدم موجود لا تغتسلي، إنما الغسل يكون عند النهاية، أما مادام الدم يتكرر في الليل والنهار فأنت في الحيض حتى تنتهي المدة وتحصل الطهارة، فإذا انتهت المدة خمساً أو ستاً أو سبعاً أو ثمان حسب العادة، إذا انتهت العادة ورأت المرأة الطهارة ... الماء الأبيض، أو جعلت في فرجها شيء من القطن ثم أخرجته أو نحوه من الأشياء الدالة على نظافتها فإنها تغتسل، وتصلي وتحل لزوجها وتصوم إذا شاءت وانتهى الأمر، أما أنها تغتسل كل ساعة، لا ؛ لأن الدم يجري تارة ويقف أخرى ما دام المدة موجودة ما بعد انتهت المدة ولا رأت الطهارة فإنها لا تغتسل حتى تنتهي المدة وينقطع الدم. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6810/معنى-حديث-اغسلي-عنك-الدم-وصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_214/21415.mp3","categories":["الغسل","الحيض والنفاس","شروح الحديث"]},{"id":8674,"question":"تقول في سؤال آخر: قال الرسول ﷺ ما معناه لامرأة: اغسلي الدم وصلي أي: دم الحيض، فهل يكون هذا في أي وقت من أوقات نزول الدورة أم قرب انتهائها، وإذا اغتسلت وتطهرت منها وصليت فهل يحل الجماع أم لا؟","title":"معنى حديث: (اغسلي عنك الدم وصلي)","answer":"الجواب: هذا عند انتهاء الحيض، إذا انتهى الحيض أمرها النبي صلى الله عليه وسلم أن تغسل الدم وتغتسل وتصلي، إذا انتهت الدورة وفي ثوبها شيء غسلت ما أصاب الثوب، تقرصه بالماء تحكه بظفرها أو بحجر أو بعظم أو بغيره ثم تغسله بالماء ويطهر الثوب وتصلي فيه بعد ذلك، وكذلك إذا اغتسلت بعد ذلك بعد زوال الدم والطهر ووجود الطهر فإنها تصلي بعد ذلك وتحل لزوجها.\nالمقصود: أن هذا كله عند انتهاء الدورة إذا رأت الطهارة إما بالقصة البيضاء أو حشت بقطن ونحوه في الفرج فخرج نقياً فإنها تغتسل غسل الحيض وتغسل إن كان في بدنها شيء إذا كان أصاب فخذها أو رجلها شيء من الدم تغسله ثم تغتسل غسل الحيض وإذا أصاب ثوبها شيء أو سراويلها غسلته أيضاً وبعد هذا تصلي وتحل لزوجها. نعم.\nالمقدم: جزاكم الله خير، الحقيقة لها كلام بعد هذا يفهم منه أنها فهمت حديث الرسول صلى الله عليه وسلم بأن تغسل المرأة دمها وهي في أثناء الحيض ثم تصلي؛ لأنها تقول: هل كلما عاد علي الدم مرة أخرى طوال اليوم أغتسل وأصلي أم لا؟\nالشيخ: مادام الدم موجود لا تغتسلي، إنما الغسل يكون عند النهاية، أما مادام الدم يتكرر في الليل والنهار فأنت في الحيض حتى تنتهي المدة وتحصل الطهارة، فإذا انتهت المدة خمساً أو ستاً أو سبعاً أو ثمان حسب العادة، إذا انتهت العادة ورأت المرأة الطهارة ... الماء الأبيض، أو جعلت في فرجها شيء من القطن ثم أخرجته أو نحوه من الأشياء الدالة على نظافتها فإنها تغتسل، وتصلي وتحل لزوجها وتصوم إذا شاءت وانتهى الأمر، أما أنها تغتسل كل ساعة، لا ؛ لأن الدم يجري تارة ويقف أخرى ما دام المدة موجودة ما بعد انتهت المدة ولا رأت الطهارة فإنها لا تغتسل حتى تنتهي المدة وينقطع الدم. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6810/معنى-حديث-اغسلي-عنك-الدم-وصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_214/21415.mp3","categories":["الغسل","الحيض والنفاس","شروح الحديث"]},{"id":8704,"question":"رسالة وصلت إلى البرنامج من الأخ: صهيب (ن . أ) أخونا يقول: لو تفضلتم بشرح الحديث التالي، يقول ﷺ: اثنتان في الناس هما بهم كفر: الطعن في الأنساب، والنياحة على الميت وما معنى الكفر بالذات في هذا الحديث؟","title":"شرح حديث: ( اثنتان في الناس هما بهم كفر..)","answer":"الجواب: هذا حديث صحيح رواه مسلم في الصحيح عن أبي هريرة رضي الله تعالى عنه عن النبي ﷺ أنه قال: اثنتان في الناس هما بهم كفر: الطعن في النسب، والنياحة على الميت الطعن في النسب: التنقص لأنساب الناس، فلان فيه كذا فلان فيه كذا، فلان نسبهم فيه كذا فيه كذا يطعن في أنسابهم ويعيبها لشيء في نفسه، أو ترفعاً وتكبراً، هذا لا يجوز، أما إذا كان من باب الخبر: بني تميم صفتهم كذا، قحطان كذا، قريش كذا، بني هاشم كذا، يخبر أنسابهم أنهم قبائل وأنهم كذا وأنهم..، يخبر عن أحوالهم من غير طعن بل يخبر عن أنسابهم وتفاصيلها، فهذا ليس من الطعن في الأنساب، الطعن معناه: العيب والتنقص لهم تكبراً وتعاظماً أو لإظهار عوراتهم والغيبة لهم ونحو ذلك، ليس قصده سوى ذلك.\nوالنياحة معناها: رفع الصوت على الميت، كونه ينوح يعني: يرفع صوته، يبكي بصوت واضح ظاهر، هذا ممنوع، والكفر هنا كفر دون كفر، الكفر هنا كفر منكر عند أهل العلم فهو كفر أصغر؛ لأن الكفر كفران، والظلم ظلمان، والشرك شركان؛ أكبر وأصغر، فالشرك الأكبر مثل: دعاء الأموات والاستغاثة بالأموات والنذر لهم، أو للأصنام، أو للأشجار والأحجار، أو للكواكب هذا شرك أكبر، والشرك الأصغر مثل قول: لولا الله وفلان، ما شاء الله وشاء فلان، هذا شرك أصغر، الواجب أن يقول: لولا الله ثم فلان، ما شاء الله ثم شاء فلان، وهكذا الحلف بغير الله كقوله: والنبي أو بالنبي أو وحياتك هذا شرك أصغر، هكذا الرياء اليسير مثل كونه يستغفر يسمع الناس يرائي أو يقرأ يرائي، هذا شرك أصغر.\nوالظلم ظلمان: أكبر وأصغر، فدعاء الأموات والاستغاثة بالأموات وجحد ما حرم الله كالزنا ونحوه يعني: استحلال ما حرم الله وجحد تحريمه، هذا كفر أكبر، وهكذا جحد ما أوجب الله كجحد وجوب الصلاة أو جحد وجوب الزكاة كفر أكبر، وكالذبح لغير الله والعبادة لغير الله كعبادة الكواكب والأموات والأصنام والأشجار هذا كفر أكبر.\nوكفر أصغر مثل: النياحة على الميت، مثل الطعن في الأنساب، مثل التبرؤ من الأنساب، مثل الحلف بغير الله، يقال: كفر دون كفر، هذه تفاصيل الشرك الأكبر والأصغر والظلم الأكبر والأصغر وهكذا الكفر الأصغر والأكبر.\nوهكذا الظلم مثل ظلم الناس في دمائهم وأموالهم هذا ظلم أصغر، والشرك الأكبر يسمى: ظلم أكبر، قال تعالى: وَالْكَافِرُونَ هُمُ الظَّالِمُونَ [البقرة:254] وقال سبحانه: الَّذِينَ آمَنُوا وَلَمْ يَلْبِسُوا إِيمَانَهُمْ بِظُلْمٍ أُوْلَئِكَ لَهُمُ الأَمْنُ وَهُمْ مُهْتَدُونَ [الأنعام:82] فسر النبي ﷺ الظلم هنا بالشرك الأكبر.\nفالكفر كفران والظلم ظلمان والشرك شركان؛ أكبر وأصغر، والذي في حديث: اثنتان في الناس هما بهم كفر: الطعن في النسب، والنياحة على الميت هذا من الكفر الأصغر. نعم.","link":"https://binbaz.org.sa/fatwas/6851/شرح-حديث-اثنتان-في-الناس-هما-بهم-كفر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_131/13111.mp3","categories":["شروح الحديث"]},{"id":8841,"question":"أيضًا يرجو شرح هذا الحديث: قال رسول الله ﷺ: أمرت أن أقاتل الناس حتى يشهدوا أن لا إله إلا الله وأن محمدًا رسول الله، ويقيموا الصلاة، ويؤتوا الزكاة، فإذا فعلوا ذلك عصموا مني دماءهم وأموالهم إلا بحق الإسلام وحسابهم على الله؟","title":"ما معنى: «أمرت أن أقاتل الناس حتى يشهدوا»؟","answer":"الجواب: هذا الحديث الصحيح قد رواه الشيخان: البخاري ومسلم في الصحيحين من حديث ابن عمر رضي الله تعالى عنهما قال: سمعت النبي يقول عليه الصلاة والسلام: أمرت أن أقاتل الناس حتى يشهدوا أن لا إله إلا الله وأني رسول الله، ويقيموا الصلاة، ويؤتوا الزكاة، فإذا فعلوا ذلك عصموا مني دماءهم وأموالهم إلا بحق الإسلام وحسابهم على الله عز وجل وهذا على ظاهره.\nفإن من أتى بالشهادتين وهو لا يأتي بها قبل ذلك، وأقام الصلاة وآتى الزكاة فإنه مسلم، يعتبر مسلمًا حرام الدم والمال إلا بحق الإسلام، إلا ما يوجبه الإسلام عليه بعد ذلك، كأن يزني فيقام عليه حد الزنا، إن كان بكرًا بالجلد والتغريب، وإن كان ثيبًا بالرجم الذي ينهي حياته، وهكذا بقية أمور الإسلام يطالب بها، هذا الذي أسلم وشهد هذه الشهادة وأقام الصلاة وآتى الزكاة، فيطالب بحقوق الإسلام وهو معصوم، معصوم الدم والمال إلا أن يأتي بناقض من نواقض الإسلام.\nوهكذا قوله في الحديث الآخر حديث أبي هريرة  أن النبي ﷺ: أمرت أن أقاتل الناس حتى يقولوا: لا إله إلا الله، فإذا قالوها عصموا مني دماءهم وأموالهم إلا بحقها وحسابهم على الله هذا الحديث مثل ذاك الحديث، من أتى بالتوحيد والإيمان بالرسالة فقد دخل في الإسلام ثم يطالب بحق الإسلام، يطالب بالصلاة والزكاة والصيام والحج وغير ذلك، فإن أدى ما أوجب الله عليه فهو مسلم حقًا، وإن امتنع من شيء أخذ بحق الله فيه، وأجبر وألزم بحقوق الله التي أوجبها على عباده.\nوهذا هو الواجب على جميع من دخل في الإسلام أن يلتزم بحق الإسلام، فإن لم يلتزم أخذ بحق الإسلام. نعم.","link":"https://binbaz.org.sa/fatwas/6996/ما-معنى-امرت-ان-اقاتل-الناس-حتى-يشهدوا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_165/16511.mp3","categories":["شروح الحديث"]},{"id":8842,"question":"أخونا كتب حديث رسول الله ﷺ: الدين النصيحة كتبه بالمعنى، أرجو من سماحة الشيخ أن يتفضل بشرح ذلكم الحديث أيضًا، حسب طلبه؟","title":"شرح حديث: (الدين النصيحة)","answer":"الجواب: هذا حديث عظيم، رواه مسلم في الصحيح من حديث تميم الداري وله شواهد عند غير مسلم، يقول ﷺ: الدين النصيحة قيل: لمن يا رسول الله؟ قال: لله، ولكتابه، ولرسوله، ولأئمة المسلمين وعامتهم فهو حديث عظيم يدل على أن الدين هو النصيحة، وذلك يدل على عظم شأنها؛ لأنه جعلها الدين، كما قال النبي ﷺ: الحج عرفة فيدل هذا الحديث على أن النصيحة هي الدين، وهي الإخلاص في الشيء والصدق فيه حتى يؤدى كما أوجب الله.\nفالدين هو النصيحة في جميع ما أوجب الله، وفي ترك ما حرم الله، وهذا عام يعم حق الله وحق الرسول وحق القرآن وحق الأئمة وحق العامة.\nوالنصيحة كما تقدم هي الإخلاص في الشيء والعناية به، والحرص على أن يؤدى كاملًا تامًا لا غش فيه ولا خيانة، يقال في لغة العرب: ذهب ناصح، يعني: ليس فيه غش، ويقولون أيضًا: عسل ناصح، يعني: ليس فيه غش، فهكذا يجب أن يكون المؤمن في أعماله ناصحًا لله ولكتابه ولرسوله ولأئمة المسلمين وعامتهم، هكذا.\nفالنصيحة لله توحيده سبحانه والإخلاص له وخلوص العبادة له جل وعلا من صلاة وصوم وحج وجهاد وغير ذلك، يعني: أن يعمل في غاية من الإخلاص لله، لا يعبد معه سواه، بل يعبده وحده، وينصح في هذه العبادة ويكملها.\nوهكذا ينصح في أداء ما فرض، وترك ما حرم الله عليه يؤديه كاملًا؛ لعلمه بأنه حق الله، وأن الله أوجبه عليه، فهو يخلص في ذلك ويعتني بذلك.\nوهكذا في حق القرآن يتدبره ويتعقله ويعمل بما فيه من الأوامر وينتهي عن النواهي، هو كتاب الله العظيم وحبله المتين.\nفالواجب العناية بالنصح لكتاب الله، وذلك بحفظ الأوامر وترك النواهي والوقوف عند الحدود حتى لا تخل بشيء من أوامر الله في القرآن وحتى لا تركب شيئًا من محارم الله، مع الإيمان بأنه كلام الله منزل غير مخلوق، منه بدأ وإليه يعود، هذا قول أهل السنة والجماعة قاطبة، كلام الله منه نزل على رسوله عليه الصلاة والسلام كما قال : نَزَلَ بِهِ الرُّوحُ الأَمِينُ ۝ عَلَى قَلْبِكَ لِتَكُونَ مِنَ الْمُنذِرِينَ [الشعراء:193-194].\nالمؤمن يؤمن بهذا، وهكذا المؤمنة، ويعتقد أنه كلام الله منزل غير مخلوق، منه بدأ وإليه يعود، خلافًا للجهمية ومن سار في ركابهم من المبتدعة.\nوهكذا النصح للرسول ﷺ بطاعة أوامر وترك نواهيه، والإيمان بأنه رسول الله حقًا، والدفاع عن سنته والذب عنها، كل هذا من النصح للرسول ﷺ، كونه يعتني بأحاديثه ويعرف صحيحها من سقيمها، ويذب عنها ويمتثلها ويقف عند الحدود التي حدتها السنة، كل هذا من النصيحة للرسول ﷺ.\nومن زاد على ذلك من أدائه الواجبات وتركه المحارم كان كمالًا للنصيحة وتمامًا لها.\nفالحاصل أنه بعنايته بما أمر الله به ورسوله، وبما دل عليه كتاب الله من الحقوق، يكون قد نصح لله ولكتابه ولرسوله، بأداء فرائض الله وترك محارم الله، والوقوف عند حدود الله، والإكثار من الثناء عليه وذكره  وخشيته جل وعلا، كل هذا من النصيحة لله ولكتابه ولرسوله. نعم.","link":"https://binbaz.org.sa/fatwas/6997/شرح-حديث-الدين-النصيحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_165/16512.mp3","categories":["شروح الحديث"]},{"id":8954,"question":"بارك الله فيكم. رسالة وصلت إلى البرنامج من العراق باعثها أحد الإخوة من هناك يقول: رمضان الطائي محافظة التأميم فيما يبدو، أخونا له مجموعة من الأسئلة نختار منها هذا السؤال يقول:إنني كثيراً ما أحفظ من الآيات من القرآن الكريم ولكنني بعد فترة أنساها، وكذلك عندما أقرأ آية فلا أعلم هل هي صحيحة أم لا، ثم أكتشف بعد ذلك أنني كنت مخطي، دلوني لو تكرمتم؟","title":"فضل حفظ القرآن وتعلمه ومجاهدة نسيانه","answer":"الجواب: المشروع لك يا أخي أن تجتهد في حفظ ما تيسر من كتاب الله، وأن تقرأ على أهل المعرفة من الإخوان الطيبين في المدارس أو في المساجد أو في البيت، وتحرص على ذلك، يقول النبي ﷺ: خيركم من تعلم القرآن وعلمه.\nخيار الناس أهل القرآن الذين تعلموه وعلموه الناس وعملوا به، ويقول ﷺ لبعض أصحابه: أيحب أحدكم أن يذهب إلى بطحان -إلى واد في المدينة- فيأتي بناقتين عظيمتين في غير إثم ولا قطيعة رحم؟ قالوا: يا رسول الله! كلنا يحب ذلك، فقال عليه الصلاة والسلام:: لأن يغدو أحدكم إلى المسجد فيتعلم آيتين من كتاب الله خير له من ناقتين عظيمتين، وثلاث خير من ثلاث، وأربع خير من أربع وأمثالهن من الإبل، فهذا يبين لنا فضل قراءة القرآن وتعلم القرآن، فأنت يا أخي تتعلم تتصل بالإخوان الطيبين في المساجد أو في المدارس أو في حلقات تحفيظ القرآن حتى تستفيد، وحتى تقرأ قراءة صحيحة.\nوأما ما يعرض من النسيان فلا حرج عليك، إذا نسيت بعض الشيء لا حرج، فالبشر ينسى، يقول النبي ﷺ: إنما أنا بشر أنسى كما تنسون، وسمع مرة قارئاً يقرأ فقال: رحم الله فلاناً لقد أذكرني آية كذا كنت أسقطتها، يعني: نسيتها.\nالمقصود أن الإنسان قد ينسى بعض الآيات، والأفضل أن يقول: نسيت؛ لأنه جاء في بعض الأحاديث أنه عليه الصلاة والسلام قال: لا يقولن أحدكم: نسيت آية كذا، نسيت آية كذا بل هو نسي، يعني: أنساه الشيطان، فلا يضرك أخي.\nأما حديث: من حفظ القرآن ثم نسيه لقي الله وهو أجذم، فهو حديث ضعيف عند أهل العلم لا يثبت عن النبي ﷺ، والنسيان ليس باختيار الإنسان وليس في طوقه قد ينسى مهما كان.\nفالمقصود أن المشروع لك أن تجتهد وتحرص على الحفظ، وتستعين بالله ثم بمن يتيسر من الإخوان في حفظ ما تيسر من كتاب الله، ثم تدرس ذلك وتعتني به وأبشر بالخير.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/7113/فضل-حفظ-القران-وتعلمه-ومجاهدة-نسيانه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_145/14503.mp3","categories":["فضائل الأعمال","شروح الحديث"]},{"id":8968,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من الأردن الزرقاء، باعثها أحد الإخوة من هناك يقول أبو محمد الناصري، أخونا يسأل ويقول: من سن سنة حسنة فله أجرها وأجر من عمل بها إلى يوم القيامة، هل هذا حديث، وهل إذا كان حديثاً فهل الرسول ﷺ ترك شيئاً لأحد حتى يستن به سنة في الإسلام، نرجو أن توضحوا لنا هذا المقام بالتفصيل، جزاكم الله خيراً؟","title":"ما معنى: «من سن في الإسلام سنة حسنة»؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فهذا الحديث صحيح، وهو يدل على شرعية إحياء السنن والدعوة إليها، والتحذير من البدع والشرور؛ لأنه ﷺ يقول: من سن في الإسلام سنة حسنة كان له أجرها وأجر من عمل بها من بعده لا ينقص ذلك من أجورهم شيئاً، ومن سن في الإسلام سنة سيئة كان عليه وزرها ووزر من عمل بها من بعده لا ينقص ذلك من أوزارهم شيئاً.\nوهذا مثل الحديث الذي رواه أبو هريرة  عن النبي ﷺ أنه قال: من دعا إلى هدى كان له من الأجر مثل أجور من تبعه لا ينقص ذلك من أجورهم شيئاً، ومن دعا إلى ضلالة كان عليه من الإثم مثل آثام من تبعه لا ينقص ذلك من آثامهم شيئاً، وهكذا حديث أبي مسعود الأنصاري ، يقول النبي ﷺ: من دل على خير فله مثل أجر فاعله.\nفمعنى (سن في الإسلام) يعني: أحيا سنة وأظهرها وأبرزها مما قد يخفى على الناس فيدعو إليها ويظهرها ويبرزها فيكون له من الأجر مثل أجور أتباعه فيها، وليس معناه الابتداع، ليس معناه أنه يبتدع في الإسلام بدعة حسنة، لا، كل بدعة ضلالة، يقول ﷺ: كل بدعة ضلالة.\nلكن المقصود: إحياء السنة وإظهارها، مثلاً: يكون في بلاد ما عندهم تعليم للقرآن، ما عندهم تعليم للسنة فيحيي هذه السنة، يجلس للناس يعلمهم القرآن يعلمهم السنة أو يأتي لهم بمعلمين، أو في بلاد يحلقون لحاهم أو يقصونها فصار هو يحيي هذه السنة وهذا المشروع يعني: يعفي لحيته ويربيها ويوفرها، فتابعه الناس في ذلك واقتدوا به عملاً بقول النبي ﷺ: قصوا الشوارب وأعفوا اللحى خالفوا المشركين، فلما رأوه قد وفر لحيته تابعوه فأحيا بينهم السنة وهي سنة واجبة، يعني: من الواجبات فيكون له مثل أجورهم.\nأو في بلاد يجهلون صلاة الجمعة ولا يصلون الجمعة فيعلمهم ويصلي بهم الجمعة أو ينصب بينهم ويصلي بهم الجمعة، أو في بلاد يجهلون الوتر فيعلمهم إياه في الليل؛ صلاة الوتر، أو ما أشبه ذلك من العبادات والأحكام المعلومة من الدين فيطرأ على بعض البلاد أو بعض القبائل جهلها، فالذي يحيها بينهم وينشرها ويبينها يقال له: سن في الإسلام سنة حسنة يعني: أظهر في الإسلام وبين في الإسلام سنة حسنة، وليس المراد أن يبتدع ما لم يأذن به الله؛ لأن البدعة ضلالة، يقول ﷺ في الحديث الصحيح: وإياكم ومحدثات الأمور فإن كل محدثة بدعة وكل بدعة ضلالة.\nويقول صلى الله عليه وسلم في الحديث الصحيح أيضاً: من عمل عملاً ليس عليه أمرنا فهو رد، وفي اللفظ الآخر: من أحدث في أمرنا هذا ما ليس منه فهو رد، متفق على صحته.\nويقول في خطبة الجمعة عليه الصلاة والسلام: أما بعد: فإن خير الحديث كتاب الله، وخير الهدي هدي محمد ﷺ، وشر الأمور محدثاتها، وكل بدعة ضلالة.\nفالبدع التي لا يشرعها الله لا يجوز الدعوة إليها ولا فعلها بل يكون فعلها إحياء للبدع، يكون الدعوة إليها دعوة إلى البدع فلا يجوز، وليس المراد في هذا الحديث هذا المعنى، من سن في الإسلام سنة حسنة، يعني: أحياها وأظهرها وبينها وأرشد إليها. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7126/ما-معنى-من-سن-في-الاسلام-سنة-حسنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_146/14601.mp3","categories":["شروح الحديث"]},{"id":8981,"question":"أخونا يسأل ويقول: عن النبي ﷺ قال: لا يأتي على الميت أشد من الليلة الأولى فارحموا أمواتكم بالصدقة، فمن لم يجد فليصل ركعتين يقرأ في كل ركعة فاتحة الكتاب مرة، وآية الكرسي والصلاة على النبي ﷺ وأيضًا يقرأ سورة الإخلاص إحدى عشرة مرة فهل هذا الأثر صحيح؟ وهل يجوز للمسلم أن يصليها لأموات أم لا أرشدونا جزاكم الله خيرًا؟","title":"ما صحة حديث: «لا يأتي على الميت أشد من الليلة الأولى»؟","answer":"الجواب: هذا الحديث ليس بصحيح ولا أصل له ولا يجوز الاعتماد عليه، ولكن الدعاء للميت في أول ليلة وفي جميع الليالي مطلوب، الدعاء بالمغفرة والرحمة هذا كله مطلوب، أما هذا الحديث الذي ذكره السائل فلا أصل له ولا يصلى للميت، يقول النبي ﷺ: إذا مات ابن آدم انقطع عمله إلا من ثلاث: صدقة جارية، أو علم ينتفع به، أو ولد صالح يدعو له، فإذا دعا له ولده أو أقاربه أو إخوانه المسلمون هذا طيب، أو تصدقوا عنه طيب، لكن لا يختص بالليلة الأولى في جميع الزمان.\nالصدقة على الميت في كل وقت تنفع الميت، والدعاء بالمغفرة والرحمة إذا كان مسلم ينفعه ذلك من إخوانه المسلمين ومن أقاربه، أما أن تخص الليلة الأولى بشيء فلا أصل في لذلك.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7139/ما-صحة-حديث-لا-ياتي-على-الميت-اشد-من-الليلة-الاولى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_174/17406.mp3","categories":["شروح الحديث","الحكم على الأحاديث"]},{"id":8988,"question":"ننتقل إلى رسالة أخرى وموضوع آخر، الرسالة من المستمع (ح. ف. ح) طالب علم في مكة المكرمة، عرضنا له سؤال في حلقة مضت، وفي هذه الحلقة يسأل ويقول: قال الله تعالى: إِنَّ أَكْرَمَكُمْ عِنْدَ اللَّهِ أَتْقَاكُمْ [الحجرات:13]، وقال ﷺ: كمل من الرجال كثير، ولم يكمل من النساء إلا مريم بنت عمران، وآسية بنت مزاحم، وفاطمة بنت محمد، وخديجة... الحديث، هل هناك تعارض بين الآية والحديث؟ وما معنى الكمال في الحديث؟","title":"معنى الكمال في حديث «كمل من الرجال كثير ولم...»","answer":"الجواب: ليس بين الآية والحديث المذكور وما جاء في معناه تعارض، فالآية تبين لنا أن أكرم الناس عند الله أتقاهم، لا أعظمهم نسبًا ولا أكثرهم مالا، ولا أرفعهم وظيفة، يقول جل وعلا: يَا أَيُّهَا النَّاسُ إِنَّا خَلَقْنَاكُمْ مِنْ ذَكَرٍ وَأُنثَى وَجَعَلْنَاكُمْ شُعُوبًا وَقَبَائِلَ لِتَعَارَفُوا إِنَّ أَكْرَمَكُمْ عِنْدَ اللَّهِ أَتْقَاكُمْ إِنَّ اللَّهَ عَلِيمٌ خَبِيرٌ [الحجرات:13]، فأكرم الناس عند الله وأفضلهم عنده أتقاهم له، معنى أتقاهم: يعني: أقومهم بحقه، بطاعته سبحانه وترك معصيته جل وعلا وهم الرسل عليهم الصلاة والسلام، ثم العلماء المستقيمون على طاعة الله وتقواه، وهم طبقات، ثم الأكمل فالأكمل والأفضل فالأفضل في طاعة الله عز وجل.\nفالمقصود أن أكمل الناس بعد الرسل هم أتقاهم، هم أكمل الناس وأكرم الناس عند الله ، ولما سئل النبي ﷺ عن أكرم الناس قال: أتقاهم.\nأما فضل خديجة وآسية ومريم بنت عمران وعائشة كذلك وفاطمة، كل هذا مسلم، وصحت به السنة وليس فيه معارضة، خديجة رضي الله عنها أم المؤمنين، وهي أم أكثر أولاد النبي عليه الصلاة والسلام، وهكذا فاطمة بنته عليه الصلاة والسلام، وهكذا مريم بنت عمران أم عيسى عليه الصلاة والسلام، وهكذا آسية بنت مزاحم امرأة فرعون ، وهكذا عائشة رضي الله عنها كلهم من كمل النساء، والكامل من النساء أقل من الكامل من الرجال، فالكمل في الرجال كثيرون ومن النساء قليلون، ولهذا بين لهم النبي ﷺ بهذا الحديث والكمال بالنظر إلى تقوى الله والقيام بحقه ، وقال في عائشة رضي الله عنها، يقول ﷺ: فضل عائشة على النساء كفضل الثريد على سائر الطعام، والثريد: هو الخبز واللحم، خبز الحنطة واللحم يقال له: ثريد، وهذا الطعام هو أفضل الطعام وأنفعه اللحم والحنطة البر.\nالمقصود أن عائشة لها فضل كبير، وخديجة كذلك، ومريم ، وآسية ، وفاطمة ، هؤلاء الخمس هم أكمل النساء وأفضل النساء، وهن متساويات في الفضل.\nوقد اختلف العلماء في تقديم بعضهن على بعض، ويكفينا أنهن أفضل النساء رضي الله عنهن وأرضاهن ورحمهن، وكمالهن من جهة تقواهن لله وقيامهن بحقه، واستقامتهن على دينه، لكن الكمل من الرجال في تقوى الله والقيام بحقه أكثر؛ لأنهم أصبر على التقوى، وهم أعلم بالله في الأغلب، وأكثر اطلاعًا على كتاب الله وسنة رسوله عليه الصلاة والسلام، وأكثر اطلاعًا على حلقات العلم وأسفارًا لطلب العلم، فلهذا يغلب على الرجال أن يكون علمهم أكثر من علم النساء وكمالهم أكثر بسبب ما حباهم الله من القوة على طلب العلم والحرص على تحصيله، ولما جبل عليه النساء من الضعف من بعض النواحي والعجز عن تحصيل العلوم من كل وجه، لما يعتريهن من الحمل والولادة وحاجات البيت وحاجات الزوج وغير ذلك.\nفالمقصود أن الكمل من الرجال بنص النبي ﷺ أكمل من الكمل من النساء، لأن الكمل من النساء قليلون لأسباب كثيرة والكمل من الرجال كثيرون، ولا تعارض بين الحديث وبين الآية الكريمة، نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7146/معنى-الكمال-في-حديث-كمل-من-الرجال-كثير-ولم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_175/17504.mp3","categories":["التفسير","شروح الحديث"]},{"id":9143,"question":"هذه رسالة من المستمع هيثم سالم حيدرة عدن اليمن الديمقراطي، يقول في بداية رسالته: بسم الله الرحمن الرحيم، الحمد لله رب العالمين، والصلاة والسلام على سيدنا رسول الله، الإخوة العلماء في برنامج نور على الدرب، أرجو إفادتي في هذا  قال الحبيب ﷺ: بدأ الإسلام غريباً وسيعود إلى آخر الحديث، نرجو تفسير هذا الحديث وعن صحته. أفيدونا أفادكم الله؟","title":"شرح حديث: (بدأ الإسلام غريباً وسيعود غريباً)","answer":"الجواب: هذا الحديث صحيح رواه مسلم في صحيحه، جاء عن أبي هريرة  عن النبي ﷺ أنه قال: بدأ الإسلام غريباً وسيعود غريباً كما بدأ فطوبى للغرباء فهو حديث صحيح ثابت عن رسول الله عليه الصلاة والسلام، زاد جماعة من أئمة الحديث في رواية أخرى: قيل: يا رسول الله! من الغرباء؟ قال: الذين يصلحون إذا فسد الناس، وفي اللفظ الآخر: يصلحون ما أفسد الناس من سنتي، وفي لفظ آخر: هم النزاع من القبائل، وفي لفظ آخر: هم أناس صالحون قليل في أناس سوء كثير.\nفالمقصود أن الغرباء: هم أهل الاستقامة، فطوبى للغرباء يعني: الجنة والسعادة للغرباء الذين يصلحون عند فساد الناس، إذا تغيرت الأحوال والتبست الأمور، وقل أهل الخير ثبتوا هم على الحق واستقاموا على دين الله، ووحدوا الله وأخلصوا له العبادة، واستقاموا على الصلاة والزكاة والصيام والحج وسائر أمور الدين، هؤلاء هم الغرباء، وهم الذين قال الله فيهم وفي أشباههم: إِنَّ الَّذِينَ قَالُوا رَبُّنَا اللَّهُ ثُمَّ اسْتَقَامُوا تَتَنَزَّلُ عَلَيْهِمُ الْمَلائِكَةُ أَلَّا تَخَافُوا وَلا تَحْزَنُوا وَأَبْشِرُوا بِالْجَنَّةِ الَّتِي كُنْتُمْ تُوعَدُونَ ۝ نَحْنُ أَوْلِيَاؤُكُمْ فِي الْحَيَاةِ الدُّنْيَا وَفِي الآخِرَةِ وَلَكُمْ فِيهَا مَا تَشْتَهِي أَنفُسُكُمْ وَلَكُمْ فِيهَا مَا تَدَّعُونَ [فصلت:30-31] أي: ما تطلبون: نُزُلًا مِنْ غَفُورٍ رَحِيمٍ [فصلت:32].\nفالإسلام بدأ قليل في مكة، لم يؤمن به إلا القليل وأكثر الخلق عادوه وعاندوا النبي ﷺ وآذوه عليه الصلاة والسلام وآذوا أصحابه الذين أسلموا، ثم انتقل إلى المدينة مهاجراً وانتقل معه من قدم من أصحابه، وكان غريباً أيضاً حتى كثر أهله في المدينة وفي بقية الأمصار، ثم دخل الناس في دين الله أفواجاً بعد أن فتح الله على نبيه مكة عليه الصلاة والسلام، فأوله كان غريباً بين الناس وأكثر الخلق على الكفر بالله والشرك بالله وعبادة الأصنام والأنبياء والصالحين والأشجار والأحجار ونحو ذلك، ثم هدى الله من هدى على يد رسوله محمد ﷺ وعلى يد أصحابه، فدخلوا في دين الله وأخلصوا العبادة لله وتركوا عبادة الأصنام والأوثان والأنبياء والصالحين، وأخلصوا لله العبادة فصاروا لا يعبدون إلا الله وحده، لا يصلون إلا له ولا يسجدون إلا له ولا يتوجهون بالدعاء والاستغاثة وطلب الشفاء إلا له سبحانه وتعالى، لا يسألون أصحاب القبور ولا يطلبونهم المدد ولا يستغيثون بهم ولا يستغيثون بالأصنام والأشجار والأحجار، ولا بالكواكب والجن والملائكة، بل لا يعبدون إلا الله وحده سبحانه وتعالى، فهؤلاء هم الغرباء، وهكذا في آخر الزمان هم الذين يستقيمون على دين الله، عندما يتأخر الناس عن دين الله، عندما يكفر الناس، عندما تكثر معاصيهم وشرورهم يستقيم هؤلاء الغرباء على طاعة الله ودينه، فلهم الجنة والسعادة ولهم العاقبة الحميدة في الدنيا وفي الآخرة. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7301/شرح-حديث-بدا-الاسلام-غريبا-وسيعود-غريبا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_230/23004.mp3","categories":["شروح الحديث"]},{"id":9310,"question":"جزاكم الله خيرا، يسأل أيضًا عن معنى حديث رسول الله ﷺ: إذا مات ابن آدم انقطع عمله إلا من ثلاث: صدقة جارية، أو علم ينتفع به، أو ولد صالح يدعو له وسمعت من البرنامج أن ثواب قراءة القرآن لا يصل إلى الميت، وأن ما يفعله الناس من قراءة القرآن وغيره كل هذا بدع، فكيف يدعو الولد الصالح لأبيه؟ وما هو المقصود بهذا الدعاء؟","title":"ما معنى: «إذا مات ابن آدم انقطع عمله»؟","answer":"الجواب: الحديث على ظاهره، وهو حديث صحيح رواه مسلم في صحيحه: إذا مات ابن آدم انقطع عمله إلا من ثلاث: صدقة جارية، أو علم ينتفع به، أو ولد صالح يدعو له والدعاء يقول: اللهم اغفر لأبي، اللهم ارحمه، اللهم أسكنه الجنة، اللهم ضاعف حسناته، اللهم كفر سيئاته، اللهم ارفع درجته في المهديين، وما أشبه هذا من الدعوات الطيبة، هذا الدعاء.\nأما قراءة القرآن كونه يقرأ ويثوب هذا فيه خلاف بين أهل العلم:\nمن العلماء من قال: إنه يلحق الميت وأنه ينتفع بذلك، وبهذا قال جم غفير من العلماء، وقاسوه على الصدقة.\nوقال آخرون: لا. لأن العبادات توقيفية، لا يسمح فيها إلا بما جاء به الشرع نصًا، ولم يرد في السنة عن النبي ﷺ ولا في الكتاب العزيز ما يدل على شرعية تثويب القرآن، أو الصلاة، أو الصوم لمن ليس عليه صوم واجب، فلما لم يأت هذا وجب تركه؛ لأن المؤمن إنما يفعل ما أمر به وشرع له، والنبي ﷺ يقول: من عمل عملًا ليس عليه أمرنا فهو رد يعني: هو مردود، ويقول عليه الصلاة والسلام: من أحدث في أمرنا هذا ما ليس منه فهو رد هذا وجه هذا القول الذي قاله جمع من أهل العلم وهو أظهر في الدليل وأقرب إلى الدليل، وفيما شرع الله الكفاية من الصدقة والدعاء والحج عن الميت، وأداء الصيام الواجب عنه إذا مات وعليه صيام من رمضان أو كفارة أو نذر، يؤدى عنه، يؤدي عنه أقاربه، أما صوم يتطوعون به عنه أو صلاة أو قراءة قرآن، فهذا لم يرد فيه دليل يدل عليه، فوجب ترك ذلك وقوفًا مع النصوص. نعم.\nالمقدم: جزاكم الله خيرا.","link":"https://binbaz.org.sa/fatwas/7474/ما-معنى-اذا-مات-ابن-ادم-انقطع-عمله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_184/18409.mp3","categories":["إهداء القرب للميت","شروح الحديث"]},{"id":9370,"question":"وننتقل إلى رسالة وصلت من رابغ وباعثها أحد الإخوة يقول عبدالله الهواري: أخونا له ثلاثة أسئلة:سؤاله الأول: يسأل عن معنى حديث رسول الله ﷺ الذي يقول: شفاء أمتي في ثلاث: كية من نار -كما يورد سماحة الشيخ- أو آية من كتاب الله، أو جرعة من عسل هل هذا حديث صحيح؟","title":"معنى حديث: (الشفاء في ثلاث ...)","answer":"الجواب: الحديث في الصحيح يقول الرسول ﷺ: الشفاء في ثلاث: كية نار، أو شرطة محجم، أو شربة عسل ليس فيه الآية، أما الآية تؤخذ من قوله تعالى: وَنُنَزِّلُ مِنَ الْقُرْآنِ مَا هُوَ شِفَاءٌ وَرَحْمَةٌ لِلْمُؤْمِنِينَ [الإسراء:82] ومن قوله تعالى: قُلْ هُوَ لِلَّذِينَ آمَنُوا هُدًى وَشِفَاءٌ [فصلت:44] ومن عمله ﷺ فإنه كان يقرأ الآيات على المريض، كان يقرأ على نفسه: قُلْ هُوَ اللَّهُ أَحَدٌ  والمعوذتين عند النوم إذا اشتكى عليه الصلاة والسلام.\nوالصحابة كانوا يقرءون على المريض من الآيات، وقد قرأ بعض الصحابة على لديغ سورة الفاتحة فشفاه الله، وعرضوا هذا على النبي ﷺ فأقرهم، وقال: وما يدريك أنها رقية؟ وكانوا قد جعل لهم قطيع من الغنم، فأخذوه وأقرهم النبي ﷺ على ذلك وقال: اضربوا لي معكم بسهم.\nفالحاصل أنه ﷺ أقرهم على قراءة القرآن على المريض للاستشفاء.\nوأما الحديث فالذي فيه: الشفاء في ثلاث: كية نار، أو شرطة محجم - يعني: حجامة- أو شربة عسل، قال: وما أحب أن أكتوي وفي اللفظ الآخر: وأنا أنهى أمتي عن الكي رواه البخاري في الصحيح، فهذا يدل على أن هذه الثلاث من أسباب الشفاء، الكي عند الحاجة إليه، والحجامة عند الحاجة إليها، والعسل، والله بين في كتابه العظيم أن العسل فيه شفاء للناس، لكن إذا تيسر علاج بغير الكي فهو أولى؛ ولهذا قال الرسول ﷺ: وما أحب أن أكتوي، وقال: وأنا أنهى أمتي عن الكي لكنه كوى بعض أصحابه للحاجة.\nفالحاصل: أنه لا يشرع الكي إلا عند الحاجة، عند عدم وجود ما يكفي عنه، فإذا تيسر دواء آخر يكفي عنه فالأولى ترك الكي؛ لأنه نوع تعذيب بالنار، فلا يصار إليه إلا عند الحاجة. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7534/معنى-حديث-الشفاء-في-ثلاث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_186/186009.mp3","categories":["الطب والتداوي","شروح الحديث"]},{"id":9371,"question":"شيخ عبدالعزيز نعود في بداية لقائنا إلى رسالة الأخ: عبدالله بن محمد بن عبد الله أخونا في حلقة مضت عرضنا بعض أسئلته وفي هذه الحلقة يسأل ويقول: ورد حديث عن النبي ﷺ ينهى فيه عن تقبيح الوجه، وأن الله خلق آدم على صورته، فما الاعتقاد السليم نحو هذا الحديث؟","title":"معنى قوله: (إن الله خلق آدم على صورته)","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فالحديث ثابت عن رسول الله عليه الصلاة والسلام أنه قال: إذا ضرب أحدكم فليتق الوجه فإن الله خلق آدم على صورته وفي لفظ آخر: على صورة الرحمن وهذا لا يلزم منه التشبيه والتمثيل، فالمعنى عند أهل العلم أن الله خلق آدم سميعًا بصيرًا متكلمًا إذا شاء، وهذا هو وصف الله ، فإنه سميع بصير متكلم ذو وجه جل وعلا، وليس المعنى التشبيه والتمثيل بل الصورة التي لله غير الصورة التي للمخلوق، وإنما المعنى أنه سميع بصير ذو وجه ومتكلم إذا شاء.\nوهكذا خلق الله آدم سميعًا بصيرًا ذا وجه وذا يد وذا قدم ويتكلم إذا شاء، لكن ليس السميع كالسميع وليس البصير كالبصير وليس المتكلم كالمتكلم وليس الوجه كالوجه بل لله صفاته سبحانه وتعالى لا يشابهه فيها شيء بل تليق به سبحانه، وللعبد صفاته التي تليق به صفات يعتريها الفناء والنقص والضعف، أما صفات الله سبحانه فهي كاملة لا يعتريها نقص ولا ضعف ولا فناء ولا زوال، ولهذا قال : لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ [الشورى:11] .. وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ [الإخلاص:4] فلا يجوز ضرب الوجه ولا تقبيح الوجه. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7535/معنى-قوله-ان-الله-خلق-ادم-على-صورته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_157/15701.mp3","categories":["شروح الحديث","الأسماء والصفات"]},{"id":9378,"question":"نعود في بداية هذه الحلقة إلى رسالة الأخت أم مجاهد سودانية مقيمة في الإمارات العربية المتحدة، أختنا عرضنا جزءًا من أسئلتها في حلقة مضت، وفي هذه الحلقة تسأل وتقول: يقول الرسول ﷺ: لا يدخل بيتك إلا مؤمن ولا يأكل طعامك إلا تقي هل هذا حديث صحيح، وإن كان صحيح فكيف أعرف المؤمن والتقي، والرسول ﷺ يقول: التقوى ها هنا يشير إلى قلبه، والتقوى والإيمان مكانهما القلب، والله المطلع على القلوب، وإذا دخل بيتي جاحد كافر جائع ماذا أفعل معه، أفيدوني جزاكم الله خيرًا؟","title":"ما معنى: «لا تصاحب إلا مؤمنًا ولا يأكل طعامك إلا تقي»؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فلفظ الحديث الثابت عن رسول الله عليه الصلاة والسلام: لا تصاحب إلا مؤمنًا ولا يأكل طعامك إلا تقي ومعناه: لا تتخذ الفساق أصحابًا، وإنما تتخذ الأخيار أهل الصفات الحميدة.. أهل المحافظة على الصلوات، الذين يحفظون ألسنتهم وجوارحهم عن محارم الله، هذا معنى ذلك: لا تصاحب إلا مؤمنًا والمؤمن من أظهر عمل الخير، القلوب لا يعلم ما فيها إلا الله ، وليس للناس إلا الظاهر، فمن أظهر الاستقامة على دين الله بالمحافظة على الصلوات وأداء حق الله وترك محارم الله، فهذا يقال له: مؤمن، ويقال له: مسلم ويقال له: متقٍ أيضًا حسب ما ظهر من أعمال، أما القلوب فإلى الله ، لا يعلم ما فيها إلا الله، وإنما يؤخذ الناس بما أظهروا من الأعمال، وقول النبي ﷺ: التقوى ها هنا يعني: أن أصل التقوى في القلب، متى صلح القلب صلحت الجوارح، ومتى فسد القلب فسدت الجوارح، فالنبي ﷺ يشير إلى أنه ينبغي للمؤمن أن يعتني بقلبه، وأن يجتهد في صلاح قلبه وطهارته حتى تصلح أعماله وأقواله.\nكما في الحديث الآخر يقول ﷺ: إن الله لا ينظر إلى صوركم ولا إلى أموالكم ولكن ينظر إلى قلوبكم وأعمالكم وفي اللفظ الآخر يقول ﷺ: ألا وإن في الجسد مضغة إذا صلحت صلح الجسد كله، وإذا فسدت فسد الجسد كله، ألا وهي القلب متفق على صحته، فالقلب هو الأساس، فمتى عمر بتقوى الله ومحبته وخشيته سبحانه وخوفه منه، والنصح له ولعباده استقامت الجوارح على دين الله وعلى فعل ما أوجب الله وعلى ترك ما حرم الله.\nوقوله: ولا يأكل طعامك إلا تقي أي: لا تدع إلى طعامك إلا الأخيار، لا تدع الفساق والكفار، قال العلماء: هذا فيما يختار، يختاره الإنسان ويتخذه عادة له، أما الضيوف فلهم شأن آخر، الضيوف لا مانع من أن يقدم لهم الطعام وإن كانوا ليسوا أتقياء، وإن كانوا فجارًا وإن كانوا كفارًا، فالنبيﷺ كان يقدم عليه الضيوف من الكفرة وغير الكفرة فيطعمهم ويكرمهم عليه الصلاة والسلام، تأليفًا لهم على الإسلام، وقد قال عليه الصلاة والسلام: من كان يؤمن بالله واليوم الآخر فليكرم ضيفه فإكرام الضيف مأمور به شرعًا ولو كان غير المسلم، وفي إكرامه دعوة إلى الإسلام، وتوجيه له إلى الخير؛ ليعرف محاسن الإسلام ومكارم الأخلاق.\nأما أن تتخذ أصحابًا ليسوا مسلمين يأكلون طعامك ويصحبونك فلا، وقد قال عليه الصلاة والسلام في الحديث الآخر الصحيح: مثل الجليس الصالح والجليس السوء كمثل حامل المسك ونافخ الكير، فحامل المسك إما أن يحذيك -يعني: يعطيك - وإما أن تبتاع منه - تشتري منه- وإما أن تجد منه ريحًا طيبة، أما نافخ الكير فإما أن يحرق ثيابك وإما أن تجد منه ريحًا خبيثة ويقول ﷺ: المرء على دين خليله -يعني: صاحبه- فينظر أحدكم من يخالل فالمؤمن ينظر في أصحابه وأخلائه ويختار الأخيار الطيبين أهل الصلاة .. أهل الاستقامة .. أهل السمعة الحسنة؛ حتى يعينوه على طاعة الله وحتى يستشيرهم فيما يشكل عليه، وحتى يتعاون معهم في الخير، ولا يتخذ أهل الفسق والكفر أصحابًا وأولياء؛ لأنهم يضرونه ويجرونه إلى أباطيلهم؛ ولهذا قال ﷺ: لا تصاحب إلا مؤمنًا، ولا يأكل طعامك إلا تقي يعني: حسب الاستطاعة وفي الاختيار.\nأما إذا هجم الضيف فإن الإنسان يكرم الضيف بما يليق بمقامه، ويدعوه إذا كان فاجرًا أو كافرًا يدعوه إلى الخير ينصح له، يدعوه إلى طاعة الله والاستقامة على دينه إن كان فاسقًا، يدعوه إلى الإسلام إن كان كافرًا، وقد جاء وفد ثقيف إلى النبي ﷺ في المدينة وهم كفار فأكرمهم ودعاهم إلى الله  حتى أسلموا، فالضيف له شأن آخر.\nوكذلك قد يدعى الإنسان إلى وليمة فيجتمع بأناس لا خير فيهم فلا يضره ذلك؛ لكونه لم يقصد صحبتهم، وإنما جمعه معهم الطعام كما يجمعه معهم السوق والمساجد ونحو ذلك، وهم فساق.\nفالحاصل أن الشيء الذي ينهى عنه هو أن يتخذ الفاجر أو الكافر صاحبًا وصديقًا يأكل طعامه ويزوره ويتزاور معه ونحو ذلك، أما ما قد يعرض للإنسان من مجيء الضيف إليه، أو اتصاله بغير مسلم لدعوته إلى الله، أو لشراء حاجة منه، فقد اشترى النبي ﷺ من الكفرة واشترى من اليهود حاجات عليه الصلاة والسلام، وقد دعاه اليهود فأكل طعامهم، وأحل الله لنا طعامهم، فهذه أمور ينبغي أن يعلمها المؤمن، وأن تكون منه على بينة حتى لا ينهى عما أذن الله فيه، وحتى لا يحرم ما أحل الله ، والله المستعان. نعم.","link":"https://binbaz.org.sa/fatwas/7542/ما-معنى-لا-تصاحب-الا-مومنا-ولا-ياكل-طعامك-الا-تقي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_187/18701.mp3","categories":["شروح الحديث"]},{"id":9446,"question":"هذه رسالة وردت إلينا من أحمد عبدالله السيد لم يذكر عنواناً، الأخ أحمد الحقيقة ملأ هذه الرسالة بعدة أمور ونود دائماً أن يعني يلاحظ الإخوة السائلون في رسائلهم الرفق بنا في الحقيقة والحرص على عدم تكرار الأسئلة، وما يتعلق بالرؤى والأحلام حبذا لو أعفي البرنامج من هذا؛ لأن هذا أمر ليس فيه كثير فائدة في الحقيقة، وأصحاب الفضيلة العلماء حريصون على الإجابة على ما يشكل شرعاً وما يجوز وما لا يجوز، وما ينفع الناس أما ما يتعلق بالرؤى والأحلام فإن هذا أمر ليس من الخطورة بمكان، والأخ السائل ضمن رسالته قصة طويلة حول بركة تدعيها له أمه فنرى أن يعفينا من مثل هذه، ولكن في رسالته سؤال لا بأس من عرضه، يسأل سماحة الشيخ عن الصدقة قبل الرد التي وردت في حديث شرحه القسطلاني على البخاري يقول: الحث على الإسراع في إخراج الصدقة خشية أن تظهر كنوز الأرض ويكثر المال، يسأل عن هذا الحديث وعن المقصود به؟","title":"ما معنى: «يأتي في آخر الزمان زمان يفيض فيه المال»؟","answer":"الجواب: المعنى أنه ينبغي للمؤمن أن يبادر بالصدقات قبل أن يأتي عليه زمان لا تقبل فيه الصدقة من أجل كثرة المال، وظهوره بين الناس، وفيضانه بين الناس، فإنه أخبر النبي ﷺ: يأتي في آخر الزمان زمان يفيض فيه المال حتى لا يقبله أحد، حتى إن الرجل ليذهب بصدقته من الذهب أو الفضة لا يجد من يقبلها.\nفالمقصود من هذا التحريض على البدار في الصدقات ما دام يوجد فقراء، ما دام هناك فقراء يقبلونها، قبل أن يأتي عليك زمان لا تجد فقيراً يقبلها، فينبغي للمؤمن أن يبادر بالصدقات إذا أوسع الله عليه ما دام الفقراء موجودين.\nالمقدم: بارك الله فيكم، وجزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/7610/ما-معنى-ياتي-في-اخر-الزمان-زمان-يفيض-فيه-المال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_239/23908.mp3","categories":["شروح الحديث"]},{"id":9776,"question":"يقول نفس السائل أيضاً: في نفس الكتاب رواية عن أم المؤمنين عائشة رضي الله تعالى عنها حينما توفي طفل قالت: طوبى لك طير من طيور الجنة، فقال عليه الصلاة والسلام: وما يدريك يا عائشة أنه في الجنة؟ لعل الله اطلع على ما كان يفعل والنبي ﷺ قال: رفع القلم عن ثلاثة، ذكر منهم: الطفل حتى يحتلم والروايتان صحيحتان، فلا أدري كيف الجمع بينهما؟","title":"توجيه حديث عائشة: (عصفور من عصافير الجنة ...)","answer":"الجواب: هذا الحديث حديث صحيح عند الشيخين، قالت فيه عائشة: عصفور من عصافير الجنة، قال النبي ﷺ: لا يا عائشة ! إن الله خلق للجنة أهلاً خلقهم لها وهم في أصلاب آبائهم، وخلق للنار أهلاً خلقهم لها وهم في أصلاب آبائهم.\nوالمقصود من هذا: منعها من أن تشهد لأحد معين بالجنة أو بالنار، ولو أنه طفل لا يشهد له؛ لأنه قد يكون تابعاً لأبويه، وأبواه ليسوا على الإسلام وإن أظهراه، فالإنسان قد يظهر الإسلام نفاقاً، وقد تظهره أمه نفاقاً.\nفلا يشهد لأحد بالجنة ولا بالنار ولو طفلاً، لا يقال: هذا من أهل الجنة قطعاً؛ لأنه ما يدري عن حال والديه، والأطفال تبع لآبائهم، ومن كان مات على الصغر وليس تبعاً للمسلمين فإنه يمتحن يوم القيامة على الصحيح، إذا كان ليس ولداً بين المسلمين بل لغيرهم من الكفار فإنه يمتحن يوم القيامة، فإن أطاع دخل الجنة وإن عصى دخل النار كأهل الفترة، الصحيح: أنهم يمتحنون، أنهم يمتحنون أهل الفترة، فهكذا الأطفال، ولهذا لما سئل النبي ﷺ عن أولاد المشركين قال: الله أعلم بما كانوا عاملين.\nوقد جاء في السنة ما يدل على أنهم يمتحنون يعني: يختبرون يوم القيامة، ويؤمرون بأمر، فإن أطاعوا دخلوا الجنة وإن عصوا دخلوا النار.\nفالمقصود: من هذا أنه لا يشهد لأحد معين بجنة ولا نار إلا من شهد له النبي ﷺ، هذه قاعدة أهل السنة والجماعة ، فإنكاره ﷺ على عائشة ؛ لأنها شهدت بالتعيين لأنها قالت: عصفور من عصافير الجنة، فلهذا أنكر عليها أن تقول هذا؛ لأن هناك شيئاً وراء هذا الأمر قد يكون سبباً لعدم دخوله الجنة، وأنه يمتحن يوم القيامة؛ لأن والديه ليسا على الإسلام.\nأما أولاد المسلمين فهم تبع آبائهم، عند أهل السنة والجماعة في الجنة، أولاد المسلمين تبع آباؤهم في الجنة، وأما أولاد الكفار فإنهم يمتحنون يوم القيامة هذا هو الحق، فمن أطاع يوم القيامة دخل الجنة ومن عصى دخل النار كأهل الفترة، هذا هو الصواب وهذا وجه الحديث. نعم.\nالمقدم: أثابكم الله وبارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7945/توجيه-حديث-عاىشة-عصفور-من-عصافير-الجنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_258/25806.mp3","categories":["شروح الحديث"]},{"id":9871,"question":"هذه الرسالة وردت إلينا من جمهورية اليمن العربية من السائل: حيدر علي أحمد القحوي يقول فيها: لقد سمعت حديثاً في خطبة الجمعة عن رسول الله ﷺ يقول: الدنيا ملعونة ملعون من فيها إلا عالماً أو متعلم أو ذكر الله وما والاه المطلوب من فضيلتكم شرح هذا الحديث شرحاً موجزاً، وهل جميع ما خلقه الله تعالى في هذه الدنيا ملعون أم كيف ذلك؟","title":"ما صحة حديث: «الدنيا ملعونة ملعون ما فيها» ومعناه؟","answer":"الجواب: الحديث لا بأس بإسناده ولفظه: الدنيا ملعونة ملعون ما فيها -ما هو: بـ (من) ملعون ما فيها- إلا ذكر الله وما والاه أو عالماً أو متعلماً والمعنى: باللعن: الذم، يعني: مذمومة (الدنيا)، اللعن: الذم، ومنه قوله : وَالشَّجَرَةَ الْمَلْعُونَةَ فِي الْقُرْآنِ [الإسراء:60]، يعني: المذمومة؛ لأن الله قال فيها: إِنَّ شَجَرَةَ الزَّقُّومِ ۝ طَعَامُ الأَثِيمِ ۝ كَالْمُهْلِ يَغْلِي فِي الْبُطُونِ ۝ كَغَلْيِ الْحَمِيمِ [الدخان:43-46]، فذمها، فاللعن هنا بمعنى: الذم، يعني: مذمومة الدنيا؛ لأن أكثر من فيها اشتغلوا بها عن الآخرة، وصدتهم عن الآخرة بزخرفها وشهواتها، فهي مذمومة مذموم ما فيها، إلا ذكر الله سبحانه وتعالى بقراءة القرآن، بالتسبيح والتهليل، بما في القلوب من ذكر الله وتعظيمه، وما والى ذلك من طاعة الله وترك معاصيه، هذا ممدوح ليس بمذموم.\nوهكذا المؤمنون والمؤمنات فإنهم مما يلي ذكر الله؛ لأنهم أهل ذكر الله، والقائمون بذكر الله، وهكذا العلماء والمتعلمون هم خواص المؤمنين، فالمؤمنون والمسلمون والعلماء الشرعيون والمتعلمون للشرع، كلهم خارجون من هذا الذم.\nفالدنيا مذمومة، مذموم ما فيها مما يصد عن الله والدار الآخرة، أما ما كان يتعلق بذكر الله، والدار الآخرة من طاعة الله ورسوله وترك معاصي الله، وهكذا من فيها من المؤمنين والمؤمنات فإن هؤلاء هم عباد الله وهم الصلحاء من عباده، وهم الأخيار من عباده، وهم الذين يلون ذكر الله، يقومون به يعملون به، فهم غير داخلين في الذم.\nوكذلك العلماء الذين يعلمون الشرع ويدعون إلى الله، ويبصرون الناس بالحق.\nوهكذا المتعلمون طلاب العلم الشرعي، هؤلاء كلهم غير داخلين في الذم وهم من خواص أهل الإيمان أهل ذكر الله سبحانه وتعالى.\nفاتضح بهذا أن ذكر الله  من صلاة وصيام وكلام طيب كالتسبيح والتهليل وقراءة القرآن ونحو ذلك، كل هذا غير داخل في الذم، وهكذا ما والى ذلك من أداء العباد طاعة ربهم، وتركهم معاصيه سبحانه وتعالى فهم غير داخلين في هذا الذم؛ لأنهم أهل طاعة الله وأهل الإيمان به، هم الموالون لذكر الله ، وهكذا ما يتعلق بالعلم والعمل، فالعلماء والمتعلمون لشرع الله عز وجل والدعاة إليه، كلهم من خواص المؤمنين غير داخلين في الذم والله ولي التوفيق.\nالمقدم: أثابكم الله.","link":"https://binbaz.org.sa/fatwas/8038/ما-صحة-حديث-الدنيا-ملعونة-ملعون-ما-فيها-ومعناه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_263/26306.mp3","categories":["شروح الحديث","الحكم على الأحاديث"]},{"id":9988,"question":"صاحبنا محمد عبد الحكم يسأل أيضا ويقول: قال الله تعالى في كتابه الكريم: وَمَا كُنَّا مُعَذِّبِينَ حَتَّى نَبْعَثَ رَسُولًا [الإسراء:15]، وقد ورد في بعض الأحاديث أن الرسول ﷺ أخبر بأن والديه في النار،  ألم يكونا من أهل الفترة، وأن القرآن صريح بأنهم ناجون أفيدونا أفادكم الله؟","title":"الجمع بين: «أبي وأبوك في النار» وبين حكم أهل الفترة","answer":"الجواب: أهل الفترة ليس في القرآن ما يدل على أنهم ناجون أو هالكون، إنما قال الله جل وعلا: وَمَا كُنَّا مُعَذِّبِينَ حَتَّى نَبْعَثَ رَسُولًا [الإسراء:15]، فالله جل وعلا من كمال عدله لا يعذب أحداً إلا بعد بعث الرسول، فمن لم تبلغه الدعوة فليس بمعذب حتى تقام عليه الحجة، أخبر سبحانه أنه لا يعذبهم إلا بعد إقامة الحجة، والحجة قد تقوم عليهم حتى يوم القيامة كما جاء في السنة أنها تقام الحجة على أهل الفترات ويمتحنون يوم القيامة فمن أجاب وامتثل نجا ومن عصى دخل النار، والنبي ﷺ قال: إن أبي وأباك في النار لرجل سأله عن أبيه قال: إن أباك في النار، فلما رأى ما في وجهه من التغير قال: إن أبي وأباك في النار حتى يتسلى بذلك وأنه ليس خاصاً بأبيه، ولعل هذين بلغتهما الحجة، لعل أبا الرجل وأبا النبي ﷺ بلغتهما الحجة، النبي ﷺ حين قال: إن أبي وأباك في النار إنما قاله عن علم عليه الصلاة والسلام، هو لا ينطق عن الهوى، قال الله سبحانه: وَالنَّجْمِ إِذَا هَوَى ۝ مَا ضَلَّ صَاحِبُكُمْ وَمَا غَوَى ۝ وَمَا يَنْطِقُ عَنِ الْهَوَى [النجم:1-3]، وإنما قال ذلك عن علم عن الله ، فلولا أن عبدالله بن عبد المطلب والد النبي ﷺ قد قامت عليه الحجة لما قال في حقه النبي ما قال عليه الصلاة والسلام، فلعله بلغه ما يوجب عليه الحجة من جهة دين إبراهيم عليه الصلاة والسلام؛ فإنهم كانوا على ملة إبراهيم حتى أحدث ما أحدث عمرو بن لحي الخزاعي، وسرى في الناس ما أحدثه عمرو من بث الأصنام ودعوتها من دون الله، فلعل عبدالله كان قد بلغه ما يدل على أن هذا باطل وأن ما عليه قريش من عبادة الأصنام باطل فتابعهم؛ فلهذا قامت عليه الحجة. وهكذا ما جاء في الحديث أنه صلى الله عليه وسلم استأذن أن يستغفر لأمه فلم يؤذن له، فاستأذن أن يزورها فأذن له، فكونه لم يؤذن له أن يستغفر لأمه هو من هذا الباب؛ لعله لأنه بلغها ما يقيم عليها الحجة، أو لأن أهل الجاهلية يعاملون معاملة الكفرة في أحكام الدنيا فلا يُدعى لهم ولا يُستغفر لهم؛ لأنهم في ظاهر الكفر ظاهرهم مع الكفرة فيعاملون معاملة الكفرة وأمرهم إلى الله في الآخرة، فالذي لم تقم عليه الحجة في الدنيا لا يعذب حتى يمتحن يوم القيامة؛ لأن الله سبحانه قال: وَمَا كُنَّا مُعَذِّبِينَ حَتَّى نَبْعَثَ رَسُولًا [الإسراء:15]، فإذا علم أن أناساً كانوا في فترة لم تبلغهم دعوة نبي فإنهم يمتحنون يوم القيامة، فإن أجابوا صاروا إلى الجنة، وإن عصوا صاروا إلى النار، وهكذا الشيخ الهرم الذي ما بلغته الدعوة، والمجانين اللي ما بلغتهم الدعوة، وأشباههم والأطفال يمتحنون -أطفال الكفار على الصحيح-؛ لأن الرسول ﷺ لما سئل عنهم قال: الله أعلم بما كانوا عاملين، فأولاد الكفار يمتحنون يوم القيامة كأهل الفترة، فإن أجابوا جواباً صحيحاً نجوا، وإلا صاروا مع الهالكين، فليس بحمد الله في حق..... أبوي النبي ﷺ ليس في ذلك إشكال على مَن عَرَف السنة وقاعدة الشرع.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8156/الجمع-بين-ابي-وابوك-في-النار-وبين-حكم-اهل-الفترة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_275/27502.mp3","categories":["شروح الحديث"]},{"id":10064,"question":"المستمعة (س) من الرياض بعثت تسأل وتقول: هل تغتسل المرأة من الاستحاضة التي بعد الحيض وإذا كان يجب الغسل فما الحكم فيمن كانت جاهلة بهذا؟","title":"حكم الغسل على المستحاضة","answer":"الجواب: الاغتسال من الاستحاضة مستحب وليس بواجب، الغسل الواجب من الحيض إذا انتهت مدته ورأت الطهارة تغتسل وجوباً كالجنب، أما الاستحاضة الدماء التي تأتيها بعد الحيض المستمر النزيف المستمر فهذا يستحب منه الغسل، لصلاتي الظهر والعصر والمغرب والعشاء غسلاً واحداً والفجر غسلاً واحداً، وإن تركت فلا حرج عليها لأن النبي ﷺ أوصى بهذا حمنة بنت جحش .\nأما الواجب فلا يجب عليها إلا غسل الحيض وغسل الجنابة أما الاستحاضة فيها الوضوء، على المرأة أن تتوضأ لكل صلاة، كما قال النبي ﷺ لـفاطمة بنت أبي حبيش وكانت مستحاضة: توضئي لوقت كل صلاة، لكن من اغتسل إذا اغتسلت فهو أفضل فالأفضل أن يكون للظهر والعصر غسلاً واحداً، أن تغتسل لوقت الظهر و العصر غسلاً واحداً، وأن تغتسل للمغرب والعشاء غسلاً واحداً وللفجر غسلاً واحداً هذا أفضل لأن الرسول ﷺ أوصى به حمنة رضي الله عنها. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8233/حكم-الغسل-على-المستحاضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_303/30315.mp3","categories":["الغسل","الحيض والنفاس","شروح الحديث"]},{"id":10068,"question":"من العراق بغداد الزعفرانية، هذه رسالة بعث بها المستمع محمود، الأخ محمود له ثمانية أسئلة في أحد أسئلته يقول: جاء في صحيح البخاري حديث أن ابن عمر رضي الله عنهما أنه كان يقتل الحيات كلها، فقال له أحد أصحابه: إن رسول الله ﷺ نهى عن قتل جنان البيوت، سؤالي ما هي جنان البيوت؟","title":"معنى الأمر بقتل الحيات إلا جنان البيوت","answer":"الجواب: هذا صحيح والذي نهاه أنه أبو لبابة الأنصاري، وجنان البيوت هم المقيمون بها الساكنون في البيوت من الحيات.\nالمقدم: إذًا الصحيح أن نقول جنان البيوت؟\nالشيخ: نعم، يستأذن، ويقال له: إن عدت قتلناك ثلاث مرات فإن عاد قتل، أمر النبي ﷺ أن يحذر ثلاث مرات وينذر ثلاث مرات فإن عاد قتل وأما إذا وجده في الصحراء أو في الطريق أو في المسجد يقتل؛ لأنه يؤذي الناس. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8234/معنى-الامر-بقتل-الحيات-الا-جنان-البيوت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_333/333005.mp3","categories":["شروح الحديث"]},{"id":10196,"question":"ترجو من سماحتكم شرح هذا القول: نعمتان مغبون فيهما كثير من الناس: الصحة، والفراغ؟ وتقول: أعتقد أن هذا حديث.","title":"معنى قوله: (نعمتان مغبون فيهما كثير من الناس ..)","answer":"الجواب: نعم هذا حديث صحيح، يقول النبي ﷺ: نعمتان مغبون فيهما كثير من الناس: الصحة، والفراغ يعني: كثير من الناس تضيع صحته بغير فائدة، وفراغه في غير فائدة، صحيح الجسم معافى في بدنه، وعنده فراغ ولكن لا يستعمل ذلك فيما ينفعه، وفيما يقربه من الله، وفيما ينفعه في الدنيا، فهذا مغبون في هاتين النعمتين، وإنما ينبغي للمؤمن أن يستغل هذه النعمة فيما يرضي الله، وفيما ينفعه، في التجارة وأنواع الكسب الحلال والاستكثار من الصوم والصلاة، والذكر والطاعات، وعيادة المرضى، والأمر بالمعروف والنهي عن المنكر، والدعوة إلى الله عز وجل إلى غير هذا من وجوه الخير، فالمؤمن يشغلهما بما يرضي الله وبما ينفعه في دنياه من الحلال، فإذا ترك هاتين النعمتين لم يستعملهما فيما ينفعه فقد غبن، وهذا الغبن قد يكون محرماً وقد يكون لا يضره، فإذا لم يستعملها في معاصي الله وأدى الواجب لم يضره هذا الغبن، أما إذا كانت الصحة مستعملة في معاصي الله ضره ذلك، أو الفراغ مستعمل في معاصي الله ضره ذلك، أما إذا كان لا لم يستعمل ذلك في معاصي الله، ولكن لم يستكثر من الحسنات المستحبة، ولم يستعمل هذا الفراغ والصحة فيما ينفعه في الدنيا، ولكنه عنده ما يقوم بحاله ويقوم بحال عائلته، ليس مضطراً إلى الكسب ونحو ذلك، فإن هذا لا يضره، لكنه نوع من الغبن، لو استعمل الصحة فيما ينفعه من الذكر وأنواع الطاعات المشروعة، وفي المكاسب الحلال الطيبة يتصدق منها ويحسن لكان خيراً له. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8363/معنى-قوله-نعمتان-مغبون-فيهما-كثير-من-الناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_309/30905.mp3","categories":["شروح الحديث"]},{"id":10207,"question":"ما معنى الحديث الشريف: «من خاف أدلج»؟","title":"معنى حديث: (من خاف أدلج)","answer":"المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8378/معنى-حديث-من-خاف-ادلج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_335/33502.mp3","categories":["شروح الحديث"]},{"id":10374,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من الأخ المستمع: مرزوق بن عتيق الشدادي ، أخونا يقول: سمعنا حديثاً عن النبي ﷺ معناه: من تسمى بغير جده فعليه لعنة الله والملائكة والناس أجمعين إلا أن بعض الناس لا يعرف جده، فكيف يتوجه هذا الحديث بالنسبة له جزاكم الله خيرًا؟كما أنه سمع أن من الناس من يقول: هلك الناس، فمن قال ذلك: فهو أهلكهم، فسروا لنا أيضاً هذه المعاني جزاكم الله خيرًا؟","title":"الانتساب لغير الأب، ومعنى حديث: (من قال: هلك الناس...)","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nفقد جاءت الأحاديث الصحيحة عن رسول الله ﷺ، تدل على تحريم الانتساب إلى غير الأب، وأن المؤمن يجب عليه أن ينتسب إلى أبيه، ولا يجوز له أن ينتسب إلى غير أبيه، واللفظ: إلى أبيه لا إلى جده، الواجب أن ينتسب إلى أبيه، ولا يجوز له أن ينتسب إلى غير أبيه، قد جاء الوعيد في ذلك عن النبي ﷺ من طرق كثيرة، فالواجب على المؤمن أن يحذر ذلك، وأن لا ينتسب إلا إلى أبيه، هذا هو الواجب على كل مسلم وهذا وكل مسلمة، وأما حديث: من قال هلك الناس فهو أهلكهم، فهو أيضاً حديث صحيح يروى (فهو أهلكُهم)، ويروى (فهو أهلكَهم)، والمعنى: أنه هو الذي أهلكهم ولم يهلكوا، وأما رواية { فهو أهلكُهم }، يعني: فهو أشدهم هلاكاً، والمسلمون لا يهلكون، بل لا تزال فيهم طائفة على الحق منصورة حتى يأتي أمر الله، كما قاله النبي ﷺ: لا تزال طائفة من أمتي على الحق منصورة لا يضرهم من خذلهم حتى يأتي أمر الله، وفي اللفظ الآخر: من خذلهم ولا من خالفهم حتى يأتي أمر الله، وفي اللفظ الآخر: لا يزال أمر هذه الأمة قائمًا حتى يأتي أمر الله.\nفالمقصود: أن هذه الأمة لا تجتمع على الضلالة، بل لا يزال فيها طائفة على الحق مستقيمة على الهدى لا يهلكون جميعًا، ولكن مثلما قال الله سبحانه: وَمَا أَكْثَرُ النَّاسِ وَلَوْ حَرَصْتَ بِمُؤْمِنِينَ [يوسف:103]، أكثر الخلق على خلاف الحق، والصواب مع القليل لا مع الأكثر، قال جل وعلا: وَقَلِيلٌ مِنْ عِبَادِيَ الشَّكُورُ [سبأ:13]، قال سبحانه: وَلَقَدْ صَدَّقَ عَلَيْهِمْ إِبْلِيسُ ظَنَّهُ فَاتَّبَعُوهُ إِلَّا فَرِيقًا مِنَ الْمُؤْمِنِينََ [سبأ:20]، فلا يجوز لمسلم أن يقول: هلك الناس، أو كفر الناس لا، ولكن يقول: هلك الأكثر، أو كفر الأكثر، يعني عبارة لا تعم الجميع، ولا يقول أيضاً: كفر الأكثر، لكن يقول: هلك الأكثر، أما العموم لا، لا يجوز العموم، لأنه لا تزال طائفة والحمد لله على الحق مستقيمة وثابتة حتى يأتي أمر الله، والمراد بأمر الله يعني: الريح التي تكون في آخر الزمان، فإن الله سبحانه يبعث ريحًا في آخر الزمان تقبض أرواح المؤمنين والمؤمنات، فلا يبقى إلا الأشرار فعليهم تقوم الساعة، وهذا بعد طلوع الشمس من مغربها، بعد الآيات الآخيرة، آيات الساعة بعد طلوع الشمس من مغربها يبعث الله ريحًا طيبة، تقبض روح كل مؤمن ومؤمنة أينما كان، فلا يبقى إلا الأشرار وعليهم تقوم الساعة، نسأل الله العافية.\nالمقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8546/الانتساب-لغير-الاب-ومعنى-حديث-من-قال-هلك-الناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_280/28001.mp3","categories":["شروح الحديث"]},{"id":10376,"question":"المستمع يحيى غازي العنزي من الرياض، بعث يسأل يقول: ذكر ابن القيم أن رسول الله ﷺ أنكر على معاذ قراءته لسورة البقرة فقال: أفتان أنت يا معاذ!، فتعلق النقارون بهذه الكلمة ولم يلتفتوا إلى ما قبلها ولا إلى ما بعدها، ما المقصود بقوله: ما قبلها وما بعدها ومن هم النقارون جزاكم الله خيراً؟","title":"شرح حديث معاذ: (أفتان أنت يا معاذ)","answer":"الجواب: النبي ﷺ أرشد الأئمة إلى أن يرفقوا بالناس فقال: أيكم أم الناس فليخفف، فإن فيهم الصغير والكبير والضعيف وذا الحاجة، فالواجب على الإمام أن ينظر في الأمر وأن لا يشق على الناس، والقدوة هو النبي عليه الصلاة والسلام، القدوة هو النبي ﷺ في أفعاله كلها، لقول الله : لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ [الأحزاب:21]، فكان عليه الصلاة والسلام يصلي صلاة وسطاً ليس فيها إطالة تشق على الناس.\nفالواجب على الأئمة أن يتأسوا به ﷺ وأن يقتدوا به في الصلوات الخمس كلها، حتى لا يفتنوا الناس، وحتى لا يشجعوهم على ترك الصلاة في الجماعة، فإذا صلى صلاة وسطاً ليس فيها مشقة على الناس، اجتمع الناس وصلوا جماعة ورغبوا في الصلاة، وتواصوا بأدائها في المساجد، ولهذا في اللفظ الآخر: أيها الناس! إن منكم منفرين، يعني: منفرين من الصلاة في الجماعة، فأيكم أم الناس فليخفف، ولهذا قال لـمعاذ: أفتان أنت يا معاذ !، وقال بعدها: هلا قرأت بسبح اسم ربك الأعلى، والليل إذا يغشى، والشمس وضحاها، واقرأ باسم ربك، هذا الذي بعده اللهم صل عليه وسلم، وقبلها: أيكم أم الناس فليخفف، ثم أرشد إلى هلا قرأت بسبح اسم ربك الأعلى، وإذا السماء انشقت، وفي بعضها والشمس وضحاها، والليل إذا يغشى، يعني في أوساط المفصل، يعني هذه السور وما يشابهها، في العشاء والظهر والعصر، أما الفجر فكان يقرأ أطول من ذلك، كان الرسول ﷺ يقرأ في الفجر بالطور، وبـ(ق والقرآن المجيد)، واقتربت الساعة والواقعة وما أشبهها، عليه الصلاة والسلام، فالفجر يطول فيها بعض الطول مثل (ق) ونحوها، وفي الظهر والعصر والمغرب والعشاء بأوساط المفصل، وفي المغرب في بعض الأحيان بقصاره، وفي بعض الأحيان يطول فيها بعض الأحيان كما فعل النبي ﷺ لكن الأغلب بالقصار. نعم.\nالمقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8548/شرح-حديث-معاذ-افتان-انت-يا-معاذ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_280/28002.mp3","categories":["شروح الحديث"]},{"id":10442,"question":"اشرحوا لنا قول الرسول ﷺ: من صلى الفجر فهو في ذمة الله إلى آخر الحديث جزاكم الله خيراً؟","title":"ما معنى: «من صلى الفجر فهو في ذمة الله»؟","answer":"الجواب: معناه أنه في جوار الله لا يجوز لأحد أن يتعدى عليه، بل يجب على إخوانه المسلمين أن يحترموه وأن لا يتعدوا عليه إلا بحق، وهذا يدل على مزية عظيمة لصلاة الفجر، وأن من أداها فهو في ذمة الله ولاسيما في الجماعة يكون أعظم، فليحذر المسلم أن يطالبه الله بذمته فإن من طالبه الله بذمته أدركه ثم أكبه في النار ولا حول ولا قوة إلا بالله، فالواجب الحذر، وعلى المسلم الذي من الله عليه بالإسلام والتوفيق أن يحذر إيذاء الناس حتى لا يؤذوه وحتى لا يتعدوا عليه، يحفظ صلاته ويواظب عليها الفجر والظهر والعصر والمغرب والعشاء في وقتها مع إخوانه في مساجد الله، والمرأة تحافظ عليها في أوقاتها في بيتها، وعلى كل واحد أن يحذر إيذاء الناس حتى لا يتعدى عليه أحد؛ لأنه متى تعدى جاز التعدي عليه بقدر القصاص، لكن إذا ابتعد عن إيذاء الناس فإنه في الأقرب يسلم من أذى الناس، والله يحميه ويعينه إذا اتقاه واستقام على أمره، وراقبه سبحانه وتعالى، كما قال سبحانه وتعالى: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا [الطلاق:2] .. وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4].\nفالواجب على كل مسلم ومسلمة أن يلزم الحدود الشرعية، وأن يقف عندها، وألا يتعدى على أحد لا بلسانه ولا بفعاله، وبذلك يسلم من أذى الناس، وبذلك تكون له الحرمة والتقدير من إخوانه المسلمين الذين عرفوا صلاته ومواظبته واستقامته، فلا يتعدوا عليه ولا يؤذونه؛ لأنه لم يؤذهم بل استقام على أمر ربه ولم يؤذ أحدا، فهو حقيق بأن لا يؤذى وبأن لا يختفر ذمة الله فيه.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8619/ما-معنى-من-صلى-الفجر-فهو-في-ذمة-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_318/31810.mp3","categories":["شروح الحديث"]},{"id":10466,"question":"ما معنى قوله ﷺ: أيما امرأة نزعت ثيابها في غير بيت زوجها فقد هتكت ما بينها وبين الله من ستر؟","title":"ما معنى: «أيما امرأة نزعت ثيابها في غير بيت زوجها»؟","answer":"الجواب: هذا محتمل والله أعلم أنه كناية عن الكشف للفاحشة وتعاطي ما حرم الله، أما لو كشفت ثيابها لحاجة في حمام خاص ما عندها أحد، في بيت أخيها، أو بيت عمها، أو بيت أبيها، فالأقرب إن شاء الله أنه لا شيء عليها.\nفالحاصل والله أعلم أن المقصود هو الكشف الذي يفضي إلى الفساد. \nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8647/ما-معنى-ايما-امراة-نزعت-ثيابها-في-غير-بيت-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_320/32013.mp3","categories":["شروح الحديث"]},{"id":10576,"question":"اشرحوا لنا قول الرسول الكريم ﷺ : أنا ابن الذبيحين.","title":"معنى قوله صلى الله عليه وسلم: (أنا ابن الذبيحين)","answer":"الجواب: هذا مروي عنه ﷺ وفي صحته نظر لكنه مشهور، والذبيحان هما إسماعيل وعبدالله، إسماعيل جده ابن إبراهيم، فإن الله جل وعلا أمر إبراهيم بذبحه ثم نسخ ذلك والحمد لله، لما سلما لأمر الله نسخ الله ذلك وفداه بذبح عظيم.\nوأما عبدالله فالمشهور أن عبدالمطلب نذر إن الله وهبه عشرة أبناء أن يتقرب إلى الله بذبح أحدهم، فتم له ما رجا وأعطاه الله عشرة، فأقرع بينهم أيهم يذبحه فوقعت القرعة على عبد الله فلم يذبحه ووداه بمائة من الإبل، بدلاً من ذبحه واستقرت هذه الدية في قريش فيما ذكر جماعة من المؤرخين لقريش وعبد المطلب .\nويروى عنه ﷺ أنه قال: أنا ابن الذبيحين تفسيراً لهذا، يعني: الذبيح إسماعيل والذبيح عبدالله الذي كاد أن يذبحه أبوه لولا أنه افتدي بمائة من الإبل، ولولا أن الله نسخ ذبح إسماعيل.\nهما ذبيحان قد استحق ذبحهما لولا ما من الله من الوقاية، من الله به من وقاية ذبحهما بنسخ الذبح في حق إسماعيل وبافتداء عبد المطلب لابنه بمائة من الإبل، هذا هو المشهور في هذا. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8748/معنى-قوله-صلى-الله-عليه-وسلم-انا-ابن-الذبيحين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_323/32308.mp3","categories":["شروح الحديث"]},{"id":10608,"question":"إذا كان هذا الكلام حديثاً فاشرحوه لنا: تقول: إن الله ليزع بالسلطان ما لا يزع بالقرآن؟","title":"معنى قوله: (إن الله ليزع بالسلطان ...)","answer":"الجواب: هذا أثر معروف عن عثمان رضي الله عنه وهو ثابت عن عثمان بن عفان الخليفة الراشد الثالث ، ويروى عن عمر أيضاً  أيضاً: إن الله يزع بالسلطان ما لا يزع بالقرآن معناه: يمنع بالسلطان من اقتراف المحارم أكثر مما يمنع بالقرآن؛ لأن بعض الناس ضعيف الإيمان لا تؤثر فيه زواجر القرآن ومناهي القرآن، بل يقدم على المحارم ولا يبالي، لكن متى علم أن هناك عقوبة من السلطان ارتدع خاف من العقوبة السلطانية، فالله يزع بالسلطان يعني: عقوبات السلطان يزع بها بعض المجرمين أكثر مما يزعهم بالقرآن؛ لضعف إيمانهم وقلة خوفهم من الله ، ولكنهم يخافون السلطان لئلا يسجنهم أو يضربهم أو ينكلهم أموالاً أو ينفيهم من البلاد، فهم يخافون ذلك وينزجرون من بعض المنكرات التي يخشون عقوبة السلطان فيها، وإيمانهم ضعيف فلا ينزجرون لزواجر القرآن ونواهي القرآن؛ لضعف الإيمان وقلة البصيرة ولا حول ولا قوة إلا بالله. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8780/معنى-قوله-ان-الله-ليزع-بالسلطان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_326/32607.mp3","categories":["شروح الحديث"]},{"id":10622,"question":"رسالة وصلت إلى البرنامج من المستمع: أحمد عوض السيد عبدالقادر سوداني مقيم في الطائف، أخونا يسأل ويقول: في حديث عن رسول الله ﷺ، رواه أنس  قال: من أحب أن يبسط له في رزقه، وينسأ له في أثره فليصل رحمه وأنا أعلم أن هناك آيات من القرآن من بينها: إذَا جَاءَ أَجَلُهُمْ لا يَسْتَأْخِرُونَ سَاعَةً وَلا يَسْتَقْدِمُونَ [الأعراف:34] كيف نوفق بين هذه الآية وبين ما في ذلكم الحديث؟","title":"الجمع بين: «من أحب أن يبسط» وقوله: {إذَا جَاءَ أَجَلُهُمْ}","answer":"الجواب: لا منافاة بين الحديث والآيات، فكون الإنسان يبسط له في الرزق وينسأ له في الأجل بسبب صلة الرحم أو بسبب بر الوالدين لا يمنع قوله تعالى: وَلَنْ يُؤَخِّرَ اللَّهُ نَفْسًا إِذَا جَاءَ أَجَلُهَا [المنافقون:11] فالمعنى: أن الله جل وعلا يجعل صلة رحمه وبر والديه من أسباب تأخير أجله في الأزل السابق والقدر السابق، فالله جل وعلا يعلم أن هذا يصل رحمه ويبر والديه، فلهذا أجل له زيادة في العمر، وفسح له في العمر، وذاك يقطع رحمه ويعق والديه فلم يفسح له في العمر وجعل عمره كذا لحكمة بالغة، وقد يطول عمر هذا العاق وعمر هذا العاصي ويعجل أجل المطيع لأسباب أخرى وحكمة بالغة من الله ، وفي الحديث الصحيح: لا يرد القدر إلا الدعاء، ولا يزيد في العمر إلا البر يعني: بر الوالدين.\nفهو من جنس حديث أنس: من أحب أن يبسط له في رزقه يقول النبي ﷺ: من أحب أن يبسط له في رزقه وأن ينسأ له في أجله فليصل رحمه وصلة الرحم وبر الوالدين وكثرة الدعاء في طول الحياة على خير من أسباب تأخير الأجل، فيما مضى في علم الله، ليس معناه أن هذا قد كتبه الله يموت في كذا ثم أخر، لا المقصود أن الله جل وعلا جعل بر هذا لوالديه، وصلته لأرحامه، وكثرة دعائه من أسباب تأخير أجله الذي مضى به علم الله، فعلم الله لا يتغير ، ولا يعقبه جهل ، ولا يسبقه جهل، بل علم الله شامل ، لا يعتريه جهل ولا نقص، فهذا إذا جاء أجله تمت حياته والآخر كذلك، والآخر كذلك، وكلٌ له أسبابه، هذا أطيل في أجله لبره وصلة رحمه وكثرة دعاءه، وهذا عجل له الأجل لأسبابٍ أخرى، وهذا مد له في الأجل لأسبابٍ أخرى، فربك حكيم جل وعلا، وليس هناك منافاة بين الأسباب؛ لأن الآجال معلقة بأسبابها، والأرزاق معلقة بأسبابها، والله هو المقدر لهذا ولهذا .","link":"https://binbaz.org.sa/fatwas/8798/الجمع-بين-من-احب-ان-يبسط-وقوله-اذا-جاء-اجلهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_327/32710.mp3","categories":["التفسير","شروح الحديث"]},{"id":10634,"question":"أعوذ بالله السميع العليم من الشيطان الرجيم من نفخه وهمزه ونفثه ما هو همز الشيطان ونفخه ونفثه؟","title":"معنى: (.. من همزه ونفخه ونفثه)","answer":"الجواب: جاء في الحديث أن النبي صلى الله عليه وسلم فسر همزه: بأنها الموتة الصرع، ما يحصل من الصرع للناس من الشيطان، ونفخه: الكبر، ما يقع في نفوس الناس من الكبر فهو من الشيطان، ينفخ بعض الناس حتى يتكبر على عباد الله.\nونفثه: الشعر المذموم، يزين له الشعر المذموم والقصائد المذمومة فيما حرم الله من التشبيب بالنساء والدعوة إلى الزنا أو إلى الخمر أو إلى غيره مما حرم الله عز وجل. نعم.","link":"https://binbaz.org.sa/fatwas/8806/معنى-من-همزه-ونفخه-ونفثه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_328/32808.mp3","categories":["شروح الحديث"]},{"id":10656,"question":"هذا السائل أبو عبد الله من الرياض يقول: أسأل سماحة الشيخ عن هذا الحديث: أسفروا بالفجر فإنه أعظم للأجر فهل معنى ذلك أن يتأخر الإنسان أو الإمام بصلاة الفجر بالمأمومين، وجهوني في ضوء هذا الحديث مأجورين؟","title":"معنى حديث: (أسفروا بالفجر فإنه أعظم في الأجر)","answer":"الجواب: الحديث صحيح، ولفظه يقول ﷺ: أسفروا بالفجر فإنه أعظم في الأجر وفي اللفظ الآخر: أصبحوا بالصبح فإنه أعظم لأجوركم والمعنى عند أهل العلم عدم العجلة حتى يتبين الصبح.. حتى يتضح الصبح، وليس معناه أنه يصلي بعد الغلس، لا، السنة بغلس، كان النبي ﷺ يصلي بالغلس بعد ضياء الصبح لكن هناك بقية من بقية الليل، هذا هو السنة يكون بينهما، بين الظلمة وبين الصبح، فيه بعض الغلس، والحديث لا يخالف ذلك، أصبحوا بالصبح يعني لا تعجلوا حتى ينشق الفجر وحتى يتضح الفجر لكن مع بقاء بعض الغلس هذا هو الأفضل، ولو أخرها حتى اتضح الفجر بالكلية وذهب الغلس قبل طلوع الشمس فلا بأس، لكن لا يؤخر إلى طلوع الشمس، يجب أن تؤدى كاملة قبل طلوع الشمس، لكن الأفضل والأحسن أن يؤديها في حال الغلس بعد طلوع الفجر نص ساعة، نصف إلا خمس، حواليها، يكون هناك غلس وهناك ضياء الصبح واضح.\nالمقدم: سماحة الشيخ عبد العزيز ! تفاوت الأئمة في صلاة الفجر بماذا تنصحونهم؟ جزاكم الله خيراً.\nالشيخ: قد وضع لهم.. الأوقاف وضعت للفجر خمسة وعشرين دقيقة احتياطًا، فإذا صلى لخمسة وعشرين أو لنص الساعة الأمر واسع إن شاء الله.\nالمقدم: جزاكم الله خيراً سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/8833/معنى-حديث-اسفروا-بالفجر-فانه-اعظم-في-الاجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_285/28518.mp3","categories":["شروح الحديث"]},{"id":10700,"question":"ننتقل بعد هذا إلى رسالة وصلت إلى البرنامج من قرية العسادي وصاب العالي من اليمن الشمالي، صاحب الرسالة هو المستمع: أحمد عز الدين حزام العماد، يقول: يقول الرسول ﷺ: كل بدعة ضلالة، وكل ضلالة في النار، أو كما قال ﷺ، ويقول أيضاً: من سن في الإسلام سنة حسنة فله أجرها وأجر من عمل بها إلى يوم القيامة، ومن سن في الإسلام سنة سيئة فعليه وزرها ووزر من عمل بها إلى يوم القيامة، أو كما جاء عن الرسول ﷺ، نرجو توضيح هذين الأمرين لأن فيهما إشكالاً على كثير من الناس، جزاكم الله خيراً؟","title":"الجمع بين: «كل بدعة ضلالة» و «من سن في الإسلام»","answer":"الجواب: نعم كل هذا صحيح عن رسول الله عليه الصلاة والسلام، صح عنه عليه الصلاة والسلام أنه قال: في الحديث الصحيح في خطبة الجمعة: خير الحديث كتاب الله، وخير الهدي هدي محمد ﷺ، وشر الأمور محدثاتها، وكل بدعة ضلالة، أخرجه مسلم في صحيحه. زاد النسائي بإسناد حسن: وكل ضلالة في النار، وقال أيضا عليه الصلاة والسلام في الحديث الصحيح: إياكم ومحدثات الأمور، فإن كل محدثة بدعة وكل بدعة ضلالة، وقال أيضاً عليه الصلاة والسلام: من أحدث في أمرنا هذا ما ليس منه فهو رد، أي: فهو مردود متفق على صحته، وقال عليه الصلاة والسلام: من عمل عملاً ليس عليه أمرنا فهو ردخرجه مسلم في صحيحه. فالواجب على علماء الإسلام أن يوضحوا البدع للناس وأن ينكروها وأن يرشدوا الناس إلى تركها، وهي الإحداث في الدين، وهي أن يشرع الإنسان شيئاً ما شرعه الله، هذا هو البدعة إحداث شيء ما شرعه الله من صلاة أو صوم أو غير ذلك على وجه ما شرعه الله، فهذا يسمى بدعة. كأن يقول مثلاً: أنه يشرع للناس أن يصوموا يوم الجمعة تطوعاً بها، هذا بدعة الرسول ﷺ نهى عن إفرادها بالصوم: نهى أن تفرد الجمعة بالصوم إلا أن يصوم قبلها يوم أو بعدها يوم فالذي يقول: إنها تصام وأنه مشروع قد ابتدع وخالف الأحاديث الصحيحة، أو يقول: أنه يشرع للناس أن يصلوا صلاة ذات ركوعين أو ذات ثلاثة سجودات في الركعة أو ما أشبه ذلك لأن هذا بدعة، إلا ما جاء به النص في صلاة الكسوف فيها ركوعان وفيها ثلاثة ركوعات كما في الأحاديث الصحيحة مع سجدتين في كل ركعة، ولكن إذا قال: يشرع أن يركع ركوعين في الصلاة في كل ركعة غير صلاة الكسوف صار هذا بدعة. وهكذا البناء على القبور واتخاذ المساجد عليها من البدع؛ لأن هذا حدث بعد النبي ﷺ؛ ولأن أصحابها يتقربون به إلى الله، وهو مما يبعدهم من الله، وهو من البدع التي توقع في الشرك وقد حذر منه النبي ﷺ فقال: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم مساجد، ألا فلا تتخذوا القبور مساجد فإني أنهاكم عن ذلك. وقال عليه الصلاة والسلام: لعن الله اليهود و النصارى اتخذوا قبور أنبيائهم مساجد ونهى عن تجصيص القبور القعود عليها والبناء عليها، فالذي يبني عليها المساجد والقباب قد ابتدع في الدين وخالف نص الرسول ﷺ وأتى بأمر وسيلة إلى الشرك، وهكذا وضع الستور عليها والأطياب من البدع، ومن وسائل الشرك. وهكذا الاحتفال بموت فلان أو بولادته فلان هذه من البدع أيضاً، ومن ذلك الاحتفال بمولده صلى الله عليه وسلم لا أصل له، لم يفعله الرسول ﷺ ولا أصحابه ، ولا العلماء والأخيار في القرون المفضلة، إنما حدث بعد القرون الثلاثة، حدث في المائة الرابعة وما بعدها. والمسلم ليس له أن يتقرب إلا بشيء شرعه الله، كما تقدم في الأحاديث. أما حديث: من سن في الإسلام سنة حسنة فله أجرها، الحديث فهذا معناه: إحياء السنن وإظهارها والدعوة إليها، هذا معنى من سن في الإسلام أظهر السنة ودعا إليها وعظمها حتى عرفها الناس وحتى عملوا بها، فيكون له مثل أجورهم، ليس معناه إنه ابتدع بدعة لا، البدعة منكرة حذر منها الرسول صلى الله عليه وسلم، ويدل على هذا سبب الحديث، فإن سبب الحديث أن النبي ﷺ رأى ناساً عليهم آثار الفقر والحاجة فخطب الناس وذكرهم وحثهم على الصدقة فجاء رجل بصرة من فضة في يده كادت كفه تعجز عنها بل قد عجزت، ثم تتابع الناس بالصدقات، فقال عند ذلك: من سن في الإسلام سنة حسنة كان له أجرها وأجر من عمل، من بعده لا ينقص من أجورهم شيئا، ومن سن في الإسلام سنة سيئة كان عليه وزرها ووزر من عمل بها من بعد ذلك لا ينقص ذلك من أوزارهم شيئا، فالمعنى: إظهار السنن والدعوة إليها يكون لفاعل ذلك أجر ما فعل ومثل أجور من اقتدى به في الخير. وهكذا من دعا إلى الباطل والمعاصي وابتدع في الدين يكون عليه إثم ذلك ومثل آثام من تابعه في البدعة. وليس معنى سن في الإسلام يعني: ابتدع لا، هذا مناقضة للأحاديث الصحيحة، ولا يجوز لأحد أن يقول هذا الكلام؛ لأن هذا معناه رد السنة وإنكارها، الرسول ﷺ أنكر البدع وحذر منها وأبدى وعاد في ذلك. والله في القرآن نبه على هذا ربنا سبحانه نبه في القرآن على هذا، فقال سبحانه: أَمْ لَهُمْ شُرَكَاءُ شَرَعُوا لَهُمْ مِنَ الدِّينِ مَا لَمْ يَأْذَنْ بِهِ اللَّهُ [الشورى:21]، هذا معناه إنكار أن يشرع في الدين ما لم يأذن به الله، فالذي يأتي بشيء من كيسه لم يشرعه الله ورسوله يكون باطلاً يكون بدعة، مثلما تقدم في إحداث البناء على القبور المساجد على القبور، وإحداث الموالد الاحتفال بالموالد، الصلاة عند القبور كل هذا من البدع. فيجب على كل مسلم وعلى كل مسلمة الحذر منها والتحذير منها، تحذير إخوانهم منها حتى يستووا على السنة وحتى يتمسكوا بالسنة، وحتى يحذروا ما ابتدعه الناس. نعم. المقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8882/الجمع-بين-كل-بدعة-ضلالة-و-من-سن-في-الاسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_342/34206.mp3","categories":["شروح الحديث"]},{"id":10769,"question":"رسالة وصلت إلى البرنامج من لاجوس عاصمة نيجيريا وباعثها مستمع من هناك يقول: نرجو أن تشرحوا لنا هذا الحديث: عن أبي هريرة  قال: قال رسول الله ﷺ: اثنتان في الناس هما بهم كفر: الطعن في النسب، والنياحة على الميت رواه مسلم ، اشرحوا لنا هذا الحديث جزاكم الله خيراً؟","title":"معنى حديث: (اثنتان في الناس هما بهم كفر ...)","answer":"الجواب: أوضح العلماء رحمهم الله أن الكفر كفران: كفر أكبر، وكفر أصغر.\nفالكفر الأكبر مثل: عبادة غير الله كدعاء الأموات والاستغاثة بالأموات، وطلب المدد من الأموات أو من الأصنام، أو من الأشجار والأحجار، أو النجوم أو الجن، هذا شرك أكبر وكفر أكبر، ومثل: سب الدين سب الله سب الرسول ﷺ، كل هذا كفر أكبر، مثل: الحكم بغير ما أنزل الله عن استحلال، يستحل الحكم بغير ما أنزل الله ويرى أنه جائز هذا كفر أكبر، وما أشبه ذلك من نواقض الإسلام، كجحد وجوب الصلاة أو جحد وجوب الزكاة أو استحلال الزنا كل هذا كفر أكبر، فإذا استحل ما حرم الله مما هو معلوم من الدين بالضرورة كالزنا والسرقة والخمر كان كافراً كفراً أكبر، أو جحد ما أوجب الله كالزكاة والصلاة وصوم رمضان صار كفراً أكبر، أو سب الله وسب الرسول ﷺ أو سب الدين أو ترك الصلاة عمداً كفر أكبر نسأل الله العافية.\nأما الكفر الأصغر مثل ما في الحديث هذا: اثنتان في الناس هما بهم كفر: الطعن في النسب، والنياحة على الميت هذا كفر أصغر؛ لأنه كفر منكر في سياق الإثبات فهو كفر أصغر، والطعن في النسب معناه: عيب الأنساب عيب أنساب الناس فلان نسبك كذا نسبه ..... فلان بخيل أهله حدادون يعيبهم بذلك، نجارون يعيبهم بذلك، إلى غير هذا مما يطعن في أنساب الناس، هذا نوع من الكفر وهو معصية وكبيرة، وهكذا النياحة على الميت إذا مات الميت ينوح عليه يعني: يرفع صوته بالبكاء هذا نوع كفر، لكنه أصغر مثل الحديث الصحيح: سباب المسلم فسوق وقتاله كفر، يعني: كفر أصغر لو قتله بغير حق يكون كفر أصغر إذا لم يستحل ذلك، مثل: إن كفراً بكم براءة من أنسابكم أو براءة من آبائكم هذا كفر أصغر، إلا إذا استحل سب المسلمين يكون كفراً أكبر نعوذ بالله، أو استحل البراءة من نسبه أو من أبيه يكون كفر أكبر إن استحل ما حرم الله بإجماع المسلمين، كما لو استحل الزنا قال: إنه حلال، أو قال: اللواط حلال، أو الخمر حلال، يكون كفراً أكبر نسأل الله العافية.\nهذا هو الفرق بينهما ما كان فيه دعوة لغير الله وعبادة لغيره كفر أكبر، وما كان فيه استحلال لما حرم الله مما هو معلوم من الدين بالضرورة، أو إنكار لما أوجب الله مما هو معلوم من الدين بالضرورة، وبالأدلة الشرعية مما أجمع عليه المسلمون هذا كفر أكبر. نعم.","link":"https://binbaz.org.sa/fatwas/8948/معنى-حديث-اثنتان-في-الناس-هما-بهم-كفر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_348/34808.mp3","categories":["شروح الحديث"]},{"id":11070,"question":"هذه السائلة رمزت لاسمها بـ (هـ. أ. م) الرياض تقول: قال الرسول ﷺ: تبلغ الحلية من المؤمن حيث يبلغ الوضوء أرجو تفسير هذا الحديث جزاكم الله خيرًا.","title":"معنى حديث: (تبلغ الحلية من المؤمن حيث بلغ الوضوء)","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فهذا الحديث من الأحاديث الصحيحة عن رسول الله ﷺ وفيها بيان أن الحلية من المؤمن في الجنة تبلغ مبلغ الوضوء، معناه: أنه يكون في يديه الحلية إلى ما خلف المرفقين، يعني: أنها تمتد الحلية على ذراعه إلى ما وراء المرفق؛ لأن الوضوء ينتهي بغسل المرفقين، فتمتد الحلية في يديه إلى نهاية موضع الوضوء، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/9248/معنى-حديث-تبلغ-الحلية-من-المومن-حيث-بلغ-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_288/28818.mp3","categories":["شروح الحديث"]},{"id":11134,"question":"كيف تشرحون حديث رسول الله ﷺ: هي لك أو لأخيك أو للذئب؟","title":"ما معنى: «هي لك أو لأخيك أو للذئب»؟","answer":"الجواب:  معناه واضح، يعني: إذا تركتها أخذها الذئب، أو أخذها غيرك، فخذها أنت، واحتسب الأجر مع التعريف لها. المقدم: مع التعريف. الشيخ: مع التعريف. المقدم: إذًا لا يقصد من هذا عدم التعريف؟ الشيخ: لا، الأحاديث يفسر بعضها بعضًا. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/9313/ما-معنى-هي-لك-او-لاخيك-او-للذىب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_369/36913.mp3","categories":["شروح الحديث"]},{"id":11144,"question":"بعد هذا رسالة وصلت إلى البرنامج من الجمهورية العربية السورية، باعثتها إحدى الأخوات المستمعات تقول: المرسلة إيمان عباس من سوريا، الأخت إيمان لها أكثر من قضية في إحدى قضاياها تقول: وضحوا لنا قول المصطفى ﷺ: من سن في الإسلام سنة حسنة فله أجرها، وأجر من عمل بها من بعده، من غير أن ينقص من أجورهم شيء رواه مسلم ، وأنه قد يسبق هذا الحديث قصة، لابد أنكم تعرفونها يا سماحة الشيخ، ولا مجال لذكرها في هذا البرنامج، فالمقصود أن تبينوا لنا السنة الحسنة، وتشرحوا لنا كلام الحبيب ﷺ.","title":"معنى حديث: (من سن في الإسلام سنة حسنة..)","answer":"الجواب:  نعم هذا الحديث صحيح، وجاء في معناه أحاديث يقول النبي ﷺ من دل على خير فله مثل أجر فاعله، ويقول ﷺ في حديث جرير: من سن في الإسلام سنة حسنة كان له أجرها، وأجر من عمل من بعده، لا ينقص ذلك من أجورهم شيئًا، ومن سن في الإسلام سنة سيئة كان عليه وزرها، ووزر من عملها من بعده، لا ينقص ذلك من أوزارهم شيئًا. وأسباب هذا الحديث أن جماعة من الفقراء، جاؤوا إلى النبي ﷺ فلما رآهم النبي ﷺ ورأى فقرهم، خطب الناس وحثهم على الصدقة، ورغبهم فيها وقال: تصدق رجل بدرهمه، بديناره، بصاع بره، بصاع تمره، بثوبه ورغبهم في ذلك -عليه الصلاة والسلام- فجاء رجل بصرة من فضة كادت كفه تعجز عنها، ثم تتابع الناس في الصدقات، حتى رأى بين يديه كومين من طعام وثياب، فلما رأى النبي ذلك -عليه الصلاة والسلام- استنار وجهه، حتى كأنه مذهبة، سرورًا منه بعملهم، وحرصهم على الخير، ومسارعتهم إلى الصدقة. ثم قال هذا الحديث: من سن في الإسلام سنة حسنة كان له أجرها، وأجر من عمل من بعده، لا ينقص ذلك من أجورهم شيئًا. والمعنى أن الإنسان إذا فعل خيرًا، وتأسى به الناس في ذلك، يكون له مثل أجورهم، فإذا تصدق على الفقراء تابعه الناس لما رأوه تصدق، فله مثل أجورهم، وإذا دعا إلى سنة كالتراويح في رمضان في بلد ما كانوا يصلون التراويح، ثم تابعوه يكون له مثل أجورهم، أو دعا إلى صيام ست من شوال بين أناس لا يعرفونها، فتابعوه صار له مثل أجورهم، أو دعا إلى صيام الإثنين والخميس، وبين فضل ذلك بين أناس لا يعرفون ذلك، فعملوا بذلك بسبب نصيحته، وصاموا الإثنين والخميس، يكون له مثل أجورهم وهكذا. كل من دل على خير، فتابعه الناس على ذلك، وتأسوا به، وانتفعوا بدعوته، يكون له مثل أجورهم، وهذا معنى الحديث الآخر: من دل على خير فله مثل أجر فاعله خرجه مسلم في صحيحه، وفق الله الجميع.  المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9322/معنى-حديث-من-سن-في-الاسلام-سنة-حسنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_370/37002.mp3","categories":["شروح الحديث"]},{"id":11234,"question":"يقول هذا السائل محمد إسماعيل في سؤاله الثاني: حديث: إذا قرأ الإنسان سورة: قُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص:1]، سورة الإخلاص ثلاث مرات كأنه قرأ القرآن، هل هذا صحيح؟ وما فضل هذه السورة سماحة الشيخ؟!","title":"معنى كون سورة الإخلاص تعدل ثلث القرآن","answer":"الجواب: نعم صحيح، وهي تعدل ثلث القرآن بنص الرسول عليه الصلاة والسلام، لكن من قرأ القرآن وكمله يكون أكمل من جهة تدبر القرآن والفائدة، ولكنها بمنزلة إذا قرأها ثلاث مرات بمنزلة الختمة من جهة الأجر، أما ما يتعلق بالفوائد والتدبر والتعقل فلا شك أن الذي يقرأ القرآن يكون له كمال آخر وفضل آخر لكثرة الفائدة. نعم.","link":"https://binbaz.org.sa/fatwas/9405/معنى-كون-سورة-الاخلاص-تعدل-ثلث-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_291/29115.mp3","categories":["شروح الحديث"]},{"id":11521,"question":"مستمع رمز إلى اسمه بحرفين هما: (أ. ج) أخونا يسأل جمعًا من الأسئلة في أحدها يقول: يقول الرسول ﷺ: إنما الأعمال بالنيات.. الحديث، فهل يجوز للمسلم أن ينوي نية واحدة لجميع الأعمال التي يقوم بها في المستقبل؛ لأنه يصعب عليه إحضار النية عند كل عمل، أم أن لكل عمل نية مستقلة؟ جزاكم الله خيرًا.","title":"حكم جعل نية واحدة لجميع الأعمال","answer":"الجواب:  كل عمل له نية، ولا يكفي النية العامة، الصلاة لها نية، والصوم له نية، وعيادة المريض لها نية، وهكذا كل شيء له نية، فلابد من النية في أعمالك العبادية أعمال العبادات، فيصلي بنية، ويصوم بنية، ويتصدق بنية، ويحج بنية، ويعود المريض بنية، وهكذا، إنما الأعمال بالنيات يقول ﷺ: إنما الأعمال بالنيات، وإنما لكل امرئ ما نوى فالنية لها شأن عظيم، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9703/حكم-جعل-نية-واحدة-لجميع-الاعمال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_384/38419.mp3","categories":["شروح الحديث"]},{"id":11551,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من الجمهورية العربية السورية محافظة الرقة، باعث الرسالة المستمع: موسى الدرويش بن دحام أخونا يسأل جمعًا من الأسئلة، في أحدها يقول: هل الذي يحفظ سورة البقرة فقط تظله يوم القيامة؟","title":"فضائل قراءة القرآن والعمل به","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد. \nفقد ثبت عن رسول الله -عليه الصلاة والسلام- أنه قال: يؤتى بأهل القرآن يوم القيامة الذين يعلمون به، تقدمه سورة البقرة وآل عمران؛ تحاجان عن أصحابهما يوم القيامة، كأنهما غمامتان، أو غيايتان، أو فرقان من طير صواف، تحاجان عن أصحابهما. فهذا الحديث الصحيح، وما جاء في معناه يدل على أن البقرة وآل عمران تحاجان عن أصحابهما الذين يعملون بالقرآن، لأنه قال: بأهله العاملين به فالقرآن حجة لمن عمل به كله، القرآن كله حجة، ومن أسباب سعادة العبد، فإن القرآن يشفع له يوم القيامة ويشفع، وهكذا هاتان السورتان العظيمتان تحاجان عن أصحابهما العاملين بهما، وإذا كان الرجل يحفظ سورة البقرة، ويعمل بها هي أيضًا تحاج عن صاحبها، وإن لم يحفظها، إذا كان يعمل بها؛ فإنها حجة له من أسباب دخوله الجنة. فجدير بالمؤمن أن يعتني بالحفظ العملي، وإذا لم يتيسر الحفظ فالمهم العمل، كونه يقرأ ولو نظرًا، يقرأ ويعتني ويعمل، وإن تيسر الحفظ؛ فهذا خير إلى خير، ونور إلى نور، لكن الأهم من هذا كله العمل، كونه يقرأ القرآن، ويعمل به، سواءً حفظه، أم لم يحفظه؛ فهو حجة له، وهكذا البقرة، وآل عمران حجة له إذا عمل بذلك. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9734/فضاىل-قراءة-القران-والعمل-به","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_386/38601.mp3","categories":["فضائل الأعمال","شروح الحديث"]},{"id":11581,"question":"أخيرًا من هو أحسن من شرح رياض الصالحين؟","title":"ذكر أحسن شرح لرياض الصالحين","answer":"الجواب:  أما شروح رياض الصالحين فلم أتأملها، ودليل الفالحين معروف، اطلعت على شيء منه، ولكن ليس هو بالشرح الكافي. المقدم: لمن لو تكرمتم دليل الفالحين؟ الشيخ: هذا شرح رياض الصالحين، نسيت اسم مؤلفه الآن راح من بالي اسم مؤلفه، والمقصود أنه ليس من الشروح الوافية، يفيد وينفع، ولكن ليس من الشروح الوافية فيما اطلعت عليه من مواضع، ولم أقرأ فيه كثيرًا، إنما راجعت بعض المواضع فيه، فقد يراجعه بعض أهل العلم فلا يجد فيه المطلوب من جهة العناية بطرق الحديث، وبيان صحته وضعفه، واستدراك هذا المؤلف أو عدم ذلك. فرياض الصالحين كتاب مفيد وعظيم، والحافظ النووي رحمه الله قد اعتنى به، واجتهد فيه، ومع ذلك يوجد فيه بعض الأحاديث الضعيفة يعرفها أهل العلم، لكنه كتاب يغلب عليه الصحة والفائدة العظيمة، وهو كتاب بحمد الله نفع الله به كثيرًا، واستعمله أهل العلم في سائر الأقطار، وهو كتاب مفيد عظيم، والحديث الضعيف فيه قليل. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9763/ذكر-احسن-شرح-لرياض-الصالحين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_298/29804.mp3","categories":["شروح الحديث"]},{"id":11587,"question":"بعد هذا يسأل سماحتكم فيقول: من السبع الموبقات قذف المحصنات، كيف يكون ذلك؟ جزاكم الله خيرًا.","title":"معنى قذف المحصنات","answer":"الجواب:  برميهن بالفاحشة الزنا، هذا القذف، نسأل الله العافية، نعم. المقدم: اللهم آمين، إذًا قذف المحصنات يكون. الشيخ: من السبع الموبقات، نعم. نسأل الله العافية. المقدم: نسأل الله العافية والسلامة، جزاكم الله خيرًا. الشيخ: نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/9770/معنى-قذف-المحصنات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_386/38616.mp3","categories":["شروح الحديث"]},{"id":11766,"question":"من الجزائر العاصمة رسالة وضمنها صاحبها ثمانية أسئلة، في أحدها يسأل ويقول: اشرحوا لنا حديث رسول الله ﷺ: أمرت أن أسجد على سبعة أعظم، ولا أكف شعرًا، ولا ثوبًا؟","title":"شرح حديث: (أمرت أن أسجد على سبعة أعظم)","answer":"الجواب:  الحديث واضح يقول ﷺ: إنه أمر أن يسجد على سبعة أعظم، وألا يكف شعرًا، ولا ثوبًا فهذا هو الواجب على الساجد أن يسجد على السبعة الأعضاء، على جبهته وأنفه هذا واحد، كفيه هذه ثلاثة، ركبتيه هذه خمسة، أطراف قدميه هذه سبعة، ولا يكف شعرًا، لو كان له ظفائر عمايل يتركها، لا يزويها، تسجد معه، أو طرف ثوبه كأكمامه، أو طرف عمامته لا حرج، السنة أن يسجد بها لا يكفها وقت السجود، يسجد على العادة التي هو عليها، لا يغير شيئًا، لا يكف شعرًا، لا شعر رأس، ولا كم، ولا عمامة، بل يسجد على الجميع، ولا يكف شيء خضوعًا لله، ورغبة فيما عنده، وإقبالًا على الخشوع، وحذرًا من التشويش، وعدم الخشوع. نعم.  المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9950/شرح-حديث-امرت-ان-اسجد-على-سبعة-اعظم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_394/39412.mp3","categories":["شروح الحديث"]},{"id":11775,"question":"يسأل عن المقصود بالكاسية العارية، ومن هي؟ جزاكم الله خيرًا.","title":"شرح حديث: (صنفان من أمتي لم أرهما ..)","answer":"الجواب:  جاء في الحديث عن رسول الله ﷺ أنه قال: صنفان من أهل النار لم أرهما: رجال بأيديهم سياط يضربون بها الناس يعني: ظلمًا ونساء كاسيات عاريات مائلات مميلات، رؤوسهن كأسنمة البخت المائلة، لا يدخلن الجنة، ولا يجدن ريحها الحديث، كاسيات عاريات فسرها العلماء بأنهن كاسيات بالاسم، عاريات؛ لأن الكسوة قصيرة، أو رقيقة، اسم كسوة، لكن ليست ساترة، إما لقصرها، وعدم وفائها، أو لأنها رقيقة شفافة، فهذا هو المعنى، وهن بهذا آثمات.  وهكذا قوله: مائلات مميلات مائلات عن الحق، عن العفاف، مميلات إلى الفاحشة والشر، ليس المراد المشية المائلة، كما يظن بعض الناس لا، المراد: أنهن مائلات عن العفاف والاستقامة، مميلات لغيرهن إلى الباطل والزنا والفواحش، نسأل الله العافية. نعم. المقدم: اللهم آمين جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9961/شرح-حديث-صنفان-من-امتي-لم-ارهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_394/39423.mp3","categories":["شروح الحديث"]},{"id":11793,"question":"بعد هذا رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول: أنا سوداني، يقول في رسالته: أسألكم عن قراب الأرض الواردة في بعض ألفاظ حديث رسول الله ﷺ؟","title":"ما معنى: «لو أتيتني بقراب الأرض خطايا»؟","answer":"الجواب:  جاء في الحديث عن النبي ﷺ أنه قال: يقول الله : لو أتيتني بقراب الأرض خطايا، ثم لقيتني لا تشرك بي شيئًا؛ لقيتك بقرابها مغفرة قرابها يعني ما يقارب ملأها، قرابها يعني ملؤها، أو ما يقارب ملأها، وهذا عبارة عن سعة جوده  وكرمه. والمعنى أنك لو لقيتني بكل الذنوب ما عدا الشرك بالله؛ فإنه -جل وعلا- يغفر لمن تاب إليه، وأناب إليه، وهكذا الشرك إذا تاب صاحبه؛ تاب الله عليه؛ لكن من مات على الشرك؛ فإنه لا يغفر له، بل له النار أبدًا -نسأل الله العافية- لقول الله : إِنَّ اللَّهَ لا يَغْفِرُ أَنْ يُشْرَكَ بِهِ [النساء:48] ثم قال سبحانه وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ [النساء:48] فبين  في كتابه العظيم أن الشرك لا يغفر، وأن ما دونه تحت مشيئته  فمن جاءه بذنوب دون الشرك تائبًا نادمًا؛ تاب الله عليه، وإن جاء غير تائب؛ فهو تحت مشيئة الله، ويرجى له أن يتوب الله عليه، وأن يعفو عنه إذا كانت له أعمال صالحة، أو مات على حسن خاتمة. فالمقصود: أن هذا فيه وعد، فيه رجاء، وعد لمن مات على المعاصي إذا لقي الله موحدًا، ليس بمشرك؛ أن الله يغفر له، فهذا من أحاديث الرجاء، من أحاديث الوعد، وهناك أحاديث الوعيد لمن مات على المعاصي. فالواجب على العاصي، الواجب عليه أن يبادر بالتوبة، وألا يتعلق بأحاديث الرجاء، بل يجب أن يحذر وعيد الله  يحذر الوعيد، ويحسن ظنه بربه -جل وعلا- فيبادر بالتوبة، وترك المعاصي، ولا يتعلق بالرجاء، ويقيم على المعاصي، فهو على خطر عظيم، لأنه متوعد بالنار إذا قام على المعاصي. فالواجب على المسلم أن يبادر إلى ما يرضي الله، وأن يدع ما حرم الله، مع حسن ظنه بربه ورجائه، أن يغفر له ما قد يبقى من ذنوبه وسيئاته إذا مات على شيء من ذلك، يحسن ظنه بربه، ويرجوه أن يغفر له، لكنه لا يتساهل، ولا يعتمد على الرجاء، ويقيم على المعاصي والسيئات. فأنت يا عبدالله عليك أن تحذر الإصرار، وأن تبادر بالتوبة النصوح من ذنوبك؛ لعلك تفوز بالمغفرة والرحمة؛ لأن الله  وعد المغفرة من لم يصر كما في هذه الآية الكريمة مع الرجاء لمن مات على المعاصي؛ يكون عنده حسن ظن بالله، لا يقنط، ولكن يحذر، ويجتهد في التوبة، في ترك المعاصيـ مادام في قيد الحياة؛ حذرًا من غضب الله؛ وحذراً من عقابه  نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9977/ما-معنى-لو-اتيتني-بقراب-الارض-خطايا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_422/42210.mp3","categories":["شروح الحديث"]},{"id":11899,"question":"يقول الرسول ﷺ: إن لله تسعة وتسعين اسمًا، لا يحفظها أحد إلا دخل الجنة أو كما قال ﷺ هل كل من حفظ أسماء الله يضمن دخوله الجنة؟ جزاكم الله خيرًا.","title":"معنى حديث: (إن لله تسعة وتسعين اسمًا ...)","answer":"الجواب:  هذا من أحاديث الوعد، من أحاديث الفضائل مثل غيره من أحاديث الفضائل، يقول ﷺ: إن لله تسعة وتسعين اسمًا مائة إلا واحدًا، من أحصاها؛ دخل الجنة وفي لفظ آخر: من حفظها دخل الجنة متفق على صحته، هذا فيه حث على العناية بأسماء الله، وتدبرها حفظًا وإحصاء؛ حتى يستفيد من هذه المعاني العظيمة، وحتى يكون هذا من أسباب خشوعه لله، وطاعته له، والقيام بحقه  وهي من أسباب دخول الجنة لمن حفظها، وأدى حق الله، ولم يغش الكبائر، أما من غشي الكبائر من المعاصي؛ فهو معرض لوعيد الله، وتحت مشيئة الله، إن شاء عذبه، وإن شاء أدخله الجنة.  لكن حفظ هذه الأسماء، وإحصاءها من أسباب دخول الجنة، لمن سلم من الموانع الأخرى، فإن دخول الجنة له أسباب، وله موانع، فالإقامة على المعاصي من أسباب حرمان دخول الجنة، مع أول من دخلها مع الداخلين أولًا، فيعذب، ثم بعدما يطهر ويمحص إذا كان مات على المعاصي؛ يدخل الجنة، وقد يعفو الله عنه، ويدخل من أول وهلة. يقول النبي ﷺ: الصلوات الخمس، والجمعة إلى الجمعة، ورمضان إلى رمضان كفارات لما بينهن ما لم تغش الكبائر يعني: كبائر الذنوب وهي المعاصي التي فيها وعيد، أو غضب أو لعنة، مثل: الزنا، مثل: شرب الخمر، مثل: عقوق الوالدين، أو أحدهما، مثل: أكل الربا، مثل: الغيبة والنميمة، وأشباهها من المعاصي، هذه خطيرة، أمرها خطير، وصاحبها إذا مات عليها تحت مشيئة الله، إن شاء الله غفر له وأدخله الجنة بتوحيده وإسلامه، وإن شاء عذبه على قدرها، ثم بعدما يطهر، ويمحص في النار، يخرجه الله من النار إلى الجنة. وقد تواترت الأحاديث عن رسول الله ﷺ أن كثيرًا من العصاة يدخلون النار بمعاصيهم، ويعذبون فيها على قدر معاصيهم، ثم بعد التطهير والتمحيص يخرجهم الله من النار، بعضهم بشفاعة النبي ﷺ وبعضهم بشفاعة غيره من الملائكة والأنبياء والأفراط، وبعضهم بمجرد عفو الله إذا طهر؛ عفا الله عنه؛ لقول الله : إِنَّ اللَّهَ لا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ [النساء:48] فهذه المعاصي مسألة معلقة، إن شاء الله عفا عنهم وأدخلهم الجنة، وإن شاء عذبهم على قدر معاصيهم، ثم يخرجون من النار، بعد التطهير، ولا يخلدون، ويدخلون الجنة بعد ذلك، ولا يخلد في النار إلا أهل الكفر بالله والشرك، هم الذين يخلدون لا يغفر لهم، أما أهل المعاصي ولو عذِّب بعضهم ودخل النار لا يخلد عند أهل السنة والجماعة، خلافًا للخوارج والمعتزلة، ومن سار على مذهبهم الباطل، فإنهم يرون أن العصاة يخلّدون في النار، وهذا مذهب باطل. أما أهل السنة والجماعة فيقولون: العصاة تحت المشيئة، إذا ماتوا على التوحيد والإسلام، وعندهم معاصٍ؛ فهم تحت المشيئة، إذا كان لم يتوبوا، وفق الله الجميع. المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10083/معنى-حديث-ان-لله-تسعة-وتسعين-اسما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_425/42520.mp3","categories":["شروح الحديث"]},{"id":11962,"question":"المستمعة (م) من الرياض بعثت تسأل تفسير وشرح عدد من الأحاديث منها هذا الحديث: إذا خلعت المرأة ثيابها في غير بيت زوجها، فقد هتكت الستر الذي بينها وبين الله  هل هذا يعني أن المرأة لا تغير ملابسها عند الضرورة في منزل أهلها، أو في منزل أخيها؟","title":"ما معنى: «إذا خلعت المرأة ثيابها في غير بيت زوجها»؟","answer":"الجواب:  الأقرب -والله أعلم- أن المراد بذلك إذا خلعتها للفاحشة والشر، أو لعدم المبالاة حتى يراها الرجال، أما إذا خلعتها لمصلحة في بيت أخيها، أو بيت أبيها، أو بيت محرم لها، أو بيت مأمون عند أخواتها في بيت ليس فيه خطر لتغيير ملابسها، أو للتحمم والاغتسال، على وجه ليس فيه إظهار العورة للناس، وليس فيه خطر، فالأقرب -والله أعلم- أنه لا حرج في ذلك، وأن مراد النبي ﷺ إذا فعلت ذلك على وجه فيه الخطر. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10147/ما-معنى-اذا-خلعت-المراة-ثيابها-في-غير-بيت-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_429/42903.mp3","categories":["شروح الحديث"]},{"id":11963,"question":"قال رسول الله ﷺ: فلا يموتن أحدكم إلا وهو يحسن الظن بالله ما معنى هذا الحديث؟","title":"ما معنى: «فلا يموتن أحدكم إلا وهو يحسن الظن بالله»؟","answer":"الجواب:  معنى ذلك أن الواجب على المؤمن حسن ظنه بالله، وأن يحذر سوء الظن بالله  وفي الحديث الآخر يقول الرب -جل وعلا-: أنا عند ظن عبدي بي، وأنا معه إذا دعاني. فالمشروع للمؤمن والواجب عليه حسن ظنه بالله، وأن يرجو رحمته ومغفرته، وأن يخشى عذابه، وأن يجتهد في طاعة الله وطاعة رسوله ﷺ؛ لأنه كلما اجتهد في الطاعة؛ صار أقرب إلى حسن الظن، وكلما ساءت أعماله؛ صار هذا من أسباب سوء ظنه كما قال الشاعر:  إذا ساء فعل المرء ساءت ظنونه. فالمقصود أن الإنسان يتحرى ما شرع الله له، ويجتهد في طاعة الله ورسوله، وترك ما نهى الله عنه ورسوله؛ لأن هذا من أعظم الأسباب في حسن ظنه بالله  يحذر سوء الظن بالله  لأنه قد عصاه، بل يبادر بالتوبة، ويحسن ظنه بربه أنه يقبل التوبة، ويرحمه  فهو الرحمن الرحيم، وهو الجواد الكريم، وهو الذي يقبل التوبة عن عباده. فعلى المؤمن أن يحسن ظنه بالله، وإن جرى منه معصية، يحسن ظنه بربه، ويبادر بالتوبة، لا أن يقيم على المعاصي، يبادر ويسارع إلى التوبة، ويحسن ظنه بربه أنه يقبل توبته، وأنه يرحمه، وأنه يجيره من عذابه، لما تاب إليه وأناب  نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10148/ما-معنى-فلا-يموتن-احدكم-الا-وهو-يحسن-الظن-بالله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_429/42904.mp3","categories":["شروح الحديث"]},{"id":11968,"question":"عن أبي هريرة  عن النبي ﷺ قال: خلق الله آدم على صورته، طوله ستون ذراعًا الحديث متفق عليه، أرجو من سماحتكم شرح هذا الحديث شرحًا وافيًا، وبيان ما يقع فيه من سوء تأويل، وما يقع فيه من إشكالات، والإجابة عن هذه الإشكالات جزاكم الله خيرًا.","title":"معنى حديث: (خلق الله آدم على صورته)","answer":"الجواب:  هذا الحديث قد أشكل على بعض الناس، وتأوله على أن المراد على صورة آدم، خلق الله آدم على صورة آدم، وهذا غلط، وليس من فصيح الكلام، بل المراد خلقه الله على صورته هو  ولهذا في الحديث الآخر: خلق الله آدم على صورة الرحمن وهي رواية جيدة، أثبتها الإمام أحمد وغيره، الإمام أحمد وإسحاق بن راهويه وآخرون، تفسر هذه رواية شبهة الضمير: (على صورته) أي: صورة الرحمن، والمعنى: أنه  خلق آدم سميعًا بصيرًا يتكلم، وله وجه، وله يد، وله قدم، وهكذا ربنا سبحانه: سميع بصير يتكلم وله وجه وله يدان وله قدم سبحانه كما أخبر عن نفسه: بَلْ يَدَاهُ مَبْسُوطَتَانِ [المائدة:64].  وقال -جل وعلا-: مَا مَنَعَكَ أَنْْ تَسْجُدَ لِمَا خَلَقْتُ بِيَدَيَّ [ص:75] وقال النبي ﷺ: إن جهنم لا تزال تقول: هل من مزيد؟ حتى يضع الله بها رجله وفي رواية: قدمه فينزوي بعضها إلى بعض وتقول: قط قط وليس المراد أنه شبيه له، وأنه مثله لا، بل المراد أنه على صورته من حيث أنه سميع بصير متكلم، ذو وجه، ذو قدم، ذو يد، لكن ليس السميع كالسميع، وليس البصير كالبصير، وليست اليد كاليد، ولا القدم كالقدم، ولا الكلام كالكلام، قال الله سبحانه: لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ [الشورى:11] وقال سبحانه: وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌٌ [الإخلاص:4] وقال : فَلا تَضْرِبُوا لِلَّهِ الأَمْثَالَ [النحل:74] هذا قول أهل السنة والجماعة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10153/معنى-حديث-خلق-الله-ادم-على-صورته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_429/42909.mp3","categories":["شروح الحديث","الأسماء والصفات"]},{"id":12001,"question":"بعد هذا رسالة بعث بها المستمع محمد نعمان من اليمن، يقول: نهى الرسول ﷺ عن بيع الحاضر للباد، أرجو توضيح هذه الصورة؟","title":"ما معنى: «نهى رسول الله أن يبيع حاضر لبادٍ»؟","answer":"الجواب:  بيع الحاضر للبادي، الحاضر: هو المقيم في البلد، والبادي: هو الذي يجيء من خارج، مثل: البادية الذين يبتعدون عن صنعاء، إذا جلبوا إلى صنعاء لا يتولى الحاضر البيع لهم يبيعون بأنفسهم. وهكذا الذي خارج الرياض إذا جلب إلى الرياض يبيع بنفسه، لا يبيع له الحاضر؛ لأنه إذا باع الحاضر؛ شدد على الناس، وأما البادي إذا باع بنفسه؛ كان أرخص للناس، ولهذا نهى النبي ﷺ عن بيع الحاضر للبادي فإذا قدم جماعة من البادية معهم غنم، أو لبن، أو أقط، أو غير ذلك يبيعون بأنفسهم، حتى يستفيد الناس منهم، إذا قدموا صنعاء، قدموا تعز، قدموا الرياض، قدموا الأحساء، قدموا حائل، قدموا المدينة، لا يتولى الحاضر البيع لهم، يتولون بأنفسهم هم، يبيعون بأنفسهم؛ لأن هذا أقرب إلى مصلحة الناس، والرسول ﷺ يقول: دعوا الناس يرزق الله بعضهم من بعض فإذا تولى الحاضر؛ شدد عليهم في الأثمان. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10186/ما-معنى-نهى-رسول-الله-ان-يبيع-حاضر-لباد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_431/43115.mp3","categories":["شروح الحديث","البيوع"]},{"id":12019,"question":"تقول أختنا في سؤالها الأخير: هل الرسول ﷺ قال في أحد أحاديثه: إنه كان أحد الأنبياء يخط بالحصى وهل يجوز الآن فعل هذا الأمر. جزاكم الله خيرًا.","title":"حكم الخط على الرمل بالحصى","answer":"الجواب:  نعم أخبر النبي ﷺ أنه كان هناك نبي يخط، أما نحن فليس لنا أن نخط؛ لأنا لا نعلم الشيء الذي فعله النبي ﷺ والشيء الذي أجازه الله، فالخطوط الآن التي يفعلها الناس ضرب من الرجم بالغيب، ولا يجوز تعاطيها، ولا فعلها، بل يجب ترك ذلك، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10204/حكم-الخط-على-الرمل-بالحصى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_432/43210.mp3","categories":["شروح الحديث"]},{"id":12022,"question":"اشرحوا لنا قول الرسول ﷺ: من ظلم قيد شبر؛ طوقه من سبع أرضين.","title":"معنى حديث: (من ظلم قيد شبر....)","answer":"الجواب:  معناه: أن الظالم يتحمل هذا الجزء، وما تحته إلى سبع أرضين، ولهذا يقول ﷺ: من ظلم شبرًا من أرض؛ طوقه الله إياه يوم القيامة من سبع أرضين يعني: يجعل طوقًا في عنقه ذلك الجزء، وما تحته إلى آخر الأرض، وهذا نوع من التعذيب الشديد له بظلمه لأخيه، ويستدل به على أن الأرض إذا ملكها إنسان ملك ما تحتها، له أن يحفر ويحفر ويحفر ولو بعد المدى؛ لأنه قد ملك الأرض وما تحتها لهذا الحديث الصحيح، نعم.","link":"https://binbaz.org.sa/fatwas/10207/معنى-حديث-من-ظلم-قيد-شبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_432/43213.mp3","categories":["شروح الحديث"]},{"id":12126,"question":"اشرحوا لنا حديث: المائلات المميلات جزاكم الله خيرًا؟","title":"ما معنى: «صنفان من أهل النار لم أرهما»؟","answer":"الجواب:  يقول النبي ﷺ: صنفان من أهل النار لم أرهما أولًا: رجال بأيديهم سياط يضربون بها الناس مثل: الشرطة، أو غير الشرطة الذين يضربون الناس بغير حق، هؤلاء من أهل النار، هذا وعيد يوجب الحذر، على الجندي، وعلى غير الجندي أن لا يضرب الناس إلا بحق .... ضرب الناس بغير حق. الثاني: نساء صنف ثاني نساء كاسيات عاريات مائلات مميلات، رؤوسهن كأسنمة البخت المائلة، لا يدخلن الجنة، ولا يجدن ريحها .. الحديث. كاسيات عاريات فسر بأنهن يلبسن الثياب الرقيقة، أو القصيرة، فهن كاسيات في الاسم، عاريات في الحقيقة، وهذا منكر عظيم، وفتنة يجب الحذر منها، وقال بعض أهل العلم: معنى كاسيات من نعم الله، عاريات من شكرها بسبب المعاصي الكثيرة. وبكل حال فهن عاصيات بالتبرج، وإظهار محاسنهن، أو لبقية المعاصي سوى ذلك، فهذا من العري، عاريات بالمعاصي، كاسيات بالملابس، أو بالنعم. فالواجب على كل امرأة، وكل مسلمة تقوى الله، وأن تكون بعيدة عما حرم الله، تستتر عن غير المحارم، تكون في ملابس مناسبة، في حشمة، ليس فيها تبرج ولا فتنة، تستر بدنها حتى لا تفتن الناس، وحتى لا تضر نفسها، تكون ملابسها كافية ساترة، ليس فيها فتنة، لا من جهة اللبس القصير، ولا من جهة شفاف، ولا من جهة إظهار بعض المحاسن، كل هذا يجب اجتنابه. مائلات مميلات مائلات عن الحق، عن العفة، عن الاستقامة، مميلات لغيرهن من النساءـ بدعوتهن إلى الباطلـ وتزيين الباطل لهن، ونحو ذلك.  فالواجب الحذر من ذلك، أن تكون مستقيمة على الحق، ولا تميل عنه، وليس لها أن تميل غيرها أيضًا، بل عليها أن تنصح لله، ولعباد الله، وأن تكون مستقيمة على الحق والعفة، وأن تبتعد عن دعوة غيرها من النساء إلى الباطل، والتبرج والتكشف وأسباب الفتنة. رءوسهن كأسنمة البخت المائلة هذه علامة، قال بعض أهل العلم: معناها: أنهن يضخمن الرؤوس، يجعلن عليها من الخرق والأشياء التي يضخمها، تجعلها كبيرة، هذه من علاماتها، من علامات هؤلاء النسوة. فالواجب على النساء أن يحذرن ما حرم الله من جميع الأمور، وأن يلبسن اللباس العادي الذي ليس فيه فتنة، ولا دعوة للباطل، وأن يكن بعيدات عن كل ما حرم الله، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10311/ما-معنى-صنفان-من-اهل-النار-لم-ارهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_438/43811.mp3","categories":["شروح الحديث"]},{"id":12219,"question":"تقول: هل صحيح أن من يقرأ دعاء المعراج أربعين جمعة؛ يغفر له ما تقدم من ذنبه، وأن من يقول: سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر؛ تكون له حسنة؟","title":"الحكم على دعاء المعراج وبيان الذكر المشروع وفضله","answer":"الجواب:  دعاء المعراج هذا لا أصل لهذا الكلام، دعاء المعراج ليس هناك دعاء يقرأ، ويحفظ فيه هذا الأجر، كل هذا باطل لا أساس له، وأما التسبيح فالله -جل وعلا- شرع لنا الذكر والتسبيح والنبي ﷺ أوصى بذلك يقول الله -جل وعلا-: يَا أَيُّهَا الَّذِينَ آمَنُوا اذْكُرُوا اللَّهَ ذِكْرًاا كَثِيرًا ۝ وَسَبِّحُوهُ بُكْرَةً وَأَصِيلًا [الأحزاب:41-42] ويقول -جل وعلا-: يَا أَيُّهَا الَّذِينَ آمَنُوا لا تُلْهِكُمْ أَمْوَالُكُمْ وَلا أَوْلادُكُمْ عَنْْ ذِكْرِ اللَّهِ [المنافقون:9]، ويقول سبحانه: إِنَّ الْمُسْلِمِينَ وَالْمُسْلِمَاتِ وَالْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ وَالْقَانِتِينَ وَالْقَانِتَاتِ [الأحزاب:35]، إلى أن قال سبحانه: وَالذَّاكِرِينَ اللَّهَ كَثِيرًا وَالذَّاكِرَاتِ أَعَدَّ اللَّهُ لَهُمْ مَغْفِرَةً وَأَجْرًا عَظِيمًا [الأحزاب:35] ويقول النبي ﷺ: أحب الكلام إلى الله أربع: سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر ويقول أيضًا -عليه الصلاة والسلام-: الباقيات الصالحات: سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر، ولا حول ولا قوة إلا بالله ويقول أيضًا -عليه الصلاة والسلام-: لأن أقول: سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر؛ أحب إلي مما طلعت عليه الشمس وهذا يدل على فضل عظيم، ويقول أيضًا -عليه الصلاة والسلام-: سبق المفردون، قيل: يا رسول الله! ما المفردون؟ قال: الذاكرون الله كثيرًا والذاكرات. فأوصي كل مسلم وكل مسلمة بالإكثار من ذكر الله، وأوصي إخواني المسلمين جميعًا من الذكور والإناث بالإكثار من ذكر الله من التسبيح، والتحميد والتهليل والتكبير، وقول: لا حول ولا قوة إلا بالله، وقول: لا إله إلا الله وحده لا شريك له، له الملك، وله الحمد، وهو على كل شيء قدير، هذه الكلمة أعظم الذكر، يقول النبي ﷺ: الإيمان بضع وسبعون شعبة أو قال: بضع وستون شعبة، فأفضلها قول: لا إله إلا الله، وأدناها إماطة الأذى عن الطريق والحياء شعبة من الإيمان ويقول ﷺ: من قال: لا إله إلا الله وحده لا شريك له، له الملك، وله الحمد، وهو على كل شيء قدير عشر مرات؛ كان كمن أعتق أربعة أنفس من ولد إسماعيل متفق على صحته، وقال أيضًا -عليه الصلاة والسلام-: من قال: لا إله إلا الله وحده لا شريك له، له الملك، وله الحمد، وهو على كل شيء قدير مائة مرة في يوم؛ كانت له عدل عشر رقاب يعني: يعتقها وكتب الله له مائة حسنة، ومحا عنه مائة سيئة، وكان في حرز من الشيطان في يومه ذاك حتى يمسي، ولم يأت أحد بأفضل مما جاء به إلا رجل عمل أكثر من عمله. وهذا فضل عظيم. فينبغي الإكثار من ذكر الله ومن التسبيح والتحميد والتهليل والتكبير والاستغفار، وفق الله الجميع. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10405/الحكم-على-دعاء-المعراج-وبيان-الذكر-المشروع-وفضله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_446/44607.mp3","categories":["شروح الحديث","الحكم على الأحاديث","الأدعية والأذكار"]},{"id":12228,"question":"تسأل أختنا وتقول: ما صحة الأحاديث التالية، وإذا كانت صحيحة نرجو من سماحتكم التفضل بالشرح الوافي لها: قال رسول الله ﷺ: إن الرجل ليعمل الزمن الطويل بعمل أهل الجنة، ثم يختم له بعمل أهل النار، وإن الرجل ليعمل الزمن الطويل بعمل أهل النار، ثم يختم له بعمل أهل الجنة هذا هو الحديث الأول الذي تسأل عن تفسيره؟","title":"ما معنى: «إن الرجل ليعمل بعمل أهل الجنة»؟","answer":"الجواب:  نعم نعم هذا صحيح، حديث صحيح رواه الشيخان من حديث ابن مسعود  ومعناه: أن الرجل قد يعمل بعمل أهل الجنة من طاعة الله، ولكن في قلبه أشياء، وفي داخله أشياء، ثم ينتقل إلى عمل أهل النار؛ فيختم له بذلك، وفي بعض الروايات: ليعمل بعمل أهل الجنة فيما يبدو للناس يعني: داخل قلبه ليس بذلك، عن نفاق، عنده نفاق، وعنده خبث؛ فلهذا يتظاهر بالأعمال الصالحة، وهو غير مؤمن بها، وإنما أظهرها إما رياءً، وإما لمقاصد أخرى من الدنيا، ثم يغلب عليه ما كان في قلبه من الشر، فيعمل بعمل أهل الشر، ويموت على الشر، ويختم له بخاتمة أهل الشر، وقد يكون عنده نية صالحة طيبة، ثم يتعاطى بعض المعاصي، وبعض الشرور في آخر حياته؛ فيختم له بذلك، وقد يرتد عن دينه -والعياذ بالله- بسبب حظ عاجل، أو بسبب سب الدين، أو بسبب مساعدة المشركين على المسلمين؛ فيكون بذلك من أهل النار؛ لأنه ارتد عن إسلامه بما فعله من النواقض، مثل سب الدين، سب الرسول ﷺ، مساعدة الكفار على المسلمين في الحرب، الاستهزاء بدين الله، وما أشبه هذا من أسباب الردة، نسأل الله العافية والسلامة. وهكذا الرجل قد يعمل بعمل أهل الشر زمنًا طويلًا، ثم يمن الله عليه بالإسلام، فيموت على الإسلام، ويدخل الجنة، كما جرى لعمر بن الخطاب، وجمع من الصحابة كانوا على الكفر والضلال، ثم هداهم الله، ودخلوا في الإسلام، وبعضهم لم يبق في الإسلام إلا مدة يسيرة، أيامًا قليلة، ثم توفاه الله، أو قتل شهيدًا؛ فدخل الجنة، وكان في غالب حياته على الكفر والضلال، ثم هداه الله للإسلام، ومات عليه، هذا يقع، وهذا يقع، وربك حكيم عليم  نعم. المقدم: جزاكم الله خيرًا، تسأل عن شرح حديث آخر قريبًا من الحديث الأول، وتروي الحديث فتقول: قال الرسول ﷺ: إن العبد ليعمل بعمل أهل النار، وإنه من أهل الجنة، ويعمل عمل أهل الجنة، وإنه من أهل النار. الشيخ: مثلما تقدم. نعم، يعني علم الله أنه سيموت على الإسلام، فيكون من أهل الجنة، وعلم الله من حاله أنه في المستقبل سوف يرتد، فيكون من أهل النار، هو يعمل بعمل أهل الإسلام، والله قد علم من قلبه، ومن حاله، ومستقبله أنه سوف يرتد؛ فيكون من أهل النار، قد يعمل بعمل أهل النار، والله يعلم من حاله، ومن قلبه أنه سوف يتغير حاله؛ فيدخل الجنة، مثلما تقدم في الحديث السابق، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10416/ما-معنى-ان-الرجل-ليعمل-بعمل-اهل-الجنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_447/44704.mp3","categories":["شروح الحديث"]},{"id":12377,"question":"بعد هذا رسالة بعث بها أحد الإخوة المستمعين يسأل ويقول: أنا عبدالرحمن الرويبي من المنطقة الشرقية، أسأل سماحتكم عن المقصود من حديث الرسول ﷺ الذي يقول فيه: يدخل الملك على النطفة بعدما تستقر في الرحم بأربعين، أو خمسة وأربعين ليلة فيقول: يا رب! أشقي أو سعيد؟ أي رب! ذكر أو أثنى؟ فيكتبان، ويكتب عمله، وأثره، وأجله، ورزقه، ثم تطوى الصحف؛ فلا يزاد فيها ولا ينقص أرجو توضيح ما المقصود من شقي أو سعيد، هل ذلكم في الآخرة، أم في الدنيا؟","title":"ما معنى: «يدخل الملك على النطفة بعدما تستقر»؟","answer":"الجواب:  هذا الحديث ثابت في صحيح مسلم من حديث حذيفة بن أسيد الغفاري، وقد ذكر بعض أهل العلم أن هذا يقع في بعض الأجنة، والعمدة على حديث ابن مسعود أن الكتابة تكون في أول الشهر، في أول الطور الرابع، إذا مضى عليه ثلاثة أطوار، أربعون وأربعون وأربعون يعني: أربعة أشهر، أتاه الملك، فقال: يا رب! ما الرزق؟ ما الأجل؟ أشقي أم سعيد؟ يكتب كل ذلك بعد مضي الأطوار الثلاثة، يعني: في أول الشهر الخامس، هذا هو المحفوظ في الصحيحين من حديث ابن مسعود  أما ما جاء في حديث حذيفة بن أسيد الغفاري بأن هذا يقع بعد مضي أربعين، أو خمسة وأربعين ليلة؛ فهذا لعله في بعض الأجنة، جمعًا بين الحديثين، لعل هذا يكون بعض الأجنة بالنسبة إلى الجمع بين الحديثين، وأنه يكتب بعض الأجنة في ... حين يمضي له أربعون، أو خمس وأربعون ليلة، ولا يتناقض، ولا تعارض مع حديث ابن مسعود، نعم. المقدم: جزاكم الله خيرًا، قضية يسأل عنها -لو تكرمتم سماحة الشيخ- يقول: ما المقصود من شقي أو سعيد، هل هو في الآخرة، أو في الدنيا؟ الشيخ: ... شقي في الدنيا، أو سعيد في الدنيا بالنسبة إلى الآخرة، إذا شقي يعني: في الآخرة، يكون في حال الدنيا شقاوة في الآخرة، تكون في الدنيا، إذا كان شقيًا في الدنيا؛ عمل بعمل الأشقياء؛ صار شقيًا في الآخرة، وإذا كان سعيدًا في الدنيا عمل بطاعة الله؛ صار سعيدًا في الآخرة؛ لأن الآخرة مبنية على الدنيا. المقدم: الله المستعان، كأن الدنيا مزرعة للآخرة سماحة الشيخ؟ الشيخ: نعم، نعم. المقدم: بارك الله فيكم، ما المقصود بهذه الشقاوة سماحة الشيخ؟  الشيخ: الشقاوة أنه من أهل النار يعني، أن أعماله كلها تضره، وأنه من أهل النار، ليس من أهل الجنة، والسعيد الذي يوفق لأعمال أهل الجنة بالصالحات، الله يجعلنا وإياكم من السعداء. المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10566/ما-معنى-يدخل-الملك-على-النطفة-بعدما-تستقر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_400/40004.mp3","categories":["شروح الحديث"]},{"id":12438,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من مستمع يقول المستمع (م. ح) من السودان يسأل ويقول: عن جابر بن سمرة : أن رجلًا سأل النبي ﷺ أأتوضأ من لحوم الغنم؟ قال: إن شئت قال: أأتوضأ من لحوم الإبل؟ قال: نعم وفي الحديث الآخر: \"أنه كان آخر الأمرين منه ﷺ عدم الوضوء مما مست النار\" ما الحكمة في هذين الحديثين، ولا سيما الوضوء من لحم الإبل؟ وكيف نجمع بين هذين الحديثين؟ جزاكم الله خيرًا.","title":"الجمع بين: الوضوء من لحوم الإبل، وترك الوضوء مما مست النار","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فحديث جابر بن سمرة المذكور صحيح، رواه مسلم في الصحيح: أن النبي  لما سئل عن لحوم الإبل أمر بالوضوء منها، وأما في الغنم فقال: إن شئت وثبت في حديث البراء بن عازب  أن النبي  قال توضؤوا من لحوم الإبل فأمر بالوضوء منها.  هذا يدل على أن لحم الإبل ينقض الوضوء، وأن الواجب على من أكل لحم الإبل من الرجال والنساء الوضوء، وأما تركه الوضوء مما مست النار فهذا عام يستثنى منه لحم الإبل، كان النبي ﷺ أمر بالوضوء مما مست النار، ثم ترك ذلك، فقال جمهور أهل العلم: إنه منسوخ، وقال آخرون: إنما ترك ذلك من جهة بيان عدم الوجوب، وإلا فيستحب الوضوء من لحم الغنم ونحوه. فالحاصل: أن ترك الوضوء مما مست النار أمر عام، يعم الإبل والبقر والغنم، وغير ذلك، فجاءت أحاديث لحم الإبل تستثنيه، فدل على أنه ما أراده ﷺ إنما أراد البقر والغنم والطيور، ونحو ذلك، أما الإبل فهو باقي، ولهذا جمع بينهما لما سئل عن لحم الإبل؟ قال: توضأ وعن لحم الغنم قال: إن شئت فدل هذا على أنه ما جاء نسخ.. الوضوء مما مست النار. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10640/الجمع-بين-الوضوء-من-لحوم-الابل-وترك-الوضوء-مما-مست-النار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_403/40309.mp3","categories":["شروح الحديث"]},{"id":12440,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من مستمع يقول المستمع (م. ح) من السودان يسأل ويقول: عن جابر بن سمرة : أن رجلًا سأل النبي ﷺ أأتوضأ من لحوم الغنم؟ قال: إن شئت قال: أأتوضأ من لحوم الإبل؟ قال: نعم وفي الحديث الآخر: \"أنه كان آخر الأمرين منه ﷺ عدم الوضوء مما مست النار\" ما الحكمة في هذين الحديثين، ولا سيما الوضوء من لحم الإبل؟ وكيف نجمع بين هذين الحديثين؟ جزاكم الله خيرًا.","title":"الجمع بين: الوضوء من لحوم الإبل، وترك الوضوء مما مست النار","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فحديث جابر بن سمرة المذكور صحيح، رواه مسلم في الصحيح: أن النبي  لما سئل عن لحوم الإبل أمر بالوضوء منها، وأما في الغنم فقال: إن شئت وثبت في حديث البراء بن عازب  أن النبي  قال توضؤوا من لحوم الإبل فأمر بالوضوء منها.  هذا يدل على أن لحم الإبل ينقض الوضوء، وأن الواجب على من أكل لحم الإبل من الرجال والنساء الوضوء، وأما تركه الوضوء مما مست النار فهذا عام يستثنى منه لحم الإبل، كان النبي ﷺ أمر بالوضوء مما مست النار، ثم ترك ذلك، فقال جمهور أهل العلم: إنه منسوخ، وقال آخرون: إنما ترك ذلك من جهة بيان عدم الوجوب، وإلا فيستحب الوضوء من لحم الغنم ونحوه. فالحاصل: أن ترك الوضوء مما مست النار أمر عام، يعم الإبل والبقر والغنم، وغير ذلك، فجاءت أحاديث لحم الإبل تستثنيه، فدل على أنه ما أراده ﷺ إنما أراد البقر والغنم والطيور، ونحو ذلك، أما الإبل فهو باقي، ولهذا جمع بينهما لما سئل عن لحم الإبل؟ قال: توضأ وعن لحم الغنم قال: إن شئت فدل هذا على أنه ما جاء نسخ.. الوضوء مما مست النار. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10640/الجمع-بين-الوضوء-من-لحوم-الابل-وترك-الوضوء-مما-مست-النار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_403/40309.mp3","categories":["شروح الحديث"]},{"id":12533,"question":"تسأل أختنا عن الفرق بين قول الزور، وشهادة الزور في حديث الرسول ﷺ؟","title":"الفرق بين قول الزور وشهادة الزور","answer":"الجواب:  قول الزور أعم، وشهادة الزور أخص، الله -جل وعلا- قال: فَاجْتَنِبُوا الرِّجْسَ مِنَ الأَوْثَانِ وَاجْتَنِبُوا قَوْلَ الزُّورِ [الحج:30] قول الزور يشمل الشهادة، وغير الشهادة وهو الكذب، قول الزور هو الكذب كونه يكذب على الناس: صار كذا .....كذا بيع كذا، سافر فلان وهو يكذب، قدم فلان، إلى غير هذا من الكذب، وشهادة الزور كونه يشهد لفلان أنه باع كذا، أو اشترى كذا، أو أن عليه دين لكذا، أو أن عنده مال لفلان، يشهد بحق وهو كاذب، يشهد بشيء وهو كاذب، هذه من شهادة الزور، يشهد لفلان: أنه شرى من فلان كذا وكذا، أن له دين على فلان وهو يكذب، هذه شهادة الزور، يشهد أنه قتل فلانًا، دعس فلانًا وهو يكذب، يشهد بأنه سبه، بأنه قذفه وهو يكذب، كل هذا يقال له: شهادة الزور، في الحديث الصحيح يقول النبي ﷺ في الحديث الصحيح: ألا أنبئكم بأكبر الكبائر؟ قلنا: بلى يا رسول الله! قال -عليه الصلاة والسلام: الإشراك بالله، وعقوق الوالدين وكان متكئًا فجلس فقال: ألا وقول الزور ألا وشهادة الزور. فأخبر ﷺ (أن أكبر الكبائر الشرك والعياذ بالله) وهو عبادة غير الله، صرف بعض العبادة لغير الله، كالذي يدعو الأموات، يستغيث بالأموات، ينذر لهم، يذبح لأهل القبور، يذبح للجن، يستغيث بالجن، يذبح للأصنام من الأشجار والأحجار، للنجوم، هذا هو الشرك الأكبر، أو يجحد ما أوجب الله، كأن يجحد وجوب الصلاة أو وجوب الزكاة أو وجوب صوم رمضان، أو يجحد ما أحل الله للمسلمين كأن يجحد حل البر، حل الإبل والبقر والغنم، أو يجحد ما حرم الله، كأن يقول الزنا حلال، أو الخمر حلال، كل هذا كفر أكبر، شرك أكبر. ثم يلي هذا العقوق للوالدين، عقوق الوالدين من أكبر الكبائر، قتل النفوس بغير حق من أكبر الكبائر، يلي الشرك القتل والعقوق للوالدين -نسأل الله العافية- الأب والأم والجد والجدة، بالسب والشتم، أو الضرب، أو غير هذا من أنواع الأذى، ثم قال: شهادة الزور الكذب، نسأل الله العافية، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10727/الفرق-بين-قول-الزور-وشهادة-الزور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_408/40806.mp3","categories":["شروح الحديث"]},{"id":12585,"question":"المستمع عمر الدين السيلاني من كلومبو بسيرلنكا بعث برسالة ضمنها جمعًا من الأسئلة، في أحد أسئلته يقول: يقول العلم: إن الإنسان يفكر بالمخ، ولكن هناك بعض الآيات في القرآن الكريم، وكذلك بعض الأحاديث للنبي ﷺ تشير إلى القلب مثلًا: أَوَلَيْسَ اللَّهُ بِأَعْلَمَ بِمَا فِي صُدُورِ الْعَالَمِينَ [العنكبوت:10] ثم قول الرسول ﷺ: ألا وإن في الجسد مضغة إذا صلحت؛ صلح الجسد كله، وإذا فسدت؛ فسد الجسد كله، ألا وهي القلب أرجو التوضيح زادكم الله من علمه؟","title":"وجه كون التفكير بالمخ وكون القلب محل الصلاح والفساد","answer":"الجواب:  ليس هناك منافاة بين ما في النصوص في أن القلب هو محل الصلاح والفساد، وما يقول الأطباء من جهة المخ، فإن الدماغ له صلة بالقلب، والقلب له صلة بالدماغ، كما قال أهل العلم، ولهذا قال -جل وعلا- في كتابه العظيم : أَفَلَمْ يَسِيرُوا فِي الأَرْضِ فَتَكُونَ لَهُمْ قُلُوبٌ يَعْقِلُونَ بِهَا [الحج:46] فجعل العقل يتعلق بالقلب، فالعقل محله القلب، ولكن له صلة بالدماغ، إذا خرب الدماغ اختل العقل، فالقلب له ارتباط بالدماغ، والدماغ له ارتباط بالقلب، فإذا اختل هذا؛ اختل هذا، وإذا اختل هذا؛ اختل هذا، فليس هناك منافاة بين ما قاله الأطباء عن الدماغ، وبين ما دل عليه القرآن والسنة من أن القلب هو محل الصلاح والفساد.  فالقلب متى صلح؛ صلح الجسد كله كما في الحديث، ومتى فسد؛ فسد الجسد كله؛ لأنه محل الإيمان، محل الخوف من الله، ومحل تعظيم حرمات الله، لكن له ارتباط بالدماغ، فإذا اختل الدماغ؛ اختل القلب، وهذا معروف عند الأطباء، معروف بالتجارب، فإنه متى أصيب الرجل في رأسه؛ اختل شعوره كثيرًا في كثير من الأحيان بالضربة التي تكون في رأسه. فالحاصل: أن الرأس له صلة بالقلب، والقلب له صلة بالدماغ، فلا منافاة بين هذا وهذا. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10793/وجه-كون-التفكير-بالمخ-وكون-القلب-محل-الصلاح-والفساد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_412/41208.mp3","categories":["التفسير","شروح الحديث"]},{"id":12660,"question":"من المملكة الأردنية الهاشمية هذا سؤال بعث به أحد الإخوة من هناك يقول: اشرحوا لنا حديث رسول الله ﷺ: إن أبغض الحلال عند الله الطلاق؟","title":"شرح حديث: (أبغض الحلال إلى الله الطلاق)","answer":"الجواب:  هذا الحديث اختلف العلماء في وصله وإرساله، منهم من ضعفه لإرساله، والصواب أنه لا بأس به، وأنه متصل، ومعناه: أن الطلاق ينبغي تركه إلا من حاجة، هو حلال ليس بحرام، ولكنه أبغض الحلال؛ لما فيه من التفرقة بين الرجل وأهله. فينبغي للمؤمن ألا يلجأ إلى الطلاق إذا وجد حيلة في ترك الطلاق، فإذا أمكن، واستصلح هو والزوجة، والبقاء معها على حالة حسنة، فالمشروع له ترك الطلاق، فإذا دعت الحاجة إلى الطلاق لسوء عشرتها، أو لفسقها، أو لأسباب أخرى، لكونه لم يحبها ما جعل الله في قلبه لها مودة؛ فلا بأس بذلك. المقصود: أن الطلاق حلال عند الحاجة إليه، ولكنه أبغض الحلال إلى الله، والمعنى في هذا الترغيب في عدم الطلاق، والحث على البقاء مع الزوجة إذا أمكن ذلك؛ لما في البقاء مع الزوجة من الخير والعفة؛ ولأنه سبب للأولاد، وعفته وعفتها، وغض البصر إلى غير هذا من مصالح. لكن إذا كانت المودة غير موجودة، أو كانت هناك أسباب أخرى من سوء خلقها، أو فسقها، أو أسباب أخرى رأى المصلحة في طلاقها؛ فلا حرج في ذلك. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10870/شرح-حديث-ابغض-الحلال-الى-الله-الطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_458/45812.mp3","categories":["شروح الحديث"]},{"id":12712,"question":"المستمع فواز محمد زايد من مدينة مهد الذهب متوسطة ابن القيم بالمهد بعث يسأل ويقول: قال الرسول ﷺ: والذي نفسي بيده لو لم تذنبوا؛ لذهب الله بكم، ولجاء بقوم غيركم يذنبون، فيستغفرون الله؛ فيغفر لهم اشرحوا لنا هذا الحديث؟ جزاكم الله خيرًا.","title":"ما معنى: «والذي نفسي بيده لو لم تذنبوا»؟","answer":"الجواب:  معنى الحديث أن الله  قضى في سابق علمه أنه لابد من وقوع الذنوب حتى تظهر آثار مغفرته ورحمته سبحانه، واسمه التواب الغفور والعفو؛ لأنه -جل وعلا- لو لم يكن هناك ذنوب؛ لم يكن لمعنى العفو والغفور والتواب معنى، فهو  سبق بقضائه وعلمه أن الجن والإنس يذنبون؛ فيتوب الله على من تاب، ويغفر الله لمن شاء، ويعفو عمن شاء . وليس معناها الترخيص في الذنوب لا، الله نهى عنها وحرمها، لكن سبق في علمه أنها توجد، وأنه سبحانه يعفو عمن يشاء، ويغفر لمن يشاء إذا تاب إليه، فهذا فيه دلالة على أن هذا لابد منه؛ فلا يقنط المؤمن، لا يقنط، ولا ييئس، ويعلم أن الله كتب ذلك عليه، فليتب إلى الله، ولا ييئس، ولا يقنط، وليبادر بالتوبة، والله يتوب على التائبين. فليس القدر حجة، ولكن عليك أن لا تقنط، وأن لا تيئس، وأن تتوب إلى الله سبحانه، وتعلم أن هذا شيء قضاه الله عليك، وعلى غيرك. فلا تيئس، ولا تقنط، وبادر بالتوبة، والله يتوب على التائبين  وقد سبق في علمه أنها تقع الذنوب من الجن والإنس، وأنه يتوب على من تاب، ويعفو عمن رجع إليه، ويعفو عمن يشاء ممن أصر  فضلًا منه، وإحسانًا -جل وعلا- حتى تظهر آثار أسمائه الحسنى التواب الرحيم العفو الغفور. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10924/ما-معنى-والذي-نفسي-بيده-لو-لم-تذنبوا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_459/45917.mp3","categories":["شروح الحديث"]},{"id":12825,"question":"أحد الإخوة المستمعين بعث برسالة يقول فيها: أرجو أن تتفضلوا بشرح الحديث التالي: يقول ﷺ: كل قرض جر نفعًا فهو ربا.","title":"شرح حديث: (كل قرض جر نفعاً فهو ربا) وحكمه","answer":"الجواب:  الحديث المذكور ضعيف عند أهل العلم، ليس بصحيح، ولكن معناه صحيح عند العلماء، معناه: أن القروض التي تجر نفعًا ممنوعة بالإجماع، فإذا أقرضه ألف ريال على أنه يعطيه سيارته، يستمتع بها شهرًا أو شهرين، أو على أنه يسكن في بيته، أو على أن يعطيه أرضه يزرعها حتى يرد عليه الدراهم، هذا لا يجوز، عند جميع أهل العلم، أو قال: أقرضك ألف ريال على أن ترد علي ألفًا ومائة، أو ألفًا وخمسين، هذا لا يجوز؛ لأن القرض إرفاق وإحسان، فلا يجوز فيه الزيادة، ولا شرط الزيادة، لكن لو رد إليه زيادة من دون شرط، لما قضى أعطاه بعض الشيء عند القضاء من دون شرط؛ لا بأس؛ لقول النبي ﷺ: إن خيار الناس أحسنهم قضاءً فإذا استقرض منه مائة ألف، ويوم ردها عليه أعطاه مائة ألف وزيادة، لا حرج من دون شرط، ومن دون مواطأة، أو اقترض منه سنًا صغيرًا، فأعطاه سنًا كبيرًا، اقترض منه جذعًا، فأعطاه ثني؛ لا بأس، كما فعل النبي ﷺ. فالمقصود أن الزيادة من دون شرط من باب المعروف؛ لا حرج فيها: إن خيار الناس أحسنهم قضاءً عند الرد، أما ما دام القرض في يده، وهو عنده، فإنه لا يعطيه زيادة، ولا يجوز لصاحب القرض أن يأخذ زيادة، لا مشروطة، ولا عند التواطؤ، ولا، ما دام القرض عنده، إلا أن يحسبها من القرض، إلا إذا كان بينهم عادة، وبينه هدايا بينهم تمشي على حالها العادية، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11039/شرح-حديث-كل-قرض-جر-نفعا-فهو-ربا-وحكمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_463/46313.mp3","categories":["شروح الحديث"]},{"id":12826,"question":"أيضًا يطلب شرح هذا الأثر: انصر أخاك ظالمًا، أو مظلومًا.","title":"شرح حديث: (انصر أخاك ظالمًا أو مظلومًا) وحكمه","answer":"الجواب:  هذا حديث صحيح شرحه النبي ﷺ قال ﷺ: انصر أخاك ظالمًا، أو مظلومًا وهذه كلمة تقولها العرب، وكان العرب عندهم تعصب، ينصرون أصحابهم وإن ظلموا، واشتهر عندهم هذا: انصر أخاك ظالمًا أو مظلومًا فلما قاله النبي ﷺ قالوا: يا رسول الله! كيف أنصره ظالمًا؟ قال: تحجزه عن الظلم فذلك نصرك إياه نصر المظلوم واضح، لكن نصر الظالم معناه: منعه من الظلم، وحجزه عن الظلم، هذا نصره، فإذا أراد أن يضرب أحدًا تقول: لا، قف تمسكه، إذا أراد أن يأخذ مال أحد؛ تمسكه، هذا نصره، إذا كان لك استطاعة؛ تمنعه من ذلك، هذا نصر الظالم، تعينه على نفسه، وعلى شيطانه، تنصره على شيطانه، وعلى هواه الباطل، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11040/شرح-حديث-انصر-اخاك-ظالما-او-مظلوما-وحكمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_463/46314.mp3","categories":["شروح الحديث"]},{"id":12857,"question":"مستمع من السودان، يقول: التيجاني آدم بعث يسأل ويقول: عن أبي هريرة  أن رسول الله ﷺ قال: كل أمتي يدخل الجنة إلا من أبى! قيل: ومن يأبى يا رسول الله؟! قال: من أطاعني دخل الجنة، ومن عصاني فقد أبى اشرحوا لنا هذا الحديث، وما معناه، جزاكم الله خيرًا؟","title":"معنى حديث: (كل أمتي يدخلون الجنة...)","answer":"الجواب:  هذا الحديث حديث صحيح، رواه البخاري في صحيحه عن أبي هريرة  عن النبي ﷺ أنه قال: كل أمتي يدخلون الجنة إلا من أبى قيل: يا رسول الله ومن يأبى؟! قال: من أطاعني دخل الجنة ومن عصاني فقد أبى معناه: أن أمته التي تطيعه، وتتبع سبيله تدخل الجنة، ومن لم يتبعه؛ فقد أبى، من تابع الرسول ﷺ ووحد الله، واستقام على الشريعة، فأدى الصلوات، وأدى الزكاة، وصام رمضان، وبر والديه، وكف عن محارم الله من الزنا، وشرب المسكرات، وغير ذلك، فهذا يدخل الجنة؛ لأنه تابع الرسول ﷺ. أما من أبى، ولم ينقد للشرع؛ فهذا معناه: قد أبى، معناه أنه امتنع من دخول الجنة بأعماله السيئة، هذا هو معنى الحديث.  فالواجب على المسلم أن ينقاد لشرع الله، وأن يتبع محمدًا -عليه الصلاة والسلام- فيما جاء به هو رسول الله حقًا، هو خاتم الأنبياء -عليه الصلاة والسلام- قد قال الله في حقه: قُلْ إِنْ كُنْتُمْ تُحِبُّونَ اللَّهَ فَاتَّبِعُونِي يُحْبِبْكُمُ اللَّهُ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ [آل عمران:31] فاتباعه ﷺ من أسباب المحبة، محبة الله للعبد، ومن أسباب المغفرة، ومن أسباب دخول الجنة، أما عصيانه ومخالفته، فذلك من أسباب غضب الله، ومن أسباب دخول النار، ومن فعل ذلك؛ فقد أبى، من امتنع من طاعة الرسول ﷺ فقد أبى. فالواجب على كل مسلم، بل على كل أهل الأرض من الرجال والنساء والجن والإنس، الواجب عليهم جميعًا أن ينقادوا لشرعه ﷺ وأن يتبعوه، وأن يطيعوا أوامره، وينتهوا عن نواهيه، وهذا هو سبب دخول الجنة، قال الله -جل وعلا-: مَنْ يُطِعِ الرَّسُولَ فَقَدْ أَطَاعَ اللَّهَ [النساء:80]، وقال سبحانه: قُلْ أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ فَإِنْ تَوَلَّوا فَإِنَّمَا عَلَيْهِ مَا حُمِّلَ وَعَلَيْكُمْ مَا حُمِّلْتُمْ وَإِنْ تُطِيعُوهُ تَهْتَدُوا وَمَا عَلَى الرَّسُولِ إِلَّا الْبَلاغُ الْمُبِينُ [النور:54] ويقول سبحانه: قُلْ يَا أَيُّهَا النَّاسُ إِنِّي رَسُولُ اللَّهِ إِلَيْكُمْ جَمِيعًا الَّذِي لَهُ مُلْكُ السَّمَوَاتِ وَالأَرْضِ لا إِلَهَ إِلَّا هُوَ يُحْيِي وَيُمِيتُ فَآمِنُوا بِاللَّهِ وَرَسُولِهِ النَّبِيِّ الأُمِّيِّ الَّذِي يُؤْمِنُ بِاللَّهِ وَكَلِمَاتِهِ وَاتَّبِعُوهُ لَعَلَّكُمْ تَهْتَدُونَ [الأعراف:158] وقال قبلها : فَالَّذِينَ آمَنُوا بِهِ [الأعراف:157] يعني: بمحمد -عليه الصلاة والسلام-فَالَّذِينَ آمَنُوا بِهِ وَعَزَّرُوهُ وَنَصَرُوهُ وَاتَّبَعُوا النُّورَ الَّذِي أُنزِلَ مَعَهُ أُوْلَئِكَ هُمُ الْمُفْلِحُونَ [الأعراف:157] وقال -جل وعلا- في كتابه المبين: وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانْتَهُوا وَاتَّقُوا اللَّهَ إِنَّ اللَّهَ شَدِيدُ الْعِقَابِ [الحشر:7] والآيات في هذا المعنى كثيرة.  فالواجب على كل عاقل، وعلى كل مسلم أن يوحد الله، وأن يلتزم بالإسلام، وأن يتبع الرسول ﷺ ويطيع أوامره، وينتهي عن نواهيه، فهذا هو سبيل الجنة، وهذا هو طريقها، ومن امتنع من هذا؛ فقد أبى، نسأل الله السلامة، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11072/معنى-حديث-كل-امتي-يدخلون-الجنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_465/46507.mp3","categories":["شروح الحديث"]},{"id":12863,"question":"المستمع: محمود أحمد دوسة من الزعفرانية بعث يقول: جاء في الحديث \"أن رسول الله ﷺ: نهى أن يتبع النظر إذا انقض الكوكب\" ما معنى انقض الكوكب؟","title":"حديث: (نهى أن يتبع النظر إذا انقض الكوكب)","answer":"الجواب:  انقضاضه: سقوطه في رأي الرائي، فإن الشهب يرمى بها الشياطين، ولا أعرف هذا الحديث الذي ذكره السائل، وهو النهي عن اتباع النظر، لا أعرف هذا، لكن معنى انقضاضه معناه: سقوطه؛ لأن الله -جل وعلا- يرمي الشياطين التي تسترق السمع، ترمى بالشهب، نعم، كما قال تعالى: وَلَقَدْ زَيَّنَّا السَّمَاءَ الدُّنْيَا بِمَصَابِيحَ وَجَعَلْنَاهَا رُجُومًا لِلشَّيَاطِينِ [الملك:5] نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11078/حديث-نهى-ان-يتبع-النظر-اذا-انقض-الكوكب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_465/46513.mp3","categories":["شروح الحديث"]},{"id":12944,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من جمهورية مصر العربية، وباعثها المستمع (س. س. ع) يسأل صاحب الرسالة ويقول: سمعت حديثًا نسب إلى رسول الله ﷺ وهو قوله ﷺ: ثلاث من الكفر بالله: شق الجيوب، وحلق الشعور، ولطم الخدود وضحوا لي هذا الحديث، وصحته أو ما في معناه؟ جزاكم الله خيرًا.","title":"الحكم على حديث: (ثلاث من الكفر. بالله)","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد.  فهذا اللفظ الذي ذكره السائل لا نعلم صحته عن النبي -عليه الصلاة والسلام- وإنما المحفوظ عنه -عليه الصلاة والسلام- أنه قال: ليس منا من ضرب الخدود، أو شق الجيوب، أو دعا بدعوى الجاهلية أخرجه البخاري ومسلم في الصحيحين، فهو حديث صحيح، لكن هذا لفظه: ليس منا من ضرب الخدود، أو شق الجيوب، أو دعا بدعوى الجاهلية. وهذا وعيد (ليس منا) هذا من باب الوعيد الشديد والتحذير، ومعنى (لطم الخدود) عند المصيبة إذا مات قريبه، مات أبوه أو أخوه أو زوجته أو نحو ذلك، لا يجوز له لطم الخدود، ولا شق الجيوب، بل يقول: إنا لله وإنا إليه راجعون، قدر الله وما شاء فعل، والحمد لله، يرضى ويسلم ويحتسب ويصبر، ولا يجوز له الجزع؛ فيشق الجيب، أو يضرب الخد، أو ينتف الشعر، كل هذا لا يجوز، هذا من الجزع ومن النياحة المحرمة، ليس منا من ضرب الخدود، أو شق الجيوب، أو دعا بدعوى الجاهلية هذا من عادة الجاهلية. ولو ضرب رأسه، أو صدره؛ فكذلك محرم، لكن من عادتهم ضرب الخدود، وشق الجيوب، فلو شق غير الجيب، أو ضرب غير الخد؛ فهو داخل في التحريم. وهكذا الدعاء بدعوى الجاهلية، والصياح والنياحة، أو يقول ما يقوله الجاهليون: واعضداه، واناصراه، وانكسار ظهراه، وما أشبه ذلك مما يقول الجاهلية. وفي الصحيحين أيضًا عن أبي موسى الأشعري  عن النبي ﷺ أنه قال: أنا بريء من الصالقة والحالقة والشاقة يعني: عند المصيبة أنا بريء يقوله النبي ﷺ: أنا بريء من الصالقة والحالقة والشاقة وقد فسر العلماء (الصالقة): بأنها التي ترفع صوتها عند المصيبة، تنوح ترفع صوتها، و(الحالقة): التي تحلق شعرها، أو تنتفه، أنا بريء من الصالقة والحالقة والشاقة (الشاقة): التي تشق ثوبها من الجيب، أو من غير الجيب، فهذا يدل على تحريم هذه الأعمال، وأنها من الجزع الذي حرمه الله. وإنما المشروع لمن أصيب أن يقول: إنا لله وإنا إليه راجعون، قدر الله وما شاء فعل، كما قال الله  في كتابه العظيم: وَلَنَبْلُوَنَّكُمْ بِشَيْءٍ مِنَ الْخَوْفِ وَالْجُوعِ وَنَقْصٍ مِنَ الأَمْوَالِ وَالأَنفُسِ وَالثَّمَرَاتِ وَبَشِّرِ الصَّابِرِينَ ۝ الَّذِينَ إِذَا أَصَابَتْهُمْ مُصِيبَةٌ قَالُوا إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ [البقرة:155-156] يعني: أنا ملك لله، نحن ملكه سبحانه عبيده. وَإِنَّا إِلَيْهِ رَاجِعُونَ [البقرة:156] يعني: المصير إليه، مرجع العباد إليه -جل وعلا- فيجازيهم بأعمالهم سبحانه يوم القيامة، ثم وعدهم بخير كثير فقال: أُوْلَئِكَ عَلَيْهِمْ صَلَوَاتٌ مِنْ رَبِّهِمْ وَرَحْمَةٌ وَأُوْلَئِكَ هُمُ الْمُهْتَدُونَ [البقرة:157] هذا جزاؤهم لما صبروا، وفي الصحيح يقول النبي ﷺ: احرص على ما ينفعك، واستعن بالله، ولا تعجز، وإن أصابك شيء فلا تقل: لو أني فعلت لكان كذا وكذا، ولكن قل: قدر الله وما شاء فعل فإن لو تفتح عمل الشيطان. فالمؤمن يأخذ بالأسباب، يطلب الرزق، يعالج عند المرض، يتجنب أسباب الخطر، فإذا وقعت المصيبة يقول: إنا لله وإنا إليه راجعون، قدر الله وما شاء فعل، ولا يقول: لو فعلت كان كذا وكذا لا، إنا لله وإنا إليه راجعون، قدر الله وما شاء فعل، يحمد ربه، ويثني عليه، يسأله حسن الخلف، ويأخذ بالأسباب التي تجبر المصيبة، والله المستعان. نعم. المقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11162/الحكم-على-حديث-ثلاث-من-الكفر-بالله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_470/47001.mp3","categories":["شروح الحديث","الحكم على الأحاديث"]},{"id":12965,"question":"هذا السائل عبدالله من الأحساء .. المبرز، يقول في  ما المقصود بالساعة الأولى والساعة الثانية والثالثة والرابعة والخامسة من يوم الجمعة، هل هي الساعة المتعارف عليها، أم زمن نسبي، ومتى تبدأ الساعة الأولى؟","title":"المقصود بالساعة في الحديث: (من أتى في الساعة الأولى...)","answer":"الجواب:  الأقرب -والله أعلم- أنها تبدأ بعد ارتفاع الشمس قيد رمح؛ لأن هذا يشرع للمؤمن أن يجلس في مصلاه يذكر الله، ويدعو حتى ترتفع، فالأقرب -والله أعلم- أنها تدخل من ارتفاع الشمس، ويكون النهار مجزأ، ست ساعات ما بين خروجه من مسجده، أو من بيته إلى دخول الخطيب ست ساعات، تختلف لطول النهار، وقصر النهار، الساعة الأولى فيها بدنة، والذاهب في الساعة الثانية كأنما قرب بقرة، وفي الثالثة كأنما قرب كبشًا أقرن، وفي الرابعة كأنما قرب دجاجة، وفي الخامسة كأنما قرب بيضة، يكون ما بين ارتفاع الشمس إلى غروبها اثنا عشر ساعة، اثنا عشر ساعة مجزأة حسب طول النهار وقصره، نعم.  المقدم: شكر الله لكم -يا سماحة الشيخ- وبارك الله فيكم، وفي علمكم، ونفع بكم المسلمين.","link":"https://binbaz.org.sa/fatwas/11182/المقصود-بالساعة-في-الحديث-من-اتى-في-الساعة-الاولى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_502/50221.mp3","categories":["صلاة الجمعة","شروح الحديث"]},{"id":12991,"question":"يقول هذا السائل في حديث الرسول ﷺ عن الإحسان: هو أن تعبد الله كأنك تراه يقول: أرجو أن توضحوا لنا كيف نعبد الله كأننا نراه مأجورين؟","title":"معنى قوله: (أن تعبد الله كأنك تراه)","answer":"الجواب:  هذا حديث جبرائيل لما سأل النبي ﷺ عن الإحسان قال له النبي ﷺ: أن تعبد الله كأنك تراه يعني: كأنك تشاهده، يعني: حتى تجتهد في العمل، حتى تخلص في العمل، حتى تؤدي العمل على خير وجه، وأكمل وجه، فإن المؤمن إذا عمل كأنه يشاهد الله، وأن الله  أمامه؛ فإنه يجتهد في العمل، ويحرص على إكماله وإتمامه، كأنه يشاهد الله، كأنه بين يدي الله يشاهد الله فإن لم تكن تراه فإنه يراك يعني: فاعلم أنه يراك، ويطلع عليك، ويشاهدك  فاجتهد في إصلاح العمل، وإحسان العمل، فأنت بين أمرين: إما أن تعمل كأنك ترى الله، وهذه أرفع، وأعلى، وهي درجة المشاهدة. والثاني: أن تعمل، تؤمن بأن الله يراك، وتعلم أن الله يراك، فأنت تعمل في مرأى من الله ومسمع؛ فتجتهد في أداء العمل على خير وجه؛ لأن الله يشاهدك، يعني: تستحضر أن الله يشاهدك، ويعلم مكانك : الَّذِي يَرَاكَ حِينَ تَقُومُ  ۝  وَتَقَلُّبَكَ فِي السَّاجِدِينَ [الشعراء:218-219] إِنَّنِي مَعَكُمَا أَسْمَعُ وَأَرَى [طه:46]  نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11208/معنى-قوله-ان-تعبد-الله-كانك-تراه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_504/50405.mp3","categories":["شروح الحديث"]},{"id":13033,"question":"إحدى الأخوات من جدة رمزت إلى اسمها بالحروف (ن. أ. د) بعثت برسالة، وضمنتها بعض الأسئلة.في أحد أسئلتها تقول: ما معنى قوله ﷺ: مائلات مميلات، رؤوسهن كأسنمة البخت؟","title":"شرح حديث: (صنفان من أمتي...)","answer":"الجواب:  هذا حديث صحيح رواه مسلم في الصحيح عن النبي ﷺ أنه قال: صنفان من أهل النار لم أرهما: رجال بأيديهم سياط يضربون بها الناس يعني ظلمًا ونساء كاسيات عاريات، مائلات مميلات رؤوسهن كأسنمة البخت المائلة لا يدخلن الجنة ولا يجدن ريحها، وإن ريحها ليوجد من مسيرة كذا وكذا.  وقد فسر العلماء هذا الحديث: بأنهن كاسيات من نعم الله، عاريات من شكرها، وقال جماعة في تفسير الحديث: كاسيات بالثياب الرقيقة والقصيرة عاريات لأن هذه الملابس لا تستر، فهن في حكم العاريات، وهذا منكر عظيم، يجب على المرأة أن تتستر الستر الكامل عن خادمها، وعن زوج أختها، وعن إخوان زوجها، وعن غيرهم من الأجانب، يجب أن يكون الستر كاملًا في جميع بدنها ورأسها ووجهها عن غير محارمها، وإذا تركت بعض ذلك؛ صارت في حكم الكاسيات العاريات. وأما قوله ﷺ: مائلات مميلات فمعناه عند أهل العلم: (مائلات) عن الصواب، عن الحق، عن العفة والاستقامة إلى الفساد والفحش (مميلات) لغيرهن إلى ذلك، فهن مائلات عن العفة والاستقامة إلى الفساد والزنا والفواحش، وغير الحق، مميلات لغيرهن من النساء، يعني: يدعين إلى الفاحشة، ويتوسطن في الفاحشة. أما من فسر ذلك بالمشطة المائلة؛ فهذا غلط، ليس بشيء، الصواب: أن المراد مائلات عن الحق، عن العفاف والاستقامة إلى الفساد، وغير الاستقامة، مميلات لغيرهن من النساء عن الاستقامة والعفة إلى الفساد، نسأل الله العافية، نعم. أما (رؤوسهن كأسنمة البخت المائلة) هذه علامة لهن، من علاماتهن: تضخيم الرؤوس، يجمعن عليها أشياء تضخمها، وتكبرها، وكأنها علامة لهن في بعض البلدان اللاتي تتعاطى هذه الأعمال السيئة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11250/شرح-حديث-صنفان-من-امتي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_472/47213.mp3","categories":["شروح الحديث"]},{"id":13047,"question":"تقول: ما معنى: اللهم اهدنا فيمن هديت، وعافنا فيمن عافيت؟","title":"معنى (اللهم اهدنا فيمن هديت)","answer":"الجواب:  معناه: أن الله يمن عليك بالهداية ضمن من هدى، والعافية ضمن من عافى، هذا معناه: اللهم اهدنا فيمن هديت، وعافنا فيمن عافيت، وتولنا فيمن توليت يعني: اللهم اهدنا في جملة المهديين، وعافنا في جملة المعافين، وتولنا في جملة المتولين، يعني: اعف عنا معهم .. اجعلنا معهم مهتديين معافيين، نعم هذا المراد. المقدم: شكر الله لكم.","link":"https://binbaz.org.sa/fatwas/11264/معنى-اللهم-اهدنا-فيمن-هديت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_505/50507.mp3","categories":["شروح الحديث","الحكم على الأحاديث","الأدعية والأذكار"]},{"id":13071,"question":"السائلة في هذا السؤال تقول: ما روي في حديث: \"بأن في الجنة باب يقال له: الريان، لا يدخله إلا الصائمون\" هل معنى ذلك: هل الصائمون يقصد بهم الذين يصومون شهر رمضان فقط، أم الذين يصومون السنن مثل الإثنين والخميس وأيام البيض؟ أفيدونا مأجورين.","title":"ما معنى: «في الجنة باب يقال له: الريان»؟","answer":"الجواب:  المراد بذلك: الصائمون صوم الفريضة، الذين يحافظون على الصوم صوم الفريضة، رمضان، وهكذا ما أوجب الله عليهم من صوم الكفارات، والنذور، هؤلاء لهم باب؛ باب الريان، يدخلون معه، فإذا دخلوا؛ أغلق. وإذا كانوا عندهم أعمال أخرى يدعون من أبواب كثيرة، لكن يدخلون من هذا الباب، باب الصيام، والمؤمن الذي يقيم الصلاة، ويؤدي الزكاة، ويصوم رمضان، ويتقي الله؛ يدعى من الأبواب كلها، لكن هذا الباب ما يدخل معه إلا الصائمون الذين حافظوا على أداء الصوم الواجب، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11287/ما-معنى-في-الجنة-باب-يقال-له-الريان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_507/50703.mp3","categories":["شروح الحديث"]},{"id":13096,"question":"ننتقل بعد ذلك إلى رسالة السائلة (خ. أ) من المدينة تقول: قال رسول الله ﷺ: إذا مات الميت يتبعه ثلاث: أهله وماله وعمله، فيرجع اثنان: المال والأهل، ويبقى واحد: وهو العمل سؤالي عن المال كيف يذهب مع الميت، وكيف يعود، جزاكم الله خيرًا؟","title":"ما معنى: «إذا مات الميت يتبعه ثلاثة»؟","answer":"الجواب:  يخبر النبي ﷺ أن الميت يتبعه ثلاثة: أهله وماله وعمله، فيرجع اثنان، ويبقى واحد، يعني: هذا وصف أغلبي، هذا وصف أغلبي يتبعه أهله مثل: أخوه وأبوه وأولاده يشيعونه للصلاة والدفن، وماله كالأدوات التي يحفر بها: القبر والماء الذي يرش به القبر، وما أشبه ذلك مما يحتاج إليه عند الدفن، ثم يرجعون، يرجع الأقارب والأدوات المالية ترجع، ويبقى معه عمله في قبره، لا يبقى معه إلا عمله من خير وشر. أما المشيعون من أهل أو أصدقاء يرجعون، وهكذا المال الذي يتبعه للحاجة إليه، كالأدوات التي يحفر بها، والأواني التي يخرج بها التراب، وما أشبه ذلك من الأشياء التي يحتاج إليها عند الحفر، هذه ترجع، يأتون بها للحفر، ثم ترجع الآلات، وغيرها إلى البيت. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11312/ما-معنى-اذا-مات-الميت-يتبعه-ثلاثة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_508/50806.mp3","categories":["شروح الحديث"]},{"id":13269,"question":"سماحة الشيخ! بعد ذلك ننتقل إلى سؤال آخر يقول فيه السائل: ما هي محقرات الذنوب، مع ضرب الأمثلة بذلك مأجورين؟","title":"محقرات الذنوب","answer":"الجواب:  محقرات الذنوب: التي يحتقرها الإنسان يراها صغيرة، والنبي  قال: إياكم ومحقرات الذنوب؛ فإنها تجتمع على العبد حتى تهلكه وفي اللفظ الآخر: فإن لها من الله طالبًا وضرب المثل بالقوم ينزلون منزلًا؛ ليصنعوا طعامهم، فيأتي هذا بعود، وهذا بعود، وهذا ببعرة، فيوقدوا نارًا، ويصنعوا الطعام على هذه الأشياء الحقيرة، ومحقرات الذنوب هي التي يراها صغيرة، (يحتقرها) يعني: يراها ذنوبًا صغيرة. قد يرى بعض الناس الغيبة من الصغائر، قد يرى بعض الناس الكلام على بعض الناس بالشدة، والكلام السيئ أنه من الصغائر يعني: بحيث لا يتأدب معه، بل يتكلم عليه بكلام قبيح، قد يرى بعض الناس أن كونه يعصي والده، أو لا يصل رحمه، قد يراها محقرة، قد يعتقد أشياء حقيرة صغيرة، وهي ليست كذلك، قد تكون كبيرة وهو ما يعلم، وقد تجتمع عليه، هي صغيرة تجتمع حتى تهلكه لكثرتها، وتساهله بها. فالمقصود: أن المحقرات التي يراها الإنسان حقيرة يعني: يتساهل بها؛ يعني يراها ما هي من الكبائر، ويراها أن الله سوف يعفو عنه فيها؛ لأنها باعتقاده ليست -يعني- لها شدة، وليست تتضمن ظلمًا للناس، أو مشقة عليهم، هذا معنى المحقرات. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11552/محقرات-الذنوب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_509/50908.mp3","categories":["شروح الحديث"]},{"id":13274,"question":"السائل يقول في سؤال له أيضًا: من الكبائر تغيير منار الأرض، ما معنى ذلك يا سماحة الشيخ؟","title":"معنى تغيير منار الأرض","answer":"الجواب: الرسول ﷺ لعن من غير منار الأرض لعن من ذبح لغير الله، ولعن من لعن والديه، ولعن من آوى محدثًا، ولعن من غير منار الأرض يعني: مراسيم الأرض، كون الإنسان بينه وبين زيد مراسيم تفصل أرضه من أرضه، فالذي يغيرها ملعون، نسأل الله.. لأنه يفضي إلى النزاع والخصومات، ويظلم هذا لهذا -نسأل الله العافية- سواء كان من الشركاء، أو من غيرهم، فهو ملعون ظالم؛ لأن تغييرها يفضي إلى النزاع والخصومات، وإعطاء الإنسان غير حقه، نسأل الله العافية. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11558/معنى-تغيير-منار-الارض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_509/50911.mp3","categories":["شروح الحديث"]},{"id":13279,"question":"بعد ذلك ننتقل إلى رسالة بعث بها السائل (م. أ. ي) مصري، ومقيم بالرياض يقول: قال رسول الله ﷺ: العمرة إلى العمرة كفارة لما بينهن فإذا كنت قد أديت العمرة في رمضان إلى رمضان الذي يليه، فهل هذه تكون كفارة لما بينها، أم أن الكفارة لما بين العمرتين لمدة ثلاثة شهور فقط؟ نرجو منكم التوجيه.","title":"معنى قوله (العمرة إلى العمرة كفارة لما بينهن)","answer":"الجواب:  الحديث عام، يقول ﷺ: العمرة إلى العمرة؛ كفارة لما بينهما، والحج المبرور ليس له جزاء إلا الجنة سواء كانت العمرة في شهر، أو في شهرين، أو في عام، أو عامين، هذا وعد، هذا من باب الفضائل، يعني: من باب التحريض والترغيب في العمرة، ولكن ما لم يصب الكبيرة. أما إذا تعاطى كبائر الذنوب ما تكون كفارة؛ لقوله ﷺ في الحديث الآخر: الصلوات الخمس، والجمعة إلى الجمعة، ورمضان إلى رمضان كفارات لما بينهن، ما لم تغش الكبائر والصلاة أعظم من العمرة والحج، فإذا كانت ما تكون كفارة مع غشيان الكبائر؛ فمن باب أولى العمرة والحج، ولهذا في الحديث الصحيح: من حج فلم يرفث، ولم يفسق؛ وجبت له الجنة والرفث الجماع، وهو محرم في الإحرام، وهكذا دواعيه، والفسق المعاصي، فشرط في حصول المغفرة، ودخول الجنة للحاج ألا يرفث، وألا يفسق، وفي اللفظ الآخر: الحج المبرور ليس له جزاء إلا الجنة المبرور: الذي ليس فيه رفث، ولا فسوق. فالواجب على المؤمن الحذر من معاصي الله كلها، فإن صومه وحجه وسائر أعماله الطيبة معلقة على ترك الكبائر، كما قال -جل وعلا-: إِنْ تَجْتَنِبُوا كَبَائِرَ مَا تُنْهَوْنَ عَنْهُ نُكَفِّرْ عَنْكُمْ سَيِّئَاتِكُمْ [النساء:31] فعلق التكفير باجتناب الكبائر. فالواجب على كل مؤمن ومؤمنة الحذر من الكبائر، وهي المعاصي التي جاء فيها وعيد، أو غضب، أو لعنة، أو حد في الدنيا، كالزنا، والسرقة، والخمر، والعقوق للوالدين وقطيعة الرحم، وأكل الربا، وأكل أموال اليتامى إلى غير ذلك. والغيبة والنميمة كلها كبائر، فإذا تعاطاها العبد؛ منعت تأثير العمرة والحج والصلاة في التكفير، كانت -يعني- عائقًا دون التكفير، فالواجب الحذر، أما مع ترك الكبائر؛ فإن هذه الطاعات تكون كفارات للصغائر، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11564/معنى-قوله-العمرة-الى-العمرة-كفارة-لما-بينهن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_514/51411.mp3","categories":["شروح الحديث"]},{"id":13283,"question":"يقول هذا السائل: قال رسول الله ﷺ: إن العمرة في رمضان تعدل حجة معي ثم قال في حديث آخر: الحج هو عرفة فما هو الفرق بين الأول، والثاني مأجورين؟","title":"الفرق بين حديث: «عمرة في رمضان» و «الحج عرفة»","answer":"الجواب:  فضل العمرة في رمضان، هذا معروف، العمرة في رمضان تعدل حجة، وفي رواية: حجة معي هذا فيه فضل عظيم، الاعتمار في رمضان، وأما معنى الحج عرفة يعني: أن من لمن يقف بعرفة ما له حج، يعني: معظم الحج عرفة، فالذي يحج، ولكن لا يقف بعرفة ما له حج، لابد من الوقوف بعرفة، يعني: معظم الحج وركنه الأعظم عرفة. فلو أنه رمى الجمار، وبقي في منى، وأتى مزدلفة؛ ما له حج إلا إذا وقف بعرفة يوم عرفة، أو ليلة النحر، ماله حج إلا بعرفة، فلو أنه مثلًا ترك الوقوف بعرفة ليلًا ونهارًا؛ فلا حج له. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11568/الفرق-بين-حديث-عمرة-في-رمضان-و-الحج-عرفة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_514/51412.mp3","categories":["شروح الحديث"]},{"id":13287,"question":"بعد ذلك ننتقل إلى سؤال لأحد الإخوة يقول: من أكل سبع تمرات في اليوم؛ منع من السحر ما صحة هذا الكلام؟","title":"ما صحة حديث: «من تصبح بسبع تمرات من عجوة المدينة»؟","answer":"الجواب:  هذا ثبت عن النبي ﷺ أنه قال: من تصبح بسبع تمرات من عجوة المدينة وفي اللفظ الآخر: مما بين لابتيها -يعني: المدينة- لم يضره سحر، ولا سم هذا ثابت في الصحيح، حديث صحيح من تصبح بسبع تمرات من عجوة المدينة وفي لفظ: مما بين لابتيها رواه مسلم، وأصله في الصحيحين: لم يضره سحر، ولا سم هذا ثابت، نعم.","link":"https://binbaz.org.sa/fatwas/11572/ما-صحة-حديث-من-تصبح-بسبع-تمرات-من-عجوة-المدينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_509/50917.mp3","categories":["شروح الحديث"]},{"id":13301,"question":"له فقرة أخرى يقول: تعوذوا بالله من جهد البلاء، ودرك الشقاء، ما معنى ذلك أيضًا؟","title":"معنى حديث: (استعيذوا بالله من جهد البلاء ...)","answer":"الجواب: على ظاهره، النبي ﷺ قال: استعيذوا بالله من جهد البلاء، ومن درك الشقاء، ومن سوء القضاء، ومن شماتة الأعداء يستعيذ بالله من هذا؛ لأن لا يبتلى بشيء يضره، بلاء يضره، درك الشقاء يدركه شيء يوقعه في الشقاء، في المعاصي، والشرك، نسأل الله العافية. الإنسان يتحرى أسباب النجاة، ويستعيذ بالله من جهد البلاء، ومن درك الشقاء، ومن شماتة الأعداء، ومن سوء القضاء، هكذا المؤمن يتحرى، ويسأل ربه العافية، فإن الأعداء يشمتون به إذا وقع فيما يضره، ولكنه يتحرى العافية من جهد البلاء، أو ما يسوؤه من البلايا، والمحن التي تنزل بالناس. ومن درك الشقاء: كونه يدركه شيء يشقيه، ويوقعه في المعاصي والشرور، أو في الشرك الأكبر، نسأل الله العافية. وسوء القضاء: كذلك كونه يقع في المعاصي، وأن يبتلى بما حرم الله عليه. وشماتة الأعداء: مثلما تقدم، كونه يقع في شيء يشمت به الأعداء، فالمؤمن يتحرى العافية من هذه الأشياء، ويستعيذ بالله من جهد البلاء، ومن درك الشقاء، ومن سوء القضاء، ومن شماتة الأعداء. يعني يحذر كل هذه الأسباب، فلا يتعرض للبلاء الذي يوقعه في المعاصي والشرور، ولا يتعرض لأشياء تشمت به الأعداء، ولا يتعرض أيضًا لشيء مما حرم الله عليه، فإن هذا يكون من سوء القضاء الذي ابتلي به، فإن الله يقضي الخير والشر -جل وعلا- فالمعاصي بقدر والطاعات بقدر، يسأل ربه أن الله يقيه شر القضاء الذي فيه المعاصي والشرور والشركيات، ونحو ذلك، نسأل الله العافية. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11586/معنى-حديث-استعيذوا-بالله-من-جهد-البلاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_522/52205.mp3","categories":["شروح الحديث"]},{"id":13305,"question":"هذا السائل يقول في هذا  سماحة الشيخ! سؤالي ما معنى بأن الصيام والقرآن يشفعان لصاحبهما؟ هل معنى ذلك هو صيام رمضان، أم أيام النوافل، وكذلك القرآن يشفع، هل هو كثرة القراءة المستمرة؟","title":"معنى أن القرآن والصيام يشفعان","answer":"الجواب:  القرآن والصيام كلاهما يشفعان، القرآن يشفع لمن قرأه، وعمل به، كما قال ﷺ: والقرآن حجة لك، أو عليك القرآن من عمل به، واستقام عليه؛ شفع له يوم القيامة في إدخاله الجنة، والنجاة من النار.  وهكذا الصيام لمن أتقنه، وصان صيامه؛ كان شافعًا له، من صان الصيام، وأتقنه؛ كان شافعًا له، فينبغي للمؤمن في حال صيامه أن يصون صيامه عن اللغو والرفث، كما قال ﷺ: الصيام جنة، فإذا كان يوم صوم أحدكم؛ فلا يرفث، ولا يفسق، فإن سابه أحد، أو قاتله؛ فليقل: إني صائم ويقول الرب -جل وعلا-: كل عمل ابن آدم له، الحسنة بعشر أمثالها، إلا الصيام فإنه لي، وأنا أجزي به، ترك شهوته وطعامه وشرابه من أجلي، للصائم فرحتان: فرحة عند فطره، وفرحة عند لقاء ربه. فالمقصود: أن الصيام يشفع لمن أتقنه وصانه، والقرآن كذلك يشفع لمن أحل حلاله، وحرم حرامه، واستقام على تعاليمه. نعم. المقدم: شكر الله لكم يا سماحة الشيخ، وبارك الله فيكم، وفي علمكم، ونفع بكم المسلمين.","link":"https://binbaz.org.sa/fatwas/11591/معنى-ان-القران-والصيام-يشفعان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_521/52113.mp3","categories":["شروح الحديث"]},{"id":13329,"question":"السائل عبدالرحمن من المدينة النبوية يقول: سماحة الشيخ! أنا من سكان المدينة النبوية، والحمد لله على هذه النعمة، إذ أديت صلاة الفريضة في المسجد النبوي، فسؤالي عن الراتبة البعدية، فأنا في حيرة بين الحديثين: الأول: صلاة في مسجدي هذا خير من ألف صلاة الحديث، والآخر: صلاة الرجل في بيته أفضل إلا المكتوبة وجهونا سماحة الشيخ.","title":"هل فضل النافلة في البيت يشمل الحرمين؟","answer":"الجواب: السنة للمؤمن أن يصلي الراتبة في بيته، هذا هو الأفضل؛ لقوله ﷺ في الحديث الصحيح: أفضل صلاة المرء في بيته إلا المكتوبة هكذا علم أصحابه في المدينة في مسجده الشريف، ولك في صلاتك في البيت أفضل من صلاتك في المسجد، لك أجر عظيم؛ لأنك امتثلت أمر الرسول ﷺ وأطعت توجيهه -عليه الصلاة والسلام- فإذا صليت الفريضة في المسجد؛ فالرواتب تكون في البيت أفضل، إذا كانت في المسجد بألف صلاة، ففي البيت أكثر؛ لأنك أطعت الرسول ﷺ وامتثلت السنة. وهكذا في مكة، هكذا في كل مكان، ويلحق بالمكتوبة ما شرعت له الجماعة، مثل صلاة التراويح في المسجد أفضل، مثل صلاة الكسوف، صلاة الجنازة، في المساجد، وفي المصلى أفضل من البيت. نعم. المقدم: شكر الله لكم يا سماحة الشيخ، وبارك الله فيكم، وفي علمكم، ونفع بكم المسلمين.","link":"https://binbaz.org.sa/fatwas/11615/هل-فضل-النافلة-في-البيت-يشمل-الحرمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_541/54112.mp3","categories":["شروح الحديث","صلاة التطوع"]},{"id":13332,"question":"هذا السائل عبدالرحمن من المدينة النبوية استعرضنا سؤالًا له، بقي له سؤالان، يقول: ثبت عن الرسول ﷺ أنه قال: من أتى مسجد قباء، وصلى فيه؛ كان كأجر عمرة والسؤال سماحة الشيخ: هل يشترط لهذه الصلاة الخروج، خصوصًا من البيت بنية الصلاة في قباء للحصول على أجر العمرة؟ أم أنه يأتي بأي صلاة تجزي؟ فمثلًا: إذا صليت الجمعة في قباء، فهل يكون لي أجر عمرة بمشيئة الله؟","title":"شرط الحصول على أجر العمرة للمصلي في قباء","answer":"الجواب:\n\nثبت عن النبي ﷺ: \"أنه كان يزور قباء كل سبت، راكبًا وماشيًا\" -عليه الصلاة والسلام- وقال -عليه الصلاة والسلام-: من تطهر في بيته، ثم أتى مسجد قباء، فصلى فيه ركعتين؛ كان كعمرة هذا الفضل ذكره لمن يتطهر من بيته، ويخرج قاصدًا للصلاة في قباء؛ يحصل له هذا الأجر.\n\nأما من صلى فيه كالعادة بغير قصد من بيته؛ فله أجر، وله خير عظيم، لكن لا يتوفر فيه الشرط المذكور، إنما يحصل هذا لمن تطهر في بيته، وخرج من بيته قاصدًا للصلاة في مسجد قباء، كما كان النبي يفعل، عليه الصلاة والسلام.\n\nأما الصلاة فيه من غير قصد من البيت، بل مر، وصلى به، أو كان من جيرانه، وصلى فيه الفروض؛ يرجى له خير عظيم؛ لكن لا يتوفر فيه ما قاله النبي ﷺ إلا بالشروط التي قالها: من تطهر في بيته، ثم أتى مسجد قباء، وصلى فيه يعني: يخرج من بيته قاصدًا، فإذا خرج من بيته قاصدًا يوم الجمعة، أو غير الجمعة، وصلى فيه؛ يحصل له هذا الأجر، والحمد لله. نعم.\n\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11618/شرط-الحصول-على-اجر-العمرة-للمصلي-في-قباء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_542/54202.mp3","categories":["شروح الحديث","فضائل الأزمنة والأمكنة","فضائل الأعمال"]},{"id":13337,"question":"المستمع محمود القطروتي من الجماهيرية الليبية يقول: أسمع كثيرًا من الناس في دعائهم يقولون: اللهم إنا نعوذ بك من غلبة الدين، وقهر الرجال فما هو المقصود من قهر الرجال؟","title":"المقصود بقهر الرجال","answer":"الجواب: هذا دعاء ثابت عن النبي ﷺ كان يدعو بهذا يقول: اللهم إني أعوذ بك من الهم والحزن، والعجز والكسل، والجبن والبخل، وأعوذ بك من غلبة الدين، وقهر الرجال ثابت عنه ﷺ وهذا من دعواته العظيمة، التي رواها مسلم، وغيره. فغلبة الدين معروف، يعني: ثقل الدين وعجزه عن تسديده. وغلبة الرجال.. أن يغلبوه... أن يقهروه حتى يقتلوه، أو يأخذوا ماله، أو يهينوه، ويضربوه إلى غير ذلك، فهو يستعيذ بالله من غلبة الدين، وقهر الرجال، فالدين إذا عجز عنه؛ يشغل فكره كثيرًا، ويهمه كثيرًا، وربما أتعبه أهله أيضًا أهل الدين بالمطالبات والخصومات، وهم لا يعرفون عجزه، وحقيقة أمره.  وقهر الرجال -لاشك- أنه مصيبة عظمى، سواء قهروه على قتله، أو قهروه على أخذ ماله، أو بعض ماله، أو قهروه على ضربه، أو قهروه على غير ذلك مما يضره، فكله شر، وكله بلاء عظيم، ومصيبة عظيمة، فلهذا شرع الله الاستعاذة من ذلك، نعم.","link":"https://binbaz.org.sa/fatwas/11623/المقصود-بقهر-الرجال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_476/47612.mp3","categories":["شروح الحديث","الحكم على الأحاديث"]},{"id":13366,"question":"يقول هذا السائل أيمن صلاح أحمد من جمهورية مصر العربية: أسأل عن معنى هذا الحديث، وعن مدى صحته: \"ثلاثة لا ينظر الله إليهم يوم القيامة، ولا يكلمهم، وهم في النار خالدون\" وذكر منهم مسبل إزاره؟","title":"ما صحة حديث «ثلاثة لا ينظر الله إليهم...»","answer":"الجواب: في حديث رواه مسلم في الصحيح: ثلاثة لا يكلمهم الله، ولا ينظر إليهم يوم القيامة، ولا يزكيهم، ولهم عذاب أليم: المسبل إزاره، والمنان فيما أعطى، والمنفق سلعته بالحلف الكاذب هذا من باب الوعيد عند أهل السنة والجماعة، ليسوا كفارًا، بل من باب الوعيد، والتحذير، والترهيب، المسبل يدل على أنه كبيرة من الكبائر، والمنان في العطية الله -جل وعلا- قال: لا تُبْطِلُوا صَدَقَاتِكُمْ بِالْمَنِّ وَالأَذَى [البقرة:264].  والمنفق سلعته بالحلف الكاذب الذي يقول: والله إنها علي بكذا، والله إني شريتها بكذا، والله إنها ...... بكذا، وهو يكذب حتى ينفقها، يمشيها، ويأكل أموال الناس بالباطل، هذا وعيد شديد، يدل على أن هذا من الكبائر، من كبائر الذنوب. مثل الحديث الآخر: ثلاث لا يكلمهم الله، ولا يزكيهم، ولهم عذاب أليم: شيخ زانٍ -شيخ شايب- وملك كذاب، وعائل مستكبر هذا يدل على أن الزنا مع الشيخوخة، مع كبر السن يكون أعظم من الزنا، في الشباب أكبر إثمًا. وهكذا الملك الكذاب إثمه أكثر؛ لأنه قد أعطاه الله الملك، وأغناه الله عن الكذب، فما الحاجة للكذب وعائل مستكبر مع فقره يستكبر، الغني قد يحمله الغنى، لكن هذا مع كونه فقيرًا يستكبر، هذا يدل على أن الكبر طبيعة له، وسجية له -نعوذ بالله- فاشتد بهذا إثمه -نسأل الله العافية- لا حول ولا قوة إلا بالله. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11653/ما-صحة-حديث-ثلاثة-لا-ينظر-الله-اليهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_524/52408.mp3","categories":["شروح الحديث","الحكم على الأحاديث"]},{"id":13377,"question":"بعد ذلك ننتقل إلى رسالة السائل (فهد . م) من الرياض يقول في هذا الحديث: سماحة الشيخ! حديث الرسول ﷺ الذي رواه أبو هريرة  وهو قول الرسول ﷺ: لو يعلم الناس ما في النداء، والصف الأول، ثم لم يجدوا إلا أن يستهموا عليه لاستهموا عليه ما المقصود بالنداء -جزاكم الله خيرًا- الوارد في الحديث؟","title":"«لو يعلم الناس ما في النداء» ما معنى النداء؟","answer":"الجواب: النداء: هو الأذان، يعني: لو يعلمون ما فيه من الفضل؛ لاستهموا عليه؛ لاقترعوا، يعني: كل واحد يقول: أنا الذي أؤذن، دعوني أؤذن؛ لما فيه من الفضل العظيم؛ لأنه ينادي على الناس بتوحيد الله، وتعظيمه، وتكبيره، ويدعو إلى الصلاة، ويقول النبي ﷺ: أطول الناس أعناقًا يوم القيامة المؤذنون فهم يشهدون لله بالوحدانية، ولنبيه بالرسالة، ويدعون الناس إلى الصلاة والفلاح، فهو ذكر عظيم على رؤوس الأشهاد. ويقول النبي ﷺ: لا يسمع مدى صوت المؤذن شجر، ولا حجر، ولا شيء إلا شهد له يوم القيامة فضل عظيم، فلو أن الناس ... هذا الفضل، واستحضروه؛ لاستهموا لاقترعوا، يعني: كل واحد يقول: أنا الذي أؤذن حتى يحتاجوا للقرعة حتى يؤذن من خرج له القرعة، من شدة الرغبة، لكن أكثر الخلق ما عنده بصيرة، ولا يحرص على الفضائل، لكن لو أن الناس عرفوا هذا الفضل، وتأكدوه، وصارت عندهم الرغبة في الخير؛ لاستهموا على ذلك. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ، ألا يدخل في ذلك -سماحة الشيخ- إجابة النداء وهو الذهاب إلى المصلى والتبكير، ألا يدخل في الأفضلية أيضًا؟ الشيخ: هذا من باب المسارعة إلى الصلاة، هذا من باب المسارعة إلى الصلاة والمسابقة إليها، مثلما في قوله -جل وعلا-: سَابِقُوا إِلَى مَغْفِرَةٍ مِنْ رَبِّكُمْ [الحديد:21] .. وَسَارِعُوا [آل عمران:133] .. فَاسْتَبِقُوا الْخَيْرَاتِ [المائدة:48] هذا من باب المسارعة إلى الخيرات، والمسابقة إلى..، لكن لو يعلم الناس ما في النداء، والصف الأول هذا مقصوده في النداء يسعى إلى النداء. أما الصف الأول معناه المسارعة إلى الصلاة؛ حتى يكون في الصف الأول، يعني: يبكر حتى يفوز بالصف الأول، أما إذا تأخر قد لا يحصل له إلا الصف الثاني، أو الثالث، أو .. إذا كان المسجد كبيرًا، فيه ناس كثير، لكن ما يتعلق بالأذان معناه أنهم يتنافسون فيه حتى كل واحد يقول: دعوني أنا الذي أؤذن، وقد يحتاجون إلى القرعة. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11667/لو-يعلم-الناس-ما-في-النداء-ما-معنى-النداء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_515/51507.mp3","categories":["الأذان والإقامة","شروح الحديث"]},{"id":13429,"question":"أبو عبدالله له هذا السؤال، له مجموعة الحقيقة من الأسئلة يقول في هذا  في الحديث الذي فيه بأن الرسول ﷺ سمع خشخشة بلال  أمامه في الجنة، فهل يفهم من هذا سماحة الشيخ أن بلالًا سبق بالدخول إلى الجنة؟ وهل كان الرسول ﷺ يصلي ركعتي الوضوء؟","title":"توضيح حديث «سمعت خشخشة أمامي فإذا بلال»","answer":"الجواب: هذه القصة تدل على واقعة واحدة وقعت عند دخوله الجنة، واقعة واحدة، لا يلزم منها أن يكون بلال مقدمًا عليه، فإن منزلة الرسول في أعلى الجنة -عليه الصلاة والسلام- لا يشابهه أحد، ولا يقاربه أحد، عليه الصلاة والسلام. لكن هذا يدل على فضل ركعتي الوضوء، وأنها من أسباب دخول الجنة، فالسنة المحافظة عليها، إذا توضأ الإنسان؛ يصلي ركعتين، يقول النبي ﷺ: من توضأ، فأحسن الوضوء، ثم صلى ركعتين لا يحدث فيهما نفسه؛ غفر له ما تقدم من ذنبه فيهما فضل عظيم. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11725/توضيح-حديث-سمعت-خشخشة-امامي-فاذا-بلال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_527/52706.mp3","categories":["شروح الحديث"]},{"id":13433,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول: حيدر الزبير حسن عثمان -ومقيم في رفحا- يقول: اشرحوا لنا هذا الحديث -جزاكم الله خيرًا- عن جندب بن عبدالله  قال: قال رسول الله ﷺ: من صلى صلاة الصبح؛ فهو في ذمة الله، فلا يطلبنكم الله من ذمته بشيء، فإنه من يطلبه من ذمته بشيء؛ يدركه، ثم يكبه في نار جهنم رواه مسلم، وما معنى يطلبه من ذمته؟","title":"معنى حديث «من صلى الصبح فهو في ذمة الله...»","answer":"الجواب: المعنى: أن من صلى الفجر؛ فهو في ذمة الله.. يعني: فهو آمن، لا يجوز الاعتداء عليه، فمن اعتدى عليه؛ فهو معرض لغضب الله، ولدخول النار -نسأل الله العافية-. والمقصود: من هذا أن صلاة الفجر لها شأن عظيم، فمن حافظ عليها؛ حافظ على ما سواها؛ لأنها أثقل الصلاة على المنافقين مع صلاة العشاء، فالمحافظة عليها، والعناية بها دليل على قوة الإيمان، فصاحبها في ذمة الله، وفي أمان الله وعهد الله، فلا يجوز لأحد أن يتعدى عليه، ومن تعدى عليه؛ فالله -جل وعلا- سوف يطلبه بهذه الذمة التي خانها، ومن طلبه الله؛ أدركه الله، وأكبه في النار، نسأل الله العافية. والمقصود من هذا: التحذير من التعدي على المصلين، والتعدي على المؤمنين، ولا سيما من حافظ على صلاة الفجر، فإنه دليل على قوة إيمانه، وعلى محافظته على بقية الصلوات، فلا يجوز التعدي عليه بأي نوع من العدوان، نسأل الله السلامة نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11728/معنى-حديث-من-صلى-الصبح-فهو-في-ذمة-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_3la_aldarb%2015884.mp3","categories":["شروح الحديث"]},{"id":13467,"question":"هل حديث: السبعة الذين يظلهم الله في ظله يوم لا ظل إلا ظله خاص بالرجال، أم هو أيضًا خاص بالنساء يدخلن فيه؟","title":"هل حديث (سبعة يظلهم الله..) يشمل النساء؟","answer":"الجواب: الحديث عام للرجال والنساء، يقول النبي ﷺ: سبعة يظلهم الله في ظله، يوم لا ظل إلا ظله: إمام عادل، وشاب نشأ في عبادة الله وهكذا المرأة إذا نشأت في عبادة الله ورجل قلبه معلق بالمساجد وهكذا المرأة المعلق قلبها بالصلاة. ورجلان تحابا في الله، اجتمعا عليه، وتفرقا عليه وهكذا امرأتان تحابتا في الله، أو رجل وامرأة تحابا في الله، داخلون في هذا الحديث.  ورجل دعته امرأة ذات منصب وجمال، فقال: إني أخاف الله هذا الخامس، وهكذا المرأة إذا دعاها ذو منصب وجمال فقالت: إني أخاف الله، فهي من السبعة الذين يظلهم الله في ظله، يوم لا ظل إلا ظله. السادس: رجل تصدق بصدقة، فأخفاها حتى لا تعلم شماله ما تنفق يمينه وهكذا المرأة إذا تصدقت بصدقة، فأخفتها حتى لا تعلم شمالها ما تنفق يمينها هي من السبعة سواء بسواء. السابع: رجل ذكر الله خاليًا يعني: ما عنده أحد  ففاضت عيناه من خشية الله يعني: بكى من خشية الله، ما عنده أحد، عن إخلاص، وعن إيمان، وعن خوف من الله -جل وعلا- هو من السبعة، وهكذا المرأة إذا بكت من خشية خالية، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11770/هل-حديث-سبعة-يظلهم-الله-يشمل-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_517/51715.mp3","categories":["شروح الحديث"]},{"id":13468,"question":"في ثالث أسئلته يقول السائل إبراهيم، ما حكم استبدال الذهب القديم بجديد، وما معنى: الذهب بالذهب، والفضة بالفضة، مثلًا بمثل، يدًا بيد؟","title":"معنى حديث: «الذهب بالذهب والفضة بالفضة...»","answer":"الجواب: معنى ذلك: أنه مثقال بمثقال، مثقالين بمثقالين، يدًا بيد يعني: لا يزيد هذا على هذا، الذهب بالذهب سواء، جديد أو قديم، لا بد أن يستويان وزنًا، يقول النبي ﷺ: الذهب بالذهب وزنًا بوزن، مثلًا بمثل، سواءً بسواء، يدًا بيد ولا فرق بين كونه جديدًا أو قديمًا، أو كون هذا أطيب وهذا أطيب، ما دام جنس الذهب لابد أن يكونا متساويين في الوزن يدًا بيد، يقبض في الحال. فإذا أراد أن يبيعه بشيء آخر يبيع الرديء بشيء آخر، بفضة، أو طعام لا بأس، أما بالذهب لا، لابد يدًا بيد، الذهب بالذهب يدًا بيد، مثلًا بمثل، سواءً بسواء سواء كان هذا أطيب، أو هذا أطيب، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11771/معنى-حديث-الذهب-بالذهب-والفضة-بالفضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_517/51716.mp3","categories":["شروح الحديث"]},{"id":13524,"question":"السائل من اليمن يقول في هذا  ما معنى هذا الحديث: قال رسول الله ﷺ: إن في الجنة لغرفًا يرى ظهورها من بطونها، وبطونها من ظهورها فقالوا: لمن يا رسول الله؟ قال -عليه الصلاة والسلام-: لمن أطاب الكلام، وأفشى السلام، وأطعم الطعام، وداوم على الصيام، وصلى بالليل والناس نيام، هل هذا حديث صحيح؟","title":"ما صحة حديث (إن في الجنة غرفًا...)؟","answer":"الجواب: نعم، حديث صحيح، وهي غرف عظيمة شفافة، تبصر ظهورها من بطونها، وبطونها من ظهورها، أعدها الله لمن ذكره النبي -عليه الصلاة والسلام- لمن أطعم الطعام، وأدام الصيام، وصلى بالليل والناس نيام، هذه منازل عظيمة لهؤلاء الأخيار، خصهم الله بها -جل وعلا- لعملهم الطيب، واجتهادهم في الخير. والجنة لها شأن عظيم، منازلها وما فيها من الخير العظيم لأهلها لا يخطر بالبال، مثلما قال -جل وعلا-: تَتَجَافَى جُنُوبُهُمْ عَنِ الْمَضَاجِعِ يَدْعُونَ رَبَّهُمْ خَوْفًا وَطَمَعًا وَمِمَّا رَزَقْنَاهُمْ يُنفِقُونَ * فَلا تَعْلَمُ نَفْسٌ مَا أُخْفِيَ لَهُمْ مِنْ قُرَّةِ أَعْيُنٍ [السجدة:16-17] ويقول النبي ﷺ: أعددت لعبادي الصالحين في الجنة ما لا عين رأت، ولا أذن سمعت، ولا خطر على قلب بشر ثم تلا هذه الآية. فالمؤمنون لهم في الجنة أشياء ما تخطر بالبال من النعيم، والغُرَف، والأسِرَّة، والحُور، وغير هذا مما أعد الله لهم من النعيم، الله يجعلنا وإياكم منهم، نسأل الله أن يجعلنا منهم وجميع إخواننا المسلمين، نعم، الله أكبر، الله أكبر. المقدم: اللهم آمين، جزاكم الله خيرًا يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11838/ما-صحة-حديث-ان-في-الجنة-غرفا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_518/51818.mp3","categories":["شروح الحديث"]},{"id":13551,"question":"السائل من أسئلته يقول في هذا  سمعنا حديثًا عن الرسول ﷺ قال بأن: الراكب شيطان، والراكبان شيطانان، والثلاثة ركب أخبرونا ما مدى صحة هذا الحديث، وما شرحه؟ جزاكم الله خيرًا.","title":"ما صحة حديث (الراكب شيطان...)؟","answer":"الجواب: الحديث صحيح لا بأس به، وهو يدل على تحريم السفر وحده، أو مع ثان فقط، وأن السفر يكون بثلاثة فأكثر، لا يسافر وحده، ولا ليس معه إلا صاحب واحد إذا تيسر ذلك، فإن اضطر؛ فلا حرج؛ لقول الله -جل وعلا-: وَقَدْ فَصَّلَ لَكُمْ مَا حَرَّمَ عَلَيْكُمْ إِلَّا مَا اضْطُرِرْتُمْ إِلَيْهِ [الأنعام:119]. نعم.","link":"https://binbaz.org.sa/fatwas/11891/ما-صحة-حديث-الراكب-شيطان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_532/53216.mp3","categories":["شروح الحديث","الحكم على الأحاديث"]},{"id":13556,"question":"السائل الذي أرسل بهذه الرسالة عاطف عبدالله من حائل، يقول في هذا  قال الرسول ﷺ: الحياء شعبة من الإيمان ما معنى الحياء؟ وهل هذا حديث؟","title":"ما معنى الحياء؟","answer":"الجواب: نعم، حديث صحيح، يقول النبي ﷺ في الصحيحين: الإيمان بضع وسبعون شعبة، أو قال: بضع وستون شعبة، فأفضلها: قول لا إله إلا الله، وأدناها: إماطة الأذى عن الطريق، والحياء شعبة من الإيمان والحياء خلق كريم قلبي، خلق في القلب يقتضي الانكفاف عما لا ينبغي هذا الحياء، الحياء: خلق كريم في القلب يقتضي أن ينكف صاحبه عما لا ينبغي من المعاصي، يستحي لا يفعل المعاصي، ولا يفعل الأشياء التي تنتقد عليه، يمنعه حياؤه من ذلك، فهو من الإيمان. وقد مر النبي ﷺ على رجل يعظ أخاه في الحياء، يقول له: دع عنك الحياء، فقال له ﷺ: دعه فإن الحياء من الإيمان فالحياء خلق كريم قلبي، يمنع صاحبه من الخصال الذميمة، والأخلاق المنحرفة، ويحمله على مكارم الأخلاق، ومحاسن الأعمال. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11879/ما-معنى-الحياء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_532/53211.mp3","categories":["شروح الحديث","الآداب والأخلاق المحمودة"]},{"id":13653,"question":"في فقرته الثانية يقول هذا السائل (أ. أ. أ) من الجزائر: ما هي السبع الموبقات، وهل صاحبها يدخل النار؟","title":"ما هي السبع الموبقات؟","answer":"الجواب: السبع الموبقات بينها النبي ﷺ في الحديث الصحيح، رواه الشيخان: البخاري ومسلم في الصحيحين عن النبي ﷺ أنه قال: اجتنبوا السبع الموبقات -يعني: المهلكات- قلنا: وما هن يا رسول الله؟ قال: الشرك بالله، والسحر، وقتل النفس التي حرم الله إلا بالحق، وأكل الربا، وأكل مال اليتيم، والتولي يوم الزحف، وقذف المحصنات الغافلات المؤمنات. أعظمها الشرك، هو المهلك الذي ليس معه رجاء إذا مات عليه الإنسان، فله النار مخلدًا فيها أبد الآباد، قال تعالى: إِنَّهُ مَنْ يُشْرِكْ بِاللَّهِ فَقَدْ حَرَّمَ اللَّهُ عَلَيْهِ الْجَنَّةَ وَمَأْوَاهُ النَّارُ وَمَا لِلظَّالِمِينَ مِنْ أَنصَارٍ [المائدة:72] وقال تعالى: وَلَقَدْ أُوحِيَ إِلَيْكَ وَإِلَى الَّذِينَ مِنْ قَبْلِكَ لَئِنْ أَشْرَكْتَ لَيَحْبَطَنَّ عَمَلُكَ وَلَتَكُونَنَّ مِنَ الْخَاسِرِينَ [الزمر:65] وقال تعالى: مَا كَانَ لِلْمُشْرِكِينَ أَنْ يَعْمُرُوا مَسَاجِدَ اللَّهِ شَاهِدِينَ عَلَى أَنفُسِهِمْ بِالْكُفْرِ أُوْلَئِكَ حَبِطَتْ أَعْمَالُهُمْ وَفِي النَّارِ هُمْ خَالِدُونَ [التوبة:17]. والسحر من الشرك؛ لأنه عبادة للجن، واستعانة بالجن في إضرار الناس، والساحر: هو الذي يتعاطى ما يضر الناس بواسطة الجن، وعبادتهم من دون الله، فتارة يتعاطى ما يضرهم من أقوال وأعمال ونفث في العقد، وتارة بالتخييل حتى يرى الشيء على غير ما هو عليه، فالساحر تارة يعمل أشياء تضر الناس بواسطة الجن، وعبادتهم من دون الله، من أقوال وأعمال ونفث في العقد، كما قال تعالى: وَمِنْ شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ [الفلق:4]. وتارة بالتخييل، حتى يرى الأمور على غير ما هي عليه، فيرى الحبل حية، ويرى العصا حية، ويرى الحجر بيضة، ويرى الإنسان على غير ما هو عليه، وما أشبه ذلك، فهو من جملة الكفرة. والواجب على ولي الأمر -ولي أمر المسلمين وأمير المسلمين- متى ثبت السحر عند الحاكم؛ وجب قتله، متى ثبت السحر عند المحكمة؛ وجب قتل الساحر، ولا يستتاب بل يقتل؛ لأن شره عظيم. وقد ثبت عن عمر  أمير المؤمنين  أنه كتب إلى أمرائه في الشام وغيره: \"أن يقتلوا كل ساحر وساحرة\" لعظم شرهم وخطرهم. أما قتل النفس التي حرم الله؛ فذلك جريمة عظيمة، يقول الله فيها: وَمَنْ يَقْتُلْ مُؤْمِنًا مُتَعَمِّدًا فَجَزَاؤُهُ جَهَنَّمُ خَالِدًا فِيهَا وَغَضِبَ اللَّهُ عَلَيْهِ وَلَعَنَهُ وَأَعَدَّ لَهُ عَذَابًا عَظِيمًا [النساء:93] قتل النفوس من أعظم الجرائم، لكنه كبيرة دون الشرك، من جنس المعاصي التي هي كبيرة، كالزنا والسرقة ونحو ذلك، ليس بكافر إلا أن يستحل ذلك، ولهذا قال في حقه سبحانه: وَمَنْ يَقْتُلْ مُؤْمِنًا مُتَعَمِّدًا فَجَزَاؤُهُ جَهَنَّمُ خَالِدًا فِيهَا وَغَضِبَ اللَّهُ عَلَيْهِ وَلَعَنَهُ وَأَعَدَّ لَهُ عَذَابًا عَظِيمًا [النساء:93] خالدًا فيها إن استحل ذلك، وإن لم يستحل فهو خلود مؤقت، له نهاية، خلود أهل المعاصي خلود مؤقت له نهاية، أما خلود الكفار فليس له نهاية. يقول ﷺ: اجتنبوا السبع الموبقات قالوا: وما هن يا رسول الله؟ قال: الشرك بالله، والسحر، وقتل النفس التي حرم الله إلا بالحق بالحق، قتله بالحق؛ زانٍ محصن يرجم، إنسان قتل نفسًا بغير حق، وهو مكافئ له يقتل، وجد منه ما يوجب قتله يقتل، كقطع الطريق الذي يقطع الطريق، يعني: يتعرض للناس بأخذ أموالهم في الطرقات أو ضربهم، أو قتلهم يقتل؛ لشره وعظم شره. الرابع: أكل الربا، يتعاطى الربا المحرم الذي حرمه الله، وقال فيه -جل وعلا-: وَأَحَلَّ اللَّهُ الْبَيْعَ وَحَرَّمَ الرِّبَا [البقرة:275] وقال سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَذَرُوا مَا بَقِيَ مِنَ الرِّبَا إِنْ كُنتُمْ مُؤْمِنِينَ ۝  فَإِنْ لَمْ تَفْعَلُوا فَأْذَنُوا بِحَرْبٍ مِنَ اللَّهِ وَرَسُولِهِ [البقرة:278-279] فأكل الربا من الكبائر، فالواجب الحذر منه. والربا أنواع: ربا نسيئة، وربا فضل. ربا الفضل: مثل بيع الدرهم بدرهمين، صاع من الحنطة بصاعين من الحنطة، هذه ربا فضل، صاع من الرز بصاعين من الرز، يعني من جنسه، هذا ربا فضل لا يجوز. ربا النسيئة: مثل الذي يبيع صاعًا من الحنطة بصاعين من الشعير مؤقتًا.. بعد يوم.. بعد يومين، يعني: ما يقبض إلا بعد المجلس، هذا ربا نسيئة، يبيع مائة دولار بمائة جنيه، أو ......... عشرة جنيهات في غير المجلس، ما تقبض في المجلس، هذا يسمى ربا النسيئة، يبيع مثلًا: صاع بر بصاعين شعير من غير تقابض، هذا يسمى ربا نسيئة، أو يبيع مثلًا: عشرة دولارات بعشرين دولارًا إلى أجل، فهذا ربا نسيئة مع ربا الفضل أيضًا، هذا الربا، وهو من أكبر الكبائر. الخامس: أكل مال اليتيم، وهو: الذي مات أبوه وهو صغير دون البلوغ، يسمى يتيمًا، الواجب الإحسان إليه وحفظ ماله، وتنميته، والإصلاح فيه، فالذي يفسد مال اليتيم، ويأكل ماله بغير حق في هذا الوعيد الشديد؛ لأنه ضعيف، يتعدى عليه، ويأكل ماله، هذا متوعد بهذا الوعيد الشديد، وليس بكافر، لكنه عاصي إذا لم يستحل ذلك. السادس: التولي يوم الزحف، عندما يلتقي المسلمون بالكفار ينهزم، يخلي إخوانه، يوم زحف الكفار على المسلمين، أو زحف المسلمين على الكفار، الذي ينهزم، ويترك إخوانه متوعد بهذا الوعيد الشديد إِلَّا مُتَحَرِّفًا لِقِتَالٍ أَوْ مُتَحَيِّزًا إِلَى فِئَةٍ [الأنفال:16] إلا إذا تأخر يستعد، يحضر سلاحه، يلبس درعه.. للاستعداد للقتال يعني ، هذا لا يضره، أو منتقلًا من فئة إلى فئة، ينتقل من صف إلى صف، أو من جماعة إلى جماعة لمكيدة العدو. السابع: قذف المحصنات الغافلات المؤمنات، الذي يقذف المحصنات المؤمنات الغافلات بالزنا، يقول: فلانة زانية، فلانة تدعو إلى الزنا، وهو كاذب، هذا من السبع الموبقات، يستحق أن يجلد ثمانين جلدة، كما قال تعالى: وَالَّذِينَ يَرْمُونَ الْمُحْصَنَاتِ ثُمَّ لَمْ يَأْتُوا بِأَرْبَعَةِ شُهَدَاءَ فَاجْلِدُوهُمْ ثَمَانِينَ جَلْدَةً [النور:4]. قذف المحصنات كبيرة من الكبائر، وهكذا المحصن من الرجال، لكن لما كان الغالب قذف النساء جاء في الحديث النساء، وإلا فهكذا، لو قذف المحصن من الرجال قال: إنه يزني؛ فعليه أن يأتي بأربعة شهداء، وإلا يجلد ثمانين جلدة. هذه السبع الموبقات، يعني: المهلكات، لشدة خبثها، نسأل الله العافية. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11996/ما-هي-السبع-الموبقات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_543/54302.mp3","categories":["شروح الحديث"]},{"id":13666,"question":"أيضًا يقول: هل هذا حديث بيت لا تمر فيه جياع أهله؟","title":"هل هذا حديث (بيت لا تمر فيه جياع أهله)؟","answer":"الجواب: نعم، هذا حديث صحيح رواه مسلم، وهو يدل على أن البيت الذي ما فيه تمر جياع أهله إذا كانوا اعتادوا التمر، مثل أهل المدينة، وأهل نجد، وغيرهم ممن اعتادوا التمر فبيت لا تمر فيه لأنه طعام جاهز، يكفي عن كل شيء، فإذا فقده أهل البيت؛ فهم جياع في الحقيقة، لاسيما إذا كانوا معتادين هذا الشيء وهو قوتهم. أما إذا تغيرت الأحوال، وصار لهم قوت آخر؛ فالحديث في غيرهم، الرسول ﷺ يخبر عن أهل المدينة الذين اعتادوا التمر وهو قوتهم. نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12009/هل-هذا-حديث-بيت-لا-تمر-فيه-جياع-اهله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_529/52909.mp3","categories":["شروح الحديث","الحكم على الأحاديث"]},{"id":13756,"question":"سماحة الشيخ! السائل يقول: ما المقصود بالنهي عن التحلق يوم الجمعة؟","title":"المقصود بالنهي عن التحلق يوم الجمعة","answer":"الجواب: على ظاهره، كونهم يتحلقون للدرس، والفائدة، أو لقراءة القرآن، يكون حلقة أمام معلمهم، أو قارئهم، هذا منهي عنه. أما كون واحد في الصف يقرأ، والآخر في الصف، أو مستند على جدار، أو على عمود يقرأ، كل واحد يقرأ لنفسه، ما يسمى حلقات هذا. نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/12132/المقصود-بالنهي-عن-التحلق-يوم-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_535/53525.mp3","categories":["صلاة الجمعة","شروح الحديث"]},{"id":13761,"question":"سماحة الشيخ! السائل يقول: ما المقصود بالنهي عن التحلق يوم الجمعة؟","title":"المقصود بالنهي عن التحلق يوم الجمعة","answer":"الجواب: على ظاهره، كونهم يتحلقون للدرس، والفائدة، أو لقراءة القرآن، يكون حلقة أمام معلمهم، أو قارئهم، هذا منهي عنه. أما كون واحد في الصف يقرأ، والآخر في الصف، أو مستند على جدار، أو على عمود يقرأ، كل واحد يقرأ لنفسه، ما يسمى حلقات هذا. نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/12132/المقصود-بالنهي-عن-التحلق-يوم-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_535/53525.mp3","categories":["صلاة الجمعة","شروح الحديث"]},{"id":13820,"question":"السائل يقول في هذا  ثبت عن النبي ﷺ: «أنه جاءته امرأة مع ابنتها، فرأى في يدي ابنتها سوارين من ذهب، فقال: أتخرجين زكاة هذا؟ قالت: لا، قال: أيسرك أن يسورك الله بهما يوم القيامة سوارين من نار؟!، فألقتهما، وقالت: هما لله وللرسول»، فهل قال الرسول ﷺ لها أم لابنتها؟ وعندما قالت: (هما لله وللرسول) فهل هذا يعتبر من الشرك؟ أم ماذا تفيد الواو عندما قالت ذلك مأجورين؟","title":"ما معنى (هما لله ورسوله)؟","answer":"الجواب: مرادها: أن هذا لله ويتصرف فيه الرسول ﷺ بما أراه الله، يعني: يتصرف في ذلك، ليس من الشرك في شيء، يعني: لله وللرسول للتصرف في ذلك كما شرع الله؛ لأن الرسول ﷺ هو المبلغ عن الله، وهذا من أدلة وجوب الزكاة في الحلي؛ لأن الرسول ﷺ قال: أتعطين زكاة هذا؟، فدل ذلك على أن الحلي فيها الزكاة إذا بلغت النصاب، هذا هو الأرجح ولو كانت مستعملة.\nوقولها: هما لله ولرسوله يعني: يتصرف فيها الرسول ﷺ؛ لأنه المبلغ عن الله والمرشد والموجه والمعلم. نعم.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12183/ما-معنى-هما-لله-ورسوله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_537/53702.mp3","categories":["شروح الحديث"]},{"id":13893,"question":"هذا السائل إبراهيم أبو حامد من الرياض له مجموعة من الأسئلة، يقول: ما هي مناسبة قول الرسول ﷺ: صبرًا آل ياسر فإن موعدكم الجنة؟","title":"ما مناسبة حديث (صبرًا آل ياسر فإن موعدكم الجنة)؟","answer":"الجواب: هذا قال لهم ﷺ لما كانوا يعذبون، كان ياسر وعمار وأم عمار يعذبون، فيقول لهم: صبرًا يا آل ياسر فإن موعدكم الجنة لأن كفار قريش كانوا يعذبون المسلمين في مكة، ومن ذلك: آل ياسر وبلال وغيرهم، فالرسول ﷺ صبرهم وشجعهم على الصبر، وأن لهم في هذا الخير العظيم، وأن الله جل وعلا سوف يدخلهم الجنة على صبرهم على دين الله. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12258/ما-مناسبة-حديث-صبرا-ال-ياسر-فان-موعدكم-الجنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_538/53804.mp3","categories":["التاريخ والسيرة","شروح الحديث"]},{"id":13928,"question":"حفت الجنة بالمكاره، وحفت النار بالشهوات، اشرحوا لنا هذا القول؟ جزاكم الله خيرًا.","title":"شرح حديث «حفت الجنة بالمكاره...»","answer":"الجواب: هذا حديث صحيح، حديث صحيح عن النبي ﷺ أنه قال: حفت النار بالشهوات، وحفت الجنة بالمكاره، وفي اللفظ الآخر: حجبت النار بالشهوات، وحجبت الجنة بالمكاره المعنى: أنه جعل بين النار وبين الإنسان ارتكاب الشهوات المحرمة فإن ارتكبها صار إلى النار وانتهك الحجاب، وإن امتنع منها سلم، فالنفس قد تشتهي الزنا أو الخمر فإن طاوعها صار إلى النار، قد تشتهي ترك الصلاة والكسل ولا يصلي فإن طاوع النفس صار إلى النار نعوذ بالله، قد تشتهي سب الدين والاستهزاء فإن طاوع نفسه كفر وصار إلى النار، قد تشتهي الربا فإن طاوع نفسه وفعل الربا صار إلى النار، قد تشتهي النفس قطيعة الرحم والعقوق للوالدين فإن طاوعها هلك وصار إلى النار، فالنار حفت بالشهوات المحرمة. والجنة حفت بالمكاره بما تكرهه النفوس، النفوس قد تكره الصدقة، قد تكره الجهاد، لكن إذا خالفها وجاهد في سبيل الله وتصدق صار إلى الجنة، قد تكره المحافظة على الصلوات في الجماعة قد تكسل يكون ما عندها نشاط عندها كسل عندها كراهة للتقدم إلى الصلوات الخمس فإذا طاوعها هلك، وإن خالفها وصلى في الجماعة وحافظ على الصلاة في المساجد صار إلى الجنة، النفس أيضًا قد تكره صلة الرحم، بر الوالدين، إكرام الجار فإن طاوعها هلك وإن خالفها وبر والديه ووصل أرحامه وأكرم جيرانه فاز بالسعادة وهكذا. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12303/شرح-حديث-حفت-الجنة-بالمكاره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_482/48205.mp3","categories":["شروح الحديث","الحكم على الأحاديث"]},{"id":13930,"question":"تقول السائلة في آخر أسئلتها: قال رسول الله ﷺ: أيما جسم نبت من الحرام فالنار أولى به، ما معنى ذلك؟","title":"ما معنى: «أيما جسم نبت من حرام فالنار أولى به»؟","answer":"الجواب: هذا وعيد، من باب الوعيد والتحذير، الذي - يعني - ينبت جسمه على أكل الربا، أو على غصب أموال الناس، أو على السرقة متوعد بالنار نعوذ بالله؛ فالواجب الحذر، وأن يكون كسب المسلم حلالًا، وليحذر ظلم الناس، أو أكل الربا، أو الغش في المعاملات، أو سرقة أموال الناس، أو ما أشبه ذلك، نسأل الله العافية. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12306/ما-معنى-ايما-جسم-نبت-من-حرام-فالنار-اولى-به","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_538/53821.mp3","categories":["شروح الحديث"]},{"id":14040,"question":"حديث من مات وعليه صوم؛ صام عنه وليه، الشيء الذي أعرفه أنه محمول على صوم النذر، ولكن أحد العلماء ذكر في البرنامج أنه صوم رمضان، فهل هذا صحيح؟ أم الصحيح ما أعرفه من طريق أحد الكتب السلفية؟ أفيدوني مأجورين، جزاكم الله خيرًا.","title":"ما هو الصوم الذي يقضى عن الميت؟","answer":"الجواب: الصواب أنه عام وليس خاصًا بالنذر، وقد روي عن بعض الأئمة كـأحمد رحمه الله وجماعة، أنهم قالوا: إنه خاص بالنذر، ولكنه قول مرجوح، ولا دليل عليه.\nوالصواب أنه عام؛ لأن الرسول عليه السلام قال: من مات وعليه صيام صام عنه وليه، متفق على صحته من حديث عائشة رضي الله عنها، ولم يقل: صوم النذر، ولا يجوز تخصيص كلام النبي ﷺ بالدعاوى والاجتهادات والآراء، لا، حديث النبي عام عليه الصلاة والسلام، يعم صوم النذر وصوم رمضان إذا تأخر، إذا ترك صيامه تكاسلًا بعد القدرة، أو صوم الكفارات، فمن ترك ذلك؛ صام عنه وليه، والولي: هو القريب، أقاربه، وإن صام غيرهم؛ أجزأ ذلك، وقد سئل النبي ﷺ سأله رجل قال: يا رسول الله! إن أمي ماتت، وعليها صوم شهر أفأصوم عنها؟ قال: أرأيت لو كان على أمك دين أكنت قاضيه؟ اقضوا الله فالله أحق بالوفاء، وسألته امرأة عن ذلك قالت: يا رسول الله! إن أمي ماتت، وعليها صوم شهر أفأصوم عنها؟ قال: أرأيت لو كان على أمك دين أكنت قاضيته؟ اقضوا الله فالله أحق بالوفاء.\nوفي مسند أحمد بإسناد صحيح عن ابن عباس رضي الله عنهما: أن امرأة قالت: يا رسول الله! إن أمي ماتت وعليها صوم رمضان أفأصوم عنها؟ قال: صومي عن أمك، فأوضحت أنه رمضان، فأمرها بالصيام، فالأحاديث الكثيرة دالة على أن القضاء يعم رمضان وغيره، وأنه لا وجه لتخصيص النذر، بل هو قول مرجوح ضعيف، والصواب العموم، هكذا جاءت الأدلة عن رسول الله عليه الصلاة والسلام، لكن إذا كان المفطر في رمضان لم يفرط، بأن أفطر من أجل المرض، أو من أجل الرضاع أو الحمل، ثم مات المريض أو ماتت الحامل أو ماتت المرضعة، ولم تستطع القضاء؛ فلا شيء على الورثة، لا قضاء ولا إطعامًا للعذر الشرعي وهو المرض ونحوه، أما من شفي من مرضه، وأمكنه الصوم فتساهل؛ هذا يقضى عنه، أو المرضع أو الحامل، استطاعت أن تقضي بعد ذلك، ولكن تساهلت؛ فهذا يقضى عنها، والله ولي التوفيق.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12462/ما-هو-الصوم-الذي-يقضى-عن-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_607/60705.mp3","categories":["قضاء الصيام","شروح الحديث"]},{"id":14042,"question":"من الجماهرية هذه رسالة بعث بها مستمع يقول: المرسل حمد عبد الصادق، الأخ حمد يقول: أرجو أن تتفضلوا بشرح الجمل الآتية: (رب قارئ للقرآن والقرآن يلعنه) كيف يلعن القرآن قارئه ولماذا؟","title":"معنى: (رب قارئ للقرآن والقرآن يلعنه)","answer":"الجواب: لا أعلم صحة هذا الحديث عن النبي عليه الصلاة والسلام، ولا حاجة إلى تفسيره، ولو صح لكان المعنى أن في القرآن ما يقتضي ذمه ولعنه لكونه خالف القرآن؛ يقرأه وهو يخالف أوامره ويرتكب نواهيه، فهو يقرأ كتاب الله وفي كتاب الله ما يقتضي سبه وسب أمثاله؛ لأنهم خالفوا الأوامر وارتكبوا النواهي، هذا هو الأقرب للمعنى لو صح عن النبي ﷺ لكني لا أعلم صحته عن النبي عليه الصلاة والسلام. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12464/معنى-رب-قارى-للقران-والقران-يلعنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_612/61208.mp3","categories":["شروح الحديث","الحكم على الأحاديث"]},{"id":14080,"question":"مستمعٌ من الرياض -هو عمر إبراهيم سوداني- بعث برسالةٍ ضمنها عددًا من الأسئلة:في سؤاله الأول يقول: ورد في كتاب \"العقيدة الواسطية\" لشيخ الإسلام في صفحة (88): سأل سائلٌ رسول الله ﷺ: أين كان ربنا قبل أن يخلق السماوات والأرض؟ وأجاب: بأنه كان في عماء ... الحديث، ما معنى هذا الحديث؟","title":"معنى حديث: أين كان ربنا قبل أن يخلق السماوات والأرض؟","answer":"الجواب: هذا الحديث معناه: أنه كان في سحابٍ، قال العلماء: معنى \"العماء\": السحاب. قال بعضهم: الغليظ. وقال بعضهم: الرقيق. والحديث في سنده بعض المقال. والله جلَّ وعلا له صفات الكمال من كل الوجوه، ومُنزَّهٌ عن صفات النقص والعيب من كل الوجوه ، كما قال : قُلْ هُوَ اللَّهُ أَحَدٌ  ۝  اللَّهُ الصَّمَدُ  ۝  لَمْ يَلِدْ وَلَمْ يُولَدْ  ۝  وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ [الإخلاص]، وقال : لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ [الشورى:11]. وهذا الحديث مشهورٌ من حديث أبي رزين العقيلي من رواية وكيع بن حدس، وهذا الرجل -وكيع- ليس من المشهورين بالثقة. وفي هذا الحديث أن الرسول ﷺ لما سئل: أين كان ربنا قبل أن يخلق السماوات والأرض؟ قال: كان في عماء، ما فوقه هواء، وما تحته هواء، فإن صحَّ فالمعنى مثلما قال العلماء -علماء اللغة-: العماء: السحاب. قال بعضهم: السحاب الرقيق. وقال بعضهم: السحاب الغليظ. هذا معناه لو صحَّ. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12527/معنى-حديث-اين-كان-ربنا-قبل-ان-يخلق-السماوات-والارض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_614/61406.mp3","categories":["شروح الحديث","الأسماء والصفات"]},{"id":14085,"question":"نعود في بداية هذه الحلقة إلى رسالة وصلت إلينا من الجماهيرية الليبية وباعثها مستمع من هناك يقول المرسل حمد عبد الصادق، أخونا حمد عرضنا بعض أسئلته في حلقة مضت، وفي هذه الحلقة بقي له جمع من الأسئلة فيسأل مثلًا ويقول: «ما أسفل الكعبين فهو في النار» ما المقصود بهذا الحديث؟","title":"معنى حديث «ما أسفل من الكعبين...»","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nفقد روى البخاري في صحيحه رحمه الله عن النبي ﷺ أنه قال: ما أسفل من الكعبين من الإزار فهو في النار، هذا وعيد شديد يدل على تحريم الإسبال وأنه لا يجوز للمسلم أن يرخي ملابسه تحت الكعبين كالإزار والسراويل والقمص والبشت، كل ذلك يمنع، ليس له أن يرخيه تحت الإزار، وهذا وعيد شديد: ما أسفل من الكعبين من الإزار فهو في النار، قوله: من الإزار مثال، ليس خاصًا بالإزار، بل يعم الإزار والسراويل والقميص والبشت.. وغير ذلك، فالواجب على المسلم الحذر من ذلك، وأن تكون ملابسه إلى الكعب فقط، وإذا رفع ذلك إلى نصف الساق كان أفضل من نصف الساق إلى الكعب هذا محل اللباس للرجل، ولا يجوز له أن ينزل لباسه تحت الكعب.  أما المرأة فالسنة لها إرخاء الملابس حتى تغطي أقدامها كما جاءت به السنة عن النبي عليه الصلاة والسلام. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12500/معنى-حديث-ما-اسفل-من-الكعبين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_614/61401.mp3","categories":["شروح الحديث"]},{"id":14137,"question":"أرجو بيان معنى الحديث الآتي: ما من امرئ مسلم يرد عن عرض أخيه إلا كان حقًا على الله أن يرد عنه نار جهنم يوم القيامة؟","title":"معنى حديث «من رد عن عرض أخيه...»","answer":"الجواب: هذا الحديث لا بأس به ولفظه المعروف: من رد عن عرض أخيه في الغيب رد الله عن وجهه النار يوم القيامة، وهذا يدل على فضل الذب عن أخيه، والمسلم يذب عن أخيه والمرأة تذب عن أخيها في الله وأختها في الله فإذا رآه يتكلم في عرضه يقول: يا أخي! اتق الله ما بلغنا هذا ولا نعلم عليه إلا خيرًا، إذا كان يعلم عنه الخير ولم يبلغه عنه إلا الخير، لأن الغيبة شرها عظيم وفسادها كبير والله سبحانه يقول: وَلا يَغْتَبْ بَعْضُكُمْ بَعْضًا [الحجرات:12]، ويقول ﷺ: إنه رأى ليلة عرج به إلى السماء رجالًا لهم أظفار من نحاس يخمشون بها وجوههم وصدورهم، فسأل عنهم قال: هم ... سأل عنهم فقيل له: إنهم هم الذين يأكلون لحوم الناس ويقعون في أعراضهم، يعني: هم أهل الغيبة.\nفالمقصود: أن الغيبة محرمة ومن الكبائر فيجب الحذر منها، وإذا سمع المسلم أو المسلمة من يغتاب يرد عليه ويقول: يا أخي! اتق الله تقول له: يا أخي! اتق الله، يقول له الرجل: يا أخي! اتق الله أو يا فلانة! اتقي الله هذا لا يجوز الغيبة محرمة؛ لقوله ﷺ: من رد عن عرض أخيه في الغيب رد الله عن وجهه النار يوم القيامة، ولأن هذا من إنكار المنكر، الله جل وعلا أمر بإنكار المنكر قال جل وعلا: وَلْتَكُنْ مِنْكُمْ أُمَّةٌ يَدْعُونَ إِلَى الْخَيْرِ وَيَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ [آل عمران:104]، وقال سبحانه: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ [التوبة:71]، وقال عليه الصلاة والسلام: من رأى منكم منكرًا فليغيره بيده، فإن لم يستطع فبلسانه، فإن لم يستطع فبقلبه وذلك أضعف الإيمان. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12578/معنى-حديث-من-رد-عن-عرض-اخيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_485/48503.mp3","categories":["شروح الحديث"]},{"id":14138,"question":"هل هذا حديث: لا يلدغ المؤمن من جحر واحد مرتين؟","title":"هل هذا حديث «لا يلدغ المؤمن من جحر..»؟","answer":"الجواب: حديث صحيح نعم، معناه ينبغي للمؤمن أن يأخذ حذره إذا لدغ من جحر من إنسان يأخذ حذره، إذا كان زيد خدعه مرة فليحذره حتى لا يخدعه مرة أخرى، وإذا كان عمرو ظلمه في المعاملة فليحذر أن يخدعه في .... في معاملة أخرى وهكذا، يعني: ينبغي له توقي الشر ممن خدعه أولًا أو أضره أولًا. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12579/هل-هذا-حديث-لا-يلدغ-المومن-من-جحر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_485/48504.mp3","categories":["شروح الحديث","الحكم على الأحاديث"]},{"id":14176,"question":"هذا السائل حامد من الأردن يقول: سماحة الشيخ! ما معنى حديث: من سن في الإسلام سنة حسنة فله أجرها وأجر من عمل بها إلى آخر الحديث؟","title":"معنى حديث «من سن في الإسلام سنة حسنة...»","answer":"الجواب: معناه يعني: أحياها وأظهرها، ما هو بمعناه يبتدع في الدين، لا، معناها أظهر السنة وبينها، مثل قوله ﷺ: من دعا إلى هدى كان له من الأجر مثل أجور من تبعه.\nفالمقصود إذا دعا إلى هدى معروف من الشريعة فمن سن في الإسلام سنة يعني: أحياها وأظهرها، ويدل على هذا أسباب الحديث، فإنه ﷺ لما رأى ناسًا فقراء خطب الناس وحثهم على الصدقة، فجاء رجل بصدقة كاد كفه تعجز عنها فتتابع الناس واقتدوا به فقال ﷺ: من سن في الإسلام؛ لأن هذا جاء بالصدقة ظاهرًا أظهرها فتابعوه، وليس المراد اللي يبتدع في الدين، البدعة منكرة لا يجوز، النبي  قال: كل بدعة ضلالة جميع البدع كلها ضلالة ما فيها حسنة، كل بدعة ضلالة، لكن من أظهر السنة وأحياها يكون له أجرها. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12619/معنى-حديث-من-سن-في-الاسلام-سنة-حسنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_547/54711.mp3","categories":["شروح الحديث"]},{"id":14185,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع رجب جادين من قطاع ..... الشمالي، أخونا رجب له جمع من الأسئلة من بينها سؤال عن حديث فرح الله  بتوبة عبده، حيث يذكر المستمع بعضًا من معاني ذلكم الحديث ويرجو أن تتفضلوا بنصه إذا أمكن وشرح الحديث؟ جزاكم الله خيرًا.","title":"معنى حديث «لله أشد فرحًا بتوبة عبده...»","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فقد ثبت عن رسول الله عليه الصلاة والسلام أنه قال: لله أشد فرحًا بتوبة عبده من أحدكم براحلته التي عليها طعامه وشرابه فأضلها في أرض فلاة، فاضطجع قد أيس منها، فبينما هو كذلك إذا هو بها قائمة على رأسه فلما رآها أخذ بخطامها وقال من شدة الفرح: اللهم أنت عبدي وأنا ربك أخطأ من شدة الفرح، أو كما قال عليه الصلاة والسلام.\nوهذا يدل على فضله وإحسانه جل وعلا وأنه سبحانه يحب لعباده أن يتوبوا إليه وأن يستقيموا على طاعته حتى يفوزوا بجنته ونعيمه. والفرح من الله جل وعلا مثل سائر الصفات كالرضا والغضب والرحمة والمحبة وغير ذلك كلها صفات تليق بالله يجب إثباتها لله على الوجه اللائق به ، وليست من جنس صفات المخلوقين، فغضب الله ليس كغضب المخلوقين، وفرحه ليس كفرحهم، ورضاه ليس كرضاهم، وهكذا رحمته ومحبته وكراهته وسمعه وبصره وغير ذلك كلها صفات كاملة تليق بالله لا يشابه فيها خلقه ؛ لقول الله  في كتابه العظيم: لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ [الشورى:11]، ولقوله سبحانه: فَلا تَضْرِبُوا لِلَّهِ الأَمْثَالَ إِنَّ اللَّهَ يَعْلَمُ وَأَنْتُمْ لا تَعْلَمُونَ [النحل:74]، وقوله : قُلْ هُوَ اللَّهُ أَحَدٌ ۝ اللَّهُ الصَّمَدُ ۝ لَمْ يَلِدْ وَلَمْ يُولَدْ ۝ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ[الإخلاص:1-4]. وهذا هو قول أهل السنة والجماعة قاطبة جميعًا، وهم أصحاب النبي ﷺ ومن تبعهم بإحسان، هؤلاء هم أهل السنة أصحاب النبي ﷺ وأتباعهم بإحسان الذين ساروا على نهجهم وعلى طريقهم واستمسكوا بما كانوا عليه في العلم والعمل، هم أهل السنة والجماعة ومنهم وعلى رأسهم أبو بكر الصديق  وعمر بن الخطاب  وعثمان  وعلي  وهكذا بقية الصحابة رضي الله عنهم وأرضاهم، ثم التابعون بعدهم كـمحمد بن سيرين وسعيد بن المسيب وعطاء بن يسار وعطاء بن أبي رباح وغيرهم من أئمة التابعين رحمة الله عليهم، وهكذا أتباع التابعين كـمالك بن أنس الإمام المعروف رحمه الله وأبي حنيفة رحمه الله، وهكذا من بعدهم كـالشافعي وأحمد وإسحاق بن راهويه وسفيان الثوري وغيرهم من أئمة الإسلام، هؤلاء ومن بعدهم ممن سار على نهجهم هم أهل السنة والجماعة. كلهم أجمعوا على أن الواجب إمرار آيات الصفات وأحاديثها كما جاءت والإيمان بمعناها وأن معناها حق لائق بالله وأنه سبحانه لا يماثل خلقه لا في ذاته ولا في أسمائه وصفاته سبحانه وتعالى وذلك هو مقتضى قوله : لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ [الشورى:11]، وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ [الإخلاص:4]، وما جاء في معناها من الآيات والله ولي التوفيق. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12638/معنى-حديث-لله-اشد-فرحا-بتوبة-عبده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_486/48601.mp3","categories":["شروح الحديث"]},{"id":14195,"question":"هذا السائل يقول في هذا  أرجو من سماحة الشيخ أن يشرح هذا الحديث الذي ما معناه: ما منكم من أحد إلا وقد علم مقعده من الجنة والنار فنرجو منكم توجيه حول هذا الحديث؟","title":"ما معنى: «ما منكم من أحد إلا وقد علم مقعده»؟","answer":"الجواب: هذا الحديث صحيح جاء بمعناه أحاديث كثيرة، فالله جل وعلا سبق علمه بجميع الكائنات، فهو يعلم سبحانه أهل الجنة وأهل النار، وقد سبق في علمه وكتابته لذلك، وكل مولود يولد يكتب رزقه وأجله وعمله وشقي أو سعيد، كما في حديث ابن مسعود وغيره، ولكن هذه الكتابة وهذا القدر لا يمنع من العمل، النبي عليه السلام قال: اعملوا فكل ميسر لما خلق له خطبهم ذات يوم عليه الصلاة والسلام وقال: ما منكم من أحد وإلا وقد علم مقعده من الجنة ومقعده من النار. فقالوا: يا رسول الله! ففيم العمل؟ -يعني: إذا كانت مقاعدنا معلومة ففيم العمل؟- قال: اعملوا فكل ميسر لما خلق له، أما أهل السعادة فييسروا لعمل أهل السعادة، وأما أهل الشقاوة فييسروا لعمل أهل الشقاوة ثم تلا قوله تعالى: فَأَمَّا مَنْ أَعْطَى وَاتَّقَى ۝ وَصَدَّقَ بِالْحُسْنَى ۝ فَسَنُيَسِّرُهُ لِلْيُسْرَى ۝ وَأَمَّا مَنْ بَخِلَ وَاسْتَغْنَى ۝ وَكَذَّبَ بِالْحُسْنَى ۝ فَسَنُيَسِّرُهُ لِلْعُسْرَى [الليل:5-10]».\nفالمقصود أن الله جل وعلا قدر المقادير وأمر بطاعته ونهى عن معصيته، وبعث الرسل بهذا الأمر، وأنزل الكتب بهذا الأمر، وأعطى العبد عقلًا وأعطاه اختيارًا وإرادة، فالواجب عليه أن يتقي الله، وأن يبادر ويسارع إلى فعل ما أوجب الله عليه، وترك ما حرم الله عليه، ويسأل ربه العون. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12648/ما-معنى-ما-منكم-من-احد-الا-وقد-علم-مقعده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_548/54802.mp3","categories":["شروح الحديث"]},{"id":14207,"question":"السائل خلف عبد الرحمن يقول: من هم الذين يظلهم الله في ظله يوم القيامة؟ وكذلك الذين لا يظلهم؟","title":"الذين يظلهم الله في ظله يوم القيامة","answer":"الجواب: حسب ما جاء في الأحاديث عن النبي ﷺ يقول ﷺ: سبعة يظلهم الله في ظله يوم لا ظل إلا ظله: إمام عادل، وشاب نشأ في عبادة الله، ورجل قلبه معلق بالمساجد، ورجلان تحابا في الله اجتمعا عليه وتفرقا عليه، ورجل دعته امرأة ذات منصب وجمال فقال: إني أخاف الله، ورجل تصدق بصدقة فأخفاها حتى لا تعلم شماله ما تنفق يمينه، ورجل ذكر الله خاليًا يعني: ما عنده أحد ففاضت عيناه يعني: بكاء من خشية الله جل وعلا، أخرجه البخاري ومسلم في الصحيحين، وهكذا ما جاء في معناه من الأحاديث حسب ما يثبت عن النبي ﷺ. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12656/الذين-يظلهم-الله-في-ظله-يوم-القيامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_548/54808.mp3","categories":["شروح الحديث"]},{"id":14247,"question":"هذا السائل الذي أرسل بهذه الرسالة لم يكتب الاسم في هذه الرسالة يقول: كان ﷺ يقول: اللهم مقلب القلوب ثبت قلبي على دينك فقال لـعائشة: إن القلوب بين أصبعي الرحمن نريد تكملة لهذا الحديث، وما المناسبة لهذا الحديث؟","title":"معنى حديث «القلوب بين أصبعين من أصابع الرحمن...»","answer":"الجواب: الحديث واضح، يقول ﷺ: إن القلوب بين إصبعين من أصابعه يقلبها كيف يشاء، فالمعنى أن الله جل وعلا هو الذي بيده تثبيت الأمور، فالمؤمن يسأل ربه الثبات على الإيمان والثبات على الحق، فالقلوب تتقلب وهي بين إصبعين من أصابع الله، هذا يجرى على ظاهره، يثبت لله الأصابع على الوجه اللائق بالله، وأن الله جل وعلا بيده تصريف الأمور وتقليب القلوب كيف يشاء، هذا يقلب فيرتد عن دينه، وهذا يقلب فيسلم، وهذا يقلب قلبه فيقع في المعاصي، فالقلوب بيد الله جل وعلا، هو الذي يصرفها كيف يشاء ، والمؤمن يسأل ربه يقول: اللهم ثبت قلبي على دينك، اللهم يا مقلب القلوب ثبت قلبي على دينك، اللهم يا مصرف القلوب صرف قلبي على طاعتك، يسأل ربه الثبات. والله  يوصف بأن له أصابع وله يد جل وعلا على الوجه اللائق به ، لا يشابه عباده لا في اليد ولا في الأصابع ولا في الكلام ولا في الرضا ولا في الغضب ولا في غير ذلك، كما قال سبحانه: لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ [الشورى:11]، وقال تعالى: وَلِلَّهِ الأَسْمَاءُ الْحُسْنَى فَادْعُوهُ بِهَا [الأعراف:180]. نعم.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12704/معنى-حديث-القلوب-بين-اصبعين-من-اصابع-الرحمن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_530/53017.mp3","categories":["شروح الحديث"]},{"id":14263,"question":"يقول النبي ﷺ فيما معناه: إن الله  لم يجعل شفاء أمتي فيما حرم عليها وبعض الناس عندما يصاب ببعض الأمراض المزمنة يذهبون لبعض المشعوذين، أي: من يسمون أنفسهم بالأطباء العرب، فينصحونهم: إما بأكل لحم الخنزير، أو بشرب الخمر، وقد حدث هذا كثيرًا، ويستدل هؤلاء المشعوذون بالقاعدة الشرعية التي تقول: إن الضرورات تبيح المحظورات، ما حكم التداوي بما ذكرت، وهل القاعدة تتعارض مع معنى الحديث السابق؟!","title":"حكم التداوي بالحرام بحجة الضرورة","answer":"الجواب: هذا غلط من بعض الناس، فإن الله جل وعلا لم يجعل شفاء الناس فيما حرم عليهم، وليست داخلة في القاعدة فليس هناك ضرورة؛ لأنه ليس فيه شفاء، الشفاء فيما أباح الله جل وعلا، ولهذا قال عليه الصلاة والسلام لما سأله سائل قال: يا رسول الله! إني أصنع الخمر للدواء، قال عليه الصلاة والسلام:إنها ليست بدواء ولكنها داء وفي الحديث: إن الله لم يجعل شفاءكم فيما حرم عليكم.\nفلا يجوز للمريض أن يأتي المشعوذين الذين يتهمون باستخدام الجن ودعوى علم الغيب ونحو ذلك، أو يتهمون بأنهم يعالجون بالحرام كلحم الخنزير أو شرب الخمر أو غير هذا مما حرم الله، هذا منكر لا يجوز، بل يجب على المريض أن يبتعد عما حرم الله وألا يتعاطى إلا ما أباح الله في علاجه، فلا يأتي السحرة والكهان والمشعوذين، ولا يجوز له سؤالهم ولا تصديقهم، ولا يجوز له أن يتعالج بما حرم الله من خمر أو خنزير أو دخان أو غير هذا مما حرم الله، وفيما أباح الله غنية -والحمد لله- عما حرم الله، نسأل الله السلامة. نعم.\nالمقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12754/حكم-التداوي-بالحرام-بحجة-الضرورة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_621/62107.mp3","categories":["الطب والتداوي","شروح الحديث"]},{"id":14287,"question":"ما صحة هذا الحديث: عن أنس بن مالك قال: قال رسول الله ﷺ: إن العبد ليموت والداه أو أحدهما وإنه لهما لعاق فلا يزال يدعو لهما ويستغفر لهما حتى يكتبه الله بارًا ما صحة هذا الحديث بارك الله في علمكم ونفع بكم؟ والحديث ورد في نصيحة المسلمين، وفي صفحة رقم ثلاثمائة وثلاثة وستين.","title":"ما صحة حديث \"إن العبد ليموت والده أو أحدهما...\"؟","answer":"الجواب: لا أعرف حال هذا الحديث ولا أدري عن صحته، ولكن المعنى صحيح، فإن الدعاء لوالديه والاستغفار لهما والصدقة عنهما من جملة البر بعد الموت، ولعل الله يخفف عنه بذلك ما سبق من عقوق مع التوبة الصادقة، فعليه أن يتوب إلى الله إذا كان عاقًا لهما، عليه أن يتوب إلى الله ويندم على ما فعل، ويقلع من ذلك ويكثر من التوبة والاستغفار والدعاء لهما بالرحمة والعفو والمغفرة، مع الإكثار من الصدقة عنهما، فإن هذا كله مما شرعه الله جل وعلا في حق الولد لوالديه، ثبت عنه ﷺ أنه سأله قال: هل بقي من بر أبوي شيء أبرهما به بعد وفاتهما؟ قال النبي ﷺ: نعم. الصلاة عليهما، والاستغفار لهما، وإنفاذ عهدهما من بعدهما، وإكرام صديقهما، وصلة الرحم التي لا توصل إلا بهما.\nهذا كله من برهما بعد الموت، والصلاة عليهما معناها: الاستغفار والدعاء، الصلاة عليهما، يعني: الدعاء لهما، ومن ذلك صلاة الجنازة.\nوالاستغفار لهما؛ طلب المغفرة، يدعو لهما بالمغفرة، وإنفاذ عهدهما يعني: وصاياهما، إذا أوصيا بشيء لا يخالف الشرع من برهما أن ينفذ الوصية الموافقة للشرع.\nوإكرام صديقهما، أصدقاء والديه يكرمهما ويحسن إليهما ويراعي حقوق الصداقة بينهم وبين والديه، كل هذا من بر والديه، وإذا كان الصديق فقيرًا واساه، وإن كان غير فقير اتصل به للسلام عليه والسؤال عن حاله، استصحابًا للصداقة التي بينه وبين والديه، إذا كان ذلك الصديق ليس ممن يستحق الهجر.\nكذلك صلة الرحم التي لا توصل إلا بهما، كالإحسان إلى أخواله وأعمامه وأقاربه من جهة الأب ومن جهة الأم، سوى الأعمام والأخوال، كل هذا من بر الوالدين. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12771/ما-صحة-حديث-ان-العبد-ليموت-والده-او-احدهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_618/61804.mp3","categories":["شروح الحديث","الحكم على الأحاديث"]},{"id":14301,"question":"....... ونعوذ بعفوك من عقوبتك ونعوذ بك منك لا نحصي ثناء عليك مع بيان كيفية التعوذ بقولنا: أعوذ بك منك، وضحوا لنا هذه المسألة؟","title":"معنى «أعوذ بك منك..»","answer":"الجواب: هذا حديث صحيح من دعاء النبي ﷺ، وهذا يدل على أنه يجوز بل يشرع التعوذ بصفات الله من صفات الله والتعوذ بالله من الله، فهو يتعوذ برضاه من سخطه: أعوذ برضاك من سخطك فهذا من باب التعوذ بالصفة من الصفة، والتعوذ بالعفو من العقوبة، وبك منك يعني: بقوتك وقدرتك على عذابي وعقوبتي بعدلك وعفوك وفضلك وإحسانك، فيتوسل من صفات العدل وصفات العقوبة بصفات العفو والإحسان والجود والكرم، وكلها صفات لله جل وعلا.\nفالإنسان يتعوذ برضاه من غضبه وبعفوه من عقوبته، وبحلمه وصبره وإحسانه من عقوبته لعبده وحرمانه لفضله.. إلى غير ذلك مما قد يقع للعبد بسبب ذنوبه وسيئاته.\nفهو تعوذ بصفاته من صفاته، وهو تعوذ بالله ، التعوذ بصفاته تعوذ به ، ومثل: أعوذ بكلمات الله التامات من شر ما خلق الكلمات صفة من صفاته يتعوذ بها من شر ما خلق .\nوهكذا التعوذ بعزة الله وبعزة الله وقدرته من شر ما أجد وأحاذر كما في الحديث. من آلمه شيء من جسده فإنه يشرع له أن يضع يده عليه ويقول: أعوذ بعزة الله وقدرته من شر ما أجد وأحاذر رواه مسلم من حديث عثمان بن أبي العاص، هذا كله من باب التعوذ بصفات الله من صفات الله، فيتعوذ بعزته وقدرته من شر ما يجد ويحاذر من آلام وأمراض، ويتعوذ بكلمات الله التامات من شر ما خلق من جن وإنس. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12773/معنى-اعوذ-بك-منك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_550/55003.mp3","categories":["شروح الحديث","مسائل متفرقة في العقيدة"]},{"id":14364,"question":"السائلة (أ. ت) تقول: قرأت بأن النبي ﷺ مات عن فدك -كتبت هكذا- عن فدك وأموال، وكذلك قرأت بأن النبي ﷺ مات ولم يترك دينارًا ولا درهمًا كيف أوفق بين هذين؟","title":"الجمع بين «ما ترك النبي دينارًا..» وتركه أرض خيبر وفدك","answer":"الجواب: نعم، توفي وما خلف نقودًا، ما جاءه من النقود أنفقها -عليه الصلاة والسلام-، لكن خلف أراضٍ في خيبر وفي فدك أراضٍ للمسلمين؛ لمصلحة المسلمين، الرسل والأنبياء ما يورثون دينارًا ولا درهمًا، إنما يورثون ما ينفع المسلمين، ما تركوه فهو صدقة، تصرف في مصالح المسلمين، كما قال ﷺ: نحن معاشر الأنبياء لا نورث، ما تركناه فهو صدقة هو ما ورث دراهم ولا دنانير، وإنما خلف أرضًا في خيبر وفدك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12844/الجمع-بين-ما-ترك-النبي-دينارا-وتركه-ارض-خيبر-وفدك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_551/55106.mp3","categories":["شروح الحديث","التاريخ والسيرة"]},{"id":14365,"question":"تقول من ضمن أسئلة هذه السائلة (أ.ت) ما معنى قولهم: كان الرسول ﷺ يصوم حتى يقال: لا يفطر، ويفطر حتى يقال: لا يصوم؟","title":"ما معنى «كان ﷺ يصوم حتى يقال لا يفطر...»","answer":"الجواب: المعنى أنه يتحرى الأوقات التي فيها فرصة له فيصوم، يسرد الصوم كاملًا، مثل ستة سبعة يسردها إذا حصل فرصة، وعدم شغل، ويكون له أشغال مع الوفود، ومع غيرهم فيسرد الفطر أيامًا كثيرة ما فيها صوم، يعني: ينتهز الفرص للصوم، فإذا وجد من نفسه فراغًا صام وسرد الأيام، وإذا وجد شغلًا أفطر وسرد أيامًا -عليه الصلاة والسلام-، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12845/ما-معنى-كان-ﷺ-يصوم-حتى-يقال-لا-يفطر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_551/55107.mp3","categories":["شروح الحديث"]},{"id":14421,"question":"تستفسر عن الحديث ما معناه، قال رسول الله ﷺ: إن الرجل ليتكلم بالكلمة ما يلقي لها بالًا يهوي بها في النار أبعد ما بين المشرق والمغرب؟","title":"ما معنى «إن الرجل ليتكلم بالكلمة..»؟","answer":"الجواب: هذا حديث صحيح يوجب الحذر من الكلام السيئ، وفي الحديث الآخر يقول ﷺ إن العبد ليتكلم بكلمة من سخط الله ما يتبين فيها يعني: ما يثبت فيها يكتب الله له بها سخطه إلى يوم يلقاه. فالواجب الحذر، وأن يحفظ الإنسان لسانه فلا يتكلم بما لا ينبغي، فقد يتكلم بكلمة خبيثة يزل بها في النار أبعد ما بين المشرق والمغرب، يكتب الله له بها سخطه، كأن يدعو إلى فاحشة، أو يسب الله أو يسب رسوله أو يسب الدين فيقع في منكر عظيم وردة عظيمة نسأل الله العافية. فالواجب أن يحذر شر لسانه، وأن لا يتكلم إلا بالخير، كما قال ﷺ: من كان يؤمن بالله واليوم الآخر فليقل خيرًا أو ليصمت. قد يتكلم يمزح ولا يتبين ولا يتثبت فيقع في شر عظيم، كأن يقول: فلان بخيل. هذه غيبة، فلان أحمق، غيبة هو يمزح هذه إثمها عظيم، وأشر من هذا وأعظم أن يدعو إلى الفاحشة يدعو إلى الزنا، يدعو إلى المعاصي، أو يسب الله، أو يسب الرسول ﷺ أو يسب الدين فيقع في الردة نعوذ بالله، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12903/ما-معنى-ان-الرجل-ليتكلم-بالكلمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_553/55317.mp3","categories":["شروح الحديث","الحكم على الأحاديث"]},{"id":14427,"question":"أخيرًا السائلة يا سماحة الشيخ عبدالعزيز تستفسر عن معنى هذا الحديث؛ قال رسول الله ﷺ: من قرأ آية الكرسي دبر كل صلاة مكتوبة لم يمنعه من دخول الجنة إلا أن يموت ما معنى هذا الحديث؟","title":"ما معنى «من قرأ آية الكرسي دبر كل صلاة..»؟","answer":"الجواب: هذا جاء له طرق، وبعضها لا بأس به، وهو يستحبن يدل على أنه يستحب أن تقرأ هذه الآية بعد كل صلاة: اللَّهُ لا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ [البقرة:255] وهي أعظم آية في القرآن، يستحب أن تقرأ بعد كل صلاة من الصلوات الخمس؛ لأن بعض الطرق صحيح جيد لا بأس به، ومعناه الوعد بالخير، وأن هذا من أسباب دخول الجنة إن لم يمنع مانع من وجود كبائر من الذنوب، مثلما في الأحاديث الأخرى التي فيها الوعد بالجنة لمن صام عرفة من صام يوم عرفة، أو صام يوم العاشوراء، أو صام الإثنين والخميس، يعني: إن لم يصر على الكبائر. الحديث هذا وعد إن لم يقم على الكبائر، أما من أقام على الكبائر ما تغفر له ذنوبه، يقول النبي ﷺ: الصلوات الخمس، والجمعة إلى الجمعة، ورمضان إلى رمضان، كفارات لما بينهن إذا اجتنب الكبائر والله يقول في كتابه العظيم يخاطب المؤمنين وغيرهم: إِنْ تَجْتَنِبُوا كَبَائِرَ مَا تُنْهَوْنَ عَنْهُ نُكَفِّرْ عَنْكُمْ سَيِّئَاتِكُمْ وَنُدْخِلْكُمْ مُدْخَلًا كَرِيمًا[النساء:31]. فشرط في تكفير السيئات، ودخول الجنات اجتناب الكبائر، أما من لم يجتبنها مات وهو مقيم عليها من الزنا أو العقوق للوالدين أو أكل الربا أو قطيعة الرحم، أو ما أشبه ذلك، فهذا معلق أمره وعلى خطر، لا تكن حسناته مكفرة، بل هو على خطر حتى يجتنب الكبائر.  إذا كانت الصلاة وهي عمود الإسلام لا تكفر إلا باجتناب الكبائر، وهكذا صوم رمضان فكيف بغير ذلك؟ يقول ﷺ: الصلوات الخمس، والجمعة إلى الجمعة، ورمضان إلى رمضان كفارات لما بينهن إذا اجتنب الكبائر وفي لفظ: ما لم تغش الكبائر أخرجه مسلم في الصحيح، فهذا يدل على أن أحاديث الوعد بالمغفرة والرحمة لمن استغفر أو فعل كذا وكذا مشروط باجتناب الكبائر، ونص الآية واضح في ذلك، يقول سبحانه: إِنْ تَجْتَنِبُوا كَبَائِرَ مَا تُنْهَوْنَ عَنْهُ نُكَفِّرْ عَنْكُمْ سَيِّئَاتِكُمْ وَنُدْخِلْكُمْ مُدْخَلًا كَرِيمًا [النساء:31]. فالأحاديث التي فيها تكفير السيئات، وحط الخطايا لمن فعل كذا، أو فعل كذا، يعني: ما لم يصر على كبيرة، ما لم يكن عنده إصرار على كبيرة من الكبائر، فإذا أصر على الكبيرة لم تكفر له الذنوب بذلك العمل، نسأل الله لنا ولجميع المسلمين العافية، نعم.","link":"https://binbaz.org.sa/fatwas/12906/ما-معنى-من-قرا-اية-الكرسي-دبر-كل-صلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_553/55320.mp3","categories":["مسائل متفرقة في الصلاة","شروح الحديث"]},{"id":14441,"question":"أخيرًا السائلة يا سماحة الشيخ عبدالعزيز تستفسر عن معنى هذا الحديث؛ قال رسول الله ﷺ: من قرأ آية الكرسي دبر كل صلاة مكتوبة لم يمنعه من دخول الجنة إلا أن يموت ما معنى هذا الحديث؟","title":"ما معنى «من قرأ آية الكرسي دبر كل صلاة..»؟","answer":"الجواب: هذا جاء له طرق، وبعضها لا بأس به، وهو يستحبن يدل على أنه يستحب أن تقرأ هذه الآية بعد كل صلاة: اللَّهُ لا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ [البقرة:255] وهي أعظم آية في القرآن، يستحب أن تقرأ بعد كل صلاة من الصلوات الخمس؛ لأن بعض الطرق صحيح جيد لا بأس به، ومعناه الوعد بالخير، وأن هذا من أسباب دخول الجنة إن لم يمنع مانع من وجود كبائر من الذنوب، مثلما في الأحاديث الأخرى التي فيها الوعد بالجنة لمن صام عرفة من صام يوم عرفة، أو صام يوم العاشوراء، أو صام الإثنين والخميس، يعني: إن لم يصر على الكبائر. الحديث هذا وعد إن لم يقم على الكبائر، أما من أقام على الكبائر ما تغفر له ذنوبه، يقول النبي ﷺ: الصلوات الخمس، والجمعة إلى الجمعة، ورمضان إلى رمضان، كفارات لما بينهن إذا اجتنب الكبائر والله يقول في كتابه العظيم يخاطب المؤمنين وغيرهم: إِنْ تَجْتَنِبُوا كَبَائِرَ مَا تُنْهَوْنَ عَنْهُ نُكَفِّرْ عَنْكُمْ سَيِّئَاتِكُمْ وَنُدْخِلْكُمْ مُدْخَلًا كَرِيمًا[النساء:31]. فشرط في تكفير السيئات، ودخول الجنات اجتناب الكبائر، أما من لم يجتبنها مات وهو مقيم عليها من الزنا أو العقوق للوالدين أو أكل الربا أو قطيعة الرحم، أو ما أشبه ذلك، فهذا معلق أمره وعلى خطر، لا تكن حسناته مكفرة، بل هو على خطر حتى يجتنب الكبائر.  إذا كانت الصلاة وهي عمود الإسلام لا تكفر إلا باجتناب الكبائر، وهكذا صوم رمضان فكيف بغير ذلك؟ يقول ﷺ: الصلوات الخمس، والجمعة إلى الجمعة، ورمضان إلى رمضان كفارات لما بينهن إذا اجتنب الكبائر وفي لفظ: ما لم تغش الكبائر أخرجه مسلم في الصحيح، فهذا يدل على أن أحاديث الوعد بالمغفرة والرحمة لمن استغفر أو فعل كذا وكذا مشروط باجتناب الكبائر، ونص الآية واضح في ذلك، يقول سبحانه: إِنْ تَجْتَنِبُوا كَبَائِرَ مَا تُنْهَوْنَ عَنْهُ نُكَفِّرْ عَنْكُمْ سَيِّئَاتِكُمْ وَنُدْخِلْكُمْ مُدْخَلًا كَرِيمًا [النساء:31]. فالأحاديث التي فيها تكفير السيئات، وحط الخطايا لمن فعل كذا، أو فعل كذا، يعني: ما لم يصر على كبيرة، ما لم يكن عنده إصرار على كبيرة من الكبائر، فإذا أصر على الكبيرة لم تكفر له الذنوب بذلك العمل، نسأل الله لنا ولجميع المسلمين العافية، نعم.","link":"https://binbaz.org.sa/fatwas/12906/ما-معنى-من-قرا-اية-الكرسي-دبر-كل-صلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_553/55320.mp3","categories":["مسائل متفرقة في الصلاة","شروح الحديث"]},{"id":14582,"question":"نختم هذا اللقاء بهذا السؤال سماحة الشيخ، تقول السائلة: هل صحيح بأن من قرأ قًلْ هُوَ اللهُ أَحّد [الإخلاص: 1] عشر مرات بنى الله له قصرًا في الجنة؟","title":"ما صحة فضيلة من قرأ سورة الأخلاص عشر مرات؟","answer":"الجواب: هذه السورة عظيمة، وهي تعدل ثلث القرآن، كما قاله النبي ﷺ، فإذا قرأها الإنسان كثيرًا ففيها فضل عظيم.\nأما قراءتها عشر أنه ورد فيه: يبنى قصر في الجنة فلا أعلم في هذا حديثًا صحيحًا، لكن قراءتها كثيرًا فيه خير كثير؛ لأنها سورة عظيمة تعدل ثلث القرآن.  فإذا قرأها الإنسان في بعض الأحيان، وكررها بينه وبين نفسه في بيته، يكررها في الليل، أو في النهار فكل هذا لا بأس به؛ لأنها سورة عظيمة.","link":"https://binbaz.org.sa/fatwas/13079/ما-صحة-فضيلة-من-قرا-سورة-الاخلاص-عشر-مرات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_557/55708.mp3","categories":["الحكم على الأحاديث","شروح الحديث","القرآن وعلومه"]},{"id":14646,"question":"أيضًا يطلبون شرح حديث آخر: بكروا بالصلاة في يوم الغيم فإنه من ترك صلاة العصر فقد حبط عمله هل ترك الصلاة هنا مع الجماعة، أم يعني: من ترك الصلاة، ثم قضاها وهو غير متعمد؟","title":"شرح حديث \"من ترك صلاة العصر...\"","answer":"الجواب: الحديث له لفظان:  أحدهما: يقول ﷺ: من فاتته صلاة العصر فكأنما وتر أهله وماله إذا فاتته مع الجماعة أو في الوقت فكأنما وتر سلب أهل وماله، يعني: مصيبة عظيم نسأل الله العافية.  واللفظ الثاني: من ترك صلاة العصر حبط عمله هذا يدل على أن ترك الصلاة كفر إذا تركها عمدًا، عزم على تركها بالكلية، فهذا يحبط عمله لأن تركها كفر، إذا عزم على تركها بالكلية صار كفرًا؛ لقول النبي ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة رواه مسلم في صحيحه، وقال -عليه الصلاة والسلام-: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر إذا تعمد تركها بالكلية كفر، أما إذا تأخر، وهو يريد الصلاة فهذا يكون عاصيًا ولا يكفر، لكن يكون عاصيًا بعمله السيئ، يجب عليه فعلها في الوقت، نسأل الله العافية، نعم. المقدم: جزاكم الله خيرًا، نسأل الله السلامة.","link":"https://binbaz.org.sa/fatwas/13140/شرح-حديث-من-ترك-صلاة-العصر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_636/nour_63612.mp3","categories":["شروح الحديث"]},{"id":14649,"question":"في حديث الرسول ﷺ: آية المنافق ثلاث: إذا حدث كذب، وإذا عاهد أخلف، وإذا خاصم فجر هل تتفضلون بتوضيح هذا الحديث وخصوصًا: إذا خاصم فجر فهل يعني الرسول ﷺ سرعة الغضب، أم ماذا يعني؟","title":"شرح حديث \"آية المنافق ثلاث...\"","answer":"الجواب: الرسول ﷺ أخبر عن المنافقين بخصال ليحذرنا منها، حتى نبتعد عنها، يقول ﷺ: آية المنافق ثلاث: إذا حدث كذب، وإذا وعد أخلف، وإذا اؤتمن خان يحذرنا من إخلاف الوعد، ومن الكذب في الحديث والأخبار، ومن الخيانة في الأمانة، وأنها من خصال أهل النفاق نعوذ بالله فيجب الحذر منها. ويقول ﷺ: أربع من كن فيه كان منافقًا خالصًا، ومن كانت فيه خصلة منهن كانت فيه خصلة من النفاق، حتى يدعها: إذا حدث كذب، وإذا وعد أخلف، وإذا خاصم فجر، وإذا عاهد غدر رواه الشيخان من حديث عبدالله بن عمر -رضي الله عنهما-، فهذا يدل على أن المنافق من خصاله إخلاف الوعد، والكذب في الحديث، والخيانة في الأمانة، وأنه إذا خاصم فجر، وفجوره التوسع في المعصية والكذب. وإذا عاهد غدر إذا عاهد إخوانه، أو عاهد الكفار غدر بهم، ولم يوف بالعهد لضعف إيمانه، أو عدم إيمانه. وإذا خاصم كذب في خصومته وتوسع في الكذب والفجور وظلم؛ لعدم إيمانه، أو لضعف إيمانه، فالفجور هو التوسع في المعصية وإظهارها -نسأل الله العافية- كانفجار الماء.  فالحاصل: أنه يتوسع في الكذب والعدوان على الخصم واللدد في الخصومة لضعف إيمانه، أو عدم إيمانه، نعوذ بالله، هكذا شأن المنافقين لعدم إيمانهم، ولهم صفات بيَّنها الله في القرآن غير هذه الصفات، قال تعالى: إِنَّ الْمُنَافِقِينَ يُخَادِعُونَ اللَّهَ وَهُوَ خَادِعُهُمْ وَإِذَا قَامُوا إِلَى الصَّلاةِ قَامُوا كُسَالَى يُرَاءُونَ النَّاسَ وَلا يَذْكُرُونَ اللَّهَ إِلَّا قَلِيلًا ۝ مُذَبْذَبِينَ بَيْنَ ذَلِكَ لا إِلَى هَؤُلاءِ وَلا إِلَى هَؤُلاءِ[النساء:142-143] هذه من صفاتهم، كالخداع والمكر والعدوان على الناس. ومن خصالهم: التكاسل عن الصلاة، والتثاقل عنها، وقلة الذكر، يعني: يغلب عليهم الغفلة.  ومن خصالهم: الرياء في أعمالهم، يصلون رياءً، يتصدقون رياءً، يذكرون الله رياءً.  ومن خصالهم الخبيثة: أنهم ما لهم ثبات عندهم تردد تارة مع المؤمنين، وتارة مع الكافرين، قد ترددوا في دينهم وتذبذبوا؛ ولهذا قال: مذبذبين ليس لهم ثبات، لا مع أهل الحق، ولا مع أهل الباطل، هم مع من رأوا المصلحة أن يكونوا معه في دنياهم، فإن نصر الكفار صاروا معهم، وإن نصر المؤمنون صاروا معهم لطلب الدنيا والأمان، ونحو ذلك، نسأل الله العافية، هذه حالهم عدم الثبات، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13138/شرح-حديث-اية-المنافق-ثلاث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_636/nour_63611.mp3","categories":["الأخلاق المذمومة","شروح الحديث"]},{"id":14670,"question":"سمعت حديثًا عن رسول الله ﷺ، عن ابن مسعود  قال: خط لنا رسول الله ﷺ خطاً، وقال: (هذا طريق الحق) وخط خطوطًا عديدة، وقال: (هذه السبل، على رأس كل منها شيطان، يزينها لسالكيها) هذا معنى ما سمعت، أرجو أن توضحوا لي معنى ذلكم الحديث، جزاكم الله خيرًا.","title":"معنى حديث: \"أن الرسول ﷺ خط خطًا...\"","answer":"الجواب: هذا الحديث صحيح، رواه الدارمي وغيره، وهو من تفسير قوله -جل وعلا-: وَأَنَّ هَذَا صِرَاطِي مُسْتَقِيمًا فَاتَّبِعُوهُ وَلا تَتَّبِعُوا السُّبُلَ فَتَفَرَّقَ بِكُمْ عَنْ سَبِيلِهِ ذَلِكُمْ وَصَّاكُمْ بِهِ لَعَلَّكُمْ تَتَّقُونَ [الأنعام:153] وفي الحديث: أن الرسول ﷺ خط خطًا مستقيمًا، فقال: هذا سبيل الله ثم خط خطوطًا عن يمينه وشماله، فقال: هذه السبل، وعلى كل سبيل شيطان يدعو إليه ثم قرأ الآية: وَأَنَّ هَذَا صِرَاطِي مُسْتَقِيمًا فَاتَّبِعُوهُ [الأنعام:153] الآية. والمعنى: أن صراط الله طريق واضح، يوصل من سلكه إلى الجنة والكرامة. أما الطرق التي عن يمينه وشماله فهي البدع والشبهات والشهوات المحرمة التي يسلكها أكثر الخلق، فهي توصل من سلكها إلى النار، نعوذ بالله من ذلك. فالواجب على كل مسلم أن يسلك الطريق السوي، وهو صراط الله الذي دل عليه كتاب الله وسنة الرسول -عليه الصلاة والسلام-، وهو فعل ما أمر الله به ورسوله، وترك ما نهى الله عنه ورسوله، عن إخلاص لله، وعن إيمان به ومحبة له ، وعن موافقة لما شرعه رسوله -عليه الصلاة والسلام-، هذا هو صراط الله، وهذا هو سبيله. أما ما خالف ذلك من المعاصي والبدع فهي السبل التي نهى عنها الرب ، وحذر منها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13167/معنى-حديث-ان-الرسول-ﷺ-خط-خطا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_628/nour_62802.mp3","categories":["شروح الحديث"]},{"id":14671,"question":"رسالة وصلت إلى البرنامج من المستمع (س. ح. ن) يسأل جمعًا من الأسئلة، ويقول: ما معنى هذا الحديث الشريف: عن أم كلثوم -رضي الله عنها- أنها سمعت رسول الله ﷺ يقول: \"لم يرخص في شيء مما يقول الناس إلا في ثلاث: يعني الحرب، والإصلاح بين الناس، وحديث الزوجين لبعضهما\"؟اشرحوا لنا هذا لو تكرمتم.","title":"شرح حديث الأمور التي رُخِّص الكذب فيها","answer":"الجواب: الحديث صحيح، رواه الشيخان، من حديث أم كلثوم -رضي الله عنها- بنت عقبة بن أبي معيط، أنها سمعت النبي يقول ﷺ: ليس الكذاب الذي يصلح بين الناس فيقول خيرًا، وينوي خيرًا قالت: \"ولم أسمعه يرخص في شيء من الكذب إلا في ثلاث: في الحرب، وفي الإصلاح بين الناس، وفي حديث الرجل لامرأته والمرأة لزوجها\" رواه مسلم بهذه الزيادة. فهذا يدل على أن المصلح بين الناس ليس بكذاب، الذي يصلح بين الناس: بين القبيلتين، أو بين الأسرتين، أو بين شخصين تنازعا فأصلح بينهما وكذب فإن هذا لا يضره؛ لأنه أراد الإصلاح فإذا أتى إحدى القبيلتين أو إحدى الأسرتين أو أحد الشخصين فقال له قولًا طيبًا عن صاحبه، وأنه يرغب في الصلح، وأنه يثني عليك، وأنه يحب مصالحتك، ثم جاء الآخر وقال له كلامًا طيبًا حتى أصلح بينهما فهذا طيب؛ لأنه لا يضر أحدًا بذلك، ينفع المتنازعين، ولا يضر أحدًا، وهكذا إذا جاء الأسرة وقال عن الأسرة الثانية: إنها تثني عليك، وإنها تدعو لك، وإنها تحب المصالحة معك، ولم يقع هذا، ولكن هو كذب هذا الشيء ليصلح بينهما، هو مأجور في هذا، ولا شيء عليه، وهكذا بين القبيلتين جاء القبيلة وقال: إن القبيلة الفلانية تثني عليكم، وتدعو لكم، وترغب الإصلاح، ثم أتى الأخرى وقال لها مثل ذلك، حتى سعى بينهما بالصلح، وإزالة الشحناء هو مأجور بذلك، إذا كان كذبه لا يضر أحدًا غيرهم، لا يضر أحدًا من الناس، وإنما ينفعهم ويجمعهم، ويزيل الشحناء بينهم، فهو مأجور، وليس بكذاب كذبًا يضره، أو يأثم به. الخصلة الثانية في الحرب إذا كان في الحرب بأن قال للغزاة: إنا قافلون غدًا؛ لينظر، قافلون: يعني: منصرفون راجعون لينظر ماذا عند العدو؟ إذا سمع خبر القفول؛ لعله يخرج من حصونه، لعله يتبين له شيء يعينه على الجهاد، ولينظر ما عند الجيش من النشاط والهمة العالية، أو عدم النشاط في الحرب، فإذا كذب لمصلحة فلا بأس بذلك في الحرب؛ لأنه يفيد، الحرب خدعة. وهكذا لو قفل راجعًا وقال: إنا راجعون، حتى يخرج العدو من حصونه، ومن مترساته حتى يبرز، ثم يكر عليهم المسلمون ويقاتلونهم إذا برزوا هذا أيضًا لا بأس به، كذب فيه مصلحة للمسلمين، فلا يضر ذلك. وكان النبي ﷺ إذا أراد غزوة ورى بغيرها، حتى يهجم على العدو، وهو على غرة إذا أراد الشمال مثلًا، قال: إنا سوف نغزو الجنوب، ونغزو جهة الغرب، جهة الشرق، حتى لا يستعد له العدو، حتى يهجم عليهم على غرة إذا كانوا قد بلغوا ودعوا إلى الله وأصروا فلا بأس أن يهاجموا على غرة. أما الثالثة فهي: حديث الرجل امرأته، والمرأة زوجها لا بأس بذلك، فإن الرجل مع زوجته قد يحصل بينهما مشاكل ونزاع عند ملابس أو طعام أو زيارة، أو ما أشبه ذلك، فيقول لها: سوف أفعل كذا وكذا، سوف أشتري لك كذا، وسوف أفعل كذا مما يرضيها، حتى يزول النزاع وحتى تزول الشحناء، أو تقول هي كذلك: سوف أفعل كذا، سوف لا أخرج إلا بإذنك، وهي عازمة أنها سوف تخالفه، لكن تريد أن يرضى، أو سوف أنفذ ما قلته في كذا وكذا وكذا، وإن كان في اعتقادها، وفي عزمها ألا تنفذ، لكن تريد أن تكسب رضاه، حتى تزول الشحناء والعداوة فلا بأس بهذا؛ لأن هذا كذب لمصلحتهما لا يضر غيرهما، فإذا كان كذبهما في مصلحتهما، ولا يضر غيرهما فلا حرج فيه، كما قاله النبي ﷺ؛ لأنه إصلاح محض ليس فيه مضرة على أحد، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13189/شرح-حديث-الامور-التي-رخص-الكذب-فيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_628/nour_62810.mp3","categories":["شروح الحديث"]},{"id":14739,"question":"المستمع يوسف عمر يوسف قلوص، يسأل ويقول: هل هذا حديث: من سن سنة حسنة فله أجرها وأجر من عمل بها، ومن سن سنة سيئة فله وزرها ووزر من عمل بها ما معنى هذا -جزاكم الله خيرًا- إذا كان حديثًا؟ وكيف يكون الابتداع حسنًا؟ جزاكم الله خيرًا.","title":"الحكم على بحديث: \"من سن في الإسلام...\" ومعنا","answer":"الجواب: الحديث صحيح، رواه مسلم في صحيحه، ومعناه: من سن في الإسلام سنة حسنة يعني: أظهرها وأحياها وبينها للناس عند غفلتهم عنها، أو جهلهم بها، وليس المقصود الابتداع، الابتداع منهي عنه، الابتداع منكر، الرسول  قال في الحديث الصحيح: من عمل عملًا ليس عليه أمرنا فهو رد وقال -عليه الصلاة والسلام-: كل بدعة ضلالة. فليس المراد بالحديث البدعة، وإنما المراد بالحديث إحياء السنن وإظهارها، وبيانها للناس، ويدل على هذا سبب الحديث؛ فإن سبب الحديث أنه خطب الناس -عليه الصلاة والسلام- ودعاهم إلى الصدقة، فجاء بعض الناس بصدقة من الورق، من الفضة كادت كفه تعجز عنها، فتتابع الناس لما رأوه، فقال عند ذلك -عليه الصلاة والسلام-: من سن في الإسلام سنة حسنة كان له أجرها وأجر من عملها من بعده لا ينقص من أجورهم شيئًا، ومن سن في الإسلام سنة سيئة كان عليه وزرها ووزر من عملها من بعده لا ينقص من أوزارهم شيئًا. فالمقصود: بالسنة الحسنة يعني: إظهار السنن وإحياؤها، والدعوة إليها بالقول والعمل، وليس المقصود البدع، نعم بإجماع المسلمين. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13241/الحكم-على-بحديث-من-سن-في-الاسلام-ومعنا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_637/nour_63719.mp3","categories":["شروح الحديث","الحكم على الأحاديث"]},{"id":14761,"question":"المستمع عبدالعزيز بن سليمان القصير، بعث برسالة ضمنها جمعًا من الأسئلة، في أحدها يقول:ورد عن النبي ﷺ في حديث صحيح أنه قال: من رآني في المنام فسيراني في اليقظة، أو كأنما رآني في اليقظة، لا يتمثل الشيطان بي متفق عليه.فهل يجوز للمؤمن الصالح إذا شاهد شيئًا من ذلك وصفه للمسلمين؟جزاكم الله خيرًا.الشيخ: أعد، بعد. يقول ورد عن النبي ﷺ في حديث صحيح أنه قال: من رآني في المنام فسيراني في اليقظة، أو كأنما رآني في اليقظة، لا يتمثل الشيطان بي متفق عليه.فهل يجوز للمؤمن الصالح إذا شاهد شيئًا من ذلك وصفه للمسلمين؟","title":"هل يجوزلمن رأى النبي ﷺ في المنام التكلم بذلك؟","answer":"الجواب: لا حرج في ذلك، الحديث صحيح، يقول: فإن الشيطان لا يتمثل في صورتي وهو شك من الراوي، هل قال: (فسيراني) أو فكأنما رآني والصواب: فقد رآني كما في الروايات الأخرى، من رآني في المنام فقد رآني -يعني رآني على الحقيقة- فإن الشيطان لا يتمثل في صورتي. أما: (فسيراني) هذه فيها شك، ولو صحت لكان المعنى أن يراه في الآخرة، يعني: إذا كان مؤمنًا، وأما في الدنيا ما يراه في الدنيا؛ لأنه بعد الموت لن يعود إلى الدنيا -عليه الصلاة والسلام-، إنما يراه المؤمنون يوم القيامة، وهو في الآخرة -عليه الصلاة والسلام-، فرواية: (فسيراني) إما أنها غلط من بعض الرواة وشك في الرواية، كما جاء في الحديث الشك أو فقد رآن وإما أن يكون المراد: (فسيراني) يعني: في الآخرة، المؤمنون يرونه في الآخرة، فإذا مات على الإيمان فهو يراه، وهذه بشارة أنه يموت على الإيمان لو صحت الرواية، حتى يرى النبي -عليه الصلاة والسلام-. فالحاصل: أنه إذا رآه على صورته فقد رآه، فإن الشيطان لا يتمثل به، وأما إذا رآه على غير صورته ما يكون رآه، لو رآه شايب -يعني لحيته بيضاء- أو رآه شاب ما له لحية، ما يكون رأى النبي ﷺ؛ لأن النبي ﷺ له لحية كثة ليس فيها إلا شعرات يسيرة من الشيب، فإذا رآه على صورته فإنه سيراه يوم القيامة، وفي الجنة إن مات على الإسلام، أو فقد رآه في الحقيقة؛ لأن الشيطان لا يتمثل في صورته، وهذا يؤيد أن المراد: فقد رآني وأن رواية: (فسيراني) ضعيفة، وأتى بها الراوي شكًا، والمحفوظ فقد رآني يعني: رأى الحقيقة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13249/هل-يجوزلمن-راى-النبي-ﷺ-في-المنام-التكلم-بذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_490/49011.mp3","categories":["شروح الحديث"]},{"id":14771,"question":"رسالة وصلت من المستمع أنهار من جمهورية مصر العربية، ضمنها جمعًا من الأسئلة من بينها يقول:قال رسول الله ﷺ: يأتي زمان على أمتي القابض على دينه كالقابض على جمرة من النار فهل هذا الحديث صحيح؟ وإذا كان صحيحًا فاشرحوه لنا. جزاكم الله خيرًا.","title":"الحكم على حديث: \"يأتي على الناس...\" ومعناه","answer":"الجواب: لا بأس به فيما نعلم، لا بأس به، حسن، حديث جيد.  ومعناه: أنه يأتي عليه من البلايا والمحن والفتن التي تؤذيه وتضره، ما يكون فيها معها كالقابض على الجمر، من شدة صبره على دينه وعلى إيمانه وثباته عليه، كأنه قابض على الجمر من شدة ما يصيبه من الآلام والشدائد في ذلك، وقت الفتن وقت الأذى من الأعداء، والعياذ بالله. وهذا واقع، فينبغي للعاقل إذا بلي بهذا أن يتصبر، فكم بلي بهذا في أوقات الفتن، وفي الحروب، وفي غير ذلك ممن مضى قبلنا وفي وقتنا. فالحاصل: أن من ابتلي في أي زمان عليه أن يصبر، قد يبتلى ممن يمنعه من الصلاة، أو يؤذيه إذا صلى، قد يبتلى بمن يؤذيه إذا صام فليصبر، يصوم ولو سرًا، فإذا أوذي في ذلك لا يضره، وكذلك يصلي، ولو أوذي يصبر ويتحمل، ولا يدع الصلاة، وهكذا، الله المستعان. المقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13266/الحكم-على-حديث-ياتي-على-الناس-ومعناه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_490/49016.mp3","categories":["شروح الحديث","الحكم على الأحاديث"]},{"id":15113,"question":"الأخ المستمع: غازي جميل محمد كتبي، بعث يقول: أرجو أن تتفضلوا بشرح حديث رسول الله ﷺ : من نام عن صلاة، أو سها عنها، فليصلها متى قام أو ذكرها أو كما قال ﷺ؟","title":"شرح حديث: \"من نام عن صلاة...\"","answer":"الجواب: يقول ﷺ: من نام عن الصلاة أو نسيها فليصلها إذا ذكرها، لا كفارة لها إلا ذلك فإذا نام الإنسان عن الفجر صلاها إذا استيقظ، ولو في الضحى، ولو الظهر متى استيقظ صلاها، أو شغل عنها نسيها، صار مشغولًا بأشياء ونسي الظهر أو العصر، متى انتبه، وذكر بادر بالصلاة، ولو مضى على ذلك يوم، أو يومان أو أكثر، متى ذكر وجب عليه البدار بالصلاة. أما التعمد فلا يجوز، ليس له أن يتعمد ترك الصلاة عن وقتها، لا ظهر ولا عصر ولا مغرب ولا عشاء ولا فجر، يجب أن يصليها في الوقت، إلا إذا كان مسافرًا أو مريضًا، لا بأس أن يجمع بين الصلاتين، في المغرب، والعشاء، والظهر، والعصر. أما إنسان مقيم صحيح، فليس له أن يجمع بين الصلاتين، وليس له أن يؤخر الصلاة عن وقتها، بل يجب عليه وجوبًا؛ أن يصليها في وقتها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13613/شرح-حديث-من-نام-عن-صلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_494/49410.mp3","categories":["شروح الحديث"]},{"id":15182,"question":"أيضًا محمد طه، من سوريا، لديه سؤال آخر، يقول: قال ﷺ: يقاتلكم اليهود وتنتصرون عليهم يقول: إنه يتوقع أنه إذا كان هذا الحديث صحيحًا، فعهدنا الذي نعيشه الآن هو العهد الذي يتحدث عنه ﷺ، فما هو رأيكم؟ أرجو أن توضحوا لي هذا الحديث؛ لأنه دائمًا يقع بيننا مشادة في الكلام عنه.وفقكم الله.","title":"بيان حديث قتال المسلمين لليهود، وفي أي زمن؟","answer":"الجواب: الحديث صحيح، رواه الشيخان البخاري ومسلم في الصحيحين وغيرهما، ولفظه: يقاتل المسلمون اليهود، فينصرون عليهم، حتى يقول الشجر والحجر: يا مسلم، يا عبدالله، هذا يهودي تعال فاقتله أو قريب من هذا اللفظ. فالمقصود: أنه ثابت عن رسول الله ﷺ، وأن المسلمين يقاتلون اليهود، وأنهم ينصرون عليهم حتى إن الحجر والشجر يقول للمسلم: يا عبدالله، تعال هذا يهودي تعال فاقتله. أما كون ذلك في وقتنا هذا محل نظر، فإن الذي يقاتلهم المسلمون، والمقاتلون الآن ليسوا على المستوى الكامل من جهة الإسلام، فيهم المسلم وفيهم غير المسلم، وليس هناك تطبيق فيما بلغنا من المسلمين هناك للشريعة المطهرة كما ينبغي، بل هناك العاصي، وهناك الكافر، وهناك المسلم المستقيم، فالقتال الذي أخبر به النبي ﷺ يكون من المسلمين الملتزمين المستقيمين، فلهذا ينصرهم الله على اليهود بسبب استقامتهم على دين الإسلام ونصرهم لدين الله، فيحتمل أن يكون هذا بعد وقت تتحسن فيه أحوال المسلمين، ويجتمعون على الحق والهدى فينصرون عليهم، ويحتمل أن هذا في وقت عيسى كما هو معلوم، فإنه في وقت عيسى يقتل اليهود، وينصر الله عيسى والمسلمين عليهم، ويقتل الدجال هذا لا شك في وقت عيسى، لكن يحتمل أن يقع قبل عيسى، وأن المسلمين تتحسن أحوالهم وتستقيم أمورهم على شريعة الله، ويقودهم أمير صالح، أو إمام صالح يقودهم إلى الحق والهدى، ويستقيمون على شريعة الله، ثم يتوجهون لقتال اليهود، فينصرون عليهم، هذا كله محل احتمال. أما في وقت عيسى فلا شك أنه يقتلهم، وأنه ينصر عليهم -عليه الصلاة والسلام- مع المسلمين عند قتله للدجال، نعم.","link":"https://binbaz.org.sa/fatwas/13685/بيان-حديث-قتال-المسلمين-لليهود-وفي-اي-زمن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_666/nour_66602.mp3","categories":["شروح الحديث","الجهاد والسير"]},{"id":15314,"question":"ما هي السبع الموبقات؟ وجزاكم الله عني كل خير.","title":"ما هي السبع الموبقات؟","answer":"الجواب: ثبت عن الرسول ﷺ أنه قال: اجتنبوا السبع الموبقات -يعني: المهلكات- قلنا: وما هن يا رسول الله؟ قال: الشرك بالله، والسحر، وقتل النفس التي حرم الله إلا بالحق، وأكل الربا، وأكل مال اليتيم، والتولي يوم الزحف -يعني: يوم الحرب، يعني: الجهاد- وقذف المحصنات الغافلات المؤمنات هذه السبع. يقول ﷺ: اجتنبوا يعني: ابتعدوا عن السبع الموبقات اجتنبوا السبع الموبقات يعني: اتركوها واحذروها، ثم فسرها فقال: الشرك بالله هذا أعظم الذنوب، الشرك هو أعظمها وأشدها، ثم السحر وهو من الشرك؛ لأن السحر يتوصل إليه بعبادة الشياطين والجن، والتقرب إليهم، وقتل النفس التي حرم الله إلا بالحق هذه الثالثة، وأكل الربا الرابعة، وأكل مال اليتيم الخامسة والتولي يوم الزحف السادسة، والسابعة: قذف المحصنات الغافلات المؤمنات يعني: قذفهن بالفاحشة، وهكذا قذف المحصن الرجل، من السبع الموبقات، نسأل الله العافية، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13814/ما-هي-السبع-الموبقات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_566/56609.mp3","categories":["شروح الحديث"]},{"id":15447,"question":"هذا محمد عبداللَه من القصيم، يقول: لي مجموعة من الأسئلة عن الاستئذان، يقول في سؤاله الأول: سماحة الشيخ، قال ﷺ: الاستئذان ثلاثًا، فإن أذن لك وإلا فارجع هل من وقفة مع هذا الحديث الشريف؟","title":"وقفة مع حديث: الاستئذان ثلاثًا","answer":"الجواب: نعم؛ لأن المستأذن عليهم قد يكونوا مشغولين، قد يكونون مشغولين، فإذا استأذنت ثلاث، ولم يُرد عليك، فانصرف، حتى لا تعطل نفسك، ولا تؤذي أهل البيت، تقول: السلام عليكم، ثم يعيدها مرة ثانية، ثم ثالثة، فإن لم يرد عليها ترك؛ لئلا يكلفهم، أو يؤذيهم، قد يكونون مشغولين، والحديث صحيح عن النبي ﷺ، وفي ذلك خير للمسلمين، ومنفعة كبيرة؛ لأن الإلحاح قد يضر أهل البيت، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13960/وقفة-مع-حديث-الاستىذان-ثلاثا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_568/56807.mp3","categories":["الآداب والأخلاق المحمودة","شروح الحديث"]},{"id":15479,"question":"سؤاله الآخر يقول: سمعت المذيع وكان يتكلم في فضل يوم الجمعة؛ وذلك في يوم الجمعة الثاني عشر من ربيع الأول، وقد أورد حديثًا يقول: فأكثروا علي من الصلاة فيه، فإن صلاتكم معروضة علي قالوا: يا رسول الله، وكيف تعرض عليك صلاتنا وقد أرمت؟ فقال: إن الله  حرم على الأرض أن تأكل أجساد الأنبياء رواه الخمسة إلا الترمذي، أليس هذا يتعارض مع الآية الكريمة التي يقول الله فيها: قُلْ إِنَّمَا أَنَا بَشَرٌ مِثْلُكُمْ[الكهف:110] وقوله: وَإِنَّا لَجَاعِلُونَ مَا عَلَيْهَا صَعِيدًا جُرُزًا[الكهف:8] وأنه لما دخل عليه العباس عمه حينما مات ومكث ثلاثة أيام قبل أن يدفن، وكان واضعًا يديه على أنفه، وقال له: عجلوا بدفن صاحبكم، والله إنه ليأسن كما يأسن سائر البشر وهذا الحديث الذي سمعته موجود في كتاب نيل الأوطار شرح منتقى الأخبار، والحديث أخرجه أيضًا ابن حبان في صحيحه، والحاكم في مستدركه، وقال: صحيح على شرط البخاري، ولم يخرجاه، وذكره ابن أبي حاتم في العلل، وحكي عن أبيه بأنه حديث منكر؛ لأن في إسناده عبد الرحمن بن يزيد بن جابر، وهو منكر الحديث، وقال ابن العربي: إن الحديث لم يثبت، وأسأل الله تعالى أن يوفقني وإياكم لما يحبه ويرضاه، نعم؟","title":"الجمع بين: «الأرض لا تأكل أجساد الأنبياء» وبشرية الأنبياء","answer":"الجواب: الحديث المذكور معروف عند أهل العلم، ولا بأس به عند أهل العلم، ولا نكارة في ذلك، فإن الله -جل وعلا- له أن يخص من شاء من عباده بما يشاء  فإذا خص الأنبياء بتحريم أجسادهم على الأرض، فلا غرابة في ذلك؛ لما لهم لديه من الكرامة. والصلاة والسلام عليه مشروعة مطلقًا، ولو فرضنا أن الجسد قد أكلته الأرض، كما تأكل أجساد الناس الآخرين، فإن هذا لا يمنع من الصلاة والسلام عليه، ولا يمنع أيضًا من تخصيص الجمعة بذلك؛ لما جاء في الحديث، فإن الصلاة والسلام عليه مشروعان دائمًا -عليه الصلاة والسلام- في حياته، وبعد وفاته -عليه الصلاة والسلام-، وقد قال الله : إِنَّ اللَّهَ وَمَلائِكَتَهُ يُصَلُّونَ عَلَى النَّبِيِّ يَا أَيُّهَا الَّذِينَ آمَنُوا صَلُّوا عَلَيْهِ وَسَلِّمُوا تَسْلِيمًا[الأحزاب:56] اللهم صل عليه وسلم صلاة وسلامًا دائمين إلى يوم الدين، وقال -عليه الصلاة والسلام- كما روى مسلم في الصحيح: من صلى علي واحدة صلى الله عليه بها عشرًا. فالصلاة والسلام عليه أمر مشروع، في حياته وبعد وفاته، حال كونه في البرزخ، وفي غير ذلك، فهذا أمر مشروع ومعلوم. أما كون جسده يبقى فهو في هذا الحديث، وسنده لا بأس به عند أهل العلم. وأما قول العباس فلا أعلم إلى يومي هذا صحته، ولم أتتبع أسانيده، ولو فرضنا صحة أثر العباس، فإنه لا ينافي ما قاله العباس قد يعتري الجسد ما يعتريه، ولكنه يسلم ويبقى ويحرم على الأرض أن تأكله، ويزول ما يعتريه من تغير، ورائحة تزول، فإن الله على كل شيء قدير ، فإذا وضع في القبر، ففي الإمكان أن تزول هذه الرائحة وهذا التغير، وأن يبقى الجسد سليمًا طريًا، ليس في هذا ما يمنع، ليس في الشرع ولا في العقل ما يمنع ذلك. والمقصود: أن الصلاة والسلام عليه مشروعان مطلقًا، سواءً بقي الجسد، أو لم يبق الجسد، وكونه تعرض عليه، المهم الروح، فإن روحه باقية، وهكذا الأرواح باقية عند أهل السنة والجماعة، أرواح المؤمنين في الجنة، وأرواح الكفار في النار، وروحه ﷺ في أعلى عليين -عليه الصلاة والسلام-، وأرواح المؤمنين في صفة طائر يعلق في شجر الجنة، وأرواح الشهداء تسرح في الجنة حيث شاءت، ثم ترجع إلى قناديل معلقة تحت العرش، وهي في أجواف طير خضر، كما جاء به الحديث الشريف. فالمقصود: أن الأرواح باقية، وفي الإمكان عرض الصلاة والسلام عليه -عليه الصلاة والسلام-، وإن ذهب الجسد، ولكن حديث: إن الله حرم على الأرض أن تأكل أجساد الأنبياء لا بأس به، فالأصل الأخذ به، والبقاء عليه، حتى يعلم بالنص الذي لا شك فيه ما يخالف ذلك. وقوله ﷺ: إن الله حرم على الأرض أن تأكل أجساد الأنبياء خبر منه ﷺ وهو لا ينطق عن الهوى: إِنْ هُوَ إِلَّا وَحْيٌ يُوحَى[النجم:4] فمتى سلم الخبر من العلة، وهو عند أهل العلم -في ظاهر أسانيده- صحيح، ولا بأس به. وإذا ثبت أثر العباس فإن ما قاله العباس -لو ثبت ووقع- فإنه لا يمنع من بقاء الجسد، وزوال هذا الأثر الذي قاله العباس مما يعتري الأجساد، قد يعتريه ما يعتريه، ويزول ولا يبقى له أثر، وقد يكون العباس قاله عن اجتهاد منه، واعتقاد أنه ﷺ كالناس في هذا الأمر، ولم يطلع على الخبر الذي رواه أوس بن أبي أوس وهو خبر: إن الله حرم على الأرض أن تأكل أجساد الأنبياء. فالحاصل: أن العباس قال ذلك إذا ثبت عنه عن اجتهاد، وعن اعتبار له بغيره من الناس، ولله أن يخصه بشيء دون بقية الناس كما خصه بأشياء دون بقية الأنبياء -عليه الصلاة والسلام-، فهذا كله لا يوجب اعتراضًا، ولا يقدح في هذا الحديث لو صح الأثر عن العباس، نعم. المقدم: نعم، بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/14006/الجمع-بين-الارض-لا-تاكل-اجساد-الانبياء-وبشرية-الانبياء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_689/nour_68902.mp3","categories":["شروح الحديث"]},{"id":15527,"question":"الحديث الذي ما معناه: بأن «الذي يصلي الفجر في جماعة، ثم يجلس في مكانه يذكر الله، حتى تطلع الشمس، ثم يصلي ركعتين، كانت له كأجر حجة وعمرة تامة تامة» هل معنى ذلك بأن الذي يغير المكان في المسجد لمكان أكثر راحة وهدوء يحجب عن هذا الفضل؟","title":"ثواب الجالس لذكر الله بعد الفجر باقٍ وإن غير مكانه","answer":"الجواب: الظاهر أنه لا يحجب؛ لأن المسجد كله مصلى، المسجد كله مصلى، فإذا انتقل من مكان إلى مكان؛ ليستند على عمود، أو غيره، أو لأنه أريح أبعد عن حوله من القراء، حتى لا يشوش عليهم، كله لا بأس، لا حرج، يحصل له الفضل -إن شاء الله-، نعم. المقدم: حفظكم الله، لو ذهب إلى بيته يا سماحة الشيخ لذكر الله هناك في غرفة من غرف بيته، هل يشمله هذا الحديث؟ الشيخ: الظاهر إنه لا يشمله؛ لأنه ذهب عن مصلاه، نعم. المقدم: حفظكم الله، وسدد خطاكم.","link":"https://binbaz.org.sa/fatwas/14072/ثواب-الجالس-لذكر-الله-بعد-الفجر-باق-وان-غير-مكانه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_691/nour_69115.mp3","categories":["شروح الحديث"]},{"id":15593,"question":"وهذه رسالة في البداية بعث بها المستمع (ح. م . ص) من جدة، ضمنها ثلاثة أسئلة:في سؤاله الأول يقول: ما معنى قوله تعالى: إِنْ تُبْدُوا مَا فِي أَنفُسِكُمْ أَوْ تُخْفُوهُ يُحَاسِبْكُمْ بِهِ اللَّهُ[البقرة:284]؟ وكيف نجمع بين معناها وبين الحديث الشريف الذي معناه: أن الله تعالى تجاوز عن أمة محمد ما حدثت به أنفسها ما لم تفعله أو تتكلم به؟ نعم.","title":"الجمع بين: {إِنْ تُبْدُوا مَا فِي أَنفُسِكُمْ...}و«إن الله تجاوز عن أمتي»","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فهذه الآية الكريمة قد أشكلت على كثير من الصحابة  لما نزلت، وهي قوله تعالى: لِلَّهِ مَا فِي السَّمَوَاتِ وَمَا فِي الأَرْضِ وَإِنْ تُبْدُوا مَا فِي أَنفُسِكُمْ أَوْ تُخْفُوهُ يُحَاسِبْكُمْ بِهِ اللَّهُ فَيَغْفِرُ لِمَنْ يَشَاءُ وَيُعَذِّبُ مَنْ يَشَاءُ وَاللَّهُ عَلَى كُلِّ شَيْءٍ قَدِيرٌ[البقرة:284] شق عليهم هذا الأمر، وجاؤوا إلى النبي ﷺ وذكروا أن هذا شيء لا يطيقونه، فقال لهم ﷺ: أتريدون أن تقولوا كما قال من قبلكم: سمعنا وعصينا؟ قولوا: سمعنا وأطعنا فقالوا: سمعنا وأطعنا، فلما قالوها وذلت بها ألسنتهم، أنزل الله بعدها قوله سبحانه: آمَنَ الرَّسُولُ بِمَا أُنزِلَ إِلَيْهِ مِنْ رَبِّهِ وَالْمُؤْمِنُونَ كُلٌّ آمَنَ بِاللَّهِ وَمَلائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ لا نُفَرِّقُ بَيْنَ أَحَدٍ مِنْ رُسُلِهِ وَقَالُوا سَمِعْنَا وَأَطَعْنَا غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ ۝ لا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا[البقرة:286] الآية. فسامحهم الله، وعفا ، ونسخ ما دل عليه مضمون هذه الآية، وأنهم لا يؤاخذون إلا بما عملوا، وبما أصروا عليه، وثبتوا عليه، وأما ما يخطر من الخطرات في النفوس والقلوب، فهذا معفو عنه؛ ولهذا صح عن رسول الله ﷺ أنه قال: إن الله تجاوز عن أمتي ما حدثت به أنفسها ما لم تعمل أو تكلم فزال هذا الأمر، والحمد لله، وصار المؤمن غير مؤاخذ إلا بما عمله، أو قاله، أو أصر عليه بقلبه عملًا بقلبه، كإصراره على ما يقع له من الكبر والنفاق، ونحو ذلك. أما الخواطر التي تعرض، والشكوك التي تعرض ثم تزول بالإيمان واليقين، فهذه لا تضر، بل هي عارضة من الشيطان، ولا تضر؛ ولهذا لما قال الصحابة: «يا رسول الله، إن أحدنا يجد في قلبه ما لئن يخر من السماء أسهل عليه من أن ينطق به -أو كما قالوا- قال: ذاك صريح الإيمان وفي لفظ: تلك الوسوسة فهي من الشيطان، إذا رأى من المؤمن الصدق والإخلاص، وصحة الإيمان، والرغبة فيما عند الله، وسوس عليه بعض الشيء، وألقى في قلبه خواطر خبيثة، فإذا جاهدها وحاربها بالإيمان والتعوذ بالله من الشيطان، سلم من شرها؛ ولهذا جاء في الحديث الآخر يقول -عليه الصلاة والسلام-: لا يزال الناس يتساءلون حتى يقولوا: هذا الله خلق كل شيء فمن خلق الله؟ فمن وجد ذلك فليقل: آمنت بالله ورسله وفي لفظ: فليستعذ بالله ولينته. فهذا يدلنا على أن الإنسان عرضة للوساوس الشيطانية، فإذا عرض له وساوس خبيثة، وخطرات منكرة، فليبتعد عنها؛ وليقل: آمنت بالله ورسله، أعوذ بالله من الشيطان الرجيم؛ ولينته، ولا يلتفت إليها، فإنها باطلة ولا تضره، وهي من الخطرات التي عفا الله عنها ، نعم.","link":"https://binbaz.org.sa/fatwas/14136/الجمع-بين-ان-تبدوا-ما-في-انفسكم-وان-الله-تجاوز-عن-امتي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_694/nour_69401.mp3","categories":["التفسير","شروح الحديث"]},{"id":15631,"question":"هذا السائل سميح من الأردن يقول في هذا السؤال -سماحة الشيخ-: يقول البعض من الناس: إذا وقعت الذبابة في الأكل أو الشرب عليك أن تنزلها في الأكل أو الشرب، بحيث يدخل الجناح في الطعام؛ لأن الرسول ﷺ يقول: \"جناح الذبابة فيه داء، وفيه دواء\" ما صحة هذا الحديث سماحة الشيخ؟","title":"حديث الذباب وبيان معناه","answer":"الجواب: نعم، قد ثبت عن النبي ﷺ أنه قال: إذا وقع الذباب في شراب أحدكم فليغمسه، ثم لينزعه ويلقه؛ فإن في أحد جناحيه داءً وفي الآخر شفاء وفي رواية: وإنه يتقي بالجناح الذي فيه الداء هذا رواه البخاري في الصحيح أن النبي  قال: إذا وقع الذباب في شراب أحدكم فليغمسه ثم ينزعه، فإن في أحد جناحيه داءً وفي الآخر شفاءً. فالسنة إذا وقع في شراب في لبن أو في ماء أو غيرهما من الشراب يغمس ثم ينزع، ويلقى ولا يضر؛ لأن الداء الذي في أحد الجناحين يداويه الدواء الذي في الجناح الآخر، ويزول الشر، إذا غمس قابل الدواء الذي فيه الداء الذي فيه حتى يزول ضرره، نعم. المقدم: هناك من ينكر هذا الحديث يا سماحة الشيخ؟ الشيخ: لا، غلط، هذا الذي أنكروه غلط، ما عندهم بصيرة، ما عندهم علم، الحديث ثابت عن النبي ﷺ، ولا حرج في ذلك والحمد لله، نعم. المقدم: أحسن الله إليكم، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/14173/حديث-الذباب-وبيان-معناه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_571/57114.mp3","categories":["شروح الحديث"]},{"id":15635,"question":"قال رسول الله ﷺ عن ناقة لعنت: دعوها فإنها ملعونة هل هذه قاعدة عامة؟","title":"معنى حديث: «دعوها فإنها ملعونة»","answer":"الجواب: استنبط منها العلماء: أن الدابة إذا لعنت فالمشروع تركها، وعدم ركوبها في ذلك الجيش في ذلك المكان، ولكن لا تخرج عن ملك صاحبها، بل هي تحت ملكه ويتصرف فيها بالبيع وغيره، ولكن لا تصحب الرفقة؛ لأن الرسول ﷺ قال: لا تصحبنا ناقة ملعونة يعني: يخرجها من الرفقة، ويتصرف فيها بعد ذلك ببيعها، نحرها، أو استعمالها في وقت آخر.  فالمقصود: تلك الرفقة التي لعنت فيها الدابة، تخرج منها لا تصحبهم، هذا هو المشروع، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14178/معنى-حديث-دعوها-فانها-ملعونة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_705/nour_70506.mp3","categories":["شروح الحديث"]},{"id":15912,"question":"من اليمن السائل في آخر أسئلته يقول: سماحة الشيخ، ما معنى هذا الحديث في رواية لـأبي داود قال النبي ﷺ: لا يحل لمؤمن أن يهجر أخاه فوق ثلاث، فإن مرت به ثلاث فليلقه فليسلم عليه، فإن رد عليه السلام فقد اشتركا في الأجر، وإن لم يرد عليه فقد باء بالإثم؟","title":"معنى حديث: «لا يحل لمؤمن أن يهجر...»","answer":"الجواب:   ثبت في الصحيحين عن النبي ﷺ أنه قال: لا يحل لمسلم أن يهجر أخاه فوق ثلاث، يلتقيان فيعرض هذا، ويعرض هذا، وخيرهما الذي يبدأ بالسلام هكذا ثبت في الصحيحين خيرهما الذي يبدأ بالسلام فليس له أن يهجر أخاه فوق ثلاث لا يزوره ولا يكلمه، إلا إذا كان هجره له من أجل إظهاره المعاصي، فمن أظهر المعاصي يستحق الهجر، نسأل الله السلامة، نعم. \nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14504/معنى-حديث-لا-يحل-لمومن-ان-يهجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_577/57711.mp3","categories":["شروح الحديث","الأخلاق المذمومة"]},{"id":16109,"question":"يسأل أخونا ويقول: هناك أحاديث لرسول الله ﷺ يقول فيها: (ليس منا من فعل كذا) و(ليس منا من فعل كذا) فهل كلمة (ليس) تخرج من الملة؟ وإذا كانت تخرج من الملة فهل هو مخلد في النار -والعياذ بالله-؟ وكيف الجمع بين هذه الأحاديث، وأحاديث الشفاعة التي تقول: ..أخرجوا من النار من قال: لا إله إلا الله، وأخرجوا من النار من كان في قلبه مثقال حبة من إيمان جزاكم الله خيرًا.","title":"معنى قول النبي ﷺ: (ليس منا من فعل كذا)","answer":"الجواب: هذه الأحاديث التي فيها (ليس منا..) في الغالب والأكثر أنها من باب الوعيد والتحذير والترهيب، مما ذكر فيها من المعاصي، ولا تخرج صاحبها من الإسلام إذا لم يستحلها، ولكن فيها الحذر، فيها الترهيب والتحذير، مثل قوله ﷺ في الحديث الصحيح: ليس منا من ضرب الخدود، أو شق الجيوب، أو دعا بدعوى الجاهلية يعني: عند المصيبة، هذا وعيد، وليس كفرًا.  وقوله -عليه الصلاة والسلام- في الحديث الصحيح: لا يؤمن أحدكم حتى يحب لأخيه ما يحب لنفسه لا يؤمن من لا يأمن جاره بوائقه كلها من باب التحذير، والترهيب من الأخلاق الذميمة، والحث على الأخلاق الكريمة، وهكذا ما أشبه ذلك. المؤمن يحذر ما حذر منه الرسول ﷺ ويبتعد عنه، وهذه المعاصي تنقص الإيمان، تضعف الإيمان، ومثال قوله ﷺ: لا يزني الزاني حين يزني وهو مؤمن، ولا يشرب الخمر حين يشرب وهو مؤمن، ولا يسرق حين يسرق وهو مؤمن الحديث، يعني: الإيمان الكامل الواجب، ليس معناه أنه كفر: السارق ما هو بكافر، والزاني ليس بكافر إذا لم يستحل، إذا كان يعرف أنها معصية، ولكن حمله الهوى والشيطان يكون عاصيًا، إيمانه ضعيف ناقص، معرض للوعيد على خطر من دخول النار. وهكذا شارب الخمر إلا إذا استحل، إذا قالوا: الزنا حلال يكفر كفرًا أكبر، وهكذا لو قال: شرب الخمر حلال؛ يكفر كفرًا أكبر، وهكذا لو قال: ظلم الناس، والسرقة منهم حلال؛ يكون كفرًا أكبر، وهكذا لو قال: الربا كله بأنواعه كلها حلال، جميع أنواع الربا كلها حلال؛ يكون كفرًا أكبر، أما إذا فعل بعض الربا، ولم يستحله، فعل بعض الربا؛ يكون عاصيًا، أتى كبيرة، أو تعاطى أنواع الربا، لكن لم يستحل ذلك، بل أطاع هواه ورابى؛ هذه معصية، يكون إيمانه ضعيفًا، ناقص الإيمان، ومعرضًا للنار -الوعيد بدخول النار- وهكذا من عق والديه، أو قطع أرحامه، ولم يستحل هذا، يكون قد تعرض للوعيد، هو على خطر من دخول النار، وهو تحت مشيئة الله .  فالمقصود: أن هذه الألفاظ ليست تدل على الكفر الأكبر، ولكن من باب الوعيد: ليس منا.. ليس منا.. أو لا يؤمن أحدكم.. إلى آخره، وإنما يُعرف أنه كفر أكبر من أدلة أخرى.","link":"https://binbaz.org.sa/fatwas/14762/معنى-قول-النبي-ﷺ-ليس-منا-من-فعل-كذا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_712/nour_71202.mp3","categories":["شروح الحديث"]},{"id":16262,"question":"تقول أختنا أيضًا: جاء رجل إلى النبي -عليه الصلاة والسلام- وقال: يا رسول الله! إني أكثر الصلاة عليك، فكم أجعل لك من صلاتي؟ قال: ما شئت قال: الربع؟ قال: ما شئت، وإن زدت فهو خير لك قال: النصف؟ قال: ما شئت، وإن زدت فهو خير لك قال: الثلثين؟ قال: ما شئت، وإن زدت فهو خير لك قال: يا رسول الله! فأجعل صلاتي كلها لك؟ قال: إذًا تكفى همك، ويغفر ذنبك وجهوني في هذا الحديث؟ واشرحوه لي؟ جزاكم الله خيرًا، وهل يجوز أن نصلي على النبي ﷺ أثناء السجود؟","title":"الحكم على حديث \"كم أجعل لك من صلاتي؟\" ومعناه","answer":"الجواب: هذا الحديث صحيح، ومعنى الصلاة هنا: الدعاء، فإذا جعل الإنسان وقتًا يصلي فيه على النبي ﷺ كثيرًا، فالله -جل وعلا- يأجره على ذلك، والحسنة بعشر أمثالها، إلى ما لا يحصى من الفضل، يقول النبي ﷺ: إذًا تكفى همك، ويغفر ذنبك إذا أكثر من الصلاة -عليه عليه الصلاة والسلام- قال بعض أهل العلم: هذا السائل له وقت خصه للدعاء، فإذا صرف ذلك الوقت كله في الصلاة على النبي ﷺ؛ حصل له هذا الفضل: إذًا تكفى همك يعني: يكفيك الله همك  ويغفر ذنبك. فينبغي الإكثار من الصلاة على النبي ﷺ، وإذا صلى على النبي ﷺ في السجود قبل الدعاء، أثنى على الله، وصلى على النبي ﷺ فهذا من أسباب الإجابة، كما أن الصلاة عليه في آخر التحيات، ثم الدعاء بعد ذلك من أسباب الإجابة. وهكذا في غير ذلك إذا حمد الله، وأثنى عليه، وصلى على النبي ﷺ ثم دعا كان هذا من أسباب الإجابة، لما ثبت عنه ﷺ أنه قال لما رأى رجلًا دعا، ولم يصل على النبي ﷺ، قال: عجل هذا ثم قال: إذا دعا أحدكم فليبدأ بتحميد ربه، والثناء عليه، ثم يصلي على النبي ﷺ ثم يدعو بما شاء فأرشد إلى أنه يحمد الله أولًا، ثم يصلي على النبي ﷺ ثم يدعو بما شاء، وهذا من أسباب الإجابة. فيشرع لك أيها الأخت في الله! أن تجتهدي في الصلاة على النبي ﷺ في الليل والنهار، وإذا صليت على النبي ﷺ في السجود؛ فلا بأس؛ لأن السجود محل دعاء، يقول النبي ﷺ: أقرب ما يكون العبد من ربه وهو ساجد؛ فأكثروا الدعاء ويقول ﷺ: أما الركوع فعظموا فيه الرب، وأما السجود فاجتهدوا في الدعاء، فقمن أن يستجاب لكم يعني: فحري أن يستجاب لكم. فيشرع في ذلك الثناء على الله، والصلاة على النبي ﷺ ثم الدعاء. وهكذا في آخر الصلاة، يقرأ التحيات، ويتشهد الشهادتين، ثم يصلي على النبي ﷺ بالصلاة الإبراهيمية، ثم يتعوذ بالله من عذاب جهنم، ومن عذاب القبر، ومن فتنة المحيا والممات، ومن فتنة المسيح الدجال، ثم يدعو بما شاء، فهو حري بالإجابة. وهكذا إذا دعا في غير ذلك في الضحى، أو في الظهر، أو في الليل، أو في أي وقت، إذا دعا يستحب له أن يبدأ دعاءه بحمد الله، والثناء على الله، ثم الصلاة على النبي ﷺ ثم الدعاء، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14963/الحكم-على-حديث-كم-اجعل-لك-من-صلاتي-ومعناه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_808/nour_80812.mp3","categories":["شروح الحديث","الحكم على الأحاديث"]},{"id":16577,"question":"المستمع أبو محمد بن أحمد علي يسأل ويقول: قال رسول الله ﷺ: \"جاء الدين غريبًا -هكذا يقول سماحة الشيخ- وسوف يعود غريبًا كما بدأ\" اشرحوا لنا معنى هذه الغربة، جزاكم الله خيرًا.","title":"شرح حديث: \"بدأ الإسلام غريبًا...\"","answer":"الجواب: نعم، يقول النبي ﷺ في الحديث الصحيح: بدأ الإسلام غريبًا بدأ يعني: ظهر الإسلام غريبًا في أول أمره في مكة، غريبًا بين الكفرة، لم يأخذ به إلا القليل من الناس، ثم انتشر شيئًا بعد شيء في مكة، ولم يزل غريبًا، ثم هاجر النبي ﷺ إلى المدينة، وانتشر في المدينة، وظهر في المدينة، ثم ظهر في جميع الدنيا، والحمد لله. وسيعود غريبًا كما بدأ يعني: في آخر الزمان بسبب قلة أهله الذين يعتنقونه، ويستمسكون به، حتى في آخر الزمان يقبض الدين كله، ولا يبقى إلا الأشرار، فعليهم تقوم الساعة، معنى يعود غريبًا يعني يقل أهله، ويكثر خصومه، وأعداؤه. وفي آخر الزمان بعد طلوع الشمس من مغربها يرسل الله ريحًا طيبة تقبض أرواح المؤمنين والمؤمنات، ولا يبقى إلا الأشرار، فعليهم تقوم الساعة، قد ينتشر في بعض البلاد، ويكثر، ويقوى، ويضعف في بلاد أخرى، لكن في الجملة أنه يعود غريبًا، لكن بالنسبة إلى بعض البلاد قد يكون فيها ليس بغريب لكثرة الدعاة فيها إلى الله، والعلماء والأخيار، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15298/شرح-حديث-بدا-الاسلام-غريبا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_716/nour_71602.mp3","categories":["شروح الحديث"]},{"id":16581,"question":"يسأل سؤالًا آخر فيقول: يقول الرسول ﷺ: كلكم تدخلون الجنة إلا من أبى اشرحوا لنا هذا الحديث جزاكم الله خيرًا.","title":"شرح حديث: \"كل أمتي يدخلون الجنة...\"","answer":"الجواب: هذا حديث صحيح رواه البخاري في الصحيح عن النبي ﷺ أنه قال: كل أمتي يدخلون الجنة، إلا من أبى قيل: يا رسول الله من يأبى؟ قال: من أطاعني دخل الجنة، ومن عصاني؛ فقد أبى هذا تفسير الحديث: من عصاه؛ فقد أبى، الذي يعصي الرسول ﷺ ولا يتبع الشرع معناه أنه آبي، ما يريد الجنة، لو أرادها لأخذ بالأسباب، فالذي يتنكب الأسباب، ويتركها ما أراد الجنة. أما الذي أراد الجنة هو الذي يطيع الرسول ﷺ ويتبع الشرع، وينقاد للشرع، ويحافظ على دين الله، ويدع المحرمات، ويأخذ بالواجبات، ويجتهد في الخيرات، هذا الذي يريد الجنة، الله -جل وعلا- قال: وَسَارِعُوا إِلَى مَغْفِرَةٍ مِنْ رَبِّكُمْ وَجَنَّةٍ عَرْضُهَا السَّمَوَاتُ وَالأَرْضُ أُعِدَّتْ لِلْمُتَّقِينَ ۝ الَّذِينَ يُنْفِقُونَ فِي السَّرَّاءِ وَالضَّرَّاءِ وَالْكَاظِمِينَ الْغَيْظَ وَالْعَافِينَ عَنِ النَّاسِ [آل عمران:133-134] الآية، ويقول سبحانه: سَابِقُوا إِلَى مَغْفِرَةٍ مِنْ رَبِّكُمْ وَجَنَّةٍ عَرْضُهَا كَعَرْضِ السَّمَاءِ وَالأَرْضِ أُعِدَّتْ لِلَّذِينَ آمَنُوا بِاللَّهِ وَرُسُلِهِ ذَلِكَ فَضْلُ اللَّهِ[الحديد:21] الآية. فالمقصود: أن الذي يريد الجنة؛ يسارع إليها، ويقوم بأعمالها، ويجتهد، ويتقي الله، أما من أعرض عنها، وعن أعمالها، ولم يبال؛ فهذا في الحقيقة قد أبى. ومثل ذلك من أراد بر الوالدين، إذا اجتهد في الإحسان إليهما، وبذل وسعه؛ فقد أراد برهما حقيقة، فإذا أعرض عن ذلك، ولم يبال؛ فهو ما أراد برهما، كذاب، لو قال: إنه يريد برهم كذاب، من أعرض عن ذلك، ولم يفعل شيئًا؛ فهو إذا قال أنا أريد برهما فهو كذاب. وهكذا لو قال: أنا أريد أحافظ على الصلاة في الجماعة، وأنا أحب ذلك، ثم هو يتنكب ذلك، ويعرض، ويبقى في بيته، ولا يصلي مع الناس؛ كذاب في قوله، فعله يكذب قوله.  والمقصود: أن من أراد الخير سلك طريقه، ومن لم يسلك الطريق فهو ما أراد الخير، نسأل الله العافية، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15306/شرح-حديث-كل-امتي-يدخلون-الجنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_716/nour_71603.mp3","categories":["شروح الحديث"]},{"id":16625,"question":"نعود في بداية هذه الحلقة إلى رسالة وصلت إلى البرنامج من القصيم، باعثة الرسالة إحدى الأخوات من هناك رمزت إلى اسمها بحرفين هما: (أ) و(ح) عرضنا بعض أسئلتها في حلقة مضت، وفي هذه الحلقة لها بعض الأسئلة، فتقول في أحد أسئلتها: أسأل سماحتكم عن حديث أبي هريرة عن النبي ﷺ: إن لله تسعة وتسعين اسمًا، مائة إلا واحدًا، من أحصاها؛ دخل الجنة هل كلمة: أحصاها الواردة في الحديث معناها: حفظها، أم قراءتها فقط؟ وجهوني، جزاكم الله خيرًا.","title":"معنى كلمة: \"أحصاها\" في حديث الأسماء الحسنى","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فهذا الحديث مخرج في الصحيحين عن النبي -عليه الصلاة والسلام- وله لفظان أحدهما: من أحصاها واللفظ الثاني: من حفظها؛ دخل الجنة معنى أحصاها: يعني: حفظها، وأتقنها دخل الجنة، وإحصاؤها يكون بحفظها، ويكون بالعمل بمقتضاها، أما لو أحصاها وهو لا يعمل بمقتضاها، ولا يؤمن بها؛ فإنها لا تنفعه، فالإحصاء يدخل فيه حفظها، ويدخل فيه العمل بمعناها. فالواجب على من وفقه الله لإحصائها، وحفظها أن يعمل بمقتضاها، فيكون رحيمًا، ويكون أيضًا عامًلا بمقتضى بقية الأسماء، يؤمن بأن الله عزيز حكيم، رؤوف رحيم، قدير، عالم بكل شيء، ويؤمن بذلك، ثم يراقب الله، ويخاف الله، فلا يصر على المعاصي التي يعلمها ربه، بل يحذر المعاصي ويبتعد عنها، وعن الكفر بالله كله بأنواعه، إلى غير ذلك. فهو يجتهد في حفظها مع العمل بمقتضاها من الإيمان بالله، ورسوله، وإثبات الصفات، والأسماء لله، على الوجه اللائق بالله، من غير تحريف، ولا تعطيل، ولا تكييف، ولا تمثيل، يعلم أنها حق، وأنها صفات لله، وأسماء لله، وأنه سبحانه الكامل في ذاته، وأسمائه، وصفاته، وأفعاله، لا شبيه له، ولا مثل له، كما قال  في كتابه العظيم: قُلْ هُوَ اللَّهُ أَحَدٌ ۝ اللَّهُ الصَّمَدُ ۝ لَمْ يَلِدْ وَلَمْ يُولَدْ ۝ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ [الإخلاص:1-4]. يؤمن بهذا، وأنه صمد، لا شبيه له، تصمد إليه الخلائق، وتحتاج إليه  وهو الكامل في كل شيء، وأنه لم يلد ولم يولد، وأنه لا كفؤ له، لا في صفاته، ولا في أفعاله، ليس له كفؤ ولا مثيل، ولا سمي قال تعالى: لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ [الشورى:11]... هَلْ تَعْلَمُ لَهُ سَمِيًّا [مريم:65]... فَلا تَضْرِبُوا لِلَّهِ الأَمْثَالَ [النحل:74] فهو سبحانه لا سمي له، ولا شبه له، ولا كفؤ له، ولا ند له، هو الكامل في كل شيء، في علمه، وفي ذاته، وفي حكمته، وفي رحمته، وفي عزته، وفي قدرته، وفي جميع صفاته .  فمن أحصاها علمًا، وعملًا، وحفظها علمًا وعملًا؛ أدخله الله الجنة، أما إذا أحصاها، وحفظها، لكن قد أقام على المعاصي، والسيئات؛ فهو تحت مشيئة الله، إن شاء الله غفر له، وإن شاء عذبه بمعاصيه، ثم بعد تطهيره من المعاصي يخرجه الله من النار إلى الجنة؛ إذا كان مات على التوحيد، والإسلام، كما قال الله سبحانه: إِنْ تَجْتَنِبُوا كَبَائِرَ مَا تُنْهَوْنَ عَنْهُ نُكَفِّرْ عَنْكُمْ سَيِّئَاتِكُمْ [النساء:31] فهذا خطاب لأهل الإسلام، بل لجميع الناس: إِنْ تَجْتَنِبُوا كَبَائِرَ مَا تُنْهَوْنَ عَنْهُ نُكَفِّرْ عَنْكُمْ سَيِّئَاتِكُمْ [النساء:31] والكبائر تشمل الشرك، وأنواع الكفر، وتشمل المعاصي التي حرم الله، وجاء فيها اللعن، والغضب، والوعيد من الكبائر. فعلى العباد من الرجال، والنساء أن يجتنبوها؛ ولهذا قال سبحانه: إِنْ تَجْتَنِبُوا كَبَائِرَ مَا تُنْهَوْنَ عَنْهُ نُكَفِّرْ عَنْكُمْ سَيِّئَاتِكُمْ [النساء:31] يعني: الصغائر وَنُدْخِلْكُمْ مُدْخَلًا كَرِيمًا [النساء:31]. ويقول النبي ﷺ: الصلوات الخمس، والجمعة إلى الجمعة، ورمضان إلى رمضان، كفارات لما بينهن إذا اجتنب الكبائر وفي لفظ: ما لم تغش الكبائر كالزنا، والسرقة، والعقوق للوالدين، أو أحدهما، قطيعة الرحم، أكل الربا، الغيبة النميمة، التولي يوم الزحف، السحر، إلى غير هذا مما حرمه الله من الكبائر. والمقصود: أن إحصاء الأسماء الحسنى، وحفظها من أسباب السعادة، ومن أسباب دخول الجنة لمن أدى حقها، واستقام على طاعة الله، ورسوله، ولم يصر على الكبائر، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15355/معنى-كلمة-احصاها-في-حديث-الاسماء-الحسنى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_759/nour_75901.mp3","categories":["شروح الحديث"]},{"id":16631,"question":"المستمع محمد صافي محمد بعث يسأل ويقول: قال رسول الله ﷺ: لأن يمشي أحدكم في حاجة أخيه خير له من أن يعتكف في مسجدي هذا اشرحوا لنا هذا الحديث، جزاكم الله خيرًا.","title":"شرح حديث: \"لأن يمشي أحدكم في حاجة أخيه...\"","answer":"الجواب: هذا الحديث لا أعرف صحته، ولكن يغني عنه، ويكفي عنه ما رواه الشيخان في الصحيحين عن ابن عمر -رضي الله تعالى عنهما- عن النبي ﷺ أنه قال: من كان في حاجة أخيه كان الله في حاجته من كان في حاجة أخيه كان الله في حاجته وفي الصحيح من حديث أبي هريرة  عن النبي ﷺ أنه قال: والله في عون العبد ما كان العبد في عون أخيه هذا يكفي عن ذاك الحديث الغير معروف. فالإنسان إذا كان في حاجة أخيه، وأعان أخاه في قضاء دينه، في الشفاعة له في حاجة، في علاجه، في إعطائه الدواء، في نقله بالسيارة إلى الطبيب، في غير هذا من الحاجات، فالله -جل وعلا- وعده أن يكون في حاجته، وأن يقضي حاجته كما قضى حاجة أخيه، وعده بالعون سبحانه وتعالى، فالمؤمنون إخوة، يتعاونون في حاجاتهم المباحة، وحاجاتهم الشرعية، وكل إنسان له أجره في عونه لأخيه في حاجته الدنيوية، والدينية جميعًا. أما المعصية فلا لا يعينه عليها المعاصي، لا يعينه عليها، لا يجوز له أن يعينه على المعصية؛ لأن الله يقول: وَلا تَعَاوَنُوا عَلَى الإِثْمِ وَالْعُدْوَانِ [المائدة:2] ولكن يعينه في المباح كالعلاج.. ونحو ذلك، وفي المشروع كإعانته على صلاة الجماعة، وإعانته على الحج، وإعانته على الجهاد، وإعانته على بر والديه، وعلى صلة أرحامه، إلى غير هذا من وجوه الخير، فهو مأجور على هذه الإعانة. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15364/شرح-حديث-لان-يمشي-احدكم-في-حاجة-اخيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_716/nour_71610.mp3","categories":["شروح الحديث"]},{"id":16662,"question":"سماحة الشيخ هذا سائل يقول: كيف نجمع بين الحديث الذي فيما معناه: بأن من ستر مسلمًا ستره الله يوم القيامة، وبين فريضة الأمر بالمعروف والنهي عن المنكر؟","title":"الجمع بين الأمر بالمعروف وستر المذنبين","answer":"الجواب: تأمره، وتستر عليه، إذا رأيته يتعاطى ما حرم الله من خمر، أو نحوه؛ تستر عليه، ما تقول: رأيت فلانًا يشرب الخمر، تأمره بالمعروف، وتنهاه عن المنكر، تنصحه، وتوصيه بالخير، ولا تفضحه عند الناس، إلا إذا هو فضح نفسه، هو الذي يشرب الخمر عند الناس، فضح نفسه، من أعلن المعاصي؛ ما له غيبة، هو الذي فضح نفسه، لكن إذا كان يتستر في بيته، ورأيته صادفته؛ لا تكشف ستره، لا تعلن أمره، يقول النبي ﷺ: من ستر مسلمًا ستره الله في الدنيا والآخرة لكن تنصحه، تأمره بالمعروف، وتنهاه عن المنكر، ولا تفضحه، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/15395/الجمع-بين-الامر-بالمعروف-وستر-المذنبين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_583/58319.mp3","categories":["شروح الحديث","الدعوة والدعاة"]},{"id":16763,"question":"المرسل (ط. ف) من الخرج يسأل شرح حديث لرسول الله ﷺ يقول: عن أبي هريرة -رضي الله عنه- أن رسول الله ﷺ قال: إذا مات ابن آدم؛ انقطع عمله إلا من ثلاث: صدقة جارية، أو علم ينتفع به، أو ولد صالح يدعو له رواه مسلم، أرجو أن يتفضل سماحتكم بشرح هذا الحديث؟","title":"شرح حديث: \"إذا مات ابن آدم انقطع عمله...\"","answer":"الجواب: هذا الحديث من أوضح الواضحات، لا يحتاج إلى شرح، يقول النبي ﷺ: إذا مات ابن آدم؛ انقطع عمله إلا من ثلاث يعني ينقطع عمله الذي يجري عليه بعد الموت إلا من هذه الثلاث: صدقة جارية قد وقفها هو مثل وقف مسجد يصلى فيه، أو عمارة تؤجر، ويتصدق بأجرتها، أو أرض زراعية يتصدق بما يحصل منها، أو ما أشبه ذلك، فهذه صدقة جارية، يجري عليه أجرها بعد وفاته، ما دامت ينتفع بها الناس.  أو علم ينتفع به: إما كتب ألفها، وانتفع بها الناس، أو اشتراها، وأوقفها، وانتفع بها الناس من الكتب الإسلامية النافعة، أو نشره بين الناس، وانتفع به المسلمون، وتعلموا منه، وتعلم بقية الناس من تلاميذه، هذا علم ينتفع به، فإن العلم الذي مع تلاميذه، ونشروه في الناس ينفعه الله به، كما ينفعهم أيضًا، وهكذا الولد الصالح الذي يدعو له، تنفعه دعوة ولده الصالح، كما تنفعه دعوة المسلمين أيضًا، وإذا دعا له إخوانه، أو تصدقوا عنه؛ نفعه ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15526/شرح-حديث-اذا-مات-ابن-ادم-انقطع-عمله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_822/nour_82206.mp3","categories":["شروح الحديث"]},{"id":16798,"question":"رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات تقول: (ص. ع. ع) أختنا لها أكثر من سؤال في أحدها تقول: لعن رسول الله ﷺ المتشبهات من النساء بالرجال، والمتشبهين من الرجال بالنساء كيف يكون ذلك التشبه؟ وهل هذا اللعن هو الطرد عن رحمة الله، وإن كانت المرأة تصلي، وتقوم بالأعمال الخيرة؟ جزاكم الله خيرًا.","title":"شرح حديث: \"لعن الله المتشبهات من النساء بالرجال...\"","answer":"الجواب: هذا من باب الوعيد، اللعن من باب الوعيد والتحذير، من باب الوعيد والتحذير، وقد يسلم الرجل من العقوبة بأعمال صالحة، أو بتوبة صادقة، وهكذا المرأة قد تسلم من العقوبة بتوبة صادقة، وأعمال صالحة، لكن المقصود من اللعن التحذير. فلا يجوز للرجل التشبه بالكفار، ولا بالنساء، والمرأة كذلك، ليس لها التشبه بالرجال، ولا بالكفار، لا في الزي، ولا في الكلام، ولا في المشي، كله ليس له أن يتشبه بالمرأة في زيه، وفي كلماته، وفي مشيه، ولا بالكفرة، وهي كذلك، ليس لها التشبه بالرجل في زيه من اللباس، ولا في زيه من المشي، ولا في زيه من الكلام؛ لأن الرسول ﷺ لعن المتشبه من النساء بالرجال، ولعن المتشبه من الرجال بالنساء، وهكذا قال: من تشبه بقوم فهو منهم وقال: قصوا الشوارب، وأعفوا اللحى؛خالفوا المشركين قال: جزوا الشوارب، وأرخوا اللحى؛ خالفوا المجوس نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15559/شرح-حديث-لعن-الله-المتشبهات-من-النساء-بالرجال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_823/nour_82302.mp3","categories":["شروح الحديث","الحكم على الأحاديث","قضايا المرأة"]},{"id":16806,"question":"رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات تقول: (ص. ع. ع) أختنا لها أكثر من سؤال في أحدها تقول: لعن رسول الله ﷺ المتشبهات من النساء بالرجال، والمتشبهين من الرجال بالنساء كيف يكون ذلك التشبه؟ وهل هذا اللعن هو الطرد عن رحمة الله، وإن كانت المرأة تصلي، وتقوم بالأعمال الخيرة؟ جزاكم الله خيرًا.","title":"شرح حديث: \"لعن الله المتشبهات من النساء بالرجال...\"","answer":"الجواب: هذا من باب الوعيد، اللعن من باب الوعيد والتحذير، من باب الوعيد والتحذير، وقد يسلم الرجل من العقوبة بأعمال صالحة، أو بتوبة صادقة، وهكذا المرأة قد تسلم من العقوبة بتوبة صادقة، وأعمال صالحة، لكن المقصود من اللعن التحذير. فلا يجوز للرجل التشبه بالكفار، ولا بالنساء، والمرأة كذلك، ليس لها التشبه بالرجال، ولا بالكفار، لا في الزي، ولا في الكلام، ولا في المشي، كله ليس له أن يتشبه بالمرأة في زيه، وفي كلماته، وفي مشيه، ولا بالكفرة، وهي كذلك، ليس لها التشبه بالرجل في زيه من اللباس، ولا في زيه من المشي، ولا في زيه من الكلام؛ لأن الرسول ﷺ لعن المتشبه من النساء بالرجال، ولعن المتشبه من الرجال بالنساء، وهكذا قال: من تشبه بقوم فهو منهم وقال: قصوا الشوارب، وأعفوا اللحى؛خالفوا المشركين قال: جزوا الشوارب، وأرخوا اللحى؛ خالفوا المجوس نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15559/شرح-حديث-لعن-الله-المتشبهات-من-النساء-بالرجال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_823/nour_82302.mp3","categories":["شروح الحديث","الحكم على الأحاديث","قضايا المرأة"]},{"id":16922,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع مصطفى سعد سليمان من مرسى مطروح في جمهورية مصر العربية، لأخينا جمع من الأسئلة في أحدها يسأل ويقول: \"من أراد الدنيا؛ فعليه بالقرآن، ومن أراد الآخرة؛ فعليه بالقرآن، ومن أرادهما معًا فعليه بالقرآن\" وأيضًا: هناك قول يقول حول القرآن الكريم: \"اقرءوا القرآن لما شئتم\" إذا كان هذه أحاديث وجهونا جزاكم الله خيرًا، وهل يصح أن يقرن الإنسان الدنيا بالدين؟ جزاكم الله خيرًا.","title":"الحكم على حديثين في فضل القرآن الكريم","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فلا أعلم صحة شيء من هذه الأحاديث، وليس لها أصل فيما نعلم، ولكن إذا قرأ القرآن ليستفيد منه في أمور دنياه، وأمور دينه؛ فهو مطلوب، لكنه أنزل لعمل الآخرة، وليستقيم على أمور الآخرة، هذا هو الأهم، ويترتب على العمل بالقرآن صلاح أمر الدنيا والآخرة، لكن ليس المقصود من إنزاله صلاح أمر الدنيا، إنما الدنيا تابعة، فإذا قرأ القرآن، ودرس القرآن وتدبر القرآن؛ ليعلم أمر الدنيا، والآخرة، وليستفيد من ذلك ما يصلح أمر الدنيا والآخرة؛ فهذا كله طيب، ولكن ليكن أكبر همه إصلاح أمر الآخرة، والعناية بما أوجب الله عليه، وما حرم الله عليه؛ حتى يعرف من كتاب الله ما أوجب الله، وما حرم الله، وحتى يستقيم على طاعة الله ورسوله، وإذا استفاد من القرآن أيضًا فيما يتعلق بطيب الكسب، فهذا من أمر الآخرة، كونه يجتهد في أن يكون كسبه طيبًا حلالًا بعيدًا عن الحرام، يستفيد في صلة رحمه.. في بر والديه.. في إكرام جاره.. في حفظ وقته، كل هذا ينفع في الدنيا والآخرة. وهكذا: (اقرؤوا القرآن لما شئتم) فالمعنى له وجه صحيح، يقرؤه ليتفقه في الدين، يقرؤه ليخاف الله، ويراقب الله، يقرؤه ليعالج به مرضه، يقرؤه ليعرف أحكام بيعه، أحكام معاملته للناس، يعرف به أحكام صلاته .. إلى غير ذلك، يقرأ لما يشاء، لكن أهم ما يكون أن يكون يقرؤه ليعرف ما يرضي الله، ويقرب لديه؛ ليعرف أسباب السعادة ليعرف أسباب النجاة، ليعرف أسباب الهلاك حتى يحذرها، فهو أنزل ليستقيم العبد على طاعة الله ورسوله، كما قال : كِتَابٌ أَنزَلْنَاهُ إِلَيْكَ مُبَارَكٌ لِيَدَّبَّرُوا آيَاتِهِ وَلِيَتَذَكَّرَ أُوْلُوا الأَلْبَابِ [ص:29] وقال سبحانه: وَنَزَّلْنَا عَلَيْكَ الْكِتَابَ تِبْيَانًا لِكُلِّ شَيْءٍ وَهُدًى وَرَحْمَةً وَبُشْرَى لِلْمُسْلِمِينَ [النحل:89] ففيه بيان أسباب السعادة في الدنيا والآخرة، فإن من سار على القرآن في معاملاته أفلح، فإنه يصدق في الحديث، ويصدق في المعاملة، لا يغش، لا يخون، لا يكذب .. إلى غير هذا من الأخلاق الطيبة التي يدعو إليها القرآن. وإذا أخذ بهذه الأخلاق -ولو كان إنما أراد الدنيا- ينفعه ذلك، لكن لا يكون له أجر إذا كان ما أراد إلا الدنيا، أما إذا أراد بذلك إرضاء الله، والتقرب لديه؛ جمع الله له خير الدنيا والآخرة، أثيب، ومع ذلك صلح له أمر الدنيا فيما فعل، وإن لم يقصد الآخرة، وثواب الله؛ نفعه ما فعله في الدنيا من الصدق، والأمانة، وعدم الغش إلى غير هذا من الأشياء التي دل عليها القرآن، وأرشد إليها القرآن، لكن إذا فعله المكلف طاعة لله، وتعظيمًا لله، ورغبة فيما عنده، ولإصلاح أيضًا من أمر دنياه؛ جمع الله الخيرين خير الدنيا، والآخرة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15712/الحكم-على-حديثين-في-فضل-القران-الكريم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_766/nour_76601.mp3","categories":["الحكم على الأحاديث","شروح الحديث","القرآن وعلومه"]},{"id":16925,"question":"يسأل ويقول: في الحديث النبوي الشريف: من سن سنةً حسنة .. إلى آخر الحديث، هل هذه العبارة مجازية؟ أم تفهم على ظاهرها؟ وهل يمكن اعتبار مكبرات الصوت في المساجد لرفع النداء، أو نقل الصلاة عبرها سنة حسنة؟","title":"معنى حديث: \"من سن في الإسلام سنة حسنة...\"","answer":"الجواب: نعم، على ظاهرها، هي سنة، وليس بمجاز، بل هو كلام حقيقي على ظاهره، فمن أحيا السنن، ودعا إليها؛ فقد سن في الإسلام سنة حسنة، ليس بمعناها البدع، المراد إظهار السنن، وإحياؤها، والدعوة إليها، كما قال في قصة الجماعة الذين قدموا عليه ﷺ مجتابي النمار، فقراء، فقام ﷺ وخطب الناس، وذكرهم، ودعاهم إلى الصدقة، فجاء رجل بصرة تكاد كفه تعجز عنها، فتتابع الناس، فقال النبي ﷺ من سن في الإسلام سنة حسنة... الحديث، هذا مثال. فالذي أتى بالصدقة جهرة حتى تابعه الناس؛ قد سن في الإسلام سنةً حسنة، أظهرها وبينها، وهكذا لو كان في بلد ما يصلون التراويح، وصلاها، وتابعوه؛ أحيا السنة، وهكذا لو كانوا لا يصلون جماعة، يصلون في بيوتهم، فدعاهم إلى الصلاة في المساجد، وصلوا الصلاة في المساجد، فقد أحيا السنة، يكون له مثل أجورهم، وهكذا ما أشبه ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15698/معنى-حديث-من-سن-في-الاسلام-سنة-حسنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_826/nour_82613.mp3","categories":["شروح الحديث"]},{"id":17055,"question":"هذا أخونا من اليمن (ع. م. الضالعي )، يقول: سماحة الشيخ! سمعت حديثًا عن رسول الله ﷺ فيما معناه: «بأنه مر على قبرين، فقال: إنهما ليعذبان، وما يعذبان في كبير؛ أما أحدهما فكان يمشي بين الناس بالنميمة، وأما الثاني فكان لا يستبرئ من بوله أو فيما معنى الحديث، سماحة الشيخ! أرجو توضيح هذا الحديث في قوله: كان لا يستبرئ من بوله فأنا عندما أسمع هذا الحديث أخاف كوني أعاني من مشكلة، وهو أنني أشعر بعد البول والوضوء التام للصلاة، وكأن قطرات تنزل مني، ويكون ذلك في الصلاة، وجهوني في ضوء هذا الحديث وشرحه، مأجورين؟","title":"شرح حديث: \"إنهما ليعذبان...\"","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد.  فهذا الحديث ثابت عن النبي ﷺ، أخرجه البخاري ومسلم في الصحيحين، قال: «مر النبي ﷺ على قبرين فقال: إنهما ليعذبان، وما يعذبان في كبير، ثم قال: بلى، أما أحدهما فكان يمشي بالنميمة، وأما الآخر فكان لا يستنزه من البول وفي لفظٍ: لا يستتر من البول فأخذ جريدة رطبة فشقها نصفين، ثم غرز على كل قبرٍ واحدة، وقال: لعله يخفف عنهما ما لم تيبسا. الحديث المذكور يفيد الحذر من النميمة، وأنها من أخبث الكبائر، ومن أكبر الكبائر، يقول النبي ﷺ: لا يدخل الجنة نمام فالمشي بالنميمة من أسباب عذاب القبر، ومن أسباب حرمان دخول الجنة، وهي: السعي بين الناس بالكلام الردي، كونه ينقل كلام هؤلاء إلى هؤلاء، وكلام هذا إلى هذا، مما يسبب البغضاء والعداوة، هذه النميمة؛ القالة بين الناس، كونه ينقل كلامًا ما هو بطيب من زيد إلى عمرو، أو من جماعة إلى جماعة، فيحصل بهذا من الشر ما يحصل، هذه يقال لها: النميمة، فالواجب الحذر منها. والذنب الثاني: عدم التنزه من البول، فالواجب على المسلم، والمسلمة العناية بالنزاهة من البول والغائط، فإذا قضى حاجته يجب عليه أن يجتهد حتى يتنزه من بوله، وغائطه بالماء، إذا تيسر الماء، أو بالحجارة بالاستجمار، بهذا أو هذا، إذا استجمر بالحجارة ثلاث مرات، أو أكثر حتى تنزه من البول، أو من آثار الغائط كفى، وإن استنزه بالماء، غسل فرجه بالماء حتى أنقى المحل كفى، والحمد لله. وإذا كان الإنسان يخرج منه قطرات بعد البول لا يعجل، لا يعجل منه حتى تنتهي القطرات، فإذا انتهت القطرات استنجى، أو استجمر، وليحذر الوساوس، كونه يوسوس في الصلاة، أو بعد الوضوء أنه خرج منه شيء لا يلتفت إلى هذا، الوساوس يجب اطراحها، فإذا علم يقينًا أنه خرج منه شيء؛ يعيد الاستنجاء، يستنجي، ثم يتوضأ وضوء الصلاة. أما الوساوس بعد الوضوء، أو في الصلاة، أو في الطريق هذه يجب اطراحها، لما سئل النبي ﷺ قال: «يا رسول الله! الرجل يشكل عليه أنه يجد شيء في الصلاة؟ قال: لا ينصرف -لما سئل عن الرجل، يشكل عليه هل خرج منه شيء- قال ﷺ: لا ينصرف حتى يسمع صوتًا، أو يجد ريحًا وقال ﷺ: إذا وجد أحدكم في بطنه شيئًا، فأشكل عليه شيء، أخرج منه شيء، أم لا؛ فلا يخرجن من المسجد حتى يسمع صوتًا، أو يجد ريحًا. المقصود: أن الرسول ﷺ نهى عن العمل بالوساوس، والحذر منها، فلا يجوز له أن يلتفت إليها؛ لأن هذا يضره والشيطان، يشغله، لكن إذا جزم، وعلم يقينًا أنه خرج بول، أو غائط يستنجي، وإلا فالأصل السلامة، فلو شك واحد في المائة أنه خرج منه شيء، لا يلزمه شيء حتى يعلم مائة في المائة، يعني: بدون أي شك أنه خرج منه بول، أو غائط، وإلا فالأصل السلامة، والبراءة، والحمد لله. نعم.","link":"https://binbaz.org.sa/fatwas/15846/شرح-حديث-انهما-ليعذبان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_588/58801.mp3","categories":["شروح الحديث","الحكم على الأحاديث"]},{"id":17066,"question":"يقول السائل: بعض النساء عندما يجمعن شعر رؤوسهن إلى الخلف، هل هذا هو المنهي في حديث الرسول ﷺ؟","title":"حكم جمع المرأة رأسها إلى الخلف","answer":"الجواب: جاء في حديث الرسول ﷺ: رؤوسهن كأسنمة البخت المائلة يجمعون عليها أشياء حتى تعظم وتكبر، أما هذا يجمعون الشعر ما هو من جنس ما قاله الرسول ﷺ، لكن هذا عليهن أن يمسحنه كله... مسح الصلاة عليهن أن ينقضنه ويمسحنه، يوخرنه إن كان عليه خرقة وإلا شيء، يزلنها ويمسحن الرأس كله. أما الذي جاء في الحديث: رؤوسهن كأسنمة البخت المائلة هذا يجمعن عليها أشياء من لفائف حتى تكون كأسنمة البخت المائلة، وأسنمة البخت كأنها سنامان بينهما شيء. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15870/حكم-جمع-المراة-راسها-الى-الخلف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_588/58806.mp3","categories":["شروح الحديث","قضايا المرأة","اللباس والزينة"]},{"id":17217,"question":"تقول سماحة الشيخ: قال رسول الله ﷺ في حديث: ومن أحب لقاء الله أحب الله لقاءه، ومن كره لقاء الله كره الله لقاءه نرجو من سماحتكم أن تشرحوا لنا هذا الحديث، جزاكم الله خيرًا.","title":"شرح حديث: \"من أحب لقاء الله...\"","answer":"الجواب: هذا حديث صحيح قاله النبي ﷺ عن عدة من الصحابة : من أحب لقاء الله أحب الله لقاءه، ومن كره لقاء الله كره الله لقاءه قالت عائشة -رضي الله عنها-: يا رسول الله، أهو الموت؟ فكلنا يكره الموت، قال: لا يا عائشة، ولكن المؤمن إذا حضر أجله؛ بشرته الملائكة برحمة الله، ورضوانه؛ فيحب لقاء الله، ويحب الله لقاءه، والكافر متى حضر أجله؛ بشر بغضب الله وعقابه، فيكره لقاء الله؛ فيكره الله لقاءه .. هذا معنى الحديث، المؤمن إذا حضره الأجل بشر بالرحمة من الملائكة، بشرته الملائكة بالرحمة والرضا من الله، فيحب لقاء الله، ويحب الله لقاءه. والكافر إذا حضره الأجل؛ بشر بغضب الله، وعقابه، فيكره لقاء الله، فيكره الله لقاءه، ليس المقصود الموت، الموت من طبيعة الناس إلا من شاء الله، يكرهون الموت، لكن المقصود أنه متى حضره أجله بشرته الملائكة بالرحمة والرضا، فيحب لقاء الله، ويحب الله لقاءه، والكافر بضد ذلك، نسأل الله العافية يبشر بالعذاب، والنقمة، فيكره لقاء الله، ويكره الله لقاءه. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16043/شرح-حديث-من-احب-لقاء-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_723/nour_72313.mp3","categories":["شروح الحديث"]},{"id":17228,"question":"ثاني أسئلة هذا السائل، يقول: سماحة الشيخ، حفظكم الله، وسدد خطاكم، ما هو شرح هذا اللفظ من الحديث: إذا رأيتم شحًا مطاعًا، وهوى متبعًا، وإعجاب كل ذي رأي برأيه؛ فعليك بنفسك، ودع عنك أمر العوام وهل هذا حديث صحيح؟","title":"معنى حديث \"إذا رأيتم شحًا مطاعًا...\"","answer":"الجواب: هذا حديث أبي ثعلبة لا بأس به، فيما أعلم، والشح المطاع يعني: الحرص على الدنيا، الذي يطيعه صاحبه، والناس اتبعوا أهواءهم، وآثروا دنياهم، ولم يستجيبوا للداعي، ولم يستطع على إنكار المنكر، فعليه بنفسه، عند العجز، إذا عجز فليتق الله في نفسه، أما إذا استطاع الأمر بالمعروف، والنهي عن المنكر فإنه يأمر وينهى.  أما إذا عجز، ولم يجد له نصيرًا، بل عجز عن الأمر والنهي، ويخاف على نفسه من ضرب، أو سجن، أو أشد من ذلك؛ فهو معذور، أما إذا استطاع ينكر؛ ينكر المنكر، ويأمر بالمعروف، ولو تركه الناس؛ لأن الله -جل وعلا- يقول: يَا أَيُّهَا الَّذِينَ آمَنُوا عَلَيْكُمْ أَنفُسَكُمْ لا يَضُرُّكُمْ مَنْ ضَلَّ إِذَا اهْتَدَيْتُمْ [المائدة:105] ويقول ﷺ: إن الناس إذا رأوا المنكر فلم يغيروه؛ أوشك أن يعمهم الله بعقاب من عنده. فالإنسان يأمر بالمعروف، وإن تركه الناس، وينهى عن المنكر كذلك، لا يتساهل، ويقول: الناس ما فيهم حيلة، لا بحسب طاقته، يأمر وينهى حسب طاقته، إلا إذا خشى على نفسه، حصل شحًا مطاعًا، وهوًى متبعًا، ودنيا مؤثرة، وإعجاب كل ذي رأي برأيه يعني: لم يستطع، بل يخشى على نفسه، فهو معذور.  المقدم: أحسن الله إليكم، وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16055/معنى-حديث-اذا-رايتم-شحا مطاعا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_591/59105.mp3","categories":["شروح الحديث","الحكم على الأحاديث"]},{"id":17233,"question":"حفظكم الله، تستفسر الأخت هذه الطبيبة، وتقول: قول الرسول ﷺ: خيركم خيركم لأهله ما المقصود بذلك يا شيخ؟","title":"معنى قول الرسول ﷺ: \"خيركم خيركم لأهله\"","answer":"الجواب: على ظاهر الحديث: خيركم خيركم لأهله، وأنا خيركم لأهلي أهله: زوجته، وأمه، وأبوه، وأولاده، كلهم أهله، يعني: يحسن إليهم، وينفق عليهم، أفضل من الأجانب، والبعيدين. نعم.","link":"https://binbaz.org.sa/fatwas/16061/معنى-قول-الرسول-ﷺ-خيركم-خيركم-لاهله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_591/59110.mp3","categories":["شروح الحديث"]},{"id":17291,"question":"ورد في الحديث الصحيح قول الرسول ﷺ: لا عدوى ولا طيرة، ويعجبني الفأل ماذا يقصد الرسول ﷺ في قوله: لا عدوى أهي عدوى المرض، نرجو التوضيح؟","title":"معنى حديث: \"لا عدوى ولا طيرة...\"","answer":"الجواب: ثبت عن النبي ﷺ أنه قال: لا عدوى، ولا طيرة، ولا هامة، ولا صفر، ويعجبني الفأل قيل: يا رسول الله! وما الفأل؟ قال: الكلمة الطيبة.  كانت العرب تعتقد العدوى، ويقولون: إنه إذا خالط المريض الأصحاء؛ أصيبوا بمثل مرضه، وقالوا للنبي ﷺ: يا رسول الله! الإبل تكون كذا وكذا، فيخالطها البعير الأجرب فتجرب، فقال -عليه الصلاة والسلام-: فمن أعدى الأول، لا عدوى ولا طيرة والمعنى نفي العدوى التي يعتقدها الجهال من المشركين، وأن المرض كالجرب، ونحوه يعدي بطبعه، هذا باطل، أما كون الخلطة تؤثر، فهذا ما نفاها النبي ﷺ الخلطة قد تؤثر، قد ينتقل المرض من المريض إلى الصحيح بسبب الخلطة بأمر الله بإذن الله -جل وعلا- لقوله ﷺ: لا يورد ممرض على مصح يعني: لا يورد صاحب إبل مراض على صاحب إبل صحاح؛ من باب تجنب أسباب الشر، وقال: فر من المجذوم فرارك من الأسد هذا من باب اجتناب أسباب الشر.  فالعدوى التي يعتقدها الكفار باطلة، وهو كون المرض ينتقل بنفسه، ويعدي بطبعه من دون قدر الله، ولا مشيئته، هذا باطل. أما كون المرض قد ينتقل من المريض إلى الصحيح بإذن الله فهذا قد يقع، ولهذا قال ﷺ: فر من المجذوم فرارك من الأسد يعني: لا تجالسه؛ قد ينتقل مرضه إليك، وقال: لا يورد ممرض على مصح يعني: إذا ورد الجميع الماء، فالممرض صاحب الإبل المراض لا يوردها مع صاحب الإبل الصحاح، هذا له وقت، وهذا له وقت، بعدًا عن العدوى، بعدًا عن انتقال المرض من المريضة إلى الصحيح. والخلاصة: أن الشريعة جاءت باجتناب أسباب الشر، مع الإيمان بأن الأمور بيد الله، وأنه لا يقع شيء إلا بقضائه وقدره، فاعتقاد المشركين أن العدوى تنتقل حتمًا بنفسها، وطبعها هذا باطل، أما كونه ينتقل بإذن الله إذا شاء فهذا واقع، ولهذا أمر النبي ﷺ بأسباب الوقاية، وقال: لا يورد ممرض على مصح فر من المجذوم فرارك من الأسد مع أنه ﷺ أخذ بيد المجذوم، وأكل معه وقال: كل باسم الله ثقة بالله ليبين أن الأمور بيد الله سبحانه، وأن الله هو الذي يقدر الأمور، فإذا اجتنب مخالطة المجذومين هذا هو المشروع بعدًا عن الشر، ولو فعل ذلك، وأكل معهم؛ لبيان أن الأمور بيد الله، وليتضح للناس أن المرض لا يعدي بطبعه، وأنه إنما ينتقل بقدر الله، إذا فعل هذا بعض الأحيان؛ لإبطال العدوى التي يعتقدها الجاهليون هذا حسن كما فعله النبي ﷺ. نعم. المقدم: إذًا سماحة الشيخ -حفظكم الله- الأخذ بالأسباب لا ينافي التوكل؟ الشيخ: نعم الواجب الأخذ بالأسباب، فالإنسان يبتعد عن أسباب الشر، ويحذر أسباب المرض، ولا يعرض نفسه للخطر، ومع هذا يعتمد على الله، ويتوكل، ويعلم أن الأمور بيده : وَعَلَى اللَّهِ فَتَوَكَّلُوا إِنْ كُنتُمْ مُؤْمِنِينَ [المائدة:23] وَمَنْ يَتَوَكَّلْ عَلَى اللَّهِ فَهُوَ حَسْبُهُ[الطلاق:3] ولكن مع اجتناب أسباب الشر، فلا يخالط المرضى الذين قد جرت العادة بإذن الله أن مرضهم ينتقل، ولا يخالط أهل الشر؛ لأنه قد يصيبه ما أصابهم من الشر؛ فيفعل أفعالهم، ويحرص على صحبة الأخيار؛ لأن ذلك من أسباب أن يتخلق بأخلاقهم، ولا يأكل الأشياء التي قد تضر، قد يعرف أنها تضر، وما أشبه ذلك. نعم. المقدم: أحسن الله إليكم، وبارك فيكم، سماحة الشيخ! في الحديث: لا عدوى ولا طيرة تشاؤم البعض من الناس في بعض الشهور كشهر صفر، هل له أصل يا شيخ؟ الشيخ: لا، جاء في الحديث: لا عدوى، ولا طيرة، ولا هامة، ولا صفر باطل صفر مثل بقية الشهور، لا يجوز التشاؤم به، وقد أبطله النبي ﷺ بقوله: لا عدوى ولا طيرة ولا هامة الهامة: طائر يتشاءم به أيضًا أهل الجاهلية، يقولون: إنه إذا صاح على بيت؛ هلك أهله، وهو باطل، وصفر الشهر المعروف، كان بعض أهل الجاهلية يتشاءمون به، فأبطل النبي ﷺ هذا وبيَّن أنه مثل بقية الشهور ليس فيه شؤم، والطيرة معروفة، التطير بالمرئيات، أو المسموعات، كانوا يتطيرون، أهل الجاهلية قد يتطير بغراب، أو بغيره؛ فأبطل النبي ﷺ هذا، وقال: لا طيرة نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16140/معنى-حديث-لا-عدوى-ولا-طيرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_769/nour_76903.mp3","categories":["شروح الحديث"]},{"id":17292,"question":"على بركة الله نبدأ هذا اللقاء برسالة من اليمن أبو الحسن رمز لاسمه بهذا الاسم (م. ح. ب) يقول: سماحة الشيخ ورد في الحديث الصحيح: أن عمرة في رمضان تعدل حجة معي في ماذا -يا سماحة الشيخ- تعدلها؟ أهو في الأجر؟ أم في الكيفية؟ أم ماذا؟ وجهونا مأجورين.","title":"معنى حديث: \"عمرة في رمضان...\"","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه. الحديث المذكور صحيح، رواه البخاري ومسلم في الصحيحين، ومعنى ذلك أنها تعدل حجة معه في الأجر، يقول ﷺ: عمرة في رمضان تعدل حجة وفي لفظ آخر: حجة معي فهذا يدل على فضلها، وأنها في رمضان لها مزية عظيمة، وأجر عظيم كالذي حج مع النبي ﷺ. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16135/معنى-حديث-عمرة-في-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_769/nour_76901.mp3","categories":["شروح الحديث"]},{"id":17349,"question":"أيام التشريق أيام أكل وشرب، وذكر لله تعالى، ما معنى هذا يا شيخ؟","title":"معنى حديث: \"أيام التشريق أيام أكل...\"","answer":"الجواب: معناه أنها لا تصام، النبي ﷺ نهى عن صوم أيام التشريق، وبعث من ينادي في الناس ألا تصام؛ لأنها أيام أكل، وشرب، وذكر، الناس يأكلون، ويشربون، ويتقربون إلى الله بالذبائح، بالهدي والضحايا؛ فيأكلون ويشربون، ما هي بأيام صوم، لا صوم فريضة، ولا صوم نافلة، بل الواجب الفطر في يوم العيد، وأيام التشريق أربعة أيام يجب إفطارها، فهي أيام أكل وشرب وذكر، إلا من لم يستطع الهدي هدي التمتع؛ فإنه له أن يصوم الثلاثة الأيام، خاصة من الناس؛ لما ثبت في البخاري في صحيحه -رحمه الله- عن عائشة، وابن عمر -رضي الله تعالى عنهما- قالا: لم يرخص في أيام التشريق أن يصمن إلا لمن لم يجد الهدي هكذا رواه البخاري في الصحيح من حديث عائشة، وابن عمر. ومعنى لم يرخص يعني: لم يرخص النبي ﷺ به، إذا قال الصحابي: لم يرخص أو رخص أو أمرنا أو.. هذا المراد به النبي ﷺ هكذا قال أهل العلم؛ لأن الرسول هو الآمر الناهي المرخص، عليه الصلاة والسلام.  فمعنى: لم يرخص يعني: أن النبي ﷺ لم يرخص لأحد أن يصوم أيام التشريق إلا من عجز عن الهدي؛ فله أن يصوم الثلاثة إذا لم يصمها قبل الحج، إذا لم يصمها قبل عرفة، فله أن يصومها هذه الأيام، وله أن يؤخرها. نعم. المقدم: أحسن الله إليكم، وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16194/معنى-حديث-ايام-التشريق-ايام-اكل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_769/nour_76911.mp3","categories":["شروح الحديث"]},{"id":17381,"question":"تقول في سؤالها الثاني: قرأت حديثًا عن النبي ﷺ (أنه رأى ذات مرة سلسلة من الذهب في يد ابنته فاطمة -رضي الله عنها- فغضب  وقال لها: أيسرك أن يقول الناس: ابنة رسول الله ﷺ وفي يدها سلسلة من نار ثم خرج  ولم يجلس، فما كان من فاطمة -رضي الله عنها- إلا أن باعت السلسلة، واشترت بثمنها غلامًا، فأعتقته، فلما علم الرسول ﷺ بذلك قال: الحمد لله الذي أنجى فاطمة من النار والسؤال هو يا سماحة الشيخ: كيف نستطيع الجمع بين هذا الحديث، والحديث الذي جاء فيه ما معناه بأن الذهب والحرير حل لنساء هذه الأمة دون رجالها؟","title":"توجيه حديث فاطمة: (أيسرك أن يقول الناس...)","answer":"الجواب: حديث فاطمة هذا عند جمع من أهل العلم غير صحيح، إسناده مخالف للأحاديث الصحيحة، وقال بعضهم: إنه منسوخ، كان في أول الأمر لم يبح الذهب، ثم أبيح، والصواب أنه منسوخ، ولا عمل عليه لقوله ﷺ: أحل الذهب والحرير لإناث أمتي، وحرم على ذكورهم ولأحاديث صحيحة كثيرة فيها بيان حل الذهب لإناث الأمة، فهذا الحديث حديث فاطمة بعض أهل العلم يراه منسوخًا، وبعضهم يقول: إنه غير صحيح، وأنه شاذ، مخالف للأحاديث الصحيحة. قد أجمع أهل العلم على حل الذهب، والحرير لإناث الأمة، حكى ذلك غير واحد من أهل العلم، أجمع أهل السنة على حل الذهب، والحرير لإناث الأمة، وتحريمها على الذكور. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16235/توجيه-حديث-فاطمة-ايسرك-ان-يقول-الناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_770/nour_77011.mp3","categories":["الحكم على الأحاديث","قضايا المرأة","شروح الحديث"]},{"id":17406,"question":"سائل فضيلة الشيخ هذا ..... أمجد، يستفسر عن معنى حديث قال رسول الله ﷺ للصحابة: ما الذي تخوضون فيه؟ فأخبروه عن أولئك الناس، فقال: هم أولئك الذين لا يرقون، ولا يتطيرون، وعلى ربهم يتوكلون؟","title":"شرح حديث الذين يدخلون الجنة بغير حساب","answer":"الجواب: هذا جاء في حديث السبعين، النبي ﷺ أخبر أصحابه أنه عرضت عليه أمته، وكان فيهم سبعون ألفًا يدخلون الجنة بغير حساب، ولا عذاب، فخاض الناس في أولئك: من هم؟ لما حدث بهذا الحديث، وقام -عليه الصلاة والسلام- خاضوا، فقال بعضهم: فلعلهم الذين ولدوا في الإسلام، وقال بعضهم: فلعلهم الذين صحبوا الرسول ﷺ يعني: من الصغر، ولم يكفروا، وخاضوا في غير هذا. ثم خرج عليهم ﷺ قال: ما ... ؟ سألهم عما يخوضون فيه، فأخبروه، فقال: هم الذين لا يسترقون، ولا يتطيرون، ولا يكتوون، وعلى ربهم يتوكلون هذه من صفاتهم، مع تقواهم لله، وإيمانهم بالله، واستقامتهم على دينه، هم مع هذا لا يسترقون يعني: لا يسألون الناس أن يرقوهم.  ولا يتطيرون الطيرة: التشاؤم بالمرئيات، والمسموعات، هذه الطيرة ما أمضاك، أو ردك بسبب التشاؤم. ولا يكتوون يعني: إذا مرضوا ما يكتوون. وعلى ربهم يتوكلون هذه من صفاتهم العظيمة.  ولكن يجوز الكي، الرسول ﷺ رخص في الكي، ويجوز الاسترقاء، رخص في الاسترقاء أيضًا لعائشة، وأم أولاد جعفر، لا حرج في الاسترقاء، كونه يطلب من يرقيه لا حرج، لكن تركه أفضل إذا تيسر دواء آخر غير الاسترقاء أفضل، وهكذا الكي لا بأس به عند الحاجة إليه؛ لقوله ﷺ: الشفاء في ثلاث: كية نار، أو شرطة محجم، أو شربة عسل، وما أحب أن أكتوي.  أما الطيرة لا تجوز أبدًا ... محرمة؛ لأنها تشاؤم، لا يجوز، أما رواية: لا يرقون فهي رواية ضعيفة، رواها مسلم، ولكنها ضعيفة، غلط من بعض الرواة: لا يرقون فإن رقية الإنسان لأخيه مطلوبة، كونك ترقي أخاك هذا مشروع، النبي  قال: لا بأس بالرقى ما لم تكن شركًا وقد رقى النبي ﷺ بعض أصحابه، ورقي ﷺ رقته عائشة -رضي الله عنها- لما مرض، والصحابة رقى بعضهم بعضًا، لا بأس بالرقية. أما الاسترقاء كونه يقول: \"اقرأ لي يا فلان\" هذا تركه أفضل إلا عند الحاجة، إلا عند الحاجة، إذا احتاج للاسترقاء؛ لا حرج؛ لقوله لعائشة: استرقي ولقوله لأم أولاد جعفر: استرقي فلا حرج في ذلك، إنما الاسترقاء تركه أفضل؛ لأنه سؤال للناس، وشحاذة، وتركه أفضل. فإن دعت الحاجة إليه كالكي، إذا دعت الحاجة إليه؛ لا بأس، لا بأس أن يقول: يا أخ فلان اقرأ علي -جزاك الله خيرًا- أو يذهب إلى الراقي يرقى عليه، لا بأس، أو يكوي عند الحاجة إذا ظن أن الكي مفيد في هذا الشيء؛ فلا بأس، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16265/شرح-حديث-الذين-يدخلون-الجنة-بغير-حساب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_771/nour_77107.mp3","categories":["شروح الحديث","الرقى والتمائم"]},{"id":17490,"question":"سماحة الشيخ! هذا السائل أبو سعد يقول: ما هو الفرق بين حديث الرسول ﷺ: من حسن إسلام المرء تركه ما لا يعنيه وبين حديث الرسول ﷺ: من رأى منكم منكرًا فليغيره بيده .. إلى آخر الحديث؟","title":"الجمع بين حديثين في ترك ما لا يعني وتغيير المنكر","answer":"الجواب: ليس بينهما تعارض، هذا معناه شيء، وهذا معناه شيء من حسن إسلام المرء تركه ما لا يعنيه الشيء الذي ما يعنيه، ولا له فيه دخل، ولا يهمه لا يتعرض له، ولا يدخل نفسه في شيء ما له فيه لزوم، إنسان يسار أخاه يقول: إيش تقولون؟ وإيش عليه منهم؟! وإيش يضره؟! إنسان ذهب يزور أخاه، يقول: ليش تزوره، ليش تبي تزوره؟ يعني: لا يشغله، ما لا يعنيه، ما لا يهمه، الشيء الذي ما له فيه لزوم لا يسأل عنه، لا يدخل فيما لا يعنيه. أما المنكر هو يعنيه، الرسول ﷺ أمر بإنكار المنكر، بل الله أمر بذلك، قال -جل وعلا-: وَلْتَكُنْ مِنْكُمْ أُمَّةٌ يَدْعُونَ إِلَى الْخَيْرِ وَيَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ وَأُوْلَئِكَ هُمُ الْمُفْلِحُونَ [آل عمران:104] فالمؤمن مأمور بهذا، وقال : كُنْتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ تَأْمُرُونَ بِالْمَعْرُوفِ وَتَنْهَوْنَ عَنِ الْمُنكَرِ وَتُؤْمِنُونَ بِاللَّهِ[آل عمران:110] ويقول -جل وعلا-: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ [التوبة:71] ويقول النبي ﷺ: من رأى منكم منكرًا فليغيره بيده، فإن لم يستطع فبلسانه، فإن لم يستطع فبقلبه؛ وذلك أضعف الإيمان فهذا يعني المؤمن، يعني: كل مؤمن، وكل مؤمنة، بل واجب على الجميع إنكار المنكر، ليس داخلة في الأحاديث: من حسن إسلام المرء تركه ما لا يعنيه هذا شيء، وهذا شيء، نعم. المقدم: أحسن الله إليكم سماحة الشيخ، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/16392/الجمع-بين-حديثين-في-ترك-ما-لا-يعني-وتغيير-المنكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_773/nour_77316.mp3","categories":["شروح الحديث"]},{"id":17580,"question":"أخيرًا يسأل عن علامات الساعة ويقول: إن الرسول عليه أفضل الصلاة والسلام حدد لنا بعضًا منها وقال في ذلك: أن تلد الأمة ربتها، فما معنى هذه العبارة؟","title":"معنى قول النبي ﷺ: \"أن تلد الأمة ربتها\"","answer":"الجواب: أشراط الساعة كثيرة، ولكنها قسمان: قسم مطلق وجد في عهد النبي ﷺ وبعده، وقسم خاص يقع عند قربها وعند دنوها، أما المطلق العام فهذا النبي ﷺ من أشراط الساعة، نبينا محمد ﷺ هو نبي الساعة، ووجوده من أشراطها عليه الصلاة والسلام، وهكذا ما قال ﷺ: أن تلد الأمة ربتها، ربتها يعني: سيدتها، وفي اللفظ الآخر: ربها يعني: سيدها، ومعنى ذلك أنها تكثر الإماء والسراري، فإذا حملت من سيدها وهو مالكها فإن المولودة البنت تكون سيدة، ربة، والمولود الذكر يكون ربًا لها.. سيدًا لها، هذا معنى الحديث، يعني: تكثر السراري، يكثر الإماء، والناس يكثر تسريهم بسبب كثرة الجهاد وكثرة الغنائم فتكثر السراري بين الناس، والسيد يطأ أمته؛ لأنها ملكه مباح له، كما قال تعالى: وَالَّذِينَ هُمْ لِفُرُوجِهِمْ حَافِظُونَ ۝ إِلَّا عَلَى أَزْوَاجِهِمْ أوْ مَا مَلَكَتْ أَيْمَانُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ [المؤمنون:5-6]، فالملك الذي هو ملكه للأمة يقال له: ملك اليمين، إذا ملكها بالغنيمة أو بالشراء أو بالورث فله أن يطأها وهي ملك اليمين، وإذا ولدت يقال للمولود إن كان ذكر: ربها وسيدها، والمولودة: ربتها وسيدتها، هذا معنى الحديث: أن تلد الأمة ربها أو ربتها، يعني: سيدتها؛ لأن بنت السيد سيدة، وولد السيد سيدًا لأمه في المعنى، والمعنى أنها تكثر السراري في الناس، وهذا من علامات الساعة، كثرة السراري وكثرة الإماء والولادة.\nومنه الحديث: أن ترى الحفاة العراة العالة رعاء الشاء يتطاولون في البنيان، فهذا أيضًا من أشراطها العامة، تطاول العرب في البناء بعدما كانوا أهل خيام، بنوا البنايات وطولوها، هذا من أشراط الساعة، وقد وقع هذا، العرب تحضروا وجاهدوا وبنوا البنايات وعمروا العمائر.\nأما أشراطها الخاصة القريبة منها فقد بينتها الأحاديث وهي عشر علامات:\nأولها: المهدي ، رجل من أهل البيت في آخر الزمان يملك الدنيا يملك الأرض ويملؤها عدلًا بعد ملئها جورًا، وهو من أهل البيت من بني هاشم من ذرية فاطمة رضي الله عنها، جاءت فيه أحاديث كثيرة.\nالثاني: الدجال، خروج الدجال في آخر الزمان يدعي أنه نبي ثم يدعي أنه رب العالمين، وقد صحت فيه الأحاديث وتواترت عن النبي ﷺ.\nوالثالث: نزول المسيح ابن مريم من السماء، عيسى ابن مريم عليه الصلاة والسلام يقتل الدجال، ويحصل به الخير العظيم للأمة، ويخرج الله به بركاتها في هذه الأرض، عليه الصلاة والسلام، ولا يقبل إلا الإسلام، ويهلك الله في زمانه الأديان فلا يبقى إلا الإسلام، تذهب اليهودية والنصرانية والشيوعية وغيرها، ولا يبقى إلا الإسلام في عهده عليه الصلاة والسلام.\nوالرابع: خروج يأجوج ومأجوج من الشرق، وهم من كل حدب ينسلون، في عهد عيسى عليه الصلاة والسلام، ثم يقتلهم الله.. يميتهم الله بعد ذلك.\nثم بعد ذلك: آية الدخان، وهدم الكعبة، ورفع المصحف.. رفع القرآن من الأرض من الصدور ومن الصحف، ثم خروج الدابة دابة الأرض، وطلوع الشمس من مغربها، وإذا طلعت لا تقبل التوبة بعد ذلك من أحد.\nوآخرها: نار تحشر الناس إلى محشرهم.\nهذه يقال لها: الآيات الخاصة القريبة من قيام الساعة، جاءت بها الأحاديث وبينها أهل العلم. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16510/معنى-قول-النبي-ﷺ-ان-تلد-الامة-ربتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_839/nour_83911.mp3","categories":["شروح الحديث"]},{"id":17646,"question":"نعود مع مطلع هذه الحلقة إلى رسالة وصلت إلى البرنامج من الأردن جرش، باعثة الرسالة إحدى الأخوات المستمعات من هناك، تقول: أختكم في الله فاطمة محمد ، أختنا عرضنا لها سؤالًا في حلقةٍ مضت، وفي هذه الحلقة تسأل عن حديث الرسول ﷺ الذي معناه: ومن مس الحصى فقد لغا ماذا يقصد بالحصى؟ وهل هي مقصودة لذاتها؟ أو أنها تشير إلى معانٍ فقط؟ جزاكم الله خيرًا.","title":"معنى حديث: \"من مس الحصى فقد لغا\"","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد:\nهذا الحديث الصحيح أرشد به النبي ﷺ إلى الإنصات للخطيب يوم الجمعة، وعدم العبث بما يشغله عن سماع الخطبة، ومس الحصى من ذلك، وليس مقصودًا بذاته، بل المقصود العناية في الاستماع، والبعد عما يشغل عن الاستماع والإنصات، فإذا مس الحصى، أو مس أشياء أخرى في المسجد، من أهداب الفرش، أو من أوراقٍ عنده، أو ما أشبه ذلك، أشبه ذلك مس الحصى.\nفالمقصود كله؛ هو أن ينصت للخطيب، وأن يفرغ قلبه لذلك، ويكف جوارحه عن العبث الذي قد يشغله عن الاستماع، ومعنى فقد لغا أي لغت جمعته، يعني ما يكون له ثواب الجمعة، يكون له ثواب الظهر، ما هو ثواب الجمعة؛ يعني يفوته الثواب العظيم الذي رتبه الله على الجمعة. نعم.\nالمقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16577/معنى-حديث-من-مس-الحصى-فقد-لغا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_727/nour_72701.mp3","categories":["صلاة الجمعة","شروح الحديث"]},{"id":17649,"question":"تسأل عن هذه العبارة سماحة الشيخ، وتقول: هل هي حديث:  \"إذا ابتليتم فاستتروا\"؟","title":"هل (إذا ابتليتم فاستتروا) حديث؟","answer":"الجواب: جاء معناه في حديث فيه ضعف، مرسل عن زيد بن أسلم أن النبي عليه الصلاة والسلام قال: من أصاب شيئًا من هذه القاذورات يعني: المعاصي فليتب إلى الله، وليستتر بستر الله وهذا يدل على أنه ينبغي للمؤمن أن يستتر بستر الله، وألا يفضح نفسه، ولهذا لما جاء ماعز إلى النبي ﷺ يقول: إنه زنا، أعرض عنه النبي ﷺ مرات، لعله يتوب ويستغفر، ويرجع؛ حتى لا يتظاهر بهذا الأمر العظيم.\nفالمقصود؛ أن الإنسان مأمور بالستر، والتوبة إلى الله، وعدم إبراز معصيته وإظهارها للناس، ومن تاب تاب الله عليه، ولهذا يقول ﷺ: من ستر مسلمًا؛ ستره الله في الدنيا والآخرة فالمؤمن يستر نفسه، ولا يعلن معصيته، لكن متى أعلنها إلى ولي الأمر، وجب أن يقام عليه الحد، إذا كانت فيها حد، وإن كان فيها تعزير، وجب التعزير، لكن هو مشروع له أن لا يبديها للناس، وأن لا يذهب إلى الحاكم، بل يستتر بستر الله، وليتب إلى الله، وليستغفر الله، ويكفي والحمد لله، هذا هو المشروع. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16579/هل-اذا-ابتليتم-فاستتروا-حديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_727/nour_72702.mp3","categories":["شروح الحديث","الحكم على الأحاديث"]},{"id":17695,"question":"ما صحة قول: يحيي ويميت في قول: لا إله إلا الله وحده لا شريك له، له الملك وله الحمد يحيي ويميت وهو على كل شيء قدير؟","title":"الحكم على زيادة (يحيي ويميت) في الذكر الوارد","answer":"الجواب: كان النبي ﷺ يقول هذا، طيب، ربما قاله وربما تركه الأمر واسع، فإذا قال: لا إله إلا الله وحده لا شريك له، له الملك وله الحمد وهو على كل شيء قدير لا بأس، وإن زاد وقال: يحيي ويميت فلا بأس، وإن زاد: بيده الخير فلا بأس، وإن زاد: وهو حي لا يموت فلا بأس، الأمر واسع كلها جاءت عن النبي ﷺ، فالأمر في هذا واسع والحمد لله، لا إله إلا الله وحده لا شريك له، له الملك وله الحمد وهو على كل شيء قدير، بعد السلام بعدما يقول: أستغفر الله أستغفر الله أستغفر الله اللهم أنت السلام ومنك السلام تباركت يا ذا الجلال والإكرام، وإذا زاد: يحيي ويميت فلا حرج، ويأتي بهذا الذكر عشر مرات بعد المغرب وبعد الفجر ويزيد فيها يحيي ويميت؛ لأنها وردت فيها الأحاديث أيضًا.\nفالمقصود: الأمر واسع، إذا أتى بها أو حذفها الأمر واسع والحمد لله كلها جاءت في النصوص، فجاء يحيي ويميت، وجاء بيده الخير، وجاءت زيادة: وهو حي لا يموت كل هذا طيب والحمد لله.\nالمقدم: أحسن الله إليكم، وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16643/الحكم-على-زيادة-يحيي-ويميت-في-الذكر-الوارد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_776/nour_77605.mp3","categories":["شروح الحديث","الحكم على الأحاديث","الأدعية والأذكار"]},{"id":17711,"question":"من ضمن أسئلة هذه السائلة أم مريم تقول: يرد كثير من الأحاديث: دبر كل صلاة فهل المقصود بها بعد انقضاء الصلاة أم قبل السلام؟","title":"المقصود بدبر الصلاة","answer":"الجواب: دبر الصلاة آخرها قبل السلام، هذا هو الأصل مثل دبر الحيوان مؤخره، فدبر الصلاة ما كان قبل السلام؛ آخرها قبل السلام يستحب فيه الدعاء بعد قراءة التحيات والصلاة على النبي ﷺ والتعوذ بالله من عذاب جهنم ومن عذاب القبر ومن فتنة المحيا والممات ومن فتنة المسيح الدجال، يستحب أن يدعو بعد هذا قبل أن يسلم في الفرض والنفل، وإن دعا بعد الذكر بعد السلام بعد العشاء فلا بأس بينه وبين نفسه، لكن الأفضل أن يكون الدعاء قبل السلام وبعد قراءة التحيات والصلاة على النبي ﷺ وبعد التعوذ بالله من عذاب جهنم ومن عذاب القبر ومن فتنة المحيا والممات ومن فتنة المسيح الدجال ؛ لأن الدبر؛ دبر الشيء آخره، ودبر الصلاة آخرها قبل السلام كما في الحديث أنه قال لمعاذ: لا تدعن دبر كل صلاة أن تقول: اللهم أعني على ذكرك وشكرك وحسن عبادتك هذا قبل السلام. وأما الحديث الآخر: كان النبي ﷺ يقول في دبر الصلاة بعد السلام: لا إله إلا الله فهذا مراده بعد السلام يأتي بالأذكار الشرعية، يقول: أستغفر الله أستغفر الله أستغفر الله يعني: بعد السلام، اللهم أنت السلام ومنك السلام تباركت يا ذا الجلال والإكرام، ثم يقول: لا إله إلا الله، كما كان النبي يفعل عليه الصلاة والسلام بعد السلام.\nالمقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16664/المقصود-بدبر-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_776/nour_77617.mp3","categories":["شروح الحديث","التشهد والتسليم"]},{"id":17741,"question":"هذا سائل للبرنامج يقول: ما معنى قول الرسول ﷺ: صنفان من أهل النار لم أرهما.. وذكر منهم: نساء كاسيات عاريات مائلات مميلات، رؤوسهن كأسنمة البخت المائلة؟","title":"معنى قول النبي ﷺ: \"صنفان من أهل النار...\"","answer":"الجواب: فسر العلماء هذا بأنهن كاسيات من نعم الله، عاريات من شكرها، وفسره آخرون بأنهن كاسيات ثياب رقيقة أو قصيرة عاريات؛ لأن الثوب القصير والرقيق ما هو كسوة. مائلات عن الحق عن العفة، مميلات لغيرهن إلى الفساد والزنا، هؤلاء متوعدون بالنار هؤلاء النسوة متوعدات بالنار؛ لهذا العمل السيئ، كونهن كاسيات عاريات كاسيات ثيابًا رقيقة أو قصيرة، عاريات في الحقيقة، أو كاسيات من النعم، عاريات من شكر الله بالمعاصي، يعني: عريهن؛ فعلهن المعاصي، مائلات عن الحق وعن العفة، مميلات لغيرهن نسأل الله العافية. نعم.\nرؤوسهن مثل أسنمة البخت المائلة يعني: يعظمن رؤوسهن، يجعلن على رؤوسهن أشياء كبيرة تعظمها. نعم.","link":"https://binbaz.org.sa/fatwas/16697/معنى-قول-النبي-ﷺ-صنفان-من-اهل-النار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_209/nour_20912.mp3","categories":["شروح الحديث","قضايا المرأة","اللباس والزينة"]},{"id":17772,"question":"هل الإصابة بالمرض كالعين مثلًا وغير ذلك يا سماحة الشيخ، هل هذا من العقوبات الدنيوية؟ وما معنى الحديث: احفظ الله يحفظك؟","title":"هل الأمراض عقوبة؟ وما معنى: \"احفظ الله يحفظك...\"","answer":"الجواب: قد يقع هذا عقوبة، وقد يقع ابتلاء وامتحان؛ ليرفع الله درجاته، قال جل وعلا: مَا أَصَابَ مِنْ مُصِيبَةٍ فِي الأَرْضِ وَلا فِي أَنْفُسِكُمْ إِلَّا فِي كِتَابٍ [الحديد:22] .. وَمَا أَصَابَكُمْ مِنْ مُصِيبَةٍ فَبِمَا كَسَبَتْ أَيْدِيكُمْ وَيَعْفُوا عَنْ كَثِيرٍ [الشورى:30]، هذا كثير يقع بسبب كسب اليد، قد يفعل أشياء تسبب المصيبة، وقد تنزل المصيبة لحكمة بالغة كما يقع للأنبياء وغير الأنبياء؛ ليرفع الله درجاتهم ويعظم أجورهم ، ولهذا يقول ﷺ: عجبًا لأمر المؤمن، إن أمره كله له خير: إن أصابته ضراء صبر؛ فكان خيرًا له، وإن أصابته سراء شكر؛ فكان خيرًا له وفي الحديث: من يرد الله به خيرًا يصب منه اللهم صل على محمد، فالعبد يصاب بمصيبة من غير سيئة، بل ليرفع الله درجاته ويعظم أجره، إن عظم الجزاء مع عظم البلاء. نعم.\nالمقدم: سماحة الشيخ! لعلنا نستأنس الحقيقة بشرحكم لهذا الحديث العظيم: احفظ الله يحفظك، احفظ الله تجده تجاهك...\nالشيخ: هذا حديث ابن عباس حديث عظيم، احفظ الله بطاعته والاستقامة على دينه؛ يحفظك من كل شر، احفظ الله تجده تجاهك -يعني: أمامك- إذا سألت فاسأل الله، وإذا استعنت فاستعن بالله هذا مشروع للمؤمن أن يعتني بهذا وأن يحفظ حدود الله ومحارمه، وأن يؤدي الواجبات، وأن يحذر كل ما نهى الله عنه، وهذا من أسباب حفظ الله له، ومن أسباب توفيق الله له جل وعلا.\nوكذلك ينزل حاجته بالله، يسأل الله ويستعين بالله، ويضع حاجاته بالله جل وعلا، كل هذا من أسباب التوفيق، يعني: ينزل حاجاته بالله، يسأل ربه كل حاجة، أن الله ييسر له كذا وييسر له كذا ويعطيه كذا ويرحمه من كذا، ويكفيه شر الذنوب، ويعينه على طاعة الله، ويرزقه الرزق الحلال، يطلب الله من فضله جل وعلا، ويحفظ الله بحفظ طاعته وترك معصيته. نعم.\nالمقدم: حفظكم الله سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16752/هل-الامراض-عقوبة-وما-معنى-احفظ-الله-يحفظك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_596/59624.mp3","categories":["شروح الحديث","الرقائق"]},{"id":17856,"question":"هذه الأخت السائلة (زينب . ح. ع) من الرومنة تقول سماحة الشيخ: قال الله تعالى في الحديث القدسي: يا ابن آدم لو بلغت ذنوبك عنان السماء، ثم استغفرتني؛ غفرت لك ولا أبالي هل معنى هذا هو الاستغفار أن أقول: أستغفر الله؟ أم أنه بشكل آخر؟","title":"معنى قوله \"ثم استغفرتني...\"","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه أجمعين.\nأما بعد:\nفالاستغفار المطلوب هو طلب المغفرة، يقول: اللهم اغفر لي، كما قال تعالى: وَاسْتَغْفِرُوا اللَّهَ إِنَّ اللَّهَ غَفُورٌ رَحِيمٌ [البقرة:199] اللهم اغفر لي، أستغفر الله وأتوب إليه، لكن مع توبة، الكلام بغير التوبة ما ينفع، لابد توبة، لابد مع التوبة والندم والإقلاع، كما قال تعالى: وَالَّذِينَ إِذَا فَعَلُوا فَاحِشَةً أَوْ ظَلَمُوا أَنْفُسَهُمْ ذَكَرُوا اللَّهَ فَاسْتَغْفَرُوا لِذُنُوبِهِمْ وَمَنْ يَغْفِرُ الذُّنُوبَ إِلَّا اللَّهُ وَلَمْ يُصِرُّوا عَلَى مَا فَعَلُوا وَهُمْ يَعْلَمُونَ ۝  أُوْلَئِكَ جَزَاؤُهُمْ مَغْفِرَةٌ مِنْ رَبِّهِمْ وَجَنَّاتٌ تَجْرِي مِنْ تَحْتِهَا الأَنْهَارُ خَالِدِينَ فِيهَا وَنِعْمَ أَجْرُ الْعَامِلِينَ [آل عمران:135-136]. فالاستغفار يكون معه توبة، ومعه ندم، ومعه إقلاع؛ حتى ينفع ويحصل به المطلوب من محو الذنوب وغفرانها، أما قول باللسان مع الإقامة على المعاصي فلا ينفع، نسأل الله العافية.\nالمقدم: نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/16862/معنى-قوله-ثم-استغفرتني","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_598/59801.mp3","categories":["الأدعية والأذكار","شروح الحديث","مسائل متفرقة في الصلاة"]},{"id":17863,"question":"تقول السائلة من مكة المكرمة سماحة الشيخ: قال ﷺ: من توضأ يوم الجمعة فبها ونعمت، ومن اغتسل فالغسل أفضل رواه أحمد ، وحديث: غسل الجمعة واجب على كل محتلم رواه الشيخان، كيف نجمع بين هذين الحديثين، وهل الاغتسال سنة أم واجب، وما معنى على كل محتلم، واشرحوا لنا الأحاديث؟","title":"الجمع بين «غسل الجمعة واجب على كل محتلم»، «ومن اغتسل فالغسل أفضل»","answer":"معنى واجب يعني: متأكد، ليس معناه الوجوب الذي يأثم به، معناه المتأكد، ولهذا جاء في الحديث معناه: \"وأن يستاك ويتطيب\" والسواك والطيب مستحبان عند الجميع، بإجماع أهل العلم، وجاء في الحديث من توضأ يوم الجمعة ثم أتى المسجد وصلى ما قدر له ثم أنصت حتى ... الخطبة كتب له .. كان له ثواب الجمعة وما بعدها إلى جمعة أخرى.","link":"https://binbaz.org.sa/fatwas/16872/الجمع-بين-غسل-الجمعة-واجب-على-كل-محتلم-ومن-اغتسل-فالغسل-افضل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_598/59808.mp3","categories":["صلاة الجمعة","شروح الحديث"]},{"id":17898,"question":"من الأخت المستمعة (س. س) من المدينة المنورة رسالة وضمنتها جمعًا من الأسئلة: في أحد أسئلتها تقول: سمعت بحديث من ضمن ما قاله ﷺ: الصبر عند الصدمة الأولى فما معنى ذلك؟","title":"معنى حديث: «إنما الصبر عند الصدمة الأولى»","answer":"الجواب: هذا حديث صحيح، رأى امرأة تبكي صبيًا فنصحها فقالت: إليك عني فإنك لم تصب بمثل مصيبتي، فلما أخبرت أنه الرسول ﷺ ذهبت إليه في بيته فلم تجد عند بابه بوابًا فاستأذنت عليه وأخبرته أنها لم تعرفه، فقال لها ﷺ: إنما الصبر عند الصدمة الأولى يعني: الصبر الذي فيه الثواب والأجر هو ما يحصل عند أول المصيبة من موت قريب أو مرض أو مفاجأة بشيء يضر الإنسان يصبر ويحتسب، فلا يجزع، ولا يتكلم بسوء، ولا يفعل ما لا ينبغي عند الصدمة الأولى، فيثاب على ذلك. أما إذا فعل ما لا ينبغي ثم صبر بعد ذلك فهذا ما ينفع، الصبر لابد منه، سوف يقع، سوف يتسلى بعد ذلك إذا طالت المدة كصبر البهائم هذا لا ينفع، الصبر الذي فيه الأجر العظيم عند الصدمة الأولى، عند أول ما تنزل به المصيبة من موت أو غيره يتحمل ولا يجزع ولا ينح ولا ينتف شعرًا ولا يشق ثوبًا، ولا يرفع صوته بالنياحة، هكذا يكون الصبر، بل يتحمل ويسأل ربه التوفيق، ويقول: إنا لله وإنا إليه راجعون، قدر الله وما شاء فعل، ولا يجزع، ولا يفعل ما لا ينبغي، ولا يقل ما لا ينبغي. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16935/معنى-حديث-انما-الصبر-عند-الصدمة-الاولى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_846/nour_84611.mp3","categories":["شروح الحديث","الحكم على الأحاديث"]},{"id":17912,"question":"بعد هذا ننتقل إلى رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات، تقول: المرسلة عائشة جبر ، أختنا لها جمعٌ من الأسئلة، في أحدها تقول: جاء عن الرسول ﷺ: ما من عبدٍ يسجد لله سجدة، إلا رفعه بها درجة، وحط بها عنه خطيئة هل المقصود بالسجدة هنا: الركعة كاملة؟ أم ما هو المقصود؟ جزاكم الله خيرًا.","title":"المقصود بقوله ﷺ : \"ما من عبد يسجد لله سجدة...\"","answer":"الجوب: السجود المعروف، ولهذا أرشد النبي إلى هذا عليه الصلاة والسلام، وبين هذا: ما من عبدٍ يسجد لله سجدة، إلا رفعه بها درجة، وحط عنه بها خطيئة فالمراد السجود المعروف، وهو وضع الجبهة والأنف في الأرض، في الصلاة، ويطلق السجود على الصلوات، كما في حديث ربيعة بن كعب الأسلمي ، حين قال يا رسول الله! أسألك مرافقتك في الجنة؟ قال: أو غير ذلك ؟ قال: لا أسألك إلا ذلك، قال: أعني على نفسك بكثرة السجود يعني: بكثرة الصلاة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16919/المقصود-بقوله-ﷺ-ما-من-عبد-يسجد-لله-سجدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_728/nour_72816.mp3","categories":["شروح الحديث"]},{"id":17993,"question":"تقول: قرأت أن الرسول ﷺ كان يتعوذ من الجن وضلع الدين وغلبة الرجال، فما معنى ذلك؟","title":"معنى حديث: \"اللهم إني أعوذ بك من الهم...\"","answer":"الجواب: في الحديث الصحيح: اللهم إني أعوذ بك من الهم والحزن والعجز والكسل والجبن والبخل  ما هو بالجن، (الجبن) والبخل- ومن غلبة الدين وقهر الرجال هذا الحديث الصحيح، الجبن بدل الجن، اللهم إني أعوذ بك من الهم والحزن والعجز والكسل والجذام والجبن والبخل وأعوذ بك من المأثم والمغرم ومن غلبة الدين وقهر الرجال، وإذا استعاذ من الجن كذلك، من أسد وأسود وحية وعقرب، يقول: اللهم إني أعوذ بك من شر الجن، من شر الدواب، من شر الإنس والجن، كله طيب. نعم.\nالمقدم: جزاكم الله خيرًا، غلبة الرجال؟\nالشيخ: قهرهم. نعم.\nالمقدم: قهرهم؟\nالشيخ: قهرهم. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17026/معنى-حديث-اللهم-اني-اعوذ-بك-من-الهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_849/nour_84913.mp3","categories":["شروح الحديث"]},{"id":18003,"question":"قال الرسول ﷺ في معنى الحديث: ويل لمن كذب ليضحك القوم ثم ويل له ثم ويل له ما رأي سماحتكم في بعض الناس الذين يجعلون مجالسهم النكت؟","title":"حكم النكت في المجالس","answer":"الجواب: هذا فيه ذكر الكذب، يقول النبي ﷺ: ويل للذي يحدث فيكذب ليضحك به القوم إذا كانت النكتة فيها كذب ما يجوز، وأما إذا كانت نكتة ما فيها كذب ما تسمى كذب ما تدخل في هذا، نعم. الله المستعان.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17028/حكم-النكت-في-المجالس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_849/nour_84914.mp3","categories":["شروح الحديث"]},{"id":18005,"question":"قال الرسول ﷺ في معنى الحديث: ويل لمن كذب ليضحك القوم ثم ويل له ثم ويل له ما رأي سماحتكم في بعض الناس الذين يجعلون مجالسهم النكت؟","title":"حكم النكت في المجالس","answer":"الجواب: هذا فيه ذكر الكذب، يقول النبي ﷺ: ويل للذي يحدث فيكذب ليضحك به القوم إذا كانت النكتة فيها كذب ما يجوز، وأما إذا كانت نكتة ما فيها كذب ما تسمى كذب ما تدخل في هذا، نعم. الله المستعان.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17028/حكم-النكت-في-المجالس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_849/nour_84914.mp3","categories":["شروح الحديث"]},{"id":18013,"question":"تسأل أختنا وتقول: ما المقصود بكلمة (أحصاها) في حديث الرسول الكريم ﷺ عن أسماء الله الحسنى: من أحصاها دخل الجنة؟","title":"شرح حديث: \"إن لله تسعة وتسعين اسمًا...\"","answer":"الجواب: الإحصاء يكون بالحفظ، ويكون بالتدبر والتعقل لمعانيها، والعمل بمقتضى ذلك، ولهذا قال عليه الصلاة والسلام: إن لله تسعة وتسعين اسمًا من أحصاها دخل الجنة، وفي لفظ: من حفظها دخل الجنة، فالمعنى: إحصاؤها بتدبر المعاني، والنظر في المعاني مع حفظها؛ لما في ذلك من الخير العظيم والعلم النافع؛ ولأن ذلك من أسباب صلاح القلب، وكمال خشيته لله، وقيامه بحقه . نعم. المقدم: جزاكم الله خيرًا، سماحة الشيخ قد يتكل الناس على بعض مثل هذه الأحاديث، فيعتقد أن حفظ أسماء الله الحسنى دون عمل، يكفيه لدخول الجنة؟ الشيخ: هذا من الفهم الخطأ، أحاديث الترغيب مقصودها: حث العباد على العمل بما شرعه الرسول ﷺ ودعا إليه، مثل: من أحصاها دخل الجنة في الأسماء الحسنى، مثل: من صام عرفة كفر الله به السنة التي قبله والتي بعده، صوم يوم عاشوراء يكفر الله به السنة التي قبله، وما أشبه ذلك، كله من باب الترغيب والترهيب، من باب الترغيب في طاعة الله  وأن هذا من أسباب المغفرة مع توافر الأسباب الأخرى التي لا تمنع المغفرة. فإذا تعاطى المؤمن أسباب المغفرة، وليس هناك موانع من إصراره على الكبائر أثرت أثرها، وإذا كان هناك موانع صار ذلك من أسباب عدم المغفرة؛ لقوله ﷺ: الصلوات الخمس، والجمعة إلى الجمعة، ورمضان إلى رمضان؛ كفارات لما بينهن إذا اجتنب الكبائر، وفي لفظ: ما لم تغش الكبائر. ولهذا ذهب جمهور أهل العلم -يعني: أكثر أهل العلم- إلى أن هذه الأحاديث التي فيها فضل كذا وفضل كذا، فضل الصلاة وأنها تكفر الذنوب، أو الوضوء، أو صوم عرفة، أو صوم يوم عاشوراء، أو إحصاء أسماء الله الحسنى أو ما أشبه ذلك، كل ذلك مقيد باجتناب الكبائر، بالاستقامة على أداء ما أوجب الله وترك ما حرم الله، وأن هذه الفضائل وهذه الأعمال من أسباب المغفرة، مع الأسباب الأخرى التي شرعها الله ، ومع السلامة من الموانع التي تمنع المغفرة، وذلك هو الإصرار على الكبائر، كما قال : وَالَّذِينَ إِذَا فَعَلُوا فَاحِشَةً أَوْ ظَلَمُوا أَنْفُسَهُمْ ذَكَرُوا اللَّهَ فَاسْتَغْفَرُوا لِذُنُوبِهِمْ وَمَنْ يَغْفِرُ الذُّنُوبَ إِلَّا اللَّهُ وَلَمْ يُصِرُّوا عَلَى مَا فَعَلُوا وَهُمْ يَعْلَمُونَ [آل عمران:135]، فشرط في هذا عدم الإصرار، والإصرار: هو الإقامة على المعصية وعدم التوبة منها، وهو من أسباب عدم المغفرة ولا حول ولا قوة إلا بالله. والخلاصة: أن هذه الفضائل وهذا الوعد الذي وعد الله به من أحصى أسماءه الحسنى بدخول الجنة، ووعد من صام يوم عاشوراء بأن يكفر السنة التي قبله، وهكذا في صوم عرفة، وهكذا غير ذلك، كله مقيد بعدم الإصرار على المعاصي، وهكذا ما جاء في أحاديث التوحيد، وأن من شهد أن لا إله إلا الله صدقًا من قلبه دخل الجنة، كل ذلك مقيد بعدم إقامته على المعاصي، فأما إذا قام على المعاصي فهو تحت مشيئة الله؛ قد يغفر له، وقد يدخل النار بذنوبه التي أصر عليها ولم يتب، حتى إذا طهر ونقي منها، أخرج من النار إلى الجنة. فالواجب على كل مسلم ومسلمة: أن يحذرا الاتكال على أحاديث الترغيب والوعد، وأن يعرضا عن أحاديث الوعيد وآيات الوعيد، بل يجب أن يأخذا بهذا وهذا، يجب أن يحذرا ما حرمه الله من المعاصي وأن تكون على باله الآيات التي فيها الوعيد والأحاديث التي فيها الوعيد لمن تعدى حدود الله وركب محارمه، ومع ذلك يحسن ظنه بربه ويرجوه ويتذكر وعده بالمغفرة والرحمة لمن فعل الأعمال الصالحات، فيجمع بين هذا وهذا بين الرجاء والخوف، فلا يقنط ولا يأمن، وهذا هو طريق أهل العلم والإيمان، كما قال جل وعلا عن أنبيائه: إِنَّهُمْ كَانُوا يُسَارِعُونَ فِي الْخَيْرَاتِ وَيَدْعُونَنَا رَغَبًا وَرَهَبًا [الأنبياء:90]، يعني: رجاءً وخوفاً. وَكَانُوا لَنَا خَاشِعِينَ [الأنبياء:90].. قال سبحانه: أُوْلَئِكَ الَّذِينَ يَدْعُونَ يَبْتَغُونَ إِلَى رَبِّهِمُ الْوَسِيلَةَ أَيُّهُمْ أَقْرَبُ وَيَرْجُونَ رَحْمَتَهُ وَيَخَافُونَ عَذَابَهُ [الإسراء:57]، هكذا أهل الإيمان من أتباع الرسل هم على هذا السبيل، يوحدون الله ويخشونه ويؤدون فرائضه ويدعون محارمه ويرجونه ويخافونه سبحانه وتعالى. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17046/شرح-حديث-ان-لله-تسعة-وتسعين-اسما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_599/59902.mp3","categories":["شروح الحديث"]},{"id":18099,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة يقول: المرسل ( عبد العزيز . س. ع) أخونا له تسعة أسئلة، من أسئلته يسأل ويقول: ما هي ساعات الجمعة التي وردت في حديث الرسول ﷺ فيما معناه: من أتى في الساعة الأولى فكأنه قدم بدنة إلى آخر الحديث؟","title":"شرح حديث: \"من راح إلى الجمعة...\"","answer":"الجواب: هذا الحديث صح عن رسول الله عليه الصلاة والسلام في الصحيحين أنه قال عليه الصلاة والسلام: من راح إلى الجمعة في الساعة الأولى فكأنما قرب بدنة، ومن راح في الساعة الثانية فكأنما قرب بقرة، ومن راح في الساعة الثالثة فكأنما قرب كبشًا أقرن، ومن راح في الرابعة فكأنما قرب دجاجة، ومن راح في الخامسة فكأنما قرب بيضة الحديث. وهو حديث عظيم شريف صحيح وهو يدل على شرعية التبكير إلى الجمعة، وذلك أمر معروف عند أهل العلم ودلت عليه الأحاديث الصحيحة عن رسول الله عليه الصلاة والسلام. أما المبدأ فقيل: يبدأ من بعد صلاة الفجر، وقيل: من طلوع الشمس، وهذا محتمل؛ لأن الرسول ﷺ ما بين المبدأ، قال: (من راح)، (من بكر وابتكر) فلم يبين المبدأ. والأقرب والله أعلم أنه من طلوع الشمس؛ لأن الصفرة تابعة لما قبلها وهي محل الجلوس في المساجد والتعبد والذكر والاستغفار وقراءة القرآن أو الذهاب إلى البيت لحاجة وقضاء الحاجة من تعاطي أول الطعام الذي يستعين به على البقاء في المسجد للجمعة.. إلى غير ذلك. فالأقرب والله أعلم والأحرى أنه يكون بعد ارتفاع الشمس، حتى إذا ذهب للمسجد يكون محل الصلاة والتعبد، هذا هو الأقرب والأظهر والله أعلم، يعني الساعة الأولى من بعد ارتفاع الشمس وحل الصلاة للمسلم في مسجده وبيته، هذا هو الأقرب والأحرى. نعم. المقدم: جزاكم الله خيرًا. هل قسم الليل والنهار سماحة الشيخ في عهد النبي ﷺ أو في عهد صحابته؟ الشيخ: ظاهر الأحاديث أن الليل اثنا عشر والنهار اثنا عشر، يجزأ اثنا عشر ساعة والنهار كذلك. نعم. المقدم: جزاكم الله خيرًا، إذًا التقسيم وارد فكأن الوقت الأول ما يقرب من الواحدة صباحًا بالتوقيت ..... الشيخ: ....... على حسب اختلاف الأوقات. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17134/شرح-حديث-من-راح-الى-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_903/nour_90306.mp3","categories":["صلاة الجمعة","شروح الحديث"]},{"id":18153,"question":"جاء في حديث أن رسول الله ﷺ قال: \"من كفر مسلمًا فقد كفر\" فهل إذا كفر شخص ما مسلمًا يكون هذا الشخص كافرًا مرتدًا؟ أم أن هذا الحديث فقط يحدد فحش تكفير المسلم؟","title":"شرح حديث: \"من قال لأخيه يا كافر ...\"","answer":"الجواب: هذا اللفظ لا أعرف صحته الآن، ولكن معناه صحيح فقد قال ﷺ: من قال لأخيه يا عدو الله أو قال: يا كافر فقد باء بها أحدهما يعني: إذا لم يكن من قيل له ذلك صالحًا لها رجعت إلى من قالها، فلا يجوز للمسلم أن يكفر أخاه، ولا أن يقول: يا عدو الله ولا يا فاجر إلا بدليل، فإذا رمى أخاه بالكفر وليس كذلك رجع إليه كلامه. والمعنى التحذير، ليس معناه أنه كفر أكبر، بل معناه التحذير من هذا الكلام السيئ، وأن صاحبه على خطر عظيم إذا قاله لأخيه، فينبغي حفظ اللسان وأن لا يتكلم إلا عن بصيرة. المقدم: جزاكم الله خيرًا ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/17189/شرح-حديث-من-قال-لاخيه-يا-كافر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_905/nour_90507.mp3","categories":["مسائل متفرقة في العقيدة","شروح الحديث","الفرق والمذاهب"]},{"id":18185,"question":"تقول السائلة من ضمن أسئلتها: المقتول في الجهاد النبي ﷺ عد الشهداء في الصحيح فذكر منهم المقتول في الجهاد والمبطون، والحريق والنفساء يقتلها ولدها، فهل لهؤلاء حق أجر الشهادة المذكورة عن النبي ﷺ: للشهيد سبع خصال، وكيف إن كان أحد هؤلاء من العصاة؟","title":"من الذين يدخلون في زمرة الشهداء؟","answer":"الجواب: الشهيد له ما وعده الله من الأجر، والأمر بيد الله ، والعاصي تحت المشيئة، إن شاء الله عفا عنه، وإن شاء عاقبه على معصيته. فالشهداء لهم أجرهم، يرجى لهم الخير العظيم إذا كانوا مخلصين في جهادهم، وفي أعمالهم فلهم أجرهم، وهكذا من ذكره النبي ﷺ كالمطعون والمبطون، وصاحب ذات الجنب هؤلاء شهداء، وإذا كان لهم معاص فأمرهم إلى الله جل وعلا، لكن لهم فضل الشهادة، وأمر المعاصي تحت مشيئة ربهم جل وعلا، إن شاء غفر لهم، وإن شاء عذبهم. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/17256/من-الذين-يدخلون-في-زمرة-الشهداء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_782/nour_78206.mp3","categories":["شروح الحديث"]},{"id":18223,"question":"هذا سائل للبرنامج يقول سماحة الشيخ: قال رسول الله ﷺ: حبب لي من دنياكم ثلاث: الطيب، والنساء، وجعلت قرة عيني في الصلاة وسؤالي يا سماحة الشيخ عن الطيب: هل هذا الطيب هو المعروف في وقتنا الحاضر دهن العود أو البخور؟","title":"معنى قوله ﷺ: \"حبب إلي من دنياكم الطيب... \"","answer":"الجواب: الحديث ما فيه ثلاث: حبب إلي من دنياكم النساء، والطيب، وجعلت قرة عيني في الصلاة لأن الصلاة ما هي من الدنيا، زيادة ثلاث غلط من بعض الرواة، الصواب: أن الحديث يقول ﷺ: حبب إلي من دنياكم النساء، والطيب، وجعلت قرة عيني في الصلاة والصلاة من الدين لا من الدنيا. والطيب كل ما له شم طيب دهن العود، دهن الورد، العنبر إلى غير ذلك، البخور، الطيب، لا يتقيد بشيء، ما كان له رائحة طيبة يسمى طيب. نعم. المقدم: أحسن الله إليكم، وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17270/معنى-قوله-ﷺ-حبب-الي-من-دنياكم-الطيب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_782/nour_78212.mp3","categories":["شروح الحديث","قضايا المرأة","اللباس والزينة"]},{"id":18254,"question":"هذا السائل (أحمد . أ. أ) يقول: ما معنى حديث: أن أناسًا من أمتي يقادون إلى الجنة بالسلاسل؟","title":"معنى حديث: \"أن أناسًا من أمتي يقادون إلى الجنة بالسلاسل\"","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: هذا الحديث يقول فيه ﷺ: عجبت لقوم يقادون إلى الجنة بالسلاسل معناه: أنهم يؤسرون في الجهاد، ثم يسلمون فيدخلون الجنة، كانوا كفارًا فأسرهم المسلمون، ثم هداهم الله ودخلوا في دين الله في الإسلام وصاروا من أهل الجنة.نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17303/معنى-حديث-ان-اناسا-من-امتي-يقادون-الى-الجنة-بالسلاسل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_783/nour_78310.mp3","categories":["شروح الحديث"]},{"id":18328,"question":"رسالة المستمعة ( لولوة . ج. ل) من القصيم - بريدة عرضنا بعض أسئلتها في حلقة مضت، وفي هذه الحلقة تسأل وتقول: هل هذا معنى حديث: \"من ستر على مسلم ستر الله عليه\"، أي: إذا فعل إنسان شيئًا منكرًا أو فاحشة وسترت عليه، ستر الله عليّ؟ أرجو أن توضحوا لي هذا، جزاكم الله خيرًا.","title":"معنى حديث: (من ستر على مسلم...)","answer":"الجواب: نعم، هذا حديث صحيح رواه مسلم عن أبي هريرة  عن النبي عليه الصلاة والسلام أنه قال: من نفس عن مؤمن كربة من كرب الدنيا نفس الله عنه كربة من كرب يوم القيامة، ومن يسر على معسر يسر الله عليه في الدنيا والآخرة، ومن ستر مسلمًا ستره الله في الدنيا والآخرة. وفي الصحيحين من حديث ابن عمر رضي الله عنهما، عن النبي ﷺ أنه قال: المسلم أخو المسلم لا يظلمه ولا يسلمه، ومن كان في حاجة أخيه كان الله في حاجته، ومن فرج عن مسلم كربة فرج الله عنه بها كربة من كرب يوم القيامة، ومن ستر مسلمًا ستره الله يوم القيامة. هذا هو المشروع إذا رأى الإنسان من أخيه في الله أو أخته في الله عورة -يعني: معصية- فلا يفضحه، ولا ينشرها بين الناس، بل يستر عليه وينصحه، ويوجهه إلى الخير، ويدعوه إلى التوبة إلى الله من ذلك، ولا يفضحه بين الناس، ومن فعل هذا وستر على أخيه ستره الله في الدنيا والآخرة؛ لأن الجزاء من جنس العمل. أما الذين يظهرون المعاصي ولا يستحون، ويظهرونها بين الناس، فهؤلاء فضحوا أنفسهم فليسوا محلًا للستر كالذي يشرب الخمر بين الناس في الأسواق، وفي المحلات والاجتماعات هذا قد فضح نفسه -نسأل الله العافية- وهكذا من يعمل المعاصي الأخرى جهرة ولا يبالي، هذا يرفع بأمره إلى ولاة الأمور إذا كانوا يردعون مثله ويقيمون عليه الحد، يرفع في أمره، وليس محل الستر من أظهر فاحشته وأعلنها -نسأل الله العافية- نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17398/معنى-حديث-من-ستر-على-مسلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_860/nour_86005.mp3","categories":["شروح الحديث"]},{"id":18372,"question":"أولى رسائل هذه الحلقة من محافظة الجزيرة في السودان، رسالة بعث بها أخونا: خضر محمد دفع الله، أخونا يسأل ويقول: أفيدوني عن الحديث الذي جاء في نهايته: إن الله خلق آدم على صورته؟أولًا: ما هي صحة هذا الحديث؟ثانيًا: ما معنى هذا الحديث؟ثالثًا: على من ترجع الهاء التي في آخر كلمة (صورته)؟ نسأل الله لكم الأجر وجزيل الثواب.","title":"ما صحة حديث: «خلق آدم على صورته» ومعناه؟","answer":"الجواب: هذا الحديث صحيح رواه البخاري ومسلم في الصحيحين وفيه: إن الله خلق آدم على صورته، والضمير على الراجح يعود إلى الرب  وقد أنكر ذلك بعض أهل العلم، وخطأهم المحققون من أهل العلم كالإمام أحمد رحمه الله وإسحاق بن راهويه وجماعة آخرين بينوا أن الضمير يعود على الله، وهكذا قال شيخ الإسلام ابن تيمية رحمه الله وابن القيم وغيرهم، قالوا: إنه يعود على الله، والمعنى: أن الله خلق آدم على صورته سميعًا بصيرًا متكلمًا مختارًا، وليس معناه التمثيل والتشبيه؛ لأن الله سبحانه لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ [الشورى:11] وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ [الإخلاص:4] فمعنى على صورته بلا كيف، ولا تمثيل، هذا هو الحق، وهذا هو الصواب. وقد جمع أخونا في الله العلامة الشيخ حمود بن عبد الله التويجري رسالة في هذا وجمع فيها الأحاديث، ونقل فيها كلام أهل العلم وهي رسالة مفيدة مطبوعة. وقد يظن بعض الناس أن هذا يقتضي التمثيل، وليس الأمر كذلك؛ ولهذا ذكر العلامة الإمام ابن خزيمة رحمه الله في كتابه؛ كتاب التوحيد، إنكار عودة الضمير على الله فرارًا من التشبيه، وليس الأمر كذلك؛ ولهذا قال أهل العلم: إنه لا تشبيه في ذلك كالإمام أحمد رحمه الله ابن حنبل، والإمام إسحاق بن راهويه، وآخرين من أهل العلم، وابن قتيبة في مختلف الحديث، والذهبي، وشيخ الإسلام ابن تيمية وغيرهم، فالمقصود: أنه حديث صحيح والضمير يعود فيه على الله . ولهذا في حديث آخر رواه أحمد وغيره: خلق آدم على صورة الرحمن فأوضح الضمير، وبين أنه يعود على الله  فهو على صورة الرحمن من حيث أنه سميع بصير متكلم إذا شاء، إلى غير ذلك. وليس معنى ذلك التمثيل والتكييف فلا؛ لأن الله  ليس له مثل ولا شبيه كما قال : لَيْسَ كَمِثْلِهِ شَيْءٌ [الشورى:11]، قال : فَلا تَضْرِبُوا لِلَّهِ الأَمْثَالَ [النحل:74]، والنبي ﷺ ليس قصده التمثيل، وإنما قصده إخبار بشرف آدم، وأن آدم شرفه الله بأن خلقه على صورته؛ ولهذا نهى عن ضرب الوجه، قال: إن الله خلق آدم على صورته . فلا يجوز لمؤمن ضرب الوجه، لا يجوز ضرب الوجه ولا الوشم في الوجه، بل يجب تجنب ذلك عملاً بالحديث الصحيح الذي فيه النهي عن ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/17439/ما-صحة-حديث-خلق-ادم-على-صورته-ومعناه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_862/nour_86201.mp3","categories":["شروح الحديث","الحكم على الأحاديث"]},{"id":18415,"question":"هذا الأخ السائل من سوريا من دمشق يقول: ما معنى الدعاء: واغسلني من خطاياي بالماء، والثلج، والبرد؟","title":"معنى حديث: \"واغسلني من خطاياي بالماء ...\"","answer":"الجواب: على ظاهره، يطلب من ربه أن يغسله بالماء، والثلج، والبرد، يعني: أن ينقيه من الذنوب نقاء تامًا. نعم.","link":"https://binbaz.org.sa/fatwas/17489/معنى-حديث-واغسلني-من-خطاياي-بالماء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_784/nour_78417.mp3","categories":["شروح الحديث"]},{"id":18417,"question":"هذا السائل من السودان الخرطوم: (ف. ش. م.) يقول: قال رسول الله ﷺ: ستنقسم أمتي إلى ثلاث وسبعين فرقة وكلها في النار ما عدا واحدة أرجو من سماحتكم شرح هذا الحديث؟","title":"شرح حديث: \"ستفترق أمتي إلى ثلاث وسبعين فرقة ...\"","answer":"الجواب: مثلما تقدم: الأمة تفترق على ثلاث وسبعين فرقة كما قاله النبي ﷺ والناجية هي فرقة واحدة: التي سارت على منهج النبي ﷺ ومنهج أصحابه، أما ثنتان وسبعون ففيهم الكافر وفيهم العاصي وفيهم المبتدع على خطر. لكن الناجية السليمة هي التي سارت على نهج النبي ﷺ ونهج أصحابه كما جاء في الحديث: من كان على ما أنا عليه وأصحابي وفي اللفظ الآخر: هي الجماعة يعني: هم الذين اجتمعوا على طريق النبي ﷺ وعلى سيرته عليه الصلاة والسلام. نعم. المقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/17496/شرح-حديث-ستفترق-امتي-الى-ثلاث-وسبعين-فرقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_913/nour_91337.mp3","categories":["شروح الحديث"]},{"id":18435,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات تقول: المرسلة أمة الله من الرياض، أختنا تسأل عن خمس قضايا في قضيتها الأولى تقول:إلى سماحة الشيخ عبد العزيز بن باز السلام عليكم ورحمة الله وبركاته، أما بعد: فإن لدي بعض الأسئلة وهي: أولًا: قرأت حديثًا عن رسول الله ﷺ عن عون بن مالك  أنه قال: أتيت رسول الله ﷺ في غزوة تبوك وهو في قبة أدم فقال: اعدد ستًا بين يدي الساعة: موتي، ثم فتح بيت المقدس، ثم موتان يأخذ فيكم كعقاص الغنم، ثم استفاضة المال حتى يعطى الرجل مائة دينار فيظل ساخطًا، ثم فتنة لا يبقى بيت من العرب إلا دخلته، ثم هدنة تكون بينكم وبين بني الأصفر فيغدرون فيأتونكم تحت ثمانين غاية، تحت كل غاية اثنا عشر ألفًا سؤالي هو: هل ظهور هذه الأحداث قبل ظهور العلامات الكبرى؟هل الفتنة التي في الحديث يقصد بها الفيديو، وما كان على شاكلته الذي ابتلينا به في وقتنا هذا؟ وما هما الموتان الواردان في الحديث؟ ومن هم بنو الأصفر الذين تكون بيننا وبينهم هدنة؟ وما هي الغاية التي وردت في الحديث؟أرجو من سماحة الشيخ أن يتفضل مشكورًا ببيان ما سألت عنه، وتسأل أيضًا وتقول: هل يتوقف عمل الإنسان بظهور أولى العلامات الكبرى؟ وما هي أولاها؟ جزاكم الله خيرًا.","title":"شرح حديث: \"اعدد ستًا بين يدي الساعة ...\"","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه أما بعد: فهذه الأشياء التي جاءت في الحديث المذكور، وهو من حديث عوف بن مالك -بالفاء- عوف بن مالك الأشجعي ، هذه من علامات النبوة، ومن دلائل صدق رسالته عليه الصلاة والسلام. المقدم: عوف بن مالك؟ الشيخ: عوف بن مالك. المقدم: أنا قلت عون. الشيخ: بدل عون عوف بن مالك . وهذه من علامات صدق الرسالة، وأنه رسول الله حقًا عليه الصلاة والسلام، فقد حصل فتح بيت المقدس بعد موته عليه الصلاة والسلام وحصل مرض وهو الموتان الذي أخذ الناس وهو الطاعون الذي عم الناس، حصل به موت عظيم. والفتنة: وقعت فتن كثيرة، ولاسيما الفتنة التي وقعت بين علي  ومعاوية  فإنه عم شرها بسبب مقتل عثمان وانتشر ضررها ودخل بيوت العرب وبيوت المسلمين، فهي فتنة عظيمة حصلت على المسلمين وافترق فيها المسلمون فرقتين، ثم أطفأها الله جل وعلا بعد مقتل علي، وبعد تنازل الحسن بن علي عن الإمرة وتركها لـمعاوية، واجتمع الناس على معاوية، وبايعوه في عام إحدى وأربعين من الهجرة، وصار ذلك العام يسمى عام الجماعة، والحمد لله على كل حال. وأما ما يتعلق بفيضان المال فقد فاض المال كثيرًا، وسوف يفيض في آخر الزمان، والأقرب والله أعلم أنه يفيض في آخر الزمان؛ لأنه جاءت أحاديث أخرى كثيرة تدل على أنه في آخر الزمان يفيض حتى لا يقبله أحد، وهذا يكون في زمن عيسى عليه الصلاة والسلام؛ فإنه إذا جاء زمن عيسى فاض المال بين الناس، ووضعت الجزية ولم تقبل، وصار المسلمون على دين واحد، وصارت العبادة لله وحده، فهناك يفيض المال، وقد يفيض في أوقات قبل ذلك كما في الحديث الصحيح أيضًا أنها لا تقوم الساعة حتى يفيض المال، وحتى يخرج الرجل بصدقته لا يجد من يقبلها، وحتى تعود أرض العرب مروجًا وأنهارًا، كل هذا ثابت عن النبي عليه الصلاة والسلام، وقد يقع في جهات وفي دول دون جهات أخرى ودول أخرى، ولكنه واقع في آخر الزمان كما أخبر به النبي عليه الصلاة والسلام، في زمن عيسى، وقد يقع في أزمان أخرى قبل زمن عيسى عليه الصلاة والسلام. وأما ما يتعلق ببني الأصفر وكونهم يأتوا إلى المسلمين على ثمانين غاية، هذا ما بعد حصل، ولابد أن يقع كما قاله النبي ﷺ، لابد أن يقع في آخر الزمان كما أخبر به النبي ﷺ، وبنو الأصفر هم الروم، يقال لهم: بنو الأصفر، والله المستعان. وأما الفيديو وما الفيديو والتلفاز هذه فتن، ليست هي المرادة في الحديث، لكنها تدخل في عموم الأدلة الأخرى التي فيها ظهور الفتن، وانتشار الشر، هذا من أسبابه: الفيديو والتلفاز والإذاعات، والصحف الماجنة والخليعة، كل هذه من أسباب الشر، ما يذاع في الإذاعة من الباطل، وما ينشر بسبب التلفاز أو بسبب الصحف أو ما أشبه ذلك من أنواع المؤلفات الباطلة، كل هذا من أسباب الفتن، وكل هذا من أسباب الشر الذي يقع بين الناس، والله المستعان. المقدم: الله المستعان. سألت أختنا سماحة الشيخ: هل يتوقف عمل الإنسان بظهور أولى العلامات الكبرى؟ وما هي أولى العلامات الكبرى؟ الشيخ: أول العلامات الكبرى عند أهل العلم خروج المهدي الذي يحكم الناس بالعدل، وهو من أهل بيت النبي ﷺ من أولاد الحسن من أولاد فاطمة ويخرج في آخر الزمان ويبايعه الناس ويحكم الناس بالعدل، ويملأ الأرض عدلًا بعدما ملئت جورًا، وهذا يقع عند نزول المسيح، قرب نزول المسيح بن مريم في آخر الزمان، وعند خروج الدجال. وأول العلامات هو المهدي ثم الدجال، ثم نزول عيسى عليه الصلاة والسلام، ثم خروج يأجوج ومأجوج، هذه كلها متقاربة، في زمن واحد، أولها المهدي ثم يليه الدجال، ثم ينزل المسيح بن مريم فيقتل الدجال، ثم يخرج يأجوج ومأجوج والمسيح موجود في الأرض عليه الصلاة والسلام. والآيات التي إذا خرجت لم تقبل التوبة وختم على الأعمال هي طلوع الشمس من مغربها، إذا طلعت من مغربها الشمس حينئذ لا تقبل التوبة من التائبين، فالكل يبقى على عمله كما قال : يَوْمَ يَأْتِي بَعْضُ آيَاتِ رَبِّكَ لا يَنفَعُ نَفْسًا إِيمَانُهَا لَمْ تَكُنْ آمَنَتْ مِنْ قَبْلُ أَوْ كَسَبَتْ فِي إِيمَانِهَا خَيْرًا [الأنعام:158] هذا هو طلوع الشمس من مغربها كما صحت به الأخبار عن رسول الله عليه الصلاة والسلام. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17516/شرح-حديث-اعدد-ستا-بين-يدي-الساعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_915/nour_91501.mp3","categories":["شروح الحديث"]},{"id":18483,"question":"يقول: هل هذا الحديث صحيح: من قرأ آية الكرسي عقب كل صلاة، ليس بينه وبين الجنة إلا أن يموت، وما معنى هذا الحديث؟","title":"الحكم على حديث فضل قراءة آية الكرسي عقب كل صلاة","answer":"الجواب: جاء في هذا عدة أحاديث مجموعها بأنه حسن، يستحب بعد الصلاة بعد التسبيح يقرأ آية الكرسي: اللَّهُ لا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ[البقرة:255] ويرجى له بذلك دخول الجنة إذا استقام، إذا استقام على دينه، وحافظ على دينه؛ يرجى له دخول الجنة؛ لقول النبي ﷺ: الصلوات الخمس والجمعة إلى الجمعة ورمضان إلى رمضان كفارات لما بينهن، ما لم تغش الكبائر . وفي اللفظ الآخر: إذا اجتنب الكبائر فإذا حافظ على ما أوجب الله عليه، وترك ما حرم الله عليه، وقرأ آية الكرسي؛ كل هذا من أسباب دخول الجنة، إذا قرأها بعد كل صلاة. نعم.","link":"https://binbaz.org.sa/fatwas/17571/الحكم-على-حديث-فضل-قراءة-اية-الكرسي-عقب-كل-صلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_785/nour_78518.mp3","categories":["شروح الحديث","الحكم على الأحاديث"]},{"id":18570,"question":"هذا سائل من فرنسا يقول -يا سماحة الشيخ-: ما معنى حديث: أعمار أمتي ما بين الستين والسبعين؟ هل هذا حديث صحيح ومن قول الرسول ﷺ؟","title":"الحكم على حديث: \"أعمار أمتي...\" ومعناه","answer":"الجواب: على ظاهره، والذي أعلمه أنه لا بأس به، سنده لا بأس به، والمعنى: أن غالب الناس من الستين إلى السبعين موتهم، هذا غالبهم، وقد يزيد إلى التسعين إلى المائة إلى أكثر، لكن الغالب في الناس أنهم بين الستين إلى السبعين، هذا هو الغالب، نعم. المقدم: أحسن الله إليكم، وبارك فيكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17685/الحكم-على-حديث-اعمار-امتي-ومعناه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_918/nour_91805.mp3","categories":["شروح الحديث","الحكم على الأحاديث"]},{"id":18575,"question":"فيما معنى الحديث سماحة الشيخ: لا يموتن أحدكم إلا وهو يحسن الظن بالله تعالى يقول:ما معنى حسن الظن بالله؟ وجهونا في ضوء ذلك.","title":"معنى حسن الظن بالله","answer":"الجواب: هذا حديث صحيح، رواه مسلم في الصحيح: لا يموتن أحدكم إلا وهو يحسن ظنه بالله والله يقول: أنا عند ظن عبدي بي والمعنى: أنه يحسن ظنه بالله: أن ربه جواد، وأنه كريم، وأنه غفور رحيم سبحانه، وأنه يتوب على عباده إذا تابوا إليه، وأن فضله عظيم، يحسن ظنه بربه، مع الجد في العمل الصالح، مع التوبة. لا يحسن الظن بالرب، ويقيم على المعاصي، لا، يحسن ظنه بربه مع العمل الصالح، مع التوبة، مع الجد في الخير، أما إحسان الظن بالله مع الإقدام على المعاصي، والإصرار عليها؛ فهذا غرور لا يجوز، لكن يحسن ظنه بربه أنه يقبل توبته، وأنه يعفو عنه، ويجتهد في أسباب العفو من الصدقة، والرحمة للفقراء، وكثرة الاستغفار، والتوبة، والندم، والإقلاع، وكثرة الأعمال الصالحات، مع حسن الظن بالله، يحسن ظنه أن الله يقبلها، وأنه لا يردها ، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/17692/معنى-حسن-الظن-بالله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_786/nour_78619.mp3","categories":["شروح الحديث","الرقائق"]},{"id":18580,"question":"في الحديث سماحة الشيخ يقول: هل الدعاء يرد القدر؟ وكيف ذلك؟","title":"كيفية رد الدعاء للقدر","answer":"الجواب: نعم، الدعاء من أسباب رد القدر المعلق، والقدر يكون معلقًا، ويكون مبتوتًا، فإذا كان قدرًا معلقًا، قد قدر الله -جل وعلا- أن يهبه ولدًا إذا دعا ربه، فدعا ربه، واستجاب دعوته، هذا معلق بالدعاء، أو قدر الله له مالًا إذا دعا ربه في طلب ذلك المال، فإذا دعا ربه يسر الله له المال المعلق على الدعاء، أو طلب زوجة، طلب أن الله يزوجه فلانة، والله قد قدر له ذلك بهذا الطلب، قد علق القدر بهذا الطلب، أن فلان قدر الله في سابق علمه أنه يسأل ربه أن الله يزوجه فلانة بنت فلان، فإذا ألهمه الله الدعاء، ووفقه للدعاء؛ حصل المقدور المعلق. أما الأقدار المبتوتة التي ما هي معلقة على الناس هذه ما تتعلق بالدعاء، الموت المعلق في يوم معلوم دون دعاء إذا جاء موته المحدود مات دعا أو لم يدع، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17703/كيفية-رد-الدعاء-للقدر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_786/nour_78623.mp3","categories":["شروح الحديث","القضاء والقدر"]},{"id":18622,"question":"السائلة أم أحمد لها هذا السؤال تقول: ما معنى في الحديث: مائلات مميلات رؤوسهن كأسنمة البخت المائلة؟","title":"معنى قوله ﷺ: \"مائلات مميلات ...\"","answer":"الجواب: هذا فيه النهي مثل هؤلاء الذين أخبر عنهم النبي -عليه الصلاة والسلام- في الحديث الصحيح، المائلة: التي تميل إلى الفاحشة والمميلة: تميل غيرها إلى الفواحش رؤوسهن كأسنمة البخت المائلة يعني: يعظمن الرؤوس يضخمنها بأشياء يجعلونها عليها. فالواجب على الرجل أن يختار المرأة الطيبة التي سمعتها حسنة، يسأل عنها حتى تتزوج المرأة الصالحة، مثل ما قال ﷺ: تنكح المرأة لأربع: لمالها، ولجمالها، ولحسبها، ولدينها، فاظفر بذات الدين تربت يداك فالمؤمن يلتمس المرأة الصالحة، ويسأل عنها؛ حتى لا تكون امرأة تتهم بالشر والفساد، بل يسأل عنها أهل خبرة، وأهل معرفة بها، فإذا وصفت له بأنها امرأة صالحة تزوجها فاظفر بذات الدين تربت يداك نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17735/معنى-قوله-ﷺ-ماىلات-مميلات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_787/nour_78708.mp3","categories":["شروح الحديث","قضايا المرأة","اللباس والزينة"]},{"id":18757,"question":"يستفسر عن صحة هذا الحديث ما معناه: «من نام على جنبه الأيمن، وقرأ قُلْ هُوَ اللَّهُ أَحَدٌ -سورة الإخلاص- مائة مرة جاء يوم القيامة وقيل له: ادخل الجنة عن يمينك» ما صحة هذا الحديث؟","title":"الحكم على حديث: (من نام على جنبه الأيمن وقرأ...)","answer":"الجواب: ليس له أصل فيما نعلم، أقول: ليس له أصل فيما نعلم، هذا من الأخبار الموضوعة عن النبي ﷺ، نعم.","link":"https://binbaz.org.sa/fatwas/17889/الحكم-على-حديث-من-نام-على-جنبه-الايمن-وقرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_790/nour_79015.mp3","categories":["شروح الحديث","الحكم على الأحاديث","الأدعية والأذكار"]},{"id":18799,"question":"أبو محمد من الرياض بعث بجملة أو مجموعة من الأسئلة يقول: سماحة الشيخ، ما معنى \"النهي عن بيعتين في بيعة\"؟","title":"معنى \"النهي عن بيعتين في بيعة\"","answer":"الجواب: بيعتان في بيعة: أن يبيعه سلعة بشرط بيعة أخرى، أن يقول: أبيعك داري هذه بشرط أن تبيعني دارك أو أرضك أو بشرط أن تقرضني كذا وكذا؛ لقوله ﷺ: لا يحل سلف وبيع ولأنه نهى عن بيعتين في بيعة. ومن ذلك أن يبيعه السلعة إلى أجل ثم يشتريها بأقل، وهذه بيعتان في بيعة وهي تسمى العينة (ربا) لا تجوز، يبيعه السلعة مثلًا بمائة، ثم يشتريها بثمانين نقدًا أو ستين نقدًا منه فهذه حيلة على الربا كأنه أعطاه ستين نقدًا حتى يرد عليه مائة مؤجلة، فهذه بيعتان في بيعة، وهي من أصول الربا، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17942/معنى-النهي-عن-بيعتين-في-بيعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_791/nour_79120.mp3","categories":["شروح الحديث","البيوع"]},{"id":18808,"question":"أختنا تسأل وتقول: سمعت حديثًا شريفًا معناه: أنه يأتي زمن تتحدث فيه عذبة السوط إلى صاحبها، وتحدثه عذبة سوطه وتخبره بما أحدث أهله من بعده، ما معنى عذبة السوط؟ وأرجو تفصيل الحديث وشرحه.","title":"ما معنى: «لا تقوم الساعة حتى يكلم الرجل فخذه»؟","answer":"الجواب: نعم، جاء هذا الحديث بإسناد جيد رواه الترمذي وغيره: أنه لا تقوم الساعة حتى يكلم الرجل فخذه بما صنعه أهله، وحتى تكلم الرجل عذبة سوطه بما صنعه أهله. وعذبة السوط: طرف السوط. والمعنى: أنه يكون في آخر الزمان شيء يجعل في السوط أو في العصا أو نحو ذلك، يترتب عليه حفظ كلام الأهل؛ وذلك كالمسجلات التي وقعت الآن هي من هذا الباب، فقد تجعل في السوط قد تجعل في العصا، وقد تجعل في شبه ساعته في البيت صغيرة، وقد يجعلها الإنسان في عضده؛ فيحفظ كل شيء. المقدم: أو في الأقلام. الشيخ: كل هذا واقع، فإذا جعل المسجل في محل في البيت عند أهله، وحول أهله؛ سجل عليهم كل ما يقولون. وأما الفخذ فقد أخبر به النبي ﷺ وسيقع؛ لم نسمع به الآن، ولكنه في آخر الزمان يقع ما أخبر به النبي -عليه الصلاة والسلام- نعم. المقدم: إذًا هذا من المعجزات النبوية لسيدنا محمد ﷺ؟ الشيخ: نعم؛ لأنه أخبر بها قبل أن تقع فوقعت كما أخبر، وهذا مما يدل على أن الله أوحى إليه من السماء وأخبره؛ لأنه لا يعلم الغيب، وإنما يخبر بما خبره الله به، كما قال الله سبحانه: وَالنَّجْمِ إِذَا هَوَى ۝ مَا ضَلَّ صَاحِبُكُمْ وَمَا غَوَى ۝ وَمَا يَنْطِقُ عَنِ الْهَوَى ۝ إِنْ هُوَ إِلَّا وَحْيٌ يُوحَى [النجم:1-4] فقوله: مَا ضَلَّ صَاحِبُكُمْ يعني: محمد -عليه الصلاة والسلام-، وَمَا غَوَى: أي: ليس بضال وهو الجاهل، وليس بغاو وهو الذي يعمل بخلاف العلم، بل هو رشيد مؤمن بصير عالم بما أوحى الله إليه -عليه الصلاة والسلام-، وَمَا يَنْطِقُ عَنِ الْهَوَى: ليس ممن ينطق عن هواه وشهوته بغير علم ولا هدى، بل إنما ينطق عن علم وعن وحي من الله  أوحاه الله إليه -عليه الصلاة والسلام- نعم. المقدم: سماحة الشيخ، أعتقد أنني قرأت الحديث خطأً، وهو حديث له أهميته، حبذا لو تكرمتم بإعادته؟ الشيخ: يقول النبي ﷺ: لا تقوم الساعة حتى يكلم الرجل فخذه بما صنعه أهله، وحتى تكلم الرجل عذبة سوطه بما صنعه أهله السوط: يطلق على العصا، ويطلق على ما يفتل من شيء من سيور أو غيرها، يقال له: سوط؛ لأنه يساط به الأشياء، وتساق به الأشياء، نعم. المقدم: جزاكم الله خيرًا، ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/17943/ما-معنى-لا-تقوم-الساعة-حتى-يكلم-الرجل-فخذه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_877/nour_87702.mp3","categories":["شروح الحديث"]},{"id":18832,"question":"يقول هذا السائل من السودان سماحة الشيخ: في الحديث: إذا مات ابن آدم انقطع عمله إلا من ثلاث: صدقة جارية، أو علم ينتفع به، أو ولد صالح يدعو له البعض من الناس يذهب لقبر أحد الأشخاص كأن يكون شيخًا، ويطلب منه كذا وكذا، هل يجوز ذلك؟ وما حكم من يفعل ذلك في الشرع؟ وكيف ندعو للميت من منطلق هذا الحديث ابن صالح يدعو له كيف ندعو بعد الممات؟جزاكم الله خيرًا.","title":"حكم دعاء الموتى من دون الله","answer":"الجواب: تقول: اللهم اغفر لأبي، اللهم اغفر له، اللهم ارحمه، اللهم نجه من النار ، ونحو ذلك، هذا الدعاء له.  أما دعاء الميت، والتوجه إلى الميت تقول له: يا فلان انصرني، أو أنا في حسبك، أو أغثني هذا الشرك الأكبر، أو اشفع لي، أو أنا في جوارك، أو ما أشبه ذلك هذا الشرك الأكبر، هذا فعل المشركين مع اللات والعزى، ومع أصنامهم، وهذا فعل المشركين مع الشيخ عبد القادر الجيلاني، ومع البدوي، ومع الحسين، ما يجوز هذا. لا يقل: يا سيدي فلان انصرني، أو أنا في حسبك، أو أنا في جوارك، أو اشفع لي، هذا ما يقال للميت يقال للحي، يقول للحي: اشفع لي، ادع الله لي؛ ما يخالف الحي، تقول: ادع الله ليغفر لي، ادع الله أن يرحمني، هذا لا بأس. أما الميت تقول له: يا فلان، يا شيخ عبد القادر، أو يا حسين، أو يا ست زينب، أو يا فلان -وهو ميت- ادع الله لي، هذا ما يجوز؛ لأنه غير قادر، لا يستطيع شيء، أو اشفع لي؛ هذا توسل بميت لا يقدر، كالذي يقول للصنم: انصرني، أو اشفع لي، جماد لا قدرة له على شيء، فسؤال الأموات، والاستغاثة بالأموات، والتشفع بالأموات؛ هذا هو عمل المشركين وهذا هو المنكر، ولا يجوز، بل هو من الشرك الأكبر، نسأل الله العافية، نعم. ومثله الغائبون يا ملائكة الله، يا جبريل، يا ميكائيل، أو يا جن الفلانيين، يا جن الظهران، يا جن الحسا، يا جن أمريكا، يا جن مصر، أو يا جني الفلاني، كل هذا من الشرك الأكبر، وقد ذم الله بعض المشركين في هذا، قال عنهم: وَأَنَّهُ كَانَ رِجَالٌ مِنَ الإِنسِ يَعُوذُونَ بِرِجَالٍ مِنَ الْجِنِّ فَزَادُوهُمْ رَهَقًا[الجن:6] يعني: زادوهم شرًا وبلاء، نسأل الله العافية، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17982/حكم-دعاء-الموتى-من-دون-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_792/nour_79202.mp3","categories":["حكم الصلاة وأهميتها","شروح الحديث","نواقض الإسلام"]},{"id":18862,"question":"رسالة وصلت من المستمع عبد الرحيم أحمد حميدان عضو البعثة التعليمية المصرية باليمن الشمالي، أخونا يقول: سمعت من أحد العلماء الأفاضل هذا الحديث، ونسأل عن صحته، وإذا كان صحيحًا فمن هو والد النبي ﷺ المقصود بالحديث؟ ولماذا ينطبق عليه هذا الكلام؟ نص الحديث: «دخل يهودي على النبي ﷺ وسأله: يا محمد! أين أبي؟ -وكان أبو اليهودي ميتًا- فقال له الرسول ﷺ: إن أباك في النار فلما تغير وجه اليهودي قال له النبي ﷺ: إن أبي وأباك في النار؟","title":"شرح حديث: «إن أبي وأباك في النار»","answer":"الجواب: هذا الحديث صحيح ثابت في صحيح مسلم عن النبي ﷺ: «أنه جاءه رجل فسأله -وليس في الحديث أنه يهودي، وإنما سأله إنسان، والظاهر أنه من المسلمين الذين آباؤهم ماتوا في الجاهلية، أو بعد الدعوة، ولكنه لم يسلم- فسأله قال: أين أبي؟ فقال: إن أباك في النار فلما رأى ما في وجهه من التغير، قال: إن أبي وأباك في النار . يخبره أن الأمر ليس خاصًا بأبيك، بل كل من مات على الجاهلية فهو من أهل النار؛ لأنه مات على الكفر بالله إلا من ثبت أنه من أهل الفترة، ولم تبلغه رسالة ولا دعوة، فهذا أمره إلى الله، لكن حكمه في الدنيا حكم الكفار -حكم الجاهلية-: لا يغسل، ولا يصلى عليه، حكم الجاهلية، لكن إذا كان في نفس الأمر لم تبلغه دعوة، ولا رسالة فهذا له حكم أهل الفترات: يمتحنون يوم القيامة على الصحيح، فمن أطاع دخل الجنة ومن عصى دخل النار. فالحاصل: أنه حديث صحيح، لكن ليس فيه أن السائل يهودي فيما أعلم إنما هو من نفس المسلمين الذين مات آباؤهم في الجاهلية، أو بعد ظهور الإسلام، لكنه لم يسلم، فقال له النبي ﷺ: «إن أباك في النار» -ثم بين له بقوله:- إن أبي وأباك في النار لأن والد النبي ﷺ مات في الجاهلية، والنبي ﷺ حمل لم يولد بعد ذلك، وقيل: إنه قد ولد، ولكنه صغير جدًا، والمشهور أنه مات والنبي ﷺ حمل، ثم ماتت أمه وهو صغير -عليه الصلاة والسلام- ابن خمس سنين، أو ست سنين. فالحاصل: أن أباه مات في الجاهلية، وهكذا أمه ماتت في الجاهلية؛ ولهذا قال في حق أبيه: إن أبي وأباك في النار. والسبب في ذلك -والله أعلم- أنه قد بلغته الدعوة لدين إبراهيم، فلهذا حكم عليه بالنار، وأما الأم فقد ثبت عنه ﷺ أنه استأذن ربه ليستغفر لها، فلم يأذن له في استغفاره لها، فهذا يدل على أن من مات في الجاهلية لا يستغفر له، وله حكم أهل الجاهلية، لا يستغفر له، وهو متوعدون بالنار إلا من ثبت أنه من أهل الفترة، من كان الله يعلم أنه من أهل الفترة لم تبلغه رسالة، ولا دعوة، ولا علم، فهذا على الصحيح يمتحن يوم القيامة، فإن أجاب إلى ما أمر به دخل الجنة وإن عصى دخل النار، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18003/شرح-حديث-ان-ابي-واباك-في-النار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_922/nour_92208.mp3","categories":["شروح الحديث","الحكم على الأحاديث"]},{"id":18896,"question":"بعد هذا رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين، يقول عبد الرحمن السيد أبو طالب، الأخ عبد الرحمن يسأل ويقول: ورد عن الرسول ﷺ حديث معناه من لم تنهه صلاته عن الفحشاء والمنكر؛ فلا صلاة له اشرحوا لنا هذا الحديث، جزاكم الله خيرًا، وإذا عرفت إنسانًا مقيمًا للصلاة، ولكنه يرتكب الفحشاء، فكيف أوفق بين ما رأيت وبين هذا الحديث؟جزاكم الله خيرًا.","title":"شرح أثر: (من لم تنهه صلاته عن الفحشاء والمنكر...)","answer":"الجواب: هذا الحديث معروف عن ابن مسعود من كلامه  موقوف من كلام عبد الله بن مسعود ، ولا أعلم صحته مرفوعًا إلى النبي ﷺ، وهذا هو من باب الوعيد، فالواجب على المؤمن أن يحذر الفحشاء والمنكر، وأن يستقيم على طاعة الله ورسوله، وأن تكون صلاته تنهاه عن هذا الشيء، كما قال -جل وعلا-: إِنَّ الصَّلاةَ تَنْهَى عَنِ الْفَحْشَاءِ وَالْمُنْكَرِ [العنكبوت:45]. فالواجب على المسلم أن يعالج وضعه، وأن يجتهد في التوبة إلى الله من معاصيه، فإذا كان يصلي ومع هذا مقيم على المعاصي؛ فهذا معناه أنه لم يؤدِ الصلاة كما ينبغي، ولم يقمها كما ينبغي، ولو أقامها كما ينبغي؛ لنهته عن الفحشاء والمنكر.  فالواجب عليه أن يحاسب نفسه، وأن يتقي الله، وأن يصلي كما أمر الله، وأن يحذر الفحشاء والمنكر، ويتوب إلى الله من ذلك، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/18040/شرح-اثر-من-لم-تنهه-صلاته-عن-الفحشاء-والمنكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_736/nour_73622.mp3","categories":["شروح الحديث","الحكم على الأحاديث"]},{"id":18971,"question":"هذا السائل يقول -سماحة الشيخ-: ورد حديث يخبر فيه الرسول ﷺ بأنه يدخل من أمة محمد ﷺ الجنة سبعون ألف من غير حساب ولا عذاب، ولما سأل الصحابة  فيما بينهم من هم وما هي صفاتهم خرج عليهم الرسول ﷺ فأخبرهم بما جرى بينهم، وأخبر ﷺ بأنهم الذين لا يسترقون، ولا يكتوون، ولا يتطيرون. نرجو من سماحتكم يقول السائل: أن تفسروا لنا هذه الصفات لعلنا نتمسك بها؟","title":"صفات السبعين ألفًا الذين يدخلون الجنة بغير حساب","answer":"الجواب: أخبر النبي ﷺ أنه يدخل من أمته سبعون ألفًا بغير حساب ولا عذاب، وفي رواية: مع كل ألف سبعين ألفًا سئل -عليه الصلاة والسلام- عن صفاتهم، قال: هم الذي لا يسترقون، ولا يكتوون، ولا يتطيرون، وعلى ربهم يتوكلون يعني: هم الذين استقاموا على دين الله من أهل التقوى والإيمان، وعبدوا الله وحده، وأدوا فرائضه، وتركوا محارمه، واجتهدوا في أنواع الخير، حتى تركوا بعض ما يستحب تركه كالاسترقاء، والكي من كمال إيمانهم. لا يسترقون يعني: لا يطلبوا من يرقيهم، ولا يكتوون لأن الكي تركه أفضل إلا عند الحاجة، والاسترقاء تركه أفضل إلا عند الحاجة، هذا من كمال إيمانهم. وإذا احتاج الإنسان إلى الاسترقاء لا بأس أن يسترقي كما أمر النبي ﷺ عائشة أن تسترقي، وأمر أم أولاد جعفر بن أبي طالب أن تسترقي لأولاده لما أصابتهم العين، فدل على أنه لا بأس بالاسترقاء عند الحاجة، ولكن تركه أفضل إذا تيسر دواء آخر، واستغني عنه، وهكذا الكي إذا تيسر دواء يقوم مقامه فهو أفضل، وإن دعت الحاجة إلى الكي فلا بأس، فقد كوى الصحابة كما كوى خباب بن الأرت وغيره، قد كوى النبي ﷺ بعض أصحابه للحاجة، فهذا من الكمال، ولا يخرجه عن السبعين إذا استرقى أو كذا لكن هذه من أعمالهم الحسنة، ترك الكي إذا استغني عنه، ترك الاسترقاء إذا استغني عنه، وإلا فالسبعون ألف هم أهل الاستقامة، هم أهل الخير والاستقامة في طاعة الله، وترك معصيته المحافظون على الخير، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/18110/صفات-السبعين-الفا-الذين-يدخلون-الجنة-بغير-حساب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_792/nour_79206.mp3","categories":["شروح الحديث"]},{"id":19010,"question":"يقول أخونا هناك حديث عن رسول الله ﷺ يقول: صلوا كما رأيتموني أصلي أي: أنه أمر من الرسول ﷺ بأن نصلي مثله، علمًا بأن الرسول ﷺ كان ينوع بالفعل، هل نحن ملزمون بتنويع الفعل؟","title":"معنى حديث: \"صلوا كما رأيتموني أصلي\"","answer":"الجواب: هذا الحديث صحيح رواه البخاري في الصحيح من حديث مالك بن الحويرث أن النبي ﷺ قال: صلوا كما رأيتموني أصلي فعلينا أن نصلي كما صلى، فيما حافظ عليه واستقام عليه، نصلي كما صلى وننوع كما نوع عليه الصلاة والسلام، أما ما يفعله تارة ويدعه تارة، هذا يدل على عدم الوجوب وأنه مستحب وليس بواجب، أما ما حافظ عليه واستمر عليه كالركوع والسجود والقراءة.. ونحو ذلك فهذا كله فرض، لابد من قراءة الفاتحة، ولابد من الركوع والسجود، ولابد من تسبيح في الركوع والسجود، ولابد من التشهد التحيات إلى غير هذا مما هو معروف. والسنة للمؤمن أن يصلي كما صلى، فيطول القراءة في الفجر وفي الظهر، ويخففها في العصر وفي المغرب، ويطيلها بعض الأحيان في المغرب، ويتوسط في العشاء فيقرأ من أوساط المفصل، ويقرأ سورة السجدة والإنسان في فجر الجمعة، ويقرأ في صلاة الجمعة بسبح والغاشية، وبالجمعة والمنافقين، كما فعل النبي ﷺ فهذه سنة؛ لأنه فعل هذا وفعل هذا عليه الصلاة والسلام، فالمؤمن يتأسى به في أفعاله وأقواله عليه الصلاة والسلام. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18177/معنى-حديث-صلوا-كما-رايتموني-اصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_926/nour_92604.mp3","categories":["شروح الحديث"]},{"id":19013,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين من الدمام وهو فيصل بو بشيت، أخونا فيصل يقول: في مسند أبي حنيفة للحارثي حديث رواه عبد الله بن عباس عن الرسول ﷺ: ادرءوا الحدود بالشبهات أرجو أن تتفضلوا بشرح هذا الحديث؟ جزاكم الله خيرًا.","title":"معنى حديث: \"ادرءوا الحدود بالشبهات\"","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فقد جاء في هذا الباب عدة أحاديث في أسانيدها مقال، لكن يشد بعضها بعضًا، منها الحديث الذي ذكر السائل: ادرءوا الحدود بالشبهات في اللفظ الآخر: ادفعوا الحدود ما استطعتم والمعنى: أن الواجب على ولاة الأمور من القضاة والعلماء والأمراء أن يدرءوا الحدود بالشبهة التي توجب الشك في ثبوت الحد، فإذا لم يثبت عند الحاكم الحد ثبوتًا واضحًا لا شبهة فيه فإنه لا يقيمه ويكتفي بما يردع عن الجريمة من أنواع التعزير، ولا يقام الحد الواجب كالرجم في حق الزاني المحصن وكالجلد مائة جلدة وتغريب عام في حق الزاني البكر، وقطع اليد في حق السرقة لا يقام إلا بعد ثبوت ذلك ثبوتًا لا شبهة فيه ولا شك فيه، بشاهدين عدلين لا شبهة فيهما فيما يتعلق بالسرقة، وبأربعة شهود عدول فيما يتعلق بحد الزنا، وهكذا بقية الحدود الواجب على ولاة الأمر أن يعتنوا بذلك وأن يدرءوا الحد بالشبهة التي توجب الريبة والشك في ثبوته. ومن ذلك إذا ادعى من يطلب إقامة الحد عليه الإكراه، وامرأة ادعت أنها أكرهت على الزنا، وأنها ليست مختارة بل أكرهها الزاني وظلمها فإن هذه شبهة يدرأ بها الحد، وهكذا إذا ادعى شارب المسكر ما يوجب الشبهة في إقامة الحد عليه.. وما أشبه ذلك، القاضي ينظر ويتأمل، فإذا زالت الشبهة أقام الحد، وإذا قويت الشبهة صار لها وجه درأ الحد بها. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18182/معنى-حديث-ادرءوا-الحدود-بالشبهات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_927/nour_92701.mp3","categories":["شروح الحديث"]},{"id":19065,"question":"سماحة الشيخ هذا سائل يقول: ما معنى \"كل قرض جر نفعًا فهو ربا\"؟","title":"معنى قول: (كل قرض جر نفعًا فهو ربا)","answer":"الجواب: كل قرض يجر عليك نفعًا إذا أقرضت زيد ألف ريال وأعطاك كسوة، أو أهدى إليك فاكهة، أو ما أشبه ذلك، هذا من الربا، أو أسكنك في البيت بدون أجرة، أو أعطاك السيارة تستعملها بدون أجرة، هذا جر ربا هذا من الربا؛ لأن ما أعطاك إلا من أجل القرض. نعم. المقدم: أحسن الله إليكم، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/18272/معنى-قول-كل-قرض-جر-نفعا-فهو-ربا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_883/nour_88329.mp3","categories":["الربا والصرف","زكاة النقدين","قضايا المرأة","شروح الحديث"]},{"id":19196,"question":"نعود في هذه الحلقة سماحة الشيخ إلى رسالة وصلت إلى البرنامج من العراق بغداد باعث الرسالة يقول: أخوكم في الله (ر. س. س) له بعض الأسئلة، في أحدها يقول: قرأت في كتاب التوحيد هذا الحديث عن أبي هريرة  أن رسول الله ﷺ قال: لا عدوى، ولا طيرة، ولا هامة، ولا صفر أخرجاه. ماذا يقصد ﷺ بقوله: لا عدوى، والعلم الحديث قد أثبت أن كثيرًا من الأمراض تنتقل بالعدوى، وضحوا لي هذا الأمر؟ جزاكم الله خيرًا.","title":"معنى حديث: (لا عدوى ولا طيرة ..)","answer":"الجواب: الحديث المذكور صحيح خرجه البخاري ومسلم في الصحيحين، زاد مسلم: ولا نوء، ولا غول، زاد في الحديث أيضًا: ويعجبني الفأل، قيل: يا رسول الله ما الفأل؟ قال: الكلمة الطيبة. فالعدوى التي نفاها الرسول ﷺ هي ما يعتقده أهل الجاهلية من الكفرة أن الأمور تعدي بطبعها من دون قضاء الله وقدره سبحانه، وأن انتقال الجرب أو الجذام من شخص إلى شخص، أو من دابة إلى دابة؛ أن هذا طبعي لا دخل لقدر الله في ذلك، ولا لفعله في ذلك ؛ وهذا باطل، فلا انتقال من عين إلى عين في الجرب وغيره إلا بإذن الله ..... وقدره السابق سبحانه وحكمته ؛ ولهذا لما قال بعض البادية: يا رسول الله.. لما سمع لا عدوى قال: «يا رسول الله! الإبل الكثيرة يكون فيها البعير الأجرب فتجرب كلها قال ﷺ: فمن أعدى الأول يعني: من الذي أنزل الجرب بالأول؟ الله هو الذي أنزله لحكمة بالغة، فالذي أنزله بالأول هو الذي أنزله في البقية؛ ولهذا قال ﷺ: لا يورد ممرض على مصح يعني: لا يورد صاحب إبل مراض إبله على صاحب إبل صحاح؛ لأن هذا وسيلة لانتقال المرض. وقال عليه الصلاة والسلام: فر من المجذوم فرارك من الأسد لأن الجذام ينتقل، هذا معناه إقرار الانتقال لكن ليس على العدوى التي تقولها الجاهلية، بل ينتقل بإذن الله عند المخالطة؛ قد ينتقل عند المخالطة، إذا خالط الأجرب الصحيح؛ والمجذوم الصحيح قد ينتقل، وهكذا أمراض أخرى عند الاختلاط قد ينتقل، وقد لا ينتقل؛ وهو ليس بلازم، لكن إذا أبعد الصحيحة عن المريض يكون هذا هو الأولى كما أمر النبي ﷺ قال: لا يورد هذا نهي من النبي ﷺ لا يورد ممرض على مصح، وقال آمرًا: فر من المجذوم فرارك من الأسد. فالمعنى: أبعدوا المريض عن الصحيح إذا كان يخشى منه العدوى لا يخلط هذا مع هذا، فهذا معناه تجنب الأسباب التي تسبب انتقال المرض، ولكن ينبغي أن يعلم أنه لا عدوى، وأن انتقاله إذا انتقل ليس لأنه يعدي بطبعه، وأنه ليس بإذن الله، ولا بمشيئة الله لا، بل ينتقل لكن بمشيئة الله وبإذنه وقدره ، لا أحد يستطيع أن ينقل شيئًا إلى شيء إلا بإذن الله وقدره، لا حيوان ولا إنسان ولا غير ذلك، كل شيء بقضاء وقدر يقول النبي ﷺ: كل شيء بقدر حتى العجز والكيس، ويقول الله في كتابه العظيم: مَا أَصَابَ مِنْ مُصِيبَةٍ فِي الأَرْضِ وَلا فِي أَنْفُسِكُمْ إِلَّا فِي كِتَابٍ مِنْ قَبْلِ أَنْ نَبْرَأَهَا[الحديد:22]، ويقول جل وعلا: إِنَّا كُلَّ شَيْءٍ خَلَقْنَاهُ بِقَدَرٍ[القمر:49]. فالمقصود أن الله سبحانه قدر الأشياء كلها: الصحة، والمرض، والسفر، والإقامة، والولد ذكرًا كان أو أنثى، والحياة والموت .. وغير ذلك كلها بأقدار ماضية من الله  يقول النبي ﷺ: إن الله قدر مقادير الخلائق قبل أن يخلق السموات والأرض بخمسين ألف سنة، وعرشه على الماء فالأمور كلها مقدرة، فكون هذا البعير يمرض، أو هذا الفرس، أو هذا الإنسان .. بقدر، وكون هذا الصحيح يخالط هذا المريض فيصاب بمرضه .. هذا بقدر، وليس بلازم، قد يقع قد تكون الصحيحة مع الجرب ولا تجرب، وقد يكون الإنسان مع المجذوم، ولا يصاب بالجذام، وقد جاء عنه ﷺ أنه أخذ بيد مجذوم، وهو يأكل فقال: كل باسم الله، ثقة بالله ولم يجذم عليه الصلاة والسلام، فالإنسان إذا خالطهم لبيان أن الله جل وعلا هو المقدر، وليعلم الناس أن هذا ليس بمشيئة العدوى، ولكن بمشيئة الله، إذا فعل ذلك حتى يعلم الناس أن هذه الأمور بقضاء الله فهو سبحانه جواد كريم الذي يصونه ويحفظه حتى يعلم الناس الحقيقة التي بيَّنها رسوله ﷺ. والخلاصة: أنه لا عدوى على طريقة الجاهلية يعني: لا عدوى بالطبع ولكن قد تقع العدوى وهي الانتقال قد تقع بمشيئة الله وإذنه بسبب الاختلاط بين المرضى والأصحاء في بعض الأحيان. نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/18408/معنى-حديث-لا-عدوى-ولا-طيرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_799/nour_79902.mp3","categories":["شروح الحديث","التشاؤم والتطير"]},{"id":19297,"question":"المستمعة من السودان رقية أحمد محمد تسأل وتقول: ما معنى هذا الحديث؟ قال ﷺ: حجبت النار بالشهوات، وحجبت الجنة بالمكاره، ما هي الشهوات وما هي المكاره؟","title":"شرح حديث: (حجبت النار بالشهوات وحجبت الجنة بالمكاره)","answer":"الجواب: ثبت هذا عن النبي ﷺ أنه قال: حجبت النار بالشهوات، وحفت الجنة بالمكاره وهكذا جاءت حفت وحجبت، معناها: أن الشهوات باب إلى النار، من ترك الشهوات المحرمة: كالخمر والزنا والعقوق وأشباه ذلك سلم من النار فهو حجاب، ومن أتى المكاره؛ (حجبت الجنة بالمكاره) بحيث جعلت حجاب للجنة، فإذا جاهد نفسه المؤمن وألزمها بالحق وأكرهها على طاعة الله ورسوله؛ دخل الجنة صار هذا حجاب، فإذا هتكه وجاهد نفسه حتى يطيع الله ورسوله دخل الجنة، وإذا اقترف الشهوات دخل النار، فهو حجاب وفي الشهوات يعني المحرمة. أما المباحة فالله أباح له الطيبات يأكل ويشرب ما أباح الله له، يلبس ما أباح الله له هذا لا بأس به، لكن المراد بالشهوات هنا المحرمة: كالزنا والسرقة وظلم الناس وأشباه ذلك مما حرم الله من الشهوات المحرمة، فهذا إذا اقترفها دخل النار، وإذا اجتنبها وحذرها صارت حجابًا عن النار، (وحفت الجنة بالمكاره) النفس قد تكره إلزامها بالحق: كأداء الصلوات الخمس في الجماعة، والصوم صوم رمضان، ولا سيما في الصيف، والحج مع الاستطاعة، بر الوالدين، صلة الرحم والبعد عن جلساء السوء، قد النفس تكره هذا، لكن إذا جاهدها المؤمن حتى تؤدي الحق دخل الجنة. نعم. المقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18492/شرح-حديث-حجبت-النار-بالشهوات-وحجبت-الجنة-بالمكاره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_739/nour_73907.mp3","categories":["شروح الحديث"]},{"id":19337,"question":"رسالة وصلت من أحد الإخوة المستمعين من مكة المكرمة يقول: طالب علم (ح. ف. ح) أخونا يسأل ويقول: قال ﷺ: كل مولود يولد على الفطرة فأبواه يهودانه أو ينصرانه ... الحديث، ما معنى هذا الحديث؟ وهل هذا الحديث على سبيل المجاز، أم على سبيل الحقيقة؟ أفيدونا بارك الله فيكم.","title":"ما صحة حديث: «كل مولود يولد على الفطرة» ومعناه؟","answer":"الجواب: الحديث صحيح رواه البخاري ومسلم في الصحيحين، وهو على سبيل الحقيقة لا على سبيل المجاز، بل مولود على الفطرة، وفي اللفظ الآخر: على هذه الملة، ملة الإسلام هكذا جاء في الحديث الصحيح، يقول ﷺ: ما من مولود يولد إلا على الفطرة، وفي اللفظ الآخر عند البخاري وغيره: على هذه الملة، وفي اللفظ الآخر: على ملة الإسلام، هذا معناه واضح وهو أنه يولد مسلمًا على فطرة الله الذي فطر عليها الناس. وفي حديث رواه مسلم في الصحيح يقول الله : إني خلقت عبادي حنفاء فاجتالتهم الشياطين وأمرتهم أن يشركوا بي ما لم أنزل به سلطانًا، فبين سبحانه أنه خلق عباده حنفاء موحدين ولكن طرأ الشرك عليهم بعد ذلك بسبب المضللين من آبائهم وأمهاتهم وغيرهم، ولهذا قال: فأبواه يهودانه أو ينصرانه أو يمجسانه، يعني: يدعونه إلى ذلك ويربونه على الشرك فيخرج عن الفطرة بسبب تربية والديه على اليهودية أو النصرانية أو المجوسية أو غيرها من أنواع الكفر، وقد يربيه غير والديه أيضًا ممن يتولى تربيته من أعمامه وأقاربه وأخواله عند فقد والديه، وقد ينشأ في بيئة مشركة فيتربى على ما يربونه عليه، وهذا معنى قوله ﷺ عن الله  أنه قال: إني خلقت عبادي حنفاء فاجتالتهم الشياطين عن دينهم وأمرتهم أن يشركوا بي ما لم أنزل به سلطانًا، فالشياطين تشمل شياطين الإنس والجن، وكذلك ما يفعله الإنس هو من تزيين الشياطين، .. شياطين الجن لهم حتى يجروهم إلى هذا الباطل بوساوسهم وتزيينهم. فشياطين الإنس تدعو إلى الشرك وهكذا شياطين الجن، والأصل في المولود أنه ولد على الفطرة فلو استمر عليها وسلم من هؤلاء وعاش بين أهل الخير عاش على الفطرة والهدى والتوحيد، لكن إذا ابتلي بمربين ضالين أخرجوه عن فطرته بتربيتهم وتزيينهم الباطل إلا من عصم الله ورحم بأن قيض له من يربيه التربية الإسلامية ويدعوه إليها.  المقدم: بارك الله فيكم. قد يخطر ببال أحد المستمعين سماحة الشيخ ما حدث لنبي الله نوح مع ابنه، فماذا هو توجيهكم لو تكرمتم؟ الشيخ: كفر الولد أو شركه بالله أو معصيته لا ينقذه من ذلك أبوه ولو كان أبوه أصلح الناس كـنوح عليه الصلاة والسلام فإنه رسول ومع هذا لم يملك هداية ابنه بل دعاه إلى أن يركب معه في السفينة فأبى ولم يستجب فصار من الهالكين ومع الغارقين على كفره وضلاله. فالمقصود أن نوحًا عليه الصلاة والسلام لم يستطع هداية ابنه، كما أن إبراهيم عليه الصلاة والسلام لم يستطع هداية أبيه، وكما أن محمدًا ﷺ لم يستطع هداية عميه؛ أبي لهب وأبي طالب، فالأمر بيد الله  هو الذي يقول سبحانه: لَيْسَ عَلَيْكَ هُدَاهُمْ وَلَكِنَّ اللَّهَ يَهْدِي مَنْ يَشَاءُ [البقرة:272].","link":"https://binbaz.org.sa/fatwas/18548/ما-صحة-حديث-كل-مولود-يولد-على-الفطرة-ومعناه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_898/nour_89803.mp3","categories":["شروح الحديث"]},{"id":19403,"question":"من العراق الأنبار هذه رسالة بعث بها الأخ أبو بكر الهيتي -فيما يبدو-، أخونا يقول في رسالته يوجد حديث عند الإمام البخاري مروي عن رسول الله ﷺ: أن الميت يعذب ببكاء أهله عليه وحديث آخر عن سيدتنا عائشة أم المؤمنين رضي الله عنها ترفض هذا القول وتقول: «حسبكم القرآن وَلا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَى [الأنعام:164] » فما جوابكم أثابكم الله عن هذه المسألة، هل الميت يعذب ببكاء أهله عليه؟ أم أنه لَيْسَ لِلإِنسَانِ إِلَّا مَا سَعَى[النجم:39] وَلا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَى [الأنعام:164] ؟","title":"الجمع بين: {وَلَا تَزِرُ وَازِرَةٌ} و«إن الميت يعذب ببكاء أهله»","answer":"الجواب: ليس هناك تعارض بين الأحاديث ولا بين آية التي ذكرتها عائشة رضي الله عنها وَلا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَى [الأنعام:164]، فقد ثبت عن رسول الله ﷺ من حديث ابن عمر ومن حديث المغيرة ومن غيرهما في الصحيحين ليس في البخاري وحده بل في الصحيحين البخاري ومسلم جميعًا وفي غيرهما أن النبي ﷺ قال: إن الميت يعذب بما يناح عليه وفي الرواية الأخرى: ببكاء أهله عليه والمراد بالبكاء: يعني: النياحة رفع الصوت. أما البكاء الذي هو دمع العين فهذا لا يضر، إنما الذي يضر النياحة رفع الصوت، والرسول ﷺ قصد بهذا منع الناس من النياحة على موتاهم، وأن يتحملوا الصبر ويكفوا عن النوح ولا بأس بدمع العين، كما قال عليه الصلاة والسلام لما مات ابنه إبراهيم العين تدمع والقلب ليحزن ولا نقول إلا ما يرضي الرب وإنا بفراقك يا إبراهيم لمحزونون. فالميت يعذب بالنياحة عليه من أهله وكيفية العذاب الله أعلم بكيفية العذاب الذي يحصل له بهذه النياحة وهذا مستثنى من قوله تعالى: وَلا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَى [الأنعام:164] فإن القرآن والسنة لا يتعارضان بل يصدق أحدهما الآخر ويفسر أحدهما الآخر، فالآيات عامة والحديث خاص والسنة تخص القرآن وتبين معناه، فيكون تعذيب الميت بنياحة أهله عليه مستثنى من الآية الكريمة ولا تعارض بينها وبين الأحاديث، وأما قول عائشة رضي الله عنها فهذا من اجتهادها وحرصها على الخير وفهمها، وما قاله النبي ﷺ مقدم على قولها وعلى رأيها.","link":"https://binbaz.org.sa/fatwas/18629/الجمع-بين-ولا-تزر-وازرة-وان-الميت-يعذب-ببكاء-اهله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_935/nour_93510.mp3","categories":["التفسير","شروح الحديث"]},{"id":19418,"question":"فهذه رسالة وصلت إلى البرنامج من جمهورية مصر العربية وباعثها أخ لنا من هناك يقول المرسل (سالم . أ. ن) من شبرا، يسأل فيقول: هناك بعض الأحاديث النبوية المطهرة تنهى عن الأكل والشرب واقفًا، وهناك أيضًا بعض الأحاديث تسمح للإنسان بالأكل والشرب واقفًا، فهل معنى ذلك أننا لا نأكل ولا نشرب واقفين أم نأكل ونشرب جالسين وأي الأحاديث أجدر بالاتباع؟","title":"الجمع بين أحاديث النهي عن الأكل والشرب قائمًا والمبيحة لذلك","answer":"الجواب: كل الأحاديث الواردة فيها صحيحة جاء عنه ﷺ النهي عن الشرب قائمًا والأكل مثل ذلك، وجاء عنه ﷺ أنه شرب قائمًا، فالأمر في هذا واسع وكلها صحيحة والحمد لله، فالنهي عن ذلك للكراهة، فمن يحتاج للأكل واقفًا أو الشرب واقفًا فلا حرج، فقد ثبت عنه ﷺ «أنه شرب قائمًا وقاعدًا» فإذا احتاج الإنسان إلى ذلك فلا حرج أن يأكل قائمًا ويشرب قائمًا، وإن جلس فهو أفضل وأحسن، وثبت عنه ﷺ «أنه شرب من زمزم واقفًا عليه الصلاة والسلام» وثبت عنه من حديث علي أنه ﷺ «شرب قائمًا وقاعدًا» فالأمر في هذا واسع. فالشرب قاعدًا والأكل قاعدًا أفضل وأهنأ وإن شرب قائمًا، فلا حرج أو أكل قائمًا فلا حرج والحمد لله. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18641/الجمع-بين-احاديث-النهي-عن-الاكل-والشرب-قاىما-والمبيحة-لذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_936/nour_93610.mp3","categories":["الأطعمة والأشربة","شروح الحديث"]},{"id":19507,"question":"من أسئلة هذا السائل يقول: حفظكم الله ما معنى قول الرسول ﷺ: من تحلم بحلم وهو كاذب كلف أن يعقد بين شعيرتين وليس بفاعل وما صحة هذا الحديث؟","title":"الحكم على حديث: (من تحلم بحلم...) ومعناه","answer":"الجواب: الحديث صحيح، وهذا من أنواع تعذيبه، من أنواع التعذيب له على كذبه، والشعيرتين ما يمكن العقد بينهما، كل واحدة يابسة وحدها، فهذا من أنواع تعذيبه على كذبه في حلمه. نعم. المقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/18760/الحكم-على-حديث-من-تحلم-بحلم-ومعناه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_946/nour_94610.mp3","categories":["شروح الحديث","الحكم على الأحاديث"]},{"id":19530,"question":"ما صحة هذا الحديث يقول السائل يا سماحة الشيخ الذي ما معناه: إذا لم تخطئوا أو تذنبوا ليأتين الله بقوم يخطئون فيتوبون؟ وما تفسير ذلك؟ وماذا يستفاد من هذا الحديث؟","title":"الحكم على حديث: (لو لم تذنبوا ...) ومعناه","answer":"الجواب: ثبت عن النبي ﷺ أنه قال: لو لم تذنبوا لذهب الله بكم، وجاء بقوم يذنبون فيستغفرون فيغفر لهم هذا من رحمته وجوده أنه جل وعلا قدر على عباده وجود الخطايا، ثم يتوب عليهم سبحانه إذا تابوا إليه. فلا ينبغي للعبد أن يقنط معناه: لا تقنط ولا تيئس بل بادر بالتوبة كما قال تعالى: قُلْ يَا عِبَادِيَ الَّذِينَ أَسْرَفُوا عَلَى أَنْفُسِهِمْ لا تَقْنَطُوا مِنْ رَحْمَةِ اللَّهِ إِنَّ اللَّهَ يَغْفِرُ الذُّنُوبَ جَمِيعًا [الزمر:53] يعني: للتائبين، فهو قدر الذنوب وقدر المغفرة . فلا ينبغي للعبد أن ييئس، بل ينبغي له البدار بالتوبة والاستغفار وحسن الظن بالله، ولو فعل ما فعل من الذنوب، لكن عليه أن يجتهد في المحافظة والحذر، والله يتوب على من تاب جل وعلا. المقدم: أحسن الله إليكم، وبارك فيكم، سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/18778/الحكم-على-حديث-لو-لم-تذنبوا-ومعناه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_939/nour_93940.mp3","categories":["شروح الحديث","الحكم على الأحاديث"]},{"id":19562,"question":"هذا السائل شحاتة من الرياض، أرسل بمجموعة من الأسئلة يقول: حفظكم الله في سؤالي أسأل وأقول: أول ما يسأل عنه العبد يوم القيامة عن الصلاة؛ فإن صلحت صلح عمله، ما المقصود بصلاح الصلاة؟","title":"معنى حديث: (فإن صلحت صلح سائر عمله...)","answer":"الجواب: هذا جاء في الحديث عنه ﷺ أنه قال: أول ما يحاسب العبد من عمله صلاته؛ فإن صلحت فقد أفلح وأنجح، وإن فسدت فقد خاب وخسر يعني: إن صحت صلاته واستقامت، وقبلها الله منه؛ فذلك من أسباب قبول بقية أعماله، وإن أضاع الصلاة، ولم تستقم الصلاة؛ فهو من أسباب ضياع أعماله، فالصلاة كالميزان لبقية الأعمال. فينبغي للمؤمن أن يحرص على إتقانها، وإكمالها، وحفظها؛ حتى لا يتطرق إليها نقص؛ لأن هذا من أسباب توفيق الله له في جميع أعماله بعد ذلك، من حافظ عليها حفظ دينه، ومن ضيعها فهو لما سواها أضيع؛ ولهذا يقول جل وعلا: حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلاةِ الْوُسْطَى[البقرة:238] ويقول ﷺ: من حافظ عليها كانت له نورًا وبرهانًا ونجاة يوم القيامة، ومن لم يحافظ عليها لم يكن له نور، ولا برهان، ولا نجاة، وحشر يوم القيامة مع فرعون، وهامان، وقارون، وأبي بن خلف نسأل الله العافية، فالمحافظة عليها، والعناية بها؛ من أسباب توفيق الله لصلاح أعماله كلها. نعم. المقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/18812/معنى-حديث-فان-صلحت-صلح-ساىر-عمله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_947/nour_94711.mp3","categories":["شروح الحديث"]},{"id":19631,"question":"سماحة الشيخ! تقول السائلة أم العنود المستمعة للبرنامج ما حكم فرق الشعر على الجنب؟ وما معنى قول الرسول ﷺ: مائلات مميلات؟","title":"معنى حديث: (مائلات مميلات) وحكم فرق المرأة شعرها على الجنب","answer":"الجواب: معنى: مائلات عن الحق، عن العفة، مميلات لغيرهن عن العفة، ما هو بالفرقة، مائلات عن الرشد، وعن العفة؛ إلى الفساد والزنا، أما الفرقة فأمرها سهل لكن الأفضل أن تكون متوسطة حتى لا يتشبه الإنسان بأعداء الله، تكون الفرقة متوسطة مما يلي الأنف وسط هذا هو الأفضل. وأما حديث: مائلات مميلات ما هو بالفرقة، مائلات عن العفة، وعن الخير؛ إلى الزنا والفواحش، نعم. المقدم: حفظكم الله يا سماحة الشيخ!","link":"https://binbaz.org.sa/fatwas/18902/معنى-حديث-ماىلات-مميلات-وحكم-فرق-المراة-شعرها-على-الجنب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_948/nour_94833.mp3","categories":["شروح الحديث","قضايا المرأة","اللباس والزينة"]},{"id":19637,"question":"أبو سلمان من اليمن صعدة يقول: في حديث الرسول ﷺ ناصحًا للرجل: قل آمنت بالله ثم استقم الإيمان معروف يقول، فكيف تكون الاستقامة؟ وما الحد الأدنى لها؟ وهل هذا حديث؟","title":"شرح حديث: (قل آمنت بالله ثم استقم)","answer":"الجواب: نعم ثبت عن النبي ﷺ أنه سأله سائل قال: يا رسول الله! قل لي في الإسلام قولًا لا أسأل عنه أحدًا غيرك، قال: قل: آمنت بالله ثم استقم معنى آمنت بالله: يعني: وحدت الله وآمنت أنه ربي وإلهي الحق، ثم يستقيم على طاعة الله وتوحيد الله بأداء فرائض الله وترك محارم الله، كما قال تعالى: إِنَّ الَّذِينَ قَالُوا رَبُّنَا اللَّهُ ثُمَّ اسْتَقَامُوا تَتَنَزَّلُ عَلَيْهِمُ الْمَلائِكَةُ أَلَّا تَخَافُوا وَلا تَحْزَنُوا وَأَبْشِرُوا بِالْجَنَّةِ الَّتِي كُنْتُمْ تُوعَدُونَ [فصلت:30].  فالإنسان يؤمن بالله يعني: يوحد الله ويخصه بالعبادة، ويشهد للرسول ﷺ بالرسالة، ويؤمن به، ثم ينقاد لطاعة الله ويستقيم عليها، على أداء فرائض الله وترك محارم الله، هذه هي الاستقامة. نعم. المقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/18908/شرح-حديث-قل-امنت-بالله-ثم-استقم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_949/nour_94924.mp3","categories":["شروح الحديث"]},{"id":19688,"question":"سماحة الشيخ يقول هذا السائل حفظكم الله: ما المراد بقوله ﷺ: اللهم باعد بيني وبين خطاياي كما باعدت بين المشرق والمغرب هل المراد باعد بيني وبينها فلا أقترفها أم المراد الذنوب؟","title":"ما معنى: «اللهم باعد بيني وبين خطاياي»؟","answer":"الجواب: يتضمن التوبة منها يعني: وفقني للتوبة منها النصوح التي تبعدها عني كما باعدت بين المشرق .. اللهم نقني من خطاياي كما ينقى الثوب الأبيض من الدنس المراد طلب العافية منها والبعد منها والسلامة منها. نعم. المقدم: أحسن الله إليكم وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/18981/ما-معنى-اللهم-باعد-بيني-وبين-خطاياي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_950/nour_95042.mp3","categories":["الأدعية والأذكار","شروح الحديث","مسائل متفرقة في الصلاة"]}]
